import { SanctionEntry, EntityType } from '../types';

export const OFFICIAL_UN_XML_URL = "https://scsanctions.un.org/resources/xml/en/consolidated.xml";
export const OFAC_SDN_URL = "https://ofac.treasury.gov/specially-designated-nationals-list-data-formats-data-schemas";
export const OPENSANCTIONS_URL = "https://www.opensanctions.org/datasets/default/";

/**
 * Parses the UN Consolidated List XML string into SanctionEntry objects.
 */
export const parseUNSanctionsXML = (xmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlString, "text/xml");
  const entries: SanctionEntry[] = [];

  const individuals = xmlDoc.getElementsByTagName("INDIVIDUAL");
  for (let i = 0; i < individuals.length; i++) {
    entries.push(parseIndividual(individuals[i]));
  }

  const entities = xmlDoc.getElementsByTagName("ENTITY");
  for (let i = 0; i < entities.length; i++) {
    entries.push(parseEntity(entities[i]));
  }

  return entries;
};

/**
 * Parses OpenSanctions JSON (Follow-the-Money format)
 */
export const parseOpenSanctionsJSON = (jsonString: string): SanctionEntry[] => {
  try {
    const data = JSON.parse(jsonString);
    const items = Array.isArray(data) ? data : (data.results || []);

    return items.map((item: any, idx: number) => {
      const props = item.properties || {};
      return {
        dataId: item.id || `OPEN-${idx}`,
        source: 'OpenSanctions',
        firstName: props.firstName?.[0] || props.name?.[0] || 'Unknown',
        lastName: props.lastName?.[0] || '',
        unListType: item.schema || 'Sanction',
        referenceNumber: props.idNumber?.[0] || item.id || `REF-${idx}`,
        listedOn: props.createdAt?.[0]?.split('T')[0] || new Date().toISOString().split('T')[0],
        comments: props.notes?.[0] || 'Imported via OpenSanctions JSON',
        nationality: props.nationality?.[0] || 'Unspecified',
        dateOfBirth: props.birthDate?.[0],
        aliases: props.alias || [],
        type: item.schema === 'Organization' || item.schema === 'Company' ? EntityType.CORPORATE : EntityType.INDIVIDUAL
      };
    });
  } catch (e) {
    console.error("OpenSanctions Parse Error:", e);
    return [];
  }
};

/**
 * Basic CSV Parser for OFAC or other simple CSV formats
 */
export const parseCSVToSanctions = (csvString: string, source: string): SanctionEntry[] => {
  const lines = csvString.split('\n');
  const entries: SanctionEntry[] = [];

  const startIdx = lines[0].toLowerCase().includes('name') ? 1 : 0;

  for (let i = startIdx; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const parts = line.split(',').map(p => p.replace(/^"|"$/g, '').trim());
    if (parts.length < 2) continue;

    entries.push({
      dataId: `${source}-${i}-${Math.random().toString(36).substr(2, 5)}`,
      source: source,
      firstName: parts[0] || 'Unknown',
      lastName: parts[1] || '',
      unListType: 'Consolidated',
      referenceNumber: parts[2] || `REF-${i}`,
      listedOn: new Date().toISOString().split('T')[0],
      comments: `Imported from ${source} CSV`,
      nationality: parts[4] || 'Unknown',
      aliases: parts[3] ? [parts[3]] : [],
      type: parts[5]?.toLowerCase().includes('entity') || parts[5]?.toLowerCase().includes('corp') ? EntityType.CORPORATE : EntityType.INDIVIDUAL
    });
  }
  return entries;
};

const getNodeVal = (parent: Element, tagName: string): string => {
  const node = parent.getElementsByTagName(tagName)[0];
  return node ? node.textContent?.trim() || '' : '';
};

const parseIndividual = (node: Element): SanctionEntry => {
  const dataId = getNodeVal(node, "DATAID");
  const firstName = getNodeVal(node, "FIRST_NAME");
  const secondName = getNodeVal(node, "SECOND_NAME");
  const thirdName = getNodeVal(node, "THIRD_NAME");
  const unListType = getNodeVal(node, "UN_LIST_TYPE");
  const referenceNumber = getNodeVal(node, "REFERENCE_NUMBER");
  const listedOn = getNodeVal(node, "LISTED_ON");
  const comments = getNodeVal(node, "COMMENTS1");

  const nationalityNode = node.getElementsByTagName("NATIONALITY")[0];
  const nationality = nationalityNode ? getNodeVal(nationalityNode, "VALUE") : '';

  const dobNode = node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0];
  const dob = dobNode ? getNodeVal(dobNode, "DATE") : '';

  const aliases: string[] = [];
  const aliasNodes = node.getElementsByTagName("INDIVIDUAL_ALIAS");
  for (let j = 0; j < aliasNodes.length; j++) {
    const aliasName = getNodeVal(aliasNodes[j], "ALIAS_NAME");
    if (aliasName) aliases.push(aliasName);
  }

  return {
    dataId: `UN-${dataId}`,
    source: 'UN Consolidated',
    firstName,
    secondName,
    thirdName,
    lastName: '', // UN format uses positional parts instead of explicit lastName
    unListType,
    referenceNumber,
    listedOn,
    comments,
    nationality,
    dateOfBirth: dob,
    aliases,
    type: EntityType.INDIVIDUAL
  };
};

const parseEntity = (node: Element): SanctionEntry => {
  const dataId = getNodeVal(node, "DATAID");
  const firstName = getNodeVal(node, "FIRST_NAME");
  const unListType = getNodeVal(node, "UN_LIST_TYPE");
  const referenceNumber = getNodeVal(node, "REFERENCE_NUMBER");
  const listedOn = getNodeVal(node, "LISTED_ON");
  const comments = getNodeVal(node, "COMMENTS1");

  const aliases: string[] = [];
  const aliasNodes = node.getElementsByTagName("ENTITY_ALIAS");
  for (let j = 0; j < aliasNodes.length; j++) {
    const aliasName = getNodeVal(aliasNodes[j], "ALIAS_NAME");
    if (aliasName) aliases.push(aliasName);
  }

  return {
    dataId: `UN-${dataId}`,
    source: 'UN Consolidated',
    firstName: firstName,
    lastName: '',
    unListType,
    referenceNumber,
    listedOn,
    comments,
    nationality: '',
    aliases,
    type: EntityType.CORPORATE
  };
};

export const fetchFromUrl = async (url: string): Promise<SanctionEntry[]> => {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);
    const text = await response.text();
    return parseUNSanctionsXML(text);
  } catch (error) {
    throw error;
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
