              <div className="flex-1">
                 {label.includes('Shareholder') ? (
                   <InputField label="Share %" type="number" value={item.percentage} onChange={(v: any) => updateItem(idx, 'percentage', parseFloat(v))} />
                 ) : (
                   <InputField label="Date of Birth" type="date" value={item.dob} onChange={(v: string) => updateItem(idx, 'dob', v)} />
                 )}
              </div>
              <button type="button" onClick={() => removeItem(idx)} className="p-4 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all">
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

