export default ClientManager;

import React, { useState, useEffect } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus } from '../types';
import { Save, Cloud, Terminal, Check, Copy, AlertTriangle, ShieldCheck, History, Users, Lock, UserCircle, ShieldAlert, Plus, Power, Key, X, Mail, UserPlus, CheckCircle2, Trash2, UserMinus, AlertCircle, RefreshCw, Link2, Share2, Shield, ToggleLeft, ToggleRight } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  onSwitchUser?: (role: UserRole, id: string) => void;
  currentUserId?: string;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, onSwitchUser, currentUserId, currentUser }) => {
  const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
  const [activeTab, setActiveTab] = useState<'config' | 'rbac' | 'logs' | 'users'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  useEffect(() => { setLocalSettings(settings); }, [settings]);

  const generateSetupLink = () => {
    const baseUrl = window.location.href.split('?')[0];
    const params = new URLSearchParams();
    if (settings.supabaseUrl) params.set('supaUrl', settings.supabaseUrl);
    if (settings.supabaseKey) params.set('supaKey', settings.supabaseKey);
    return `${baseUrl}?${params.toString()}`;
  };

  const copySetupLink = () => {
    navigator.clipboard.writeText(generateSetupLink());
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2000);
  };

  const saveUsersToStorage = async (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    if (!settings.supabaseUrl || !settings.supabaseKey) return;
    setIsSyncing(true);
    try {
      if (isDelete) {
        await deleteCloudUser(user.email);
      } else {
        await upsertCloudUser(user);
      }
    } catch (e: any) {
      console.error("Cloud Engine Error:", e.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const toggleUserStatus = async (email: string) => {
    const updated = systemUsers.map(u => {
      if (u.email === email) {
        const newUser = { ...u, status: u.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE };
        handleCloudSync(newUser);
        return newUser;
      }
      return u;
    });
    saveUsersToStorage(updated);
  };

  const resetUserPassword = async (email: string) => {
    if (!window.confirm(`Issue new credentials for ${email}?`)) return;
    const updated = systemUsers.map(u => {
      if (u.email === email) {
        const newUser = { 
          ...u, 
          password: DEFAULT_TEMP_PASSWORD, 
          must_change_password: true,
          password_expiry: new Date(Date.now() + 80 * 86400000).toISOString()
        };
        handleCloudSync(newUser);
        return newUser;
      }
      return u;
    });
    saveUsersToStorage(updated);
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;

    const emailToDelete = pendingDeleteUser.email;
    const updated = systemUsers.filter(u => u.email !== emailToDelete);

    // Optimistic UI update
    saveUsersToStorage(updated);

    // Sync with Cloud
    await handleCloudSync(pendingDeleteUser, true);
    setPendingDeleteUser(null);
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const normalizedEmail = newUserEmail.trim().toLowerCase();

    if (systemUsers.some(u => u.email === normalizedEmail) || normalizedEmail === 'aqandeel@gmail.com') {
      alert("This identity is already registered in the system.");
      return;
    }

    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: normalizedEmail,
      password: DEFAULT_TEMP_PASSWORD,
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };

    await handleCloudSync(newUser);
    const newList = [...systemUsers, newUser];
    saveUsersToStorage(newList);
    setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false); setIsNewUserAdmin(false);
  };

  const sqlScript = `
-- SanctionGuard IDENTITY Schema v10.1
CREATE TABLE IF NOT EXISTS profiles (
    id TEXT PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    full_name TEXT NOT NULL,
    role_id TEXT NOT NULL,
    is_system_admin BOOLEAN DEFAULT FALSE,
    status TEXT DEFAULT 'Active',
    must_change_password BOOLEAN DEFAULT TRUE,
    password_expiry TIMESTAMP WITH TIME ZONE,
    password_hash_mock TEXT,
    last_login TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);
ALTER TABLE profiles DISABLE ROW LEVEL SECURITY;
`.trim();

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 gap-4">
        <div className="flex items-center gap-4">
          <div className="bg-amber-500 p-4 rounded-2xl text-white shadow-xl shadow-amber-100">
            <Shield size={28}/>
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight">System Governance</h2>
            <p className="text-[10px] text-amber-600 font-black uppercase tracking-[0.2em] mt-1">Technical Control Plane</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
            <button onClick={() => setActiveTab('users')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'users' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Identities</button>
            <button onClick={() => setActiveTab('config')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'config' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Cloud Engine</button>
            <button onClick={() => setActiveTab('logs')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'logs' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Audit Logs</button>
        </div>
      </div>

      {activeTab === 'users' && (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
                <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                   <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] flex items-center gap-3">
                      Identity Registry {isSyncing && <RefreshCw size={16} className="animate-spin text-indigo-500" />}
                   </h3>
                   <button onClick={() => setIsUserModalOpen(true)} className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
                     <Plus size={16} /> Provision User
                   </button>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                      <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                        <tr>
                          <th className="px-10 py-5">Identity</th>
                          <th className="px-10 py-5">Role</th>
                          <th className="px-10 py-5 text-right">Controls</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        <tr className="bg-amber-50/10 italic border-l-4 border-amber-500">
                          <td className="px-10 py-5">
                            <div className="font-black text-slate-900 text-sm">aqandeel@gmail.com</div>
                            <div className="text-[10px] text-amber-600 font-bold uppercase">System Authority</div>
                          </td>
                          <td className="px-10 py-5"><span className="px-3 py-1 bg-slate-900 text-white text-[9px] font-black rounded-lg uppercase">Root Admin</span></td>
                          <td className="px-10 py-5 text-right text-[10px] text-slate-300 font-black tracking-widest uppercase italic">Node Master</td>
                        </tr>
                        {systemUsers.map(user => (
                          <tr key={user.email} className="hover:bg-slate-50/50 group transition-all">
                            <td className="px-10 py-5">
                              <div className="font-bold text-slate-900 text-sm">{user.full_name}</div>
                              <div className="text-xs text-slate-400 font-medium">{user.email}</div>
                              {user.is_system_admin && <span className="text-[8px] font-black text-amber-600 uppercase tracking-widest">Sys Admin</span>}
                            </td>
                            <td className="px-10 py-5">
                              <span className={`px-3 py-1 text-[9px] font-black rounded-lg border uppercase ${user.role === UserRole.ADMIN ? 'bg-indigo-50 text-indigo-700 border-indigo-100' : 'bg-slate-50 text-slate-600 border-slate-100'}`}>
                                {user.role}
                              </span>
                            </td>
                            <td className="px-10 py-5 text-right">
                               <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all">
                                  <button onClick={() => resetUserPassword(user.email)} title="Reset Password" className="p-2 text-slate-400 hover:text-indigo-600 transition-colors"><Key size={16}/></button>
                                  <button onClick={() => toggleUserStatus(user.email)} title={user.status === AccountStatus.ACTIVE ? "Disable Account" : "Enable Account"} className={`p-2 ${user.status === AccountStatus.ACTIVE ? 'text-amber-500 hover:text-amber-600' : 'text-green-500 hover:text-green-600'} transition-colors`}><Power size={16}/></button>
                                  <button onClick={() => setPendingDeleteUser(user)} title="Delete Identity" className="p-2 text-red-400 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                               </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                </div>
            </div>

            <div className="bg-gradient-to-br from-slate-800 to-slate-950 rounded-[2.5rem] p-10 text-white shadow-2xl shadow-indigo-200 relative overflow-hidden">
                <div className="absolute top-[-20%] right-[-10%] w-64 h-64 bg-white/5 rounded-full blur-3xl pointer-events-none" />
                <Share2 size={48} className="mb-8 opacity-40" />
                <h4 className="text-2xl font-black mb-4">Master Setup Link</h4>
                <p className="text-slate-400 text-sm leading-relaxed mb-8 font-medium italic">
                  Link your team's browsers to the current global registry. This bypasses manual API entry for all provisioned identities.
                </p>
                <button 
                  onClick={copySetupLink}
                  className={`w-full py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 transition-all ${copiedLink ? 'bg-emerald-500 text-white' : 'bg-white text-slate-900 hover:bg-slate-100'}`}
                >
                  {copiedLink ? <><Check size={18}/> LINK COPIED</> : <><Link2 size={18}/> COPY MASTER LINK</>}
                </button>
                <p className="mt-6 text-[10px] text-slate-500 text-center font-bold uppercase tracking-tight">Security Protocol Level 4 Active</p>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'config' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in duration-500">
          <div className="bg-white p-10 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-8">
            <div className="flex items-center gap-5">
              <div className="bg-indigo-50 p-4 rounded-3xl text-indigo-600 shadow-sm"><Cloud size={32}/></div>
              <div>
                <h4 className="text-2xl font-black text-slate-900">Cloud Persistence</h4>
                <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Global Identity Registry</p>
              </div>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-2">Supabase API URL</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-2xl py-4 px-6 text-sm font-bold outline-none transition-all" 
                  value={localSettings.supabaseUrl || ''} 
                  onChange={e => setLocalSettings({...localSettings, supabaseUrl: e.target.value})}
                  placeholder="https://your-project.supabase.co"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Supabase API Key (Anon/Service)</label>
                <input 
                  type="password" 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-2xl py-4 px-6 text-sm font-bold outline-none transition-all" 
                  value={localSettings.supabaseKey || ''} 
                  onChange={e => setLocalSettings({...localSettings, supabaseKey: e.target.value})}
                  placeholder="Secret API Key"
                />
              </div>
              <button 
                onClick={() => {
                  onUpdateSettings(localSettings);
                  localStorage.setItem('unsg_settings', JSON.stringify(localSettings));
                  alert('Cloud settings synchronized.');
                }}
                className="w-full bg-indigo-600 text-white font-black py-5 rounded-[1.5rem] shadow-2xl flex items-center justify-center gap-3 hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs"
              >
                <Save size={20}/> Update Cloud Core
              </button>
            </div>
          </div>

          <div className="bg-slate-900 p-10 rounded-[2.5rem] text-white space-y-6 relative shadow-2xl border border-slate-800">
            <div className="flex items-center gap-4 border-b border-slate-800 pb-6">
              <div className="bg-white/10 p-3 rounded-2xl"><Terminal size={24}/></div>
              <h4 className="text-xl font-black">Manual SQL Protocol</h4>
            </div>
            <div className="bg-slate-950 rounded-2xl p-6 font-mono text-[11px] border border-slate-800 h-64 overflow-y-auto group relative">
              <pre className="text-emerald-400 whitespace-pre-wrap">{sqlScript}</pre>
              <button 
                onClick={() => { navigator.clipboard.writeText(sqlScript); alert('SQL Copied'); }}
                className="absolute top-4 right-4 bg-slate-800 p-3 rounded-xl opacity-0 group-hover:opacity-100 hover:bg-slate-700 transition-all text-white"
              >
                <Copy size={20}/>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Identity Provisioning Modal (For System Users) */}
      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-indigo-600 p-12 text-white relative">
              <div className="bg-white/20 p-4 rounded-3xl w-fit mb-6 shadow-inner"><UserPlus size={32} /></div>
              <h3 className="text-3xl font-black">Professional Identity Provisioning</h3>
              <p className="text-xs text-indigo-200 mt-2 uppercase font-black tracking-widest">Compliance Access Control</p>
              <button onClick={() => setIsUserModalOpen(false)} className="absolute top-10 right-10 bg-white/10 p-3 rounded-full hover:bg-white/20 transition-all"><X size={24}/></button>
            </div>
            <form onSubmit={handleCreateUser} className="p-12 space-y-7">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Legal Professional Name</label>
                <input type="text" required className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-5 px-6 outline-none transition-all font-bold text-slate-700" placeholder="e.g. Reham Tanany" value={newUserName} onChange={(e) => setNewUserName(e.target.value)}/>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Identity Email</label>
                <input type="email" required className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-5 px-6 outline-none transition-all font-bold text-slate-700" placeholder="user@firm.com" value={newUserEmail} onChange={(e) => setNewUserEmail(e.target.value)}/>
