                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Assigned Security Role</label>
                <select className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-5 px-6 outline-none transition-all font-bold text-slate-700 cursor-pointer" value={newUserRole} onChange={(e) => setNewUserRole(e.target.value as UserRole)}>
