                <p className="text-xs text-red-100 mt-2 font-bold uppercase tracking-widest">Irreversible Critical Action</p>
             </div>
             <div className="p-10 space-y-8">
                <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 space-y-3">
                   <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Identity Record</div>
                   <div className="font-black text-slate-900 text-lg">{pendingDeleteUser.full_name}</div>
                   <div className="text-sm text-slate-500 font-medium">{pendingDeleteUser.email}</div>
                </div>

                <div className="flex items-start gap-4 p-5 bg-red-50 rounded-2xl text-red-700 text-[11px] font-bold leading-relaxed border border-red-100">
                   <ShieldAlert size={24} className="shrink-0"/>
                   <p>By proceeding, all platform privileges and audit association for this identity will be permanently decommissioned from the Global Registry.</p>
                </div>

                <div className="grid grid-cols-2 gap-4 pt-4">
                   <button 
                     onClick={() => setPendingDeleteUser(null)} 
                     className="py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-all border border-slate-100"
                   >
                     Cancel
                   </button>
                   <button 
                     onClick={confirmDeleteUser} 
                     disabled={isSyncing}
                     className="bg-red-600 hover:bg-red-700 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-red-100 transition-all flex items-center justify-center gap-2"
                   >
                     {isSyncing ? <RefreshCw className="animate-spin" size={14}/> : 'Revoke Access'}
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState } from 'react';
import { Client, RiskLevel, PersonRecord, KYCStatus, EntityType, UserRole } from '../types';
import { Plus, Trash2, Eye, RefreshCw, X, CheckCircle2, Landmark, Users, Mail, FileCheck, Shield, UserPlus, FileText, ArrowRight, ShieldAlert, Printer, Calendar, Briefcase, UserCheck, Gavel } from 'lucide-react';

interface FormSectionProps {
  title: string;
  icon: React.ReactNode;
  children?: React.ReactNode;
  fullWidth?: boolean;
}

const FormSection: React.FC<FormSectionProps> = ({ title, icon, children, fullWidth = false }) => (
  <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm space-y-6">
    <div className="flex items-center gap-4 text-emerald-800 font-black border-b border-gray-50 pb-4">
      <div className="bg-emerald-50 p-2.5 rounded-xl">{icon}</div>
      <span className="text-[10px] uppercase tracking-[0.2em]">{title}</span>
    </div>
    <div className={fullWidth ? "w-full" : "grid grid-cols-1 md:grid-cols-3 gap-6"}>{children}</div>
  </div>
);

const InputField = ({ label, value, onChange, type = "text", placeholder = "", required = false }: any) => (
  <div className="space-y-2">
    <div className="flex justify-between">
        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block ml-1">{label}</label>
        {required && <span className="text-[9px] text-amber-600 font-black uppercase">Required</span>}
    </div>
    <input 
      type={type} 
      placeholder={placeholder}
      className="w-full bg-gray-50 border-2 border-transparent rounded-2xl p-4 text-sm font-bold text-emerald-950 focus:border-emerald-800 focus:bg-white outline-none transition-all" 
      value={value} 
      onChange={e => onChange(e.target.value)} 
      required={required} 
    />
  </div>
);

const PersonRecordList = ({ label, items, onChange }: { label: string, items: PersonRecord[], onChange: (items: PersonRecord[]) => void }) => {
  const safeItems = Array.isArray(items) ? items : [];
  const addItem = () => onChange([...safeItems, { name: '', qid_passport: '', nationality: '', dob: '' }]);
  const updateItem = (index: number, field: keyof PersonRecord, value: string | number) => {
    const newItems = [...safeItems];
    newItems[index] = { ...newItems[index], [field]: value };
    onChange(newItems);
  };
  const removeItem = (index: number) => onChange(safeItems.filter((_, i) => i !== index));

  return (
    <div className="w-full space-y-4">
      <div className="flex justify-between items-center bg-emerald-950/5 p-4 rounded-2xl">
        <label className="text-[9px] font-black text-emerald-900 uppercase tracking-widest ml-2">{label}</label>
        <button type="button" onClick={addItem} className="text-[9px] uppercase tracking-widest flex items-center gap-2 bg-emerald-800 text-white px-4 py-2 rounded-xl font-black hover:bg-emerald-900 transition-all">
          <UserPlus size={14} /> Add Record
        </button>
      </div>
      {safeItems.length === 0 && (
        <div className="text-center py-6 border-2 border-dashed border-gray-100 rounded-[2rem]">
          <p className="text-[10px] text-gray-400 font-black uppercase">No records added for this category</p>
        </div>
      )}
      <div className="grid grid-cols-1 gap-4">
        {safeItems.map((item, idx) => (
          <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-4 p-6 bg-gray-50 rounded-[2rem] border border-gray-100 relative group">
            <div className="md:col-span-2">
              <InputField label="Name / Entity" value={item.name} onChange={(v: string) => updateItem(idx, 'name', v)} />
            </div>
            <InputField label="ID / Passport / Reg" value={item.qid_passport} onChange={(v: string) => updateItem(idx, 'qid_passport', v)} />
            <InputField label="Nationality / Juris" value={item.nationality} onChange={(v: string) => updateItem(idx, 'nationality', v)} />
            <div className="flex items-end gap-3">
              <div className="flex-1">
                 {label.includes('Shareholder') ? (
                   <InputField label="Share %" type="number" value={item.percentage} onChange={(v: any) => updateItem(idx, 'percentage', parseFloat(v))} />
                 ) : (
                   <InputField label="Date of Birth" type="date" value={item.dob} onChange={(v: string) => updateItem(idx, 'dob', v)} />
                 )}
              </div>
              <button type="button" onClick={() => removeItem(idx)} className="p-4 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all">
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

