            className={`flex-1 xs:flex-none flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl text-white transition-all shadow-xl font-black text-[10px] uppercase tracking-widest ${isUpdating ? 'bg-emerald-400' : 'bg-emerald-800 hover:bg-emerald-950 shadow-emerald-200'}`}
          >
            <RefreshCw size={18} className={isUpdating ? 'animate-spin' : ''} />
            {isUpdating ? 'Syncing...' : 'Live Fetch'}
          </button>
        </div>
      </div>

