                      <div className="flex flex-col items-center gap-4 text-gray-300">
                         <Database size={48} strokeWidth={1}/>
                         <p className="text-xs font-black uppercase tracking-widest">Zero Registry Matches for "{searchTerm}"</p>
                      </div>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination - Stack on very small, row on sm */}
        {filtered.length > 0 && (
          <div className="px-6 py-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-gray-50/30">
            <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">
              Showing <span className="text-emerald-950">{startIndex + 1}</span> - <span className="text-emerald-950">{Math.min(startIndex + ITEMS_PER_PAGE, filtered.length)}</span> of {filtered.length.toLocaleString()} Records
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={() => handlePageChange(currentPage - 1)} 
                disabled={currentPage === 1}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronLeft size={20} />
              </button>

              <div className="px-6 py-3 text-[10px] font-black text-emerald-950 bg-white rounded-xl border border-gray-200 shadow-sm min-w-[140px] text-center uppercase tracking-widest">
                Tier {currentPage} / {totalPages}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)} 
                disabled={currentPage === totalPages}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronRight size={20} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

