import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry } from '../types';
import { RefreshCw, Search, ChevronLeft, ChevronRight, Info, Database, Activity, CheckCircle2, AlertCircle, Loader2 } from 'lucide-react';
import { fetchSanctionsBatch, fetchSanctionsTotalCount } from '../services/cloudDb';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[]) => void;
  isCloudConnected: boolean;
}

const ITEMS_PER_PAGE = 15;
const TARGET_RECORDS = 1000;
const BATCH_SIZE = 500;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected }) => {
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [isFetching, setIsFetching] = useState(false);
  const [totalInDb, setTotalInDb] = useState(0);
  const [fetchProgress, setFetchProgress] = useState(0);
  const [syncStatus, setSyncStatus] = useState<'IDLE' | 'SYNCING' | 'COMPLETED' | 'ERROR'>('IDLE');
  const [lastSyncTime, setLastSyncTime] = useState<string>('Never');

  const fetchRegistry = useCallback(async () => {
    if (!isCloudConnected) return;

    setIsFetching(true);
    setSyncStatus('SYNCING');
    setSanctions([]);
    setFetchProgress(0);

    try {
      // Get exact count from DB
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);

      // Batch 1: First 500
      const batch1 = await fetchSanctionsBatch(0, BATCH_SIZE);
      setSanctions(batch1);
      setFetchProgress(batch1.length);

      // Batch 2: Next 500 (Total 1000)
      const batch2 = await fetchSanctionsBatch(BATCH_SIZE, BATCH_SIZE);
      const combined = [...batch1, ...batch2];

      // Filter duplicates just in case
      const unique = Array.from(new Set(combined.map(s => s.dataId)))
        .map(id => combined.find(s => s.dataId === id)!);

      setSanctions(unique);
      setFetchProgress(unique.length);
      setSyncStatus('COMPLETED');
      setLastSyncTime(new Date().toLocaleString());
      onSyncComplete(unique);
    } catch (err) {
      console.error("Registry Sync Error:", err);
      setSyncStatus('ERROR');
    } finally {
      setIsFetching(false);
    }
  }, [isCloudConnected, onSyncComplete]);

  useEffect(() => {
    fetchRegistry();
  }, [isCloudConnected]);

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (Array.isArray(s.aliases) && s.aliases.some(a => a.toLowerCase().includes(searchTerm.toLowerCase())))
  );

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const paginatedData = filtered.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  return (
    <div className="space-y-6 sm:space-y-8 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
           <div className="flex items-center gap-3 mb-2">
             <div className="p-2.5 bg-emerald-900 text-white rounded-xl shadow-lg shadow-emerald-100">
               <Database size={20} />
             </div>
             <h2 className="text-xl sm:text-2xl font-black text-emerald-950 uppercase tracking-tight">Sanctions Registry Node</h2>
           </div>
           <p className="text-xs sm:text-sm text-gray-400 font-bold uppercase tracking-widest ml-12">Authorized screening registry and fuzzy matching engine</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-3 w-full lg:w-auto">
          <div className="bg-slate-50 px-6 py-4 rounded-2xl border border-slate-100 flex flex-col justify-center min-w-[200px]">
             <div className="flex justify-between items-center mb-1">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Registry Sync</p>
                {syncStatus === 'SYNCING' && <Loader2 size={12} className="animate-spin text-amber-600" />}
                {syncStatus === 'COMPLETED' && <CheckCircle2 size={12} className="text-emerald-600" />}
             </div>
             <p className="text-xs font-black text-slate-800">{syncStatus === 'SYNCING' ? 'Synchronizing...' : syncStatus === 'COMPLETED' ? 'Synchronized' : 'Idle'}</p>
             <p className="text-[8px] font-bold text-slate-400 uppercase mt-1">Last: {lastSyncTime}</p>
          </div>

          <button 
            onClick={fetchRegistry}
            disabled={isFetching || !isCloudConnected}
            className="flex items-center justify-center gap-3 px-8 py-4 bg-emerald-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-100 hover:bg-emerald-950 disabled:opacity-50 transition-all h-full"
          >
            <RefreshCw size={16} className={isFetching ? 'animate-spin' : ''} />
            Re-Sync Registry
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center justify-between">
           <div>
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Registry Capacity</p>
              <h4 className="text-xl font-black text-emerald-950">{totalInDb.toLocaleString()}</h4>
           </div>
           <Database size={24} className="text-emerald-800 opacity-20" />
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center justify-between">
           <div>
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Active Batch Load</p>
              <h4 className="text-xl font-black text-amber-600">{fetchProgress.toLocaleString()} / {TARGET_RECORDS}</h4>
           </div>
           <Activity size={24} className="text-amber-800 opacity-20" />
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
           <div className="flex justify-between items-center mb-3">
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Progress</p>
              <span className="text-[9px] font-black text-emerald-800">{Math.round((fetchProgress / TARGET_RECORDS) * 100)}%</span>
           </div>
           <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-emerald-600 transition-all duration-1000" 
                style={{ width: `${(fetchProgress / TARGET_RECORDS) * 100}%` }}
              />
           </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-[2rem] shadow-sm border border-gray-100 flex items-center">
        <div className="relative flex-1">
          <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
          <input 
            type="text" 
            placeholder="Fuzzy search registry for names, aliases, or reference IDs..." 
            className="w-full pl-16 pr-6 py-5 bg-slate-50/50 border-none rounded-2xl focus:ring-2 focus:ring-emerald-800 outline-none transition-all text-sm font-bold placeholder-gray-300"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col relative">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse min-w-[900px]">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Source Node</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Registry Identity</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Jurisdiction</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Designation</th>
                <th className="px-8 py-6 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Audit Ref</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {paginatedData.map((entry) => (
                <tr key={entry.dataId} className="hover:bg-emerald-50/20 transition-colors group">
                  <td className="px-8 py-5">
                     <span className="inline-flex items-center px-3 py-1.5 rounded-xl text-[8px] font-black uppercase border bg-white border-slate-100 text-slate-500 group-hover:border-emerald-200 group-hover:text-emerald-800 transition-all">
                        {entry.source}
                     </span>
                  </td>
                  <td className="px-8 py-5">
                    <div className="font-black text-emerald-950 text-sm">{entry.firstName} {entry.lastName}</div>
                    {entry.aliases && entry.aliases.length > 0 && (
                      <div className="text-[9px] text-amber-600 font-bold uppercase mt-1 italic line-clamp-1">aka: {entry.aliases.join(', ')}</div>
                    )}
                  </td>
                  <td className="px-8 py-5">
                    <span className="px-2.5 py-1 rounded-md text-[9px] font-black uppercase bg-slate-100 text-slate-600 border border-slate-200">
                      {entry.nationality || 'Unspecified'}
                    </span>
                  </td>
                  <td className="px-8 py-5 text-xs font-black text-slate-600 uppercase tracking-tight">{entry.unListType}</td>
                  <td className="px-8 py-5 text-right text-[10px] text-slate-400 font-bold uppercase">{entry.referenceNumber}</td>
                </tr>
              ))}
              {paginatedData.length === 0 && (
                <tr>
                   <td colSpan={5} className="px-8 py-24 text-center">
                      {isFetching ? (
                        <div className="flex flex-col items-center gap-4 text-emerald-900 animate-pulse">
                          <Loader2 size={48} className="animate-spin" />
                          <p className="text-[10px] font-black uppercase tracking-widest">Synchronizing Registry...</p>
                        </div>
                      ) : (
                        <div className="flex flex-col items-center gap-4 text-slate-300">
                          <Database size={48} strokeWidth={1}/>
                          <p className="text-[10px] font-black uppercase tracking-widest">No registry matches for "{searchTerm}"</p>
                        </div>
                      )}
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {filtered.length > 0 && (
          <div className="px-8 py-8 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-slate-50/30">
            <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              Tier <span className="text-emerald-950">{currentPage}</span> of {totalPages} <span className="mx-2 opacity-30">•</span> {filtered.length.toLocaleString()} Hits
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} 
                disabled={currentPage === 1}
                className="p-3 bg-white border border-slate-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronLeft size={20} />
              </button>
              <div className="px-6 py-3 bg-white rounded-xl border border-slate-200 font-black text-[10px] uppercase tracking-widest min-w-[100px] text-center">{currentPage}</div>
              <button 
                onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} 
                disabled={currentPage === totalPages}
                className="p-3 bg-white border border-slate-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronRight size={20} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SanctionsRegistry;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsRegistry from './components/SanctionsRegistry';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Client, SanctionEntry, SystemLog, RiskLevel, AppSettings, UserRole, UserProfile, AccountStatus } from './types';
import { screenClient } from './services/screeningEngine';
import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  fetchCloudUsers, 
  upsertCloudUser
} from './services/cloudDb';
import { OFFICIAL_UN_XML_URL } from './services/unSanctionsService';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co'
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('unsg_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    let merged = stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
    if (!merged.supabaseUrl) merged.supabaseUrl = DEFAULT_SETTINGS.supabaseUrl;
    merged.autoSync = false;
    return merged;
  });
  const [connectionStatus, setConnectionStatus] = useState<'LOCAL' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('LOCAL');

  const subscriptionRef = useRef<any>(null);

  const syncIdentities = useCallback(async () => {
    const cloudUsers = await fetchCloudUsers();
    const storedUsersStr = localStorage.getItem('unsg_users');
    let localUsers = storedUsersStr ? JSON.parse(storedUsersStr) : [];

    if (cloudUsers) {
      const merged = [...localUsers];
      cloudUsers.forEach((cu: any) => {
        const localIdx = merged.findIndex((lu: any) => lu.email.toLowerCase() === cu.email.toLowerCase());
        const transformedUser = {
           ...cu,
           role: cu.role_id,
           password: cu.password_hash_mock
        };
        if (localIdx >= 0) merged[localIdx] = transformedUser;
        else merged.push(transformedUser);
      });
      localUsers = merged;
    }
    localStorage.setItem('unsg_users', JSON.stringify(localUsers));
  }, []);

  const handleLogin = (user: UserProfile) => {
    setCurrentUser(user);
    localStorage.setItem('unsg_session', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('unsg_session');
  };

  const refreshClients = useCallback(async (isConnected: boolean) => {
    if (isConnected) {
      try {
        const cloudClients = await fetchCloudClients();
        if (cloudClients) {
          setClients(cloudClients);
        }
      } catch (err: any) {
        console.error("Connection error loading clients.");
      }
    } else {
      const stored = localStorage.getItem('unsg_clients');
      if (stored) setClients(JSON.parse(stored));
    }
  }, []);

  // Automatic Re-Screening logic
  const performFuzzyScreening = useCallback(async (currentSanctions: SanctionEntry[], currentClients: Client[]) => {
    if (currentSanctions.length === 0 || currentClients.length === 0) return;

    const screenedClients = currentClients.map(client => {
      const match = screenClient(client, currentSanctions);
      return {
        ...client,
        riskLevel: match ? match.riskLevel : RiskLevel.NONE,
        lastScreenedAt: new Date().toISOString(),
        matches: match ? [match.sanctionId] : []
      };
    });

    // Update state and cloud
    setClients(screenedClients);
    if (connectionStatus === 'CONNECTED') {
      for (const updatedClient of screenedClients) {
         // Only push if changed to avoid unnecessary API calls
         const original = currentClients.find(c => c.id === updatedClient.id);
         if (original?.riskLevel !== updatedClient.riskLevel) {
           await upsertCloudClient(updatedClient);
         }
      }
    }
  }, [connectionStatus]);

  const handleRegistrySync = (newSanctions: SanctionEntry[]) => {
    setSanctions(newSanctions);
    performFuzzyScreening(newSanctions, clients);
  };

  useEffect(() => {
    if (!currentUser) return;
    const connectToCloud = async () => {
      if (!settings.supabaseUrl || !settings.supabaseKey) {
        setConnectionStatus('LOCAL');
        refreshClients(false);
        return;
      }
      setConnectionStatus('CONNECTING');
      const initialized = initSupabase(settings);
      if (initialized) {
        const healthy = await checkConnection();
        if (healthy) {
          setConnectionStatus('CONNECTED');
          await refreshClients(true);
          await syncIdentities();
          if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
          subscriptionRef.current = subscribeToClients(() => refreshClients(true));
        } else {
          setConnectionStatus('ERROR');
          refreshClients(false);
        }
      }
    };
    connectToCloud();
    return () => { if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current); };
  }, [settings, refreshClients, currentUser, syncIdentities]);

  if (!currentUser) return <Login onLogin={handleLogin} />;
  if (currentUser.must_change_password) return <PasswordUpdate user={currentUser} onUpdate={() => {}} />;

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={handleLogout}
        currentUser={currentUser}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctions.length} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              onAddClient={async (newClient) => {
                const match = screenClient(newClient, sanctions);
                const clientWithRisk = { ...newClient, riskLevel: match ? match.riskLevel : RiskLevel.NONE };
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(clientWithRisk);
                else setClients(prev => [clientWithRisk, ...prev]);
              }} 
              onUpdateClient={async (updated) => {
                const match = screenClient(updated, sanctions);
                const clientWithRisk = { ...updated, riskLevel: match ? match.riskLevel : RiskLevel.NONE };
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(clientWithRisk);
                setClients(prev => prev.map(c => c.id === updated.id ? clientWithRisk : c));
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                setClients(prev => prev.filter(c => c.id !== id));
              }}
              onRefresh={() => refreshClients(connectionStatus === 'CONNECTED')} 
              currentUserRole={currentUser.role}
              currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsRegistry 
              onSyncComplete={handleRegistrySync}
              isCloudConnected={connectionStatus === 'CONNECTED'}
            />} />
          <Route path="/admin" element={
            currentUser.is_system_admin === true ? (
              <AdminPanel 
                logs={[]} 
                settings={settings} 
                onUpdateSettings={setSettings} 
                currentUserId={currentUser.id}
                currentUser={currentUser}
              />
            ) : <Navigate to="/" replace />
          } />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry } from '../types';
import { RefreshCw, Search, ChevronLeft, ChevronRight, Info, Database, Activity, CheckCircle2, AlertCircle, Loader2, Beaker, Trash2, Zap } from 'lucide-react';
import { fetchSanctionsBatch, fetchSanctionsTotalCount } from '../services/cloudDb';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[]) => void;
  isCloudConnected: boolean;
}

const ITEMS_PER_PAGE = 15;
const TARGET_RECORDS = 1000;
const TEST_TARGET_RECORDS = 1000;
const BATCH_SIZE = 500;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected }) => {
  const [sanctions, setSanctions] = useState<(SanctionEntry & { isTestData?: boolean })[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [isFetching, setIsFetching] = useState(false);
  const [isTesting, setIsTesting] = useState(false);
  const [totalInDb, setTotalInDb] = useState(0);
  const [fetchProgress, setFetchProgress] = useState(0);
  const [testFetchProgress, setTestFetchProgress] = useState(0);
  const [syncStatus, setSyncStatus] = useState<'IDLE' | 'SYNCING' | 'COMPLETED' | 'ERROR'>('IDLE');
  const [testSyncStatus, setTestSyncStatus] = useState<'IDLE' | 'SYNCING' | 'COMPLETED' | 'ERROR'>('IDLE');
  const [lastSyncTime, setLastSyncTime] = useState<string>('Never');
  const [performanceMetrics, setPerformanceMetrics] = useState<{ time: number, count: number } | null>(null);

  const fetchRegistry = useCallback(async () => {
    if (!isCloudConnected) return;

    setIsFetching(true);
    setSyncStatus('SYNCING');
    setSanctions([]);
    setFetchProgress(0);
    setTestFetchProgress(0);
    setTestSyncStatus('IDLE');

    try {
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);

      // Batch 1: First 500
      const batch1 = await fetchSanctionsBatch(0, BATCH_SIZE);
      setSanctions(batch1);
      setFetchProgress(batch1.length);

      // Batch 2: Next 500 (Total 1000)
      const batch2 = await fetchSanctionsBatch(BATCH_SIZE, BATCH_SIZE);
      const combined = [...batch1, ...batch2];

      const unique = Array.from(new Set(combined.map(s => s.dataId)))
        .map(id => combined.find(s => s.dataId === id)!);

      setSanctions(unique);
      setFetchProgress(unique.length);
      setSyncStatus('COMPLETED');
      setLastSyncTime(new Date().toLocaleString());
      onSyncComplete(unique);
    } catch (err) {
      console.error("Registry Sync Error:", err);
      setSyncStatus('ERROR');
    } finally {
      setIsFetching(false);
    }
  }, [isCloudConnected, onSyncComplete]);

  const loadTestData = async () => {
    if (!isCloudConnected || isTesting) return;

    setIsTesting(true);
    setTestSyncStatus('SYNCING');
    setTestFetchProgress(0);
    const startTime = performance.now();

    try {
      // Fetch 1000 more records starting from index 1000
      // Batch 1 (Test): 1000 - 1500
      const testBatch1 = await fetchSanctionsBatch(TARGET_RECORDS, BATCH_SIZE);
      const tagged1 = testBatch1.map(s => ({ ...s, isTestData: true }));

      setSanctions(prev => [...prev, ...tagged1]);
      setTestFetchProgress(tagged1.length);

      // Batch 2 (Test): 1500 - 2000
      const testBatch2 = await fetchSanctionsBatch(TARGET_RECORDS + BATCH_SIZE, BATCH_SIZE);
      const tagged2 = testBatch2.map(s => ({ ...s, isTestData: true }));

      const finalTestSet = [...tagged1, ...tagged2];
      setSanctions(prev => {
        const merged = [...prev, ...tagged2];
        const unique = Array.from(new Set(merged.map(s => s.dataId)))
          .map(id => merged.find(s => s.dataId === id)!);
        return unique;
      });

      setTestFetchProgress(finalTestSet.length);
      setTestSyncStatus('COMPLETED');

      const endTime = performance.now();
      setPerformanceMetrics({ time: Math.round(endTime - startTime), count: finalTestSet.length });

      // Trigger screening logic update in parent
      setSanctions(current => {
        onSyncComplete(current);
        return current;
      });
    } catch (err) {
      console.error("Test Data Load Error:", err);
      setTestSyncStatus('ERROR');
    } finally {
      setIsTesting(false);
    }
  };

  const clearTestData = () => {
    const cleaned = sanctions.filter(s => !s.isTestData);
    setSanctions(cleaned);
    setTestFetchProgress(0);
    setTestSyncStatus('IDLE');
    setPerformanceMetrics(null);
    onSyncComplete(cleaned);
  };

  useEffect(() => {
    fetchRegistry();
  }, [isCloudConnected]);

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (Array.isArray(s.aliases) && s.aliases.some(a => a.toLowerCase().includes(searchTerm.toLowerCase())))
  );

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const paginatedData = filtered.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  return (
    <div className="space-y-6 sm:space-y-8 animate-in fade-in duration-500">
      {/* Header Panel */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="flex-1">
           <div className="flex items-center gap-3 mb-2">
             <div className="p-2.5 bg-emerald-900 text-white rounded-xl shadow-lg shadow-emerald-100">
               <Database size={20} />
             </div>
             <h2 className="text-xl sm:text-2xl font-black text-emerald-950 uppercase tracking-tight">Global Compliance Node</h2>
           </div>
           <p className="text-xs sm:text-sm text-gray-400 font-bold uppercase tracking-widest ml-12">Authorized screening registry and fuzzy matching engine</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-3 w-full lg:w-auto">
          <div className="bg-slate-50 px-6 py-4 rounded-2xl border border-slate-100 flex flex-col justify-center min-w-[200px]">
             <div className="flex justify-between items-center mb-1">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Protocol Sync</p>
                {syncStatus === 'SYNCING' && <Loader2 size={12} className="animate-spin text-amber-600" />}
                {syncStatus === 'COMPLETED' && <CheckCircle2 size={12} className="text-emerald-600" />}
             </div>
             <p className="text-xs font-black text-slate-800 uppercase tracking-tighter">
                {syncStatus === 'SYNCING' ? 'Synchronizing...' : syncStatus === 'COMPLETED' ? 'Verified Online' : 'Idle'}
             </p>
             <p className="text-[8px] font-bold text-slate-400 uppercase mt-1 tracking-widest">Node ID: {lastSyncTime}</p>
          </div>

          <button 
            onClick={fetchRegistry}
            disabled={isFetching || !isCloudConnected || isTesting}
            className="flex items-center justify-center gap-3 px-8 py-4 bg-emerald-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-100 hover:bg-emerald-950 disabled:opacity-50 transition-all h-full group"
          >
            <RefreshCw size={16} className={`${isFetching ? 'animate-spin' : 'group-hover:rotate-180'} transition-transform duration-500`} />
            Update Registry
          </button>
        </div>
      </div>

      {/* Validation Sandbox Control Panel */}
      <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden border border-slate-800">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <Beaker size={180} />
        </div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8">
          <div className="max-w-xl">
            <h3 className="text-xl sm:text-2xl font-black uppercase tracking-tight flex items-center gap-3 text-amber-500">
              <Beaker size={24} /> Validation Sandbox
            </h3>
            <p className="text-slate-400 text-xs sm:text-sm font-bold leading-relaxed uppercase tracking-tight mt-2">
              Stress-test the fuzzy matching engine and validate batch fetch logic by loading 1,000 isolated test records from the compliance cloud.
            </p>
            {performanceMetrics && (
              <div className="mt-4 flex items-center gap-3">
                 <div className="bg-emerald-500/10 text-emerald-400 px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest border border-emerald-500/20 flex items-center gap-2">
                    <Zap size={12}/> {performanceMetrics.time}ms execution
                 </div>
                 <div className="bg-amber-500/10 text-amber-400 px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest border border-amber-500/20">
                    {performanceMetrics.count} test hits
                 </div>
              </div>
            )}
          </div>

          <div className="flex flex-col xs:flex-row gap-3 w-full lg:w-auto">
            {testFetchProgress > 0 ? (
              <button 
                onClick={clearTestData}
                className="flex items-center justify-center gap-3 px-8 py-4 bg-red-500 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-red-900/20 hover:bg-red-600 transition-all"
              >
                <Trash2 size={16} /> Decommission Test Data
              </button>
            ) : (
              <button 
                onClick={loadTestData}
                disabled={isTesting || isFetching || !isCloudConnected}
                className="flex items-center justify-center gap-3 px-8 py-4 bg-amber-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-amber-900/20 hover:bg-amber-700 disabled:opacity-50 transition-all"
              >
                <Beaker size={16} className={isTesting ? 'animate-bounce' : ''} />
                Initialize Test Batch
              </button>
            )}
          </div>
        </div>

        {/* Test Data Progress Bar */}
        {(isTesting || testFetchProgress > 0) && (
          <div className="mt-8 pt-8 border-t border-slate-800 space-y-4">
             <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                   <div className={`w-2 h-2 rounded-full ${testSyncStatus === 'SYNCING' ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'}`} />
                   <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                      Validation Sequence: <span className="text-white">{testFetchProgress.toLocaleString()}</span> / {TEST_TARGET_RECORDS} Hits
                   </span>
                </div>
                <span className="text-[10px] font-black uppercase text-amber-500">{Math.round((testFetchProgress / TEST_TARGET_RECORDS) * 100)}% Complete</span>
             </div>
             <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-amber-600 transition-all duration-700 ease-out shadow-[0_0_10px_rgba(217,119,6,0.5)]" 
                  style={{ width: `${(testFetchProgress / TEST_TARGET_RECORDS) * 100}%` }}
                />
             </div>
          </div>
        )}
      </div>

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center justify-between group hover:border-emerald-200 transition-all">
           <div>
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Registry Capacity</p>
              <h4 className="text-xl font-black text-emerald-950 group-hover:scale-110 transition-transform origin-left">{totalInDb.toLocaleString()}</h4>
           </div>
           <Database size={24} className="text-emerald-800 opacity-20" />
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex items-center justify-between group hover:border-amber-200 transition-all">
           <div>
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Active Sandbox Volume</p>
              <h4 className="text-xl font-black text-amber-600 group-hover:scale-110 transition-transform origin-left">{testFetchProgress.toLocaleString()} Units</h4>
           </div>
           <Beaker size={24} className="text-amber-800 opacity-20" />
        </div>
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
           <div className="flex justify-between items-center mb-3">
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Main Registry Load</p>
              <span className="text-[9px] font-black text-emerald-800">{Math.round((fetchProgress / TARGET_RECORDS) * 100)}%</span>
           </div>
           <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-emerald-600 transition-all duration-1000" 
                style={{ width: `${(fetchProgress / TARGET_RECORDS) * 100}%` }}
              />
           </div>
        </div>
