                  <td className="px-8 py-5">
                     <div className="flex items-center gap-3">
                        <span className={`inline-flex items-center px-3 py-1.5 rounded-xl text-[8px] font-black uppercase border transition-all ${entry.isTestData ? 'bg-amber-50 text-amber-700 border-amber-100' : 'bg-white border-slate-100 text-slate-500 group-hover:border-emerald-200 group-hover:text-emerald-800'}`}>
                           {entry.source}
                        </span>
                        {entry.isTestData && (
                          <span className="bg-amber-600 text-white text-[7px] font-black px-1.5 py-0.5 rounded uppercase tracking-widest">TEST</span>
                        )}
                     </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="font-black text-emerald-950 text-sm flex items-center gap-2">
                       {entry.firstName} {entry.lastName}
                    </div>
                    {entry.aliases && entry.aliases.length > 0 && (
                      <div className="text-[9px] text-slate-400 font-bold uppercase mt-1 italic line-clamp-1 group-hover:text-amber-600 transition-colors">aka: {entry.aliases.join(', ')}</div>
                    )}
                  </td>
                  <td className="px-8 py-5">
                    <span className="px-2.5 py-1 rounded-md text-[9px] font-black uppercase bg-slate-100 text-slate-600 border border-slate-200">
                      {entry.nationality || 'Unspecified'}
                    </span>
                  </td>
                  <td className="px-8 py-5">
                     <div className="text-xs font-black text-slate-600 uppercase tracking-tight">{entry.unListType}</div>
                     <div className="text-[8px] text-slate-400 font-bold uppercase mt-1">Listed: {entry.listedOn || 'Permanent'}</div>
                  </td>
                  <td className="px-8 py-5 text-right text-[10px] text-slate-400 font-bold uppercase tracking-widest font-mono">{entry.referenceNumber}</td>
                </tr>
              ))}
              {paginatedData.length === 0 && (
                <tr>
                   <td colSpan={5} className="px-8 py-24 text-center">
                      {isFetching || isTesting ? (
                        <div className="flex flex-col items-center gap-4 text-emerald-900 animate-pulse">
                          <Loader2 size={48} className="animate-spin text-amber-600" />
                          <p className="text-[10px] font-black uppercase tracking-widest">Processing Registry Protocol...</p>
                        </div>
                      ) : (
                        <div className="flex flex-col items-center gap-4 text-slate-300">
                          <Database size={48} strokeWidth={1}/>
