export default SanctionsRegistry;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry } from '../types';
import { RefreshCw, Search, ChevronLeft, ChevronRight, Database, Activity, CheckCircle2, AlertCircle, Loader2, Beaker, Trash2, Zap, Play, Pause, Square, SkipForward } from 'lucide-react';
import { fetchSanctionsBatch, fetchSanctionsTotalCount } from '../services/cloudDb';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[]) => void;
  isCloudConnected: boolean;
}

type ProcessStatus = 'IDLE' | 'FETCHING' | 'TESTING' | 'PAUSED' | 'COMPLETED' | 'ERROR' | 'STOPPED';

const ITEMS_PER_PAGE = 15;
const BATCH_SIZE = 500;
const MAX_TARGET = 5000; // Configurable upper limit for automation

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected }) => {
  const [sanctions, setSanctions] = useState<(SanctionEntry & { isTestData?: boolean })[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  // Automation State
  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [currentOffset, setCurrentOffset] = useState(0);
  const [targetRecords, setTargetRecords] = useState(1000);
  const [batchesFetched, setBatchesFetched] = useState(0);
  const [batchesTested, setBatchesTested] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [lastActionLog, setLastActionLog] = useState<string>('System initialized. Waiting for manual trigger.');

  const isRunningRef = useRef(false);
  const isPausedRef = useRef(false);

  // Load total count on mount (authorized metadata)
  useEffect(() => {
    if (isCloudConnected) {
      fetchSanctionsTotalCount().then(setTotalInDb);
    }
  }, [isCloudConnected]);

  const logAction = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLastActionLog(`[${timestamp}] ${msg}`);
    console.log(`SanctionsRegistry: ${msg}`);
  };

  const runAutomationStep = useCallback(async (offset: number) => {
    if (!isRunningRef.current || isPausedRef.current) return;

    try {
      // Step 1: Fetching
      setStatus('FETCHING');
      logAction(`Initiating fetch for batch at offset ${offset}...`);
      const batch = await fetchSanctionsBatch(offset, BATCH_SIZE);

      if (batch.length === 0) {
        logAction("End of database reached.");
        setStatus('COMPLETED');
        isRunningRef.current = false;
        return;
      }

      setSanctions(prev => {
        const merged = [...prev, ...batch];
        return Array.from(new Set(merged.map(s => s.dataId)))
          .map(id => merged.find(s => s.dataId === id)!);
      });
      setBatchesFetched(prev => prev + 1);

      // Step 2: Testing (Screening)
      setStatus('TESTING');
      logAction(`Batch fetched (${batch.length} records). Starting automated integrity and fuzzy testing...`);

      // We wrap this in a small timeout to ensure UI updates and mimic processing time for large fuzzy sets
      await new Promise(resolve => setTimeout(resolve, 800));

      // Trigger parent screening logic
      setSanctions(current => {
        onSyncComplete(current);
        return current;
      });

      setBatchesTested(prev => prev + 1);
      const nextOffset = offset + batch.length;
      setCurrentOffset(nextOffset);

      // Step 3: Loop Check
      if (nextOffset >= targetRecords) {
        logAction(`Target reached (${nextOffset} records processed). Process finalized.`);
        setStatus('COMPLETED');
        isRunningRef.current = false;
      } else {
        logAction(`Batch ${batchesFetched + 1} verified. Proceeding to next segment...`);
        runAutomationStep(nextOffset);
      }

    } catch (err: any) {
      logAction(`CRITICAL FAILURE: ${err.message}`);
      setErrorMessage(err.message);
      setStatus('ERROR');
      isRunningRef.current = false;
    }
  }, [targetRecords, batchesFetched, onSyncComplete]);

  const handleStart = () => {
    if (!isCloudConnected) return;
    logAction(`User triggered START. Target: ${targetRecords} records.`);
    setErrorMessage(null);
    isRunningRef.current = true;
    isPausedRef.current = false;
    runAutomationStep(currentOffset);
  };

  const handlePause = () => {
    logAction("User triggered PAUSE. Operation suspended.");
    isPausedRef.current = true;
    setStatus('PAUSED');
  };

  const handleStop = () => {
    logAction("User triggered STOP. Sequence terminated.");
    isRunningRef.current = false;
    isPausedRef.current = false;
    setStatus('STOPPED');
  };

  const handleReset = () => {
    logAction("Registry clear requested. Returning to IDLE.");
    setSanctions([]);
    setCurrentOffset(0);
    setBatchesFetched(0);
    setBatchesTested(0);
    setStatus('IDLE');
    setErrorMessage(null);
    onSyncComplete([]);
  };

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (Array.isArray(s.aliases) && s.aliases.some(a => a.toLowerCase().includes(searchTerm.toLowerCase())))
  );

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const paginatedData = filtered.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  return (
    <div className="space-y-6 sm:space-y-8 animate-in fade-in duration-500">
      {/* Automated Control Console */}
      <div className="bg-slate-950 p-8 rounded-[2.5rem] text-white shadow-2xl border border-slate-800 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <Activity size={180} />
        </div>

        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8">
          <div className="space-y-4 max-w-2xl">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-emerald-500 rounded-lg text-slate-950">
                <Database size={20} />
              </div>
              <h3 className="text-xl sm:text-2xl font-black uppercase tracking-tight">Automation Engine</h3>
              {status !== 'IDLE' && (
                 <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest ${
                   status === 'FETCHING' ? 'bg-blue-500 text-white animate-pulse' :
                   status === 'TESTING' ? 'bg-amber-500 text-white animate-bounce' :
                   status === 'COMPLETED' ? 'bg-emerald-500 text-white' :
                   status === 'ERROR' ? 'bg-red-500 text-white' :
                   'bg-slate-700 text-slate-300'
                 }`}>
                   {status}
                 </span>
              )}
            </div>

            <p className="text-slate-400 text-xs sm:text-sm font-bold leading-relaxed uppercase tracking-tight">
              Sequential batch processor: Fetches {BATCH_SIZE} records, executes fuzzy match validation, and iterates until target is met. Fully manual initialization required.
            </p>

            <div className="flex flex-wrap gap-4 items-center">
              <div className="space-y-1">
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Target Depth</label>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    disabled={status !== 'IDLE' && status !== 'STOPPED' && status !== 'COMPLETED'}
                    value={targetRecords} 
                    onChange={e => setTargetRecords(Math.min(MAX_TARGET, parseInt(e.target.value) || 0))}
                    className="bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-xs font-black text-emerald-400 outline-none w-32 focus:border-emerald-500 transition-all"
                  />
                  <span className="text-[10px] text-slate-600 font-bold uppercase">/ {totalInDb.toLocaleString()} Max</span>
                </div>
              </div>

              <div className="flex gap-2">
                {status === 'FETCHING' || status === 'TESTING' ? (
                  <button onClick={handlePause} className="p-4 bg-amber-600 hover:bg-amber-700 rounded-2xl transition-all shadow-xl shadow-amber-900/20"><Pause size={20}/></button>
                ) : (
                  <button 
                    onClick={handleStart} 
                    disabled={!isCloudConnected || status === 'COMPLETED' || (currentOffset >= targetRecords && status !== 'IDLE')}
                    className="flex items-center gap-3 px-8 py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-900/20 disabled:opacity-30 transition-all"
                  >
                    <Play size={16} /> {status === 'PAUSED' ? 'Resume' : 'Start Fetch'}
                  </button>
                )}

                <button 
                  onClick={handleStop}
                  disabled={status === 'IDLE' || status === 'STOPPED' || status === 'COMPLETED'}
                  className="p-4 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl transition-all disabled:opacity-30"
                >
                  <Square size={20} />
                </button>

                <button 
                  onClick={handleReset}
                  className="p-4 bg-red-950/30 text-red-500 border border-red-900/30 hover:bg-red-500 hover:text-white rounded-2xl transition-all"
                >
                  <Trash2 size={20} />
                </button>
              </div>
            </div>
          </div>

          {/* Progress Indicators */}
          <div className="w-full lg:w-80 space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-slate-900 p-4 rounded-2xl border border-slate-800 text-center">
                <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Batches Fetched</p>
                <p className="text-xl font-black text-white">{batchesFetched}</p>
              </div>
              <div className="bg-slate-900 p-4 rounded-2xl border border-slate-800 text-center">
                <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Batches Tested</p>
                <p className="text-xl font-black text-white">{batchesTested}</p>
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex justify-between text-[10px] font-black uppercase tracking-widest">
                <span className="text-slate-500">Sequence Integrity</span>
                <span className="text-emerald-500">{Math.round((currentOffset / targetRecords) * 100)}%</span>
              </div>
              <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                <div 
                  className={`h-full transition-all duration-500 ${status === 'ERROR' ? 'bg-red-500' : 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.4)]'}`}
                  style={{ width: `${Math.min(100, (currentOffset / targetRecords) * 100)}%` }}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Live Event Log */}
        <div className="mt-8 pt-6 border-t border-slate-800 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={`w-2 h-2 rounded-full ${status === 'FETCHING' || status === 'TESTING' ? 'bg-emerald-500 animate-pulse' : 'bg-slate-600'}`} />
            <p className="text-[10px] font-bold text-slate-400 font-mono italic">{lastActionLog}</p>
          </div>
          {status === 'ERROR' && (
            <div className="flex items-center gap-2 text-red-500 bg-red-500/10 px-4 py-2 rounded-xl border border-red-500/20">
               <AlertCircle size={14}/>
               <span className="text-[9px] font-black uppercase tracking-widest">Batch Fault: {errorMessage}</span>
            </div>
          )}
        </div>
      </div>

      {/* Registry Display */}
      <div className="space-y-6">
        <div className="bg-white p-4 rounded-[2rem] shadow-sm border border-gray-100 flex items-center focus-within:ring-2 focus-within:ring-emerald-800 transition-all">
          <div className="relative flex-1">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
            <input 
              type="text" 
              placeholder="Query active batch profiles for names, aliases, or reference IDs..." 
              className="w-full pl-16 pr-6 py-5 bg-slate-50/50 border-none rounded-2xl outline-none transition-all text-sm font-bold placeholder-gray-300"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col relative">
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left border-collapse min-w-[1000px]">
              <thead className="bg-slate-50/50 border-b border-slate-100">
                <tr>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Source Protocol</th>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Identity Profile</th>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Nationality</th>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Designation</th>
                  <th className="px-8 py-6 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Reference ID</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {paginatedData.map((entry) => (
                  <tr key={entry.dataId} className="hover:bg-slate-50/80 transition-colors group">
                    <td className="px-8 py-5">
                       <span className="inline-flex items-center px-3 py-1.5 rounded-xl text-[8px] font-black uppercase border bg-white border-slate-100 text-slate-500 group-hover:border-emerald-200 group-hover:text-emerald-800 transition-all">
                          {entry.source}
                       </span>
                    </td>
                    <td className="px-8 py-5">
                      <div className="font-black text-emerald-950 text-sm">{entry.firstName} {entry.lastName}</div>
                      {entry.aliases && entry.aliases.length > 0 && (
                        <div className="text-[9px] text-slate-400 font-bold uppercase mt-1 italic line-clamp-1 group-hover:text-amber-600 transition-colors">aka: {entry.aliases.join(', ')}</div>
                      )}
                    </td>
                    <td className="px-8 py-5">
                      <span className="px-2.5 py-1 rounded-md text-[9px] font-black uppercase bg-slate-100 text-slate-600 border border-slate-200">
                        {entry.nationality || 'Unspecified'}
                      </span>
                    </td>
                    <td className="px-8 py-5">
                       <div className="text-xs font-black text-slate-600 uppercase tracking-tight">{entry.unListType}</div>
                    </td>
                    <td className="px-8 py-5 text-right text-[10px] text-slate-400 font-bold uppercase tracking-widest font-mono">{entry.referenceNumber}</td>
                  </tr>
                ))}
                {paginatedData.length === 0 && (
                  <tr>
                     <td colSpan={5} className="px-8 py-24 text-center">
                        <div className="flex flex-col items-center gap-4 text-slate-300">
                           <Database size={48} strokeWidth={1}/>
                           <p className="text-[10px] font-black uppercase tracking-widest">No registry matches for "{searchTerm}"</p>
                        </div>
                     </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          {filtered.length > 0 && (
            <div className="px-8 py-8 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-slate-50/30">
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                Tier <span className="text-emerald-950">{currentPage}</span> of {totalPages} <span className="mx-2 opacity-30">•</span> {filtered.length.toLocaleString()} Active Profiles
              </div>

              <div className="flex items-center gap-2">
                <button 
                  onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} 
                  disabled={currentPage === 1}
                  className="p-3 bg-white border border-slate-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
                >
                  <ChevronLeft size={20} />
                </button>
                <div className="px-8 py-3 bg-white rounded-xl border border-slate-200 font-black text-[10px] uppercase tracking-widest min-w-[100px] text-center shadow-sm">Page {currentPage}</div>
                <button 
                  onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} 
                  disabled={currentPage === totalPages}
                  className="p-3 bg-white border border-slate-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
                >
                  <ChevronRight size={20} />
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

