import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsRegistry from './components/SanctionsRegistry';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Client, SanctionEntry, SystemLog, RiskLevel, AppSettings, UserRole, UserProfile, AccountStatus } from './types';
import { screenClient } from './services/screeningEngine';
import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  fetchCloudUsers, 
  upsertCloudUser
} from './services/cloudDb';
import { OFFICIAL_UN_XML_URL } from './services/unSanctionsService';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co'
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('unsg_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [registryStats, setRegistryStats] = useState(() => {
    const saved = localStorage.getItem('unsg_registry_stats');
    return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never' };
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    let merged = stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
    if (!merged.supabaseUrl) merged.supabaseUrl = DEFAULT_SETTINGS.supabaseUrl;
    merged.autoSync = false;
    return merged;
  });
  const [connectionStatus, setConnectionStatus] = useState<'LOCAL' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('LOCAL');

  const subscriptionRef = useRef<any>(null);

  const syncIdentities = useCallback(async () => {
    const cloudUsers = await fetchCloudUsers();
    const storedUsersStr = localStorage.getItem('unsg_users');
    let localUsers = storedUsersStr ? JSON.parse(storedUsersStr) : [];

    if (cloudUsers) {
      const merged = [...localUsers];
      cloudUsers.forEach((cu: any) => {
        const localIdx = merged.findIndex((lu: any) => lu.email.toLowerCase() === cu.email.toLowerCase());
        const transformedUser = {
           ...cu,
           role: cu.role_id,
           password: cu.password_hash_mock
        };
        if (localIdx >= 0) merged[localIdx] = transformedUser;
        else merged.push(transformedUser);
      });
      localUsers = merged;
    }
    localStorage.setItem('unsg_users', JSON.stringify(localUsers));
  }, []);

  const handleLogin = (user: UserProfile) => {
    setCurrentUser(user);
    localStorage.setItem('unsg_session', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('unsg_session');
  };

  const refreshClients = useCallback(async (isConnected: boolean) => {
    if (isConnected) {
      try {
        const cloudClients = await fetchCloudClients();
        if (cloudClients) {
          setClients(cloudClients);
        }
      } catch (err: any) {
        console.error("Connection error loading clients.");
      }
    } else {
      const stored = localStorage.getItem('unsg_clients');
      if (stored) setClients(JSON.parse(stored));
    }
  }, []);

  // Automatic Re-Screening logic
  const performFuzzyScreening = useCallback(async (currentSanctions: SanctionEntry[], currentClients: Client[]) => {
    if (currentSanctions.length === 0 || currentClients.length === 0) return;

    const screenedClients = currentClients.map(client => {
      const match = screenClient(client, currentSanctions);
      return {
        ...client,
        riskLevel: match ? match.riskLevel : RiskLevel.NONE,
        lastScreenedAt: new Date().toISOString(),
        matches: match ? [match.sanctionId] : []
      };
    });

    setClients(screenedClients);
    if (connectionStatus === 'CONNECTED') {
      for (const updatedClient of screenedClients) {
         const original = currentClients.find(c => c.id === updatedClient.id);
         if (original?.riskLevel !== updatedClient.riskLevel) {
           await upsertCloudClient(updatedClient);
         }
      }
    }
  }, [connectionStatus]);

  const handleRegistrySync = (newSanctions: SanctionEntry[], stats?: { lastFetch: string; lastTest: string }) => {
    setSanctions(newSanctions);
    if (stats) {
      setRegistryStats(stats);
      localStorage.setItem('unsg_registry_stats', JSON.stringify(stats));
    }
    performFuzzyScreening(newSanctions, clients);
  };

  useEffect(() => {
    if (!currentUser) return;
    const connectToCloud = async () => {
      if (!settings.supabaseUrl || !settings.supabaseKey) {
        setConnectionStatus('LOCAL');
        refreshClients(false);
        return;
      }
      setConnectionStatus('CONNECTING');
      const initialized = initSupabase(settings);
      if (initialized) {
        const healthy = await checkConnection();
        if (healthy) {
          setConnectionStatus('CONNECTED');
          await refreshClients(true);
          await syncIdentities();
          if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
          subscriptionRef.current = subscribeToClients(() => refreshClients(true));
        } else {
          setConnectionStatus('ERROR');
          refreshClients(false);
        }
      }
    };
    connectToCloud();
    return () => { if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current); };
  }, [settings, refreshClients, currentUser, syncIdentities]);

  if (!currentUser) return <Login onLogin={handleLogin} />;
  if (currentUser.must_change_password) return <PasswordUpdate user={currentUser} onUpdate={() => {}} />;

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={handleLogout}
        currentUser={currentUser}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctions.length} registryStats={registryStats} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              onAddClient={async (newClient) => {
                const match = screenClient(newClient, sanctions);
                const clientWithRisk = { ...newClient, riskLevel: match ? match.riskLevel : RiskLevel.NONE };
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(clientWithRisk);
                else setClients(prev => [clientWithRisk, ...prev]);
              }} 
              onUpdateClient={async (updated) => {
                const match = screenClient(updated, sanctions);
                const clientWithRisk = { ...updated, riskLevel: match ? match.riskLevel : RiskLevel.NONE };
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(clientWithRisk);
                setClients(prev => prev.map(c => c.id === updated.id ? clientWithRisk : c));
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                setClients(prev => prev.filter(c => c.id !== id));
              }}
              onRefresh={() => refreshClients(connectionStatus === 'CONNECTED')} 
              currentUserRole={currentUser.role}
              currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsRegistry 
              onSyncComplete={handleRegistrySync}
              isCloudConnected={connectionStatus === 'CONNECTED'}
              initialStats={registryStats}
            />} />
          <Route path="/admin" element={
            currentUser.is_system_admin === true ? (
              <AdminPanel 
                logs={[]} 
                settings={settings} 
                onUpdateSettings={setSettings} 
                currentUserId={currentUser.id}
                currentUser={currentUser}
              />
            ) : <Navigate to="/" replace />
          } />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry } from '../types';
import { RefreshCw, Search, ChevronLeft, ChevronRight, Database, Activity, CheckCircle2, AlertCircle, Loader2, Play, Pause, Square, Trash2, Clock, ShieldCheck, CloudDownload, Server, Cpu } from 'lucide-react';
import { fetchSanctionsBatch, fetchSanctionsTotalCount, upsertCloudSanctions } from '../services/cloudDb';
import { fetchFromUrl, OFFICIAL_UN_XML_URL } from '../services/unSanctionsService';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[], stats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string }) => void;
  isCloudConnected: boolean;
  initialStats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string };
}

type ProcessStatus = 'IDLE' | 'FETCHING' | 'TESTING' | 'PAUSED' | 'COMPLETED' | 'ERROR' | 'STOPPED' | 'UPLOADING';

const ITEMS_PER_PAGE = 15;
const BATCH_SIZE = 500;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, initialStats }) => {
  const [sanctions, setSanctions] = useState<(SanctionEntry & { isTestData?: boolean })[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  // Automation & Source States
  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [currentOffset, setCurrentOffset] = useState(0);
  const [targetRecords, setTargetRecords] = useState(0);
  const [batchesFetched, setBatchesFetched] = useState(0);
  const [batchesTested, setBatchesTested] = useState(0);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [lastActionLog, setLastActionLog] = useState<string>('System initialized. Waiting for manual trigger.');

  // Timestamp State
  const [lastFetchTime, setLastFetchTime] = useState<string>(initialStats?.lastFetch || 'Never');
  const [lastTestTime, setLastTestTime] = useState<string>(initialStats?.lastTest || 'Never');
  const [lastSourceUpdate, setLastSourceUpdate] = useState<string>(initialStats?.lastSourceUpdate || 'Never');

  const isRunningRef = useRef(false);
  const isPausedRef = useRef(false);

  // Refresh total count from cloud
  const refreshDbStats = useCallback(async () => {
    if (isCloudConnected) {
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);
      return count;
    }
    return 0;
  }, [isCloudConnected]);

  useEffect(() => {
    refreshDbStats().then(count => {
      if (targetRecords === 0) setTargetRecords(count);
    });
  }, [refreshDbStats]);

  const logAction = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLastActionLog(`[${timestamp}] ${msg}`);
  };

  /**
   * CORE PURPOSE: Import and Update from Source
   * Fetches official UN XML and pushes to Supabase
   */
  const syncFromOfficialSource = async () => {
    if (!isCloudConnected) return;
    setStatus('UPLOADING');
    setUploadProgress(0);
    setErrorMessage(null);
    logAction("Initiating handshake with UN Security Council Source...");

    try {
      const liveData = await fetchFromUrl(OFFICIAL_UN_XML_URL);
      logAction(`Live source retrieved: ${liveData.length} records found. Synchronizing with Cloud Registry...`);

      await upsertCloudSanctions(liveData, (progress) => {
        setUploadProgress(progress);
      });

      const now = new Date().toLocaleString();
      setLastSourceUpdate(now);
      const newTotal = await refreshDbStats();
      setTargetRecords(newTotal);

      logAction("Cloud Registry synchronized successfully. Source update complete.");
      setStatus('COMPLETED');

      // Auto-trigger automation engine to refresh view
      handleStart();
    } catch (err: any) {
      const msg = err.message.includes('fetch') ? "CORS/Network Block: Source unreachable. Use manual file import in Governance." : err.message;
      setErrorMessage(msg);
      setStatus('ERROR');
      logAction(`Source Sync Failure: ${msg}`);
    }
  };

  /**
   * AUTOMATION ENGINE: Sequential Batch Processing
   * Reads from Cloud Registry and triggers fuzzy screening
   */
  const runAutomationStep = useCallback(async (offset: number) => {
    if (!isRunningRef.current || isPausedRef.current) return;

    try {
      setStatus('FETCHING');
      logAction(`Retrieving batch at offset ${offset}...`);
      const batch = await fetchSanctionsBatch(offset, BATCH_SIZE);

      const now = new Date().toLocaleString();
      setLastFetchTime(now);

      if (batch.length === 0) {
        logAction("Registry saturation reached.");
        setStatus('COMPLETED');
        isRunningRef.current = false;
        return;
      }

      setSanctions(prev => {
        const merged = [...prev, ...batch];
        return Array.from(new Set(merged.map(s => s.dataId)))
          .map(id => merged.find(s => s.dataId === id)!);
      });
      setBatchesFetched(prev => prev + 1);

      setStatus('TESTING');
      logAction(`Batch retrieved. Executing automated fuzzy integrity validation...`);

      await new Promise(resolve => setTimeout(resolve, 600));

      const testNow = new Date().toLocaleString();
      setLastTestTime(testNow);

      onSyncComplete(sanctions, { 
        lastFetch: now, 
        lastTest: testNow, 
        lastSourceUpdate 
      });

      setBatchesTested(prev => prev + 1);
      const nextOffset = offset + batch.length;
      setCurrentOffset(nextOffset);

      if (nextOffset >= targetRecords) {
        logAction(`Target depth reached (${nextOffset} records). Node synchronized.`);
        setStatus('COMPLETED');
        isRunningRef.current = false;
      } else {
        runAutomationStep(nextOffset);
      }

    } catch (err: any) {
      setErrorMessage(err.message);
      setStatus('ERROR');
      isRunningRef.current = false;
    }
  }, [targetRecords, batchesFetched, onSyncComplete, lastSourceUpdate, sanctions]);

  const handleStart = () => {
    if (!isCloudConnected) return;
    logAction(`User triggered START. Target: ${targetRecords} records.`);
    setErrorMessage(null);
    isRunningRef.current = true;
    isPausedRef.current = false;
    runAutomationStep(currentOffset);
  };

  const handlePause = () => {
    isPausedRef.current = true;
    setStatus('PAUSED');
    logAction("Operation suspended.");
  };

  const handleStop = () => {
    isRunningRef.current = false;
    isPausedRef.current = false;
    setStatus('STOPPED');
    logAction("Sequence terminated.");
  };

  const handleReset = () => {
    setSanctions([]);
    setCurrentOffset(0);
    setBatchesFetched(0);
    setBatchesTested(0);
    setStatus('IDLE');
    setErrorMessage(null);
    onSyncComplete([], { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate });
    logAction("Node cache cleared.");
  };

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (Array.isArray(s.aliases) && s.aliases.some(a => a.toLowerCase().includes(searchTerm.toLowerCase())))
  );

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const paginatedData = filtered.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  return (
    <div className="space-y-6 sm:space-y-8 animate-in fade-in duration-500 pb-20">
      {/* 1. SOURCE SYNCHRONIZER */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm flex flex-col xl:flex-row gap-8">
        <div className="flex-1 space-y-4">
           <div className="flex items-center gap-3">
             <div className="p-2.5 bg-blue-900 text-white rounded-xl shadow-lg shadow-blue-100">
               <CloudDownload size={24} />
             </div>
             <div>
                <h2 className="text-xl sm:text-2xl font-black text-slate-900 uppercase tracking-tight">Source Synchronizer</h2>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Global UN Security Council Live Feed</p>
             </div>
           </div>
           <p className="text-xs text-gray-500 font-medium leading-relaxed max-w-2xl">
             Connects directly to official UN XML endpoints to ingest latest designations. This process populates your Cloud Registry for downstream screening.
           </p>

           <div className="flex flex-wrap gap-3">
              <div className="bg-slate-50 px-5 py-3 rounded-2xl border border-slate-100 min-w-[180px]">
                 <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-2">
                    <Clock size={10} /> Last Source Sync
                 </p>
                 <p className="text-[10px] font-black text-slate-800 uppercase">{lastSourceUpdate}</p>
              </div>
              <button 
                onClick={syncFromOfficialSource}
                disabled={!isCloudConnected || status === 'UPLOADING' || isRunningRef.current}
                className="flex items-center justify-center gap-3 px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 disabled:opacity-50 transition-all"
              >
                {status === 'UPLOADING' ? <Loader2 size={16} className="animate-spin" /> : <RefreshCw size={16} />}
                Update from Source
              </button>
           </div>
        </div>

        {status === 'UPLOADING' && (
          <div className="xl:w-80 bg-blue-50/50 rounded-3xl p-6 border border-blue-100 flex flex-col justify-center space-y-4">
             <div className="flex justify-between items-center">
                <span className="text-[9px] font-black text-blue-900 uppercase">Cloud Uplink</span>
                <span className="text-[9px] font-black text-blue-900">{uploadProgress}%</span>
             </div>
             <div className="w-full h-2 bg-blue-100 rounded-full overflow-hidden">
                <div className="h-full bg-blue-600 transition-all duration-500" style={{ width: `${uploadProgress}%` }} />
             </div>
             <p className="text-[8px] font-bold text-blue-400 uppercase tracking-tighter text-center italic">Ingesting Registry Chunks...</p>
          </div>
        )}
      </div>

      {/* 2. AUTOMATION ENGINE (SCREENING) */}
      <div className="bg-slate-950 p-8 rounded-[2.5rem] text-white shadow-2xl border border-slate-800 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none text-emerald-500">
           <Cpu size={180} />
        </div>

        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8">
          <div className="space-y-4 max-w-2xl">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-emerald-500 rounded-lg text-slate-950">
                <Activity size={20} />
              </div>
              <h3 className="text-xl sm:text-2xl font-black uppercase tracking-tight">Automation Engine</h3>
              {status !== 'IDLE' && status !== 'UPLOADING' && (
                 <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest ${
                   status === 'FETCHING' ? 'bg-blue-500 text-white animate-pulse' :
                   status === 'TESTING' ? 'bg-amber-500 text-white animate-bounce' :
                   status === 'COMPLETED' ? 'bg-emerald-500 text-white' :
                   status === 'ERROR' ? 'bg-red-500 text-white' :
                   'bg-slate-700 text-slate-300'
                 }`}>
                   {status}
                 </span>
              )}
            </div>

            <p className="text-slate-400 text-xs sm:text-sm font-bold leading-relaxed uppercase tracking-tight">
              Screening Sequencer: Processes Cloud Registry in batches, validating fuzzy matches against your local client base.
            </p>

            <div className="flex flex-wrap gap-4 items-center">
              <div className="space-y-1">
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Target Depth</label>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    disabled={status !== 'IDLE' && status !== 'STOPPED' && status !== 'COMPLETED'}
                    value={targetRecords} 
                    onChange={e => setTargetRecords(Math.min(totalInDb, parseInt(e.target.value) || 0))}
                    className="bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-xs font-black text-emerald-400 outline-none w-32 focus:border-emerald-500 transition-all"
                  />
                  <span className="text-[10px] text-slate-600 font-bold uppercase">/ {totalInDb.toLocaleString()} Available</span>
                </div>
              </div>

              <div className="flex gap-2">
                {status === 'FETCHING' || status === 'TESTING' ? (
                  <button onClick={handlePause} className="p-4 bg-amber-600 hover:bg-amber-700 rounded-2xl transition-all shadow-xl shadow-amber-900/20"><Pause size={20}/></button>
                ) : (
                  <button 
                    onClick={handleStart} 
                    disabled={!isCloudConnected || status === 'COMPLETED' || (currentOffset >= targetRecords && status !== 'IDLE') || status === 'UPLOADING'}
                    className="flex items-center gap-3 px-8 py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-900/20 disabled:opacity-30 transition-all"
                  >
                    <Play size={16} /> {status === 'PAUSED' ? 'Resume' : 'Execute Screening'}
                  </button>
                )}
                <button onClick={handleStop} disabled={status === 'IDLE' || status === 'STOPPED' || status === 'COMPLETED'} className="p-4 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl transition-all disabled:opacity-30">
                  <Square size={20} />
                </button>
                <button onClick={handleReset} className="p-4 bg-red-950/30 text-red-500 border border-red-900/30 hover:bg-red-500 hover:text-white rounded-2xl transition-all">
                  <Trash2 size={20} />
                </button>
              </div>
            </div>
          </div>

          <div className="w-full lg:w-80 space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-slate-900 p-4 rounded-2xl border border-slate-800 text-center">
                <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Local Cache</p>
                <p className="text-xl font-black text-white">{batchesFetched}</p>
              </div>
              <div className="bg-slate-900 p-4 rounded-2xl border border-slate-800 text-center">
                <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Tested</p>
                <p className="text-xl font-black text-white">{batchesTested}</p>
              </div>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between text-[10px] font-black uppercase tracking-widest">
                <span className="text-slate-500">Screening Coverage</span>
                <span className="text-emerald-500">{targetRecords > 0 ? Math.round((currentOffset / targetRecords) * 100) : 0}%</span>
              </div>
              <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                <div 
                  className={`h-full transition-all duration-500 ${status === 'ERROR' ? 'bg-red-500' : 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.4)]'}`}
                  style={{ width: `${targetRecords > 0 ? Math.min(100, (currentOffset / targetRecords) * 100) : 0}%` }}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Live Event Log */}
        <div className="mt-8 pt-6 border-t border-slate-800 flex flex-col xs:flex-row items-start xs:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className={`w-2 h-2 rounded-full ${isRunningRef.current ? 'bg-emerald-500 animate-pulse' : 'bg-slate-600'}`} />
            <p className="text-[10px] font-bold text-slate-400 font-mono italic">{lastActionLog}</p>
          </div>
          <div className="flex gap-4">
            <div className="flex flex-col items-end">
               <p className="text-[8px] font-black text-slate-600 uppercase">Last Cache</p>
               <p className="text-[9px] font-black text-white uppercase">{lastFetchTime}</p>
            </div>
            <div className="flex flex-col items-end">
               <p className="text-[8px] font-black text-slate-600 uppercase">Last Validation</p>
               <p className="text-[9px] font-black text-white uppercase">{lastTestTime}</p>
            </div>
          </div>
        </div>
        {status === 'ERROR' && (
          <div className="mt-4 flex items-center gap-2 text-red-500 bg-red-500/10 px-4 py-2 rounded-xl border border-red-500/20">
             <AlertCircle size={14}/>
             <span className="text-[9px] font-black uppercase tracking-widest">System Fault: {errorMessage}</span>
          </div>
        )}
      </div>

      {/* Registry View */}
      <div className="space-y-6">
        <div className="bg-white p-4 rounded-[2rem] shadow-sm border border-gray-100 flex items-center focus-within:ring-2 focus-within:ring-emerald-800 transition-all">
          <div className="relative flex-1">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
            <input 
              type="text" 
              placeholder="Query node identities for names, aliases, or reference IDs..." 
              className="w-full pl-16 pr-6 py-5 bg-slate-50/50 border-none rounded-2xl outline-none transition-all text-sm font-bold placeholder-gray-300"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col relative">
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left border-collapse min-w-[1000px]">
              <thead className="bg-slate-50/50 border-b border-slate-100">
                <tr>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Protocol</th>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Designated Profile</th>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Jurisdiction</th>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Designation</th>
                  <th className="px-8 py-6 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Audit ID</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {paginatedData.map((entry) => (
                  <tr key={entry.dataId} className="hover:bg-slate-50/80 transition-colors group">
                    <td className="px-8 py-5">
                       <span className="inline-flex items-center px-3 py-1.5 rounded-xl text-[8px] font-black uppercase border bg-white border-slate-100 text-slate-500 group-hover:border-emerald-200 group-hover:text-emerald-800 transition-all">
                          {entry.source}
                       </span>
                    </td>
                    <td className="px-8 py-5">
                      <div className="font-black text-emerald-950 text-sm">{entry.firstName} {entry.lastName}</div>
                      {entry.aliases && entry.aliases.length > 0 && (
                        <div className="text-[9px] text-slate-400 font-bold uppercase mt-1 italic line-clamp-1 group-hover:text-amber-600 transition-colors">aka: {entry.aliases.join(', ')}</div>
                      )}
                    </td>
                    <td className="px-8 py-5">
                      <span className="px-2.5 py-1 rounded-md text-[9px] font-black uppercase bg-slate-100 text-slate-600 border border-slate-200">
                        {entry.nationality || 'Unspecified'}
                      </span>
                    </td>
                    <td className="px-8 py-5">
                       <div className="text-xs font-black text-slate-600 uppercase tracking-tight">{entry.unListType}</div>
                    </td>
                    <td className="px-8 py-5 text-right text-[10px] text-slate-400 font-bold uppercase tracking-widest font-mono">{entry.referenceNumber}</td>
                  </tr>
                ))}
                {paginatedData.length === 0 && (
                  <tr>
                     <td colSpan={5} className="px-8 py-24 text-center">
                        <div className="flex flex-col items-center gap-4 text-slate-300">
                           <Database size={48} strokeWidth={1}/>
                           <p className="text-[10px] font-black uppercase tracking-widest">Node results null for "{searchTerm}"</p>
                        </div>
                     </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          {filtered.length > 0 && (
            <div className="px-8 py-8 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-slate-50/30">
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                Tier <span className="text-emerald-950">{currentPage}</span> of {totalPages} <span className="mx-2 opacity-30">•</span> {filtered.length.toLocaleString()} Active Profiles
              </div>

              <div className="flex items-center gap-2">
                <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="p-3 bg-white border border-slate-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm">
                  <ChevronLeft size={20} />
                </button>
                <div className="px-8 py-3 bg-white rounded-xl border border-slate-200 font-black text-[10px] uppercase tracking-widest min-w-[100px] text-center shadow-sm">Page {currentPage}</div>
                <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} disabled={currentPage === totalPages} className="p-3 bg-white border border-slate-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm">
                  <ChevronRight size={20} />
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SanctionsRegistry;

import React from 'react';
