  );

  return (
    <div className="space-y-6 sm:space-y-8">
      {/* Registry Pulse Header */}
      <div className="bg-emerald-950 p-6 sm:p-8 rounded-[2rem] text-white flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none">
          <Activity size={120} />
        </div>
