import React, { useState, useEffect } from 'react';
import { Lock, Mail, AlertCircle, Eye, EyeOff, CheckCircle, RefreshCw, Wifi, WifiOff, ChevronDown, ChevronUp, ShieldCheck, Zap, Server, Activity } from 'lucide-react';
import { UserProfile, UserRole, AccountStatus, AppSettings } from '../types';
import { fetchCloudUsers, initSupabase, checkConnection } from '../services/cloudDb';

interface LoginProps {
  onLogin: (user: UserProfile) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [supabaseKey, setSupabaseKey] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showCloudSetup, setShowCloudSetup] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isCloudReady, setIsCloudReady] = useState(false);

  const LOCAL_LOGO = "/images/logo.png";
  const GITHUB_LOGO = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";

  useEffect(() => {
    const stored = localStorage.getItem('unsg_settings');
    if (stored) {
      try {
        const settings: AppSettings = JSON.parse(stored);
        if (settings.supabaseUrl && settings.supabaseKey) {
          initSupabase(settings);
          checkConnection().then(connected => setIsCloudReady(connected));
        }
      } catch (e) {
        console.error("Cloud restore failed", e);
      }
    }
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPassword = password.trim();

    if (normalizedEmail === 'aqandeel@gmail.com' && normalizedPassword === 'Rodl@2026') {
      setIsSuccess(true);
      setTimeout(() => {
        onLogin({
          id: 'SYS-ADMIN-ROOT',
          email: 'aqandeel@gmail.com',
          full_name: 'RPME System Admin',
          role: UserRole.ADMIN, 
          is_system_admin: true, 
          status: AccountStatus.ACTIVE,
          must_change_password: false,
          password_expiry: '',
          created_at: new Date().toISOString()
        });
      }, 800);
      return;
    }

    if (!isCloudReady && supabaseKey) {
      const tempSettings: AppSettings = {
        autoSync: true,
        syncIntervalMinutes: 1440,
        sourceUrl: '',
        lastSync: 'Never',
        nextSync: '',
        supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co',
        supabaseKey: supabaseKey
      };
      const initialized = initSupabase(tempSettings);
      const connected = initialized ? await checkConnection() : false;
      if (!connected) {
        setError('Handshake Error: Invalid Registry Key.');
        setIsLoading(false);
        return;
      }
      localStorage.setItem('unsg_settings', JSON.stringify(tempSettings));
      setIsCloudReady(true);
    }

    let userFound: any = null;
    try {
      const cloudUsers = await fetchCloudUsers();
      if (cloudUsers) {
        userFound = cloudUsers.find((u: any) => u.email.toLowerCase().trim() === normalizedEmail && u.password_hash_mock === normalizedPassword);
        if (userFound) {
          userFound = { ...userFound, role: userFound.role_id, password: userFound.password_hash_mock };
          const stored = JSON.parse(localStorage.getItem('unsg_users') || '[]');
          localStorage.setItem('unsg_users', JSON.stringify([...stored.filter((u:any) => u.email !== normalizedEmail), userFound]));
        }
      }
    } catch (err) { console.warn("Registry fallback triggered."); }

    if (!userFound) {
      const stored = JSON.parse(localStorage.getItem('unsg_users') || '[]');
      userFound = stored.find((u: any) => u.email.toLowerCase().trim() === normalizedEmail && (u.password || u.password_hash_mock) === normalizedPassword);
    }

    if (userFound) {
      if (userFound.status === AccountStatus.DISABLED) {
        setError('Identity Status: This account has been decommissioned.');
        setIsLoading(false);
      } else {
        setIsSuccess(true);
        setTimeout(() => onLogin(userFound), 800);
      }
    } else {
      setError('Authentication Failed: Verify credentials or contact administrator.');
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fcfdfd] flex items-center justify-center p-4 sm:p-6 relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-full opacity-5 pointer-events-none">
        <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-emerald-600 rounded-full blur-[180px]" />
        <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-amber-600 rounded-full blur-[180px]" />
      </div>

      <div className="w-full max-w-lg relative z-10">
        <div className="bg-white rounded-[2rem] sm:rounded-[3.5rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] overflow-hidden border border-gray-100">
          <div className="p-8 sm:p-12 md:p-16">
            <div className="flex flex-col items-center mb-8 sm:mb-12 text-center">
              <div className="mb-6 sm:mb-10 transform transition-transform duration-700 min-h-[140px] sm:min-h-[180px] flex items-center justify-center w-full">
                 <img 
                   src={LOCAL_LOGO} 
                   alt="RPME Limited Logo" 
                   className="h-32 sm:h-44 md:h-52 w-auto object-contain"
                   onError={(e) => {
                     const target = e.currentTarget;
                     if (target.src.includes('logo.png')) {
                       target.src = GITHUB_LOGO;
                     } else {
                       target.onerror = null;
                       target.src = "https://placehold.co/600x400/064e3b/ffffff?text=RPME+LIMITED";
                     }
                   }}
                 />
              </div>
              <div className="space-y-1">
                <h1 className="text-xs sm:text-sm font-black text-emerald-900 tracking-[0.3em] sm:tracking-[0.4em] uppercase">SanctionGuard Portal</h1>
                <p className="text-[9px] sm:text-[10px] text-gray-400 font-bold uppercase tracking-widest">Enterprise Compliance Platform</p>
                <div className="mt-4 flex flex-col items-center gap-2">
                   <div className="inline-flex items-center gap-1.5 px-4 py-1.5 bg-emerald-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg shadow-emerald-900/20 border border-emerald-500 animate-in fade-in zoom-in duration-500">
                      <Zap size={12} className="animate-pulse" /> Final Build: v1.4.5
                   </div>
                   <div className="inline-flex items-center gap-1.5 text-[8px] text-emerald-500 font-bold uppercase tracking-[0.2em]">
                      <Activity size={10} className="animate-ping" /> Project Synchronization Verified
                   </div>
