      <aside className={`fixed inset-y-0 left-0 z-[70] w-72 bg-emerald-950 text-white flex flex-col transform transition-transform duration-500 ease-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 md:static md:inset-auto md:h-full flex-shrink-0 shadow-2xl`}>
