              <div className="absolute -top-2 -right-2 bg-emerald-600 text-white text-[7px] font-black px-1.5 py-0.5 rounded-full shadow-lg border border-white/20">v1.4.5</div>
            </div>
            <div className="text-center">
              <h1 className="text-sm font-black tracking-[0.25em] uppercase text-emerald-100">SanctionGuard</h1>
              <p className="text-[8px] text-amber-500 uppercase tracking-widest font-black mt-1">Audit • Tax • Consulting</p>
            </div>
          </Link>
        </div>

        <nav className="flex-1 px-4 py-8 space-y-2 overflow-y-auto custom-scrollbar">
          {filteredNavItems.map((item) => (
            <Link key={item.path} to={item.path} className={`flex items-center gap-4 px-6 py-4 rounded-2xl transition-all ${location.pathname === item.path ? 'bg-amber-600 text-white shadow-lg shadow-amber-900/20' : 'text-emerald-100/60 hover:bg-white/5 hover:text-white'}`}>
