                    <h2 className="text-base font-black text-emerald-950 uppercase tracking-tight">
                      {navItems.find(n => n.path === location.pathname)?.label || 'Overview'}
                    </h2>
                    <div className="flex gap-2 mt-0.5 items-center">
                        {isCloudConnected ? (
                            <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[7px] font-black uppercase bg-emerald-50 text-emerald-700 border border-emerald-100">
                                <Wifi size={10} /> Live Registry
