                    <Lock className="absolute left-5 sm:left-6 top-1/2 -translate-y-1/2 text-gray-300" size={16} />
                    <input type={showPassword ? "text" : "password"} required className="w-full bg-gray-50 border-2 border-transparent focus:border-emerald-800 focus:bg-white rounded-xl sm:rounded-2xl py-4 sm:py-5 pl-12 sm:pl-16 pr-12 sm:pr-16 outline-none transition-all font-bold text-gray-700 text-sm" placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)}/>
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-emerald-800 transition-colors">
                      {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>
                  </div>
                </div>

                {!isCloudReady && (
                  <div className="pt-1 sm:pt-2">
                    <button type="button" onClick={() => setShowCloudSetup(!showCloudSetup)} className="text-[9px] sm:text-[10px] font-black text-amber-600 uppercase tracking-widest flex items-center gap-1 hover:underline ml-2">
                      {showCloudSetup ? <ChevronUp size={12}/> : <ChevronDown size={12}/>} Link Master Registry
