import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Users, Globe, FileText, Settings, Menu, X, Wifi, WifiOff, Loader2, LogOut, Shield, Clock, ShieldCheck } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';
import { UserProfile, UserRole } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  cloudError?: string | null;
  isCloudConnected: boolean;
  isConnecting?: boolean;
  onLogout: () => void;
  currentUser: UserProfile;
}

const Layout: React.FC<LayoutProps> = ({ children, isCloudConnected, isConnecting, onLogout, currentUser }) => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [registryStats, setRegistryStats] = useState({ lastSourceUpdate: 'Never' });
  const location = useLocation();

  const LOCAL_LOGO = "/images/logo.png";
  const GITHUB_LOGO = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";

  useEffect(() => { setSidebarOpen(false); }, [location.pathname]);

  // Listen for registry updates to keep header fresh
  useEffect(() => {
    const updateStats = () => {
      const saved = localStorage.getItem('unsg_registry_stats');
      if (saved) setRegistryStats(JSON.parse(saved));
    };
    updateStats();
    window.addEventListener('storage', updateStats);
    const interval = setInterval(updateStats, 5000); // Periodic check for local state changes
    return () => {
      window.removeEventListener('storage', updateStats);
      clearInterval(interval);
    };
  }, []);

  const navItems = [
    { label: 'System Dashboard', path: '/', icon: <LayoutDashboard size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.DATA_ENTRY, UserRole.REPORTING, UserRole.AUDITOR] },
