import React, { useState, useEffect } from 'react';
import { Lock, Mail, AlertCircle, Eye, EyeOff, CheckCircle, RefreshCw, Wifi, WifiOff, ChevronDown, ChevronUp, ShieldCheck, Zap, Server, Activity } from 'lucide-react';
import { UserProfile, UserRole, AccountStatus, AppSettings } from '../types';
import { fetchCloudUsers, initSupabase, checkConnection } from '../services/cloudDb';

interface LoginProps {
  onLogin: (user: UserProfile) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [supabaseKey, setSupabaseKey] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showCloudSetup, setShowCloudSetup] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isCloudReady, setIsCloudReady] = useState(false);

  const LOCAL_LOGO = "/images/logo.png";
  const GITHUB_LOGO = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";

  useEffect(() => {
    const stored = localStorage.getItem('unsg_settings');
    if (stored) {
      try {
        const settings: AppSettings = JSON.parse(stored);
        if (settings.supabaseUrl && settings.supabaseKey) {
          initSupabase(settings);
          checkConnection().then(connected => setIsCloudReady(connected));
        }
      } catch (e) {
        console.error("Cloud restore failed", e);
      }
    }
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPassword = password.trim();

    // System Admin Root Override
    if (normalizedEmail === 'aqandeel@gmail.com' && normalizedPassword === 'Rodl@2026') {
      setIsSuccess(true);
      setTimeout(() => {
        onLogin({
          id: 'SYS-ADMIN-ROOT',
          email: 'aqandeel@gmail.com',
          full_name: 'RPME System Admin',
          role: UserRole.ADMIN, 
          is_system_admin: true, 
          status: AccountStatus.ACTIVE,
          must_change_password: false,
          password_expiry: '',
          created_at: new Date().toISOString()
        });
      }, 800);
      return;
    }

    if (!isCloudReady && supabaseKey) {
      const tempSettings: AppSettings = {
        autoSync: true,
        syncIntervalMinutes: 1440,
        sourceUrl: '',
        lastSync: 'Never',
        nextSync: '',
        supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co',
        supabaseKey: supabaseKey
      };
      const initialized = initSupabase(tempSettings);
      const connected = initialized ? await checkConnection() : false;
      if (!connected) {
        setError('Handshake Error: Invalid Registry Key or Supabase Offline.');
        setIsLoading(false);
        return;
      }
      localStorage.setItem('unsg_settings', JSON.stringify(tempSettings));
      setIsCloudReady(true);
    }

    let userFound: any = null;
    try {
      const cloudUsers = await fetchCloudUsers();
      if (cloudUsers) {
        userFound = cloudUsers.find((u: any) => u.email.toLowerCase().trim() === normalizedEmail && u.password_hash_mock === normalizedPassword);
        if (userFound) {
          userFound = { ...userFound, role: userFound.role_id, password: userFound.password_hash_mock };
          const stored = JSON.parse(localStorage.getItem('unsg_users') || '[]');
          localStorage.setItem('unsg_users', JSON.stringify([...stored.filter((u:any) => u.email !== normalizedEmail), userFound]));
        }
      }
    } catch (err) { console.warn("Registry fallback triggered."); }

    if (!userFound) {
      const stored = JSON.parse(localStorage.getItem('unsg_users') || '[]');
      userFound = stored.find((u: any) => u.email.toLowerCase().trim() === normalizedEmail && (u.password || u.password_hash_mock) === normalizedPassword);
    }

    if (userFound) {
      if (userFound.status === AccountStatus.DISABLED) {
        setError('Identity Status: This account has been decommissioned.');
        setIsLoading(false);
      } else {
        setIsSuccess(true);
        setTimeout(() => onLogin(userFound), 800);
      }
    } else {
      setError('Authentication Failed: Verify credentials or check Cloud Connection.');
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fcfdfd] flex items-center justify-center p-4 sm:p-6 relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-full opacity-5 pointer-events-none">
        <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-emerald-600 rounded-full blur-[180px]" />
        <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-amber-600 rounded-full blur-[180px]" />
      </div>

      <div className="w-full max-w-lg relative z-10">
        <div className="bg-white rounded-[2rem] sm:rounded-[3.5rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] overflow-hidden border border-gray-100">
          <div className="p-8 sm:p-12 md:p-16">
            <div className="flex flex-col items-center mb-8 sm:mb-12 text-center">
              <div className="mb-6 sm:mb-10 transform transition-transform duration-700 min-h-[140px] sm:min-h-[180px] flex items-center justify-center w-full">
                 <img 
                   src={LOCAL_LOGO} 
                   alt="RPME Limited Logo" 
                   className="h-32 sm:h-44 md:h-52 w-auto object-contain"
                   onError={(e) => {
                     const target = e.currentTarget;
                     if (target.src.includes('logo.png')) {
                       target.src = GITHUB_LOGO;
                     } else {
                       target.onerror = null;
                       target.src = "https://placehold.co/600x400/064e3b/ffffff?text=RPME+LIMITED";
                     }
                   }}
                 />
              </div>
              <div className="space-y-1">
                <h1 className="text-xs sm:text-sm font-black text-emerald-900 tracking-[0.3em] sm:tracking-[0.4em] uppercase">SanctionGuard Portal</h1>
                <p className="text-[9px] sm:text-[10px] text-gray-400 font-bold uppercase tracking-widest">Enterprise Compliance Platform</p>
                <div className="mt-4 flex flex-col items-center gap-2">
                   <div className="inline-flex items-center gap-1.5 px-4 py-1.5 bg-emerald-600 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg shadow-emerald-900/20 border border-emerald-500 animate-in fade-in zoom-in duration-500">
                      <Zap size={12} className="animate-pulse" /> Final Sync: v1.4.7
                   </div>
                   <div className="inline-flex items-center gap-1.5 text-[8px] text-emerald-500 font-bold uppercase tracking-[0.2em]">
                      <Activity size={10} className="animate-ping" /> Global Synchronization Active
                   </div>
                </div>
              </div>
              <div className={`mt-8 flex items-center gap-2 px-4 py-1.5 sm:py-2 rounded-full text-[8px] sm:text-[9px] font-black uppercase border tracking-widest ${isCloudReady ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-amber-50 text-amber-700 border-amber-100'}`}>
                 {isCloudReady ? <><Wifi size={10}/> Global Cloud Connected</> : <><WifiOff size={10}/> Local Offline Node</>}
              </div>
            </div>

            {error && (
              <div className="mb-6 sm:mb-8 p-4 sm:p-5 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-4 text-red-600 text-[10px] sm:text-[11px] font-bold animate-in fade-in slide-in-from-top-2">
                <AlertCircle size={18} className="shrink-0 mt-0.5" />
                <p>{error}</p>
              </div>
            )}

            {isSuccess ? (
              <div className="flex flex-col items-center justify-center py-8 sm:py-12 animate-in zoom-in-95 duration-300">
                <div className="h-20 w-20 sm:h-24 sm:w-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-emerald-50">
                  <CheckCircle size={40} className="sm:size-[48px]" />
                </div>
                <h3 className="text-lg sm:text-2xl font-black text-emerald-900 uppercase tracking-widest text-center">Access Authorized</h3>
              </div>
            ) : (
              <form onSubmit={handleLogin} className="space-y-4 sm:space-y-6">
                <div className="space-y-1.5 sm:space-y-2">
                  <label className="text-[9px] sm:text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Compliance Identity</label>
                  <div className="relative">
                    <Mail className="absolute left-5 sm:left-6 top-1/2 -translate-y-1/2 text-gray-300" size={16} />
                    <input type="email" required className="w-full bg-gray-50 border-2 border-transparent focus:border-emerald-800 focus:bg-white rounded-xl sm:rounded-2xl py-4 sm:py-5 pl-12 sm:pl-16 pr-6 outline-none transition-all font-bold text-gray-700 text-sm" placeholder="user@rodlme.com" value={email} onChange={(e) => setEmail(e.target.value)}/>
                  </div>
                </div>
                <div className="space-y-1.5 sm:space-y-2">
                  <label className="text-[9px] sm:text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Secure Keyphrase</label>
                  <div className="relative">
                    <Lock className="absolute left-5 sm:left-6 top-1/2 -translate-y-1/2 text-gray-300" size={16} />
                    <input type={showPassword ? "text" : "password"} required className="w-full bg-gray-50 border-2 border-transparent focus:border-emerald-800 focus:bg-white rounded-xl sm:rounded-2xl py-4 sm:py-5 pl-12 sm:pl-16 pr-12 sm:pr-16 outline-none transition-all font-bold text-gray-700 text-sm" placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)}/>
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-emerald-800 transition-colors">
                      {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>
                  </div>
                </div>

                {!isCloudReady && (
                  <div className="pt-1 sm:pt-2">
                    <button type="button" onClick={() => setShowCloudSetup(!showCloudSetup)} className="text-[9px] sm:text-[10px] font-black text-amber-600 uppercase tracking-widest flex items-center gap-1 hover:underline ml-2">
                      {showCloudSetup ? <ChevronUp size={12}/> : <ChevronDown size={12}/>} Link Master Registry
                    </button>
                    {showCloudSetup && (
                      <div className="mt-4 p-4 sm:p-5 bg-amber-50 border border-amber-100 rounded-2xl space-y-4 animate-in slide-in-from-top-2">
                        <input type="password" className="w-full bg-white border border-amber-100 rounded-xl py-4 px-5 text-xs font-bold outline-none focus:border-amber-600" placeholder="Paste Registry Key" value={supabaseKey} onChange={(e) => setSupabaseKey(e.target.value)}/>
                        <p className="text-[8px] text-amber-800 font-bold uppercase tracking-widest px-2">Key required to exit Offline Mode</p>
                      </div>
                    )}
                  </div>
                )}

                <button type="submit" disabled={isLoading} className="w-full bg-emerald-900 hover:bg-emerald-950 text-white font-black py-5 sm:py-6 rounded-xl sm:rounded-2xl shadow-xl transition-all flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50 text-xs sm:text-sm">
                  {isLoading ? <RefreshCw className="animate-spin" size={18} /> : 'Secure Logon'}
                </button>
              </form>
            )}
          </div>
          <div className="bg-gray-50 p-6 sm:p-8 text-center border-t border-gray-100">
             <p className="text-[9px] sm:text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] sm:tracking-[0.3em]">Official Audit Portal - RPME Limited</p>
          </div>
        </div>
