import { createClient } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel, UserProfile, SanctionEntry } from '../types';

let supabase: any = null;

export const initSupabase = (settings: AppSettings) => {
  if (settings.supabaseUrl && settings.supabaseKey) {
    try {
      supabase = createClient(settings.supabaseUrl, settings.supabaseKey);
      return true;
    } catch (e) {
      console.error("[CloudDb] Initialization Failed:", e);
      return false;
    }
  }
  return false;
};

export const checkConnection = async () => {
  if (!supabase) {
    console.warn("[CloudDb] checkConnection called but supabase is null.");
    return false;
  }
  try {
    // We query the profiles table. If this fails, the table might not be created or keys are wrong.
    const { data, error } = await supabase.from('profiles').select('email').limit(1);

    if (error) {
      console.error("[CloudDb] Connection Failed:", error.message, error.code);
      if (error.code === '42P01') {
        console.warn("[CloudDb] Table 'profiles' does not exist. Please run the SQL Schema in Admin Panel.");
      }
      return false;
    }

    console.log("[CloudDb] Connection Verified.");
    return true;
  } catch (err) {
    console.error("[CloudDb] Unexpected Connection Error:", err);
    return false;
  }
};

// --- CLIENT OPERATIONS ---

export const fetchCloudClients = async (): Promise<Client[] | null> => {
  if (!supabase) return null;
  const { data, error } = await supabase.from('clients').select('*').order('created_at', { ascending: false });
  if (error) throw error;
  return data;
};

export const upsertCloudClient = async (client: Client) => {
  if (!supabase) return;
  const { error } = await supabase.from('clients').upsert([client], { onConflict: 'id' });
  if (error) throw error;
};

export const deleteCloudClient = async (id: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('clients').delete().eq('id', id);
  if (error) throw error;
};

// --- SANCTIONS REGISTRY OPERATIONS ---

export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabase) return 0;
  const { count, error } = await supabase
    .from('sanctions')
    .select('*', { count: 'exact', head: true });
  if (error) return 0;
  return count || 0;
};

export const fetchSanctionsBatch = async (offset: number, limit: number): Promise<SanctionEntry[]> => {
  if (!supabase) return [];
  const { data, error } = await supabase
    .from('sanctions')
    .select('*')
    .range(offset, offset + limit - 1);
  if (error) throw error;
  return data || [];
};

export const fetchCloudSanctions = async (): Promise<SanctionEntry[] | null> => {
  if (!supabase) return null;
  try {
    const { data, error } = await supabase.from('sanctions').select('*');
    if (error) throw error;
    return data;
  } catch (err) {
    console.error("Cloud Registry Fetch Error:", err);
    return null;
  }
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (percent: number) => void) => {
  if (!supabase) throw new Error("Cloud connection not initialized.");

  const CHUNK_SIZE = 500;
  const total = sanctions.length;

  for (let i = 0; i < total; i += CHUNK_SIZE) {
    const chunk = sanctions.slice(i, i + CHUNK_SIZE);

    const dbEntries = chunk.map(s => ({
      dataId: s.dataId,
      source: s.source,
      firstName: s.firstName || '',
      secondName: s.secondName || '',
      thirdName: s.thirdName || '',
      lastName: s.lastName || '',
      unListType: s.unListType || '',
      referenceNumber: s.referenceNumber || '',
      listedOn: s.listedOn || '',
      comments: s.comments || '',
      nationality: s.nationality || '',
      dateOfBirth: s.dateOfBirth || '',
      aliases: s.aliases || [],
      type: s.type || ''
    }));

    const { error } = await supabase
      .from('sanctions')
      .upsert(dbEntries, { onConflict: 'dataId' });

    if (error) {
      throw new Error(`Cloud Storage Error at record ${i}: ${error.message}`);
    }

    if (onProgress) {
      onProgress(Math.round(((i + chunk.length) / total) * 100));
    }
  }
};

// --- USER PROFILE OPERATIONS ---

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabase) return null;
  try {
    const { data, error } = await supabase.from('profiles').select('*');
    if (error) return null;
    return data;
  } catch (err) {
    return null;
  }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabase) return;

  const dbProfile = {
    id: user.id,
    email: user.email.toLowerCase().trim(),
    full_name: user.full_name,
    role_id: user.role,
    status: user.status || 'Active',
    is_system_admin: user.is_system_admin === true,
    must_change_password: user.must_change_password,
    password_expiry: user.password_expiry,
    password_hash_mock: user.password,
    created_at: user.created_at || new Date().toISOString()
  };

  const { error } = await supabase.from('profiles').upsert([dbProfile], { onConflict: 'email' });
  if (error) throw new Error(error.message);
};

export const deleteCloudUser = async (email: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('profiles').delete().eq('email', email.toLowerCase().trim());
  if (error) throw new Error(error.message);
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabase) return null;
  return supabase.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabase && channel) await supabase.removeChannel(channel);
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsRegistry from './components/SanctionsRegistry';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Client, SanctionEntry, RiskLevel, AppSettings, UserRole, UserProfile, AccountStatus } from './types';
import { screenClient } from './services/screeningEngine';
import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  fetchCloudUsers, 
  upsertCloudUser
} from './services/cloudDb';
import { OFFICIAL_UN_XML_URL } from './services/unSanctionsService';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co'
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('unsg_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [registryStats, setRegistryStats] = useState(() => {
    const saved = localStorage.getItem('unsg_registry_stats');
    return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    // Check URL parameters first for auto-config magic link
    const urlParams = new URLSearchParams(window.location.search);
    const supaUrl = urlParams.get('supaUrl');
    const supaKey = urlParams.get('supaKey');

    if (supaUrl && supaKey) {
      const magicSettings = { ...DEFAULT_SETTINGS, supabaseUrl: supaUrl, supabaseKey: supaKey };
      localStorage.setItem('unsg_settings', JSON.stringify(magicSettings));
      return magicSettings;
    }

    const stored = localStorage.getItem('unsg_settings');
    let merged = stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
    if (!merged.supabaseUrl) merged.supabaseUrl = DEFAULT_SETTINGS.supabaseUrl;
    return merged;
  });

  const [connectionStatus, setConnectionStatus] = useState<'LOCAL' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('LOCAL');

  const subscriptionRef = useRef<any>(null);

  const syncIdentities = useCallback(async () => {
    const cloudUsers = await fetchCloudUsers();
    const storedUsersStr = localStorage.getItem('unsg_users');
    let localUsers = storedUsersStr ? JSON.parse(storedUsersStr) : [];

    if (cloudUsers) {
      const merged = [...localUsers];
      cloudUsers.forEach((cu: any) => {
        const localIdx = merged.findIndex((lu: any) => lu.email.toLowerCase() === cu.email.toLowerCase());
        const transformedUser = {
           ...cu,
           role: cu.role_id,
           password: cu.password_hash_mock
        };
        if (localIdx >= 0) merged[localIdx] = transformedUser;
        else merged.push(transformedUser);
      });
      localUsers = merged;
    }
    localStorage.setItem('unsg_users', JSON.stringify(localUsers));
  }, []);

  const handleLogin = (user: UserProfile) => {
    setCurrentUser(user);
    localStorage.setItem('unsg_session', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('unsg_session');
  };

  const refreshClients = useCallback(async (isConnected: boolean) => {
    if (isConnected) {
      try {
        const cloudClients = await fetchCloudClients();
        if (cloudClients) {
          setClients(cloudClients);
        }
      } catch (err: any) {
        console.error("Connection error loading clients.");
      }
    } else {
      const stored = localStorage.getItem('unsg_clients');
      if (stored) setClients(JSON.parse(stored));
    }
  }, []);

  const performFuzzyScreening = useCallback(async (currentSanctions: SanctionEntry[], currentClients: Client[]) => {
    if (currentSanctions.length === 0 || currentClients.length === 0) return;

    const screenedClients = currentClients.map(client => {
      const match = screenClient(client, currentSanctions);
      return {
        ...client,
        riskLevel: match ? match.riskLevel : RiskLevel.NONE,
        lastScreenedAt: new Date().toISOString(),
        matches: match ? [match.sanctionId] : []
      };
    });

    setClients(screenedClients);
    if (connectionStatus === 'CONNECTED') {
      for (const updatedClient of screenedClients) {
         const original = currentClients.find(c => c.id === updatedClient.id);
         if (original?.riskLevel !== updatedClient.riskLevel) {
           await upsertCloudClient(updatedClient);
         }
      }
    }
  }, [connectionStatus]);

  const handleRegistrySync = (newSanctions: SanctionEntry[], stats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string }) => {
    setSanctions(newSanctions);
    if (stats) {
      setRegistryStats(stats);
      localStorage.setItem('unsg_registry_stats', JSON.stringify(stats));
    }
    performFuzzyScreening(newSanctions, clients);
  };

  useEffect(() => {
    if (!currentUser) return;
    const connectToCloud = async () => {
      if (!settings.supabaseUrl || !settings.supabaseKey) {
        setConnectionStatus('LOCAL');
        refreshClients(false);
        return;
      }
      setConnectionStatus('CONNECTING');
      console.log("[App] Attempting Cloud Handshake...");
      const initialized = initSupabase(settings);
      if (initialized) {
        const healthy = await checkConnection();
        if (healthy) {
          setConnectionStatus('CONNECTED');
          await refreshClients(true);
          await syncIdentities();
          if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
          subscriptionRef.current = subscribeToClients(() => refreshClients(true));
        } else {
          setConnectionStatus('ERROR');
          refreshClients(false);
        }
      }
    };
    connectToCloud();
    return () => { if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current); };
  }, [settings, refreshClients, currentUser, syncIdentities]);

  if (!currentUser) return <Login onLogin={handleLogin} />;
  if (currentUser.must_change_password) return <PasswordUpdate user={currentUser} onUpdate={() => {}} />;

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={handleLogout}
        currentUser={currentUser}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctions.length} registryStats={registryStats} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              onAddClient={async (newClient) => {
                const match = screenClient(newClient, sanctions);
                const clientWithRisk = { ...newClient, riskLevel: match ? match.riskLevel : RiskLevel.NONE };
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(clientWithRisk);
                else setClients(prev => [clientWithRisk, ...prev]);
              }} 
              onUpdateClient={async (updated) => {
                const match = screenClient(updated, sanctions);
                const clientWithRisk = { ...updated, riskLevel: match ? match.riskLevel : RiskLevel.NONE };
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(clientWithRisk);
                setClients(prev => prev.map(c => c.id === updated.id ? clientWithRisk : c));
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                setClients(prev => prev.filter(c => c.id !== id));
              }}
              onRefresh={() => refreshClients(connectionStatus === 'CONNECTED')} 
              currentUserRole={currentUser.role}
              currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsRegistry 
              onSyncComplete={handleRegistrySync}
              isCloudConnected={connectionStatus === 'CONNECTED'}
              initialStats={registryStats}
            />} />
          <Route path="/admin" element={
            currentUser.is_system_admin === true ? (
              <AdminPanel 
                logs={[]} 
                settings={settings} 
                onUpdateSettings={setSettings} 
                currentUserId={currentUser.id}
                currentUser={currentUser}
              />
            ) : <Navigate to="/" replace />
          } />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

