const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, onSwitchUser, currentUserId, currentUser }) => {
  const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
