  const GITHUB_LOGO = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";

  useEffect(() => {
    setIsInternalCloudReady(isCloudConnected);
  }, [isCloudConnected]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPassword = password.trim();

    // 1. System Admin Root Override
    if (normalizedEmail === 'aqandeel@gmail.com' && normalizedPassword === 'Rodl@2026') {
      setIsSuccess(true);
      setTimeout(() => {
        onLogin({
          id: 'SYS-ADMIN-ROOT',
          email: 'aqandeel@gmail.com',
          full_name: 'RPME System Admin',
          role: UserRole.ADMIN, 
          is_system_admin: true, 
          status: AccountStatus.ACTIVE,
          must_change_password: false,
          password_expiry: '',
          created_at: new Date().toISOString()
        });
      }, 800);
      return;
    }

    // 2. Inline Provisioning (If offline and user provides key)
    if (!isInternalCloudReady && supabaseKey) {
      const tempSettings: AppSettings = {
        autoSync: true,
        syncIntervalMinutes: 1440,
        sourceUrl: '',
        lastSync: 'Never',
        nextSync: '',
        supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co',
        supabaseKey: supabaseKey
      };
      const initialized = initSupabase(tempSettings);
      const connected = initialized ? await checkConnection() : false;
      if (!connected) {
        setError('Handshake Error: Access Key invalid for this registry.');
        setIsLoading(false);
        return;
      }
      onProvision(tempSettings);
      setIsInternalCloudReady(true);
    }

    if (!isInternalCloudReady) {
      setError('Connection Required: Domain must be linked to Master Registry before authentication.');
      setIsLoading(false);
      setShowCloudSetup(true);
      return;
    }

    // 3. Authenticate
    let userFound: any = null;
    try {
