                   onError={(e) => {
                     const target = e.currentTarget;
                     if (target.src.includes('logo.png')) { target.src = GITHUB_LOGO; } 
                     else { target.src = "https://placehold.co/600x400/064e3b/ffffff?text=RPME+LIMITED"; }
                   }}
                 />
              </div>
              <div className="space-y-1">
                <h1 className="text-xs sm:text-sm font-black text-emerald-900 tracking-[0.3em] sm:tracking-[0.4em] uppercase">SanctionGuard Portal</h1>
                <p className="text-[9px] sm:text-[10px] text-gray-400 font-bold uppercase tracking-widest">v1.6.0 Enterprise Node</p>
                <div className="mt-4 flex flex-col items-center gap-2">
                   <div className={`inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg border animate-in fade-in zoom-in duration-500 ${isInternalCloudReady ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-red-600 text-white border-red-500'}`}>
                      {isInternalCloudReady ? <Zap size={12} className="animate-pulse" /> : <WifiOff size={12} />}
                      {isInternalCloudReady ? 'Live Registry Active' : 'Offline Node Detected'}
                   </div>
                </div>
              </div>
            </div>

            {error && (
              <div className="mb-6 sm:mb-8 p-4 sm:p-5 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-4 text-red-600 text-[10px] sm:text-[11px] font-bold animate-in fade-in slide-in-from-top-2">
                <AlertCircle size={18} className="shrink-0 mt-0.5" />
                <p>{error}</p>
              </div>
            )}

            {isSuccess ? (
              <div className="flex flex-col items-center justify-center py-8 sm:py-12 animate-in zoom-in-95 duration-300">
                <div className="h-20 w-20 sm:h-24 sm:w-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-emerald-50">
                  <CheckCircle size={40} className="sm:size-[48px]" />
                </div>
                <h3 className="text-lg sm:text-2xl font-black text-emerald-900 uppercase tracking-widest text-center">Identity Verified</h3>
              </div>
            ) : (
              <form onSubmit={handleLogin} className="space-y-4 sm:space-y-6">
                {!isInternalCloudReady && (
