                <h1 className="text-xs sm:text-sm font-black text-emerald-900 tracking-[0.3em] uppercase">SanctionGuard Portal</h1>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">v1.8.0 Enterprise Node</p>
                <div className="mt-4 flex flex-col items-center gap-2">
                   <div className={`inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg border ${isCloudConnected ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-red-600 text-white border-red-500'}`}>
