                <div className="h-20 w-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-6 shadow-xl">
                  <CheckCircle size={40} />
                </div>
                <h3 className="text-lg font-black text-emerald-900 uppercase tracking-widest text-center">Node Configured</h3>
