import React, { useState, useEffect } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus } from '../types';
import { Save, Cloud, Terminal, Check, Copy, AlertTriangle, ShieldCheck, History, Users, Lock, UserCircle, ShieldAlert, Plus, Power, Key, X, Mail, UserPlus, CheckCircle2, Trash2, UserMinus, AlertCircle, RefreshCw, Link2, Share2, Shield, Zap, Globe } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  onSwitchUser?: (role: UserRole, id: string) => void;
  currentUserId?: string;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, onSwitchUser, currentUserId, currentUser }) => {
  const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
  const [activeTab, setActiveTab] = useState<'config' | 'rbac' | 'logs' | 'users'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);
  const [copiedSql, setCopiedSql] = useState(false);

  // v1.8.5: Auto-detect domain if none exists
  const [targetDomain, setTargetDomain] = useState(window.location.origin + window.location.pathname);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  useEffect(() => { setLocalSettings(settings); }, [settings]);

  const SQL_SCHEMA = `-- 1. Identities Table
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT UNIQUE NOT NULL,
  full_name TEXT,
  role_id TEXT,
  status TEXT DEFAULT 'Active',
  is_system_admin BOOLEAN DEFAULT false,
  must_change_password BOOLEAN DEFAULT true,
  password_expiry TIMESTAMPTZ,
  password_hash_mock TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- (Other SQL tables suppressed for brevity)
`;

  const copySql = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopiedSql(true);
    setTimeout(() => setCopiedSql(false), 2000);
  };

  const copyMasterInstallLink = () => {
    let cleanBase = targetDomain.trim();
    if (!cleanBase.startsWith('http')) cleanBase = 'https://' + cleanBase;

    // Ensure base doesn't have a trailing slash for consistent param joining
    if (cleanBase.endsWith('/')) cleanBase = cleanBase.slice(0, -1);

    const params = new URLSearchParams();
    if (settings.supabaseUrl) params.set('supaUrl', settings.supabaseUrl);
    if (settings.supabaseKey) params.set('supaKey', settings.supabaseKey);

    // For HashRouter links, params should go after the #/login but usually browsers 
    // handle query params before or after hash. We put them after for better compatibility.
    const link = `${cleanBase}/#/login?${params.toString()}`;

    navigator.clipboard.writeText(link);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2000);
  };

  const saveUsersToStorage = async (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    if (!settings.supabaseUrl || !settings.supabaseKey) return;
    setIsSyncing(true);
    try {
      if (isDelete) { await deleteCloudUser(user.email); } else { await upsertCloudUser(user); }
    } catch (e: any) { console.error("Cloud Engine Error:", e.message); } finally { setIsSyncing(false); }
  };

  const toggleUserStatus = async (email: string) => {
    const updated = systemUsers.map(u => {
      if (u.email === email) {
