import { createClient } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel, UserProfile, SanctionEntry } from '../types';

let supabaseClient: any = null;

export const initSupabase = (settings: AppSettings) => {
  if (!settings.supabaseUrl || !settings.supabaseKey) {
    supabaseClient = null;
    return false;
  }

  try {
    supabaseClient = createClient(settings.supabaseUrl, settings.supabaseKey, {
      auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false }
    });
    return true;
  } catch (e) {
    console.error("[CloudDb] Init Exception:", e);
    return false;
  }
};

export const checkConnection = async () => {
  if (!supabaseClient) return false;
  try {
    const { error } = await supabaseClient.from('profiles').select('email').limit(1);
    return !error;
  } catch (err) {
    return false;
  }
};

// Global Lock Services
export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return { is_syncing: false, last_sync: 'Never' };
  try {
    const { data, error } = await supabaseClient
      .from('system_metadata')
      .select('*')
      .eq('key', 'global_sync_lock')
      .single();

    if (error && error.code === 'PGRST116') {
      // Row doesn't exist, create it
      await supabaseClient.from('system_metadata').insert([{ key: 'global_sync_lock', value: { is_syncing: false, last_sync: 'Never' } }]);
      return { is_syncing: false, last_sync: 'Never' };
    }
    return data?.value || { is_syncing: false, last_sync: 'Never' };
  } catch (e) {
    return { is_syncing: false, last_sync: 'Never' };
  }
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync?: string) => {
  if (!supabaseClient) return;
  const status = { is_syncing: isSyncing, last_sync: lastSync || 'In Progress...' };
  await supabaseClient
    .from('system_metadata')
    .upsert([{ key: 'global_sync_lock', value: status }], { onConflict: 'key' });
};

export const subscribeToGlobalSync = (onUpdate: (status: any) => void) => {
  if (!supabaseClient) return null;
  return supabaseClient
    .channel('system-metadata-changes')
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'system_metadata', filter: 'key=eq.global_sync_lock' }, 
      (payload: any) => onUpdate(payload.new.value))
    .subscribe();
};

export const fetchCloudClients = async (): Promise<Client[] | null> => {
  if (!supabaseClient) return null;
  const { data, error } = await supabaseClient.from('clients').select('*').order('created_at', { ascending: false });
  if (error) throw error;
  return data;
};

export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').upsert([client], { onConflict: 'id' });
  if (error) throw error;
};

export const deleteCloudClient = async (id: string) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').delete().eq('id', id);
  if (error) throw error;
};

export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
  return error ? 0 : (count || 0);
};

export const fetchSanctionsBatch = async (offset: number, limit: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  const { data, error } = await supabaseClient.from('sanctions').select('*').range(offset, offset + limit - 1);
  if (error) throw error;
  return data || [];
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (progress: number) => void) => {
  if (!supabaseClient) return;
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize);
    const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'dataId' });
    if (error) throw error;
    if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
  }
};

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabaseClient) return null;
  const { data, error } = await supabaseClient.from('profiles').select('*');
  return error ? null : data;
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) return;
  const dbProfile = {
    id: user.id,
    email: user.email.toLowerCase().trim(),
    full_name: user.full_name,
    role_id: user.role,
    status: user.status || 'Active',
    is_system_admin: user.is_system_admin === true,
    must_change_password: user.must_change_password,
    password_expiry: user.password_expiry,
    password_hash_mock: user.password,
    created_at: user.created_at || new Date().toISOString()
  };
  const { error } = await supabaseClient.from('profiles').upsert([dbProfile], { onConflict: 'email' });
  if (error) throw new Error(error.message);
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('profiles').delete().eq('email', email.toLowerCase().trim());
  if (error) throw new Error(error.message);
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabaseClient && channel) await supabaseClient.removeChannel(channel);
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry } from '../types';
import { RefreshCw, Search, ChevronLeft, ChevronRight, Database, Activity, AlertCircle, Loader2, Play, Pause, Square, Trash2, Clock, ShieldCheck, CloudDownload, Cpu, CheckCircle, Zap } from 'lucide-react';
import { fetchSanctionsBatch, fetchSanctionsTotalCount, upsertCloudSanctions, setGlobalSyncLock, fetchGlobalSyncStatus, subscribeToGlobalSync } from '../services/cloudDb';
import { fetchFromUrl, OFFICIAL_UN_XML_URL } from '../services/unSanctionsService';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[], stats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string }) => void;
  isCloudConnected: boolean;
  initialStats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string };
}

type ProcessStatus = 'IDLE' | 'FETCHING' | 'TESTING' | 'PAUSED' | 'COMPLETED' | 'ERROR' | 'STOPPED' | 'UPLOADING';

const ITEMS_PER_PAGE = 15;
const BATCH_SIZE = 500;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, initialStats }) => {
  const [sanctions, setSanctions] = useState<(SanctionEntry & { isTestData?: boolean })[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [currentOffset, setCurrentOffset] = useState(0);
  const [targetRecords, setTargetRecords] = useState(0);
  const [batchesFetched, setBatchesFetched] = useState(0);
  const [batchesTested, setBatchesTested] = useState(0);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [lastActionLog, setLastActionLog] = useState<string>('System initialized.');

  const [lastFetchTime, setLastFetchTime] = useState<string>(initialStats?.lastFetch || 'Never');
  const [lastTestTime, setLastTestTime] = useState<string>(initialStats?.lastTest || 'Never');
  const [lastSourceUpdate, setLastSourceUpdate] = useState<string>(initialStats?.lastSourceUpdate || 'Never');

  const isRunningRef = useRef(false);
  const isPausedRef = useRef(false);
  const syncChannelRef = useRef<any>(null);

  const logAction = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLastActionLog(`[${timestamp}] ${msg}`);
  };

  const refreshDbStats = useCallback(async () => {
    if (isCloudConnected) {
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);
      return count;
    }
    return 0;
  }, [isCloudConnected]);

  // v1.9.0 Global Sync Handlers
  const handleGlobalStatusUpdate = useCallback((globalValue: any) => {
    setIsGlobalSyncing(globalValue.is_syncing);
    if (globalValue.last_sync && globalValue.last_sync !== 'In Progress...') {
      setLastSourceUpdate(globalValue.last_sync);
      // Automatically refresh if a global sync just finished
      if (!isRunningRef.current && status !== 'UPLOADING') {
        refreshDbStats().then(count => setTargetRecords(count));
        logAction("Registry updated via Distributed Pulse.");
      }
    }
  }, [status, refreshDbStats]);

  useEffect(() => {
    if (isCloudConnected) {
      // 1. Initial Status Check
      fetchGlobalSyncStatus().then(handleGlobalStatusUpdate);
      // 2. Subscribe to Global Changes
      syncChannelRef.current = subscribeToGlobalSync(handleGlobalStatusUpdate);
    }
    return () => { if (syncChannelRef.current) syncChannelRef.current.unsubscribe(); };
  }, [isCloudConnected, handleGlobalStatusUpdate]);

  useEffect(() => {
    refreshDbStats().then(count => { if (targetRecords === 0) setTargetRecords(count); });
  }, [refreshDbStats]);

  const syncFromOfficialSource = async () => {
    if (!isCloudConnected || isGlobalSyncing) return;

    setStatus('UPLOADING');
    setUploadProgress(0);
    setErrorMessage(null);
    logAction("Acquiring Global Mutex Lock...");

    try {
      // Set global lock
      await setGlobalSyncLock(true, 'In Progress...');

      const liveData = await fetchFromUrl(OFFICIAL_UN_XML_URL);
      logAction(`Source retrieved: ${liveData.length} profiles.`);

      await upsertCloudSanctions(liveData, (progress) => setUploadProgress(progress));

      const now = new Date().toLocaleString();

      // Release global lock
      await setGlobalSyncLock(false, now);

      setLastSourceUpdate(now);
      const newTotal = await refreshDbStats();
      setTargetRecords(newTotal);

      logAction("Global Sync Verified. Lock Released.");
      setStatus('COMPLETED');

      handleStart();
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate); // Release lock on error
      const msg = err.message.includes('fetch') ? "CORS Blocked: Access UN XML via Governance manual upload." : err.message;
      setErrorMessage(msg);
      setStatus('ERROR');
      logAction(`Sync Fault: ${msg}`);
    }
  };

  const runAutomationStep = useCallback(async (offset: number) => {
    if (!isRunningRef.current || isPausedRef.current) return;

    try {
      setStatus('FETCHING');
      logAction(`Retrieving batch at index ${offset}...`);
      const batch = await fetchSanctionsBatch(offset, BATCH_SIZE);

      const now = new Date().toLocaleString();
      setLastFetchTime(now);

      if (batch.length === 0) {
        logAction("End of cloud registry.");
        setStatus('COMPLETED');
        isRunningRef.current = false;
        return;
      }

      let updatedList: (SanctionEntry & { isTestData?: boolean })[] = [];
      setSanctions(prev => {
        const merged = [...prev, ...batch];
        updatedList = Array.from(new Set(merged.map(s => s.dataId)))
          .map(id => merged.find(s => s.dataId === id)!);
        return updatedList;
      });
      setBatchesFetched(prev => prev + 1);

      setStatus('TESTING');
      logAction(`Executing automated fuzzy validation...`);
      await new Promise(resolve => setTimeout(resolve, 300));

      const testNow = new Date().toLocaleString();
      setLastTestTime(testNow);

      onSyncComplete(updatedList, { lastFetch: now, lastTest: testNow, lastSourceUpdate });

      setBatchesTested(prev => prev + 1);
      const nextOffset = offset + batch.length;
      setCurrentOffset(nextOffset);

      if (nextOffset >= targetRecords) {
        logAction("Registry coverage complete.");
        setStatus('COMPLETED');
        isRunningRef.current = false;
      } else {
        runAutomationStep(nextOffset);
      }
    } catch (err: any) {
      setErrorMessage(err.message);
      setStatus('ERROR');
      isRunningRef.current = false;
    }
  }, [targetRecords, onSyncComplete, lastSourceUpdate]);

  const handleStart = () => {
    if (!isCloudConnected) return;
    setErrorMessage(null);
    isRunningRef.current = true;
    isPausedRef.current = false;
    runAutomationStep(currentOffset);
  };

  const handlePause = () => { isPausedRef.current = true; setStatus('PAUSED'); logAction("Sequence suspended."); };
  const handleStop = () => { isRunningRef.current = false; isPausedRef.current = false; setStatus('STOPPED'); logAction("Sequence terminated."); };
  const handleReset = () => {
    setSanctions([]); setCurrentOffset(0); setBatchesFetched(0); setBatchesTested(0); setStatus('IDLE'); setErrorMessage(null);
    onSyncComplete([], { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate });
    logAction("Node cache purged.");
  };

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (Array.isArray(s.aliases) && s.aliases.some(a => a.toLowerCase().includes(searchTerm.toLowerCase())))
  );

  const paginatedData = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* 1. SOURCE SYNC PANEL */}
      <div className={`bg-white p-8 rounded-[2.5rem] border shadow-sm flex flex-col xl:flex-row gap-8 relative overflow-hidden transition-colors ${isGlobalSyncing ? 'border-blue-200 bg-blue-50/10' : 'border-gray-100'}`}>
        {isGlobalSyncing && (
           <div className="absolute top-0 left-0 w-full h-1 bg-blue-500 overflow-hidden">
             <div className="w-1/3 h-full bg-blue-200 animate-slide-infinite" />
           </div>
        )}

        <div className="flex-1 space-y-4">
           <div className="flex items-center gap-3">
             <div className={`p-3 rounded-2xl shadow-lg text-white ${isGlobalSyncing ? 'bg-blue-600' : 'bg-emerald-900'}`}>
               {isGlobalSyncing ? <Zap className="animate-pulse" size={24} /> : <CloudDownload size={24} />}
             </div>
             <div>
                <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Source Synchronizer</h2>
                <div className="flex items-center gap-2 mt-1">
                   {isGlobalSyncing ? (
                     <span className="text-[10px] text-blue-600 font-black uppercase tracking-widest flex items-center gap-1.5 bg-blue-100 px-3 py-0.5 rounded-full">
                        <Activity size={10} className="animate-spin" /> Locked: Global Sync in Progress
                     </span>
                   ) : (
                     <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Continuous UN Registry Ingestion</p>
                   )}
                </div>
             </div>
           </div>
           <p className="text-sm text-gray-500 font-medium leading-relaxed max-w-2xl">
             Connects to the official UN Consolidated List to ingest the latest global designations. Updates are committed to your private Cloud Registry for organization-wide screening.
           </p>
           <div className="flex flex-wrap gap-4 pt-2">
              <div className="bg-slate-50 px-6 py-4 rounded-2xl border border-slate-100 flex items-center gap-4">
                 <Clock size={16} className="text-emerald-600" />
                 <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Last Master Sync</p>
                    <p className="text-[10px] font-black text-slate-800 uppercase">{lastSourceUpdate}</p>
                 </div>
              </div>
              <button 
                onClick={syncFromOfficialSource}
                disabled={!isCloudConnected || isGlobalSyncing || status === 'UPLOADING' || isRunningRef.current}
                className={`px-10 py-4 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl disabled:opacity-50 transition-all flex items-center gap-3 ${isGlobalSyncing ? 'bg-slate-400' : 'bg-emerald-800 hover:bg-emerald-950'}`}
              >
                {status === 'UPLOADING' ? <Loader2 size={16} className="animate-spin" /> : <RefreshCw size={16} />}
                {isGlobalSyncing ? 'Global Lock Active' : 'Sync from Source'}
              </button>
           </div>
        </div>
      </div>

      {/* 2. AUTOMATION ENGINE */}
      <div className="bg-slate-950 p-8 rounded-[2.5rem] text-white shadow-2xl border border-slate-800 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none text-emerald-500">
           <Cpu size={180} />
        </div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8">
          <div className="space-y-4 max-w-2xl">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-emerald-500 rounded-lg text-slate-950">
                <Activity size={20} />
              </div>
              <h3 className="text-2xl font-black uppercase tracking-tight">Automation Engine</h3>
              {status !== 'IDLE' && status !== 'UPLOADING' && (
                 <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest ${
                   status === 'FETCHING' ? 'bg-blue-500 animate-pulse' :
                   status === 'TESTING' ? 'bg-amber-500 animate-bounce' :
                   status === 'COMPLETED' ? 'bg-emerald-500' : 'bg-slate-700'
                 }`}>
                   {status}
                 </span>
              )}
            </div>
            <p className="text-slate-400 text-sm font-bold leading-relaxed uppercase tracking-tight">
              Cloud Sequencer: Synchronizes the local screening node with the cloud registry and executes fuzzy match validation.
            </p>
            <div className="flex flex-wrap gap-4 items-center">
              <div className="space-y-1">
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Sync Depth</label>
                <div className="flex items-center gap-2">
                  <input 
                    type="number" 
                    disabled={status !== 'IDLE' && status !== 'STOPPED' && status !== 'COMPLETED'}
                    value={targetRecords} 
                    onChange={e => setTargetRecords(Math.min(totalInDb, parseInt(e.target.value) || 0))}
                    className="bg-slate-900 border border-slate-700 rounded-xl px-4 py-2 text-xs font-black text-emerald-400 outline-none w-32 focus:border-emerald-500"
                  />
                  <span className="text-[10px] text-slate-600 font-bold uppercase">/ {totalInDb.toLocaleString()} Profiles</span>
                </div>
              </div>
              <div className="flex gap-2">
                {status === 'FETCHING' || status === 'TESTING' ? (
                  <button onClick={handlePause} className="p-4 bg-amber-600 rounded-2xl shadow-xl shadow-amber-900/20"><Pause size={20}/></button>
                ) : (
                  <button 
                    onClick={handleStart} 
                    disabled={!isCloudConnected || status === 'COMPLETED' || (currentOffset >= targetRecords && status !== 'IDLE') || status === 'UPLOADING'}
                    className="flex items-center gap-3 px-8 py-4 bg-emerald-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-900/20 disabled:opacity-30"
                  >
                    <Play size={16} /> {status === 'PAUSED' ? 'Resume' : 'Execute Sync'}
                  </button>
                )}
                <button onClick={handleStop} disabled={status === 'IDLE' || status === 'STOPPED' || status === 'COMPLETED'} className="p-4 bg-slate-800 rounded-2xl disabled:opacity-30"><Square size={20} /></button>
                <button onClick={handleReset} className="p-4 bg-red-950/30 text-red-500 border border-red-900/30 rounded-2xl hover:bg-red-500 hover:text-white transition-all"><Trash2 size={20} /></button>
              </div>
            </div>
          </div>
          <div className="w-full lg:w-80 space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-slate-900 p-4 rounded-2xl border border-slate-800 text-center">
                <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Local Buffer</p>
                <p className="text-xl font-black text-white">{batchesFetched}</p>
              </div>
              <div className="bg-slate-900 p-4 rounded-2xl border border-slate-800 text-center">
                <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Verified</p>
                <p className="text-xl font-black text-white">{batchesTested}</p>
              </div>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between text-[10px] font-black uppercase tracking-widest">
                <span className="text-slate-500">Node Sync Coverage</span>
                <span className="text-emerald-500">{targetRecords > 0 ? Math.round((currentOffset / targetRecords) * 100) : 0}%</span>
              </div>
              <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                <div className={`h-full bg-emerald-500 transition-all duration-500`} style={{ width: `${targetRecords > 0 ? Math.min(100, (currentOffset / targetRecords) * 100) : 0}%` }} />
              </div>
            </div>
          </div>
        </div>
        <div className="mt-8 pt-6 border-t border-slate-800 flex flex-col xs:flex-row items-start xs:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className={`w-2 h-2 rounded-full ${isRunningRef.current ? 'bg-emerald-500 animate-pulse' : 'bg-slate-600'}`} />
            <p className="text-[10px] font-bold text-slate-400 font-mono italic">{lastActionLog}</p>
          </div>
          <div className="flex gap-6">
            <div className="flex flex-col items-end">
               <p className="text-[8px] font-black text-slate-600 uppercase tracking-tighter">Vital Refresh</p>
               <p className="text-[10px] font-black text-white uppercase">{lastFetchTime}</p>
            </div>
            <div className="flex flex-col items-end">
               <p className="text-[8px] font-black text-slate-600 uppercase tracking-tighter">Last Screening</p>
               <p className="text-[10px] font-black text-white uppercase">{lastTestTime}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Registry View */}
      <div className="space-y-6">
        <div className="bg-white p-4 rounded-[2rem] shadow-sm border border-gray-100 flex items-center focus-within:ring-2 focus-within:ring-emerald-800 transition-all">
          <div className="relative flex-1">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
            <input type="text" placeholder="Query node identities..." className="w-full pl-16 pr-6 py-5 bg-slate-50/50 border-none rounded-2xl outline-none text-sm font-bold" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>
        </div>
        <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left border-collapse min-w-[1000px]">
              <thead className="bg-slate-50/50 border-b border-slate-100">
                <tr>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Protocol</th>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Identity Profile</th>
                  <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Jurisdiction</th>
                  <th className="px-8 py-6 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Audit ID</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {paginatedData.map((entry) => (
                  <tr key={entry.dataId} className="hover:bg-slate-50/80 transition-colors group">
                    <td className="px-8 py-5">
                       <span className="px-3 py-1.5 rounded-xl text-[8px] font-black uppercase border border-slate-100 text-slate-500">{entry.source}</span>
                    </td>
                    <td className="px-8 py-5 font-black text-emerald-950 text-sm">{entry.firstName} {entry.lastName}</td>
                    <td className="px-8 py-5 font-black text-[9px] text-slate-600 uppercase tracking-widest">{entry.nationality || 'Unspecified'}</td>
                    <td className="px-8 py-5 text-right text-[10px] text-slate-400 font-mono">{entry.referenceNumber}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {filtered.length > 0 && (
            <div className="px-8 py-8 border-t border-slate-100 flex items-center justify-between bg-slate-50/30">
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Page {currentPage} of {totalPages} • {filtered.length.toLocaleString()} Active Profiles</div>
              <div className="flex items-center gap-2">
                <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="p-3 bg-white border border-slate-200 rounded-xl disabled:opacity-30"><ChevronLeft size={20} /></button>
                <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} disabled={currentPage === totalPages} className="p-3 bg-white border border-slate-200 rounded-xl disabled:opacity-30"><ChevronRight size={20} /></button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SanctionsRegistry;

import React, { useState, useEffect } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus } from '../types';
import { Save, Cloud, Terminal, Check, Copy, AlertTriangle, ShieldCheck, History, Users, Lock, UserCircle, ShieldAlert, Plus, Power, Key, X, Mail, UserPlus, CheckCircle2, Trash2, UserMinus, AlertCircle, RefreshCw, Link2, Share2, Shield, Zap, Globe } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  onSwitchUser?: (role: UserRole, id: string) => void;
  currentUserId?: string;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, onSwitchUser, currentUserId, currentUser }) => {
  const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
  const [activeTab, setActiveTab] = useState<'config' | 'rbac' | 'logs' | 'users'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);
  const [copiedSql, setCopiedSql] = useState(false);

  const [targetDomain, setTargetDomain] = useState(window.location.origin + window.location.pathname);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  useEffect(() => { setLocalSettings(settings); }, [settings]);

  const SQL_SCHEMA = `-- 1. System Metadata Table (For Global Locking)
CREATE TABLE IF NOT EXISTS public.system_metadata (
  key TEXT PRIMARY KEY,
  value JSONB DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- Enable Realtime for Mutex Lock
ALTER TABLE public.system_metadata REPLICA IDENTITY FULL;
ALTER PUBLICATION supabase_realtime ADD TABLE public.system_metadata;

-- 2. Profiles Table
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT UNIQUE NOT NULL,
  full_name TEXT,
  role_id TEXT,
  status TEXT DEFAULT 'Active',
  is_system_admin BOOLEAN DEFAULT false,
  must_change_password BOOLEAN DEFAULT true,
  password_expiry TIMESTAMPTZ,
  password_hash_mock TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 3. Clients Table
CREATE TABLE IF NOT EXISTS public.clients (
  id TEXT PRIMARY KEY,
  "Client Name" TEXT,
  kyc_status TEXT,
  "Company Nationality" TEXT,
  "QFC No" TEXT,
  "Legal Structure" TEXT,
  "No" TEXT,
  created_at TIMESTAMPTZ DEFAULT now(),
  riskLevel TEXT DEFAULT 'None'
);

-- 4. Sanctions Table
CREATE TABLE IF NOT EXISTS public.sanctions (
  "dataId" TEXT PRIMARY KEY,
  "firstName" TEXT,
  "lastName" TEXT,
  "source" TEXT,
  "referenceNumber" TEXT,
  "listedOn" TEXT,
  "nationality" TEXT,
  "unListType" TEXT,
  "aliases" JSONB DEFAULT '[]'::jsonb
);
`;

  const copySql = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopiedSql(true);
    setTimeout(() => setCopiedSql(false), 2000);
  };

  const copyMasterInstallLink = () => {
    let cleanBase = targetDomain.trim();
    if (!cleanBase.startsWith('http')) cleanBase = 'https://' + cleanBase;
    if (cleanBase.endsWith('/')) cleanBase = cleanBase.slice(0, -1);
    const params = new URLSearchParams();
    if (settings.supabaseUrl) params.set('supaUrl', settings.supabaseUrl);
    if (settings.supabaseKey) params.set('supaKey', settings.supabaseKey);
    const link = `${cleanBase}/#/login?${params.toString()}`;
    navigator.clipboard.writeText(link);
    setCopiedLink(true);
    setTimeout(() => setCopiedLink(false), 2000);
  };

  const saveUsersToStorage = async (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    if (!settings.supabaseUrl || !settings.supabaseKey) return;
    setIsSyncing(true);
    try {
      if (isDelete) { await deleteCloudUser(user.email); } else { await upsertCloudUser(user); }
    } catch (e: any) { console.error("Cloud Engine Error:", e.message); } finally { setIsSyncing(false); }
  };

  const toggleUserStatus = async (email: string) => {
    const updated = systemUsers.map(u => {
      if (u.email === email) {
        const newUser = { ...u, status: u.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE };
        handleCloudSync(newUser);
        return newUser;
      }
      return u;
    });
    saveUsersToStorage(updated);
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;
    const emailToDelete = pendingDeleteUser.email;
    const updated = systemUsers.filter(u => u.email !== emailToDelete);
    saveUsersToStorage(updated);
    await handleCloudSync(pendingDeleteUser, true);
    setPendingDeleteUser(null);
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const normalizedEmail = newUserEmail.trim().toLowerCase();
    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: normalizedEmail,
      password: DEFAULT_TEMP_PASSWORD,
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };
    await handleCloudSync(newUser);
    saveUsersToStorage([...systemUsers, newUser]);
    setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false); setIsNewUserAdmin(false);
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-10">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center bg-white p-6 sm:p-8 rounded-[2rem] shadow-sm border border-gray-100 gap-6">
        <div className="flex items-center gap-4">
          <div className="bg-amber-500 p-4 rounded-2xl text-white shadow-xl shadow-amber-100">
            <Shield size={28}/>
          </div>
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-900 tracking-tight uppercase">Governance</h2>
            <p className="text-[10px] text-amber-600 font-black uppercase tracking-widest mt-1">Control Plane Node</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full xl:w-auto overflow-x-auto custom-scrollbar no-scrollbar-on-mobile">
            <button onClick={() => setActiveTab('users')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'users' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Identities</button>
            <button onClick={() => setActiveTab('config')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'config' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Engine</button>
            <button onClick={() => setActiveTab('logs')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'logs' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Logs</button>
        </div>
      </div>

      {activeTab === 'users' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 sm:gap-8">
            <div className="lg:col-span-2 bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
                <div className="p-6 sm:p-8 border-b border-slate-50 flex flex-col xs:flex-row justify-between items-start xs:items-center gap-4">
                   <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-3">
                      Access Roster {isSyncing && <RefreshCw size={16} className="animate-spin text-emerald-600" />}
                   </h3>
                   <button onClick={() => setIsUserModalOpen(true)} className="w-full xs:w-auto bg-emerald-800 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest flex justify-center items-center gap-2 hover:bg-emerald-900 transition-all shadow-lg">
                     <Plus size={16} /> New Identity
                   </button>
                </div>
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="w-full text-left min-w-[500px]">
                      <thead className="bg-slate-50/50 text-[9px] font-black text-slate-400 uppercase tracking-widest">
                        <tr>
                          <th className="px-8 py-5">System Identity</th>
                          <th className="px-8 py-5">Role</th>
                          <th className="px-8 py-5 text-right">Controls</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {systemUsers.map(user => (
                          <tr key={user.email} className="hover:bg-slate-50/50 group transition-all">
                            <td className="px-8 py-5">
                              <div className="font-black text-slate-900 text-sm truncate max-w-[200px]">{user.full_name}</div>
                              <div className="text-[10px] text-slate-400 font-bold truncate max-w-[200px]">{user.email}</div>
                            </td>
                            <td className="px-8 py-5">
                              <span className="px-2 py-1 text-[8px] font-black rounded-md border uppercase bg-white border-slate-100 text-slate-500">{user.role}</span>
                            </td>
                            <td className="px-8 py-5 text-right">
                               <div className="flex justify-end gap-1">
                                  <button onClick={() => toggleUserStatus(user.email)} title="Toggle Account Status" className={`p-2.5 rounded-xl transition-all ${user.status === AccountStatus.ACTIVE ? 'text-amber-500 hover:bg-amber-50' : 'text-emerald-500 hover:bg-emerald-50'}`}><Power size={18}/></button>
                                  <button onClick={() => setPendingDeleteUser(user)} title="Delete User" className="p-2.5 rounded-xl text-red-400 hover:bg-red-50 transition-all"><Trash2 size={18}/></button>
                               </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                </div>
            </div>

            <div className="bg-emerald-950 rounded-[2.5rem] p-8 sm:p-10 text-white shadow-2xl relative overflow-hidden flex flex-col justify-between min-h-[500px]">
                <div className="absolute top-0 right-0 p-10 opacity-10 pointer-events-none text-emerald-400">
                  <Zap size={140} className="animate-pulse" />
                </div>
                <div className="relative z-10">
                  <Globe size={40} className="mb-6 text-emerald-400" />
                  <h4 className="text-xl sm:text-2xl font-black mb-4 uppercase leading-tight">Master Install Link</h4>
                  <p className="text-emerald-100/60 text-[10px] leading-relaxed mb-6 font-black uppercase tracking-widest">
                    v1.9.0 Zero-Config: Generate a provisioning link for any production domain. Colleagues who open this link will auto-configure their browser for Live Screening.
                  </p>

                  <div className="space-y-4 mb-8">
                    <div className="bg-white/5 border border-white/10 rounded-2xl p-4">
                      <label className="text-[8px] font-black uppercase tracking-widest text-emerald-400 mb-2 block">Target Deployment URL</label>
                      <input 
                        type="text" 
                        value={targetDomain}
                        onChange={(e) => setTargetDomain(e.target.value)}
                        placeholder="e.g. https://my-app.vercel.app"
                        className="w-full bg-slate-900/50 border border-emerald-500/30 rounded-xl px-4 py-3 text-[10px] font-mono text-white outline-none focus:border-emerald-500 transition-all"
                      />
                    </div>
                  </div>
                </div>

                <button 
                  onClick={copyMasterInstallLink}
                  className={`w-full py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-3 transition-all ${copiedLink ? 'bg-emerald-500 text-white' : 'bg-white text-emerald-950 hover:bg-emerald-50 shadow-xl'}`}
                >
                  {copiedLink ? <Check size={18}/> : <Link2 size={18}/>}
                  {copiedLink ? 'Link Buffered to Clipboard' : 'Generate & Copy Install Link'}
                </button>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'config' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2">
           <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm">
              <div className="flex justify-between items-center mb-8">
                 <div className="flex items-center gap-4">
                    <div className="bg-emerald-50 p-3 rounded-2xl text-emerald-600"><Database size={24}/></div>
                    <h3 className="text-sm font-black uppercase tracking-widest text-emerald-900">SQL Synchronization Schema</h3>
                 </div>
                 <button onClick={copySql} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${copiedSql ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                    {copiedSql ? <Check size={16}/> : <Copy size={16}/>} {copiedSql ? 'Copied' : 'Copy Schema'}
                 </button>
              </div>
              <div className="bg-slate-900 rounded-3xl p-6 overflow-hidden">
                 <pre className="text-[10px] text-emerald-400 font-mono overflow-x-auto custom-scrollbar h-96">{SQL_SCHEMA}</pre>
              </div>
              <div className="mt-6 p-4 bg-amber-50 border border-amber-100 rounded-2xl flex gap-4 text-amber-800">
                 <AlertTriangle size={20} className="shrink-0"/>
                 <p className="text-[10px] font-bold uppercase tracking-widest leading-relaxed">Mandatory: Run this SQL in your Supabase project to enable Global Locking and Real-time registry updates.</p>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

