import React, { useState, useEffect } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus } from '../types';
// Added Database icon to imports
import { Save, Cloud, Terminal, Check, Copy, AlertTriangle, ShieldCheck, History, Users, Lock, UserCircle, ShieldAlert, Plus, Power, Key, X, Mail, UserPlus, CheckCircle2, Trash2, UserMinus, AlertCircle, RefreshCw, Link2, Share2, Shield, Zap, Globe, Database } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  onSwitchUser?: (role: UserRole, id: string) => void;
  currentUserId?: string;
