import { createClient } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel, UserProfile, SanctionEntry } from '../types';

let supabaseClient: any = null;

export const initSupabase = (settings: AppSettings) => {
  if (!settings.supabaseUrl || !settings.supabaseKey) {
    supabaseClient = null;
    return false;
  }

  try {
    // v2.2.0 Hardened creation guard
    supabaseClient = createClient(settings.supabaseUrl.trim(), settings.supabaseKey.trim(), {
      auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false }
    });
    return true;
  } catch (e) {
    console.error("[v2.2.0] Supabase Init Crash Protection:", e);
    supabaseClient = null;
    return false;
  }
};

export const checkConnection = async () => {
  if (!supabaseClient) return false;
  try {
    const { error } = await supabaseClient.from('profiles').select('email').limit(1);
    return !error;
  } catch (err) {
    return false;
  }
};

export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  try {
    const { data, error } = await supabaseClient
      .from('system_metadata')
      .select('*')
      .eq('key', 'global_sync_lock')
      .single();

    if (error && error.code === 'PGRST116') {
      const initial = { is_syncing: false, last_sync: 'Never', locked_at: 0 };
      await supabaseClient.from('system_metadata').insert([{ key: 'global_sync_lock', value: initial }]);
      return initial;
    }

    const val = data?.value || { is_syncing: false, last_sync: 'Never', locked_at: 0 };
    const LOCK_TIMEOUT = 10 * 60 * 1000;
    if (val.is_syncing && val.locked_at && (Date.now() - val.locked_at > LOCK_TIMEOUT)) {
      return { ...val, is_syncing: false };
    }
    return val;
  } catch (e) {
    return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  }
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync?: string) => {
  if (!supabaseClient) return;
  const status = { 
    is_syncing: isSyncing, 
    last_sync: lastSync || 'In Progress...',
    locked_at: isSyncing ? Date.now() : 0 
  };
  await supabaseClient
    .from('system_metadata')
    .upsert([{ key: 'global_sync_lock', value: status }], { onConflict: 'key' });
};

export const subscribeToGlobalSync = (onUpdate: (status: any) => void) => {
  if (!supabaseClient) return null;
  return supabaseClient
    .channel('system-metadata-consensus')
    .on('postgres_changes', { 
      event: '*', 
      schema: 'public', 
      table: 'system_metadata', 
      filter: 'key=eq.global_sync_lock' 
    }, (payload: any) => {
      const newVal = payload.new?.value || payload.old?.value;
      if (newVal) onUpdate(newVal);
    })
    .subscribe();
};

export const fetchCloudClients = async (): Promise<Client[] | null> => {
  if (!supabaseClient) return null;
  const { data, error } = await supabaseClient.from('clients').select('*').order('created_at', { ascending: false });
  if (error) throw error;
  return data;
};

export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').upsert([client], { onConflict: 'id' });
  if (error) throw error;
};

export const deleteCloudClient = async (id: string) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').delete().eq('id', id);
  if (error) throw error;
};

export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
  return error ? 0 : (count || 0);
};

export const fetchSanctionsBatch = async (offset: number, limit: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  const { data, error } = await supabaseClient.from('sanctions').select('*').range(offset, offset + limit - 1);
  if (error) throw error;
  return data || [];
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (progress: number) => void) => {
  if (!supabaseClient) return;
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize);
    const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'dataId' });
    if (error) throw error;
    if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
  }
};

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabaseClient) return null;
  const { data, error } = await supabaseClient.from('profiles').select('*');
  return error ? null : data;
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) return;
  const dbProfile = {
    id: user.id,
    email: user.email.toLowerCase().trim(),
    full_name: user.full_name,
    role_id: user.role,
    status: user.status || 'Active',
    is_system_admin: user.is_system_admin === true,
    must_change_password: user.must_change_password,
    password_expiry: user.password_expiry,
    password_hash_mock: user.password,
    created_at: user.created_at || new Date().toISOString()
  };
  const { error } = await supabaseClient.from('profiles').upsert([dbProfile], { onConflict: 'email' });
  if (error) throw new Error(error.message);
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('profiles').delete().eq('email', email.toLowerCase().trim());
  if (error) throw new Error(error.message);
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabaseClient && channel) await supabaseClient.removeChannel(channel);
};

