import { createClient } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel, UserProfile, SanctionEntry } from '../types';

let supabaseClient: any = null;

export const initSupabase = (settings: AppSettings) => {
  if (!settings.supabaseUrl || !settings.supabaseKey) {
    supabaseClient = null;
    return false;
  }

  try {
    supabaseClient = createClient(settings.supabaseUrl.trim(), settings.supabaseKey.trim(), {
      auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false }
    });
    return true;
  } catch (e) {
    console.error("[v2.2.1] Supabase Init Error:", e);
    supabaseClient = null;
    return false;
  }
};

export const checkConnection = async () => {
  if (!supabaseClient) return false;
  try {
    const { error } = await supabaseClient.from('profiles').select('email').limit(1);
    return !error;
  } catch (err) {
    return false;
  }
};

export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  try {
    // v2.2.1: Optimized metadata fetch with fallback creation
    const { data, error } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'global_sync_lock')
      .maybeSingle(); // maybeSingle avoids the 'PGRST116' error (moved/deleted)

    if (error) throw error;

    if (!data) {
      const initial = { is_syncing: false, last_sync: 'Never', locked_at: 0 };
      // Attempt to initialize if missing
      await supabaseClient.from('system_metadata').insert([{ key: 'global_sync_lock', value: initial }]);
      return initial;
    }

    const val = data.value || { is_syncing: false, last_sync: 'Never', locked_at: 0 };

    // Auto-release stuck locks (10 min timeout)
    const LOCK_TIMEOUT = 10 * 60 * 1000;
    if (val.is_syncing && val.locked_at && (Date.now() - val.locked_at > LOCK_TIMEOUT)) {
      console.warn("[v2.2.1] Stale Global Lock Detected. Releasing...");
      return { ...val, is_syncing: false };
    }
    return val;
  } catch (e) {
    console.error("[v2.2.1] Metadata Fetch Failed:", e);
    return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  }
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync?: string) => {
  if (!supabaseClient) return;
  const status = { 
    is_syncing: isSyncing, 
    last_sync: lastSync || 'In Progress...',
    locked_at: isSyncing ? Date.now() : 0 
  };
  try {
    await supabaseClient
      .from('system_metadata')
      .upsert([{ key: 'global_sync_lock', value: status }], { onConflict: 'key' });
  } catch (e) {
    console.error("[v2.2.1] Failed to set lock:", e);
  }
};

export const subscribeToGlobalSync = (onUpdate: (status: any) => void) => {
  if (!supabaseClient) return null;
  return supabaseClient
    .channel('system-metadata-consensus')
    .on('postgres_changes', { 
      event: '*', 
      schema: 'public', 
      table: 'system_metadata', 
      filter: 'key=eq.global_sync_lock' 
    }, (payload: any) => {
      const newVal = payload.new?.value || payload.old?.value;
      if (newVal) onUpdate(newVal);
    })
    .subscribe();
};

export const fetchCloudClients = async (): Promise<Client[] | null> => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient.from('clients').select('*').order('created_at', { ascending: false });
    if (error) throw error;
    return data;
  } catch (e) {
    console.error("fetchCloudClients error:", e);
    return null;
  }
};

export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').upsert([client], { onConflict: 'id' });
  if (error) throw error;
};

export const deleteCloudClient = async (id: string) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').delete().eq('id', id);
  if (error) throw error;
};

export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  try {
    const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
    return error ? 0 : (count || 0);
  } catch (e) {
    return 0;
  }
};

export const fetchSanctionsBatch = async (offset: number, limit: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  const { data, error } = await supabaseClient.from('sanctions').select('*').range(offset, offset + limit - 1);
  if (error) throw error;
  return data || [];
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (progress: number) => void) => {
  if (!supabaseClient) return;
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize);
    const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'dataId' });
    if (error) throw error;
    if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
  }
};

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient.from('profiles').select('*');
    return error ? null : data;
  } catch (e) {
    return null;
  }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) return;
  const dbProfile = {
    id: user.id,
    email: user.email.toLowerCase().trim(),
    full_name: user.full_name,
    role_id: user.role,
    status: user.status || 'Active',
    is_system_admin: user.is_system_admin === true,
    must_change_password: user.must_change_password,
    password_expiry: user.password_expiry,
    password_hash_mock: user.password,
    created_at: user.created_at || new Date().toISOString()
  };
  const { error } = await supabaseClient.from('profiles').upsert([dbProfile], { onConflict: 'email' });
  if (error) throw new Error(error.message);
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('profiles').delete().eq('email', email.toLowerCase().trim());
  if (error) throw new Error(error.message);
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabaseClient && channel) {
    try {
      await supabaseClient.removeChannel(channel);
    } catch (e) {}
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsRegistry from './components/SanctionsRegistry';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Loader2, ShieldCheck, AlertCircle } from 'lucide-react';
import { Client, SanctionEntry, RiskLevel, AppSettings, UserRole, UserProfile, AccountStatus } from './types';
import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  fetchCloudUsers,
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount
} from './services/cloudDb';
import { OFFICIAL_UN_XML_URL } from './services/unSanctionsService';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co'
};

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [bootError, setBootError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('unsg_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'LOCAL' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('LOCAL');

  const [registryStats, setRegistryStats] = useState(() => {
    const saved = localStorage.getItem('unsg_registry_stats');
    return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    // v2.2.1 Robust Deep Link Extraction
    const getParam = (name: string) => {
      // Check standard search params
      const searchParams = new URLSearchParams(window.location.search);
      if (searchParams.has(name)) return searchParams.get(name);

      // Check hash-based params (common in some hosting envs)
      const hash = window.location.hash;
      if (hash.includes('?')) {
        const hashParams = new URLSearchParams(hash.split('?')[1]);
        if (hashParams.has(name)) return hashParams.get(name);
      }
      return null;
    };

    const urlKey = getParam('supaKey');
    const urlUrl = getParam('supaUrl');

    if (urlKey && urlUrl) {
      const magic = { ...DEFAULT_SETTINGS, supabaseUrl: urlUrl, supabaseKey: urlKey };
      localStorage.setItem('unsg_settings', JSON.stringify(magic));
      // Cleanup URL without refreshing
      const cleanUrl = window.location.origin + window.location.pathname + window.location.hash.split('?')[0];
      window.history.replaceState({}, document.title, cleanUrl);
      return magic;
    }

    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);
  const lastUpdateRef = useRef<number>(0);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);

    if (meta.last_sync && meta.last_sync !== 'In Progress...') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
    }
  }, []);

  const attemptHandshake = useCallback(async (targetSettings: AppSettings) => {
    if (!targetSettings.supabaseUrl || !targetSettings.supabaseKey) {
      setConnectionStatus('LOCAL');
      setIsBooting(false);
      return;
    }

    setConnectionStatus('CONNECTING');
    const initialized = initSupabase(targetSettings);

    if (initialized) {
      try {
        const healthy = await checkConnection();
        if (healthy) {
          setConnectionStatus('CONNECTED');

          const [cloudClients, count, lockStatus] = await Promise.all([
            fetchCloudClients().catch(() => null),
            fetchSanctionsTotalCount().catch(() => 0),
            fetchGlobalSyncStatus().catch(() => null)
          ]);

          if (cloudClients) setClients(cloudClients);
          setSanctionsCount(count);
          if (lockStatus) handleGlobalMetadataUpdate(lockStatus);

          // Subscriptions
          if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
          subscriptionRef.current = subscribeToClients(() => {
            fetchCloudClients().then(c => c && setClients(c));
          });

          if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
          syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
        } else {
          setConnectionStatus('ERROR');
        }
      } catch (e: any) {
        console.error("Handshake fatal error:", e);
        setBootError(e.message || "Unknown Handshake Error");
        setConnectionStatus('ERROR');
      }
    } else {
      setConnectionStatus('LOCAL');
    }
    setIsBooting(false);
  }, [handleGlobalMetadataUpdate]);

  useEffect(() => {
    attemptHandshake(settings);

    const heartbeat = setInterval(async () => {
      if (connectionStatus === 'CONNECTED') {
        try {
          const [status, count] = await Promise.all([
            fetchGlobalSyncStatus(),
            fetchSanctionsTotalCount()
          ]);
          handleGlobalMetadataUpdate(status);
          setSanctionsCount(count);
        } catch (e) {}
      }
    }, 15000); 

    return () => { 
      if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current); 
      if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
      clearInterval(heartbeat);
    };
  }, [attemptHandshake, settings, connectionStatus, handleGlobalMetadataUpdate]);

  if (isBooting) {
    return (
      <div className="min-h-screen bg-emerald-950 flex flex-col items-center justify-center p-6 text-white">
        <div className="bg-white/5 p-12 rounded-[3rem] border border-white/10 flex flex-col items-center gap-8 shadow-2xl animate-in zoom-in-95 duration-500">
          <div className="relative">
             <Loader2 className="animate-spin text-emerald-400" size={64} strokeWidth={1} />
             <ShieldCheck className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-white" size={24} />
          </div>
          <div className="text-center space-y-2">
            <h1 className="text-sm font-black uppercase tracking-[0.4em] text-emerald-100">UNSanctionGuard</h1>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-widest">
              {connectionStatus === 'CONNECTING' ? 'Handshaking Layer 1...' : 'Establishing Consensus...'}
            </p>
          </div>
        </div>
      </div>
    );
  }

  // Handle critical boot failures with a reset option
  if (bootError && connectionStatus === 'ERROR') {
    return (
      <div className="min-h-screen bg-red-950 flex flex-col items-center justify-center p-6 text-white">
        <div className="bg-white/5 p-12 rounded-[3rem] border border-white/10 flex flex-col items-center gap-8 shadow-2xl max-w-md w-full text-center">
          <AlertCircle className="text-red-400" size={64} />
          <div className="space-y-4">
            <h1 className="text-sm font-black uppercase tracking-[0.2em] text-red-100">Registry Boot Failure</h1>
            <p className="text-[10px] text-red-400/80 font-bold uppercase leading-relaxed">{bootError}</p>
            <button 
              onClick={() => {
                localStorage.removeItem('unsg_settings');
                window.location.reload();
              }}
              className="w-full bg-red-600 hover:bg-red-700 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all"
            >
              Reset Connection & Retry
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!currentUser) return (
    <Login 
      onLogin={(user) => {
        setCurrentUser(user);
        localStorage.setItem('unsg_session', JSON.stringify(user));
      }} 
      isCloudConnected={connectionStatus === 'CONNECTED'} 
      defaultUrl={settings.supabaseUrl || ''}
    />
  );

  if (currentUser.must_change_password) return (
    <PasswordUpdate 
      user={currentUser} 
      onUpdate={async (newPassword) => {
        const updatedUser = { ...currentUser, password: newPassword, must_change_password: false };
        if (connectionStatus === 'CONNECTED') await upsertCloudUser(updatedUser);
        setCurrentUser(updatedUser);
        localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      }} 
    />
  );

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={() => {
          setCurrentUser(null);
          localStorage.removeItem('unsg_session');
        }}
        currentUser={currentUser}
        onRetryConnection={() => attemptHandshake(settings)}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              onAddClient={async (newClient) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(newClient);
                else setClients(prev => [newClient, ...prev]);
              }} 
              onUpdateClient={async (updated) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(updated);
                setClients(prev => prev.map(c => c.id === updated.id ? updated : c));
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                setClients(prev => prev.filter(c => c.id !== id));
              }}
              onRefresh={() => {
                 fetchCloudClients().then(c => c && setClients(c));
              }} 
              currentUserRole={currentUser.role}
              currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsRegistry 
              onSyncComplete={(data, stats) => {
                setSanctions(data);
                if (stats) {
                  setRegistryStats(stats);
                  localStorage.setItem('unsg_registry_stats', JSON.stringify(stats));
                  fetchSanctionsTotalCount().then(setSanctionsCount);
                }
              }}
              isCloudConnected={connectionStatus === 'CONNECTED'}
              initialStats={registryStats}
              isGlobalSyncing={isGlobalSyncing}
            />} />
          <Route path="/admin" element={
            currentUser.is_system_admin === true ? (
              <AdminPanel settings={settings} logs={[]} onUpdateSettings={(s) => {
                setSettings(s);
