const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co'
};

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [bootError, setBootError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'LOCAL' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('LOCAL');

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    try {
      // v2.4.0: Hardened URL Extraction with Error Boundary
      const urlStr = window.location.href.replace('#/', '');
      const url = new URL(urlStr);
      let urlKey = url.searchParams.get('supaKey');
      let urlUrl = url.searchParams.get('supaUrl');

      if (!urlKey || !urlUrl) {
        const hashParts = window.location.hash.split('?');
        if (hashParts[1]) {
          const altParams = new URLSearchParams(hashParts[1]);
          urlKey = urlKey || altParams.get('supaKey');
          urlUrl = urlUrl || altParams.get('supaUrl');
        }
      }

      if (urlKey && urlUrl) {
        const magic = { ...DEFAULT_SETTINGS, supabaseUrl: urlUrl, supabaseKey: urlKey };
        localStorage.setItem('unsg_settings', JSON.stringify(magic));
        // Cleanup UI path
        const base = window.location.origin + window.location.pathname;
        window.history.replaceState({}, document.title, base + window.location.hash.split('?')[0]);
        return magic;
      }

      const stored = localStorage.getItem('unsg_settings');
      return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
    } catch (e) {
      console.warn("[v2.4.0] Settings Init Fault Reverted to Default.");
      return { ...DEFAULT_SETTINGS };
    }
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);

    if (meta.last_sync && meta.last_sync !== 'In Progress...') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
    }
  }, []);

  const attemptHandshake = useCallback(async (targetSettings: AppSettings) => {
    if (!targetSettings.supabaseUrl || !targetSettings.supabaseKey) {
      setConnectionStatus('LOCAL');
      setIsBooting(false);
      return;
    }

    setConnectionStatus('CONNECTING');

    try {
      const initialized = initSupabase(targetSettings);
      if (!initialized) {
        throw new Error("Initialization failed. Invalid registry credentials.");
      }

      const healthy = await checkConnection();
      if (healthy) {
        setConnectionStatus('CONNECTED');

        // Parallel Data Fetch with Individual Error Catching
        const [cloudClients, count, lockStatus] = await Promise.all([
          fetchCloudClients().catch(() => null),
          fetchSanctionsTotalCount().catch(() => 0),
          fetchGlobalSyncStatus().catch(() => null)
        ]);

        if (cloudClients) setClients(cloudClients);
        setSanctionsCount(count);
        if (lockStatus) handleGlobalMetadataUpdate(lockStatus);

        // Real-time Event Bus
        if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
        subscriptionRef.current = subscribeToClients(() => {
          fetchCloudClients().then(c => c && setClients(c));
        });

        if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
        syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
      } else {
        setConnectionStatus('ERROR');
        setBootError("Handshake Refused. Master registry is unreachable or offline.");
      }
    } catch (e: any) {
      setConnectionStatus('ERROR');
      setBootError(e.message || "Fatal protocol handshake violation.");
    }

    setIsBooting(false);
  }, [handleGlobalMetadataUpdate]);

  useEffect(() => {
    attemptHandshake(settings);

    const heartbeat = setInterval(async () => {
      if (connectionStatus === 'CONNECTED') {
        try {
          const [status, count] = await Promise.all([
            fetchGlobalSyncStatus(),
            fetchSanctionsTotalCount()
          ]);
          if (status) handleGlobalMetadataUpdate(status);
          setSanctionsCount(count);
        } catch (e) {}
      }
    }, 15000); 

    return () => { 
      if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current); 
      if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
      clearInterval(heartbeat);
    };
  }, [attemptHandshake, settings, connectionStatus, handleGlobalMetadataUpdate]);

  if (isBooting) {
    return (
      <div className="min-h-screen bg-emerald-950 flex flex-col items-center justify-center p-6 text-white font-sans">
        <div className="bg-white/5 p-12 rounded-[3.5rem] border border-white/10 flex flex-col items-center gap-10 shadow-2xl animate-in zoom-in-95 duration-700">
          <div className="relative">
             <div className="absolute inset-0 bg-emerald-500/20 blur-3xl animate-pulse" />
             <Loader2 className="animate-spin text-emerald-400 relative z-10" size={72} strokeWidth={1.5} />
             <ShieldCheck className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-white relative z-20" size={28} />
          </div>
          <div className="text-center space-y-3">
            <h1 className="text-sm font-black uppercase tracking-[0.5em] text-emerald-50">UNSanctionGuard</h1>
            <div className="flex flex-col items-center gap-2">
               <p className="text-[10px] text-emerald-400/80 font-bold uppercase tracking-widest">
                {connectionStatus === 'CONNECTING' ? 'Decrypting Secure Vault...' : 'Authorizing Identity Node...'}
               </p>
               <div className="w-48 h-1 bg-emerald-900/50 rounded-full overflow-hidden">
                  <div className="h-full bg-emerald-400 w-1/2 animate-slide-infinite" />
               </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (connectionStatus === 'ERROR') {
    return (
      <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-white font-sans">
        <div className="bg-white/5 p-12 rounded-[3.5rem] border border-red-500/20 flex flex-col items-center gap-8 shadow-2xl max-w-lg w-full text-center">
          <div className="bg-red-500/20 p-6 rounded-full text-red-400">
            <AlertCircle size={48} />
          </div>
          <div className="space-y-4">
            <h1 className="text-base font-black uppercase tracking-[0.2em] text-red-100">Handshake Interrupted</h1>
            <p className="text-xs text-slate-400 font-medium leading-relaxed uppercase">{bootError}</p>

            <div className="pt-6 flex flex-col gap-3">
               <button 
                onClick={() => {
                  setIsBooting(true);
                  setBootError(null);
                  attemptHandshake(settings);
                }}
                className="w-full bg-emerald-700 hover:bg-emerald-600 text-white py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center justify-center gap-3"
              >
                <RefreshCw size={16} /> Force Re-Attempt
              </button>
              <button 
                onClick={() => {
                  localStorage.clear();
                  window.location.reload();
                }}
                className="w-full bg-white/5 hover:bg-white/10 text-slate-400 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all"
              >
                Purge Node Cache
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!currentUser) return (
    <Login 
      onLogin={(user) => {
        setCurrentUser(user);
        localStorage.setItem('unsg_session', JSON.stringify(user));
      }} 
