import React, { useState } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus } from '../types';
import { Plus, Power, Trash2, RefreshCw, Database, Shield, Globe, Copy, Check, Users, ShieldAlert, History } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'users' | 'engine' | 'logs'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);
  const [copiedSql, setCopiedSql] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const SQL_SCHEMA = `-- v2.7.0 Cloud Schema
CREATE TABLE IF NOT EXISTS public.system_metadata (
  key TEXT PRIMARY KEY,
  value JSONB DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT UNIQUE NOT NULL,
  full_name TEXT,
  role_id TEXT,
  status TEXT DEFAULT 'Active',
  is_system_admin BOOLEAN DEFAULT false,
  must_change_password BOOLEAN DEFAULT true,
  password_expiry TIMESTAMPTZ,
  password_hash_mock TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.clients (
  id TEXT PRIMARY KEY,
  "Client Name" TEXT,
  kyc_status TEXT,
  "Company Nationality" TEXT,
  "QFC No" TEXT,
  "Legal Structure" TEXT,
  "No" TEXT,
  riskLevel TEXT DEFAULT 'None',
  created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.sanctions (
  "dataId" TEXT PRIMARY KEY,
  "firstName" TEXT,
  "lastName" TEXT,
  "source" TEXT,
  "referenceNumber" TEXT,
  "listedOn" TEXT,
  "nationality" TEXT,
  "unListType" TEXT,
  "aliases" JSONB DEFAULT '[]'::jsonb
);`;

  const copySql = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopiedSql(true);
    setTimeout(() => setCopiedSql(false), 2000);
  };

  const saveUsersToStorage = (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isDelete) { await deleteCloudUser(user.email); } else { await upsertCloudUser(user); }
    } catch (e) {} finally { setIsSyncing(false); }
  };

  const toggleUserStatus = async (email: string) => {
    const updated = systemUsers.map(u => {
      if (u.email === email) {
        const newUser = { ...u, status: u.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE };
        handleCloudSync(newUser);
        return newUser;
      }
      return u;
    });
    saveUsersToStorage(updated);
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;
    const updated = systemUsers.filter(u => u.email !== pendingDeleteUser.email);
    saveUsersToStorage(updated);
    await handleCloudSync(pendingDeleteUser, true);
    setPendingDeleteUser(null);
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: newUserEmail.trim().toLowerCase(),
      password: DEFAULT_TEMP_PASSWORD,
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };
    await handleCloudSync(newUser);
    saveUsersToStorage([...systemUsers, newUser]);
    setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false); setIsNewUserAdmin(false);
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center bg-white p-6 sm:p-8 rounded-[2rem] shadow-sm border border-gray-100 gap-6">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-800 p-4 rounded-2xl text-white shadow-xl">
            <Shield size={28}/>
          </div>
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-900 tracking-tight uppercase">Governance</h2>
            <p className="text-[10px] text-emerald-600 font-black uppercase tracking-widest mt-1">Self-Linking Enterprise v2.7.0</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full xl:w-auto">
            <button onClick={() => setActiveTab('users')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'users' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Identities</button>
            <button onClick={() => setActiveTab('engine')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'engine' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Engine</button>
            <button onClick={() => setActiveTab('logs')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'logs' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Logs</button>
        </div>
      </div>

      {activeTab === 'users' && (
        <div className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-2">
            <div className="p-6 sm:p-8 border-b border-slate-50 flex flex-col xs:flex-row justify-between items-start xs:items-center gap-4">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-3">
                  Access Roster {isSyncing && <RefreshCw size={16} className="animate-spin text-emerald-600" />}
               </h3>
               <button onClick={() => setIsUserModalOpen(true)} className="w-full xs:w-auto bg-emerald-800 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest flex justify-center items-center gap-2 hover:bg-emerald-900 transition-all">
                 <Plus size={16} /> New Identity
               </button>
            </div>
            <div className="overflow-x-auto">
                <table className="w-full text-left min-w-[500px]">
                  <thead className="bg-slate-50/50 text-[9px] font-black text-slate-400 uppercase tracking-widest">
                    <tr>
                      <th className="px-8 py-5">System Identity</th>
                      <th className="px-8 py-5">Role</th>
                      <th className="px-8 py-5 text-right">Controls</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {systemUsers.map(user => (
                      <tr key={user.email} className="hover:bg-slate-50/50 transition-all">
                        <td className="px-8 py-5">
                          <div className="font-black text-slate-900 text-sm">{user.full_name}</div>
                          <div className="text-[10px] text-slate-400 font-bold">{user.email}</div>
                        </td>
                        <td className="px-8 py-5">
                          <span className="px-2 py-1 text-[8px] font-black rounded-md border uppercase bg-white border-slate-100 text-slate-500">{user.role}</span>
                        </td>
                        <td className="px-8 py-5 text-right">
                           <div className="flex justify-end gap-1">
                              <button onClick={() => toggleUserStatus(user.email)} className={`p-2.5 rounded-xl ${user.status === AccountStatus.ACTIVE ? 'text-amber-500 hover:bg-amber-50' : 'text-emerald-500 hover:bg-emerald-50'}`} title="Toggle Access"><Power size={18}/></button>
                              <button onClick={() => setPendingDeleteUser(user)} className="p-2.5 rounded-xl text-red-400 hover:bg-red-50" title="Delete Identity"><Trash2 size={18}/></button>
                           </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
            </div>
        </div>
      )}

      {activeTab === 'engine' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm animate-in fade-in">
          <div className="flex justify-between items-center mb-8">
             <div className="flex items-center gap-4">
                <div className="bg-emerald-50 p-3 rounded-2xl text-emerald-600"><Database size={24}/></div>
                <h3 className="text-sm font-black uppercase tracking-widest text-emerald-900">Synchronizer Schema</h3>
             </div>
             <button onClick={copySql} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${copiedSql ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                {copiedSql ? <Check size={16}/> : <Copy size={16}/>} Copy SQL
             </button>
          </div>
          <div className="bg-slate-900 rounded-3xl p-6">
             <pre className="text-[10px] text-emerald-400 font-mono overflow-x-auto h-96">{SQL_SCHEMA}</pre>
          </div>
        </div>
      )}

      {/* User Modal */}
      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden">
             <div className="bg-emerald-900 p-8 text-white flex justify-between items-center">
                <h3 className="text-xl font-black uppercase">Provision Identity</h3>
                <button onClick={() => setIsUserModalOpen(false)}><RefreshCw size={24}/></button>
             </div>
             <form onSubmit={handleCreateUser} className="p-8 space-y-6">
                <div className="space-y-1.5">
                   <label className="text-[9px] font-black text-slate-400 uppercase ml-1">Full Legal Name</label>
                   <input type="text" required value={newUserName} onChange={e => setNewUserName(e.target.value)} className="w-full bg-slate-50 border-none rounded-xl py-4 px-6 font-bold outline-none focus:ring-2 focus:ring-emerald-800" />
                </div>
                <div className="space-y-1.5">
                   <label className="text-[9px] font-black text-slate-400 uppercase ml-1">Email Address</label>
                   <input type="email" required value={newUserEmail} onChange={e => setNewUserEmail(e.target.value)} className="w-full bg-slate-50 border-none rounded-xl py-4 px-6 font-bold outline-none focus:ring-2 focus:ring-emerald-800" />
                </div>
                <div className="space-y-1.5">
                   <label className="text-[9px] font-black text-slate-400 uppercase ml-1">System Role</label>
                   <select value={newUserRole} onChange={e => setNewUserRole(e.target.value as UserRole)} className="w-full bg-slate-50 border-none rounded-xl py-4 px-6 font-bold outline-none focus:ring-2 focus:ring-emerald-800">
                      {Object.values(UserRole).map(role => <option key={role} value={role}>{role}</option>)}
                   </select>
                </div>
                <button type="submit" className="w-full bg-emerald-800 text-white font-black py-5 rounded-2xl uppercase tracking-widest shadow-lg">Commit Identity</button>
             </form>
          </div>
        </div>
      )}

      {pendingDeleteUser && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-sm w-full shadow-2xl border border-red-100 text-center">
            <h3 className="text-lg font-black text-slate-900 uppercase tracking-tight mb-2">Delete Identity?</h3>
            <p className="text-xs text-slate-500 font-bold mb-6">Remove {pendingDeleteUser.full_name} from the cloud registry.</p>
            <div className="flex gap-3">
              <button onClick={() => setPendingDeleteUser(null)} className="flex-1 py-3 bg-slate-50 text-slate-400 font-black text-[10px] uppercase rounded-xl">Cancel</button>
              <button onClick={confirmDeleteUser} className="flex-1 py-3 bg-red-600 text-white font-black text-[10px] uppercase rounded-xl">Confirm</button>
            </div>
          </div>
