{
  "name": "UNSanctionGuard",
  "description": "Enterprise compliance screening system. v2.8.0 - Unified Engine.",
  "requestFramePermissions": []
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry, EntityType } from '../types';
import { 
  RefreshCw, Search, ChevronLeft, ChevronRight, Database, Activity, 
  AlertCircle, Loader2, Play, Pause, Square, Trash2, Clock, 
  ShieldCheck, CloudDownload, Cpu, CheckCircle, Zap, Upload, FileText, 
  Globe, ShieldAlert, FileJson, Info, ExternalLink, Terminal 
} from 'lucide-react';
import { fetchSanctionsBatch, fetchSanctionsTotalCount, upsertCloudSanctions, setGlobalSyncLock } from '../services/cloudDb';
import { fetchFromUrl, parseUNSanctionsXML, OFFICIAL_UN_XML_URL } from '../services/unSanctionsService';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[], stats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string }) => void;
  isCloudConnected: boolean;
  initialStats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string };
  isGlobalSyncing?: boolean;
}

type ProcessStatus = 'IDLE' | 'FETCHING' | 'TESTING' | 'PAUSED' | 'COMPLETED' | 'ERROR' | 'STOPPED' | 'UPLOADING' | 'IMPORTING';

const ITEMS_PER_PAGE = 15;
const BATCH_SIZE = 500;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, initialStats, isGlobalSyncing }) => {
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [currentOffset, setCurrentOffset] = useState(0);
  const [targetRecords, setTargetRecords] = useState(0);
  const [batchesFetched, setBatchesFetched] = useState(0);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [processLogs, setProcessLogs] = useState<{msg: string, time: string}[]>([]);

  const [lastFetchTime, setLastFetchTime] = useState<string>(initialStats?.lastFetch || 'Never');
  const [lastTestTime, setLastTestTime] = useState<string>(initialStats?.lastTest || 'Never');
  const [lastSourceUpdate, setLastSourceUpdate] = useState<string>(initialStats?.lastSourceUpdate || 'Never');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const isRunningRef = useRef(false);
  const isPausedRef = useRef(false);

  const addLog = (msg: string) => {
    const time = new Date().toLocaleTimeString();
    setProcessLogs(prev => [{ msg, time }, ...prev].slice(0, 10));
  };

  const refreshDbStats = useCallback(async () => {
    if (isCloudConnected) {
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);
      return count;
    }
    return 0;
  }, [isCloudConnected]);

  useEffect(() => {
    refreshDbStats().then(count => { if (targetRecords === 0) setTargetRecords(count); });
  }, [refreshDbStats]);

  // Handle Manual File Import
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isCloudConnected) return;

    setStatus('IMPORTING');
    setUploadProgress(0);
    setErrorMessage(null);
    addLog(`Ingesting local file: ${file.name}`);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result as string;
        let parsedData: SanctionEntry[] = [];

        if (file.name.endsWith('.xml')) {
          parsedData = parseUNSanctionsXML(content);
        } else if (file.name.endsWith('.json')) {
          parsedData = JSON.parse(content);
        } else {
          throw new Error("Unsupported format. Use official UN XML or compatible JSON.");
        }

        addLog(`Parsed ${parsedData.length} records. Uploading to Cloud...`);
        setStatus('UPLOADING');

        await setGlobalSyncLock(true, 'Importing...');
        await upsertCloudSanctions(parsedData, (p) => setUploadProgress(p));

        const now = new Date().toLocaleString();
        await setGlobalSyncLock(false, now);
        setLastSourceUpdate(now);

        const newTotal = await refreshDbStats();
        setTargetRecords(newTotal);

        addLog("Cloud Registry Updated Successfully.");
        setStatus('COMPLETED');
        // Auto-trigger node sync after import
        handleStart();
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMessage(err.message);
        addLog(`Import Error: ${err.message}`);
      }
    };
    reader.readAsText(file);
  };

  const syncFromOfficialSource = async () => {
    if (!isCloudConnected || isGlobalSyncing) return;

    setStatus('UPLOADING');
    setUploadProgress(0);
    setErrorMessage(null);
    addLog("Attempting Direct Handshake with UN Global Registry...");

    try {
      await setGlobalSyncLock(true, 'In Progress...');
      const liveData = await fetchFromUrl(OFFICIAL_UN_XML_URL);
      addLog(`Handshake Success: ${liveData.length} profiles retrieved.`);

      await upsertCloudSanctions(liveData, (progress) => setUploadProgress(progress));

      const now = new Date().toLocaleString();
      await setGlobalSyncLock(false, now);

      setLastSourceUpdate(now);
      const newTotal = await refreshDbStats();
      setTargetRecords(newTotal);

      addLog("Global Sync Verified. Data Committed.");
      setStatus('COMPLETED');
      handleStart();
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate); 
      const isCors = err.message.includes('fetch');
      setErrorMessage(isCors ? "CORS Security Block: Source refuses direct browser handshake. Please use 'Manual File Import'." : err.message);
      setStatus('ERROR');
      addLog(`Handshake Failure: ${isCors ? 'CORS Restricted' : err.message}`);
    }
  };

  const runAutomationStep = useCallback(async (offset: number) => {
    if (!isRunningRef.current || isPausedRef.current) return;

    try {
      setStatus('FETCHING');
      addLog(`Fetching Cloud Batch @ offset ${offset}...`);
      const batch = await fetchSanctionsBatch(offset, BATCH_SIZE);

      const now = new Date().toLocaleString();
      setLastFetchTime(now);

      if (batch.length === 0) {
        addLog("Full Registry Reached.");
        setStatus('COMPLETED');
        isRunningRef.current = false;
        return;
      }

      setSanctions(prev => {
        const merged = [...prev, ...batch];
        // Deduplicate
        return Array.from(new Set(merged.map(s => s.dataId)))
          .map(id => merged.find(s => s.dataId === id)!);
      });
      setBatchesFetched(prev => prev + 1);

      setStatus('TESTING');
      addLog(`Fuzzy Validation of ${batch.length} profiles...`);
      await new Promise(resolve => setTimeout(resolve, 200));

      const testNow = new Date().toLocaleString();
      setLastTestTime(testNow);

      // We call onSyncComplete with the full list so far
      setSanctions(current => {
        onSyncComplete(current, { lastFetch: now, lastTest: testNow, lastSourceUpdate });
        return current;
      });

      const nextOffset = offset + batch.length;
      setCurrentOffset(nextOffset);

      if (nextOffset >= targetRecords) {
        addLog("Node Sync Verified.");
        setStatus('COMPLETED');
        isRunningRef.current = false;
      } else {
        runAutomationStep(nextOffset);
      }
    } catch (err: any) {
      setErrorMessage(err.message);
      setStatus('ERROR');
      isRunningRef.current = false;
    }
  }, [targetRecords, onSyncComplete, lastSourceUpdate]);

  const handleStart = () => {
    if (!isCloudConnected || isGlobalSyncing) return;
    setErrorMessage(null);
    isRunningRef.current = true;
    isPausedRef.current = false;
    runAutomationStep(currentOffset);
  };

  const handlePause = () => { isPausedRef.current = true; setStatus('PAUSED'); addLog("Engine Suspended."); };
  const handleStop = () => { isRunningRef.current = false; isPausedRef.current = false; setStatus('STOPPED'); addLog("Engine Terminated."); };
  const handleReset = () => {
    setSanctions([]); setCurrentOffset(0); setBatchesFetched(0); setStatus('IDLE'); setErrorMessage(null);
    onSyncComplete([], { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate });
    addLog("Node Cache Purged.");
  };

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const paginatedData = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* 1. UNIFIED INGESTION PANEL */}
      <div className={`bg-white p-8 rounded-[3rem] border shadow-2xl flex flex-col xl:flex-row gap-10 relative overflow-hidden transition-all duration-500 ${isGlobalSyncing ? 'border-blue-200 bg-blue-50/10' : 'border-gray-100'}`}>
        {isGlobalSyncing && (
           <div className="absolute top-0 left-0 w-full h-1.5 bg-blue-500 overflow-hidden">
             <div className="w-1/3 h-full bg-blue-200 animate-slide-infinite" />
           </div>
        )}

        <div className="flex-1 space-y-6">
           <div className="flex items-center gap-4">
             <div className={`p-4 rounded-[1.5rem] shadow-xl text-white transition-colors ${isGlobalSyncing ? 'bg-blue-600' : 'bg-emerald-950'}`}>
               {isGlobalSyncing ? <RefreshCw className="animate-spin" size={28} /> : <CloudDownload size={28} />}
             </div>
             <div>
                <h2 className="text-2xl sm:text-3xl font-black text-slate-900 uppercase tracking-tight">Consolidated Ingestion</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.3em] mt-1">Multi-Channel Registry Update</p>
             </div>
           </div>

           {errorMessage && (
              <div className="p-5 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-4 text-red-600 animate-in slide-in-from-top-2">
                <AlertCircle size={20} className="shrink-0 mt-0.5" />
                <p className="text-[10px] font-black uppercase leading-relaxed">{errorMessage}</p>
              </div>
           )}

           <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
              <button 
                onClick={syncFromOfficialSource}
                disabled={!isCloudConnected || isGlobalSyncing || status === 'UPLOADING' || isRunningRef.current}
                className="group relative flex items-center justify-between p-6 bg-slate-900 text-white rounded-[2rem] hover:bg-black transition-all disabled:opacity-30 overflow-hidden"
              >
                <div className="relative z-10 text-left">
                  <p className="text-[9px] font-black text-emerald-400 uppercase tracking-widest mb-1">Channel A</p>
                  <h4 className="text-sm font-black uppercase">Direct Sync</h4>
                  <p className="text-[8px] text-slate-400 font-bold uppercase mt-1">Direct URL Fetch Protocol</p>
                </div>
                <Globe className="relative z-10 text-emerald-500 opacity-50 group-hover:scale-110 transition-transform" size={32} />
              </button>

              <div className="relative">
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xml,.json" className="hidden" />
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  disabled={!isCloudConnected || isGlobalSyncing || status === 'UPLOADING' || isRunningRef.current}
