import PasswordUpdate from './components/PasswordUpdate';
import { Loader2, ShieldCheck, AlertCircle, RefreshCw, WifiOff, Zap } from 'lucide-react';
import { Client, SanctionEntry, RiskLevel, AppSettings, UserRole, UserProfile, AccountStatus } from './types';
import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  fetchCloudUsers,
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount
} from './services/cloudDb';
import { OFFICIAL_UN_XML_URL } from './services/unSanctionsService';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
};

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR'>('CONNECTING');
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    if (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
    }
  }, []);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');
    setConnectionError(null);

    try {
      initSupabase();
      const healthy = await checkConnection();

      if (healthy) {
        setConnectionStatus('CONNECTED');
        const [cloudClients, count, lockStatus] = await Promise.all([
          fetchCloudClients().catch(() => []),
          fetchSanctionsTotalCount().catch(() => 0),
          fetchGlobalSyncStatus().catch(() => null)
        ]);

        if (Array.isArray(cloudClients)) setClients(cloudClients);
        setSanctionsCount(count);
        if (lockStatus) handleGlobalMetadataUpdate(lockStatus);

        if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
        subscriptionRef.current = subscribeToClients(() => {
          fetchCloudClients().then(c => c && setClients(c));
        });
        if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
        syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
      } else {
        setConnectionStatus('ERROR');
        setConnectionError("Cloud Registry refused handshake. Verify network connectivity or master credentials.");
      }
    } catch (e: any) {
      setConnectionStatus('ERROR');
      setConnectionError(e.message || "Fatal exception during node bootloader.");
    }

    setIsBooting(false);
  }, [handleGlobalMetadataUpdate]);

  useEffect(() => {
    bootEnterpriseNode();
    const heartbeat = setInterval(async () => {
      if (connectionStatus === 'CONNECTED') {
        try {
          const [status, count] = await Promise.all([
            fetchGlobalSyncStatus().catch(() => null),
            fetchSanctionsTotalCount().catch(() => 0)
          ]);
          if (status) handleGlobalMetadataUpdate(status);
          setSanctionsCount(count);
        } catch (e) {}
      }
    }, 20000); 
    return () => clearInterval(heartbeat);
  }, [bootEnterpriseNode, connectionStatus, handleGlobalMetadataUpdate]);

  if (isBooting) {
    return (
      <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-white font-sans">
        <div className="bg-white/5 p-12 rounded-[3.5rem] border border-white/10 flex flex-col items-center gap-10 shadow-2xl animate-pulse">
          <Loader2 className="animate-spin text-emerald-400" size={64} strokeWidth={1.5} />
          <h1 className="text-xs font-black uppercase tracking-[0.5em] text-emerald-50 text-center">SanctionGuard Secure Node v2.8.5</h1>
        </div>
      </div>
    );
  }

  // Connection Error Screen
  if (connectionStatus === 'ERROR' && !currentUser) {
     return (
        <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-white font-sans">
          <div className="bg-white/5 p-12 rounded-[3.5rem] border border-red-500/20 flex flex-col items-center gap-8 max-w-lg w-full text-center shadow-2xl">
            <WifiOff className="text-red-400" size={64} strokeWidth={1.5} />
            <div className="space-y-4">
              <h1 className="text-base font-black uppercase tracking-[0.3em] text-red-50">Handshake Violation</h1>
              <p className="text-[10px] text-slate-400 font-bold leading-relaxed uppercase tracking-widest">{connectionError}</p>
            </div>
            <div className="w-full space-y-3">
               <button 
                onClick={() => { setIsBooting(true); bootEnterpriseNode(); }} 
                className="w-full bg-emerald-700 hover:bg-emerald-600 text-white py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3"
               >
                 <Zap size={16} /> Re-Verify Connection
               </button>
               <button 
                onClick={() => setConnectionStatus('CONNECTED')} 
                className="w-full bg-white/5 text-slate-400 py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] hover:bg-white/10"
               >
                 Bypass to Local-Only Node
               </button>
            </div>
          </div>
        </div>
     );
  }

  if (!currentUser) return (
    <Login 
      onLogin={(user) => { 
        setCurrentUser(user); 
        localStorage.setItem('unsg_session', JSON.stringify(user)); 
      }} 
      isCloudConnected={connectionStatus === 'CONNECTED'} 
    />
  );

  if (currentUser.must_change_password) return (
    <PasswordUpdate 
      user={currentUser} 
      onUpdate={async (newPassword) => {
        const updatedUser = { ...currentUser, password: newPassword, must_change_password: false };
        if (connectionStatus === 'CONNECTED') await upsertCloudUser(updatedUser).catch(() => {});
        setCurrentUser(updatedUser);
        localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      }} 
    />
  );

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={() => { 
          setCurrentUser(null); 
          localStorage.removeItem('unsg_session'); 
        }}
        currentUser={currentUser}
        onRetryConnection={() => bootEnterpriseNode()}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              onAddClient={async (newClient) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(newClient);
                else setClients(prev => [newClient, ...prev]);
              }} 
              onUpdateClient={async (updated) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(updated);
                setClients(prev => prev.map(c => c.id === updated.id ? updated : c));
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                setClients(prev => prev.filter(c => c.id !== id));
              }}
              onRefresh={() => { fetchCloudClients().then(c => c && setClients(c)); }} 
              currentUserRole={currentUser.role} currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsRegistry 
              onSyncComplete={(data, stats) => {
                setSanctions(data);
                if (stats) {
                  setRegistryStats(stats);
                  localStorage.setItem('unsg_registry_stats', JSON.stringify(stats));
                  fetchSanctionsTotalCount().then(setSanctionsCount);
                }
              }}
              isCloudConnected={connectionStatus === 'CONNECTED'} initialStats={registryStats} isGlobalSyncing={isGlobalSyncing}
            />} />
          <Route path="/admin" element={
            currentUser.is_system_admin === true ? (
              <AdminPanel settings={settings} logs={[]} onUpdateSettings={(s) => {
                setSettings(s);
                localStorage.setItem('unsg_settings', JSON.stringify(s));
              }} currentUser={currentUser} />
            ) : <Navigate to="/" replace />
          } />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry, EntityType } from '../types';
import { 
  RefreshCw, Search, ChevronLeft, ChevronRight, Database, Activity, 
  AlertCircle, Loader2, Play, Pause, Square, Trash2, Clock, 
  ShieldCheck, CloudDownload, Cpu, CheckCircle, Zap, Upload, FileText, 
  Globe, ShieldAlert, FileJson, Info, ExternalLink, Terminal 
} from 'lucide-react';
import { fetchSanctionsBatch, fetchSanctionsTotalCount, upsertCloudSanctions, setGlobalSyncLock } from '../services/cloudDb';
import { fetchFromUrl, parseUNSanctionsXML, OFFICIAL_UN_XML_URL } from '../services/unSanctionsService';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[], stats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string }) => void;
  isCloudConnected: boolean;
  initialStats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string };
  isGlobalSyncing?: boolean;
}

type ProcessStatus = 'IDLE' | 'FETCHING' | 'TESTING' | 'PAUSED' | 'COMPLETED' | 'ERROR' | 'STOPPED' | 'UPLOADING' | 'IMPORTING';

const ITEMS_PER_PAGE = 15;
const BATCH_SIZE = 500;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, initialStats, isGlobalSyncing }) => {
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [currentOffset, setCurrentOffset] = useState(0);
  const [targetRecords, setTargetRecords] = useState(0);
  const [batchesFetched, setBatchesFetched] = useState(0);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [processLogs, setProcessLogs] = useState<{msg: string, time: string}[]>([]);

  const [lastFetchTime, setLastFetchTime] = useState<string>(initialStats?.lastFetch || 'Never');
  const [lastTestTime, setLastTestTime] = useState<string>(initialStats?.lastTest || 'Never');
  const [lastSourceUpdate, setLastSourceUpdate] = useState<string>(initialStats?.lastSourceUpdate || 'Never');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const isRunningRef = useRef(false);
  const isPausedRef = useRef(false);

  const addLog = (msg: string) => {
    const time = new Date().toLocaleTimeString();
    setProcessLogs(prev => [{ msg, time }, ...prev].slice(0, 10));
  };

  const refreshDbStats = useCallback(async () => {
    if (isCloudConnected) {
      try {
        const count = await fetchSanctionsTotalCount();
        setTotalInDb(count);
        return count;
      } catch (e) { return 0; }
    }
    return 0;
  }, [isCloudConnected]);

  useEffect(() => {
    refreshDbStats().then(count => { 
       if (targetRecords === 0) setTargetRecords(count); 
    });
  }, [refreshDbStats]);

  // Handle Manual File Import
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isCloudConnected) return;

    setStatus('IMPORTING');
    setUploadProgress(0);
    setErrorMessage(null);
    addLog(`Ingesting local file: ${file.name}`);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result as string;
        let parsedData: SanctionEntry[] = [];

        if (file.name.endsWith('.xml')) {
          parsedData = parseUNSanctionsXML(content);
        } else if (file.name.endsWith('.json')) {
          parsedData = JSON.parse(content);
        } else {
          throw new Error("Unsupported format. Use official UN XML or compatible JSON.");
        }

        addLog(`Parsed ${parsedData.length} records. Committing to Cloud...`);
        setStatus('UPLOADING');

        await setGlobalSyncLock(true, 'Importing...');
        await upsertCloudSanctions(parsedData, (p) => setUploadProgress(p));

        const now = new Date().toLocaleString();
        await setGlobalSyncLock(false, now);
        setLastSourceUpdate(now);

        const newTotal = await refreshDbStats();
        setTargetRecords(newTotal);

        addLog("Enterprise Registry Updated Successfully.");
        setStatus('COMPLETED');
        handleStart(); // Trigger local sync to pull the fresh data
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMessage(err.message);
        addLog(`Ingestion Error: ${err.message}`);
      }
    };
    reader.readAsText(file);
  };

  const syncFromOfficialSource = async () => {
    if (!isCloudConnected || isGlobalSyncing) return;

    setStatus('UPLOADING');
    setUploadProgress(0);
    setErrorMessage(null);
    addLog("Attempting Direct Handshake with UN Global Registry...");

    try {
      await setGlobalSyncLock(true, 'In Progress...');
      const liveData = await fetchFromUrl(OFFICIAL_UN_XML_URL);
      addLog(`Handshake Success: ${liveData.length} profiles retrieved.`);

      await upsertCloudSanctions(liveData, (progress) => setUploadProgress(progress));

      const now = new Date().toLocaleString();
      await setGlobalSyncLock(false, now);

      setLastSourceUpdate(now);
      const newTotal = await refreshDbStats();
      setTargetRecords(newTotal);

      addLog("Global Sync Verified. Persistence layer updated.");
      setStatus('COMPLETED');
      handleStart();
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate); 
      setErrorMessage(`Registry unreachable: ${err.message}. Please use 'Manual Injection' as a fail-safe.`);
      setStatus('ERROR');
      addLog(`Handshake Failure: ${err.message}`);
    }
  };

  const runAutomationStep = useCallback(async (offset: number) => {
    if (!isRunningRef.current || isPausedRef.current) return;

    try {
      setStatus('FETCHING');
      addLog(`Downloading batch @ offset ${offset}...`);
      const batch = await fetchSanctionsBatch(offset, BATCH_SIZE);

      const now = new Date().toLocaleString();
      setLastFetchTime(now);

      if (batch.length === 0) {
        addLog("Full Compliance Registry synchronized.");
        setStatus('COMPLETED');
        isRunningRef.current = false;
        return;
      }

      setSanctions(prev => {
        const merged = [...prev, ...batch];
        return Array.from(new Set(merged.map(s => s.dataId)))
          .map(id => merged.find(s => s.dataId === id)!);
      });
      setBatchesFetched(prev => prev + 1);

      setStatus('TESTING');
      addLog(`Fuzzy Validation of ${batch.length} identities...`);
      await new Promise(resolve => setTimeout(resolve, 150));

      const testNow = new Date().toLocaleString();
      setLastTestTime(testNow);

      setSanctions(current => {
        onSyncComplete(current, { lastFetch: now, lastTest: testNow, lastSourceUpdate });
        return current;
      });

      const nextOffset = offset + batch.length;
      setCurrentOffset(nextOffset);

      if (nextOffset >= targetRecords) {
        addLog("Local node verified with cloud registry.");
        setStatus('COMPLETED');
        isRunningRef.current = false;
      } else {
        runAutomationStep(nextOffset);
      }
    } catch (err: any) {
      setErrorMessage(err.message);
      setStatus('ERROR');
      isRunningRef.current = false;
    }
  }, [targetRecords, onSyncComplete, lastSourceUpdate]);

  const handleStart = () => {
    if (!isCloudConnected || isGlobalSyncing) return;
    setErrorMessage(null);
    isRunningRef.current = true;
    isPausedRef.current = false;
    runAutomationStep(currentOffset);
  };

  const handlePause = () => { isPausedRef.current = true; setStatus('PAUSED'); addLog("Sequencer Suspended."); };
  const handleStop = () => { isRunningRef.current = false; isPausedRef.current = false; setStatus('STOPPED'); addLog("Sequencer Terminated."); };
  const handleReset = () => {
    setSanctions([]); setCurrentOffset(0); setBatchesFetched(0); setStatus('IDLE'); setErrorMessage(null);
    onSyncComplete([], { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate });
    addLog("Node cache purged.");
  };

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const paginatedData = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* 1. CLOUD INGESTION PANEL */}
      <div className={`bg-white p-8 rounded-[3rem] border shadow-2xl flex flex-col xl:flex-row gap-10 relative overflow-hidden transition-all duration-500 ${isGlobalSyncing ? 'border-blue-200 bg-blue-50/10' : 'border-gray-100'}`}>
        {isGlobalSyncing && (
           <div className="absolute top-0 left-0 w-full h-1.5 bg-blue-500 overflow-hidden">
             <div className="w-1/3 h-full bg-blue-200 animate-slide-infinite" />
           </div>
        )}

        <div className="flex-1 space-y-6">
           <div className="flex items-center gap-4">
             <div className={`p-4 rounded-[1.5rem] shadow-xl text-white transition-colors ${isGlobalSyncing ? 'bg-blue-600' : 'bg-emerald-950'}`}>
               {isGlobalSyncing ? <RefreshCw className="animate-spin" size={28} /> : <CloudDownload size={28} />}
             </div>
             <div>
                <h2 className="text-2xl sm:text-3xl font-black text-slate-900 uppercase tracking-tight">Cloud Ingestion Engine</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.3em] mt-1">Global Data Consensus v2.8.5</p>
             </div>
           </div>

           {errorMessage && (
              <div className="p-5 bg-red-50 border border-red-100 rounded-2xl flex items-start gap-4 text-red-600 animate-in slide-in-from-top-2">
                <AlertCircle size={20} className="shrink-0 mt-0.5" />
                <p className="text-[10px] font-black uppercase leading-relaxed">{errorMessage}</p>
              </div>
           )}

           <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
              <button 
                onClick={syncFromOfficialSource}
                disabled={!isCloudConnected || isGlobalSyncing || status === 'UPLOADING' || isRunningRef.current}
                className="group relative flex items-center justify-between p-6 bg-slate-900 text-white rounded-[2rem] hover:bg-black transition-all disabled:opacity-30 overflow-hidden shadow-xl"
              >
                <div className="relative z-10 text-left">
                  <p className="text-[9px] font-black text-emerald-400 uppercase tracking-widest mb-1">Method A</p>
                  <h4 className="text-sm font-black uppercase">Automated Sync</h4>
                  <p className="text-[8px] text-slate-400 font-bold uppercase mt-1">Direct fetch with proxy fallback</p>
                </div>
                <Globe className="relative z-10 text-emerald-500 opacity-50 group-hover:scale-110 transition-transform" size={32} />
              </button>

              <div className="relative">
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xml,.json" className="hidden" />
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  disabled={!isCloudConnected || isGlobalSyncing || status === 'UPLOADING' || isRunningRef.current}
                  className="w-full group relative flex items-center justify-between p-6 bg-emerald-700 text-white rounded-[2rem] hover:bg-emerald-800 transition-all disabled:opacity-30 overflow-hidden shadow-xl"
                >
                  <div className="relative z-10 text-left">
                    <p className="text-[9px] font-black text-white/60 uppercase tracking-widest mb-1">Method B</p>
                    <h4 className="text-sm font-black uppercase">Manual Injection</h4>
                    <p className="text-[8px] text-white/40 font-bold uppercase mt-1">Primary fail-safe protocol</p>
                  </div>
                  <Upload className="relative z-10 text-white opacity-50 group-hover:translate-y-[-4px] transition-transform" size={32} />
                </button>
              </div>
           </div>
        </div>

        <div className="w-full xl:w-96 bg-slate-50 rounded-[2.5rem] p-8 border border-slate-100 flex flex-col justify-between">
           <div className="space-y-6">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-200 pb-4">Consensus Telemetry</h4>
              <div className="space-y-4">
                 <div className="flex justify-between items-center">
                    <span className="text-[9px] font-black text-slate-500 uppercase">Registry Lock</span>
                    <span className={`px-2 py-0.5 rounded-md text-[8px] font-black uppercase ${isGlobalSyncing ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}>
                       {isGlobalSyncing ? 'MUTEX ACTIVE' : 'OPEN ACCESS'}
                    </span>
                 </div>
                 <div className="flex justify-between items-center">
                    <span className="text-[9px] font-black text-slate-500 uppercase">Cloud Count</span>
                    <span className="text-[10px] font-black text-slate-900">{totalInDb.toLocaleString()} Identities</span>
                 </div>
                 <div className="flex justify-between items-center">
                    <span className="text-[9px] font-black text-slate-500 uppercase">Last Registry Refresh</span>
                    <span className="text-[10px] font-black text-slate-900 truncate ml-4">{lastSourceUpdate}</span>
                 </div>
              </div>
           </div>

           {(status === 'UPLOADING' || status === 'IMPORTING') && (
              <div className="mt-8 space-y-2 animate-in fade-in">
                 <div className="flex justify-between text-[9px] font-black uppercase text-emerald-700">
                    <span>Synchronizing Persistence Layer</span>
                    <span>{uploadProgress}%</span>
                 </div>
                 <div className="w-full h-1.5 bg-emerald-100 rounded-full overflow-hidden">
                    <div className="h-full bg-emerald-600 transition-all duration-300" style={{ width: `${uploadProgress}%` }} />
                 </div>
              </div>
           )}
        </div>
      </div>

      {/* 2. AUTOMATION SEQUENCER */}
      <div className="bg-[#020617] p-8 sm:p-12 rounded-[3.5rem] text-white shadow-2xl border border-slate-800 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-16 opacity-5 pointer-events-none text-emerald-500">
           <Cpu size={240} />
        </div>

        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-12">
          <div className="space-y-6 max-w-2xl">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-emerald-500 rounded-2xl text-slate-950 shadow-xl shadow-emerald-500/20">
                <Activity size={24} />
              </div>
              <div>
                <h3 className="text-2xl font-black uppercase tracking-tight">Fuzzy Node Sequencer</h3>
                <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">High-Throughput Node Ingestion</p>
              </div>
            </div>

            <div className="flex flex-wrap gap-4 items-center bg-white/5 p-6 rounded-[2rem] border border-white/10">
              <div className="space-y-1.5">
                <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Ingestion Depth</label>
                <div className="flex items-center gap-3">
                  <input 
                    type="number" 
                    disabled={status !== 'IDLE' && status !== 'STOPPED' && status !== 'COMPLETED'}
                    value={targetRecords} 
                    onChange={e => setTargetRecords(Math.min(99999, parseInt(e.target.value) || 0))}
