export const OFFICIAL_UN_XML_URL = "https://scsanctions.un.org/resources/xml/en/consolidated.xml";
export const QATAR_NCTC_URL = "https://portal.moi.gov.qa/wps/portal/NCTC/sanctionlist/unifiedsanctionlist/";
export const OPENSANCTIONS_URL = "https://www.opensanctions.org/datasets/default/entities.json";

const PROXY_URL = "https://api.allorigins.win/get?url=";

/**
 * Normalizes sanction types across different sources
 */
const mapToEntityType = (rawType: string): EntityType => {
  const t = rawType.toLowerCase();
  if (t.includes('individual') || t.includes('person')) return EntityType.INDIVIDUAL;
  return EntityType.CORPORATE;
};

/**
 * Parses CSV strings into SanctionEntry objects
 */
export const parseCSVToSanctions = (csv: string, sourceName: string): SanctionEntry[] => {
  const lines = csv.split(/\r?\n/);
  if (lines.length < 2) return [];

  const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
  const entries: SanctionEntry[] = [];

  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const values = lines[i].split(',').map(v => v.trim());
    const entry: any = {
      source: sourceName,
      aliases: [],
      type: EntityType.INDIVIDUAL
    };

    headers.forEach((h, idx) => {
      const val = values[idx];
      if (h === 'id' || h === 'dataid') entry.dataId = `${sourceName}-${val}`;
      if (h === 'firstname' || h === 'name') entry.firstName = val;
      if (h === 'lastname') entry.lastName = val;
      if (h === 'nationality') entry.nationality = val;
      if (h === 'type') entry.type = mapToEntityType(val);
      if (h === 'reference') entry.referenceNumber = val;
    });

    if (entry.firstName) entries.push(entry as SanctionEntry);
  }
  return entries;
};

/**
 * Parses JSON strings (OpenSanctions style)
 */
export const parseJSONToSanctions = (jsonStr: string, sourceName: string): SanctionEntry[] => {
  try {
    const data = JSON.parse(jsonStr);
    const list = Array.isArray(data) ? data : (data.entities || []);
    return list.map((item: any) => ({
      dataId: `${sourceName}-${item.id || Math.random()}`,
      source: sourceName,
      firstName: item.name || item.caption || 'Unknown',
      lastName: '',
      unListType: item.schema || 'General',
      referenceNumber: item.id || '',
      listedOn: item.first_seen || '',
      comments: item.notes || '',
      nationality: Array.isArray(item.properties?.nationality) ? item.properties.nationality[0] : '',
      aliases: item.properties?.alias || [],
      type: mapToEntityType(item.schema || 'person')
    }));
  } catch (e) {
    return [];
  }
};

/**
 * Parses the UN Consolidated List XML string
 */
export const parseUNSanctionsXML = (xmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlString, "text/xml");
  const entries: SanctionEntry[] = [];

  const individuals = xmlDoc.getElementsByTagName("INDIVIDUAL");
  for (let i = 0; i < individuals.length; i++) {
    entries.push(parseIndividual(individuals[i]));
  }

  const entities = xmlDoc.getElementsByTagName("ENTITY");
  for (let i = 0; i < entities.length; i++) {
    entries.push(parseEntity(entities[i]));
  }

  return entries;
};

const getNodeVal = (parent: Element, tagName: string): string => {
  const node = parent.getElementsByTagName(tagName)[0];
  return node ? node.textContent?.trim() || '' : '';
};

const parseIndividual = (node: Element): SanctionEntry => {
  const dataId = getNodeVal(node, "DATAID");
  return {
    dataId: `UN-${dataId}`,
    source: 'UN Consolidated',
    firstName: getNodeVal(node, "FIRST_NAME"),
    secondName: getNodeVal(node, "SECOND_NAME"),
    thirdName: getNodeVal(node, "THIRD_NAME"),
    lastName: '', 
    unListType: getNodeVal(node, "UN_LIST_TYPE"),
    referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
    listedOn: getNodeVal(node, "LISTED_ON"),
    comments: getNodeVal(node, "COMMENTS1"),
    nationality: node.getElementsByTagName("NATIONALITY")[0] ? getNodeVal(node.getElementsByTagName("NATIONALITY")[0], "VALUE") : '',
    dateOfBirth: node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0] ? getNodeVal(node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0], "DATE") : '',
    aliases: Array.from(node.getElementsByTagName("INDIVIDUAL_ALIAS")).map(a => getNodeVal(a, "ALIAS_NAME")).filter(Boolean),
    type: EntityType.INDIVIDUAL
  };
};

const parseEntity = (node: Element): SanctionEntry => {
  const dataId = getNodeVal(node, "DATAID");
  return {
    dataId: `UN-${dataId}`,
    source: 'UN Consolidated',
    firstName: getNodeVal(node, "FIRST_NAME"),
    lastName: '',
    unListType: getNodeVal(node, "UN_LIST_TYPE"),
    referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
    listedOn: getNodeVal(node, "LISTED_ON"),
    comments: getNodeVal(node, "COMMENTS1"),
    nationality: '',
    aliases: Array.from(node.getElementsByTagName("ENTITY_ALIAS")).map(a => getNodeVal(a, "ALIAS_NAME")).filter(Boolean),
    type: EntityType.CORPORATE
  };
};

export const fetchFromUrl = async (url: string, sourceName: string): Promise<SanctionEntry[]> => {
  try {
    const proxyResponse = await fetch(`${PROXY_URL}${encodeURIComponent(url)}`);
    if (!proxyResponse.ok) throw new Error("CORS Proxy Handshake Failed.");
    const json = await proxyResponse.json();
    const content = json.contents;

    if (content.includes('<?xml')) return parseUNSanctionsXML(content);
    if (content.trim().startsWith('{') || content.trim().startsWith('[')) return parseJSONToSanctions(content, sourceName);
    return parseCSVToSanctions(content, sourceName);
  } catch (error: any) {
    console.error(`fetchFromUrl [${sourceName}] Error:`, error);
    throw error;
  }
};

