  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [currentOffset, setCurrentOffset] = useState(0);
  const [targetRecords, setTargetRecords] = useState(0);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successReport, setSuccessReport] = useState<{source: string, count: number, type: string} | null>(null);
  const [processLogs, setProcessLogs] = useState<{msg: string, time: string, type: 'info' | 'error' | 'success'}[]>([]);

  const [lastSourceUpdate, setLastSourceUpdate] = useState<string>(initialStats?.lastSourceUpdate || 'Never');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const isRunningRef = useRef(false);
  const isPausedRef = useRef(false);

  const addLog = (msg: string, type: 'info' | 'error' | 'success' = 'info') => {
    const time = new Date().toLocaleTimeString();
    setProcessLogs(prev => [{ msg, time, type }, ...prev].slice(0, 15));
  };

  const refreshDbStats = useCallback(async () => {
    if (isCloudConnected) {
      try {
        const count = await fetchSanctionsTotalCount();
        setTotalInDb(count);
        return count;
      } catch (e) { return 0; }
    }
    return 0;
  }, [isCloudConnected]);

  useEffect(() => {
    refreshDbStats().then(count => { 
       if (targetRecords === 0) setTargetRecords(count); 
    });
  }, [refreshDbStats]);

  const handleManualImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isCloudConnected) return;

    setStatus('IMPORTING');
    setUploadProgress(0);
    setErrorMessage(null);
    setSuccessReport(null);
    addLog(`Ingesting local file: ${file.name}`);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result as string;
        let parsedData: SanctionEntry[] = [];
        const sourceName = file.name.split('.')[0].toUpperCase();

        if (file.name.endsWith('.xml')) parsedData = parseUNSanctionsXML(content);
        else if (file.name.endsWith('.json')) parsedData = parseJSONToSanctions(content, sourceName);
        else if (file.name.endsWith('.csv')) parsedData = parseCSVToSanctions(content, sourceName);
        else throw new Error("Format not recognized. Use XML, JSON, or CSV.");

        if (parsedData.length === 0) throw new Error("File empty or mapping failed.");

        addLog(`Validation complete. ${parsedData.length} records ready for commit.`, 'success');
        setStatus('UPLOADING');

        await setGlobalSyncLock(true, 'Manual Import...');
        await upsertCloudSanctions(parsedData, (p) => setUploadProgress(p));

        const now = new Date().toLocaleString();
        await setGlobalSyncLock(false, now);
        setLastSourceUpdate(now);
        setSuccessReport({ source: sourceName, count: parsedData.length, type: 'Manual' });

        const newTotal = await refreshDbStats();
        setTargetRecords(newTotal);
        setStatus('COMPLETED');
        addLog("Database persistence success.", 'success');
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMessage(err.message);
        addLog(`Import Error: ${err.message}`, 'error');
      }
    };
    reader.readAsText(file);
  };

  const syncSource = async (url: string, name: string) => {
    if (!isCloudConnected || isGlobalSyncing) return;

    setStatus('FETCHING');
    setUploadProgress(0);
    setErrorMessage(null);
    setSuccessReport(null);
    addLog(`Initiating Handshake: ${name}...`);

    try {
      await setGlobalSyncLock(true, `Syncing ${name}...`);
      const liveData = await fetchFromUrl(url, name);
      addLog(`Handshake Success. ${liveData.length} profiles retrieved.`, 'success');

      setStatus('UPLOADING');
      await upsertCloudSanctions(liveData, (p) => setUploadProgress(p));

      const now = new Date().toLocaleString();
      await setGlobalSyncLock(false, now);
      setLastSourceUpdate(now);
      setSuccessReport({ source: name, count: liveData.length, type: 'Automated' });

      const newTotal = await refreshDbStats();
      setTargetRecords(newTotal);
      setStatus('COMPLETED');
      addLog(`${name} synchronized with Master Registry.`, 'success');
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate); 
      setErrorMessage(`Source Unreachable: ${err.message}. Network or CORS limitation detected.`);
      setStatus('ERROR');
      addLog(`Sync Failed: ${err.message}`, 'error');
    }
  };

  const runLocalSync = useCallback(async (offset: number) => {
    if (!isRunningRef.current || isPausedRef.current) return;

    try {
      setStatus('FETCHING');
      const batch = await fetchSanctionsBatch(offset, BATCH_SIZE);

      if (batch.length === 0) {
        setStatus('COMPLETED');
        isRunningRef.current = false;
        addLog("Local node fully synchronized.", 'success');
        return;
      }

      setSanctions(prev => {
        const merged = [...prev, ...batch];
        const unique = Array.from(new Set(merged.map(s => s.dataId))).map(id => merged.find(s => s.dataId === id)!);
        onSyncComplete(unique, { lastFetch: new Date().toLocaleString(), lastTest: 'Validated', lastSourceUpdate });
        return unique;
      });

      const nextOffset = offset + batch.length;
      setCurrentOffset(nextOffset);

      if (nextOffset >= targetRecords) {
        setStatus('COMPLETED');
        isRunningRef.current = false;
        addLog("Registry Verification Complete.", 'success');
      } else {
        runLocalSync(nextOffset);
      }
    } catch (err: any) {
      setErrorMessage(err.message);
      setStatus('ERROR');
      isRunningRef.current = false;
    }
  }, [targetRecords, onSyncComplete, lastSourceUpdate]);

  const handleStartSequencer = () => {
    if (!isCloudConnected || isGlobalSyncing) return;
    setErrorMessage(null);
    isRunningRef.current = true;
    isPausedRef.current = false;
    runLocalSync(currentOffset);
  };

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const paginatedData = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">

      {/* SECTION: INGESTION CONTROL CENTER */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

        {/* Method A: Automated Sync */}
        <div className="xl:col-span-2 bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex items-center gap-4 border-b border-gray-50 pb-6">
              <div className="bg-blue-600 p-4 rounded-2xl text-white shadow-lg">
                 <CloudDownload size={28} />
              </div>
              <div>
                 <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">Consensus Engine</h2>
                 <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Multi-Source Ingestion Protocol</p>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {[
                { name: 'UN Security Council', url: OFFICIAL_UN_XML_URL, icon: <Globe />, color: 'blue' },
                { name: 'Qatar NCTC', url: QATAR_NCTC_URL, icon: <ShieldAlert />, color: 'amber' },
                { name: 'OpenSanctions', url: OPENSANCTIONS_URL, icon: <FileJson />, color: 'emerald' }
              ].map(source => (
                <button 
                  key={source.name}
                  onClick={() => syncSource(source.url, source.name)}
                  disabled={!isCloudConnected || isGlobalSyncing || status === 'FETCHING' || status === 'UPLOADING'}
                  className="p-6 rounded-[2rem] border border-slate-100 hover:border-blue-500 hover:bg-blue-50/50 transition-all flex flex-col items-center text-center gap-4 group disabled:opacity-30"
                >
                   <div className={`p-4 rounded-2xl bg-slate-50 text-slate-400 group-hover:bg-blue-600 group-hover:text-white transition-all`}>
                      {React.cloneElement(source.icon as any, { size: 24 })}
                   </div>
                   <div>
                      <h4 className="text-xs font-black uppercase text-slate-800">{source.name}</h4>
                      <p className="text-[8px] font-bold text-slate-400 uppercase mt-1 tracking-widest">Connect & Fetch</p>
                   </div>
                </button>
              ))}
           </div>

           {/* Feedback Area */}
           {successReport && (
             <div className="p-6 bg-emerald-50 border border-emerald-100 rounded-[2rem] flex items-center justify-between animate-in zoom-in-95">
                <div className="flex items-center gap-4">
                   <div className="p-3 bg-emerald-600 text-white rounded-xl"><CheckCircle size={20}/></div>
                   <div>
                      <p className="text-[10px] font-black text-emerald-900 uppercase">Successful Ingestion</p>
                      <p className="text-sm font-black text-emerald-950">{successReport.count.toLocaleString()} Records from {successReport.source}</p>
                   </div>
                </div>
                <div className="text-right">
                   <p className="text-[8px] font-black text-emerald-600 uppercase">Persistence Level</p>
                   <p className="text-[10px] font-black text-emerald-900 uppercase">{successReport.type}</p>
                </div>
             </div>
           )}

           {errorMessage && (
             <div className="p-6 bg-red-50 border border-red-100 rounded-[2rem] flex items-start gap-4 animate-in slide-in-from-top-2">
                <AlertCircle className="text-red-600 shrink-0 mt-1" size={24} />
                <div>
                   <p className="text-[10px] font-black text-red-900 uppercase">Operation Failed</p>
                   <p className="text-xs font-bold text-red-700 mt-1 leading-relaxed">{errorMessage}</p>
                   <p className="text-[8px] font-black text-red-400 uppercase mt-2">Recommended: Download the file manually and use "Injection" mode.</p>
                </div>
             </div>
           )}
        </div>

        {/* Method B: Manual Injection & Telemetry */}
        <div className="bg-slate-950 p-8 rounded-[3rem] text-white flex flex-col justify-between shadow-2xl relative overflow-hidden">
           <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none text-blue-500">
              <Database size={160} />
           </div>

           <div className="relative z-10 space-y-6">
              <div className="flex items-center gap-3">
                 <Terminal className="text-emerald-400" size={20} />
                 <h3 className="text-sm font-black uppercase tracking-widest">Node Telemetry</h3>
              </div>

              <div className="space-y-4">
                 <div className="flex justify-between items-center py-3 border-b border-white/5">
                    <span className="text-[9px] font-black text-white/40 uppercase">Registry Status</span>
                    <span className={`px-2 py-0.5 rounded-md text-[8px] font-black uppercase ${isGlobalSyncing ? 'bg-amber-500 text-black' : 'bg-emerald-500 text-white'}`}>
                       {isGlobalSyncing ? 'SYNCING...' : 'LIVE'}
                    </span>
                 </div>
                 <div className="flex justify-between items-center py-3 border-b border-white/5">
                    <span className="text-[9px] font-black text-white/40 uppercase">Master Count</span>
                    <span className="text-xs font-black text-white">{totalInDb.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center py-3">
                    <span className="text-[9px] font-black text-white/40 uppercase">Last Global Refresh</span>
                    <span className="text-[10px] font-black text-emerald-400 truncate ml-4">{lastSourceUpdate}</span>
                 </div>
              </div>
           </div>

           <div className="relative z-10 mt-8 space-y-4">
              <input type="file" ref={fileInputRef} onChange={handleManualImport} accept=".xml,.json,.csv" className="hidden" />
              <button 
                onClick={() => fileInputRef.current?.click()}
                disabled={isGlobalSyncing || status === 'FETCHING' || status === 'UPLOADING'}
                className="w-full py-5 bg-white text-black rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-slate-200 transition-all shadow-xl disabled:opacity-30"
              >
                 <Upload size={18} /> Manual injection
              </button>

              {(status === 'UPLOADING' || status === 'IMPORTING') && (
                <div className="space-y-2 animate-in fade-in">
                   <div className="flex justify-between text-[8px] font-black uppercase text-emerald-400">
                      <span>Persistence Progress</span>
                      <span>{uploadProgress}%</span>
                   </div>
                   <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden">
                      <div className="h-full bg-emerald-400 transition-all duration-300" style={{ width: `${uploadProgress}%` }} />
                   </div>
                </div>
              )}
           </div>
        </div>
      </div>

      {/* SECTION: NODE SEQUENCER */}
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col lg:flex-row gap-8 items-start lg:items-center">
         <div className="flex-1 space-y-2">
            <div className="flex items-center gap-3">
               <Activity className="text-blue-600" size={20} />
               <h3 className="text-sm font-black uppercase text-slate-900">Node Cache Synchronizer</h3>
            </div>
            <p className="text-[10px] text-gray-400 font-bold uppercase leading-relaxed">Verified {sanctions.length.toLocaleString()} of {totalInDb.toLocaleString()} entries against master registry.</p>
         </div>
         <div className="flex items-center gap-3 w-full lg:w-auto">
            {status === 'FETCHING' ? (
              <button onClick={() => { isPausedRef.current = true; setStatus('PAUSED'); }} className="flex-1 lg:flex-none p-4 bg-amber-600 text-white rounded-2xl shadow-lg"><Pause size={20}/></button>
            ) : (
              <button 
                onClick={handleStartSequencer} 
                disabled={isGlobalSyncing || (currentOffset >= totalInDb && status !== 'IDLE')}
                className="flex-1 lg:flex-none flex items-center justify-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all shadow-xl disabled:opacity-30"
              >
                <Play size={18} /> {status === 'PAUSED' ? 'Resume' : 'Verify Node'}
              </button>
            )}
            <button 
               onClick={() => { 
                 setSanctions([]); 
                 setCurrentOffset(0); 
                 setStatus('IDLE'); 
                 onSyncComplete([], { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate });
               }} 
               className="p-4 bg-gray-50 text-gray-400 rounded-2xl hover:bg-red-50 hover:text-red-600 transition-all"
            >
               <Trash2 size={20} />
            </button>
         </div>
      </div>

      {/* SECTION: REGISTRY EXPLORER */}
      <div className="space-y-6">
        <div className="bg-white p-3 rounded-[2.5rem] shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
            <input 
              type="text" 
              placeholder="Filter synchronized node records..." 
              className="w-full pl-16 pr-6 py-5 bg-gray-50/50 border-none rounded-[2rem] outline-none text-xs font-bold placeholder-gray-400" 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
            />
          </div>
          <div className="flex items-center gap-4 px-6 py-2">
             <div className="text-right">
                <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Search Scope</p>
                <p className="text-[10px] font-black text-slate-900 uppercase">{filtered.length.toLocaleString()} Hits</p>
             </div>
             <ListChecks className="text-blue-600" size={20} />
          </div>
        </div>

        <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left border-collapse min-w-[1000px]">
              <thead className="bg-gray-50/50 border-b border-gray-100">
                <tr>
                  <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Origin</th>
                  <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Identified Persona / Entity</th>
                  <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Nationality</th>
                  <th className="px-10 py-7 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Reference ID</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {paginatedData.map((entry) => (
                  <tr key={entry.dataId} className="hover:bg-blue-50/20 transition-colors group">
                    <td className="px-10 py-6">
                       <span className="px-3 py-1.5 rounded-xl text-[8px] font-black uppercase border border-slate-100 text-slate-500 bg-white group-hover:border-blue-200 group-hover:text-blue-800 transition-all">
                          {entry.source}
                       </span>
                    </td>
                    <td className="px-10 py-6">
                       <div className="font-black text-slate-900 text-base leading-tight">{entry.firstName} {entry.lastName}</div>
                       <div className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-1">{entry.unListType}</div>
                    </td>
                    <td className="px-10 py-6 font-black text-[10px] text-slate-600 uppercase tracking-widest">{entry.nationality || 'NOT SPECIFIED'}</td>
                    <td className="px-10 py-6 text-right text-[11px] text-slate-400 font-mono font-bold">{entry.referenceNumber}</td>
                  </tr>
                ))}
                {paginatedData.length === 0 && (
                   <tr>
                      <td colSpan={4} className="px-10 py-32 text-center opacity-40">
                         <div className="flex flex-col items-center gap-4">
                            <BarChart3 size={48} strokeWidth={1} />
                            <p className="text-[10px] font-black uppercase tracking-[0.4em]">Local Cache Empty</p>
                         </div>
                      </td>
                   </tr>
                )}
              </tbody>
            </table>
          </div>
          {filtered.length > 0 && (
            <div className="px-10 py-8 border-t border-gray-50 flex flex-col sm:flex-row items-center justify-between bg-gray-50/30 gap-6">
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-4">
                 <span>Tier {currentPage} / {totalPages}</span>
                 <span className="h-1 w-1 bg-slate-300 rounded-full" />
                 <span>Verified Node Integrity</span>
              </div>
              <div className="flex items-center gap-3">
                <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="p-4 bg-white border border-gray-200 rounded-2xl disabled:opacity-30 shadow-sm hover:border-blue-500 transition-all"><ChevronLeft size={20} /></button>
                <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} disabled={currentPage === totalPages} className="p-4 bg-white border border-gray-200 rounded-2xl disabled:opacity-30 shadow-sm hover:border-blue-500 transition-all"><ChevronRight size={20} /></button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SanctionsRegistry;

import { SanctionEntry, EntityType } from '../types';

export const OFFICIAL_UN_XML_URL = "https://scsanctions.un.org/resources/xml/en/consolidated.xml";
export const QATAR_NCTC_URL = "https://portal.moi.gov.qa/wps/portal/NCTC/sanctionlist/unifiedsanctionlist/";
export const OPENSANCTIONS_URL = "https://www.opensanctions.org/datasets/default/entities.json";
// Added missing OFAC SDN URL export for U.S. Treasury data
export const OFAC_SDN_URL = "https://www.treasury.gov/ofac/downloads/sdn.csv";

const PROXY_URL = "https://api.allorigins.win/get?url=";

/**
 * Normalizes sanction types across different sources
 */
const mapToEntityType = (rawType: string): EntityType => {
  const t = rawType.toLowerCase();
  if (t.includes('individual') || t.includes('person')) return EntityType.INDIVIDUAL;
  return EntityType.CORPORATE;
};

/**
 * Parses CSV strings into SanctionEntry objects
 */
export const parseCSVToSanctions = (csv: string, sourceName: string): SanctionEntry[] => {
  const lines = csv.split(/\r?\n/);
  if (lines.length < 2) return [];

  const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
  const entries: SanctionEntry[] = [];

  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const values = lines[i].split(',').map(v => v.trim());
    const entry: any = {
      source: sourceName,
      aliases: [],
      type: EntityType.INDIVIDUAL
    };

    headers.forEach((h, idx) => {
      const val = values[idx];
      if (h === 'id' || h === 'dataid') entry.dataId = `${sourceName}-${val}`;
      if (h === 'firstname' || h === 'name') entry.firstName = val;
      if (h === 'lastname') entry.lastName = val;
      if (h === 'nationality') entry.nationality = val;
      if (h === 'type') entry.type = mapToEntityType(val);
      if (h === 'reference') entry.referenceNumber = val;
    });

    if (entry.firstName) entries.push(entry as SanctionEntry);
  }
  return entries;
};

/**
 * Parses JSON strings (OpenSanctions style)
 */
export const parseJSONToSanctions = (jsonStr: string, sourceName: string): SanctionEntry[] => {
  try {
    const data = JSON.parse(jsonStr);
    const list = Array.isArray(data) ? data : (data.entities || []);
    return list.map((item: any) => ({
      dataId: `${sourceName}-${item.id || Math.random()}`,
      source: sourceName,
      firstName: item.name || item.caption || 'Unknown',
      lastName: '',
      unListType: item.schema || 'General',
      referenceNumber: item.id || '',
      listedOn: item.first_seen || '',
      comments: item.notes || '',
      nationality: Array.isArray(item.properties?.nationality) ? item.properties.nationality[0] : '',
      aliases: item.properties?.alias || [],
      type: mapToEntityType(item.schema || 'person')
    }));
  } catch (e) {
    return [];
  }
};

/**
 * Parses the UN Consolidated List XML string
 */
export const parseUNSanctionsXML = (xmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlString, "text/xml");
  const entries: SanctionEntry[] = [];

  const individuals = xmlDoc.getElementsByTagName("INDIVIDUAL");
  for (let i = 0; i < individuals.length; i++) {
    entries.push(parseIndividual(individuals[i]));
  }

  const entities = xmlDoc.getElementsByTagName("ENTITY");
  for (let i = 0; i < entities.length; i++) {
    entries.push(parseEntity(entities[i]));
  }

  return entries;
};

const getNodeVal = (parent: Element, tagName: string): string => {
  const node = parent.getElementsByTagName(tagName)[0];
  return node ? node.textContent?.trim() || '' : '';
};

const parseIndividual = (node: Element): SanctionEntry => {
  const dataId = getNodeVal(node, "DATAID");
  return {
    dataId: `UN-${dataId}`,
    source: 'UN Consolidated',
    firstName: getNodeVal(node, "FIRST_NAME"),
    secondName: getNodeVal(node, "SECOND_NAME"),
    thirdName: getNodeVal(node, "THIRD_NAME"),
    lastName: '', 
    unListType: getNodeVal(node, "UN_LIST_TYPE"),
    referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
    listedOn: getNodeVal(node, "LISTED_ON"),
    comments: getNodeVal(node, "COMMENTS1"),
    nationality: node.getElementsByTagName("NATIONALITY")[0] ? getNodeVal(node.getElementsByTagName("NATIONALITY")[0], "VALUE") : '',
    dateOfBirth: node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0] ? getNodeVal(node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0], "DATE") : '',
    aliases: Array.from(node.getElementsByTagName("INDIVIDUAL_ALIAS")).map(a => getNodeVal(a, "ALIAS_NAME")).filter(Boolean),
    type: EntityType.INDIVIDUAL
  };
};

const parseEntity = (node: Element): SanctionEntry => {
  const dataId = getNodeVal(node, "DATAID");
  return {
    dataId: `UN-${dataId}`,
    source: 'UN Consolidated',
    firstName: getNodeVal(node, "FIRST_NAME"),
    lastName: '',
    unListType: getNodeVal(node, "UN_LIST_TYPE"),
    referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
    listedOn: getNodeVal(node, "LISTED_ON"),
    comments: getNodeVal(node, "COMMENTS1"),
    nationality: '',
    aliases: Array.from(node.getElementsByTagName("ENTITY_ALIAS")).map(a => getNodeVal(a, "ALIAS_NAME")).filter(Boolean),
    type: EntityType.CORPORATE
  };
};

export const fetchFromUrl = async (url: string, sourceName: string): Promise<SanctionEntry[]> => {
  try {
    const proxyResponse = await fetch(`${PROXY_URL}${encodeURIComponent(url)}`);
    if (!proxyResponse.ok) throw new Error("CORS Proxy Handshake Failed.");
    const json = await proxyResponse.json();
    const content = json.contents;

    if (content.includes('<?xml')) return parseUNSanctionsXML(content);
    if (content.trim().startsWith('{') || content.trim().startsWith('[')) return parseJSONToSanctions(content, sourceName);
    return parseCSVToSanctions(content, sourceName);
  } catch (error: any) {
    console.error(`fetchFromUrl [${sourceName}] Error:`, error);
    throw error;
  }
};

