/**
 * Normalizes sanction types across different sources
 */
const mapToEntityType = (rawType: string): EntityType => {
  const t = rawType.toLowerCase();
  if (t.includes('individual') || t.includes('person') || t.includes('person')) return EntityType.INDIVIDUAL;
  return EntityType.CORPORATE;
};

/**
 * Detects file format based on content snippet or extension
 */
export const detectFormat = (content: string, fileName?: string): 'XML' | 'JSON' | 'CSV' | 'UNKNOWN' => {
  const trimmed = content.trim();
  if (trimmed.startsWith('<?xml') || trimmed.startsWith('<')) return 'XML';
  if (trimmed.startsWith('{') || trimmed.startsWith('[')) return 'JSON';
  if (trimmed.includes(',') && trimmed.split('\n')[0].includes(',')) return 'CSV';

  if (fileName) {
    if (fileName.endsWith('.xml')) return 'XML';
    if (fileName.endsWith('.json')) return 'JSON';
    if (fileName.endsWith('.csv')) return 'CSV';
  }

  return 'UNKNOWN';
};

/**
 * Parses CSV strings into SanctionEntry objects
 */
export const parseCSVToSanctions = (csv: string, sourceName: string): SanctionEntry[] => {
  const lines = csv.split(/\r?\n/);
  if (lines.length < 2) return [];

  const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
  const entries: SanctionEntry[] = [];

  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;

    // Simple CSV split (not handling quoted commas for now)
    const values = lines[i].split(',').map(v => v.trim());
    const entry: any = {
      source: sourceName,
      aliases: [],
      type: EntityType.INDIVIDUAL,
      fetchDate: new Date().toISOString()
    };

    headers.forEach((h, idx) => {
      const val = values[idx];
      if (!val) return;
      if (h === 'id' || h === 'dataid' || h === 'uid') entry.dataId = `${sourceName}-${val}`;
      if (h === 'firstname' || h === 'first_name' || h === 'name') entry.firstName = val;
      if (h === 'lastname' || h === 'last_name') entry.lastName = val;
      if (h === 'nationality') entry.nationality = val;
      if (h === 'type' || h === 'kind') entry.type = mapToEntityType(val);
      if (h === 'reference' || h === 'ref_id') entry.referenceNumber = val;
      if (h === 'date_of_birth' || h === 'dob') entry.dateOfBirth = val;
    });

    if (entry.firstName) {
      if (!entry.dataId) entry.dataId = `${sourceName}-${i}`;
      entries.push(entry as SanctionEntry);
    }
  }
  return entries;
};

/**
 * Parses JSON strings (Generic or OpenSanctions style)
 */
export const parseJSONToSanctions = (jsonStr: string, sourceName: string): SanctionEntry[] => {
  try {
    const data = JSON.parse(jsonStr);
    const list = Array.isArray(data) ? data : (data.entities || data.results || []);

    return list.map((item: any, idx: number) => ({
      dataId: `${sourceName}-${item.id || item.uid || idx}`,
      source: sourceName,
      firstName: item.name || item.caption || item.first_name || 'Unknown',
      lastName: item.last_name || '',
      unListType: item.schema || item.category || 'General',
      referenceNumber: item.id || item.ref || '',
      listedOn: item.first_seen || item.listing_date || '',
      comments: item.notes || item.summary || '',
      nationality: Array.isArray(item.properties?.nationality) ? item.properties.nationality[0] : (item.nationality || ''),
      aliases: item.properties?.alias || item.aliases || [],
      type: mapToEntityType(item.schema || item.type || 'person'),
      fetchDate: new Date().toISOString()
    }));
  } catch (e) {
    console.error("JSON Parse Error:", e);
    return [];
  }
};

/**
 * Parses the UN Consolidated List XML string
 */
export const parseUNSanctionsXML = (xmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlString, "text/xml");
  const entries: SanctionEntry[] = [];

  const individuals = xmlDoc.getElementsByTagName("INDIVIDUAL");
  for (let i = 0; i < individuals.length; i++) {
    entries.push(parseIndividual(individuals[i]));
  }

  const entities = xmlDoc.getElementsByTagName("ENTITY");
  for (let i = 0; i < entities.length; i++) {
    entries.push(parseEntity(entities[i]));
  }

  return entries;
};

const getNodeVal = (parent: Element, tagName: string): string => {
  const node = parent.getElementsByTagName(tagName)[0];
  return node ? node.textContent?.trim() || '' : '';
};

const parseIndividual = (node: Element): SanctionEntry => {
  const dataId = getNodeVal(node, "DATAID");
  return {
    dataId: `UN-${dataId}`,
    source: 'UN Consolidated',
    firstName: getNodeVal(node, "FIRST_NAME"),
    secondName: getNodeVal(node, "SECOND_NAME"),
    thirdName: getNodeVal(node, "THIRD_NAME"),
    lastName: '', 
    unListType: getNodeVal(node, "UN_LIST_TYPE"),
    referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
    listedOn: getNodeVal(node, "LISTED_ON"),
    comments: getNodeVal(node, "COMMENTS1"),
    nationality: node.getElementsByTagName("NATIONALITY")[0] ? getNodeVal(node.getElementsByTagName("NATIONALITY")[0], "VALUE") : '',
    dateOfBirth: node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0] ? getNodeVal(node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0], "DATE") : '',
    aliases: Array.from(node.getElementsByTagName("INDIVIDUAL_ALIAS")).map(a => getNodeVal(a, "ALIAS_NAME")).filter(Boolean),
    type: EntityType.INDIVIDUAL,
    fetchDate: new Date().toISOString()
  };
};

const parseEntity = (node: Element): SanctionEntry => {
  const dataId = getNodeVal(node, "DATAID");
  return {
    dataId: `UN-${dataId}`,
    source: 'UN Consolidated',
    firstName: getNodeVal(node, "FIRST_NAME"),
    lastName: '',
    unListType: getNodeVal(node, "UN_LIST_TYPE"),
    referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
    listedOn: getNodeVal(node, "LISTED_ON"),
    comments: getNodeVal(node, "COMMENTS1"),
    nationality: '',
    aliases: Array.from(node.getElementsByTagName("ENTITY_ALIAS")).map(a => getNodeVal(a, "ALIAS_NAME")).filter(Boolean),
    type: EntityType.CORPORATE,
    fetchDate: new Date().toISOString()
  };
};

/**
 * High-level fetcher that attempts to detect format and parse accordingly
 */
export const fetchAndNormalize = async (url: string, sourceName: string): Promise<SanctionEntry[]> => {
  try {
    const proxyResponse = await fetch(`${PROXY_URL}${encodeURIComponent(url)}`);
    if (!proxyResponse.ok) throw new Error("Connectivity failed. Source host unreachable via proxy.");

    const json = await proxyResponse.json();
    const content = json.contents;
    if (!content) throw new Error("Source returned empty payload.");

    const format = detectFormat(content);

    switch (format) {
      case 'XML':
        return parseUNSanctionsXML(content);
      case 'JSON':
        return parseJSONToSanctions(content, sourceName);
      case 'CSV':
        return parseCSVToSanctions(content, sourceName);
      default:
        throw new Error(`Unrecognized data structure at ${sourceName}. Parsers need updating.`);
    }
  } catch (error: any) {
    console.error(`Fetch Failure [${sourceName}]:`, error);
    throw error;
  }
};

