        const count = await fetchSanctionsTotalCount();
        setTotalInDb(count);
        const logs = await fetchIngestionLogs();
        setIngestionHistory(logs);
        return count;
      } catch (e) { return 0; }
    }
    return 0;
  }, [isCloudConnected]);

  useEffect(() => {
    refreshDbStats();
  }, [refreshDbStats]);

  const handleManualImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isCloudConnected) return;

    // Security & In-memory validation
    if (file.size > 10 * 1024 * 1024) {
      addLog("File size exceeds 10MB limit. Rejected for security.", "error");
      return;
    }

    setStatus('VALIDATING');
    setUploadProgress(0);
    setErrorMessage(null);
    setSuccessReport(null);
    addLog(`Scanning & Ingesting: ${file.name}`);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result as string;
        const format = detectFormat(content, file.name);
        let parsedData: SanctionEntry[] = [];
        const sourceName = file.name.split('.')[0].toUpperCase();

        if (format === 'XML') parsedData = parseUNSanctionsXML(content);
        else if (format === 'JSON') parsedData = parseJSONToSanctions(content, sourceName);
        else if (format === 'CSV') parsedData = parseCSVToSanctions(content, sourceName);
        else throw new Error("Format validation failed. Use CSV, JSON, or XML.");

        if (parsedData.length === 0) throw new Error("Inconsistent structure detected. Check mandatory fields.");

        addLog(`Integrity Verified. ${parsedData.length} records parsed.`, 'success');
        setStatus('UPLOADING');

        await setGlobalSyncLock(true, 'Manual Upload...');
        await upsertCloudSanctions(parsedData, (p) => setUploadProgress(p));

        const now = new Date().toLocaleString();
        await setGlobalSyncLock(false, now);
        setLastSourceUpdate(now);
        setSuccessReport({ source: sourceName, count: parsedData.length, type: 'Manual', method: 'Upload' });

        await logIngestionEvent({
          timestamp: new Date().toISOString(),
          source: sourceName,
          method: 'Manual',
          status: 'Success',
          recordsProcessed: parsedData.length,
          recordsAccepted: parsedData.length,
          recordsRejected: 0,
          details: `Manual file upload: ${file.name}`,
          triggeredBy: 'Current User'
        });

        const newTotal = await refreshDbStats();
        setTargetRecords(newTotal);
        setStatus('COMPLETED');
        addLog("Persistence successful. Registry updated.", 'success');
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMessage(err.message);
        addLog(`Ingestion Failure: ${err.message}`, 'error');
        await logIngestionEvent({
          timestamp: new Date().toISOString(),
          source: file.name,
          method: 'Manual',
          status: 'Failed',
          recordsProcessed: 0,
          recordsAccepted: 0,
          recordsRejected: 0,
          details: `Upload failed: ${err.message}`,
          triggeredBy: 'Current User',
          errorReason: err.message
        });
      }
    };
    reader.readAsText(file);
  };

  const automatedSync = async (url: string, name: string) => {
    if (!isCloudConnected || isGlobalSyncing) return;

    setStatus('FETCHING');
    setUploadProgress(0);
    setErrorMessage(null);
    setSuccessReport(null);
    addLog(`Handshaking with ${name} API...`);

    try {
      await setGlobalSyncLock(true, `Syncing ${name}...`);
      const liveData = await fetchAndNormalize(url, name);
      addLog(`Connectivity Valid. ${liveData.length} entries retrieved.`, 'success');

      setStatus('UPLOADING');
      await upsertCloudSanctions(liveData, (p) => setUploadProgress(p));

      const now = new Date().toLocaleString();
      await setGlobalSyncLock(false, now);
      setLastSourceUpdate(now);
      setSuccessReport({ source: name, count: liveData.length, type: 'Automated', method: 'Direct Fetch' });

      await logIngestionEvent({
        timestamp: new Date().toISOString(),
        source: name,
        method: 'Automated',
        status: 'Success',
        recordsProcessed: liveData.length,
        recordsAccepted: liveData.length,
        recordsRejected: 0,
        details: `Automated sync from ${url}`,
        triggeredBy: 'System'
      });

      const newTotal = await refreshDbStats();
      setTargetRecords(newTotal);
      setStatus('COMPLETED');
      addLog(`Master Registry synchronized with ${name}.`, 'success');
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate); 
      setErrorMessage(`Source Failure: ${err.message}. Fallback to manual download required.`);
      setStatus('ERROR');
      addLog(`Handshake Error: ${err.message}`, 'error');
      await logIngestionEvent({
        timestamp: new Date().toISOString(),
        source: name,
        method: 'Automated',
        status: 'Failed',
        recordsProcessed: 0,
        recordsAccepted: 0,
        recordsRejected: 0,
        details: `Fetch failed: ${err.message}`,
        triggeredBy: 'System',
        errorReason: err.message
      });
    }
  };

  const runLocalSync = useCallback(async (offset: number) => {
    if (!isRunningRef.current || isPausedRef.current) return;

    try {
      setStatus('FETCHING');
      const batch = await fetchSanctionsBatch(offset, BATCH_SIZE);

      if (batch.length === 0) {
        setStatus('COMPLETED');
        isRunningRef.current = false;
        addLog("Local node verification complete.", 'success');
        return;
      }

      setSanctions(prev => {
        const merged = [...prev, ...batch];
        const unique = Array.from(new Set(merged.map(s => s.dataId))).map(id => merged.find(s => s.dataId === id)!);
        onSyncComplete(unique, { lastFetch: new Date().toLocaleString(), lastTest: 'Validated', lastSourceUpdate });
        return unique;
      });

      const nextOffset = offset + batch.length;
      setCurrentOffset(nextOffset);

      if (nextOffset >= totalInDb) {
        setStatus('COMPLETED');
        isRunningRef.current = false;
        addLog("Consensus Verification Finished.", 'success');
      } else {
        runLocalSync(nextOffset);
      }
    } catch (err: any) {
      setErrorMessage(err.message);
      setStatus('ERROR');
      isRunningRef.current = false;
    }
  }, [totalInDb, onSyncComplete, lastSourceUpdate]);

  const handleStartSequencer = () => {
    if (!isCloudConnected || isGlobalSyncing) return;
    setErrorMessage(null);
    isRunningRef.current = true;
    isPausedRef.current = false;
    runLocalSync(currentOffset);
  };

  const filtered = sanctions.filter(s => 
    s.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.source?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.referenceNumber?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const paginatedData = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">

      {/* METHOD SELECTOR & STATUS CARDS */}
      <div className="grid grid-cols-1 xl:grid-cols-4 gap-8">

        {/* Method 1: Automated Sync Controls */}
        <div className="xl:col-span-3 bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col justify-between space-y-8">
           <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div className="flex items-center gap-4">
                <div className="bg-blue-600 p-4 rounded-2xl text-white shadow-lg">
                  <CloudDownload size={28} />
                </div>
                <div>
                  <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">Data Ingestion Engine</h2>
                  <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Method 1: Direct Integration</p>
                </div>
              </div>
              <button 
                onClick={() => setShowHistory(!showHistory)}
                className="flex items-center gap-2 px-4 py-2 bg-slate-50 text-slate-500 rounded-xl hover:bg-slate-100 transition-all font-black text-[9px] uppercase tracking-widest"
              >
                <History size={16} /> {showHistory ? 'Hide' : 'Audit'} Logs
              </button>
           </div>

           <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
              {[
                { name: 'UN Consolidated', url: OFFICIAL_UN_XML_URL, icon: <Globe />, color: 'blue', desc: 'XML Feed' },
                { name: 'Qatar NCTC', url: QATAR_NCTC_URL, icon: <ShieldAlert />, color: 'amber', desc: 'Unified List' },
                { name: 'OpenSanctions', url: OPENSANCTIONS_URL, icon: <FileJson />, color: 'emerald', desc: 'JSON API' }
              ].map(source => (
                <div key={source.name} className="p-6 rounded-[2rem] border border-slate-100 flex flex-col gap-5 hover:border-blue-200 transition-all group relative overflow-hidden">
                   <div className="flex justify-between items-start relative z-10">
                      <div className={`p-4 rounded-2xl bg-slate-50 text-slate-400 group-hover:bg-blue-600 group-hover:text-white transition-all`}>
                        {React.cloneElement(source.icon as any, { size: 24 })}
                      </div>
                      <button 
                        onClick={() => automatedSync(source.url, source.name)}
                        disabled={!isCloudConnected || isGlobalSyncing || status === 'FETCHING' || status === 'UPLOADING'}
                        className="p-3 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white transition-all disabled:opacity-30"
                      >
                         <Play size={16} />
                      </button>
                   </div>
                   <div className="relative z-10">
                      <h4 className="text-xs font-black uppercase text-slate-800">{source.name}</h4>
                      <p className="text-[9px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{source.desc}</p>
                   </div>
                   <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:scale-110 transition-transform pointer-events-none">
                      {React.cloneElement(source.icon as any, { size: 80 })}
                   </div>
                </div>
              ))}
           </div>

           {/* Feedback Reports */}
           {successReport && (
             <div className="p-6 bg-emerald-50 border border-emerald-100 rounded-[2.5rem] flex items-center justify-between animate-in zoom-in-95">
                <div className="flex items-center gap-4">
                   <div className="p-4 bg-emerald-600 text-white rounded-2xl"><CheckCircle size={24}/></div>
                   <div>
                      <p className="text-[10px] font-black text-emerald-900 uppercase">Successful Ingestion</p>
                      <h4 className="text-sm font-black text-emerald-950">{successReport.count.toLocaleString()} New/Updated Records Committed</h4>
                      <p className="text-[9px] font-bold text-emerald-600 uppercase mt-1">{successReport.source} • {successReport.method} Mode</p>
                   </div>
                </div>
                <div className="hidden sm:flex flex-col items-end">
                   <p className="text-[8px] font-black text-emerald-600 uppercase">Persistence</p>
                   <p className="text-[10px] font-black text-emerald-900 uppercase">Verified Master</p>
                </div>
             </div>
           )}

           {errorMessage && (
             <div className="p-6 bg-red-50 border border-red-100 rounded-[2.5rem] flex items-start gap-4 animate-in slide-in-from-top-2">
                <div className="p-4 bg-red-600 text-white rounded-2xl shrink-0"><FileWarning size={24}/></div>
                <div className="flex-1">
                   <p className="text-[10px] font-black text-red-900 uppercase">Ingestion Fault Detected</p>
                   <p className="text-xs font-bold text-red-700 mt-1 leading-relaxed">{errorMessage}</p>
                   <div className="mt-4 flex flex-col sm:flex-row gap-4 items-center">
                      <p className="text-[8px] font-black text-red-400 uppercase tracking-widest">Resolution: Use Method 2 (Manual Injection) to bypass node restrictions.</p>
                      <button onClick={() => setErrorMessage(null)} className="text-[8px] font-black uppercase text-red-700 hover:underline">Dismiss</button>
                   </div>
                </div>
             </div>
           )}
        </div>

        {/* Method 2: Manual Data Upload */}
        <div className="bg-slate-950 p-8 rounded-[3rem] text-white flex flex-col justify-between shadow-2xl relative overflow-hidden">
           <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none text-blue-500">
              <Database size={160} />
           </div>

           <div className="relative z-10 space-y-6">
              <div className="flex items-center gap-3">
                 <div className="bg-white/10 p-2.5 rounded-xl"><Upload size={18} className="text-emerald-400" /></div>
                 <h3 className="text-xs font-black uppercase tracking-widest">Method 2: Manual Injection</h3>
              </div>

              <p className="text-[10px] text-white/40 font-bold uppercase leading-relaxed">
                 Inject local compliance files directly into the master registry. Supports CSV, XML, and JSON formats.
              </p>

              <div className="space-y-4 pt-4">
                 <div className="flex justify-between items-center py-3 border-b border-white/5">
                    <span className="text-[9px] font-black text-white/40 uppercase">Max File Limit</span>
                    <span className="text-[10px] font-black text-white uppercase">10MB</span>
                 </div>
                 <div className="flex justify-between items-center py-3 border-b border-white/5">
                    <span className="text-[9px] font-black text-white/40 uppercase">Registry Lock</span>
                    <span className={`px-2 py-0.5 rounded-md text-[8px] font-black uppercase ${isGlobalSyncing ? 'bg-amber-500 text-black' : 'bg-emerald-500 text-white'}`}>
                       {isGlobalSyncing ? 'LOCKED' : 'OPEN'}
                    </span>
                 </div>
              </div>
           </div>

           <div className="relative z-10 mt-8 space-y-4">
              <input type="file" ref={fileInputRef} onChange={handleManualImport} accept=".xml,.json,.csv" className="hidden" />
              <button 
                onClick={() => fileInputRef.current?.click()}
                disabled={isGlobalSyncing || status === 'FETCHING' || status === 'UPLOADING' || status === 'VALIDATING'}
                className="w-full py-5 bg-white text-black rounded-[1.5rem] font-black text-[11px] uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:bg-slate-200 transition-all shadow-xl disabled:opacity-30 group"
              >
                 {status === 'VALIDATING' ? <Loader2 size={18} className="animate-spin" /> : <Database size={18} />}
                 {status === 'VALIDATING' ? 'Scanning File...' : 'Begin Injection'}
              </button>

              {(status === 'UPLOADING' || status === 'IMPORTING') && (
                <div className="space-y-3 animate-in fade-in pt-4">
                   <div className="flex justify-between text-[9px] font-black uppercase text-emerald-400">
                      <span>Persistence Protocol</span>
                      <span>{uploadProgress}%</span>
                   </div>
                   <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden">
                      <div className="h-full bg-emerald-400 transition-all duration-300 shadow-[0_0_10px_#10b981]" style={{ width: `${uploadProgress}%` }} />
                   </div>
                   <p className="text-[8px] font-black text-white/30 uppercase text-center animate-pulse">Synchronizing Distributed Ledger...</p>
                </div>
              )}
           </div>
        </div>
      </div>

      {/* AUDIT LOGS OVERLAY */}
      {showHistory && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm animate-in slide-in-from-top-4">
           <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                 <History className="text-slate-400" size={24} />
                 <h3 className="text-sm font-black uppercase text-slate-900">Ingestion Audit History</h3>
              </div>
              <button onClick={() => refreshDbStats()} className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:text-blue-600 transition-all"><RefreshCw size={20}/></button>
           </div>
           <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left min-w-[800px]">
                 <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest">
                    <tr>
                       <th className="px-6 py-4">Timestamp</th>
                       <th className="px-6 py-4">Source</th>
                       <th className="px-6 py-4">Method</th>
                       <th className="px-6 py-4">Status</th>
                       <th className="px-6 py-4 text-right">Processed</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-50">
                    {ingestionHistory.map(log => (
                       <tr key={log.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 text-[10px] font-bold text-slate-900">{new Date(log.timestamp).toLocaleString()}</td>
                          <td className="px-6 py-4 text-[10px] font-black text-slate-800 uppercase">{log.source}</td>
                          <td className="px-6 py-4 text-[9px] font-bold text-slate-500 uppercase">{log.method}</td>
                          <td className="px-6 py-4">
                             <span className={`px-2 py-1 rounded-md text-[8px] font-black uppercase ${log.status === 'Success' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>{log.status}</span>
                          </td>
                          <td className="px-6 py-4 text-right text-[10px] font-black text-slate-900">{log.recordsProcessed.toLocaleString()}</td>
                       </tr>
                    ))}
                    {ingestionHistory.length === 0 && (
                       <tr><td colSpan={5} className="py-12 text-center text-[10px] font-black text-slate-400 uppercase">No recent ingestion events recorded</td></tr>
                    )}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {/* NODE SYNCHRONIZER (CACHING) */}
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col lg:flex-row gap-8 items-start lg:items-center">
         <div className="flex-1 space-y-2">
            <div className="flex items-center gap-3">
               <Activity className="text-blue-600" size={20} />
               <h3 className="text-sm font-black uppercase text-slate-900">Distributed Node Cache</h3>
            </div>
            <p className="text-[10px] text-gray-400 font-bold uppercase leading-relaxed">Local copy contains {sanctions.length.toLocaleString()} records. Master registry reports {totalInDb.toLocaleString()} sanctioned identities.</p>
         </div>
         <div className="flex items-center gap-3 w-full lg:w-auto">
            {status === 'FETCHING' ? (
              <button onClick={() => { isPausedRef.current = true; setStatus('PAUSED'); }} className="flex-1 lg:flex-none p-4 bg-amber-600 text-white rounded-2xl shadow-lg"><Pause size={20}/></button>
            ) : (
              <button 
                onClick={handleStartSequencer} 
                disabled={isGlobalSyncing || (currentOffset >= totalInDb && status !== 'IDLE')}
                className="flex-1 lg:flex-none flex items-center justify-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all shadow-xl disabled:opacity-30 group"
              >
                <Activity size={18} className="group-hover:rotate-180 transition-transform duration-500" /> 
                {status === 'PAUSED' ? 'Resume Verification' : 'Verify Node Continuity'}
              </button>
            )}
            <button 
               onClick={() => { 
                 setSanctions([]); 
                 setCurrentOffset(0); 
                 setStatus('IDLE'); 
                 onSyncComplete([], { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate });
               }} 
               className="p-4 bg-gray-50 text-gray-400 rounded-2xl hover:bg-red-50 hover:text-red-600 transition-all"
               title="Flush Cache"
            >
               <Trash2 size={20} />
            </button>
         </div>
      </div>

      {/* REGISTRY EXPLORER */}
      <div className="space-y-6">
        <div className="bg-white p-4 rounded-[2.5rem] shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
            <input 
              type="text" 
              placeholder="Search synchronized node cache (Name, Reference, Nationality)..." 
              className="w-full pl-16 pr-6 py-5 bg-gray-50/50 border-none rounded-[1.8rem] outline-none text-xs font-bold placeholder-gray-400" 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
            />
          </div>
          <div className="flex items-center gap-4 px-6 border-l border-gray-100 hidden sm:flex">
             <div className="text-right">
                <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Search Scope</p>
                <p className="text-[10px] font-black text-slate-900 uppercase">{filtered.length.toLocaleString()} Hits</p>
             </div>
             <ListChecks className="text-blue-600" size={20} />
          </div>
        </div>

        <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left border-collapse min-w-[1000px]">
              <thead className="bg-gray-50/50 border-b border-gray-100">
                <tr>
                  <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Origin Source</th>
                  <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Identified Persona / Entity</th>
                  <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Jurisdiction</th>
                  <th className="px-10 py-7 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Reference Protocol</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {paginatedData.map((entry) => (
                  <tr key={entry.dataId} className="hover:bg-blue-50/20 transition-colors group">
                    <td className="px-10 py-6">
                       <span className="px-3 py-1.5 rounded-xl text-[8px] font-black uppercase border border-slate-100 text-slate-500 bg-white group-hover:border-blue-200 group-hover:text-blue-800 transition-all flex items-center gap-2 w-fit">
                          <Globe size={10} /> {entry.source}
                       </span>
                    </td>
                    <td className="px-10 py-6">
                       <div className="font-black text-slate-900 text-base leading-tight group-hover:text-blue-900 transition-colors">{entry.firstName} {entry.lastName}</div>
                       <div className="flex items-center gap-2 mt-1.5">
                          <span className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{entry.unListType}</span>
                          <span className="h-1 w-1 bg-slate-200 rounded-full" />
                          <span className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">Ingested: {entry.fetchDate ? new Date(entry.fetchDate).toLocaleDateString() : 'N/A'}</span>
                       </div>
                    </td>
                    <td className="px-10 py-6">
                       <span className="font-black text-[10px] text-slate-600 uppercase tracking-widest">{entry.nationality || 'UNDISCLOSED'}</span>
                    </td>
                    <td className="px-10 py-6 text-right">
                       <p className="text-[11px] text-slate-400 font-mono font-bold uppercase">{entry.referenceNumber}</p>
                       <p className="text-[7px] text-slate-300 font-black uppercase tracking-widest mt-0.5">Hash: {entry.dataId.split('-').pop()}</p>
                    </td>
                  </tr>
                ))}
                {paginatedData.length === 0 && (
                   <tr>
                      <td colSpan={4} className="px-10 py-40 text-center bg-gray-50/10">
                         <div className="flex flex-col items-center gap-6 opacity-30">
                            <BarChart3 size={64} strokeWidth={1} />
                            <div className="space-y-2">
                               <p className="text-[11px] font-black uppercase tracking-[0.4em]">Local Cache Synchronizer Empty</p>
                               <p className="text-[9px] font-bold uppercase">Begin Method 1 or 2 to populate registry</p>
                            </div>
                         </div>
                      </td>
                   </tr>
                )}
              </tbody>
            </table>
          </div>
          {filtered.length > 0 && (
            <div className="px-10 py-8 border-t border-gray-50 flex flex-col sm:flex-row items-center justify-between bg-gray-50/30 gap-6">
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-4">
                 <span>Batch {currentPage} / {totalPages}</span>
                 <span className="h-1 w-1 bg-slate-300 rounded-full" />
                 <span className="text-blue-600">Enterprise Mode Active</span>
              </div>
              <div className="flex items-center gap-3">
                <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="p-4 bg-white border border-gray-200 rounded-2xl disabled:opacity-30 shadow-sm hover:border-blue-500 transition-all"><ChevronLeft size={20} /></button>
                <div className="px-6 py-4 bg-white text-[10px] font-black uppercase tracking-widest border border-slate-100 rounded-2xl shadow-sm min-w-[100px] text-center">Page {currentPage}</div>
                <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} disabled={currentPage === totalPages} className="p-4 bg-white border border-gray-200 rounded-2xl disabled:opacity-30 shadow-sm hover:border-blue-500 transition-all"><ChevronRight size={20} /></button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

