import * as XLSX from 'xlsx';

export const OFFICIAL_UN_XML_URL = "https://scsanctions.un.org/resources/xml/en/consolidated.xml";
export const QATAR_NCTC_URL = "https://portal.moi.gov.qa/wps/portal/NCTC/sanctionlist/unifiedsanctionlist/";
export const OPENSANCTIONS_URL = "https://www.opensanctions.org/datasets/default/entities.json";
export const OFAC_SDN_URL = "https://www.treasury.gov/ofac/downloads/sdn.csv";

const PROXY_URL = "https://api.allorigins.win/get?url=";

/**
 * Normalizes sanction types
 */
const mapToEntityType = (rawType: string): string => {
  const t = (rawType || '').toLowerCase();
  if (t.includes('individual') || t.includes('person')) return EntityType.INDIVIDUAL;
  return EntityType.CORPORATE;
};

/**
 * Parses XLSX/XLS data
 */
export const parseExcelToSanctions = (buffer: ArrayBuffer, sourceName: string): any[] => {
  const workbook = XLSX.read(buffer, { type: 'array' });
  const firstSheetName = workbook.SheetNames[0];
  const worksheet = workbook.Sheets[firstSheetName];
  return XLSX.utils.sheet_to_json(worksheet);
};

/**
 * Field mapping utility to transform arbitrary objects to SanctionEntry
 */
export const mapFieldsToSanction = (raw: any, mapping: Record<string, string>, source: string): SanctionEntry => {
  return {
    dataId: `${source}-${raw[mapping.dataId] || Math.random().toString(36).substr(2, 9)}`,
    source: source,
    firstName: raw[mapping.firstName] || 'Unknown',
    lastName: raw[mapping.lastName] || '',
    unListType: raw[mapping.unListType] || 'Manual Entry',
    referenceNumber: raw[mapping.referenceNumber] || '',
    listedOn: raw[mapping.listedOn] || new Date().toISOString().split('T')[0],
    comments: raw[mapping.comments] || '',
    nationality: raw[mapping.nationality] || '',
    aliases: Array.isArray(raw[mapping.aliases]) ? raw[mapping.aliases] : (raw[mapping.aliases] ? [raw[mapping.aliases]] : []),
    type: mapToEntityType(raw[mapping.type]),
    fetchDate: new Date().toISOString()
  };
};

export const detectFormat = (content: string, fileName?: string): 'XML' | 'JSON' | 'CSV' | 'EXCEL' | 'UNKNOWN' => {
  if (fileName?.match(/\.(xlsx|xls)$/i)) return 'EXCEL';
  const trimmed = content.trim();
  if (trimmed.startsWith('<?xml') || trimmed.startsWith('<')) return 'XML';
  if (trimmed.startsWith('{') || trimmed.startsWith('[')) return 'JSON';
  if (trimmed.includes(',') && trimmed.split('\n')[0].includes(',')) return 'CSV';
  return 'UNKNOWN';
};

export const parseCSVToSanctions = (csv: string, sourceName: string): any[] => {
  const lines = csv.split(/\r?\n/);
  if (lines.length < 2) return [];
  const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
  return lines.slice(1).filter(l => l.trim()).map(line => {
    const values = line.split(',').map(v => v.trim());
    const obj: any = {};
    headers.forEach((h, i) => { obj[h] = values[i]; });
    return obj;
  });
};

export const parseUNSanctionsXML = (xmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlString, "text/xml");
  const entries: SanctionEntry[] = [];

  const parseNode = (node: Element, isInd: boolean): SanctionEntry => {
    const getVal = (tag: string) => node.getElementsByTagName(tag)[0]?.textContent?.trim() || '';
    return {
      dataId: `UN-${getVal("DATAID")}`,
      source: 'UN Consolidated',
      firstName: getVal("FIRST_NAME"),
      secondName: getVal("SECOND_NAME"),
      thirdName: getVal("THIRD_NAME"),
      lastName: '',
      unListType: getVal("UN_LIST_TYPE"),
      referenceNumber: getVal("REFERENCE_NUMBER"),
      listedOn: getVal("LISTED_ON"),
      comments: getVal("COMMENTS1"),
      nationality: node.getElementsByTagName("NATIONALITY")[0] ? node.getElementsByTagName("NATIONALITY")[0].getElementsByTagName("VALUE")[0]?.textContent || '' : '',
      dateOfBirth: isInd ? (node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0]?.getElementsByTagName("DATE")[0]?.textContent || '') : '',
      aliases: Array.from(node.getElementsByTagName(isInd ? "INDIVIDUAL_ALIAS" : "ENTITY_ALIAS")).map(a => a.getElementsByTagName("ALIAS_NAME")[0]?.textContent || '').filter(Boolean),
      type: isInd ? EntityType.INDIVIDUAL : EntityType.CORPORATE,
      fetchDate: new Date().toISOString()
    };
  };

  const individuals = xmlDoc.getElementsByTagName("INDIVIDUAL");
  for (let i = 0; i < individuals.length; i++) entries.push(parseNode(individuals[i], true));
  const entities = xmlDoc.getElementsByTagName("ENTITY");
  for (let i = 0; i < entities.length; i++) entries.push(parseNode(entities[i], false));

  return entries;
};

export const fetchAndNormalize = async (url: string, sourceName: string): Promise<SanctionEntry[]> => {
  try {
    const proxyResponse = await fetch(`${PROXY_URL}${encodeURIComponent(url)}`);
    if (!proxyResponse.ok) throw new Error("CORS Proxy Failure: Target host unreachable.");
    const json = await proxyResponse.json();
    const content = json.contents;
    if (!content) throw new Error("Empty payload from source.");

    const format = detectFormat(content);
    if (format === 'XML' && sourceName === 'UN Consolidated') return parseUNSanctionsXML(content);

    // Default fallback for other sources: try to parse as JSON or CSV
    if (format === 'JSON') {
        const data = JSON.parse(content);
        const entities = Array.isArray(data) ? data : (data.entities || data.results || []);
        return entities.map((e: any, i: number) => ({
            dataId: `${sourceName}-${e.id || i}`,
            source: sourceName,
            firstName: e.name || e.first_name || 'Unknown',
            lastName: e.last_name || '',
            unListType: 'Automated Feed',
            referenceNumber: e.id || '',
            listedOn: e.listed_on || new Date().toISOString(),
            comments: e.notes || '',
            nationality: e.nationality || '',
            aliases: e.aliases || [],
            type: mapToEntityType(e.type || e.schema),
            fetchDate: new Date().toISOString()
        }));
    }

    throw new Error(`Auto-parser for ${sourceName} format ${format} is under development. Use Manual Injection.`);
  } catch (error: any) {
    throw error;
  }
};

