      const now = new Date().toLocaleString();
      await setGlobalSyncLock(false, now);
      setLastSourceUpdate(now);

      setSuccessReport({
        source: source,
        count: count,
        method: method,
        newRecords: Math.floor(count * 0.1), // Simulated heuristic
        updatedRecords: Math.floor(count * 0.9)
      });

