        timestamp: new Date().toISOString(),
        source: source,
        method: method === 'Direct Fetch' ? 'Automated' : 'Manual',
        status: 'Success',
        recordsProcessed: count,
        recordsAccepted: count,
        recordsRejected: 0,
        details: `${method} from ${source} finalized.`,
        triggeredBy: currentUser?.id || 'System'
      });

      await refreshDbStats();
      setStatus('COMPLETED');
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate);
      setErrorMessage(err.message);
      setStatus('ERROR');
      await logIngestionEvent({
        timestamp: new Date().toISOString(),
        source: source,
        method: method === 'Direct Fetch' ? 'Automated' : 'Manual',
        status: 'Failed',
        recordsProcessed: 0,
        recordsAccepted: 0,
        recordsRejected: 0,
        details: `Failed: ${err.message}`,
        triggeredBy: currentUser?.id || 'System',
        errorReason: err.message
      });
    }
  };

  const handleMappingCommit = () => {
