/**
 * Detects the data format based on file content or name
 */
export const detectFormat = (content: string, fileName: string): 'XML' | 'CSV' | 'JSON' | 'EXCEL' | 'UNKNOWN' => {
  const ext = fileName.split('.').pop()?.toLowerCase();
  if (ext === 'xlsx' || ext === 'xls') return 'EXCEL';
  if (ext === 'xml' || content.trim().startsWith('<')) return 'XML';
  if (ext === 'json' || content.trim().startsWith('{') || content.trim().startsWith('[')) return 'JSON';
  if (ext === 'csv') return 'CSV';
  return 'UNKNOWN';
};

