  try {
    const sessionStr = localStorage.getItem('unsg_session');
    if (!sessionStr) return false;

    const session = JSON.parse(sessionStr);
    if (session.id !== 'SYS-ROOT') return false;

    const settings = JSON.parse(localStorage.getItem('unsg_settings') || '{}');
    return settings.environment === SystemEnvironment.SANDBOX;
  } catch (e) {
    return false;
  }
};

