                     <span className="inline-flex items-center px-2 py-1 rounded-lg text-[8px] font-black uppercase border bg-white border-gray-100 text-gray-500 group-hover:border-emerald-200 group-hover:text-emerald-800 transition-all">
                        {entry.source}
                     </span>
                  </td>
                  <td className="px-6 py-4">
