                  <td className="px-6 py-4">
                    <span className="px-2.5 py-1 rounded-md text-[9px] font-black uppercase bg-gray-50 text-gray-500 border border-gray-100">
                      {entry.unListType}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-xs font-black text-gray-600 uppercase tracking-tight">{entry.nationality || 'Unspecified'}</td>
                  <td className="px-6 py-4 text-right text-[10px] text-gray-400 font-bold uppercase">{entry.listedOn || 'Permanent'}</td>
                </tr>
              ))}
              {paginatedData.length === 0 && (
                <tr>
                   <td colSpan={5} className="px-6 py-20 text-center bg-gray-50/10">
                      <div className="flex flex-col items-center gap-4 text-gray-300">
                         <Database size={48} strokeWidth={1}/>
                         <p className="text-xs font-black uppercase tracking-widest text-center px-4">Zero Registry Matches for "{searchTerm}"</p>
                         <p className="text-[10px] text-slate-400 font-bold mt-2 uppercase">Please ensure the latest data file has been imported.</p>
                      </div>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {filtered.length > 0 && (
          <div className="px-6 py-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-gray-50/30">
            <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">
              Page <span className="text-emerald-950">{currentPage}</span> of {totalPages} <span className="mx-2 hidden sm:inline">•</span> <span className="block sm:inline mt-1 sm:mt-0">{filtered.length.toLocaleString()} Records Loaded</span>
              {totalInDb > filtered.length && (
                <span className="block mt-1 text-[8px] text-amber-600 font-black">({totalInDb.toLocaleString()} Total in Registry)</span>
              )}
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={() => handlePageChange(1)} 
                disabled={currentPage === 1}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
                title="Jump to First Page"
              >
                <ChevronsLeft size={20} />
              </button>

              <button 
                onClick={() => handlePageChange(currentPage - 1)} 
                disabled={currentPage === 1}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronLeft size={20} />
              </button>

              <div className="px-6 py-3 text-[10px] font-black text-emerald-950 bg-white rounded-xl border border-gray-200 shadow-sm min-w-[120px] text-center uppercase tracking-widest">
                Tier {currentPage}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)} 
                disabled={currentPage === totalPages}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronRight size={20} />
              </button>

              <button 
                onClick={() => handlePageChange(totalPages)} 
                disabled={currentPage === totalPages}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
                title="Jump to Final Page"
              >
                <ChevronsRight size={20} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

