  if (!supabaseClient) return;
  if (isSandbox()) {
    onProgress?.(100);
    return simulateWrite('UpsertCloudSanctions', `${sanctions.length} entries`);
  }
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize);
    try {
      await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'dataId' });
      if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
    } catch (e) { break; }
  }
};

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient.from('profiles').select('*');
    if (error) return (error.code === '42P01') ? [] : null;
    return data;
  } catch (e) { return null; }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('UpsertCloudUser', user.email);
  const dbProfile = {
    id: user.id, email: user.email.toLowerCase().trim(), full_name: user.full_name,
    role_id: user.role, status: user.status || 'Active', is_system_admin: user.is_system_admin === true,
    must_change_password: user.must_change_password, password_expiry: user.password_expiry,
    password_hash_mock: user.password, created_at: user.created_at || new Date().toISOString()
  };
  try {
    const { error } = await supabaseClient.from('profiles').upsert([dbProfile], { onConflict: 'email' });
    if (error) throw new Error(error.message);
  } catch (e: any) { throw e; }
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('DeleteCloudUser', email);
  try { await supabaseClient.from('profiles').delete().eq('email', email.toLowerCase().trim()); } catch (e) {}
};

export const logIngestionEvent = async (event: Omit<IngestionLog, 'id'>) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('LogIngestionEvent', event);
  const fullEvent = { ...event, id: `LOG-${Math.random().toString(36).substr(2, 6).toUpperCase()}` };
  try {
    await supabaseClient.from('ingestion_logs').upsert([fullEvent]);
  } catch (e) {}
};

export const fetchIngestionLogs = async (): Promise<IngestionLog[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient.from('ingestion_logs').select('*').order('timestamp', { ascending: false });
    if (error) return [];
    return data || [];
  } catch (e) { return []; }
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabaseClient) return null;
  try {
    return supabaseClient.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
  } catch (e) { return null; }
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabaseClient && channel) {
    try { await supabaseClient.removeChannel(channel); } catch (e) {}
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsBrowser from './components/SanctionsBrowser';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Loader2 } from 'lucide-react';
import { Client, SanctionEntry, RiskLevel, AppSettings, UserRole, UserProfile, SystemEnvironment } from './types';
import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount,
  fetchSanctionsBatch,
  upsertCloudSanctions,
  fetchClientsTotalCount
} from './services/cloudDb';
import { parseUNSanctionsXML, parseCSVToSanctions, OFFICIAL_UN_XML_URL } from './services/unSanctionsService';
import { screenClient } from './services/screeningEngine';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  environment: SystemEnvironment.PRODUCTION
};

const CLIENTS_PER_PAGE = 15;

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [clientsCount, setClientsCount] = useState(0);
  const [currentClientsPage, setCurrentClientsPage] = useState(1);
  const [isRefreshingClients, setIsRefreshingClients] = useState(false);

  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [isUpdatingSanctions, setIsUpdatingSanctions] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [totalInDb, setTotalInDb] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR'>('CONNECTING');

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    if (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
    }
  }, []);

  const loadSanctionsCache = useCallback(async () => {
    try {
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);
      setSanctionsCount(count);
      const batch = await fetchSanctionsBatch(0, 1000);
      setSanctions(batch);
    } catch (e) {
      console.error("Failed to load sanctions cache", e);
    }
  }, []);

  const refreshClients = useCallback(async (page: number = 1) => {
    setIsRefreshingClients(true);
    try {
      const from = (page - 1) * CLIENTS_PER_PAGE;
      const to = from + CLIENTS_PER_PAGE - 1;
      const [cloudClients, count] = await Promise.all([
        fetchCloudClients(from, to),
        fetchClientsTotalCount()
      ]);
      if (cloudClients) setClients(cloudClients);
      setClientsCount(count);
      setCurrentClientsPage(page);
    } catch (e) {
      console.error("Client refresh failed", e);
    } finally {
      setIsRefreshingClients(false);
    }
  }, []);

  const handleRetrieveIncremental = useCallback(async () => {
    setIsUpdatingSanctions(true);
    try {
      const nextBatch = await fetchSanctionsBatch(sanctions.length, 1000);
      if (nextBatch.length > 0) {
        setSanctions(prev => [...prev, ...nextBatch]);
      }
    } catch (e) {
      console.error("Incremental retrieval failed", e);
    } finally {
      setIsUpdatingSanctions(false);
    }
  }, [sanctions.length]);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');

    try {
      initSupabase();
      const healthy = await checkConnection();

      if (healthy) {
        setConnectionStatus('CONNECTED');
        await Promise.all([
          refreshClients(1),
          loadSanctionsCache(),
          fetchGlobalSyncStatus().then(lockStatus => lockStatus && handleGlobalMetadataUpdate(lockStatus))
        ]);

        if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
        subscriptionRef.current = subscribeToClients(() => {
          refreshClients(currentClientsPage);
        });
        if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
        syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
      } else {
        setConnectionStatus('ERROR');
      }
    } catch (e: any) {
      setConnectionStatus('ERROR');
    }

    setTimeout(() => {
      setIsBooting(false);
    }, 1500);
  }, [handleGlobalMetadataUpdate, loadSanctionsCache, refreshClients, currentClientsPage]);

  useEffect(() => {
    bootEnterpriseNode();
  }, [bootEnterpriseNode]);

  const handleAddClientWithScreening = async (newClient: Client) => {
    const match = screenClient(newClient, sanctions);
    const screenedClient = {
      ...newClient,
      riskLevel: match ? match.riskLevel : RiskLevel.NONE,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };

    if (connectionStatus === 'CONNECTED') {
      try {
        await upsertCloudClient(screenedClient);
        // CRITICAL: Immediately refresh to current page (usually 1) to show new record
        await refreshClients(1); 
      } catch (e) {
        console.error("Failed to persist client:", e);
      }
    } else {
      setClients(prev => [screenedClient, ...prev].slice(0, CLIENTS_PER_PAGE));
      setClientsCount(prev => prev + 1);
    }
  };

  const handleSanctionsFileUpload = async (file: File, type: 'UN' | 'OFAC' | 'OPEN') => {
    setIsUpdatingSanctions(true);
    try {
      const text = await file.text();
      let parsed: SanctionEntry[] = [];

      if (type === 'UN') {
        parsed = parseUNSanctionsXML(text);
      } else if (type === 'OFAC') {
        const rawRows = parseCSVToSanctions(text, 'OFAC SDN');
        parsed = rawRows.map((r: any, i: number) => ({
          dataId: `OFAC-${r.ent_num || i}`,
          source: 'OFAC SDN',
          firstName: r.sdn_name || 'Unknown',
          lastName: '',
          unListType: r.sdn_type || 'Individual',
          referenceNumber: r.ent_num || '',
          listedOn: new Date().toISOString().split('T')[0],
          comments: r.remarks || '',
          nationality: '',
          aliases: [],
          type: r.sdn_type === 'Entity' ? 'Corporate' : 'Individual',
          fetchDate: new Date().toISOString()
        }));
      }

      if (parsed.length > 0) {
        await upsertCloudSanctions(parsed);
        const now = new Date().toLocaleString();
        const stats = { ...registryStats, lastFetch: now, lastSourceUpdate: now };
        setRegistryStats(stats);
        localStorage.setItem('unsg_registry_stats', JSON.stringify(stats));
        await loadSanctionsCache();
      }
    } catch (e) {
      console.error("Manual Import Error:", e);
      alert("Import failed. Verify file structure.");
    } finally {
      setIsUpdatingSanctions(false);
    }
  };

  if (isBooting) {
    return (
      <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-white font-sans">
        <div className="bg-white/5 p-12 rounded-[3.5rem] border border-white/10 flex flex-col items-center gap-10 shadow-2xl animate-pulse">
          <Loader2 className="animate-spin text-emerald-400" size={64} strokeWidth={1.5} />
          <h1 className="text-xs font-black uppercase tracking-[0.5em] text-emerald-50 text-center">SanctionGuard Secure Node v1.8.5</h1>
        </div>
      </div>
    );
  }

  const effectiveEnvironment = (currentUser?.id === 'SYS-ROOT') 
    ? settings.environment 
    : SystemEnvironment.PRODUCTION;

  if (!currentUser) return (
    <Login 
      onLogin={(user) => { 
        setCurrentUser(user); 
        localStorage.setItem('unsg_session', JSON.stringify(user)); 
      }} 
      isCloudConnected={connectionStatus === 'CONNECTED'} 
    />
  );

  if (currentUser.must_change_password) return (
    <PasswordUpdate 
      user={currentUser} 
      onUpdate={async (newPassword) => {
        const updatedUser = { ...currentUser, password: newPassword, must_change_password: false };
        if (connectionStatus === 'CONNECTED') await upsertCloudUser(updatedUser).catch(() => {});
        setCurrentUser(updatedUser);
        localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      }} 
    />
  );

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={() => { 
          setCurrentUser(null); 
          localStorage.removeItem('unsg_session'); 
        }}
        currentUser={currentUser}
        onRetryConnection={() => bootEnterpriseNode()}
        environment={effectiveEnvironment}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              totalCount={clientsCount}
              currentPage={currentClientsPage}
              onPageChange={refreshClients}
              isRefreshing={isRefreshingClients}
              onAddClient={handleAddClientWithScreening} 
              onUpdateClient={async (updated) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(updated);
                setClients(prev => prev.map(c => c.id === updated.id ? updated : c));
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                refreshClients(currentClientsPage);
              }}
              onRefresh={() => refreshClients(currentClientsPage)} 
              currentUserRole={currentUser.role} currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsBrowser 
              sanctions={sanctions}
              lastUpdated={registryStats.lastFetch}
              onRefresh={loadSanctionsCache}
              isUpdating={isUpdatingSanctions}
              onFileUpload={handleSanctionsFileUpload}
              totalInDb={totalInDb}
              onRetrieveIncremental={handleRetrieveIncremental}
            />} />
          <Route path="/admin" element={
            currentUser.is_system_admin === true ? (
              <AdminPanel settings={settings} logs={[]} onUpdateSettings={(s) => {
                setSettings(s);
                localStorage.setItem('unsg_settings', JSON.stringify(s));
              }} currentUser={currentUser} />
            ) : <Navigate to="/" replace />
          } />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

