              <div className="flex flex-col xs:flex-row justify-end gap-3 pb-8 sticky bottom-0 bg-white/90 backdrop-blur-md pt-5 border-t border-gray-100 z-10">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-8 py-4 font-black text-[10px] uppercase tracking-widest text-gray-400 hover:text-gray-600 order-2 xs:order-1">Cancel</button>
                <button type="submit" className="w-full xs:w-auto bg-emerald-800 text-white px-10 py-4 rounded-xl sm:rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-emerald-900 flex justify-center items-center gap-2 order-1 xs:order-2">
                  <CheckCircle2 size={20}/> Commit Entity
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {selectedClient && (
        <div className="fixed inset-0 bg-emerald-950/90 backdrop-blur-2xl z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 overflow-y-auto">
          <div className="bg-white rounded-t-[3rem] sm:rounded-[4rem] w-full max-w-6xl my-0 sm:my-8 overflow-hidden flex flex-col shadow-2xl animate-in slide-in-from-bottom-6 duration-500 h-[95vh] sm:h-auto max-h-[95vh]">
            <div className="p-6 sm:p-12 bg-emerald-950 text-white flex justify-between items-start shrink-0">
              <div className="flex flex-col gap-6">
                <div className="bg-white p-2 sm:p-3 rounded-xl w-fit">
                   <img src={LOCAL_LOGO} alt="RPME" className="h-10 sm:h-16 w-auto object-contain" onError={(e) => { e.currentTarget.src = GITHUB_LOGO; }} />
                </div>
                <div>
                  <h3 className="text-xl sm:text-2xl font-black uppercase tracking-tight line-clamp-2">{selectedClient["Client Name"]}</h3>
                  <p className="text-[9px] text-emerald-400 uppercase font-black tracking-[0.2em] mt-1 opacity-70">Ref: {selectedClient["No"]}</p>
                </div>
              </div>
              <button onClick={() => setSelectedClient(null)} className="p-2 hover:bg-white/10 rounded-full shrink-0"><X size={28}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 sm:p-12 space-y-8 bg-gray-50/20 custom-scrollbar">
               <div className="grid grid-cols-1 xs:grid-cols-3 gap-4 sm:gap-8">
                  <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm text-center">
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2">Standing</p>
                     <p className={`font-black text-xs uppercase ${selectedClient.kyc_status === KYCStatus.APPROVED ? 'text-emerald-600' : 'text-amber-600'}`}>{selectedClient.kyc_status}</p>
                  </div>
                  <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm text-center">
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2">Risk</p>
                     <p className={`font-black text-xs uppercase ${selectedClient.riskLevel === RiskLevel.HIGH ? 'text-red-600' : 'text-emerald-600'}`}>{selectedClient.riskLevel}</p>
                  </div>
                  <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm text-center">
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2">Jurisdiction</p>
                     <p className="font-black text-xs text-emerald-900 uppercase truncate">{selectedClient["Company Nationality"]}</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-6 sm:gap-10 pb-8">
                  <div className="bg-white p-6 sm:p-10 rounded-3xl border border-gray-100 shadow-sm space-y-6">
                    <h4 className="text-[10px] font-black text-emerald-800 uppercase tracking-widest border-b pb-4 flex items-center gap-3"><Landmark size={18}/> Registry Details</h4>
                    <div className="grid grid-cols-2 gap-6">
                      <div><p className="text-[9px] text-gray-400 font-black uppercase mb-1">QFC No</p><p className="text-xs font-black text-emerald-950">{selectedClient["QFC No"] || 'N/A'}</p></div>
                      <div><p className="text-[9px] text-gray-400 font-black uppercase mb-1">Structure</p><p className="text-xs font-black text-emerald-950">{selectedClient["Legal Structure"]}</p></div>
                    </div>
                  </div>
                  <div className="bg-white p-6 sm:p-10 rounded-3xl border border-gray-100 shadow-sm space-y-6">
                    <h4 className="text-[10px] font-black text-emerald-800 uppercase tracking-widest border-b pb-4 flex items-center gap-3"><Mail size={18}/> Official Contact</h4>
                    <div><p className="text-[9px] text-gray-400 font-black uppercase mb-1">Email</p><p className="text-xs font-black text-emerald-950 truncate">{selectedClient["E Mail"]}</p></div>
                    <div><p className="text-[9px] text-gray-400 font-black uppercase mb-1">Address</p><p className="text-xs font-bold text-emerald-950 leading-relaxed">{selectedClient["Registered Address"]}</p></div>
                  </div>
               </div>
            </div>

            <div className="p-6 sm:p-12 bg-white border-t flex flex-col xs:flex-row justify-end gap-3 shrink-0">
               <button onClick={() => window.print()} className="xs:hidden w-full border border-gray-200 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest">Print Record</button>
               <button onClick={() => setSelectedClient(null)} className="w-full xs:w-auto bg-emerald-950 text-white px-12 py-4 rounded-xl sm:rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-900 transition-all">Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClientManager;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsBrowser from './components/SanctionsBrowser';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Loader2 } from 'lucide-react';
import { Client, SanctionEntry, RiskLevel, AppSettings, UserRole, UserProfile, SystemEnvironment } from './types';
import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount,
  fetchSanctionsBatch,
  upsertCloudSanctions,
  fetchClientsTotalCount
} from './services/cloudDb';
import { parseUNSanctionsXML, parseCSVToSanctions, OFFICIAL_UN_XML_URL } from './services/unSanctionsService';
import { screenClient } from './services/screeningEngine';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  environment: SystemEnvironment.PRODUCTION
};

const CLIENTS_PER_PAGE = 15;

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [clientsCount, setClientsCount] = useState(0);
  const [currentClientsPage, setCurrentClientsPage] = useState(1);
  const [isRefreshingClients, setIsRefreshingClients] = useState(false);

  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [isUpdatingSanctions, setIsUpdatingSanctions] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [totalInDb, setTotalInDb] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR'>('CONNECTING');

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    if (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
    }
  }, []);

  const loadSanctionsCache = useCallback(async () => {
    try {
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);
      setSanctionsCount(count);
      const batch = await fetchSanctionsBatch(0, 1000);
      setSanctions(batch);
    } catch (e) {
      console.error("Failed to load sanctions cache", e);
    }
  }, []);

  const refreshClients = useCallback(async (page: number = 1) => {
    setIsRefreshingClients(true);
    try {
      const from = (page - 1) * CLIENTS_PER_PAGE;
      const to = from + CLIENTS_PER_PAGE - 1;
      const [cloudClients, count] = await Promise.all([
        fetchCloudClients(from, to),
        fetchClientsTotalCount()
      ]);
      if (cloudClients) setClients(cloudClients);
      setClientsCount(count);
      setCurrentClientsPage(page);
    } catch (e) {
      console.error("Client refresh failed", e);
    } finally {
      setIsRefreshingClients(false);
    }
  }, []);

  const handleRetrieveIncremental = useCallback(async () => {
    setIsUpdatingSanctions(true);
    try {
      const nextBatch = await fetchSanctionsBatch(sanctions.length, 1000);
      if (nextBatch.length > 0) {
        setSanctions(prev => [...prev, ...nextBatch]);
      }
    } catch (e) {
      console.error("Incremental retrieval failed", e);
    } finally {
      setIsUpdatingSanctions(false);
    }
  }, [sanctions.length]);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');

    try {
      initSupabase();
      const healthy = await checkConnection();

      if (healthy) {
        setConnectionStatus('CONNECTED');
        await Promise.all([
          refreshClients(1),
          loadSanctionsCache(),
          fetchGlobalSyncStatus().then(lockStatus => lockStatus && handleGlobalMetadataUpdate(lockStatus))
        ]);

        if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
        subscriptionRef.current = subscribeToClients(() => {
          refreshClients(currentClientsPage);
        });
        if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
        syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
      } else {
        setConnectionStatus('ERROR');
      }
    } catch (e: any) {
      setConnectionStatus('ERROR');
    }

    setTimeout(() => {
      setIsBooting(false);
    }, 1500);
  }, [handleGlobalMetadataUpdate, loadSanctionsCache, refreshClients, currentClientsPage]);

  useEffect(() => {
    bootEnterpriseNode();
  }, [bootEnterpriseNode]);

  const handleAddClientWithScreening = async (newClient: Client) => {
    const match = screenClient(newClient, sanctions);
    const screenedClient = {
      ...newClient,
      riskLevel: match ? match.riskLevel : RiskLevel.NONE,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };

    if (connectionStatus === 'CONNECTED') {
      try {
        await upsertCloudClient(screenedClient);
        // CRITICAL: Immediately refresh to current page (usually 1) to show new record
        await refreshClients(1); 
      } catch (e) {
        console.error("Failed to persist client:", e);
        throw e; // Propagate to allow UI to handle error
      }
    } else {
      setClients(prev => [screenedClient, ...prev].slice(0, CLIENTS_PER_PAGE));
      setClientsCount(prev => prev + 1);
    }
  };

  const handleSanctionsFileUpload = async (file: File, type: 'UN' | 'OFAC' | 'OPEN') => {
    setIsUpdatingSanctions(true);
    try {
      const text = await file.text();
      let parsed: SanctionEntry[] = [];

      if (type === 'UN') {
        parsed = parseUNSanctionsXML(text);
      } else if (type === 'OFAC') {
        const rawRows = parseCSVToSanctions(text, 'OFAC SDN');
        parsed = rawRows.map((r: any, i: number) => ({
          dataId: `OFAC-${r.ent_num || i}`,
          source: 'OFAC SDN',
          firstName: r.sdn_name || 'Unknown',
          lastName: '',
          unListType: r.sdn_type || 'Individual',
          referenceNumber: r.ent_num || '',
          listedOn: new Date().toISOString().split('T')[0],
          comments: r.remarks || '',
          nationality: '',
          aliases: [],
          type: r.sdn_type === 'Entity' ? 'Corporate' : 'Individual',
          fetchDate: new Date().toISOString()
        }));
      }

      if (parsed.length > 0) {
        await upsertCloudSanctions(parsed);
        const now = new Date().toLocaleString();
        const stats = { ...registryStats, lastFetch: now, lastSourceUpdate: now };
        setRegistryStats(stats);
        localStorage.setItem('unsg_registry_stats', JSON.stringify(stats));
        await loadSanctionsCache();
      }
    } catch (e) {
      console.error("Manual Import Error:", e);
      alert("Import failed. Verify file structure.");
    } finally {
      setIsUpdatingSanctions(false);
    }
  };

  if (isBooting) {
    return (
      <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-white font-sans">
        <div className="bg-white/5 p-12 rounded-[3.5rem] border border-white/10 flex flex-col items-center gap-10 shadow-2xl animate-pulse">
          <Loader2 className="animate-spin text-emerald-400" size={64} strokeWidth={1.5} />
          <h1 className="text-xs font-black uppercase tracking-[0.5em] text-emerald-50 text-center">SanctionGuard Secure Node v1.8.5</h1>
        </div>
      </div>
    );
  }

  const effectiveEnvironment = (currentUser?.id === 'SYS-ROOT') 
    ? settings.environment 
    : SystemEnvironment.PRODUCTION;

  if (!currentUser) return (
    <Login 
      onLogin={(user) => { 
        setCurrentUser(user); 
        localStorage.setItem('unsg_session', JSON.stringify(user)); 
      }} 
      isCloudConnected={connectionStatus === 'CONNECTED'} 
    />
  );

  if (currentUser.must_change_password) return (
    <PasswordUpdate 
      user={currentUser} 
      onUpdate={async (newPassword) => {
        const updatedUser = { ...currentUser, password: newPassword, must_change_password: false };
        if (connectionStatus === 'CONNECTED') await upsertCloudUser(updatedUser).catch(() => {});
        setCurrentUser(updatedUser);
        localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      }} 
    />
  );

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={() => { 
          setCurrentUser(null); 
          localStorage.removeItem('unsg_session'); 
        }}
        currentUser={currentUser}
        onRetryConnection={() => bootEnterpriseNode()}
        environment={effectiveEnvironment}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              totalCount={clientsCount}
              currentPage={currentClientsPage}
              onPageChange={refreshClients}
              isRefreshing={isRefreshingClients}
              onAddClient={handleAddClientWithScreening} 
              onUpdateClient={async (updated) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(updated);
                setClients(prev => prev.map(c => c.id === updated.id ? updated : c));
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                refreshClients(currentClientsPage);
              }}
              onRefresh={() => refreshClients(currentClientsPage)} 
              currentUserRole={currentUser.role} currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsBrowser 
              sanctions={sanctions}
              lastUpdated={registryStats.lastFetch}
              onRefresh={loadSanctionsCache}
              isUpdating={isUpdatingSanctions}
              onFileUpload={handleSanctionsFileUpload}
              totalInDb={totalInDb}
              onRetrieveIncremental={handleRetrieveIncremental}
            />} />
          <Route path="/admin" element={
            currentUser.is_system_admin === true ? (
              <AdminPanel settings={settings} logs={[]} onUpdateSettings={(s) => {
                setSettings(s);
                localStorage.setItem('unsg_settings', JSON.stringify(s));
              }} currentUser={currentUser} />
            ) : <Navigate to="/" replace />
          } />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { Client, RiskLevel, PersonRecord, KYCStatus, EntityType, UserRole } from '../types';
import { 
  Plus, Trash2, Eye, RefreshCw, X, CheckCircle2, Landmark, Users, Mail, FileCheck, Shield, 
  UserPlus, FileText, ArrowRight, ShieldAlert, Printer, Calendar, Briefcase, UserCheck, 
  Gavel, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, Loader2
} from 'lucide-react';

interface FormSectionProps {
  title: string;
  icon: React.ReactNode;
  children?: React.ReactNode;
  fullWidth?: boolean;
}

const FormSection: React.FC<FormSectionProps> = ({ title, icon, children, fullWidth = false }) => (
  <div className="bg-white p-5 sm:p-8 rounded-2xl sm:rounded-[2rem] border border-gray-100 shadow-sm space-y-6">
    <div className="flex items-center gap-4 text-emerald-800 font-black border-b border-gray-50 pb-4">
      <div className="bg-emerald-50 p-2.5 rounded-xl">{icon}</div>
      <span className="text-[10px] uppercase tracking-[0.2em]">{title}</span>
    </div>
    <div className={fullWidth ? "w-full" : "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-5 sm:gap-6"}>{children}</div>
  </div>
);

const InputField = ({ label, value, onChange, type = "text", placeholder = "", required = false }: any) => (
  <div className="space-y-1.5 sm:space-y-2">
    <div className="flex justify-between">
        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block ml-1">{label}</label>
        {required && <span className="text-[9px] text-amber-600 font-black uppercase">Required</span>}
    </div>
    <input 
      type={type} 
      placeholder={placeholder}
      className="w-full bg-gray-50 border-2 border-transparent rounded-xl sm:rounded-2xl p-3 sm:p-4 text-sm font-bold text-emerald-950 focus:border-emerald-800 focus:bg-white outline-none transition-all" 
      value={value} 
      onChange={e => onChange(e.target.value)} 
      required={required} 
    />
  </div>
);

const PersonRecordList = ({ label, items, onChange }: { label: string, items: PersonRecord[], onChange: (items: PersonRecord[]) => void }) => {
  const safeItems = Array.isArray(items) ? items : [];
  const addItem = () => onChange([...safeItems, { name: '', qid_passport: '', nationality: '', dob: '' }]);
  const updateItem = (index: number, field: keyof PersonRecord, value: string | number) => {
    const newItems = [...safeItems];
    newItems[index] = { ...newItems[index], [field]: value };
    onChange(newItems);
  };
  const removeItem = (index: number) => onChange(safeItems.filter((_, i) => i !== index));

  return (
    <div className="w-full space-y-4">
      <div className="flex flex-col xs:flex-row justify-between items-start xs:items-center bg-emerald-950/5 p-4 rounded-xl sm:rounded-2xl gap-3">
        <label className="text-[9px] font-black text-emerald-900 uppercase tracking-widest ml-2">{label}</label>
        <button type="button" onClick={addItem} className="w-full xs:w-auto text-[9px] uppercase tracking-widest flex justify-center items-center gap-2 bg-emerald-800 text-white px-4 py-2.5 rounded-xl font-black hover:bg-emerald-900 transition-all">
          <UserPlus size={14} /> Add Record
        </button>
      </div>
      {safeItems.length === 0 && (
        <div className="text-center py-6 border-2 border-dashed border-gray-100 rounded-xl sm:rounded-[2rem]">
          <p className="text-[10px] text-gray-400 font-black uppercase">No records added</p>
        </div>
      )}
      <div className="grid grid-cols-1 gap-4">
        {safeItems.map((item, idx) => (
          <div key={idx} className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 p-5 sm:p-6 bg-gray-50 rounded-xl sm:rounded-[2rem] border border-gray-100 relative group">
            <div className="sm:col-span-2 lg:col-span-2">
              <InputField label="Name / Entity" value={item.name} onChange={(v: string) => updateItem(idx, 'name', v)} />
            </div>
            <InputField label="ID / Passport" value={item.qid_passport} onChange={(v: string) => updateItem(idx, 'qid_passport', v)} />
            <InputField label="Nationality" value={item.nationality} onChange={(v: string) => updateItem(idx, 'nationality', v)} />
            <div className="flex items-end gap-3">
              <div className="flex-1">
                 {label.includes('Shareholder') ? (
                   <InputField label="Share %" type="number" value={item.percentage} onChange={(v: any) => updateItem(idx, 'percentage', parseFloat(v))} />
                 ) : (
                   <InputField label="Date of Birth" type="date" value={item.dob} onChange={(v: string) => updateItem(idx, 'dob', v)} />
                 )}
              </div>
              <button type="button" onClick={() => removeItem(idx)} className="p-3 sm:p-4 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all">
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

interface ClientManagerProps {
  clients: Client[];
  totalCount: number;
  currentPage: number;
  onPageChange: (page: number) => void;
  isRefreshing: boolean;
  onAddClient: (client: Client) => Promise<void>;
  onDeleteClient: (id: string) => void;
  onUpdateClient?: (client: Client) => void;
  onRefresh: () => void;
  currentUserRole: UserRole;
  currentUserId: string;
}

