                <button type="button" onClick={() => setIsModalOpen(false)} className="px-8 py-4 font-black text-[10px] uppercase tracking-widest text-gray-400 hover:text-gray-600 order-2 xs:order-1">Cancel</button>
                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="w-full xs:w-auto bg-emerald-800 text-white px-10 py-4 rounded-xl sm:rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-emerald-900 flex justify-center items-center gap-2 order-1 xs:order-2 disabled:opacity-50"
                >
                  {isSubmitting ? <Loader2 size={20} className="animate-spin" /> : <CheckCircle2 size={20}/>}
                  {isSubmitting ? 'Committing...' : 'Commit Entity'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

