export default ClientManager;

import { createClient } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel, UserProfile, SanctionEntry, SystemEnvironment, IngestionLog } from '../types';

const MASTER_REGISTRY_URL = 'https://wbjiokaryxrjicavcvwx.supabase.co';
const MASTER_REGISTRY_KEY = 'sb_publishable_Folrp4epgSCgQArvm2GAfQ_Nbo-xJ-m';

let supabaseClient: any = null;

const isSandbox = (): boolean => {
  try {
    const sessionStr = localStorage.getItem('unsg_session');
    if (!sessionStr) return false;

    const session = JSON.parse(sessionStr);
    if (session.id !== 'SYS-ROOT') return false;

    const settings = JSON.parse(localStorage.getItem('unsg_settings') || '{}');
    return settings.environment === SystemEnvironment.SANDBOX;
  } catch (e) {
    return false;
  }
};

const simulateWrite = (action: string, data: any) => {
  console.warn(`[SANDBOX MODE] Simulated ${action}:`, data);
  return { error: null, data: null };
};

export const initSupabase = () => {
  try {
    supabaseClient = createClient(MASTER_REGISTRY_URL, MASTER_REGISTRY_KEY, {
      auth: { 
        persistSession: false, 
        autoRefreshToken: false, 
        detectSessionInUrl: false 
      }
    });
    return true;
  } catch (e) {
    console.error("[v1.8.5] Enterprise Handshake Fatal:", e);
    supabaseClient = null;
    return false;
  }
};

export const checkConnection = async () => {
  if (!supabaseClient) return false;
  try {
    const { error } = await supabaseClient.from('profiles').select('count').limit(1);
    if (error && error.code !== '42P01') return false;
    return true;
  } catch (err) {
    return false;
  }
};

export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  try {
    const { data, error } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'global_sync_lock')
      .limit(1);

    if (error) {
      if (error.code === '42P01') return { is_syncing: false, last_sync: 'Uninitialized', locked_at: 0, tableMissing: true };
      throw error;
    }
    if (!data || data.length === 0) return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
    return data[0].value || { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  } catch (e) {
    return { is_syncing: false, last_sync: 'Offline', locked_at: 0 };
  }
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync?: string) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('SetGlobalSyncLock', { isSyncing, lastSync });
  try {
    const status = { 
      is_syncing: isSyncing, 
      last_sync: lastSync || 'In Progress...',
      locked_at: isSyncing ? Date.now() : 0 
    };
    await supabaseClient
      .from('system_metadata')
      .upsert([{ key: 'global_sync_lock', value: status }], { onConflict: 'key' });
  } catch (e) {}
};

export const subscribeToGlobalSync = (onUpdate: (status: any) => void) => {
  if (!supabaseClient) return null;
  try {
    return supabaseClient
      .channel('system-metadata-consensus')
      .on('postgres_changes', { 
        event: 'UPDATE', 
        schema: 'public', 
        table: 'system_metadata', 
        filter: 'key=eq.global_sync_lock' 
      }, (payload: any) => {
        const newVal = payload.new?.value;
        if (newVal) onUpdate(newVal);
      })
      .subscribe();
  } catch (e) { return null; }
};

/**
 * Fetches clients from the database with strict DESC ordering on created_at.
 */
export const fetchCloudClients = async (from = 0, to = 14): Promise<Client[] | null> => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient
      .from('clients')
      .select('*')
      .order('created_at', { ascending: false })
      .range(from, to);
    if (error) return (error.code === '42P01') ? [] : null;
    return data;
  } catch (e) { return null; }
};

export const fetchClientsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  try {
    const { count, error } = await supabaseClient.from('clients').select('*', { count: 'exact', head: true });
    return (error) ? 0 : (count || 0);
  } catch (e) { return 0; }
};

/**
 * Persists client record to the cloud registry.
 * Maps fields strictly to avoid undefined column errors in Supabase.
 */
export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) throw new Error("Database client not initialized");
  if (isSandbox()) return simulateWrite('UpsertCloudClient', client);

  // Map only standard columns to match the core SQL schema
  const dbRecord = {
    id: client.id,
    "Client Name": client["Client Name"],
    kyc_status: client.kyc_status,
    "Company Nationality": client["Company Nationality"],
    "QFC No": client["QFC No"],
    "Legal Structure": client["Legal Structure"],
    "No": client["No"],
    riskLevel: client.riskLevel,
    created_at: client.created_at || new Date().toISOString()
  };

  try { 
    const { error } = await supabaseClient
      .from('clients')
      .upsert([dbRecord], { onConflict: 'id' }); 

    if (error) {
      console.error(`[CloudDB] Upsert failed (${error.code}): ${error.message}`);
      throw error;
    }
  } catch (e: any) {
    console.error("[CloudDB] Fatal exception during client provision:", e);
    throw e;
  }
};

export const deleteCloudClient = async (id: string) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('DeleteCloudClient', id);
  try { await supabaseClient.from('clients').delete().eq('id', id); } catch (e) {}
};

export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  try {
    const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
    return (error) ? 0 : (count || 0);
  } catch (e) { return 0; }
};

export const fetchSanctionsBatch = async (offset: number, limit: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient.from('sanctions').select('*').range(offset, offset + limit - 1);
    if (error) return [];
    return data || [];
  } catch (e) { return []; }
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (progress: number) => void) => {
  if (!supabaseClient) return;
  if (isSandbox()) {
    onProgress?.(100);
    return simulateWrite('UpsertCloudSanctions', `${sanctions.length} entries`);
  }
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize);
    try {
      await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'dataId' });
      if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
    } catch (e) { break; }
  }
};

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient.from('profiles').select('*');
    if (error) return (error.code === '42P01') ? [] : null;
    return data;
  } catch (e) { return null; }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('UpsertCloudUser', user.email);
  const dbProfile = {
    id: user.id, email: user.email.toLowerCase().trim(), full_name: user.full_name,
    role_id: user.role, status: user.status || 'Active', is_system_admin: user.is_system_admin === true,
    must_change_password: user.must_change_password, password_expiry: user.password_expiry,
    password_hash_mock: user.password, created_at: user.created_at || new Date().toISOString()
  };
  try {
    const { error } = await supabaseClient.from('profiles').upsert([dbProfile], { onConflict: 'email' });
    if (error) throw new Error(error.message);
  } catch (e: any) { throw e; }
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('DeleteCloudUser', email);
  try { await supabaseClient.from('profiles').delete().eq('email', email.toLowerCase().trim()); } catch (e) {}
};

export const logIngestionEvent = async (event: Omit<IngestionLog, 'id'>) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('LogIngestionEvent', event);
  const fullEvent = { ...event, id: `LOG-${Math.random().toString(36).substr(2, 6).toUpperCase()}` };
  try {
    await supabaseClient.from('ingestion_logs').upsert([fullEvent]);
  } catch (e) {}
};

export const fetchIngestionLogs = async (): Promise<IngestionLog[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient.from('ingestion_logs').select('*').order('timestamp', { ascending: false });
    if (error) return [];
    return data || [];
  } catch (e) { return []; }
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabaseClient) return null;
  try {
    return supabaseClient.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
  } catch (e) { return null; }
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabaseClient && channel) {
    try { await supabaseClient.removeChannel(channel); } catch (e) {}
  }
};

