export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) throw new Error("Cloud Node is currently offline. Please verify network or project status.");
  if (isSandbox()) return simulateWrite('UpsertCloudClient', client);

  // Strictly map fields to the database schema. 
  // Note: Columns with spaces must match the SQL definition in double-quotes exactly.
  const dbRecord: any = {
    id: client.id,
    "Client Name": client["Client Name"],
    kyc_status: client.kyc_status,
    "Company Nationality": client["Company Nationality"],
    "QFC No": client["QFC No"],
    "Legal Structure": client["Legal Structure"],
    "No": client["No"],
    riskLevel: client.riskLevel,
    created_at: client.created_at || new Date().toISOString()
  };

  try { 
    const { error, status } = await supabaseClient
      .from('clients')
      .upsert([dbRecord], { onConflict: 'id' }); 

    if (error) {
      console.error(`[CloudDB] Database operation failed. Code: ${error.code}. Msg: ${error.message}`);

      let friendlyMessage = error.message;
      if (error.code === '42501') {
        friendlyMessage = "Permission Denied (42501): Row Level Security (RLS) is active on the 'clients' table. Please add an 'Enable insert for authenticated users' policy in Supabase.";
      } else if (error.code === '42P01') {
        friendlyMessage = "Schema Error (42P01): The 'clients' table does not exist in the master registry. Please run the SQL initialization in Governance > Engine.";
      } else if (error.code === '23502') {
        friendlyMessage = "Validation Error (23502): A required column is missing. Please check your registry schema.";
      }

      const enhancedError = new Error(friendlyMessage);
      (enhancedError as any).code = error.code;
      throw enhancedError;
    }

    if (status >= 400) {
       throw new Error(`Registry Gateway Error: HTTP ${status}. Potential configuration mismatch.`);
    }

    return true;
  } catch (e: any) {
    console.error("[CloudDB] Fatal Provisioning Error:", e);
    throw e;
  }
};

