/**
 * Iterative Levenshtein distance implementation for string comparison.
 */
const levenshtein = (a: string, b: string): number => {
  const matrix = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));

  for (let i = 0; i <= a.length; i++) matrix[i][0] = i;
  for (let j = 0; j <= b.length; j++) matrix[0][j] = j;

  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1].toLowerCase() === b[j - 1].toLowerCase() ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }
  return matrix[a.length][b.length];
};

/**
 * Calculates a basic similarity score [0-1] between two words using Levenshtein distance.
 * This is non-recursive to prevent stack overflows.
 */
const calculateWordSimilarity = (s1: string, s2: string): number => {
  if (!s1 || !s2) return 0;
  const str1 = s1.trim().toLowerCase();
  const str2 = s2.trim().toLowerCase();

  if (str1 === str2) return 1.0;

  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  if (longer.length === 0) return 1.0;

  return (longer.length - levenshtein(longer, shorter)) / longer.length;
};

/**
 * Calculates a token-based similarity score to handle reordered names or partial matches.
 */
const calculateTokenScore = (str1: string, str2: string): number => {
  const tokens1 = str1.toLowerCase().split(/\s+/).filter(t => t.length > 1);
  const tokens2 = str2.toLowerCase().split(/\s+/).filter(t => t.length > 1);

  if (tokens1.length === 0 || tokens2.length === 0) return 0;

  let tokenMatches = 0;
  tokens1.forEach(t1 => {
    // Check for exact match or high fuzzy similarity between individual tokens
    const hasMatch = tokens2.some(t2 => t1 === t2 || calculateWordSimilarity(t1, t2) > 0.85);
    if (hasMatch) {
      tokenMatches++;
    }
  });

  return tokenMatches / Math.max(tokens1.length, tokens2.length);
};

export const screenClient = (client: Client, sanctions: SanctionEntry[]): MatchResult | null => {
  let bestMatch: MatchResult | null = null;
  let highestScore = 0;

  // Normalize client name
  const clientFullName = (client["Client Name"] || "").replace(/\s+/g, ' ').trim();
  if (!clientFullName) return null;

  for (const sanction of sanctions) {
    // Construct sanction full name parts
    const sanctionNameParts = [sanction.firstName, sanction.secondName, sanction.thirdName, sanction.lastName]
      .filter(Boolean)
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim();

    // Check main name and aliases
    const aliases = Array.isArray(sanction.aliases) ? sanction.aliases : [];
    const namesToCheck = [sanctionNameParts, ...aliases].filter(Boolean);

    let maxNameScore = 0;
    for (const name of namesToCheck) {
        // Combined score: 40% Word-Order/Levenshtein + 60% Token matching
        const wordSimilarity = calculateWordSimilarity(clientFullName, name);
        const tokenScore = calculateTokenScore(clientFullName, name);

        const combinedScore = (wordSimilarity * 0.4) + (tokenScore * 0.6);
        if (combinedScore > maxNameScore) maxNameScore = combinedScore;
    }

    // Secondary field matches
    let nationalityMatch = false;
    const clientNationality = (client["Company Nationality"] || "").toLowerCase();
    const sanctionNationality = (sanction.nationality || "").toLowerCase();
    if (clientNationality && sanctionNationality) {
        if (sanctionNationality.includes(clientNationality) || clientNationality.includes(sanctionNationality)) {
            nationalityMatch = true;
        }
    }

    let dobMatch = false;
    const clientDob = client["Date of QFC Incorporation or Registration"] || "";
    const sanctionDob = sanction.dateOfBirth || "";
    if (clientDob && sanctionDob && clientDob === sanctionDob) {
        dobMatch = true;
    }

    // Boost score if auxiliary fields match
    let finalScore = maxNameScore * 100;
    if (finalScore > 40) {
        if (nationalityMatch) finalScore += 15;
        if (dobMatch) finalScore += 25;
    }

    if (finalScore > highestScore) {
        highestScore = finalScore;

        let risk = RiskLevel.NONE;
        if (finalScore >= 85) risk = RiskLevel.HIGH;
        else if (finalScore >= 65) risk = RiskLevel.MEDIUM;
        else if (finalScore >= 45) risk = RiskLevel.LOW;

        if (risk !== RiskLevel.NONE) {
            bestMatch = {
                clientId: client.id,
                sanctionId: sanction.dataId,
                score: Math.min(Math.round(finalScore), 100),
                riskLevel: risk,
                matchedFields: [
                    maxNameScore > 0.7 ? 'Name' : '',
                    nationalityMatch ? 'Nationality' : '',
                    dobMatch ? 'Date of Birth' : ''
                ].filter(Boolean),
                timestamp: new Date().toISOString()
            };
        }
    }
  }

  return bestMatch;
};

