export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) throw new Error("Cloud Node is currently offline. Please verify project status.");
  if (isSandbox()) return simulateWrite('UpsertCloudClient', client);

  // Map business object to optimized snake_case schema
  const dbRecord: any = {
    id: client.id,
    client_name: client["Client Name"],
    kyc_status: client.kyc_status,
    company_nationality: client["Company Nationality"],
    qfc_no: client["QFC No"],
    legal_structure: client["Legal Structure"],
    file_no: client["No"],
    risk_level: client.riskLevel,
    entity_type: client.entity_type,
    created_at: client.created_at || new Date().toISOString(),
    created_by: client.created_by
  };

  try { 
    const { error, status } = await supabaseClient
      .from('clients')
      .upsert([dbRecord], { onConflict: 'id' }); 

    if (error) {
      console.error(`[CloudDB] DB Failure. Code: ${error.code}. Msg: ${error.message}`);

      let friendlyMessage = error.message;
      if (error.code === '42501') {
        friendlyMessage = "Security Policy Block: Row Level Security (RLS) is active. Ensure your Supabase policies permit 'INSERT/UPDATE' for the 'clients' table.";
      } else if (error.code === '42P01') {
        friendlyMessage = "Database Uninitialized: The 'clients' table is missing. Go to Governance > Engine and run the provided SQL script.";
      } else if (error.message.includes('column') && error.message.includes('cache')) {
        friendlyMessage = "Schema Mismatch: The application is expecting snake_case columns. Please RE-RUN the SQL initialization script in Governance > Engine.";
      }

      const enhancedError = new Error(friendlyMessage);
      (enhancedError as any).code = error.code;
      throw enhancedError;
    }

    if (status >= 400) throw new Error(`Gateway Error: HTTP ${status}`);
    return true;
  } catch (e: any) {
    throw e;
  }
};

