);

-- MIGRATION: Ensure old columns are renamed to snake_case if they exist
DO $$ 
BEGIN 
  -- Rename "Client Name" to client_name if exists
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='clients' AND column_name='Client Name') THEN
