  const SQL_SCHEMA = `-- v3.2.1 Enterprise Cloud Schema & Cache Sync
-- Run this in your Supabase SQL Editor to REPAIR column cache (PGRST204).

-- 1. Metadata & Sync Control
CREATE TABLE IF NOT EXISTS public.system_metadata (
  key TEXT PRIMARY KEY,
  value JSONB DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- 2. Identity Profiles
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT UNIQUE NOT NULL,
  full_name TEXT,
  role_id TEXT,
  status TEXT DEFAULT 'Active',
  is_system_admin BOOLEAN DEFAULT false,
  must_change_password BOOLEAN DEFAULT true,
  password_expiry TIMESTAMPTZ,
  password_hash_mock TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 3. Entity Registry
CREATE TABLE IF NOT EXISTS public.clients (
  id TEXT PRIMARY KEY,
  client_name TEXT,
  kyc_status TEXT,
  company_nationality TEXT,
  qfc_no TEXT,
  legal_structure TEXT,
  file_no TEXT,
  risk_level TEXT DEFAULT 'None',
  entity_type TEXT,
  email TEXT,
  address TEXT,
  created_at TIMESTAMPTZ DEFAULT now(),
  created_by TEXT
);

-- MASTER REPAIR BLOCK: Force snake_case standardization
DO $$ 
BEGIN 
  -- Fix "Client Name"
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='Client Name') THEN
    ALTER TABLE public.clients RENAME COLUMN "Client Name" TO client_name;
  END IF;

  -- Fix "Company Nationality"
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='Company Nationality') THEN
    ALTER TABLE public.clients RENAME COLUMN "Company Nationality" TO company_nationality;
  END IF;

  -- Fix "QFC No"
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='QFC No') THEN
    ALTER TABLE public.clients RENAME COLUMN "QFC No" TO qfc_no;
  END IF;

  -- Fix "Legal Structure"
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='Legal Structure') THEN
    ALTER TABLE public.clients RENAME COLUMN "Legal Structure" TO legal_structure;
  END IF;

  -- Fix "No"
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='No') THEN
    ALTER TABLE public.clients RENAME COLUMN "No" TO file_no;
  END IF;

  -- Add Missing Contact Fields
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='email') THEN
    ALTER TABLE public.clients ADD COLUMN email TEXT;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='address') THEN
    ALTER TABLE public.clients ADD COLUMN address TEXT;
  END IF;

  -- Add Missing Status Fields
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='kyc_status') THEN
    ALTER TABLE public.clients ADD COLUMN kyc_status TEXT DEFAULT 'Draft';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='risk_level') THEN
    ALTER TABLE public.clients ADD COLUMN risk_level TEXT DEFAULT 'None';
  END IF;
END $$;

-- 4. Sanctions Cache
CREATE TABLE IF NOT EXISTS public.sanctions (
  data_id TEXT PRIMARY KEY,
  first_name TEXT,
  last_name TEXT,
  source TEXT,
  reference_number TEXT,
  listed_on TEXT,
  nationality TEXT,
  un_list_type TEXT,
  aliases JSONB DEFAULT '[]'::jsonb,
  fetch_date TIMESTAMPTZ DEFAULT now()
);

-- 5. System Ingestion Logs
CREATE TABLE IF NOT EXISTS public.ingestion_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  timestamp TIMESTAMPTZ DEFAULT now(),
  source TEXT,
  method TEXT,
  status TEXT,
  records_processed INTEGER DEFAULT 0,
  records_accepted INTEGER DEFAULT 0,
  records_rejected INTEGER DEFAULT 0,
  details TEXT,
  triggered_by TEXT
);

-- FORCE CACHE RELOAD: Signal Supabase to refresh its API schema cache
NOTIFY pgrst, 'reload schema';`;

