  address TEXT,
  created_at TIMESTAMPTZ DEFAULT now(),
  created_by TEXT
);

-- MASTER REPAIR BLOCK: Standardize to snake_case and repair schema cache
DO $$ 
BEGIN 
  -- Fix "Client Name"
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND (column_name='Client Name' OR column_name='client name')) THEN
    ALTER TABLE public.clients RENAME COLUMN "Client Name" TO client_name;
  END IF;

  -- Fix "Company Nationality"
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND (column_name='Company Nationality' OR column_name='company nationality')) THEN
