export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  try {
    const { data, error } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'global_sync_lock')
      .limit(1);

    if (error) {
      if (error.code === '42P01') return { is_syncing: false, last_sync: 'Uninitialized', locked_at: 0, tableMissing: true };
      throw error;
    }
    if (!data || data.length === 0) return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
    return data[0].value || { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  } catch (e) {
    return { is_syncing: false, last_sync: 'Offline', locked_at: 0 };
  }
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync?: string) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('SetGlobalSyncLock', { isSyncing, lastSync });
  try {
    const status = { 
      is_syncing: isSyncing, 
      last_sync: lastSync || 'In Progress...',
      locked_at: isSyncing ? Date.now() : 0 
    };
    await supabaseClient
      .from('system_metadata')
      .upsert([{ key: 'global_sync_lock', value: status }], { onConflict: 'key' });
  } catch (e) {}
};

export const subscribeToGlobalSync = (onUpdate: (status: any) => void) => {
  if (!supabaseClient) return null;
  try {
    return supabaseClient
      .channel('system-metadata-consensus')
      .on('postgres_changes', { 
        event: 'UPDATE', 
        schema: 'public', 
        table: 'system_metadata', 
        filter: 'key=eq.global_sync_lock' 
      }, (payload: any) => {
        const newVal = payload.new?.value;
        if (newVal) onUpdate(newVal);
      })
      .subscribe();
  } catch (e) { return null; }
};

export const fetchCloudClients = async (from = 0, to = 14): Promise<Client[] | null> => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient
      .from('clients')
      .select('*')
      .order('created_at', { ascending: false })
      .range(from, to);
    if (error) {
      console.warn(`[CloudDB] Fetch error: ${error.message} (${error.code})`);
      return (error.code === '42P01') ? [] : null;
    }

    // Map snake_case database back to Business Object with fallback safety
