export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  try {
    const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
    return (error) ? 0 : (count || 0);
  } catch (e) { return 0; }
};

export const fetchSanctionsBatch = async (offset: number, limit: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient.from('sanctions').select('*').range(offset, offset + limit - 1);
    if (error) return [];

    // Map back to business object
    return data.map((row: any) => ({
      dataId: row.data_id,
      firstName: row.first_name,
      lastName: row.last_name,
      source: row.source,
      referenceNumber: row.reference_number,
      listedOn: row.listed_on,
      nationality: row.nationality,
      unListType: row.un_list_type,
      aliases: row.aliases || [],
      fetchDate: row.fetch_date
    } as SanctionEntry));
  } catch (e) { return []; }
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (progress: number) => void) => {
  if (!supabaseClient) return;
  if (isSandbox()) {
    onProgress?.(100);
    return simulateWrite('UpsertCloudSanctions', `${sanctions.length} entries`);
  }
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize).map(s => ({
      data_id: s.dataId,
      first_name: s.firstName,
      last_name: s.lastName,
      source: s.source,
      reference_number: s.referenceNumber,
      listed_on: s.listedOn,
      nationality: s.nationality,
      un_list_type: s.unListType,
      aliases: s.aliases,
      fetch_date: s.fetchDate || new Date().toISOString()
    }));

    try {
      await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
      if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
    } catch (e) { break; }
  }
};

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient.from('profiles').select('*');
    if (error) return null;
    return data;
  } catch (e) { return null; }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('UpsertCloudUser', user);
  const dbRecord = {
    email: user.email,
    full_name: user.full_name,
    role_id: user.role,
    status: user.status,
    is_system_admin: user.is_system_admin,
    must_change_password: user.must_change_password,
    password_expiry: user.password_expiry,
    password_hash_mock: user.password || user.password_hash_mock,
  };
  try {
    await supabaseClient.from('profiles').upsert([dbRecord], { onConflict: 'email' });
  } catch (e) {}
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('DeleteCloudUser', email);
  try {
    await supabaseClient.from('profiles').delete().eq('email', email);
  } catch (e) {}
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabaseClient) return null;
  try {
    return supabaseClient
      .channel('clients-rt-v323')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, () => {
        onUpdate();
      })
      .subscribe();
  } catch (e) { return null; }
};

export const unsubscribeFromClients = (subscription: any) => {
  if (subscription) {
    subscription.unsubscribe();
  }
};

export const logIngestionEvent = async (log: Partial<IngestionLog>) => {
  if (!supabaseClient) return;
  if (isSandbox()) return simulateWrite('LogIngestionEvent', log);

  const dbRecord = {
    source: log.source,
    method: log.method,
    status: log.status,
    records_processed: log.recordsProcessed,
    records_accepted: log.recordsAccepted,
    records_rejected: log.recordsRejected,
    details: log.details,
    triggered_by: log.triggeredBy
  };

  try {
    await supabaseClient.from('ingestion_logs').insert([dbRecord]);
  } catch (e) {}
};

export const fetchIngestionLogs = async (): Promise<IngestionLog[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient
      .from('ingestion_logs')
      .select('*')
      .order('timestamp', { ascending: false })
      .limit(50);

    if (error) return [];

    return data.map((row: any) => ({
      id: row.id,
      timestamp: row.timestamp,
      source: row.source,
      method: row.method,
      status: row.status,
      recordsProcessed: row.records_processed,
      recordsAccepted: row.records_accepted,
      recordsRejected: row.records_rejected,
      details: row.details,
      triggeredBy: row.triggered_by
    } as IngestionLog));
  } catch (e) { return []; }
};

