const isSandbox = (): boolean => {
  try {
    const sessionStr = localStorage.getItem('unsg_session');
    if (!sessionStr) return false;

    const session = JSON.parse(sessionStr);
    if (session.id !== 'SYS-ROOT') return false;

    const settings = JSON.parse(localStorage.getItem('unsg_settings') || '{}');
    return settings.environment === SystemEnvironment.SANDBOX;
  } catch (e) {
    return false;
  }
};

const simulateWrite = (action: string, data: any) => {
  console.warn(`[SANDBOX MODE] Simulated ${action}:`, data);
  return { error: null, data: null };
};

export const initSupabase = () => {
  try {
    supabaseClient = createClient(MASTER_REGISTRY_URL, MASTER_REGISTRY_KEY, {
      auth: { 
        persistSession: false, 
        autoRefreshToken: false, 
        detectSessionInUrl: false 
      }
