  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const SQL_SCHEMA = `-- v3.2.5 Enterprise Cloud Schema & Cache Force-Refresh
-- Run this in your Supabase SQL Editor to REPAIR column cache (PGRST204).

-- 1. Metadata & Sync Control
CREATE TABLE IF NOT EXISTS public.system_metadata (
  key TEXT PRIMARY KEY,
  value JSONB DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- 2. Identity Profiles
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT UNIQUE NOT NULL,
  full_name TEXT,
  role_id TEXT,
  status TEXT DEFAULT 'Active',
  is_system_admin BOOLEAN DEFAULT false,
  must_change_password BOOLEAN DEFAULT true,
  password_expiry TIMESTAMPTZ,
  password_hash_mock TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 3. Entity Registry (Base Table)
CREATE TABLE IF NOT EXISTS public.clients (
  id TEXT PRIMARY KEY,
  client_name TEXT,
  kyc_status TEXT DEFAULT 'Draft',
  company_nationality TEXT,
  qfc_no TEXT,
  legal_structure TEXT,
  file_no TEXT,
  risk_level TEXT DEFAULT 'None',
  entity_type TEXT DEFAULT 'Corporate',
  email TEXT,
  address TEXT,
  created_at TIMESTAMPTZ DEFAULT now(),
  created_by TEXT
);

-- MASTER REPAIR BLOCK: Standardize to snake_case & Force Refresh
DO $$ 
DECLARE
  r RECORD;
BEGIN 
  -- Fix "Client Name" / "client name"
  FOR r IN SELECT column_name FROM information_schema.columns 
           WHERE table_schema='public' AND table_name='clients' 
           AND lower(column_name) = 'client name'
  LOOP
    EXECUTE format('ALTER TABLE public.clients RENAME COLUMN %I TO client_name', r.column_name);
  END LOOP;

  -- Fix "Company Nationality" / "company nationality"
  FOR r IN SELECT column_name FROM information_schema.columns 
           WHERE table_schema='public' AND table_name='clients' 
           AND lower(column_name) = 'company nationality'
  LOOP
    EXECUTE format('ALTER TABLE public.clients RENAME COLUMN %I TO company_nationality', r.column_name);
  END LOOP;

  -- Ensure company_nationality exists even if table was created in v1.x
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='company_nationality') THEN
    ALTER TABLE public.clients ADD COLUMN company_nationality TEXT;
  END IF;

  -- Fix "QFC No" / "qfc no"
  FOR r IN SELECT column_name FROM information_schema.columns 
           WHERE table_schema='public' AND table_name='clients' 
           AND lower(column_name) = 'qfc no'
  LOOP
    EXECUTE format('ALTER TABLE public.clients RENAME COLUMN %I TO qfc_no', r.column_name);
  END LOOP;

  -- Fix "Legal Structure" / "legal structure"
  FOR r IN SELECT column_name FROM information_schema.columns 
           WHERE table_schema='public' AND table_name='clients' 
           AND lower(column_name) = 'legal structure'
  LOOP
    EXECUTE format('ALTER TABLE public.clients RENAME COLUMN %I TO legal_structure', r.column_name);
  END LOOP;

  -- Fix "No" / "no"
  FOR r IN SELECT column_name FROM information_schema.columns 
           WHERE table_schema='public' AND table_name='clients' 
           AND lower(column_name) = 'no'
  LOOP
    EXECUTE format('ALTER TABLE public.clients RENAME COLUMN %I TO file_no', r.column_name);
  END LOOP;

  -- Ensure other required columns exist
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='email') THEN
    ALTER TABLE public.clients ADD COLUMN email TEXT;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='address') THEN
    ALTER TABLE public.clients ADD COLUMN address TEXT;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='kyc_status') THEN
    ALTER TABLE public.clients ADD COLUMN kyc_status TEXT DEFAULT 'Draft';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='risk_level') THEN
    ALTER TABLE public.clients ADD COLUMN risk_level TEXT DEFAULT 'None';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='clients' AND column_name='entity_type') THEN
    ALTER TABLE public.clients ADD COLUMN entity_type TEXT DEFAULT 'Corporate';
  END IF;

  -- CACHE BUSTER: Force metadata update using dynamic SQL to avoid syntax errors
  EXECUTE format('COMMENT ON TABLE public.clients IS %L', 'Standardized Registry v3.2.5 - REPAIRED ' || now());
END $$;

-- Force API Schema Reload
NOTIFY pgrst, 'reload schema';

-- 4. Sanctions Cache (Maintenance)
CREATE TABLE IF NOT EXISTS public.sanctions (
  data_id TEXT PRIMARY KEY,
  first_name TEXT,
  last_name TEXT,
  source TEXT,
  reference_number TEXT,
  listed_on TEXT,
  nationality TEXT,
  un_list_type TEXT,
