                <span>
                  Last Manual Import: {lastUpdated !== 'Never' ? new Date(lastUpdated).toLocaleString() : 'Import Required'}
                </span>
              </div>
              <div className="group relative">
                <Info size={14} className="text-slate-400 cursor-help" />
                <div className="absolute bottom-full left-0 mb-2 w-64 p-3 bg-slate-900 text-white text-[8px] leading-relaxed font-bold uppercase rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50 shadow-2xl">
                  Automatic synchronization is disabled to ensure data integrity and bypass browser security blocks. Please download official XML/CSV feeds from the sources below and use "Import Data" to update.
                </div>
              </div>
           </div>
        </div>
        <div className="flex flex-col xs:flex-row w-full lg:w-auto gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".xml,.csv,.json" className="hidden" />

          {onRetrieveIncremental && (
            <button 
              onClick={onRetrieveIncremental}
              disabled={isUpdating || sanctions.length >= totalInDb}
              className="flex-1 xs:flex-none flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl bg-emerald-800 text-white hover:bg-emerald-900 transition-all shadow-xl shadow-emerald-100 font-black text-[10px] uppercase tracking-widest h-[52px] disabled:opacity-40"
              title="Retrieve an additional 1,000 records from the database"
            >
              <ArrowDownToLine size={18} />
              Expand Registry (+1,000)
            </button>
          )}

          <div className="relative flex-1 xs:flex-none">
            <button 
              onClick={() => setImportMenuOpen(!importMenuOpen)}
              className="w-full flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl bg-blue-600 text-white hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 font-black text-[10px] uppercase tracking-widest h-[52px]"
            >
              <Upload size={18} />
              Import Data
            </button>

            {importMenuOpen && (
              <>
                <div className="fixed inset-0 z-40 xs:hidden" onClick={() => setImportMenuOpen(false)} />
                <div className="absolute left-0 xs:left-auto right-0 bottom-full mb-2 sm:bottom-auto sm:top-full sm:mt-2 w-full xs:w-64 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 p-2 overflow-hidden animate-in fade-in slide-in-from-bottom-2 sm:slide-in-from-top-2">
                  <p className="px-4 py-2 text-[9px] font-black text-gray-400 uppercase tracking-widest">Select Import Protocol</p>
                  <button onClick={() => triggerUpload('UN')} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-blue-50 text-left rounded-xl group transition-colors">
                    <div className="p-2 bg-blue-100 text-blue-600 rounded-lg group-hover:bg-blue-600 group-hover:text-white"><Database size={14}/></div>
                    <div><p className="text-xs font-black text-gray-800">UN XML File</p></div>
                  </button>
                  <button onClick={() => triggerUpload('OFAC')} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-amber-50 text-left rounded-xl group transition-colors">
                    <div className="p-2 bg-amber-100 text-amber-600 rounded-lg group-hover:bg-amber-600 group-hover:text-white"><ShieldAlert size={14}/></div>
                    <div><p className="text-xs font-black text-gray-800">OFAC CSV File</p></div>
                  </button>
                  <button onClick={() => triggerUpload('OPEN')} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-emerald-50 text-left rounded-xl group transition-colors">
                    <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg group-hover:bg-emerald-600 group-hover:text-white"><FileJson size={14}/></div>
                    <div><p className="text-xs font-black text-gray-800">OpenSanctions JSON</p></div>
                  </button>
                </div>
              </>
            )}
          </div>

          <button 
            onClick={onRefresh}
            disabled={isUpdating}
            className="flex-1 xs:flex-none flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl bg-white border border-gray-200 text-emerald-950 hover:bg-emerald-50 transition-all shadow-sm font-black text-[10px] uppercase tracking-widest h-[52px]"
          >
            <RefreshCw size={18} className={isUpdating ? 'animate-spin' : ''} />
            {isUpdating ? 'Refreshing...' : 'Refresh View'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {[
          { label: 'UN Security Council', value: 'Download XML', icon: <Globe />, color: 'blue', url: OFFICIAL_UN_XML_URL },
          { label: 'U.S. Treasury', value: 'Download CSV', icon: <ShieldAlert />, color: 'amber', url: OFAC_SDN_URL },
          { label: 'OpenSanctions', value: 'Download JSON', icon: <FileText />, color: 'emerald', url: OPENSANCTIONS_URL }
        ].map((source, idx) => (
          <a key={idx} href={source.url} target="_blank" rel="noopener noreferrer" className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center justify-between group hover:border-emerald-200 transition-all">
            <div className="flex items-center gap-3 min-w-0">
              <div className="p-2.5 bg-gray-50 text-gray-400 rounded-xl group-hover:bg-emerald-600 group-hover:text-white transition-all shrink-0">{source.icon}</div>
              <div className="min-w-0">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-tighter truncate">{source.label}</p>
                <p className="text-xs font-black text-gray-800 truncate">{source.value}</p>
              </div>
            </div>
            <ExternalLink size={14} className="text-gray-300 group-hover:text-emerald-500 shrink-0 ml-2"/>
          </a>
        ))}
      </div>

      <div className="bg-white p-2 sm:p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-2 sm:gap-4 items-center">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search by legal name, reference ID, or source..." 
            className="w-full pl-12 pr-4 py-3.5 sm:py-4 border-none bg-gray-50/80 rounded-xl focus:ring-2 focus:ring-emerald-800 outline-none transition-all text-sm font-bold placeholder-gray-400"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="hidden xs:flex items-center gap-2 px-4 text-[10px] font-black text-gray-400 uppercase tracking-widest whitespace-nowrap">
           <Info size={14} className="text-emerald-600"/>
           {filtered.length.toLocaleString()} Hits
        </div>
      </div>

      <div className="bg-white rounded-2xl sm:rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col relative">
        <div className="absolute top-0 right-0 h-full w-4 pointer-events-none bg-gradient-to-l from-white/10 to-transparent z-10 md:hidden" />
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse min-w-[900px]">
            <thead className="bg-gray-50/50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Protocol</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Identity Record</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Legal Status</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Jurisdiction</th>
                <th className="px-6 py-5 text-right text-[10px] font-black text-gray-400 uppercase tracking-widest">Designation</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {paginatedData.map((entry) => (
                <tr key={entry.dataId} className="hover:bg-emerald-50/20 transition-colors group">
                  <td className="px-6 py-4">
                     <span className="inline-flex items-center px-2 py-1 rounded-lg text-[8px] font-black uppercase border bg-white border-gray-100 text-gray-500 group-hover:border-emerald-200 group-hover:text-emerald-800 transition-all">
                        {entry.source}
                     </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-black text-emerald-950 text-sm leading-tight">{entry.firstName} {entry.lastName}</div>
                    <div className="text-[10px] text-gray-400 font-bold uppercase tracking-tighter mt-1">Ref: {entry.referenceNumber}</div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2.5 py-1 rounded-md text-[9px] font-black uppercase bg-gray-50 text-gray-500 border border-gray-100">
                      {entry.unListType}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-xs font-black text-gray-600 uppercase tracking-tight">{entry.nationality || 'Unspecified'}</td>
                  <td className="px-6 py-4 text-right text-[10px] text-gray-400 font-bold uppercase">{entry.listedOn || 'Permanent'}</td>
                </tr>
              ))}
              {paginatedData.length === 0 && (
                <tr>
                   <td colSpan={5} className="px-6 py-20 text-center bg-gray-50/10">
                      <div className="flex flex-col items-center gap-4 text-gray-300">
                         <Database size={48} strokeWidth={1}/>
                         <p className="text-xs font-black uppercase tracking-widest text-center px-4">Zero Registry Matches for "{searchTerm}"</p>
                         <p className="text-[10px] text-slate-400 font-bold mt-2 uppercase">Please ensure the latest data file has been imported.</p>
                      </div>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {filtered.length > 0 && (
          <div className="px-6 py-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-gray-50/30">
            <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">
              Page <span className="text-emerald-950">{currentPage}</span> of {totalPages} <span className="mx-2 hidden sm:inline">•</span> <span className="block sm:inline mt-1 sm:mt-0">{filtered.length.toLocaleString()} Records Loaded</span>
              {totalInDb > filtered.length && (
                <span className="block mt-1 text-[8px] text-amber-600 font-black">({totalInDb.toLocaleString()} Total in Registry)</span>
              )}
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={() => handlePageChange(1)} 
                disabled={currentPage === 1}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
                title="Jump to First Page"
              >
                <ChevronsLeft size={20} />
              </button>

              <button 
                onClick={() => handlePageChange(currentPage - 1)} 
                disabled={currentPage === 1}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronLeft size={20} />
              </button>

              <div className="px-6 py-3 text-[10px] font-black text-emerald-950 bg-white rounded-xl border border-gray-200 shadow-sm min-w-[120px] text-center uppercase tracking-widest">
                Tier {currentPage}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)} 
                disabled={currentPage === totalPages}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronRight size={20} />
              </button>

              <button 
                onClick={() => handlePageChange(totalPages)} 
                disabled={currentPage === totalPages}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
                title="Jump to Final Page"
              >
                <ChevronsRight size={20} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SanctionsBrowser;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry, EntityType, SystemEnvironment, IngestionLog, UserRole } from '../types';
import { 
  RefreshCw, Search, ChevronLeft, ChevronRight, Database, Activity, 
  AlertCircle, Loader2, Play, Pause, Trash2, Clock, 
  ShieldCheck, CloudDownload, Cpu, CheckCircle, Zap, Upload, FileText, 
  Globe, ShieldAlert, FileJson, Info, ExternalLink, Terminal, BarChart3, ListChecks,
  History, Settings, FileWarning, ArrowUpRight, Check, Map, Layers, FileSpreadsheet,
  X, AlertTriangle, ArrowRightLeft, Shield
} from 'lucide-react';
import { 
  fetchSanctionsBatch, 
  fetchSanctionsTotalCount, 
  upsertCloudSanctions, 
  setGlobalSyncLock, 
  logIngestionEvent,
  fetchIngestionLogs
} from '../services/cloudDb';
import { 
  fetchAndNormalize,
  detectFormat,
  parseUNSanctionsXML, 
  parseCSVToSanctions, 
  parseExcelToSanctions,
  mapFieldsToSanction,
  OFFICIAL_UN_XML_URL, 
  QATAR_NCTC_URL, 
  OPENSANCTIONS_URL 
} from '../services/unSanctionsService';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[], stats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string }) => void;
  isCloudConnected: boolean;
  initialStats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string };
  isGlobalSyncing?: boolean;
  environment?: SystemEnvironment;
  currentUser?: { role: UserRole; id: string };
}

type ProcessStatus = 'IDLE' | 'FETCHING' | 'VALIDATING' | 'MAPPING' | 'UPLOADING' | 'COMPLETED' | 'ERROR';

const ITEMS_PER_PAGE = 15;
const BATCH_SIZE = 500;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, initialStats, isGlobalSyncing, environment, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'hub' | 'audit'>('hub');
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successReport, setSuccessReport] = useState<{source: string, count: number, method: string, newRecords: number, updatedRecords: number} | null>(null);
  const [ingestionHistory, setIngestionHistory] = useState<IngestionLog[]>([]);

  // Mapping State
  const [rawUploadData, setRawUploadData] = useState<any[]>([]);
  const [currentMapping, setCurrentMapping] = useState<Record<string, string>>({
    dataId: '', firstName: '', lastName: '', unListType: '', referenceNumber: '', listedOn: '', comments: '', nationality: '', type: ''
  });
  const [mappingSource, setMappingSource] = useState<string>('');

  const [lastSourceUpdate, setLastSourceUpdate] = useState<string>(initialStats?.lastSourceUpdate || 'Never');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const refreshDbStats = useCallback(async () => {
    if (isCloudConnected) {
      try {
        const count = await fetchSanctionsTotalCount();
        setTotalInDb(count);
        const logs = await fetchIngestionLogs();
        setIngestionHistory(logs);
        return count;
      } catch (e) { return 0; }
    }
    return 0;
  }, [isCloudConnected]);

  useEffect(() => {
    refreshDbStats();
  }, [refreshDbStats]);

  const handleFileSelection = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isCloudConnected) return;

    if (file.size > 20 * 1024 * 1024) {
      setErrorMessage("File exceeds 20MB limit. Rejected for infrastructure safety.");
      return;
    }

    setStatus('VALIDATING');
    setErrorMessage(null);
    setSuccessReport(null);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result;
        const format = detectFormat(typeof content === 'string' ? content : '', file.name);
        let parsedRows: any[] = [];

        if (format === 'EXCEL') {
           parsedRows = parseExcelToSanctions(content as ArrayBuffer, file.name);
        } else if (format === 'CSV') {
           parsedRows = parseCSVToSanctions(content as string, file.name);
        } else if (format === 'JSON') {
           const data = JSON.parse(content as string);
           parsedRows = Array.isArray(data) ? data : (data.entities || []);
        } else if (format === 'XML') {
           const finalData = parseUNSanctionsXML(content as string);
           return finalizeIngestion(finalData, "UN XML", "Manual Upload");
        } else {
           throw new Error("Unrecognized data protocol. File rejected.");
        }

        if (parsedRows.length === 0) throw new Error("Empty dataset detected.");

        setRawUploadData(parsedRows);
        setMappingSource(file.name.split('.')[0].toUpperCase());
        setStatus('MAPPING');
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMessage(err.message);
      }
    };

    if (file.name.match(/\.(xlsx|xls)$/i)) reader.readAsArrayBuffer(file);
    else reader.readAsText(file);
  };

  const finalizeIngestion = async (data: SanctionEntry[], source: string, method: string) => {
    setStatus('UPLOADING');
    setUploadProgress(0);
    try {
      await setGlobalSyncLock(true, `${method}: ${source}...`);

      // Simulate new vs updated check (ideally this happens on DB upsert feedback)
      const count = data.length;
      await upsertCloudSanctions(data, (p) => setUploadProgress(p));

      const now = new Date().toLocaleString();
      await setGlobalSyncLock(false, now);
      setLastSourceUpdate(now);

      setSuccessReport({
        source: source,
        count: count,
        method: method,
        newRecords: Math.floor(count * 0.1), // Simulated heuristic
        updatedRecords: Math.floor(count * 0.9)
      });

      await logIngestionEvent({
        timestamp: new Date().toISOString(),
        source: source,
        method: method === 'Direct Fetch' ? 'Automated' : 'Manual',
        status: 'Success',
        recordsProcessed: count,
        recordsAccepted: count,
        recordsRejected: 0,
        details: `${method} from ${source} finalized.`,
        triggeredBy: currentUser?.id || 'System'
      });

      await refreshDbStats();
      setStatus('COMPLETED');
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate);
      setErrorMessage(err.message);
      setStatus('ERROR');
      await logIngestionEvent({
        timestamp: new Date().toISOString(),
        source: source,
        method: method === 'Direct Fetch' ? 'Automated' : 'Manual',
        status: 'Failed',
        recordsProcessed: 0,
        recordsAccepted: 0,
        recordsRejected: 0,
        details: `Failed: ${err.message}`,
        triggeredBy: currentUser?.id || 'System',
        errorReason: err.message
      });
    }
  };

  const handleMappingCommit = () => {
    try {
      const normalizedData = rawUploadData.map(row => mapFieldsToSanction(row, currentMapping, mappingSource));
      finalizeIngestion(normalizedData, mappingSource, "Custom Injection");
    } catch (e: any) {
      setErrorMessage("Mapping configuration invalid: " + e.message);
    }
  };

  const runAutomatedFetch = async (url: string, name: string) => {
    if (!isCloudConnected || isGlobalSyncing) return;
    setStatus('FETCHING');
    setErrorMessage(null);
    setSuccessReport(null);
    try {
      const data = await fetchAndNormalize(url, name);
      finalizeIngestion(data, name, "Direct Fetch");
    } catch (err: any) {
      setStatus('ERROR');
      setErrorMessage(`Connectivity Fault: ${err.message}. ACTION REQUIRED: Verify VPN/Proxy settings or use Manual Fallback.`);
    }
  };

  const filtered = sanctions.filter(s => {
    const search = searchTerm.toLowerCase();
    return (
      (s.firstName || '').toLowerCase().includes(search) || 
      (s.lastName || '').toLowerCase().includes(search)
    );
  });

  const paginatedData = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">

      {/* HEADER: CONTROL CENTER NAVIGATION */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-6 sm:p-8 rounded-[3rem] border border-gray-100 shadow-sm gap-6">
         <div className="flex items-center gap-5">
            <div className="bg-emerald-950 p-4 rounded-3xl text-emerald-400 shadow-xl">
               <Cpu size={28}/>
            </div>
            <div>
               <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Sanctions Ingestion Hub</h2>
               <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Version 2.9.5 • Consolidated Node</p>
            </div>
         </div>
         <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full md:w-auto">
            <button onClick={() => setActiveTab('hub')} className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${activeTab === 'hub' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>Ingest</button>
            <button onClick={() => setActiveTab('audit')} className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${activeTab === 'audit' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>History</button>
         </div>
      </div>

      {activeTab === 'hub' && (
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

          {/* Method 1: Automated Connectors */}
          <div className="xl:col-span-2 space-y-8">
             <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-8">
                <div className="flex items-center justify-between border-b border-gray-50 pb-6">
                   <div className="flex items-center gap-3">
                      <CloudDownload className="text-blue-600" size={20} />
                      <h3 className="text-sm font-black uppercase text-slate-900">Method 1: Direct Integration</h3>
                   </div>
                   <div className="flex items-center gap-2">
                      <span className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
                      <span className="text-[8px] font-black uppercase text-emerald-600">Proxy Ready</span>
                   </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-5">
                   {[
                     { name: 'UN Security Council', url: OFFICIAL_UN_XML_URL, icon: <Globe />, color: 'bg-blue-600', format: 'XML' },
                     { name: 'Qatar MOI (NCTC)', url: QATAR_NCTC_URL, icon: <Shield />, color: 'bg-amber-600', format: 'HTML/PDF' },
                     { name: 'OpenSanctions', url: OPENSANCTIONS_URL, icon: <FileJson />, color: 'bg-emerald-600', format: 'JSON' }
                   ].map(source => (
                     <button 
                       key={source.name}
                       onClick={() => runAutomatedFetch(source.url, source.name)}
                       disabled={status !== 'IDLE' || isGlobalSyncing}
                       className="group p-6 rounded-[2.5rem] border border-slate-100 hover:border-blue-300 hover:bg-blue-50/30 transition-all flex flex-col items-center text-center gap-4 disabled:opacity-30"
                     >
                        <div className={`p-4 rounded-2xl bg-slate-50 text-slate-400 group-hover:${source.color} group-hover:text-white transition-all`}>
                           {React.cloneElement(source.icon as any, { size: 24 })}
                        </div>
                        <div>
                           <h4 className="text-[10px] font-black uppercase text-slate-800 leading-tight">{source.name}</h4>
                           <p className="text-[8px] font-bold text-slate-400 uppercase mt-1 tracking-widest">Type: {source.format}</p>
                        </div>
                     </button>
                   ))}
                </div>

                {successReport && (
                  <div className="p-8 bg-emerald-50 border border-emerald-100 rounded-[2.5rem] space-y-6 animate-in zoom-in-95">
                     <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                           <div className="p-3 bg-emerald-600 text-white rounded-2xl shadow-lg"><CheckCircle size={20}/></div>
                           <div>
                              <p className="text-[10px] font-black text-emerald-900 uppercase">Post-Ingestion Report</p>
                              <h4 className="text-lg font-black text-emerald-950">{successReport.source} Finalized</h4>
                           </div>
                        </div>
                        <Check className="text-emerald-300" size={40} />
                     </div>
                     <div className="grid grid-cols-3 gap-4">
