);

-- Ensure date_of_birth column exists for v3.2.6
DO $$ 
BEGIN 
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='sanctions' AND column_name='date_of_birth') THEN
    ALTER TABLE public.sanctions ADD COLUMN date_of_birth TEXT;
