                </div>

                {successReport && (
                  <div className="p-8 bg-emerald-50 border border-emerald-100 rounded-[2.5rem] space-y-6 animate-in zoom-in-95">
                     <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
