              <div className="p-8 border-t bg-white flex justify-end gap-3 shrink-0">
                 <button onClick={() => setStatus('IDLE')} className="px-10 py-4 font-black text-[10px] uppercase text-slate-400 tracking-[0.2em] hover:text-slate-600">Cancel</button>
                 <button 
