                    className="px-12 py-4 bg-emerald-800 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-900 transition-all flex items-center gap-3"
                 >
                    <ArrowRightLeft size={18}/> Commit Ingestion
