                     ))}
                     {paginatedData.length === 0 && (
                        <tr><td colSpan={5} className="py-40 text-center opacity-30"><BarChart3 className="mx-auto mb-4" size={48}/><p className="text-xs font-black uppercase tracking-[0.3em]">Master Node Empty</p></td></tr>
