export default SanctionsRegistry;

import React, { useState, useEffect, useRef } from 'react';
import { SanctionEntry } from '../types';
import { 
  RefreshCw, Search, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, 
  Upload, Globe, ShieldAlert, FileJson, FileText, ExternalLink, Info, 
  Database, Filter, Activity, FileCheck, ArrowDownToLine 
} from 'lucide-react';
import { OFFICIAL_UN_XML_URL, OFAC_SDN_URL, OPENSANCTIONS_URL } from '../services/unSanctionsService';

interface SanctionsBrowserProps {
  sanctions: SanctionEntry[];
  lastUpdated: string;
  onRefresh: () => void;
  isUpdating: boolean;
  onFileUpload: (file: File, type: 'UN' | 'OFAC' | 'OPEN') => void;
  totalInDb?: number;
  onRetrieveIncremental?: () => void;
}

const ITEMS_PER_PAGE = 15;

const SanctionsBrowser: React.FC<SanctionsBrowserProps> = ({ 
  sanctions, 
  lastUpdated, 
  onRefresh, 
  isUpdating, 
  onFileUpload,
  totalInDb = 0,
  onRetrieveIncremental
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [importMenuOpen, setImportMenuOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [pendingType, setPendingType] = useState<'UN' | 'OFAC' | 'OPEN'>('UN');

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, sanctions]);

  const filtered = sanctions.filter(s => {
    const search = searchTerm.toLowerCase();
    return (
      (s.firstName || '').toLowerCase().includes(search) || 
      (s.lastName || '').toLowerCase().includes(search) ||
      (s.unListType || '').toLowerCase().includes(search) ||
      (s.source || '').toLowerCase().includes(search) ||
      (s.referenceNumber || '').toLowerCase().includes(search) ||
      (s.nationality || '').toLowerCase().includes(search)
    );
  });

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const paginatedData = filtered.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
    }
  };

  const triggerUpload = (type: 'UN' | 'OFAC' | 'OPEN') => {
    setPendingType(type);
    fileInputRef.current?.click();
    setImportMenuOpen(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onFileUpload(e.target.files[0], pendingType);
    }
  };

  return (
    <div className="space-y-6 sm:space-y-8">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
           <h2 className="text-xl sm:text-2xl font-black text-emerald-950 uppercase tracking-tight">Global Screening Registry</h2>
           <p className="text-xs sm:text-sm text-gray-500 mt-1">Cross-referenced verification against manually imported UN, OFAC, and OpenSanctions records.</p>

           <div className="mt-3 flex items-center gap-2">
              <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] sm:text-[10px] font-black uppercase tracking-widest transition-all ${lastUpdated !== 'Never' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-amber-50 text-amber-700 border-amber-100'}`}>
                <FileCheck size={12} className={isUpdating ? 'animate-pulse' : ''} />
                <span>
                  Last Manual Import: {lastUpdated !== 'Never' ? new Date(lastUpdated).toLocaleString() : 'Import Required'}
                </span>
              </div>
              <div className="group relative">
                <Info size={14} className="text-slate-400 cursor-help" />
                <div className="absolute bottom-full left-0 mb-2 w-64 p-3 bg-slate-900 text-white text-[8px] leading-relaxed font-bold uppercase rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50 shadow-2xl">
                  Automatic synchronization is disabled to ensure data integrity and bypass browser security blocks. Please download official XML/CSV feeds from the sources below and use "Import Data" to update.
                </div>
              </div>
           </div>
        </div>
        <div className="flex flex-col xs:flex-row w-full lg:w-auto gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".xml,.csv,.json" className="hidden" />

          {onRetrieveIncremental && (
            <button 
              onClick={onRetrieveIncremental}
              disabled={isUpdating || sanctions.length >= totalInDb}
              className="flex-1 xs:flex-none flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl bg-emerald-800 text-white hover:bg-emerald-900 transition-all shadow-xl shadow-emerald-100 font-black text-[10px] uppercase tracking-widest h-[52px] disabled:opacity-40"
              title="Retrieve an additional 1,000 records from the database"
            >
              <ArrowDownToLine size={18} />
              Expand Registry (+1,000)
            </button>
          )}

          <div className="relative flex-1 xs:flex-none">
            <button 
              onClick={() => setImportMenuOpen(!importMenuOpen)}
              className="w-full flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl bg-blue-600 text-white hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 font-black text-[10px] uppercase tracking-widest h-[52px]"
            >
              <Upload size={18} />
              Import Data
            </button>

            {importMenuOpen && (
              <>
                <div className="fixed inset-0 z-40 xs:hidden" onClick={() => setImportMenuOpen(false)} />
                <div className="absolute left-0 xs:left-auto right-0 bottom-full mb-2 sm:bottom-auto sm:top-full sm:mt-2 w-full xs:w-64 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 p-2 overflow-hidden animate-in fade-in slide-in-from-bottom-2 sm:slide-in-from-top-2">
                  <p className="px-4 py-2 text-[9px] font-black text-gray-400 uppercase tracking-widest">Select Import Protocol</p>
                  <button onClick={() => triggerUpload('UN')} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-blue-50 text-left rounded-xl group transition-colors">
                    <div className="p-2 bg-blue-100 text-blue-600 rounded-lg group-hover:bg-blue-600 group-hover:text-white"><Database size={14}/></div>
                    <div><p className="text-xs font-black text-gray-800">UN XML File</p></div>
                  </button>
                  <button onClick={() => triggerUpload('OFAC')} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-amber-50 text-left rounded-xl group transition-colors">
                    <div className="p-2 bg-amber-100 text-amber-600 rounded-lg group-hover:bg-amber-600 group-hover:text-white"><ShieldAlert size={14}/></div>
                    <div><p className="text-xs font-black text-gray-800">OFAC CSV File</p></div>
                  </button>
                  <button onClick={() => triggerUpload('OPEN')} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-emerald-50 text-left rounded-xl group transition-colors">
                    <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg group-hover:bg-emerald-600 group-hover:text-white"><FileJson size={14}/></div>
                    <div><p className="text-xs font-black text-gray-800">OpenSanctions JSON</p></div>
                  </button>
                </div>
              </>
            )}
          </div>

          <button 
            onClick={onRefresh}
            disabled={isUpdating}
            className="flex-1 xs:flex-none flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl bg-white border border-gray-200 text-emerald-950 hover:bg-emerald-50 transition-all shadow-sm font-black text-[10px] uppercase tracking-widest h-[52px]"
          >
            <RefreshCw size={18} className={isUpdating ? 'animate-spin' : ''} />
            {isUpdating ? 'Refreshing...' : 'Refresh View'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {[
          { label: 'UN Security Council', value: 'Download XML', icon: <Globe />, color: 'blue', url: OFFICIAL_UN_XML_URL },
          { label: 'U.S. Treasury', value: 'Download CSV', icon: <ShieldAlert />, color: 'amber', url: OFAC_SDN_URL },
          { label: 'OpenSanctions', value: 'Download JSON', icon: <FileText />, color: 'emerald', url: OPENSANCTIONS_URL }
        ].map((source, idx) => (
          <a key={idx} href={source.url} target="_blank" rel="noopener noreferrer" className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center justify-between group hover:border-emerald-200 transition-all">
            <div className="flex items-center gap-3 min-w-0">
              <div className="p-2.5 bg-gray-50 text-gray-400 rounded-xl group-hover:bg-emerald-600 group-hover:text-white transition-all shrink-0">{source.icon}</div>
              <div className="min-w-0">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-tighter truncate">{source.label}</p>
                <p className="text-xs font-black text-gray-800 truncate">{source.value}</p>
              </div>
            </div>
            <ExternalLink size={14} className="text-gray-300 group-hover:text-emerald-500 shrink-0 ml-2"/>
          </a>
        ))}
      </div>

      <div className="bg-white p-2 sm:p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-2 sm:gap-4 items-center">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search by legal name, reference ID, or source..." 
            className="w-full pl-12 pr-4 py-3.5 sm:py-4 border-none bg-gray-50/80 rounded-xl focus:ring-2 focus:ring-emerald-800 outline-none transition-all text-sm font-bold placeholder-gray-400"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="hidden xs:flex items-center gap-2 px-4 text-[10px] font-black text-gray-400 uppercase tracking-widest whitespace-nowrap">
           <Info size={14} className="text-emerald-600"/>
           {filtered.length.toLocaleString()} Hits
        </div>
      </div>

      <div className="bg-white rounded-2xl sm:rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col relative">
        <div className="absolute top-0 right-0 h-full w-4 pointer-events-none bg-gradient-to-l from-white/10 to-transparent z-10 md:hidden" />
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse min-w-[1100px]">
            <thead className="bg-gray-50/50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Authority</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">First Name</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Last Name</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Jurisdiction</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Birth Date</th>
                <th className="px-6 py-5 text-right text-[10px] font-black text-gray-400 uppercase tracking-widest">Reference</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {paginatedData.map((entry) => (
                <tr key={entry.dataId} className="hover:bg-emerald-50/20 transition-colors group">
                  <td className="px-6 py-4">
                     <span className="inline-flex items-center px-2 py-1 rounded-lg text-[8px] font-black uppercase border bg-white border-gray-100 text-gray-500 group-hover:border-emerald-200 group-hover:text-emerald-800 transition-all">
                        {entry.source}
                     </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-black text-emerald-950 text-sm uppercase tracking-tight">{entry.firstName || '-'}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-black text-emerald-950 text-sm uppercase tracking-tight">{entry.lastName || '-'}</div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2.5 py-1 rounded-md text-[9px] font-black uppercase bg-gray-50 text-gray-500 border border-gray-100">
                      {entry.nationality || 'Unspecified'}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-xs font-black text-emerald-800 uppercase tracking-tight">{entry.dateOfBirth || 'N/A'}</td>
                  <td className="px-6 py-4 text-right">
                     <div className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{entry.referenceNumber || entry.dataId}</div>
                  </td>
                </tr>
              ))}
              {paginatedData.length === 0 && (
                <tr>
                   <td colSpan={6} className="px-6 py-20 text-center bg-gray-50/10">
                      <div className="flex flex-col items-center gap-4 text-gray-300">
                         <Database size={48} strokeWidth={1}/>
                         <p className="text-xs font-black uppercase tracking-widest text-center px-4">Zero Registry Matches for "{searchTerm}"</p>
                         <p className="text-[10px] text-slate-400 font-bold mt-2 uppercase">Please ensure the latest data file has been imported.</p>
                      </div>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {filtered.length > 0 && (
          <div className="px-6 py-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-gray-50/30">
            <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">
              Page <span className="text-emerald-950">{currentPage}</span> of {totalPages} <span className="mx-2 hidden sm:inline">•</span> <span className="block sm:inline mt-1 sm:mt-0">{filtered.length.toLocaleString()} Records Loaded</span>
              {totalInDb > filtered.length && (
                <span className="block mt-1 text-[8px] text-amber-600 font-black">({totalInDb.toLocaleString()} Total in Registry)</span>
              )}
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={() => handlePageChange(1)} 
                disabled={currentPage === 1}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
                title="Jump to First Page"
              >
                <ChevronsLeft size={20} />
              </button>

              <button 
                onClick={() => handlePageChange(currentPage - 1)} 
                disabled={currentPage === 1}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronLeft size={20} />
              </button>

              <div className="px-6 py-3 text-[10px] font-black text-emerald-950 bg-white rounded-xl border border-gray-200 shadow-sm min-w-[120px] text-center uppercase tracking-widest">
                Tier {currentPage}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)} 
                disabled={currentPage === totalPages}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
              >
                <ChevronRight size={20} />
              </button>

              <button 
                onClick={() => handlePageChange(totalPages)} 
                disabled={currentPage === totalPages}
                className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"
                title="Jump to Final Page"
              >
                <ChevronsRight size={20} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SanctionsBrowser;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsBrowser from './components/SanctionsBrowser';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Loader2 } from 'lucide-react';
import { Client, SanctionEntry, RiskLevel, AppSettings, UserRole, UserProfile, SystemEnvironment } from './types';
import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount,
  fetchSanctionsBatch,
  upsertCloudSanctions,
  fetchClientsTotalCount
} from './services/cloudDb';
import { parseUNSanctionsXML, parseCSVToSanctions, OFFICIAL_UN_XML_URL } from './services/unSanctionsService';
import { screenClient } from './services/screeningEngine';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  environment: SystemEnvironment.PRODUCTION
};

const CLIENTS_PER_PAGE = 15;

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [clientsCount, setClientsCount] = useState(0);
  const [currentClientsPage, setCurrentClientsPage] = useState(1);
  const [isRefreshingClients, setIsRefreshingClients] = useState(false);

  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [isUpdatingSanctions, setIsUpdatingSanctions] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [totalInDb, setTotalInDb] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR'>('CONNECTING');

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    if (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
    }
  }, []);

  const loadSanctionsCache = useCallback(async () => {
    try {
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);
      setSanctionsCount(count);
      const batch = await fetchSanctionsBatch(0, 1000);
      setSanctions(batch);
    } catch (e) {
      console.error("Failed to load sanctions cache", e);
    }
  }, []);

  const refreshClients = useCallback(async (page: number = 1) => {
    setIsRefreshingClients(true);
    try {
      const from = (page - 1) * CLIENTS_PER_PAGE;
      const to = from + CLIENTS_PER_PAGE - 1;
      const [cloudClients, count] = await Promise.all([
        fetchCloudClients(from, to),
        fetchClientsTotalCount()
      ]);
      if (cloudClients) setClients(cloudClients);
      setClientsCount(count);
      setCurrentClientsPage(page);
    } catch (e) {
      console.error("Client refresh failed", e);
    } finally {
      setIsRefreshingClients(false);
    }
  }, []);

  const handleRetrieveIncremental = useCallback(async () => {
    setIsUpdatingSanctions(true);
    try {
      const nextBatch = await fetchSanctionsBatch(sanctions.length, 1000);
      if (nextBatch.length > 0) {
        setSanctions(prev => [...prev, ...nextBatch]);
      }
    } catch (e) {
      console.error("Incremental retrieval failed", e);
    } finally {
      setIsUpdatingSanctions(false);
    }
  }, [sanctions.length]);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');

    try {
      initSupabase();
      const healthy = await checkConnection();

      if (healthy) {
        setConnectionStatus('CONNECTED');
        await Promise.all([
          refreshClients(1),
          loadSanctionsCache(),
          fetchGlobalSyncStatus().then(lockStatus => lockStatus && handleGlobalMetadataUpdate(lockStatus))
        ]);

        if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
        subscriptionRef.current = subscribeToClients(() => {
          refreshClients(currentClientsPage);
        });
        if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
        syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
      } else {
        setConnectionStatus('ERROR');
      }
    } catch (e: any) {
      setConnectionStatus('ERROR');
    }

    setTimeout(() => {
      setIsBooting(false);
    }, 1500);
  }, [handleGlobalMetadataUpdate, loadSanctionsCache, refreshClients, currentClientsPage]);

  useEffect(() => {
    bootEnterpriseNode();
  }, [bootEnterpriseNode]);

  const handleAddClientWithScreening = async (newClient: Client) => {
    const match = screenClient(newClient, sanctions);
    const screenedClient = {
      ...newClient,
      riskLevel: match ? match.riskLevel : RiskLevel.NONE,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };

    if (connectionStatus === 'CONNECTED') {
      try {
        await upsertCloudClient(screenedClient);
        // CRITICAL: Immediately refresh to current page (usually 1) to show new record
        await refreshClients(1); 
      } catch (e) {
        console.error("Failed to persist client:", e);
        throw e; // Propagate to allow UI to handle error
      }
    } else {
      setClients(prev => [screenedClient, ...prev].slice(0, CLIENTS_PER_PAGE));
      setClientsCount(prev => prev + 1);
    }
  };

  const handleSanctionsFileUpload = async (file: File, type: 'UN' | 'OFAC' | 'OPEN') => {
    setIsUpdatingSanctions(true);
    try {
      const text = await file.text();
      let parsed: SanctionEntry[] = [];

      if (type === 'UN') {
        parsed = parseUNSanctionsXML(text);
      } else if (type === 'OFAC') {
        const rawRows = parseCSVToSanctions(text, 'OFAC SDN');
        parsed = rawRows.map((r: any, i: number) => {
          // Attempt to split OFAC name (Last, First)
          let firstName = r.sdn_name || 'Unknown';
          let lastName = '';
          const rawName = r.sdn_name || '';
          if (rawName.includes(',')) {
            const parts = rawName.split(',').map((p: string) => p.trim());
            lastName = parts[0];
            firstName = parts[1];
          }

          return {
            dataId: `OFAC-${r.ent_num || i}`,
            source: 'OFAC SDN',
            firstName: firstName,
            lastName: lastName,
            unListType: r.sdn_type || 'Individual',
            referenceNumber: r.ent_num || '',
            listedOn: new Date().toISOString().split('T')[0],
            comments: r.remarks || '',
            nationality: '',
            aliases: [],
            type: r.sdn_type === 'Entity' ? 'Corporate' : 'Individual',
            fetchDate: new Date().toISOString()
          };
        });
      }

      if (parsed.length > 0) {
        await upsertCloudSanctions(parsed);
        const now = new Date().toLocaleString();
        const stats = { ...registryStats, lastFetch: now, lastSourceUpdate: now };
        setRegistryStats(stats);
        localStorage.setItem('unsg_registry_stats', JSON.stringify(stats));
        await loadSanctionsCache();
      }
    } catch (e) {
      console.error("Manual Import Error:", e);
      alert("Import failed. Verify file structure.");
    } finally {
      setIsUpdatingSanctions(false);
    }
  };

  if (isBooting) {
    return (
      <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-white font-sans">
        <div className="bg-white/5 p-12 rounded-[3.5rem] border border-white/10 flex flex-col items-center gap-10 shadow-2xl animate-pulse">
          <Loader2 className="animate-spin text-emerald-400" size={64} strokeWidth={1.5} />
          <h1 className="text-xs font-black uppercase tracking-[0.5em] text-emerald-50 text-center">SanctionGuard Secure Node v1.8.5</h1>
        </div>
      </div>
    );
  }

  const effectiveEnvironment = (currentUser?.id === 'SYS-ROOT') 
    ? settings.environment 
    : SystemEnvironment.PRODUCTION;

  if (!currentUser) return (
    <Login 
      onLogin={(user) => { 
        setCurrentUser(user); 
        localStorage.setItem('unsg_session', JSON.stringify(user)); 
      }} 
      isCloudConnected={connectionStatus === 'CONNECTED'} 
    />
  );

  if (currentUser.must_change_password) return (
    <PasswordUpdate 
      user={currentUser} 
      onUpdate={async (newPassword) => {
        const updatedUser = { ...currentUser, password: newPassword, must_change_password: false };
        if (connectionStatus === 'CONNECTED') await upsertCloudUser(updatedUser).catch(() => {});
        setCurrentUser(updatedUser);
        localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      }} 
    />
  );

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={() => { 
          setCurrentUser(null); 
          localStorage.removeItem('unsg_session'); 
        }}
        currentUser={currentUser}
        onRetryConnection={() => bootEnterpriseNode()}
        environment={effectiveEnvironment}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              totalCount={clientsCount}
              currentPage={currentClientsPage}
              onPageChange={refreshClients}
              isRefreshing={isRefreshingClients}
              onAddClient={handleAddClientWithScreening} 
              onUpdateClient={async (updated) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(updated);
                setClients(prev => prev.map(c => c.id === updated.id ? updated : c));
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                refreshClients(currentClientsPage);
              }}
              onRefresh={() => refreshClients(currentClientsPage)} 
              currentUserRole={currentUser.role} currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsBrowser 
              sanctions={sanctions}
              lastUpdated={registryStats.lastFetch}
              onRefresh={loadSanctionsCache}
              isUpdating={isUpdatingSanctions}
              onFileUpload={handleSanctionsFileUpload}
              totalInDb={totalInDb}
              onRetrieveIncremental={handleRetrieveIncremental}
            />} />
          <Route path="/admin" element={
            currentUser.is_system_admin === true ? (
              <AdminPanel settings={settings} logs={[]} onUpdateSettings={(s) => {
                setSettings(s);
                localStorage.setItem('unsg_settings', JSON.stringify(s));
              }} currentUser={currentUser} />
            ) : <Navigate to="/" replace />
          } />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

