export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (progress: number) => void) => {
  if (!supabaseClient) return;
  if (isSandbox()) {
    onProgress?.(100);
    return simulateWrite('UpsertCloudSanctions', `${sanctions.length} entries`);
  }
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize).map(s => ({
      data_id: String(s.dataId),
      first_name: String(s.firstName),
      last_name: String(s.lastName),
      source: String(s.source),
      reference_number: String(s.referenceNumber),
      listed_on: String(s.listedOn),
      nationality: String(s.nationality),
      date_of_birth: String(s.dateOfBirth),
      un_list_type: String(s.unListType),
      aliases: s.aliases,
      fetch_date: s.fetchDate || new Date().toISOString()
    }));

    try {
      await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
      if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
    } catch (e) { break; }
  }
};

