export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
  try {
    const { data, error } = await supabaseClient.from('system_metadata').select('value').eq('key', 'global_sync_lock').limit(1);
    if (error || !data?.[0]) return { is_syncing: false, last_sync: 'Never', locked_at: 0 };
    return data[0].value;
  } catch (e) { return { is_syncing: false, last_sync: 'Offline', locked_at: 0 }; }
};

export const subscribeToGlobalSync = (onUpdate: (status: any) => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('metadata-channel').on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'system_metadata' }, (p: any) => onUpdate(p.new?.value)).subscribe();
};

export const fetchCloudClients = async (from = 0, to = 14): Promise<Client[] | null> => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient.from('clients').select('*').order('created_at', { ascending: false }).range(from, to);
    if (error) return [];
    return data.map((row: any) => ({
      id: String(row.id || ''),
      "Client Name": String(row.client_name || row['Client Name'] || ''),
      kyc_status: (row.kyc_status as KYCStatus) || KYCStatus.DRAFT,
