      "Legal Structure": String(row.legal_structure || row['Legal Structure'] || ''),
      "No": String(row.file_no || row['No'] || ''),
      riskLevel: (row.risk_level as RiskLevel) || RiskLevel.NONE,
      entity_type: (row.entity_type as EntityType) || EntityType.CORPORATE,
      created_at: row.created_at,
      created_by: row.created_by,
      "E Mail": String(row.email || ''),
      "Registered Address": String(row.address || '')
    } as Client));
  } catch (e) { return null; }
};

