export const fetchSanctionsBatch = async (offset: number, limit: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient.from('sanctions').select('*').range(offset, offset + limit - 1);
    if (error || !data) return [];

    // v3.2.8 Strict Cast: Prevents numeric values like 36 from failing to render as strings
    return data.map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: String(row.first_name ?? row.firstName ?? row.name ?? ''), 
      lastName: String(row.last_name ?? row.lastName ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? row.referenceNumber ?? ''),
      listedOn: String(row.listed_on ?? row.listedOn ?? ''),
      nationality: String(row.nationality ?? row.country ?? ''),
      dateOfBirth: String(row.date_of_birth ?? row.dateOfBirth ?? ''),
      unListType: String(row.un_list_type ?? row.type ?? 'Designated'),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || row.updated_at || ''
    } as SanctionEntry));
  } catch (e) { return []; }
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void) => {
  if (!supabaseClient) return;
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize).map(s => ({
      data_id: String(s.dataId),
      first_name: String(s.firstName),
      last_name: String(s.lastName),
      source: String(s.source),
      reference_number: String(s.referenceNumber),
      listed_on: String(s.listedOn),
      nationality: String(s.nationality),
      date_of_birth: String(s.dateOfBirth),
      un_list_type: String(s.unListType),
      aliases: s.aliases,
      fetch_date: new Date().toISOString()
    }));
    await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
    if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
  }
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('clients-rt').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
};

