                    <button type="button" onClick={() => setEntityType(EntityType.CORPORATE)} className={`px-4 sm:px-6 py-1.5 rounded-lg sm:rounded-xl text-[10px] font-black transition-all uppercase ${entityType === EntityType.CORPORATE ? 'bg-white text-emerald-900' : 'text-white'}`}>Corp</button>
