                <InputField label="Legal Form" value={formData["Legal Structure"]} onChange={(v:any)=>setFormData({...formData, "Legal Structure": v})} />
              </FormSection>
              <FormSection title="Timelines & Licensing" icon={<Calendar size={18}/>}>
                <InputField label="Incorporation Date" type="date" value={formData["Date of QFC Incorporation or Registration"]} onChange={(v:any)=>setFormData({...formData, "Date of QFC Incorporation or Registration": v})} />
                <InputField label="CR Expiry" type="date" value={formData["CR Expired date"]} onChange={(v:any)=>setFormData({...formData, "CR Expired date": v})} />
                <InputField label="License Number" value={formData["License"]} onChange={(v:any)=>setFormData({...formData, "License": v})} />
                <InputField label="License Expiry" type="date" value={formData["License Expiry"]} onChange={(v:any)=>setFormData({...formData, "License Expiry": v})} />
              </FormSection>
              <FormSection title="Governance Structure" icon={<Users size={18}/>} fullWidth>
                <PersonRecordList label="Directors / UBOs" items={formData["Directors Names"]} onChange={(v) => setFormData({...formData, "Directors Names": v})} />
              </FormSection>
              <div className="flex flex-col xs:flex-row justify-end gap-3 pb-8 sticky bottom-0 bg-white/90 backdrop-blur-md pt-5 border-t border-gray-100 z-10">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-8 py-4 font-black text-[10px] uppercase tracking-widest text-gray-400 hover:text-gray-600 order-2 xs:order-1">Cancel</button>
                <button type="submit" disabled={isSubmitting} className="w-full xs:w-auto bg-emerald-800 text-white px-10 py-4 rounded-xl sm:rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-emerald-900 flex justify-center items-center gap-2 order-1 xs:order-2 disabled:opacity-50">{isSubmitting ? <Loader2 size={20} className="animate-spin" /> : <CheckCircle2 size={20}/>} {isSubmitting ? 'Committing...' : 'Commit Entity'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
