import React, { useState, useEffect, useRef } from 'react';
import { SanctionEntry } from '../types';
import { 
  RefreshCw, Search, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, 
  Upload, Globe, ShieldAlert, FileJson, FileText, ExternalLink, Info, 
  Database, Filter, Activity, FileCheck, ArrowDownToLine 
} from 'lucide-react';
import { OFFICIAL_UN_XML_URL, OFAC_SDN_URL, OPENSANCTIONS_URL } from '../services/unSanctionsService';

interface SanctionsBrowserProps {
  sanctions: SanctionEntry[];
  lastUpdated: string;
  onRefresh: () => void;
  isUpdating: boolean;
  onFileUpload: (file: File, type: 'UN' | 'OFAC' | 'OPEN') => void;
  totalInDb?: number;
  onRetrieveIncremental?: () => void;
}

const ITEMS_PER_PAGE = 15;

const SanctionsBrowser: React.FC<SanctionsBrowserProps> = ({ 
  sanctions, 
  lastUpdated, 
  onRefresh, 
  isUpdating, 
  onFileUpload,
  totalInDb = 0,
  onRetrieveIncremental
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [importMenuOpen, setImportMenuOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [pendingType, setPendingType] = useState<'UN' | 'OFAC' | 'OPEN'>('UN');

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, sanctions]);

  const filtered = sanctions.filter(s => {
    const search = searchTerm.trim().toLowerCase();
    if (!search) return true;
    const matchesField = (val: any) => {
        if (val === undefined || val === null) return false;
        return String(val).toLowerCase().includes(search);
    };
    return (
      matchesField(s.firstName) || 
      matchesField(s.lastName) ||
      matchesField(s.unListType) ||
      matchesField(s.source) ||
      matchesField(s.referenceNumber) ||
      matchesField(s.nationality) ||
      matchesField(s.dataId)
    );
  });

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
  const paginatedData = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) setCurrentPage(page);
  };

  const triggerUpload = (type: 'UN' | 'OFAC' | 'OPEN') => {
    setPendingType(type);
    fileInputRef.current?.click();
    setImportMenuOpen(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) onFileUpload(e.target.files[0], pendingType);
  };

  return (
    <div className="space-y-6 sm:space-y-8">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
           <h2 className="text-xl sm:text-2xl font-black text-emerald-950 uppercase tracking-tight">Global Screening Registry</h2>
           <p className="text-xs sm:text-sm text-gray-500 mt-1">Cross-referenced verification against manually imported UN, OFAC, and OpenSanctions records.</p>
           <div className="mt-3 flex items-center gap-2">
              <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] sm:text-[10px] font-black uppercase tracking-widest transition-all ${lastUpdated !== 'Never' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-amber-50 text-amber-700 border-amber-100'}`}>
                <FileCheck size={12} className={isUpdating ? 'animate-pulse' : ''} />
                <span>Last Manual Import: {lastUpdated !== 'Never' ? new Date(lastUpdated).toLocaleString() : 'Import Required'}</span>
              </div>
           </div>
        </div>
        <div className="flex flex-col xs:flex-row w-full lg:w-auto gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
          {onRetrieveIncremental && (
            <button onClick={onRetrieveIncremental} disabled={isUpdating || sanctions.length >= totalInDb} className="flex-1 xs:flex-none flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl bg-emerald-800 text-white hover:bg-emerald-900 font-black text-[10px] uppercase h-[52px] disabled:opacity-40">
              <ArrowDownToLine size={18} /> Expand Registry (+1,000)
            </button>
          )}
          <div className="relative flex-1 xs:flex-none">
            <button onClick={() => setImportMenuOpen(!importMenuOpen)} className="w-full flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl bg-blue-600 text-white hover:bg-blue-700 font-black text-[10px] uppercase h-[52px]">
              <Upload size={18} /> Import Data
            </button>
            {importMenuOpen && (
              <div className="absolute left-0 xs:left-auto right-0 top-full mt-2 w-full xs:w-64 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 p-2 overflow-hidden">
                <button onClick={() => triggerUpload('UN')} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-blue-50 text-left rounded-xl transition-colors">
                  <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Database size={14}/></div>
                  <span className="text-xs font-black text-gray-800">UN XML</span>
                </button>
                <button onClick={() => triggerUpload('OFAC')} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-amber-50 text-left rounded-xl transition-colors">
                  <div className="p-2 bg-amber-100 text-amber-600 rounded-lg"><ShieldAlert size={14}/></div>
                  <span className="text-xs font-black text-gray-800">OFAC CSV</span>
                </button>
              </div>
            )}
          </div>
          <button onClick={onRefresh} disabled={isUpdating} className="flex-1 xs:flex-none flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl bg-white border border-gray-200 text-emerald-950 font-black text-[10px] uppercase h-[52px]">
            <RefreshCw size={18} className={isUpdating ? 'animate-spin' : ''} /> Refresh
          </button>
        </div>
      </div>

      <div className="bg-white p-2 sm:p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-2 sm:gap-4 items-center">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input type="text" placeholder="Search by name, ID, or source..." className="w-full pl-12 pr-4 py-4 border-none bg-gray-50/80 rounded-xl focus:ring-2 focus:ring-emerald-800 outline-none text-sm font-bold placeholder-gray-400" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
        </div>
        <div className="hidden xs:flex items-center gap-2 px-4 text-[10px] font-black text-gray-400 uppercase">
           {filtered.length.toLocaleString()} Hits
        </div>
      </div>

      <div className="bg-white rounded-2xl sm:rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col relative">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse min-w-[1100px]">
            <thead className="bg-gray-50/50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Protocol</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">First Name</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Last Name</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Jurisdiction</th>
                <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Birth Date</th>
                <th className="px-6 py-5 text-right text-[10px] font-black text-gray-400 uppercase tracking-widest">Ref ID</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {paginatedData.map((entry) => (
                <tr key={entry.dataId} className="hover:bg-emerald-50/20 transition-colors group">
                  <td className="px-6 py-4"><span className="inline-flex items-center px-2 py-1 rounded-lg text-[8px] font-black uppercase border bg-white border-gray-100 text-gray-500 group-hover:text-emerald-800">{entry.source}</span></td>
                  <td className="px-6 py-4 font-black text-emerald-950 text-sm uppercase">{String(entry.firstName ?? '') || '-'}</td>
                  <td className="px-6 py-4 font-black text-emerald-950 text-sm uppercase">{String(entry.lastName ?? '') || '-'}</td>
                  <td className="px-6 py-4"><span className="px-2.5 py-1 rounded-md text-[9px] font-black uppercase bg-gray-50 text-gray-500">{entry.nationality || 'Unspecified'}</span></td>
                  <td className="px-6 py-4 text-xs font-black text-emerald-800 uppercase">{entry.dateOfBirth || 'N/A'}</td>
                  <td className="px-6 py-4 text-right text-[10px] text-gray-400 font-bold uppercase">{entry.referenceNumber || entry.dataId}</td>
                </tr>
              ))}
              {paginatedData.length === 0 && (
                <tr><td colSpan={6} className="py-20 text-center opacity-30 font-black uppercase tracking-widest">No matching records found.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        {filtered.length > 0 && (
          <div className="px-6 py-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-gray-50/30">
            <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Page <span className="text-emerald-950">{currentPage}</span> of {totalPages}</div>
            <div className="flex items-center gap-2">
              <button onClick={() => handlePageChange(1)} disabled={currentPage === 1} className="p-3 bg-white border rounded-xl hover:bg-emerald-50 disabled:opacity-30"><ChevronsLeft size={20} /></button>
              <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-3 bg-white border rounded-xl hover:bg-emerald-50 disabled:opacity-30"><ChevronLeft size={20} /></button>
              <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-3 bg-white border rounded-xl hover:bg-emerald-50 disabled:opacity-30"><ChevronRight size={20} /></button>
              <button onClick={() => handlePageChange(totalPages)} disabled={currentPage === totalPages} className="p-3 bg-white border rounded-xl hover:bg-emerald-50 disabled:opacity-30"><ChevronsRight size={20} /></button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SanctionsBrowser;

import React, { useState } from 'react';
import { Client, RiskLevel, PersonRecord, KYCStatus, EntityType, UserRole } from '../types';
import { 
  Plus, Trash2, Eye, RefreshCw, X, CheckCircle2, Landmark, Users, Mail, FileCheck, Shield, 
  UserPlus, FileText, ArrowRight, ShieldAlert, Printer, Calendar, Briefcase, UserCheck, 
  Gavel, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, Loader2, ScanSearch
} from 'lucide-react';

// Added CLIENTS_PER_PAGE constant to match App.tsx configuration
const CLIENTS_PER_PAGE = 15;

interface FormSectionProps {
  title: string;
  icon: React.ReactNode;
  children?: React.ReactNode;
  fullWidth?: boolean;
}

const FormSection: React.FC<FormSectionProps> = ({ title, icon, children, fullWidth = false }) => (
  <div className="bg-white p-5 sm:p-8 rounded-2xl sm:rounded-[2rem] border border-gray-100 shadow-sm space-y-6">
    <div className="flex items-center gap-4 text-emerald-800 font-black border-b border-gray-50 pb-4">
      <div className="bg-emerald-50 p-2.5 rounded-xl">{icon}</div>
      <span className="text-[10px] uppercase tracking-[0.2em]">{title}</span>
    </div>
    <div className={fullWidth ? "w-full" : "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-5 sm:gap-6"}>{children}</div>
  </div>
);

const InputField = ({ label, value, onChange, type = "text", placeholder = "", required = false }: any) => (
  <div className="space-y-1.5 sm:space-y-2">
    <div className="flex justify-between">
        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block ml-1">{label}</label>
        {required && <span className="text-[9px] text-amber-600 font-black uppercase">Required</span>}
    </div>
    <input 
      type={type} 
      placeholder={placeholder}
      className="w-full bg-gray-50 border-2 border-transparent rounded-xl sm:rounded-2xl p-3 sm:p-4 text-sm font-bold text-emerald-950 focus:border-emerald-800 focus:bg-white outline-none transition-all" 
      value={value} 
      onChange={e => onChange(e.target.value)} 
      required={required} 
    />
  </div>
);

const PersonRecordList = ({ label, items, onChange }: { label: string, items: PersonRecord[], onChange: (items: PersonRecord[]) => void }) => {
  const safeItems = Array.isArray(items) ? items : [];
  const addItem = () => onChange([...safeItems, { name: '', qid_passport: '', nationality: '', dob: '' }]);
  const updateItem = (index: number, field: keyof PersonRecord, value: string | number) => {
    const newItems = [...safeItems];
    newItems[index] = { ...newItems[index], [field]: value };
    onChange(newItems);
  };
  const removeItem = (index: number) => onChange(safeItems.filter((_, i) => i !== index));

  return (
    <div className="w-full space-y-4">
      <div className="flex flex-col xs:flex-row justify-between items-start xs:items-center bg-emerald-950/5 p-4 rounded-xl sm:rounded-2xl gap-3">
        <label className="text-[9px] font-black text-emerald-900 uppercase tracking-widest ml-2">{label}</label>
        <button type="button" onClick={addItem} className="w-full xs:w-auto text-[9px] uppercase tracking-widest flex justify-center items-center gap-2 bg-emerald-800 text-white px-4 py-2.5 rounded-xl font-black hover:bg-emerald-900 transition-all">
          <UserPlus size={14} /> Add Record
        </button>
      </div>
      {safeItems.length === 0 && (
        <div className="text-center py-6 border-2 border-dashed border-gray-100 rounded-xl sm:rounded-[2rem]">
          <p className="text-[10px] text-gray-400 font-black uppercase">No records added</p>
        </div>
      )}
      <div className="grid grid-cols-1 gap-4">
        {safeItems.map((item, idx) => (
          <div key={idx} className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 p-5 sm:p-6 bg-gray-50 rounded-xl sm:rounded-[2rem] border border-gray-100 relative group">
            <div className="sm:col-span-2 lg:col-span-2">
              <InputField label="Name / Entity" value={item.name} onChange={(v: string) => updateItem(idx, 'name', v)} />
            </div>
            <InputField label="ID / Passport" value={item.qid_passport} onChange={(v: string) => updateItem(idx, 'qid_passport', v)} />
            <InputField label="Nationality" value={item.nationality} onChange={(v: string) => updateItem(idx, 'nationality', v)} />
            <div className="flex items-end gap-3">
              <div className="flex-1">
                 {label.includes('Shareholder') ? (
                   <InputField label="Share %" type="number" value={item.percentage} onChange={(v: any) => updateItem(idx, 'percentage', parseFloat(v))} />
                 ) : (
                   <InputField label="Date of Birth" type="date" value={item.dob} onChange={(v: string) => updateItem(idx, 'dob', v)} />
                 )}
              </div>
              <button type="button" onClick={() => removeItem(idx)} className="p-3 sm:p-4 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all">
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

interface ClientManagerProps {
  clients: Client[];
  totalCount: number;
  currentPage: number;
  onPageChange: (page: number) => void;
  isRefreshing: boolean;
  onAddClient: (client: Client) => Promise<void>;
  onDeleteClient: (id: string) => void;
  onUpdateClient?: (client: Client) => void;
  onRefresh: () => void;
  onReScreen?: () => void;
  currentUserRole: UserRole;
  currentUserId: string;
}

