  clients, 
  totalCount,
  currentPage,
  onPageChange,
  isRefreshing,
  onAddClient, 
  onDeleteClient, 
  onUpdateClient, 
  onRefresh, 
  onReScreen,
  currentUserRole, 
  currentUserId 
}) => {
