/**
 * Iterative Levenshtein distance for fuzzy string comparison.
 */
const levenshtein = (a: string, b: string): number => {
  const matrix = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
  for (let i = 0; i <= a.length; i++) matrix[i][0] = i;
  for (let j = 0; j <= b.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1].toLowerCase() === b[j - 1].toLowerCase() ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }
  return matrix[a.length][b.length];
};

/**
 * Calculates similarity between two strings, favoring containment.
 * Returns a score between 0 and 1.
 */
const calculateSimilarity = (s1: string, s2: string): number => {
  if (!s1 || !s2) return 0;
  const str1 = s1.trim().toLowerCase();
  const str2 = s2.trim().toLowerCase();

  if (str1 === str2) return 1.0;

  // High-weight containment check: If one name is entirely inside the other.
  if (str1.includes(str2) || str2.includes(str1)) {
    const longerLen = Math.max(str1.length, str2.length);
    const shorterLen = Math.min(str1.length, str2.length);
    // Base score for containment is 0.85 (High), plus a factor of how much of the name matches.
    return 0.85 + (0.15 * (shorterLen / longerLen));
  }

  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  return (longer.length - levenshtein(longer, shorter)) / longer.length;
};

/**
 * Token-based Inclusion Model.
 * This is the critical logic for "12559 DURANSOY".
 * It checks what percentage of the SANCTIONED name tokens are found in the CLIENT name.
 */
const calculateInclusionScore = (clientName: string, sanctionedName: string): number => {
  // Normalize and tokenize. Remove pure numeric tokens from the sanction side (unlikely), 
  // but keep them in the client side to check against.
  const cTokens = clientName.toLowerCase().split(/[\s,.-]+/).filter(t => t.length > 0);
  const sTokens = sanctionedName.toLowerCase().split(/[\s,.-]+/).filter(t => t.length > 1); // Ignore single-char initials

  if (sTokens.length === 0) return 0;

  let matchCount = 0;
  sTokens.forEach(st => {
    // Check if this specific sanctioned token is "included" in any client token
    // We use a high threshold (0.9) to signify an identity match for that token
    const isFound = cTokens.some(ct => ct === st || calculateSimilarity(ct, st) > 0.9);
    if (isFound) matchCount++;
  });

  // Percentage of sanctioned identity found in the client string
  return matchCount / sTokens.length;
};

export const screenClient = (client: Client, sanctions: SanctionEntry[]): MatchResult | null => {
  let bestMatch: MatchResult | null = null;
  let highestScore = 0;

  const clientName = (client["Client Name"] || "").trim().toUpperCase();
  if (!clientName) return null;

  for (const sanction of sanctions) {
    const sFullName = [sanction.firstName, sanction.lastName]
      .filter(Boolean).join(' ').trim().toUpperCase();

    const aliases = Array.isArray(sanction.aliases) ? sanction.aliases : [];
    const checkNames = [sFullName, ...aliases.map(a => a.toUpperCase())].filter(Boolean);

    let maxEntryScore = 0;
    for (const sName of checkNames) {
      // 1. Inclusion Analysis (80% weight) - Critical for handling prefixes/noise like "12559"
      const inclusionScore = calculateInclusionScore(clientName, sName);

      // 2. Global Fuzzy Similarity (20% weight) - Overall string structure
      const fuzzyScore = calculateSimilarity(clientName, sName);

      // If inclusion is 100% (all sanctioned tokens found), we boost the score significantly.
      const weightedScore = inclusionScore === 1 ? (0.95 + (fuzzyScore * 0.05)) : (inclusionScore * 0.8) + (fuzzyScore * 0.2);

      if (weightedScore > maxEntryScore) maxEntryScore = weightedScore;
    }

    const finalScore = Math.min(100, Math.round(maxEntryScore * 100));

    if (finalScore > highestScore) {
      highestScore = finalScore;

      let risk = RiskLevel.NONE;

      /**
       * RISK LEVEL DEFINITIONS (Compliance-Standard):
       * HIGH (>= 85): Identity Confirmation. All or most sanctioned name tokens present.
       * MEDIUM (>= 50): Suspicious Overlap. Significant fuzzy match or partial token match.
       * LOW (>= 20): Potential Noise. Minor similarity requiring monitoring but lower priority.
       */
      if (finalScore >= 85) risk = RiskLevel.HIGH;
      else if (finalScore >= 50) risk = RiskLevel.MEDIUM;
      else if (finalScore >= 20) risk = RiskLevel.LOW;

      if (risk !== RiskLevel.NONE) {
        bestMatch = {
          clientId: client.id,
          sanctionId: sanction.dataId,
          score: finalScore,
          riskLevel: risk,
          matchedFields: ['Name Inclusion'],
          timestamp: new Date().toISOString()
        };
      }
    }
  }

  return bestMatch;
};

