/**
 * AUTHORITATIVE SEARCH: Queries the sanctions table using name fragments.
 * Searches first_name, last_name, and the aliases JSONB field.
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];

  const normalized = name.trim().toUpperCase();
  // Split name into meaningful fragments, ignoring purely numeric ones for candidate searching 
  // if they are too short, but keeping significant ones like "DURANSOY"
  const fragments = normalized.split(/[\s,.-]+/).filter(f => f.length >= 3 || (f.length >= 2 && isNaN(Number(f))));

  try {
    let query = supabaseClient.from('sanctions').select('*');

    if (fragments.length > 0) {
      // Build filter covering primary names and the aliases field cast to text
      const filterParts = fragments.map(f => 
        `first_name.ilike.%${f}%,last_name.ilike.%${f}%,aliases.at.text.ilike.%${f}%`
      ).join(',');
      query = query.or(filterParts);
    } else {
      query = query.ilike('first_name', `%${normalized}%`).or(`last_name.ilike.%${normalized}%`);
    }

    const { data, error } = await query.limit(1000);
    if (error || !data) return [];

    return data.map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: String(row.first_name ?? ''), 
      lastName: String(row.last_name ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? ''),
      listedOn: String(row.listed_on ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? ''),
      unListType: String(row.un_list_type ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e) {
    return [];
  }
};

