import { Client, SanctionEntry, MatchResult, RiskLevel } from '../types';

/**
 * Iterative Levenshtein distance for fuzzy string comparison.
 */
const levenshtein = (a: string, b: string): number => {
  const matrix = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
  for (let i = 0; i <= a.length; i++) matrix[i][0] = i;
  for (let j = 0; j <= b.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1].toLowerCase() === b[j - 1].toLowerCase() ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }
  return matrix[a.length][b.length];
};

/**
 * Calculates similarity between two strings, favoring containment.
 * Returns a score between 0 and 1.
 */
const calculateSimilarity = (s1: string, s2: string): number => {
  if (!s1 || !s2) return 0;
  const str1 = s1.trim().toLowerCase();
  const str2 = s2.trim().toLowerCase();

  if (str1 === str2) return 1.0;

  // High-weight containment check: If one name is entirely inside the other.
  if (str1.includes(str2) || str2.includes(str1)) {
    return 0.95; // High confidence for any substring match
  }

  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  return (longer.length - levenshtein(longer, shorter)) / longer.length;
};

/**
 * Token-based Inclusion Model.
 * Specifically handles cases like "12559 DURANSOY".
 * It determines if the identity of the sanction list entry is 'fully present' in the client string.
 */
const calculateInclusionScore = (clientName: string, sanctionedName: string): number => {
  const clientNormalized = clientName.toLowerCase();
  const sanctionNormalized = sanctionedName.toLowerCase();

  // 1. Direct Substring Check: If the entire sanctioned name is a part of the client name
  // e.g., "DURANSOY" is in "12559 DURANSOY"
  if (clientNormalized.includes(sanctionNormalized)) return 1.0;

  // 2. Token-by-Token Check
  const cTokens = clientNormalized.split(/[\s,.-]+/).filter(t => t.length > 0);
  const sTokens = sanctionNormalized.split(/[\s,.-]+/).filter(t => t.length > 1);

  if (sTokens.length === 0) return 0;

  let matchCount = 0;
  sTokens.forEach(st => {
    // If the sanction token is found as a whole word in the client name
    const isFound = cTokens.some(ct => ct === st || calculateSimilarity(ct, st) > 0.9);
    if (isFound) matchCount++;
  });

  return matchCount / sTokens.length;
};

export const screenClient = (client: Client, sanctions: SanctionEntry[]): MatchResult | null => {
  let bestMatch: MatchResult | null = null;
  let highestScore = 0;

  const clientNameRaw = (client["Client Name"] || "").trim().toUpperCase();
  if (!clientNameRaw) return null;

  for (const sanction of sanctions) {
    const sFullName = [sanction.firstName, sanction.lastName]
      .filter(Boolean).join(' ').trim().toUpperCase();

    const aliases = Array.isArray(sanction.aliases) ? sanction.aliases : [];
    const checkNames = [sFullName, ...aliases.map(a => a.toUpperCase())].filter(Boolean);

    let maxEntryScore = 0;
    for (const sName of checkNames) {
      // Inclusion analysis is primary (e.g. "DURANSOY" vs "12559 DURANSOY")
      const inclusionScore = calculateInclusionScore(clientNameRaw, sName);
      const fuzzyScore = calculateSimilarity(clientNameRaw, sName);

      // If the sanction is "included" (100% tokens or substring), we force the score to high-confidence
      let weightedScore = 0;
      if (inclusionScore === 1.0) {
        weightedScore = 1.0; // Identity Match Found
      } else {
        weightedScore = (inclusionScore * 0.7) + (fuzzyScore * 0.3);
      }

      if (weightedScore > maxEntryScore) maxEntryScore = weightedScore;
    }

    const finalScore = Math.min(100, Math.round(maxEntryScore * 100));

    if (finalScore > highestScore) {
      highestScore = finalScore;

      let risk = RiskLevel.NONE;

      /**
       * AUTHORITATIVE THRESHOLDS
       * HIGH (>= 80): Identity match (e.g. "12559 DURANSOY" hit on "DURANSOY")
       * MEDIUM (>= 45): Significant overlap
       * LOW (>= 15): Minor similarity
       */
      if (finalScore >= 80) risk = RiskLevel.HIGH;
      else if (finalScore >= 45) risk = RiskLevel.MEDIUM;
      else if (finalScore >= 15) risk = RiskLevel.LOW;

      if (risk !== RiskLevel.NONE) {
        bestMatch = {
          clientId: client.id,
          sanctionId: sanction.dataId,
          score: finalScore,
          riskLevel: risk,
          matchedFields: ['Identity Content Match'],
          timestamp: new Date().toISOString()
        };
      }
    }
  }

  return bestMatch;
};

