/**
 * Iterative Levenshtein distance for fuzzy string comparison.
 */
const levenshtein = (a: string, b: string): number => {
  const matrix = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
  for (let i = 0; i <= a.length; i++) matrix[i][0] = i;
  // Fix: Removed duplicate 'j =' which caused a reference error
  for (let j = 0; j <= b.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1].toLowerCase() === b[j - 1].toLowerCase() ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }
  return matrix[a.length][b.length];
};

/**
 * Calculates similarity between two strings.
 * Returns a score between 0 and 1.
 */
const calculateSimilarity = (s1: string, s2: string): number => {
  if (!s1 || !s2) return 0;
  const str1 = s1.trim().toLowerCase();
  const str2 = s2.trim().toLowerCase();

  if (str1 === str2) return 1.0;

  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  return (longer.length - levenshtein(longer, shorter)) / longer.length;
};

/**
 * Checks if the sanctioned identity is "exactly" within the client name.
 * Handles cases like "12559 DURANSOY" hitting "DURANSOY".
 */
const isExactIdentityMatch = (clientName: string, sanctionedName: string): boolean => {
  const cNorm = clientName.toLowerCase();
  const sNorm = sanctionedName.toLowerCase();

  // Rule 1: Full substring containment (Identity included in string)
  if (cNorm.includes(sNorm)) return true;

  // Rule 2: Token-based identity match
  const cTokens = cNorm.split(/[\s,.-]+/).filter(t => t.length > 0);
  const sTokens = sNorm.split(/[\s,.-]+/).filter(t => t.length > 1);

  if (sTokens.length === 0) return false;

  // Check if every token of the sanctioned name exists in the client name
  return sTokens.every(st => cTokens.some(ct => ct === st || calculateSimilarity(ct, st) > 0.95));
};

export const screenClient = (client: Client, sanctions: SanctionEntry[]): MatchResult | null => {
  let bestMatch: MatchResult | null = null;
  let highestScore = 0;

  const clientName = (client["Client Name"] || "").trim().toUpperCase();
  if (!clientName) return null;

  for (const sanction of sanctions) {
    const sFullName = [sanction.firstName, sanction.lastName]
      .filter(Boolean).join(' ').trim().toUpperCase();

    const aliases = Array.isArray(sanction.aliases) ? sanction.aliases : [];
    const checkNames = [sFullName, ...aliases.map(a => a.toUpperCase())].filter(Boolean);

    let maxMatchScore = 0;
    let currentRisk = RiskLevel.NONE;

    for (const sName of checkNames) {
      // DETERMINISTIC RULE 1: Exact / Identity Containment match
      if (isExactIdentityMatch(clientName, sName)) {
        maxMatchScore = 1.0;
        currentRisk = RiskLevel.HIGH;
        break; // Found highest possible match
      }

      // DETERMINISTIC RULE 2: Partial / Fuzzy match
      const fuzzy = calculateSimilarity(clientName, sName);
      if (fuzzy > 0.45 && fuzzy > maxMatchScore) {
        maxMatchScore = fuzzy;
        currentRisk = RiskLevel.MEDIUM; // Mapped to "Potential Match"
      }
    }

    const finalScore = Math.round(maxMatchScore * 100);

    if (finalScore > highestScore || (finalScore === highestScore && currentRisk === RiskLevel.HIGH)) {
      highestScore = finalScore;

      // DETERMINISTIC RULE 3: No match (Clear)
      if (maxMatchScore < 0.15) currentRisk = RiskLevel.NONE;

      if (currentRisk !== RiskLevel.NONE) {
        bestMatch = {
          clientId: client.id,
          sanctionId: sanction.dataId,
          score: finalScore,
          riskLevel: currentRisk,
          matchedFields: currentRisk === RiskLevel.HIGH ? ['Identity Match'] : ['Potential Match'],
          timestamp: new Date().toISOString()
        };
      }
    }
  }

  return bestMatch;
};

