  if (str1.includes(str2) || str2.includes(str1)) return 0.95;

  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  return (longer.length - levenshtein(longer, shorter)) / longer.length;
};

/**
 * MANDATORY COMPLIANCE EVALUATOR:
 * Returns whether a match is detected and the corresponding type.
 * Thresholds are deliberately low (0.25 fuzzy, 0.4 token) to favor false positives over missed hits.
 */
const isMandatoryHighRiskMatch = (clientName: string, sanctionedName: string): { isMatch: boolean; type: string } => {
  const cNorm = clientName.toLowerCase();
  const sNorm = sanctionedName.toLowerCase();

  // 1. Direct containment or exact match
  if (cNorm === sNorm) return { isMatch: true, type: 'Exact Identity Match' };
  if (cNorm.includes(sNorm) || sNorm.includes(cNorm)) return { isMatch: true, type: 'Identity Containment' };

  // 2. Token-based matching (e.g., "John Smith" matches "Smith, John")
  const cTokens = cNorm.split(/[\s,.-]+/).filter(t => t.length > 1);
  const sTokens = sNorm.split(/[\s,.-]+/).filter(t => t.length > 1);

  if (sTokens.length === 0) return { isMatch: false, type: 'No Match' };

  let matches = 0;
  for (const st of sTokens) {
    if (cTokens.some(ct => ct === st || calculateSimilarity(ct, st) > 0.85)) {
      matches++;
    }
  }

  // MANDATORY RULE: If any significant token matches (>= 40% threshold), it is HIGH RISK.
  if (matches > 0 && (matches / sTokens.length) >= 0.4) {
    return { isMatch: true, type: 'Partial/Token Match' };
  }

  // 3. Aggressive fuzzy similarity floor (0.25)
  const fuzzy = calculateSimilarity(cNorm, sNorm);
  if (fuzzy > 0.25) {
    return { isMatch: true, type: 'Fuzzy Similarity Match' };
  }

  return { isMatch: false, type: 'No Match' };
};

export const screenClient = (client: Client, sanctions: SanctionEntry[]): MatchResult | null => {
  let bestMatch: MatchResult | null = null;
  let highestScore = 0;

  const clientName = (client["Client Name"] || "").trim().toUpperCase();
  if (!clientName) return null;

  for (const sanction of sanctions) {
    const sFullName = [sanction.firstName, sanction.lastName]
      .filter(Boolean).join(' ').trim().toUpperCase();

    const aliases = Array.isArray(sanction.aliases) ? sanction.aliases : [];
    const checkNames = [sFullName, ...aliases.map(a => a.toUpperCase())].filter(Boolean);

    let currentEntryBestType = '';
    let currentEntryMaxScore = 0;

    for (const sName of checkNames) {
      const { isMatch, type } = isMandatoryHighRiskMatch(clientName, sName);

      if (isMatch) {
        const score = type === 'Exact Identity Match' ? 1.0 : calculateSimilarity(clientName, sName);
        if (score > currentEntryMaxScore) {
          currentEntryMaxScore = score;
          currentEntryBestType = type;
        }
      }
    }

    if (currentEntryBestType) {
      const finalScore = Math.round(Math.max(0.1, currentEntryMaxScore) * 100);

      // MANDATORY ENFORCEMENT: Any detected match is automatically HIGH RISK.
      // This classification is non-optional and non-overridable.
      if (finalScore > highestScore) {
        highestScore = finalScore;

        bestMatch = {
          clientId: client.id,
          sanctionId: sanction.dataId,
          score: finalScore,
          riskLevel: RiskLevel.HIGH,
          matchedFields: [currentEntryBestType],
          timestamp: new Date().toISOString()
        };
      }
    }
  }

  return bestMatch;
};

