/**
 * Upsert cloud client record.
 * MANDATORY RULE: Re-screens the entity right before saving to ensure
 * high-risk status is system-enforced and cannot be manually downgraded.
 */
export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) return;

  // SYSTEM ENFORCEMENT: Re-verify sanctions before persistence to ensure
  // compliance with the non-optional high-risk classification rule.
  let clientToSave = client;
  try {
    const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
    const match = screenClient(client, candidates);

    // If a match is detected, force RiskLevel.HIGH regardless of incoming state.
    if (match && match.riskLevel === RiskLevel.HIGH) {
      clientToSave = {
        ...client,
        riskLevel: RiskLevel.HIGH,
        matches: match ? [match.sanctionId] : (client.matches || []),
        lastScreenedAt: new Date().toISOString()
      };

      // Audit the enforced high-risk hit
      await logScreeningAudit(
        clientToSave.id, 
        clientToSave["Client Name"], 
        match.sanctionId, 
        match.matchedFields[0], 
        RiskLevel.HIGH, 
        'SYSTEM-ENFORCEMENT'
      );
    }
  } catch (e) {
    console.error("Enforcement Engine Error:", e);
    // Continue with original client if engine fails, though normally this shouldn't happen.
  }

  const dbClient = {
    id: clientToSave.id,
    client_name: clientToSave["Client Name"],
    company_nationality: clientToSave["Company Nationality"],
    qfc_no: clientToSave["QFC No"],
    legal_structure: clientToSave["Legal Structure"],
    file_no: clientToSave["No"],
    email: clientToSave["E Mail"],
    address: clientToSave["Registered Address"],
    kyc_status: clientToSave.kyc_status,
    risk_level: clientToSave.riskLevel,
    entity_type: clientToSave.entity_type,
    created_at: clientToSave.created_at,
    created_by: clientToSave.created_by,
    last_screened_at: clientToSave.lastScreenedAt,
    matches: clientToSave.matches || []
  };

  const { error } = await supabaseClient.from('clients').upsert([dbClient]);
  if (error) throw error;
};

