                                <p className="text-sm font-black text-emerald-950 truncate uppercase">{person.name}</p>
                                <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest truncate">{person.qid_passport} • {person.nationality}</p>
                             </div>
                          </div>
                       ))}
                    </div>
                  ) : (
                    <div className="bg-white p-12 rounded-[2rem] border-2 border-dashed border-gray-100 text-center">
                       <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest">No verified personnel records on file</p>
                    </div>
                  )}
               </div>
            </div>

            {/* Dossier Footer Actions */}
            <div className="p-8 sm:p-10 bg-white border-t border-gray-100 flex flex-col sm:flex-row justify-between items-center gap-6 shrink-0">
               <div className="flex items-center gap-3">
                  <ShieldCheck size={24} className="text-emerald-600"/>
                  <div>
                     <p className="text-[10px] font-black text-emerald-900 uppercase">Registry Authenticity</p>
                     <p className="text-[9px] font-bold text-gray-400 uppercase">Verified Compliance Engine v3.3.3</p>
                  </div>
               </div>
               <div className="flex gap-4 w-full sm:w-auto">
                  <button 
                    onClick={() => setSelectedClient(null)}
                    className="flex-1 sm:flex-none px-10 py-4 bg-gray-50 text-gray-400 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-gray-100 transition-all"
                  >
                    Dismiss Dossier
                  </button>
                  <button className="flex-1 sm:flex-none px-10 py-4 bg-emerald-800 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:bg-emerald-900 transition-all flex items-center justify-center gap-2">
                    <FileSignature size={18}/> Authorize Update
                  </button>
               </div>
            </div>
          </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-xl z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-[2rem] sm:rounded-[3rem] w-full max-w-7xl h-[92vh] sm:h-auto max-h-[95vh] overflow-hidden flex flex-col shadow-2xl animate-in slide-in-from-bottom-4 duration-300">
            <div className="bg-emerald-900 p-6 sm:p-8 text-white flex justify-between items-center shrink-0">
              <div className="flex flex-col xs:flex-row xs:items-center gap-4">
                 <h3 className="text-xl sm:text-2xl font-black tracking-tight uppercase">Identity Provisioning</h3>
                 <div className="flex bg-white/10 p-1 rounded-xl sm:rounded-2xl border border-white/20 w-fit">
                    <button type="button" onClick={() => setEntityType(EntityType.CORPORATE)} className={`px-4 sm:px-6 py-1.5 rounded-lg sm:rounded-xl text-[10px] font-black transition-all uppercase ${entityType === EntityType.CORPORATE ? 'bg-white text-emerald-900' : 'text-white'}`}>Corp</button>
                    <button type="button" onClick={() => setEntityType(EntityType.INDIVIDUAL)} className={`px-4 sm:px-6 py-1.5 rounded-lg sm:rounded-xl text-[10px] font-black transition-all uppercase ${entityType === EntityType.INDIVIDUAL ? 'bg-white text-emerald-900' : 'text-white'}`}>Indiv</button>
                 </div>
              </div>
              <button type="button" onClick={() => setIsModalOpen(false)} className="bg-white/10 p-2.5 rounded-full hover:bg-white/20"><X size={20}/></button>
            </div>
            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 sm:p-10 space-y-8 sm:space-y-10 custom-scrollbar bg-gray-50/30">
              <FormSection title="Registry Identification" icon={<Landmark size={18}/>}>
                <div className="sm:col-span-2"><InputField label="Entity Legal Name" value={formData["Client Name"]} onChange={(v:any)=>setFormData({...formData, "Client Name": v})} required /></div>
                <InputField label="File Reference" value={formData["No"]} onChange={(v:any)=>setFormData({...formData, "No": v})} required />
                <InputField label="QFC No" value={formData["QFC No"]} onChange={(v:any)=>setFormData({...formData, "QFC No": v})} />
                <InputField label="Jurisdiction" value={formData["Company Nationality"]} onChange={(v:any)=>setFormData({...formData, "Company Nationality": v})} required />
                <InputField label="Legal Form" value={formData["Legal Structure"]} onChange={(v:any)=>setFormData({...formData, "Legal Structure": v})} />
              </FormSection>
              <div className="flex flex-col xs:flex-row justify-end gap-3 pb-8 sticky bottom-0 bg-white/90 backdrop-blur-md pt-5 border-t border-gray-100 z-10">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-8 py-4 font-black text-[10px] uppercase tracking-widest text-gray-400 hover:text-gray-600 order-2 xs:order-1">Cancel</button>
                <button type="submit" disabled={isSubmitting} className="w-full xs:w-auto bg-emerald-800 text-white px-10 py-4 rounded-xl sm:rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-emerald-900 flex justify-center items-center gap-2 order-1 xs:order-2 disabled:opacity-50">{isSubmitting ? <Loader2 size={20} className="animate-spin" /> : <CheckCircle2 size={20}/>} {isSubmitting ? 'Committing & Screening...' : 'Commit Entity'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClientManager;

import React, { useState } from 'react';
import { Client, RiskLevel, PersonRecord, KYCStatus, EntityType, UserRole, ScreeningProgress, MatchResult } from '../types';
import { 
  Plus, Trash2, Eye, RefreshCw, X, CheckCircle2, Landmark, Users, 
  UserPlus, FileText, Shield, Calendar, Loader2, ScanSearch, 
  AlertTriangle, Activity, Database, CheckCircle,
  ChevronsLeft, ChevronLeft, ChevronRight, ChevronsRight, ShieldAlert,
  Info, MapPin, Phone, Mail, Globe, Briefcase, FileSignature, UserCheck,
  History, Fingerprint, ShieldCheck
} from 'lucide-react';

const CLIENTS_PER_PAGE = 15;

interface FormSectionProps {
  title: string;
  icon: React.ReactNode;
  children?: React.ReactNode;
  fullWidth?: boolean;
}

const FormSection: React.FC<FormSectionProps> = ({ title, icon, children, fullWidth = false }) => (
  <div className="bg-white p-5 sm:p-8 rounded-2xl sm:rounded-[2rem] border border-gray-100 shadow-sm space-y-6">
    <div className="flex items-center gap-4 text-emerald-800 font-black border-b border-gray-50 pb-4">
      <div className="bg-emerald-50 p-2.5 rounded-xl">{icon}</div>
      <span className="text-[10px] uppercase tracking-[0.2em]">{title}</span>
    </div>
    <div className={fullWidth ? "w-full" : "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-5 sm:gap-6"}>{children}</div>
  </div>
);

const InputField = ({ label, value, onChange, type = "text", placeholder = "", required = false }: any) => (
  <div className="space-y-1.5 sm:space-y-2">
    <div className="flex justify-between">
        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block ml-1">{label}</label>
        {required && <span className="text-[9px] text-amber-600 font-black uppercase">Required</span>}
    </div>
    <input 
      type={type} 
      placeholder={placeholder}
      className="w-full bg-gray-50 border-2 border-transparent rounded-xl sm:rounded-2xl p-3 sm:p-4 text-sm font-bold text-emerald-950 focus:border-emerald-800 focus:bg-white outline-none transition-all" 
      value={value} 
      onChange={e => onChange(e.target.value)} 
      required={required} 
    />
  </div>
);

const DetailRow = ({ label, value, icon }: { label: string, value: string | React.ReactNode, icon: React.ReactNode }) => (
  <div className="flex items-start gap-4 p-4 bg-gray-50/50 rounded-2xl border border-transparent hover:border-gray-100 transition-all">
    <div className="p-2.5 bg-white rounded-xl shadow-sm text-emerald-800">{icon}</div>
    <div className="min-w-0 flex-1">
      <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-0.5">{label}</p>
      <div className="text-sm font-bold text-emerald-950 truncate">{value || <span className="text-gray-300 italic">Not Disclosed</span>}</div>
    </div>
  </div>
);

interface ClientManagerProps {
  clients: Client[];
  totalCount: number;
  currentPage: number;
  onPageChange: (page: number) => void;
  isRefreshing: boolean;
  onAddClient: (client: Client) => Promise<void>;
  onDeleteClient: (id: string) => void;
  onUpdateClient?: (client: Client) => void;
  onRefresh: () => void;
  onReScreen?: () => void;
  screeningProgress?: ScreeningProgress;
  currentUserRole: UserRole;
  currentUserId: string;
}

const ClientManager: React.FC<ClientManagerProps> = ({ 
  clients, 
  totalCount,
  currentPage,
  onPageChange,
  isRefreshing,
  onAddClient, 
  onDeleteClient, 
  onRefresh, 
  onReScreen,
  screeningProgress,
  currentUserRole, 
  currentUserId 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [entityType, setEntityType] = useState<EntityType>(EntityType.CORPORATE);

  const totalPages = Math.ceil(totalCount / CLIENTS_PER_PAGE);

  const initialForm: any = {
    "No": "", "Status": "Pending", "QFC No": "", "Legal Structure": "", "Company Nationality": "",
    "Client Name": "", "Services Provided": [], "Engagement Year": new Date().getFullYear().toString(), 
    "Engagement Date": "", "Onboarding Date": new Date().toISOString().split('T')[0], 
    "Date of QFC Incorporation or Registration": "", "CR Expired date": "",
    "Entity Card No": "", "Entity Card Expiry": "", "License": "", "License Expiry": "",
    "Nature of Business": "", "Registered Address": "", "Telephone Number": "", "E Mail": "",
    "Website": "", "Directors Names": [], "Significant Shareholders": [], "UBO Details": [],
    "Authorized Signatory": [], "Secretary": "", "Senior Executive Function": "",
    "Approved Auditor": "", "Company Type": "", "kyc_status": KYCStatus.DRAFT, "entity_type": EntityType.CORPORATE
  };

  const [formData, setFormData] = useState(initialForm);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      const newClient: Client = { 
        ...formData, 
        id: `RPME-${Math.random().toString(36).substr(2, 6).toUpperCase()}`, 
        created_at: new Date().toISOString(), 
        created_by: currentUserId, 
        riskLevel: RiskLevel.NONE, 
        entity_type: entityType 
      };
      await onAddClient(newClient);
      setFormData(initialForm);
      setIsModalOpen(false);
    } catch (err: any) { alert("Provisioning Failed: " + err.message); } finally { setIsSubmitting(false); }
  };

  return (
    <div className="space-y-6 sm:space-y-8 relative">

      {/* SCREENING PROGRESS INDICATOR */}
      {screeningProgress && screeningProgress.status !== 'Not Started' && (
        <div className="bg-emerald-950 p-6 sm:p-8 rounded-[2rem] text-white shadow-2xl animate-in slide-in-from-top-4 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-5">
             <Activity size={100} />
          </div>
          <div className="flex flex-col sm:flex-row justify-between items-center gap-6 relative z-10">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-white/10 rounded-2xl animate-pulse">
                {screeningProgress.status === 'Completed' ? <CheckCircle className="text-emerald-400" size={24}/> : <ScanSearch className="text-amber-400" size={24}/>}
              </div>
              <div>
                <h4 className="text-lg font-black uppercase tracking-tight">
                  {screeningProgress.status === 'Completed' ? 'Batch Authoritative Screening Finalized' : 'Global Screening In Progress'}
                </h4>
                <p className="text-[10px] text-white/50 font-black uppercase tracking-widest mt-1">
                   Authority: Sanctions Master Table (Auth-Consensus)
                </p>
              </div>
            </div>
            <div className="flex items-center gap-4 w-full sm:w-auto">
               <div className="flex flex-col items-end">
                  <p className="text-[9px] font-black text-white/30 uppercase">Screened / Total</p>
                  <p className="text-sm font-black text-emerald-400">{screeningProgress.screenedRecords.toLocaleString()} / {screeningProgress.totalRecords.toLocaleString()}</p>
               </div>
               <div className="flex-1 sm:w-48 h-2 bg-white/10 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-emerald-400 transition-all duration-500" 
                    style={{ width: `${(screeningProgress.screenedRecords / screeningProgress.totalRecords) * 100}%` }}
                  />
               </div>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white p-6 sm:p-8 rounded-2xl sm:rounded-[2.5rem] border border-gray-100 shadow-sm relative z-10 gap-4">
        <div>
          <h2 className="text-2xl sm:text-3xl font-black text-emerald-950 tracking-tighter uppercase">Entity Registry</h2>
          <p className="text-[10px] text-emerald-700 mt-1 uppercase tracking-[0.4em] font-black">Database-Authoritative Hub</p>
        </div>
        <div className="flex w-full sm:w-auto gap-3">
          <button 
            onClick={onReScreen} 
            disabled={isRefreshing || (screeningProgress?.status === 'In Progress')} 
            className="flex items-center gap-2 px-6 py-4 bg-amber-50 text-amber-700 border border-amber-100 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-amber-100 transition-all disabled:opacity-50"
          >
             <Database size={18} /> Global DB Screen
          </button>
          <button onClick={onRefresh} disabled={isRefreshing} className="p-4 text-gray-400 hover:text-emerald-800 bg-gray-50 rounded-xl transition-all shrink-0">
            <RefreshCw size={24} className={isRefreshing ? 'animate-spin' : ''}/>
          </button>
          {(currentUserRole === UserRole.DATA_ENTRY || currentUserRole === UserRole.ADMIN) && (
            <button 
              type="button" 
              onClick={(e) => { e.stopPropagation(); setIsModalOpen(true); }} 
              className="flex-1 sm:flex-none bg-emerald-800 text-white px-6 sm:px-8 py-4 rounded-xl sm:rounded-2xl font-black text-[10px] uppercase tracking-widest flex justify-center items-center gap-2 shadow-xl hover:bg-emerald-900 transition-all"
            >
              <Plus size={18} /> Provision Entity
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-2xl sm:rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden relative z-0 flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left min-w-[900px]">
            <thead>
              <tr className="bg-gray-50/50">
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Classification</th>
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Entity Name</th>
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Screening Status</th>
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Risk Index</th>
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-right">Audit</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {clients.map(client => (
                <tr key={client.id} className="hover:bg-emerald-50/20 cursor-pointer transition-colors group" onClick={() => setSelectedClient(client)}>
                  <td className="px-6 sm:px-10 py-5 sm:py-6">
                    <span className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border ${client.entity_type === EntityType.INDIVIDUAL ? 'bg-amber-50 text-amber-800 border-amber-100' : 'bg-emerald-50 text-emerald-800 border-emerald-100'}`}>
                      {client.entity_type === EntityType.INDIVIDUAL ? <Users size={12}/> : <Landmark size={12}/>}
                      {client.entity_type}
                    </span>
                  </td>
                  <td className="px-6 sm:px-10 py-5 sm:py-6">
                    <div className="font-black text-emerald-950 text-sm tracking-tight">{client["Client Name"]}</div>
                    <div className="text-[8px] text-gray-400 font-bold uppercase mt-1">Ref: {client["No"]}</div>
                  </td>
                  <td className="px-6 sm:px-10 py-5 sm:py-6">
                    <div className="flex flex-col gap-1">
                       <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-[8px] font-black uppercase border ${client.lastScreenedAt ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                          {client.lastScreenedAt ? <CheckCircle2 size={10}/> : <Activity size={10}/>}
                          {client.lastScreenedAt ? 'DB Authoritative' : 'Screening Required'}
                       </span>
                       {client.lastScreenedAt && (
                         <span className="text-[7px] text-gray-400 font-bold uppercase ml-1">
                           {new Date(client.lastScreenedAt).toLocaleString()}
                         </span>
                       )}
                    </div>
                  </td>
                  <td className="px-6 sm:px-10 py-5 sm:py-6">
                    <div className="flex items-center gap-2">
                       <span className={`px-2.5 py-1 rounded-md text-[9px] font-black uppercase border-2 flex items-center gap-1.5 ${
                         client.riskLevel === RiskLevel.HIGH ? 'bg-red-500 text-white border-red-600' :
                         'bg-gray-100 text-gray-400 border-gray-200'
                       }`}>
                         {client.riskLevel === RiskLevel.HIGH ? <ShieldAlert size={10} /> : <CheckCircle size={10} />}
                         {client.riskLevel === RiskLevel.HIGH ? 'HIGH RISK' : 'CLEAR'}
                       </span>
                    </div>
                  </td>
                  <td className="px-6 sm:px-10 py-5 sm:py-6 text-right">
                    <button 
                      onClick={(e) => { e.stopPropagation(); setSelectedClient(client); }}
                      className="p-3 text-emerald-800 bg-gray-50 rounded-xl sm:opacity-0 group-hover:opacity-100 transition-all hover:bg-emerald-100"
                    >
                      <Eye size={20}/>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {totalCount > 0 && (
          <div className="px-6 sm:px-10 py-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-gray-50/30">
            <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">
              Tier <span className="text-emerald-950">{currentPage}</span> of {totalPages} <span className="mx-2 hidden sm:inline">•</span> <span className="block sm:inline mt-1 sm:mt-0">{totalCount.toLocaleString()} Entities Profiled</span>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => onPageChange(1)} disabled={currentPage === 1 || isRefreshing} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"><ChevronsLeft size={18} /></button>
              <button onClick={() => onPageChange(currentPage - 1)} disabled={currentPage === 1 || isRefreshing} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"><ChevronLeft size={18} /></button>
              <div className="px-6 py-3 text-[10px] font-black text-emerald-950 bg-white rounded-xl border border-gray-200 shadow-sm min-w-[100px] text-center uppercase tracking-widest">{currentPage}</div>
              <button onClick={() => onPageChange(currentPage + 1)} disabled={currentPage === totalPages || isRefreshing} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"><ChevronRight size={18} /></button>
              <button onClick={() => onPageChange(totalPages)} disabled={currentPage === totalPages || isRefreshing} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"><ChevronsRight size={18} /></button>
            </div>
          </div>
        )}
      </div>

      {/* CLIENT DOSSIER MODAL (EYE ICON RESPONSE) */}
      {selectedClient && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-xl z-[100] flex items-center justify-center p-4 sm:p-6">
          <div className="bg-white rounded-[2.5rem] sm:rounded-[3.5rem] w-full max-w-5xl h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in-95 duration-300">
            {/* Dossier Header */}
            <div className={`p-8 sm:p-12 text-white relative overflow-hidden shrink-0 ${selectedClient.riskLevel === RiskLevel.HIGH ? 'bg-red-900' : 'bg-emerald-900'}`}>
               <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
                  <Fingerprint size={160} />
               </div>

               <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 relative z-10">
                  <div className="space-y-4">
                     <div className="flex items-center gap-3">
                        <span className="px-3 py-1 bg-white/10 rounded-lg text-[10px] font-black uppercase tracking-[0.2em] border border-white/20">
                           {selectedClient.id}
                        </span>
                        {selectedClient.riskLevel === RiskLevel.HIGH && (
                           <span className="px-3 py-1 bg-white text-red-900 rounded-lg text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-2">
                              <ShieldAlert size={12} /> Mandatory High Risk
                           </span>
                        )}
                     </div>
                     <h2 className="text-3xl sm:text-4xl font-black tracking-tight uppercase leading-none">
                        {selectedClient["Client Name"]}
                     </h2>
