/**
 * Upsert sanctions batch to cloud
 */
export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void) => {
  if (!supabaseClient) return;
  const batchSize = 100;
  for (let i = 0; i < sanctions.length; i += batchSize) {
    const batch = sanctions.slice(i, i + batchSize).map(s => ({
      data_id: s.dataId,
      first_name: s.firstName,
      last_name: s.lastName,
      source: s.source,
      reference_number: s.referenceNumber,
      listed_on: s.listedOn,
      nationality: s.nationality,
      date_of_birth: s.dateOfBirth,
      un_list_type: s.unListType,
      aliases: s.aliases || [],
      fetch_date: s.fetchDate || new Date().toISOString()
    }));
    const { error } = await supabaseClient.from('sanctions').upsert(batch);
    if (error) throw error;
    if (onProgress) onProgress(Math.min(100, Math.round(((i + batch.length) / sanctions.length) * 100)));
  }
};

