 * Mandatory for tracing sanctions match events.
 */
export const logScreeningAudit = async (clientId: string, clientName: string, sanctionId: string, matchType: string, result: RiskLevel, userId: string) => {
  if (!supabaseClient) return;
  try {
    await supabaseClient.from('ingestion_logs').insert([{
      source: 'Compliance Rules Engine',
      method: 'Screening',
      status: 'Success',
      records_processed: 1,
      records_accepted: 1,
      records_rejected: 0,
      details: `AUDIT [${new Date().toISOString()}]: Entity [${clientId}] "${clientName}" screened. Result: ${result}. Authority Ref: ${sanctionId}. Match Context: ${matchType}`,
      triggered_by: userId || 'System-Enforced'
    }]);
  } catch (e) {}
};

/**
 * AUTHORITATIVE SCREENING: Performs real-time fuzzy matching against DB results.
 */
export const screenEntityAgainstDb = async (client: Client, userId: string = 'System'): Promise<Client> => {
  const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
  const match = screenClient(client, candidates);

  const riskLevel = match ? match.riskLevel : RiskLevel.NONE;

  // COMPLIANCE AUDIT LOGGING
  await logScreeningAudit(
    client.id, 
    client["Client Name"], 
    match?.sanctionId || 'N/A', 
    match?.matchedFields?.[0] || 'Clear', 
    riskLevel, 
    userId
  );

  return {
    ...client,
    riskLevel: riskLevel, // Mandatory High Risk if match exists (enforced by screeningEngine)
    matches: match ? [match.sanctionId] : [],
    lastScreenedAt: new Date().toISOString()
  };
};

