import { Client, SanctionEntry, MatchResult, RiskLevel } from '../types';

/**
 * CORPORATE NOISE: Common terms that dilute similarity scores for large entities.
 * We ignore these when calculating token-based match percentages.
 */
const CORPORATE_NOISE = ['CO', 'LTD', 'CORP', 'INC', 'INTERNATIONAL', 'SHIPPING', 'AGENCY', 'UNITED', 'AND', 'FOR', 'THE', 'LIMITED', 'GROUP', 'COMPANY', 'LLC', 'PVT', 'FZE', 'PLC'];

/**
 * Iterative Levenshtein distance for fuzzy string comparison.
 */
const levenshtein = (a: string, b: string): number => {
  const matrix = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
  for (let i = 0; i <= a.length; i++) matrix[i][0] = i;
  for (let j = 0; j <= b.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1].toLowerCase() === b[j - 1].toLowerCase() ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }
  return matrix[a.length][b.length];
};

/**
 * Calculates similarity between two strings.
 * Returns a score between 0 and 1.
 */
const calculateSimilarity = (s1: string, s2: string): number => {
  if (!s1 || !s2) return 0;
  const str1 = s1.trim().toLowerCase();
  const str2 = s2.trim().toLowerCase();

  if (str1 === str2) return 1.0;

  // Containment check for cases like "12559 DURANSOY" vs "DURANSOY"
  if (str1.includes(str2) || str2.includes(str1)) return 0.95;

  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  return (longer.length - levenshtein(longer, shorter)) / longer.length;
};

/**
 * MANDATORY COMPLIANCE EVALUATOR:
 * Returns whether a match is detected and the corresponding type.
 */
const isMandatoryHighRiskMatch = (clientName: string, sanctionedName: string): { isMatch: boolean; type: string } => {
  const cNorm = clientName.toLowerCase();
  const sNorm = sanctionedName.toLowerCase();

  // 1. Direct containment or exact match
  if (cNorm === sNorm) return { isMatch: true, type: 'Exact Identity Match' };
  if (cNorm.includes(sNorm) || sNorm.includes(cNorm)) return { isMatch: true, type: 'Identity Containment' };

  // 2. Numeric Cross-Reference Logic (e.g. "38160" matches "UN-38160")
  const numericFragments = cNorm.match(/\d{4,}/g) || [];
  for (const num of numericFragments) {
    if (sNorm.includes(num)) return { isMatch: true, type: 'Numeric ID Match' };
  }

  // 3. Token-based matching with Salience Weighting
  const cTokensRaw = cNorm.split(/[\s,.-]+/).filter(t => t.length > 1);
  const sTokensRaw = sNorm.split(/[\s,.-]+/).filter(t => t.length > 1);

  // Salience filter: Remove noise tokens for denominator calculation
  const cSalient = cTokensRaw.filter(t => !CORPORATE_NOISE.includes(t.toUpperCase()));
  const sSalient = sTokensRaw.filter(t => !CORPORATE_NOISE.includes(t.toUpperCase()));

  if (sTokensRaw.length === 0) return { isMatch: false, type: 'No Match' };

  let salientMatches = 0;
  let genericMatches = 0;

  for (const st of sTokensRaw) {
    const isNoise = CORPORATE_NOISE.includes(st.toUpperCase());
    if (cTokensRaw.some(ct => ct === st || calculateSimilarity(ct, st) > 0.9)) {
      if (isNoise) genericMatches++;
      else salientMatches++;
    }
  }

  // MANDATORY CORPORATE RULE:
  // If 2+ unique salient (non-noise) tokens match, it's a High Risk hit regardless of name length.
  if (salientMatches >= 2) {
    return { isMatch: true, type: 'High Salience Entity Match' };
  }

  // Fallback to percentage based on salient tokens
  const denominator = sSalient.length > 0 ? sSalient.length : sTokensRaw.length;
  if (salientMatches > 0 && (salientMatches / denominator) >= 0.4) {
    return { isMatch: true, type: 'Salient Partial Match' };
  }

  // 4. Aggressive fuzzy similarity floor (0.25)
  const fuzzy = calculateSimilarity(cNorm, sNorm);
  if (fuzzy > 0.35) { // Slightly increased floor to prevent noise false positives
    return { isMatch: true, type: 'Fuzzy Similarity Match' };
  }

  return { isMatch: false, type: 'No Match' };
};

export const screenClient = (client: Client, sanctions: SanctionEntry[]): MatchResult | null => {
  let bestMatch: MatchResult | null = null;
  let highestScore = 0;

  const clientName = (client["Client Name"] || "").trim().toUpperCase();
  if (!clientName) return null;

  for (const sanction of sanctions) {
    const sFullName = [sanction.firstName, sanction.lastName]
      .filter(Boolean).join(' ').trim().toUpperCase();

    const aliases = Array.isArray(sanction.aliases) ? sanction.aliases : [];

    const checkNames = [
      (sanction.referenceNumber || '').toUpperCase(),
      (sanction.dataId || '').toUpperCase(),
      sFullName, 
      ...aliases.map(a => a.toUpperCase())
    ].filter(Boolean);

    let currentEntryBestType = '';
    let currentEntryMaxScore = 0;

    for (const sName of checkNames) {
      const { isMatch, type } = isMandatoryHighRiskMatch(clientName, sName);

      if (isMatch) {
        // Boost score for salience-based matches
        const weight = (type === 'High Salience Entity Match') ? 1.0 : calculateSimilarity(clientName, sName);
        const score = (type === 'Exact Identity Match' || type === 'Numeric ID Match' || type === 'High Salience Entity Match') ? 1.0 : weight;

        if (score > currentEntryMaxScore) {
          currentEntryMaxScore = score;
          currentEntryBestType = type;
        }
      }
    }

    if (currentEntryBestType) {
      const finalScore = Math.round(Math.max(0.1, currentEntryMaxScore) * 100);

      if (finalScore > highestScore) {
        highestScore = finalScore;

        bestMatch = {
          clientId: client.id,
          sanctionId: sanction.dataId,
          score: finalScore,
          riskLevel: RiskLevel.HIGH,
          matchedFields: [currentEntryBestType],
          timestamp: new Date().toISOString()
        };
      }
    }
  }

  return bestMatch;
};

