/**
 * CORPORATE NOISE: Words that should not be used as primary search fragments
 */
const SEARCH_NOISE_WORDS = ['CO', 'LTD', 'CORP', 'INC', 'INTERNATIONAL', 'SHIPPING', 'AGENCY', 'UNITED', 'AND', 'FOR', 'THE', 'LIMITED', 'GROUP', 'COMPANY', 'LLC', 'SERVICES', 'TRADING'];

/**
 * AUTHORITATIVE SEARCH: Queries the sanctions table for candidates.
 * Updated v1.8.9: Implemented Salience-First fragmenting to handle long corporate names.
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];

  const normalized = name.trim().toUpperCase();
  const allFragments = normalized.split(/[\s,.-]+/).filter(f => f.length >= 2);

  // Identify salient fragments (not noise)
  const salientFragments = allFragments.filter(f => !SEARCH_NOISE_WORDS.includes(f));

  // We use salient fragments if available, otherwise fallback to all fragments
  const searchFragments = salientFragments.length > 0 ? salientFragments : allFragments;

  try {
    let query = supabaseClient.from('sanctions').select('*');

    if (searchFragments.length > 0) {
      // Construction of broad OR condition across all identity columns
      const orConditions = searchFragments.flatMap(f => [
        `first_name.ilike.%${f}%`,
        `last_name.ilike.%${f}%`,
        `reference_number.ilike.%${f}%`,
        `data_id.ilike.%${f}%`
      ]).join(',');

      query = query.or(orConditions);
    } else {
      // Fallback for very short or non-standard names
      query = query.or(`first_name.ilike.%${normalized}%,last_name.ilike.%${normalized}%`);
    }

    const { data, error } = await query.limit(1000);
    if (error || !data) return [];

    return data.map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: String(row.first_name ?? ''), 
      lastName: String(row.last_name ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? ''),
      listedOn: String(row.listed_on ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? ''),
      unListType: String(row.un_list_type ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e) {
    return [];
  }
};

