/**
 * Upsert sanctions in bulk with progress tracking
 */
export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (progress: number) => void) => {
  if (!supabaseClient) return;
  const BATCH_SIZE = 50;
  const total = sanctions.length;

  for (let i = 0; i < total; i += BATCH_SIZE) {
    const batch = sanctions.slice(i, i + BATCH_SIZE).map(s => ({
      data_id: s.dataId,
      first_name: s.firstName,
      last_name: s.lastName,
      source: s.source,
      reference_number: s.referenceNumber,
      listed_on: s.listedOn,
      nationality: s.nationality,
      date_of_birth: s.dateOfBirth,
      un_list_type: s.unListType,
      aliases: s.aliases,
      fetch_date: s.fetchDate || new Date().toISOString()
    }));

    const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
    if (error) throw error;

    if (onProgress) {
      onProgress(Math.round(((i + batch.length) / total) * 100));
    }
  }
};

