import { Client, SanctionEntry, MatchResult, RiskLevel } from '../types';

/**
 * CORPORATE NOISE: Words that dilute name uniqueness.
 * Expanded to ensure common UN and OFAC entity suffixes are ignored.
 */
const CORPORATE_NOISE = [
  'CO', 'LTD', 'CORP', 'INC', 'INTERNATIONAL', 'SHIPPING', 'AGENCY', 'UNITED', 
  'AND', 'FOR', 'THE', 'LIMITED', 'GROUP', 'COMPANY', 'LLC', 'PVT', 'FZE', 
  'PLC', 'SERVICES', 'TRADING', 'MARITIME', 'MANAGEMENT', 'INVESTMENT', 
  'HOLDINGS', 'TRUST', 'PARTNERS', 'L.L.C', 'L.T.D', 'CO.', 'CO.,'
];

/**
 * Iterative Levenshtein distance for fuzzy string comparison.
 */
const levenshtein = (a: string, b: string): number => {
  const matrix = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
  for (let i = 0; i <= a.length; i++) matrix[i][0] = i;
  for (let j = 0; j <= b.length; j++) matrix[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1].toLowerCase() === b[j - 1].toLowerCase() ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }
  return matrix[a.length][b.length];
};

/**
 * Calculates similarity between two strings.
 * Returns a score between 0 and 1.
 */
const calculateSimilarity = (s1: string, s2: string): number => {
  if (!s1 || !s2) return 0;
  const str1 = s1.trim().toLowerCase();
  const str2 = s2.trim().toLowerCase();

  if (str1 === str2) return 1.0;

  // Containment check for direct substrings
  if (str1.includes(str2) || str2.includes(str1)) return 0.95;

  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  return (longer.length - levenshtein(longer, shorter)) / longer.length;
};

/**
 * MANDATORY COMPLIANCE EVALUATOR:
 * Returns whether a match is detected and the corresponding type.
 * Updated v3.0.0: Strict Hyper-Aggressive Salience Intersection.
 */
const isMandatoryHighRiskMatch = (clientName: string, sanctionedName: string): { isMatch: boolean; type: string } => {
  const cNorm = clientName.toUpperCase().replace(/[.,/#!$%^&*;:{}=\-_`~()]/g, " ");
  const sNorm = sanctionedName.toUpperCase().replace(/[.,/#!$%^&*;:{}=\-_`~()]/g, " ");

  // 1. Direct Identity Match
  if (cNorm.trim() === sNorm.trim()) return { isMatch: true, type: 'Exact Identity Match' };

  // 2. Numeric Cross-Reference (ID Catching)
  const numericFragments = cNorm.match(/\d{4,}/g) || [];
  for (const num of numericFragments) {
    if (sNorm.includes(num)) return { isMatch: true, type: 'Numeric ID Match' };
  }

  // 3. HYPER-AGGRESSIVE SALIENCE INTERSECTION
  // Tokens are split and filtered for common corporate noise.
  const cTokens = cNorm.split(/\s+/).filter(t => t.length > 1);
  const sTokens = sNorm.split(/\s+/).filter(t => t.length > 1);

  const cSalient = cTokens.filter(t => !CORPORATE_NOISE.includes(t));
  const sSalient = sTokens.filter(t => !CORPORATE_NOISE.includes(t));

  if (sSalient.length === 0) return { isMatch: false, type: 'No Match' };

  // Calculate salient word overlap
  let salientMatches = 0;
  const matchedTokens: string[] = [];

  for (const st of sSalient) {
    if (cSalient.some(ct => ct === st || calculateSimilarity(ct, st) > 0.9)) {
      salientMatches++;
      matchedTokens.push(st);
    }
  }

  // RULE A: Complete Salience Intersection (e.g., "QINGDAO" and "HEXIN" both match)
  // If ALL salient parts of the sanctioned entry are found in the client entry, it's a forced match.
  if (salientMatches === sSalient.length && sSalient.length >= 2) {
    return { isMatch: true, type: 'Salient Set Consensus' };
  }

  // RULE B: Multi-Token Salience Coverage
  // If 2 or more core identifiers match exactly, it's a High Risk hit.
  if (salientMatches >= 2) {
    return { isMatch: true, type: 'Multi-Token Salience Match' };
  }

  // RULE C: Identity Containment (Ignoring Suffixes)
  // If the salient string of the sanction is contained within the salient string of the client
  const sSalientStr = sSalient.join(' ');
  const cSalientStr = cSalient.join(' ');
  if (sSalientStr.length > 5 && (cSalientStr.includes(sSalientStr) || sSalientStr.includes(cSalientStr))) {
    return { isMatch: true, type: 'Salience Containment' };
  }

  // 4. Salience Percentage Fallback (60%+ match of important words)
  if (sSalient.length > 0 && (salientMatches / sSalient.length) >= 0.6) {
    return { isMatch: true, type: 'Salience Intersection' };
  }

  // 5. Aggressive fuzzy similarity fallback
  const fuzzy = calculateSimilarity(cNorm, sNorm);
  if (fuzzy > 0.4) {
    return { isMatch: true, type: 'Fuzzy Similarity Match' };
  }

  return { isMatch: false, type: 'No Match' };
};

export const screenClient = (client: Client, sanctions: SanctionEntry[]): MatchResult | null => {
  let bestMatch: MatchResult | null = null;
  let highestScore = 0;

  const clientName = (client["Client Name"] || "").trim().toUpperCase();
  if (!clientName) return null;

  for (const sanction of sanctions) {
    const sFullName = [sanction.firstName, sanction.lastName]
      .filter(Boolean).join(' ').trim().toUpperCase();

    const aliases = Array.isArray(sanction.aliases) ? sanction.aliases : [];

    const checkNames = [
      (sanction.referenceNumber || '').toUpperCase(),
      (sanction.dataId || '').toUpperCase(),
      sFullName, 
      ...aliases.map(a => a.toUpperCase())
    ].filter(Boolean);

    let currentEntryBestType = '';
    let currentEntryMaxScore = 0;

    for (const sName of checkNames) {
      const { isMatch, type } = isMandatoryHighRiskMatch(clientName, sName);

      if (isMatch) {
        // Boost scores for salient types to ensure RiskLevel.HIGH
        let score = calculateSimilarity(clientName, sName);
        if (type === 'Exact Identity Match' || type === 'Salient Set Consensus' || type === 'Multi-Token Salience Match' || type === 'Salience Containment') {
          score = Math.max(score, 0.99); // Force High Risk
        }

        if (score > currentEntryMaxScore) {
          currentEntryMaxScore = score;
          currentEntryBestType = type;
        }
      }
    }

    if (currentEntryBestType) {
      const finalScore = Math.round(Math.max(0.1, currentEntryMaxScore) * 100);

      if (finalScore > highestScore) {
        highestScore = finalScore;

        bestMatch = {
          clientId: client.id,
          sanctionId: sanction.dataId,
          score: finalScore,
          riskLevel: RiskLevel.HIGH, // Explicitly force HIGH for any identified match
          matchedFields: [currentEntryBestType],
          timestamp: new Date().toISOString()
        };
      }
    }
  }

  return bestMatch;
};

