    must_change_password: user.must_change_password,
    password_expiry: user.password_expiry,
    password_hash_mock: user.password || user.password_hash_mock,
    created_at: user.created_at || new Date().toISOString()
  };
  const { error } = await supabaseClient.from('profiles').upsert([dbUser], { onConflict: 'email' });
  if (error) throw error;
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('profiles').delete().eq('email', email);
  if (error) throw error;
};

export const subscribeToClients = (callback: () => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('clients-all').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, callback).subscribe();
};

export const unsubscribeFromClients = (channel: any) => {
  if (channel) channel.unsubscribe();
};

export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return null;
  const { data, error } = await supabaseClient.from('system_metadata').select('*').eq('key', 'global_sync_status').single();
  return error ? null : data.value;
};

export const subscribeToGlobalSync = (callback: (meta: any) => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('sync-status').on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'system_metadata', filter: 'key=eq.global_sync_status' }, (p: any) => callback(p.new.value)).subscribe();
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync: string) => {
  if (!supabaseClient) return;
  const value = { is_syncing: isSyncing, last_sync: lastSync };
  await supabaseClient.from('system_metadata').upsert([{ key: 'global_sync_status', value }], { onConflict: 'key' });
};

export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
  return error ? 0 : count || 0;
};

export const fetchSanctionsBatch = async (from: number, to: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  const { data, error } = await supabaseClient.from('sanctions').select('*').range(from, to);
  if (error) throw error;
  return (data || []).map((row: any) => ({
    dataId: row.data_id,
    firstName: row.first_name,
    lastName: row.last_name,
    source: row.source,
    referenceNumber: row.reference_number,
    listedOn: row.listed_on,
    nationality: row.nationality,
    dateOfBirth: row.date_of_birth,
    unListType: row.un_list_type,
    aliases: row.aliases || [],
    fetchDate: row.fetch_date
  }));
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void) => {
  if (!supabaseClient) return;
  const total = sanctions.length;
  for (let i = 0; i < total; i += 50) {
    const batch = sanctions.slice(i, i + 50).map(s => ({
      data_id: s.dataId,
      first_name: s.firstName,
      last_name: s.lastName,
      source: s.source,
      reference_number: s.referenceNumber,
      listed_on: s.listedOn,
      nationality: s.nationality,
      date_of_birth: s.dateOfBirth,
      un_list_type: s.unListType,
      aliases: s.aliases,
      fetch_date: s.fetchDate || new Date().toISOString()
    }));
    await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
    if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
  }
};

export const logIngestionEvent = async (log: any) => {
  if (!supabaseClient) return;
  await supabaseClient.from('ingestion_logs').insert([{
    source: log.source,
    method: log.method,
    status: log.status,
    records_processed: log.recordsProcessed,
    records_accepted: log.recordsAccepted,
    records_rejected: log.recordsRejected,
    details: log.details,
    triggered_by: log.triggeredBy
  }]);
};

export const fetchIngestionLogs = async (): Promise<IngestionLog[]> => {
  if (!supabaseClient) return [];
  const { data, error } = await supabaseClient.from('ingestion_logs').select('*').order('timestamp', { ascending: false }).limit(50);
  if (error) return [];
  return (data || []).map((row: any) => ({
    id: row.id,
