/**
 * CORPORATE NOISE: Words that dilute name uniqueness.
 */
const CORPORATE_NOISE = [
  'CO', 'LTD', 'CORP', 'INC', 'INTERNATIONAL', 'SHIPPING', 'AGENCY', 'UNITED', 
  'AND', 'FOR', 'THE', 'LIMITED', 'GROUP', 'COMPANY', 'LLC', 'PVT', 'FZE', 
  'PLC', 'SERVICES', 'TRADING', 'MARITIME', 'MANAGEMENT', 'INVESTMENT', 
  'HOLDINGS', 'TRUST', 'PARTNERS', 'L.L.C', 'L.T.D', 'CO.', 'CO.,'
];

/**
 * AUTHORITATIVE SEARCH: Queries the sanctions table for candidates.
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];

  const normalized = name.trim().toUpperCase();
  const allFragments = normalized.split(/[\s,.-]+/).filter(f => f.length >= 2);
  const salientFragments = allFragments.filter(f => !CORPORATE_NOISE.includes(f));
  const searchFragments = salientFragments.length > 0 ? salientFragments : allFragments;

  try {
    let query = supabaseClient.from('sanctions').select('*');
    if (searchFragments.length > 0) {
      const conditions = searchFragments
        .filter(f => f.length >= 3)
        .flatMap(f => [
          `first_name.ilike.%${f}%`,
          `last_name.ilike.%${f}%`,
          `reference_number.ilike.%${f}%`,
          `data_id.ilike.%${f}%`
        ]);

      if (conditions.length > 0) {
        query = query.or(conditions.join(','));
      }
    }

    const { data, error } = await query.limit(1000);
    if (error) {
      console.error("Authoritative Search Query Error:", error.message);
      return [];
    }
    if (!data) return [];

    return data.map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: String(row.first_name ?? ''), 
      lastName: String(row.last_name ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? ''),
      listedOn: String(row.listed_on ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? ''),
      unListType: String(row.un_list_type ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e) {
    console.error("Sanctions Search Exception:", e);
    return [];
  }
};

/**
 * LOG SCREENING AUDIT
 */
export const logScreeningAudit = async (clientId: string, clientName: string, sanctionId: string, matchType: string, result: RiskLevel, userId: string) => {
  if (!supabaseClient) return;
  try {
    await supabaseClient.from('ingestion_logs').insert([{
      source: 'Compliance Rules Engine',
      method: 'Screening',
      status: 'Success',
      records_processed: 1,
      records_accepted: 1,
      records_rejected: 0,
      details: `AUDIT: Entity [${clientId}] "${clientName}" screened. Result: ${result}. Ref: ${sanctionId}. Match: ${matchType}`,
      triggered_by: userId || 'System'
    }]);
  } catch (e) {
    console.warn("Audit Logging Bypassed:", e);
  }
};

/**
 * AUTHORITATIVE SCREENING
 */
export const screenEntityAgainstDb = async (client: Client, userId: string = 'System'): Promise<Client> => {
  const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
  const match = screenClient(client, candidates);
  const riskLevel = match ? match.riskLevel : RiskLevel.NONE;

  // Asynchronous audit logging (doesn't block return)
  logScreeningAudit(client.id, client["Client Name"], match?.sanctionId || 'N/A', match?.matchedFields?.[0] || 'Clear', riskLevel, userId);

  return {
    ...client,
    riskLevel: riskLevel,
    matches: match ? [match.sanctionId] : [],
    lastScreenedAt: new Date().toISOString()
  };
};

