export const subscribeToGlobalSync = (callback: (meta: any) => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('sync-status').on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'system_metadata', filter: 'key=eq.global_sync_status' }, (p: any) => callback(p.new.value)).subscribe();
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync: string) => {
