export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void) => {
  if (!supabaseClient) return;
  const total = sanctions.length;
  for (let i = 0; i < total; i += 50) {
    const batch = sanctions.slice(i, i + 50).map(s => ({
      data_id: s.dataId,
      first_name: s.firstName,
      last_name: s.lastName,
      source: s.source,
      reference_number: s.referenceNumber,
      listed_on: s.listedOn,
      nationality: s.nationality,
      date_of_birth: s.dateOfBirth,
      un_list_type: s.unListType,
      aliases: s.aliases,
      // Fixed: Property 'fetch_date' does not exist on type 'SanctionEntry'. Correct property is 'fetchDate'.
      fetch_date: s.fetchDate || new Date().toISOString()
    }));
    await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
    if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
  }
};

