interface ClientManagerProps {
  clients: Client[];
  totalCount: number;
  currentPage: number;
  onPageChange: (page: number) => void;
  isRefreshing: boolean;
  onAddClient: (client: Client) => Promise<void>;
  onDeleteClient: (id: string) => Promise<void>;
  onUpdateClient?: (client: Client) => void;
  onRefresh: () => void;
  onReScreen?: () => void;
  screeningProgress?: ScreeningProgress;
  currentUserRole: UserRole;
  currentUserId: string;
}

const ClientManager: React.FC<ClientManagerProps> = ({ 
  clients, 
  totalCount,
  currentPage,
  onPageChange,
  isRefreshing,
  onAddClient, 
  onDeleteClient, 
  onRefresh, 
  onReScreen,
  screeningProgress,
  currentUserRole, 
  currentUserId 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const totalPages = Math.ceil(totalCount / CLIENTS_PER_PAGE);

  const [formData, setFormData] = useState({ ...INITIAL_FORM_STATE });

  // Sub-form state for personnel entry
  const [personForm, setPersonForm] = useState({ name: '', qid_passport: '', nationality: '', dob: '', type: 'Directors Names' });

  const addPerson = () => {
    if (!personForm.name) return;
    const typeKey = personForm.type as keyof typeof formData;
    const currentList = Array.isArray(formData[typeKey]) ? formData[typeKey] as any[] : [];
    setFormData({
      ...formData,
      [typeKey]: [...currentList, { 
        name: personForm.name, 
        qid_passport: personForm.qid_passport, 
        nationality: personForm.nationality,
        dob: personForm.dob || ""
      }]
    });
    setPersonForm({ ...personForm, name: '', qid_passport: '', nationality: '', dob: '' });
  };

  const removePerson = (type: string, index: number) => {
    const currentList = formData[type as keyof typeof formData] as any[];
    setFormData({
      ...formData,
      [type]: currentList.filter((_, i) => i !== index)
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    console.log("[Registry] Initiating entity provision:", formData["Client Name"]);

    if (isSubmitting) {
      console.warn("[Registry] Already committing. Blocking overlapping request.");
      return;
    }

    if (!formData["Client Name"]) {
      alert("Validation Error: Entity Legal Name is mandatory.");
      return;
    }

    setIsSubmitting(true);
    try {
      const newClient: Client = { 
        ...formData, 
        id: `RPME-${Math.random().toString(36).substr(2, 6).toUpperCase()}`, 
        created_at: new Date().toISOString(), 
        created_by: currentUserId, 
        riskLevel: RiskLevel.NONE, 
        entity_type: EntityType.CORPORATE 
      };

      console.log("[Registry] Dispatching authoritative screening & provision request...");
      await onAddClient(newClient);

      console.log("[Registry] Provisioning successful.");
      setFormData({ ...INITIAL_FORM_STATE });
      setIsModalOpen(false);
    } catch (err: any) { 
      console.error("[Registry] Submission Exception:", err);
      // Ensure the error is shown to the user clearly.
      alert(`Critical Provisioning Failure: ${err.message || "The node could not commit the entity to the registry."}`); 
    } finally { 
      setIsSubmitting(false); 
    }
  };

  const isPrivileged = currentUserRole === UserRole.ADMIN || currentUserRole === UserRole.DATA_ENTRY;

  const handleConfirmDelete = async () => {
    if (pendingDeleteId && !isDeleting) {
      setIsDeleting(true);
      try {
        await onDeleteClient(pendingDeleteId);
        if (selectedClient?.id === pendingDeleteId) {
          setSelectedClient(null);
        }
        setPendingDeleteId(null);
      } catch (err: any) {
        alert("Deletion Failed: " + (err.message || "Communication fault."));
      } finally {
        setIsDeleting(false);
      }
    }
  };

  return (
    <div className="space-y-6 sm:space-y-8 relative">

      {/* SCREENING PROGRESS INDICATOR */}
      {screeningProgress && screeningProgress.status !== 'Not Started' && (
        <div className="bg-emerald-950 p-6 sm:p-8 rounded-[2rem] text-white shadow-2xl animate-in slide-in-from-top-4 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-5">
             <Activity size={100} />
          </div>
          <div className="flex flex-col sm:flex-row justify-between items-center gap-6 relative z-10">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-white/10 rounded-2xl animate-pulse">
                {screeningProgress.status === 'Completed' ? <CheckCircle className="text-emerald-400" size={24}/> : <ScanSearch className="text-amber-400" size={24}/>}
              </div>
              <div>
                <h4 className="text-lg font-black uppercase tracking-tight">
                  {screeningProgress.status === 'Completed' ? 'Batch Authoritative Screening Finalized' : 'Global Screening In Progress'}
                </h4>
                <p className="text-[10px] text-white/50 font-black uppercase tracking-widest mt-1">
                   Authority: Sanctions Master Table (Auth-Consensus)
                </p>
              </div>
            </div>
            <div className="flex items-center gap-4 w-full sm:w-auto">
               <div className="flex flex-col items-end">
                  <p className="text-[9px] font-black text-white/30 uppercase">Screened / Total</p>
                  <p className="text-sm font-black text-emerald-400">{screeningProgress.screenedRecords.toLocaleString()} / {screeningProgress.totalRecords.toLocaleString()}</p>
               </div>
               <div className="flex-1 sm:w-48 h-2 bg-white/10 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-emerald-400 transition-all duration-500" 
                    style={{ width: `${(screeningProgress.screenedRecords / screeningProgress.totalRecords) * 100}%` }}
                  />
               </div>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white p-6 sm:p-8 rounded-2xl sm:rounded-[2.5rem] border border-gray-100 shadow-sm relative z-10 gap-4">
