                          <option value="Authorized Signatory">Signatory</option>
                       </select>
                    </div>
                    <div className="sm:col-span-1">
                       <InputField label="Legal Name" value={personForm.name} onChange={(v:any)=>setPersonForm({...personForm, name: v})} />
                    </div>
                    <div className="sm:col-span-1">
                       <InputField label="ID / Passport" value={personForm.qid_passport} onChange={(v:any)=>setPersonForm({...personForm, qid_passport: v})} />
                    </div>
                    <div className="flex gap-2">
                       <div className="flex-1">
                          <InputField label="Nationality" value={personForm.nationality} onChange={(v:any)=>setPersonForm({...personForm, nationality: v})} />
                       </div>
                       <button type="button" onClick={addPerson} className="bg-emerald-800 text-white p-4 rounded-2xl hover:bg-emerald-900 shadow-lg">
                          <Plus size={20}/>
                       </button>
                    </div>
                 </div>

                 {/* Personnel List Visualizer */}
                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                    {['Directors Names', 'Significant Shareholders', 'UBO Details', 'Authorized Signatory'].map((type) => (
                      <div key={type} className="space-y-3">
                         <h5 className="text-[8px] font-black text-gray-400 uppercase tracking-widest border-b border-gray-50 pb-2">{type.replace(' Names', '').replace(' Details', '')}</h5>
                         <div className="space-y-2">
                            {(formData[type as keyof typeof formData] as any[] || []).map((person, idx) => (
                               <div key={idx} className="bg-gray-50 p-3 rounded-xl border border-gray-100 flex justify-between items-center group">
                                  <div className="min-w-0">
                                     <p className="text-[10px] font-black text-emerald-950 truncate">{person.name}</p>
                                     <p className="text-[8px] font-bold text-gray-400">{person.nationality}</p>
                                  </div>
                                  <button type="button" onClick={() => removePerson(type, idx)} className="text-red-300 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all">
                                     <X size={14}/>
                                  </button>
                               </div>
                            ))}
                            {(formData[type as keyof typeof formData] as any[] || []).length === 0 && (
                               <p className="text-[8px] italic text-gray-300 py-2">No records added</p>
                            )}
                         </div>
                      </div>
                    ))}
                 </div>
              </div>

              <div className="flex flex-col xs:flex-row justify-end gap-3 pb-8 sticky bottom-0 bg-white/90 backdrop-blur-md pt-5 border-t border-gray-100 z-10 px-4">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-8 py-4 font-black text-[10px] uppercase tracking-widest text-gray-400 hover:text-gray-600 order-2 xs:order-1">Cancel</button>
                <button 
                  type="submit" 
                  disabled={isSubmitting} 
                  className="w-full xs:w-auto bg-emerald-800 text-white px-10 py-4 rounded-xl sm:rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-emerald-900 flex justify-center items-center gap-2 order-1 xs:order-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isSubmitting ? <Loader2 size={20} className="animate-spin" /> : <CheckCircle2 size={20}/>} 
                  {isSubmitting ? 'Committing...' : 'Commit Entity'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

