];

/**
 * AUTHORITATIVE SEARCH
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const normalized = name.trim().toUpperCase();
  const fragments = normalized.split(/[\s,.-]+/).filter(f => f.length >= 3 && !CORPORATE_NOISE.includes(f));

  try {
    let query = supabaseClient.from('sanctions').select('*');
    if (fragments.length > 0) {
      const conditions = fragments.flatMap(f => [
        `first_name.ilike.%${f}%`,
        `last_name.ilike.%${f}%`,
        `reference_number.ilike.%${f}%`,
        `data_id.ilike.%${f}%`
      ]);
      query = query.or(conditions.join(','));
    }

    const { data, error } = await query.limit(100);
    if (error) {
      console.warn("[Registry] Search Query Error:", extractError(error));
      return [];
    }
    return (data || []).map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: String(row.first_name ?? ''), 
      lastName: String(row.last_name ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? ''),
      listedOn: String(row.listed_on ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? ''),
      unListType: String(row.un_list_type ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e) { return []; }
};

/**
 * AUTHORITATIVE SCREENING
 */
export const screenEntityAgainstDb = async (client: Client, userId: string = 'System'): Promise<Client> => {
  const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
  const match = screenClient(client, candidates);
  const riskLevel = match ? match.riskLevel : RiskLevel.NONE;

  return {
    ...client,
    riskLevel: riskLevel,
    matches: match ? [match.sanctionId] : [],
    lastScreenedAt: new Date().toISOString()
  };
};

