  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formErrors, setFormErrors] = useState<string[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const totalPages = Math.ceil(totalCount / CLIENTS_PER_PAGE);

  const [formData, setFormData] = useState({ ...INITIAL_FORM_STATE });

  const [personForm, setPersonForm] = useState({ name: '', qid_passport: '', nationality: '', dob: '', type: 'Directors Names' });

  const addPerson = () => {
    if (!personForm.name) return;
    const typeKey = personForm.type as keyof typeof formData;
    const currentList = Array.isArray(formData[typeKey]) ? formData[typeKey] as any[] : [];
    setFormData({
      ...formData,
      [typeKey]: [...currentList, { 
        name: personForm.name, 
        qid_passport: personForm.qid_passport, 
        nationality: personForm.nationality,
        dob: personForm.dob || ""
      }]
    });
    setPersonForm({ ...personForm, name: '', qid_passport: '', nationality: '', dob: '' });
  };

  const removePerson = (type: string, index: number) => {
    const currentList = formData[type as keyof typeof formData] as any[];
    setFormData({
      ...formData,
      [type]: currentList.filter((_, i) => i !== index)
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    // Reset errors
    const errors: string[] = [];
    if (!formData["Client Name"]) errors.push("Client Name");
    if (!formData["No"]) errors.push("No");
    if (!formData["Company Nationality"]) errors.push("Company Nationality");

    setFormErrors(errors);

    if (errors.length > 0) {
      alert(`Provisioning Interrupted: Mandatory information is missing (${errors.join(', ')}).`);
      return;
    }

    setIsSubmitting(true);
    try {
      const newClient: Client = { 
        ...formData, 
        id: `RPME-${Math.random().toString(36).substr(2, 6).toUpperCase()}`, 
        created_at: new Date().toISOString(), 
        created_by: currentUserId, 
        riskLevel: RiskLevel.NONE, 
        entity_type: EntityType.CORPORATE 
      };

      console.log("[Registry] Committing authoritative provision payload:", newClient);
      await onAddClient(newClient);

      console.log("[Registry] Entity committed successfully.");
      setFormData({ ...INITIAL_FORM_STATE });
      setFormErrors([]);
      setIsModalOpen(false);
    } catch (err: any) { 
      const msg = err.message || "The node could not commit the entity to the registry.";
      console.error("[Registry] Provision Failure:", err);
      alert(`Critical Provisioning Failure: ${msg}`); 
    } finally { 
      setIsSubmitting(false); 
    }
  };

  const isPrivileged = currentUserRole === UserRole.ADMIN || currentUserRole === UserRole.DATA_ENTRY;

  const handleConfirmDelete = async () => {
    if (pendingDeleteId && !isDeleting) {
      setIsDeleting(true);
      try {
        await onDeleteClient(pendingDeleteId);
        if (selectedClient?.id === pendingDeleteId) {
          setSelectedClient(null);
        }
        setPendingDeleteId(null);
      } catch (err: any) {
        alert("Deletion Failed: " + (err.message || "Communication fault."));
      } finally {
        setIsDeleting(false);
      }
    }
  };

  return (
    <div className="space-y-6 sm:space-y-8 relative">

      {/* SCREENING PROGRESS INDICATOR */}
      {screeningProgress && screeningProgress.status !== 'Not Started' && (
        <div className="bg-emerald-950 p-6 sm:p-8 rounded-[2rem] text-white shadow-2xl animate-in slide-in-from-top-4 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-5">
             <Activity size={100} />
          </div>
          <div className="flex flex-col sm:flex-row justify-between items-center gap-6 relative z-10">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-white/10 rounded-2xl animate-pulse">
                {screeningProgress.status === 'Completed' ? <CheckCircle className="text-emerald-400" size={24}/> : <ScanSearch className="text-amber-400" size={24}/>}
              </div>
              <div>
                <h4 className="text-lg font-black uppercase tracking-tight">
                  {screeningProgress.status === 'Completed' ? 'Batch Authoritative Screening Finalized' : 'Global Screening In Progress'}
                </h4>
                <p className="text-[10px] text-white/50 font-black uppercase tracking-widest mt-1">
                   Authority: Sanctions Master Table (Auth-Consensus)
                </p>
              </div>
            </div>
            <div className="flex items-center gap-4 w-full sm:w-auto">
               <div className="flex flex-col items-end">
                  <p className="text-[9px] font-black text-white/30 uppercase">Screened / Total</p>
                  <p className="text-sm font-black text-emerald-400">{screeningProgress.screenedRecords.toLocaleString()} / {screeningProgress.totalRecords.toLocaleString()}</p>
               </div>
               <div className="flex-1 sm:w-48 h-2 bg-white/10 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-emerald-400 transition-all duration-500" 
                    style={{ width: `${(screeningProgress.screenedRecords / screeningProgress.totalRecords) * 100}%` }}
                  />
               </div>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white p-6 sm:p-8 rounded-2xl sm:rounded-[2.5rem] border border-gray-100 shadow-sm relative z-10 gap-4">
        <div>
          <h2 className="text-2xl sm:text-3xl font-black text-emerald-950 tracking-tighter uppercase">Corporate Registry</h2>
          <p className="text-[10px] text-emerald-700 mt-1 uppercase tracking-[0.4em] font-black">Database-Authoritative Hub</p>
        </div>
        <div className="flex w-full sm:w-auto gap-3">
          <button 
            onClick={onReScreen} 
            disabled={isRefreshing || (screeningProgress?.status === 'In Progress')} 
            className="flex items-center gap-2 px-6 py-4 bg-amber-50 text-amber-700 border border-amber-100 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-amber-100 transition-all disabled:opacity-50"
          >
             <Database size={18} /> Global DB Screen
          </button>
          <button onClick={onRefresh} disabled={isRefreshing} className="p-4 text-gray-400 hover:text-emerald-800 bg-gray-50 rounded-xl transition-all shrink-0">
            <RefreshCw size={24} className={isRefreshing ? 'animate-spin' : ''}/>
          </button>
          {isPrivileged && (
            <button 
              type="button" 
              onClick={(e) => { e.stopPropagation(); setIsModalOpen(true); }} 
              className="flex-1 sm:flex-none bg-emerald-800 text-white px-6 sm:px-8 py-4 rounded-xl sm:rounded-2xl font-black text-[10px] uppercase tracking-widest flex justify-center items-center gap-2 shadow-xl hover:bg-emerald-900 transition-all"
            >
              <Plus size={18} /> Provision Entity
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-2xl sm:rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden relative z-0 flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left min-w-[900px]">
            <thead>
              <tr className="bg-gray-50/50">
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Entity Name</th>
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Screening Status</th>
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Risk Index</th>
                <th className="px-6 sm:px-10 py-5 sm:py-6 text-right">Audit</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {clients.map(client => (
                <tr key={client.id} className="hover:bg-emerald-50/20 cursor-pointer transition-colors group" onClick={() => setSelectedClient(client)}>
                  <td className="px-6 sm:px-10 py-5 sm:py-6">
                    <div className="font-black text-emerald-950 text-sm tracking-tight">{client["Client Name"]}</div>
                    <div className="text-[8px] text-gray-400 font-bold uppercase mt-1">Ref: {client["No"]} • {client["Legal Structure"] || 'Corporate'}</div>
                  </td>
                  <td className="px-6 sm:px-10 py-5 sm:py-6">
                    <div className="flex flex-col gap-1">
                       <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-[8px] font-black uppercase border ${client.lastScreenedAt ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                          {client.lastScreenedAt ? <CheckCircle2 size={10}/> : <Activity size={10}/>}
                          {client.lastScreenedAt ? 'DB Authoritative' : 'Screening Required'}
                       </span>
                       {client.lastScreenedAt && (
                         <span className="text-[7px] text-gray-400 font-bold uppercase ml-1">
                           {new Date(client.lastScreenedAt).toLocaleString()}
                         </span>
                       )}
                    </div>
                  </td>
                  <td className="px-6 sm:px-10 py-5 sm:py-6">
                    <div className="flex items-center gap-2">
                       <span className={`px-2.5 py-1 rounded-md text-[9px] font-black uppercase border-2 flex items-center gap-1.5 ${
                         client.riskLevel === RiskLevel.HIGH ? 'bg-red-500 text-white border-red-600' :
                         'bg-gray-100 text-gray-400 border-gray-200'
                       }`}>
                         {client.riskLevel === RiskLevel.HIGH ? <ShieldAlert size={10} /> : <CheckCircle size={10} />}
                         {client.riskLevel === RiskLevel.HIGH ? 'HIGH RISK' : 'CLEAR'}
                       </span>
                    </div>
                  </td>
                  <td className="px-6 sm:px-10 py-5 sm:py-6 text-right">
                    <div className="flex justify-end items-center gap-2">
                      <button 
                        onClick={(e) => { e.stopPropagation(); setSelectedClient(client); }}
                        className="p-3 text-emerald-800 bg-gray-50 rounded-xl sm:opacity-0 group-hover:opacity-100 transition-all hover:bg-emerald-100"
                      >
                        <Eye size={20}/>
                      </button>
                      {isPrivileged && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); setPendingDeleteId(client.id); }}
                          className="p-3 text-red-600 bg-red-50 rounded-xl sm:opacity-0 group-hover:opacity-100 transition-all hover:bg-red-100"
                        >
                          <Trash2 size={20}/>
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
              {clients.length === 0 && !isRefreshing && (
                <tr>
                  <td colSpan={4} className="py-20 text-center opacity-30 font-black uppercase tracking-widest">
                    No registry entries found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {totalCount > 0 && (
          <div className="px-6 sm:px-10 py-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-gray-50/30">
            <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">
              Tier <span className="text-emerald-950">{currentPage}</span> of {totalPages} <span className="mx-2 hidden sm:inline">•</span> <span className="block sm:inline mt-1 sm:mt-0">{totalCount.toLocaleString()} Corporate Profiles</span>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => onPageChange(1)} disabled={currentPage === 1 || isRefreshing} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"><ChevronsLeft size={18} /></button>
              <button onClick={() => onPageChange(currentPage - 1)} disabled={currentPage === 1 || isRefreshing} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"><ChevronLeft size={18} /></button>
              <div className="px-6 py-3 text-[10px] font-black text-emerald-950 bg-white rounded-xl border border-gray-200 shadow-sm min-w-[100px] text-center uppercase tracking-widest">{currentPage}</div>
              <button onClick={() => onPageChange(currentPage + 1)} disabled={currentPage === totalPages || isRefreshing} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"><ChevronRight size={18} /></button>
              <button onClick={() => onPageChange(totalPages)} disabled={currentPage === totalPages || isRefreshing} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 disabled:opacity-30 text-emerald-800 transition-all shadow-sm"><ChevronsRight size={18} /></button>
            </div>
          </div>
        )}
      </div>

      {/* CLIENT DOSSIER MODAL */}
      {selectedClient && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-xl z-[100] flex items-center justify-center p-4 sm:p-6">
          <div className="bg-white rounded-[2.5rem] sm:rounded-[3.5rem] w-full max-w-5xl h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in-95 duration-300">
            {/* Dossier Header */}
            <div className={`p-8 sm:p-12 text-white relative overflow-hidden shrink-0 ${selectedClient.riskLevel === RiskLevel.HIGH ? 'bg-red-900' : 'bg-emerald-900'}`}>
               <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
                  <Fingerprint size={160} />
               </div>

               <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 relative z-10">
                  <div className="space-y-4">
                     <div className="flex items-center gap-3">
                        <span className="px-3 py-1 bg-white/10 rounded-lg text-[10px] font-black uppercase tracking-[0.2em] border border-white/20">
                           {selectedClient.id}
                        </span>
                        {selectedClient.riskLevel === RiskLevel.HIGH && (
                           <span className="px-3 py-1 bg-white text-red-900 rounded-lg text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-2">
                              <ShieldAlert size={12} /> Mandatory High Risk
                           </span>
                        )}
                     </div>
                     <h2 className="text-3xl sm:text-4xl font-black tracking-tight uppercase leading-none">
                        {selectedClient["Client Name"]}
                     </h2>
                     <div className="flex flex-wrap gap-4 text-[10px] font-black uppercase tracking-widest text-white/60">
                        <span className="flex items-center gap-2"><Globe size={14}/> {selectedClient["Company Nationality"]}</span>
                        <span className="flex items-center gap-2"><Landmark size={14}/> {selectedClient["Legal Structure"]}</span>
                        <span className="flex items-center gap-2"><Calendar size={14}/> Joined {selectedClient["Engagement Year"]}</span>
                     </div>
                  </div>
                  <button 
                    onClick={() => setSelectedClient(null)} 
                    className="p-4 bg-white/10 hover:bg-white/20 rounded-full transition-all border border-white/10"
                  >
                    <X size={24} />
                  </button>
               </div>
            </div>

            {/* Dossier Body */}
            <div className="flex-1 overflow-y-auto p-8 sm:p-12 space-y-12 custom-scrollbar bg-gray-50/30">
               {/* Risk & Compliance Summary */}
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className={`p-8 rounded-[2rem] border shadow-sm ${selectedClient.riskLevel === RiskLevel.HIGH ? 'bg-red-50 border-red-100' : 'bg-emerald-50 border-emerald-100'}`}>
                     <div className="flex items-center gap-3 mb-4">
                        <Shield className={selectedClient.riskLevel === RiskLevel.HIGH ? 'text-red-600' : 'text-emerald-600'} size={24}/>
                        <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-500">Risk Assessment</h4>
                     </div>
                     <p className={`text-2xl font-black uppercase ${selectedClient.riskLevel === RiskLevel.HIGH ? 'text-red-900' : 'text-emerald-900'}`}>
                        {selectedClient.riskLevel === RiskLevel.HIGH ? 'High Risk' : 'Clearance Valid'}
                     </p>
                     <p className="text-[9px] font-bold text-gray-400 uppercase mt-2">Compliance Rating: 98% Integrity</p>
                  </div>

                  <div className="p-8 rounded-[2rem] border border-gray-100 bg-white shadow-sm md:col-span-2 space-y-4">
                     <div className="flex items-center gap-3">
                        <History className="text-gray-400" size={24}/>
                        <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-500">Screening Audit Trail</h4>
                     </div>
                     <div className="flex flex-wrap gap-6">
                        <div>
                           <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Last System Check</p>
                           <p className="text-sm font-bold text-emerald-950">{selectedClient.lastScreenedAt ? new Date(selectedClient.lastScreenedAt).toLocaleString() : 'Pending Batch'}</p>
                        </div>
                        <div>
                           <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Matched Sanction IDs</p>
                           <p className="text-sm font-bold text-emerald-950">{selectedClient.matches?.length || 0} Conflict Matches</p>
                        </div>
                        <div>
                           <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Provisioned By</p>
                           <p className="text-sm font-bold text-emerald-950 uppercase">{selectedClient.created_by || 'System Automatic'}</p>
                        </div>
                     </div>
                  </div>
               </div>

               {/* Detailed Information Sections */}
               <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                  <div className="space-y-6">
                     <h4 className="flex items-center gap-3 text-xs font-black uppercase tracking-widest text-emerald-900 border-b border-gray-100 pb-4">
                        <Info size={16}/> Identity & Jurisdiction
                     </h4>
                     <div className="grid grid-cols-1 gap-3">
                        <DetailRow label="Entity Legal Name" value={selectedClient["Client Name"]} icon={<Fingerprint size={16}/>} />
                        <DetailRow label="File Reference No" value={selectedClient["No"]} icon={<FileText size={16}/>} />
                        <DetailRow label="QFC Registration No" value={selectedClient["QFC No"]} icon={<Landmark size={16}/>} />
                        <DetailRow label="Onboarding Date" value={selectedClient["Onboarding Date"]} icon={<Calendar size={16}/>} />
                        <DetailRow label="Legal Form" value={selectedClient["Legal Structure"]} icon={<Landmark size={16}/>} />
                     </div>
                  </div>

                  <div className="space-y-6">
                     <h4 className="flex items-center gap-3 text-xs font-black uppercase tracking-widest text-emerald-900 border-b border-gray-100 pb-4">
                        <MapPin size={16}/> Connectivity & Operations
                     </h4>
                     <div className="grid grid-cols-1 gap-3">
                        <DetailRow label="Primary Address" value={selectedClient["Registered Address"]} icon={<MapPin size={16}/>} />
                        <DetailRow label="Communication Channel" value={selectedClient["E Mail"]} icon={<Mail size={16}/>} />
                        <DetailRow label="Business Telephone" value={selectedClient["Telephone Number"]} icon={<Phone size={16}/>} />
                        <DetailRow label="Digital Presence" value={selectedClient["Website"]} icon={<Globe size={16}/>} />
                     </div>
                  </div>
               </div>

               {/* Personnel Records */}
               <div className="space-y-6">
                  <h4 className="flex items-center gap-3 text-xs font-black uppercase tracking-widest text-emerald-900 border-b border-gray-100 pb-4">
                     <Users size={16}/> Key Personnel & UBO Registry
                  </h4>
                  { (selectedClient["Directors Names"]?.length || 0) > 0 || (selectedClient["UBO Details"]?.length || 0) > 0 ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                       {[...(selectedClient["Directors Names"] || []), ...(selectedClient["UBO Details"] || [])].map((person, idx) => (
                          <div key={idx} className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm flex items-center gap-4">
                             <div className="h-12 w-12 rounded-2xl bg-gray-50 flex items-center justify-center text-emerald-800 border border-gray-100 shrink-0">
