            <h3 className="text-lg font-black text-emerald-950 uppercase tracking-tight mb-2">Purge Entity Profile?</h3>
            <p className="text-xs text-gray-500 font-bold mb-8 uppercase leading-relaxed">
              This action will permanently delete the entity from the authoritative registry. This is irreversible.
            </p>
            <div className="flex gap-3">
              <button 
                onClick={() => setPendingDeleteId(null)} 
                disabled={isDeleting}
                className="flex-1 py-4 bg-gray-50 text-gray-400 font-black text-[10px] uppercase rounded-xl tracking-widest disabled:opacity-50"
