/**
 * Robust error message extractor to prevent [object Object]
 */
const extractError = (err: any): string => {
  if (!err) return "Unknown Error";
  if (typeof err === 'string') return err;

  // Try to find a message in common Supabase/PostgREST error structures
  const msg = err.message || err.error_description || err.details || (err.error && err.error.message);
  if (msg) return String(msg);

  try {
    return JSON.stringify(err);
  } catch (e) {
    return String(err);
  }
};

/**
 * Helper to ensure dates are either valid strings or null (Postgres safety)
 */
const cleanDate = (val: any) => {
  if (!val || val === "" || val === "undefined" || val === "null") return null;
  return String(val);
};

