      un_list_type: s.unListType,
      aliases: s.aliases,
      fetch_date: s.fetchDate || new Date().toISOString()
    }));
    await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
    if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
  }
};

export const logIngestionEvent = async (log: any) => {
  if (!supabaseClient) return;
  await supabaseClient.from('ingestion_logs').insert([{
    source: log.source,
    method: log.method,
    status: log.status,
    records_processed: log.recordsProcessed,
    records_accepted: log.recordsAccepted,
    records_rejected: log.recordsRejected,
    details: log.details,
    triggered_by: log.triggeredBy
  }]);
};

export const fetchIngestionLogs = async (): Promise<IngestionLog[]> => {
  if (!supabaseClient) return [];
  const { data, error } = await supabaseClient.from('ingestion_logs').select('*').order('timestamp', { ascending: false }).limit(50);
  if (error) return [];
  return (data || []).map((row: any) => ({
    id: row.id,
    timestamp: row.timestamp,
    source: row.source,
    method: row.method,
    status: row.status,
    recordsProcessed: row.records_processed,
    recordsAccepted: row.records_accepted,
    recordsRejected: row.records_rejected,
    details: row.details,
    triggeredBy: row.triggered_by
  }));
};

