import React, { useState, useEffect, useRef, useCallback } from 'react';
import { SanctionEntry } from '../types';
import { 
  RefreshCw, Search, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, 
  Upload, FileCheck, ArrowDownToLine, Globe, ShieldAlert, Loader2, Database,
  ArrowLeft, ArrowRight, Layers
} from 'lucide-react';
import { searchSanctionsAuthoritative, fetchSanctionsBatch } from '../services/cloudDb';

interface SanctionsBrowserProps {
  sanctions: SanctionEntry[];
  lastUpdated: string;
  onRefresh: () => void;
  isUpdating: boolean;
  onFileUpload: (file: File, type: 'UN' | 'OFAC' | 'OPEN') => void;
  totalInDb?: number;
}

const ITEMS_PER_PAGE = 15;
const BATCH_SIZE = 1000;

const SanctionsBrowser: React.FC<SanctionsBrowserProps> = ({ 
  sanctions: initialSanctions, 
  lastUpdated, 
  onRefresh, 
  isUpdating, 
  onFileUpload,
  totalInDb = 0
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [displaySanctions, setDisplaySanctions] = useState<SanctionEntry[]>(initialSanctions);
  const [isSearchingAuthoritative, setIsSearchingAuthoritative] = useState(false);
  const [isFetchingBatch, setIsFetchingBatch] = useState(false);
  const [importMenuOpen, setImportMenuOpen] = useState(false);
  const [batchOffset, setBatchOffset] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (searchTerm.trim() === '') {
      setDisplaySanctions(initialSanctions);
    }
  }, [initialSanctions, searchTerm]);

  // Authoritative Search Handler
  useEffect(() => {
    const handler = setTimeout(async () => {
      if (searchTerm.trim().length > 2) {
        setIsSearchingAuthoritative(true);
        const results = await searchSanctionsAuthoritative(searchTerm);
        setDisplaySanctions(results);
        setIsSearchingAuthoritative(false);
        setCurrentPage(1);
      } else if (searchTerm.trim().length === 0) {
        // When clearing search, revert to the current batch
        handleFetchBatch(batchOffset);
      }
    }, 500);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  const handleFetchBatch = async (offset: number) => {
    setIsFetchingBatch(true);
    try {
      const nextBatch = await fetchSanctionsBatch(offset, offset + BATCH_SIZE - 1);
      setDisplaySanctions(nextBatch);
      setBatchOffset(offset);
      setCurrentPage(1);
    } catch (err) {
      console.error("Batch fetch failed", err);
    } finally {
      setIsFetchingBatch(false);
    }
  };

  const totalPages = Math.ceil(displaySanctions.length / ITEMS_PER_PAGE);
  const paginatedData = displaySanctions.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) setCurrentPage(page);
  };

  const isSearchActive = searchTerm.trim().length > 0;

  return (
    <div className="space-y-6 sm:space-y-8">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
           <h2 className="text-xl sm:text-2xl font-black text-emerald-950 uppercase tracking-tight">Global Screening Registry</h2>
           <p className="text-xs sm:text-sm text-gray-500 mt-1">Direct database lookups against authoritative sanctions table.</p>
           <div className="mt-3 flex items-center gap-2">
              <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] sm:text-[10px] font-black uppercase tracking-widest transition-all ${lastUpdated !== 'Never' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-amber-50 text-amber-700 border-amber-100'}`}>
                <FileCheck size={12} className={isUpdating ? 'animate-pulse' : ''} />
                <span>Last Manual Import: {lastUpdated !== 'Never' ? new Date(lastUpdated).toLocaleString() : 'Import Required'}</span>
              </div>
           </div>
        </div>
        <div className="flex flex-col xs:flex-row w-full lg:w-auto gap-3">
          <input type="file" ref={fileInputRef} onChange={(e) => e.target.files?.[0] && onFileUpload(e.target.files[0], 'UN')} className="hidden" />
          <div className="relative flex-1 xs:flex-none">
            <button onClick={() => setImportMenuOpen(!importMenuOpen)} className="w-full flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl bg-blue-600 text-white hover:bg-blue-700 font-black text-[10px] uppercase h-[52px]">
              <Upload size={18} /> Import Data
            </button>
            {importMenuOpen && (
              <div className="absolute left-0 xs:left-auto right-0 top-full mt-2 w-full xs:w-64 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 p-2 overflow-hidden">
                <button onClick={() => {fileInputRef.current?.click(); setImportMenuOpen(false);}} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-blue-50 text-left rounded-xl transition-colors">
