           {isSearchingAuthoritative ? <Loader2 size={14} className="animate-spin text-emerald-600"/> : displaySanctions.length.toLocaleString()} {isSearchActive ? 'Search Hits' : 'Batch Hits'}
        </div>
      </div>

      <div className="bg-white rounded-2xl sm:rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden flex flex-col relative">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse min-w-[1100px]">
            <thead className="bg-gray-50/50 border-b border-gray-100">
