              {paginatedData.length === 0 && (
                <tr><td colSpan={6} className="py-20 text-center opacity-30 font-black uppercase tracking-widest">
                  {isFetchingBatch ? 'Synchronizing Batch...' : 'No matching records in master sanctions table.'}
                </td></tr>
              )}
