        </div>
        {displaySanctions.length > 0 && (
          <div className="px-6 py-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6 bg-gray-50/30">
            <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">
              Showing <span className="text-emerald-950">{(currentPage - 1) * ITEMS_PER_PAGE + 1} - {Math.min(currentPage * ITEMS_PER_PAGE, displaySanctions.length)}</span> of {displaySanctions.length.toLocaleString()} in current view
            </div>
            <div className="flex items-center gap-2">
