  const isSearchActive = searchTerm.trim().length > 0;

  return (
    <div className="space-y-6 sm:space-y-8">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div>
           <h2 className="text-xl sm:text-2xl font-black text-emerald-950 uppercase tracking-tight">Global Screening Registry</h2>
           <p className="text-xs sm:text-sm text-gray-500 mt-1">Search the master database to view authoritative sanctions records.</p>
           <div className="mt-3 flex items-center gap-2">
              <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] sm:text-[10px] font-black uppercase tracking-widest transition-all ${lastUpdated !== 'Never' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-amber-50 text-amber-700 border-amber-100'}`}>
                <FileCheck size={12} className={isUpdating ? 'animate-pulse' : ''} />
