const CORPORATE_NOISE = [
  'CO', 'LTD', 'CORP', 'INC', 'INTERNATIONAL', 'SHIPPING', 'AGENCY', 'UNITED', 
  'AND', 'FOR', 'THE', 'LIMITED', 'GROUP', 'COMPANY', 'LLC', 'PVT', 'FZE', 
  'PLC', 'SERVICES', 'TRADING', 'MARITIME', 'MANAGEMENT', 'INVESTMENT', 
  'HOLDINGS', 'TRUST', 'PARTNERS', 'L.L.C', 'L.T.D', 'CO.', 'CO.,'
];

/**
 * AUTHORITATIVE SEARCH V3.6.0
 * Deep-scans all name columns and JSONB aliases.
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const normalized = name.trim().toUpperCase();

  // Split into tokens for granular matching (ignoring noise)
  const tokens = normalized.split(/[\s,.-]+/).filter(t => t.length >= 2 && !CORPORATE_NOISE.includes(t));

  try {
    // We fetch a larger candidate pool and refine if needed
    let query = supabaseClient.from('sanctions').select('*');

    const searchConditions: string[] = [];

    // 1. Exact phrase match across primary containers
    searchConditions.push(`first_name.ilike.%${normalized}%`);
    searchConditions.push(`last_name.ilike.%${normalized}%`);
    searchConditions.push(`comments.ilike.%${normalized}%`);

    // 2. Tokenized matching (to catch "AEROCARIBBEAN" if it's in firstName and "AIRLINES" in lastName)
    if (tokens.length > 0) {
      tokens.forEach(token => {
        searchConditions.push(`first_name.ilike.%${token}%`);
        searchConditions.push(`second_name.ilike.%${token}%`);
        searchConditions.push(`third_name.ilike.%${token}%`);
        searchConditions.push(`last_name.ilike.%${token}%`);
        searchConditions.push(`reference_number.ilike.%${token}%`);
        // Search inside aliases JSONB (cast to text for ILIKE)
        searchConditions.push(`aliases::text.ilike.%${token}%`);
      });
    }

    if (searchConditions.length > 0) {
      query = query.or(searchConditions.join(','));
    }

    const { data, error } = await query.limit(100);
    if (error) {
      console.error("Master Search Error:", error);
      return [];
    }

    return (data || []).map((row: any) => ({
      dataId: String(row.data_id ?? ''),
      firstName: String(row.first_name ?? ''),
      secondName: String(row.second_name ?? ''),
      thirdName: String(row.third_name ?? ''),
      lastName: String(row.last_name ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? ''),
      listedOn: String(row.listed_on ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? ''),
      unListType: String(row.un_list_type ?? ''),
      comments: String(row.comments ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e) { return []; }
};

export const screenEntityAgainstDb = async (client: Client, userId: string = 'System'): Promise<Client> => {
  const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
  const match = screenClient(client, candidates);
  const riskLevel = match ? match.riskLevel : RiskLevel.NONE;

  return {
    ...client,
    riskLevel: riskLevel,
    matches: match ? [match.sanctionId] : [],
    lastScreenedAt: new Date().toISOString()
  };
};

