export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const queryStr = name.trim().toUpperCase();

  try {
    // 1. We create a broad search across all relevant text-based columns
    // We use .or() with ilike and also search inside the aliases JSONB
    const { data, error } = await supabaseClient
      .from('sanctions')
      .select('*')
      .or(`first_name.ilike.%${queryStr}%,last_name.ilike.%${queryStr}%,second_name.ilike.%${queryStr}%,third_name.ilike.%${queryStr}%,comments.ilike.%${queryStr}%,reference_number.ilike.%${queryStr}%,aliases::text.ilike.%${queryStr}%`)
      .limit(100);

    if (error) {
      console.error("Search Error:", error);
      return [];
    }

    // 2. Client-side refinement: If no direct match, try tokenized search
    let results = data || [];
    if (results.length === 0 && queryStr.includes(' ')) {
      const firstWord = queryStr.split(' ')[0];
      if (firstWord.length > 3) {
        const { data: secondPass } = await supabaseClient
          .from('sanctions')
          .select('*')
          .or(`first_name.ilike.%${firstWord}%,last_name.ilike.%${firstWord}%,aliases::text.ilike.%${firstWord}%`)
          .limit(50);
        results = secondPass || [];
      }
    }

    return results.map((row: any) => ({
      dataId: String(row.data_id ?? ''),
      firstName: String(row.first_name ?? ''),
      secondName: String(row.second_name ?? ''),
      thirdName: String(row.third_name ?? ''),
      lastName: String(row.last_name ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? ''),
      listedOn: String(row.listed_on ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? ''),
      unListType: String(row.un_list_type ?? ''),
      comments: String(row.comments ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e) { return []; }
};

