import { SanctionEntry, EntityType } from '../types';
import * as XLSX from 'xlsx';

export const OFFICIAL_UN_XML_URL = "https://scsanctions.un.org/resources/xml/en/consolidated.xml";
export const QATAR_NCTC_URL = "https://portal.moi.gov.qa/wps/portal/NCTC/sanctionlist/unifiedsanctionlist/";
export const OPENSANCTIONS_URL = "https://www.opensanctions.org/datasets/default/entities.json";
export const OFAC_SDN_URL = "https://www.treasury.gov/ofac/downloads/sdn.csv";

const PROXY_URL = "https://api.allorigins.win/get?url=";

/**
 * Parses the UN Consolidated List XML string
 */
export const parseUNSanctionsXML = (xmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlString, "text/xml");
  const entries: SanctionEntry[] = [];

  const getNodeVal = (parent: Element, tagName: string): string => {
    const node = parent.getElementsByTagName(tagName)[0];
    return node ? node.textContent?.trim() || '' : '';
  };

  const parseNode = (node: Element, isInd: boolean): SanctionEntry => {
    return {
      dataId: `UN-${getNodeVal(node, "DATAID")}`,
      source: 'UN Consolidated',
      firstName: getNodeVal(node, "FIRST_NAME"),
      secondName: getNodeVal(node, "SECOND_NAME"),
      thirdName: getNodeVal(node, "THIRD_NAME"),
      lastName: getNodeVal(node, "LAST_NAME") || '',
      unListType: getNodeVal(node, "UN_LIST_TYPE"),
      referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
      listedOn: getNodeVal(node, "LISTED_ON"),
      comments: getNodeVal(node, "COMMENTS1"),
      nationality: node.getElementsByTagName("NATIONALITY")[0] ? getNodeVal(node.getElementsByTagName("NATIONALITY")[0], "VALUE") : '',
      dateOfBirth: isInd ? (node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0] ? getNodeVal(node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0], "DATE") : '') : '',
      aliases: Array.from(node.getElementsByTagName(isInd ? "INDIVIDUAL_ALIAS" : "ENTITY_ALIAS")).map(a => getNodeVal(a, "ALIAS_NAME")).filter(Boolean),
      type: isInd ? EntityType.INDIVIDUAL : EntityType.CORPORATE,
      fetchDate: new Date().toISOString()
    };
  };

  const individuals = xmlDoc.getElementsByTagName("INDIVIDUAL");
  for (let i = 0; i < individuals.length; i++) entries.push(parseNode(individuals[i], true));

  const entities = xmlDoc.getElementsByTagName("ENTITY");
  for (let i = 0; i < entities.length; i++) entries.push(parseNode(entities[i], false));

  return entries;
};

/**
 * Robust CSV Parser for SDN lists and custom data
 */
export const parseCSVToSanctions = (csv: string, sourceName: string): any[] => {
  const rows: any[] = [];
  const lines = csv.split(/\r?\n/);
  if (lines.length < 2) return [];

  // Helper to split CSV line while respecting quotes
  const splitLine = (line: string) => {
    const result = [];
    let startValueIndex = 0;
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      if (line[i] === '"') inQuotes = !inQuotes;
      if (line[i] === ',' && !inQuotes) {
        result.push(line.substring(startValueIndex, i).replace(/^"|"$/g, '').trim());
        startValueIndex = i + 1;
      }
    }
    result.push(line.substring(startValueIndex).replace(/^"|"$/g, '').trim());
    return result;
  };

  const headers = splitLine(lines[0]).map(h => h.toLowerCase());

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const values = splitLine(line);
    const obj: any = {};
    headers.forEach((h, idx) => { obj[h] = values[idx] || ''; });
    rows.push(obj);
  }
  return rows;
};

/**
 * Detects format of provided file content
 */
export const detectFormat = (content: string, fileName: string): 'XML' | 'JSON' | 'CSV' | 'EXCEL' | 'UNKNOWN' => {
  const ext = fileName.split('.').pop()?.toUpperCase();
  if (ext === 'XLSX' || ext === 'XLS') return 'EXCEL';
  if (ext === 'JSON') return 'JSON';
  if (ext === 'CSV' || ext === 'TXT') return 'CSV';
  if (ext === 'XML' || content.trim().startsWith('<?xml') || content.trim().startsWith('<')) return 'XML';
  return 'UNKNOWN';
};

/**
 * Parses Excel files (XLSX/XLS) using SheetJS
 */
export const parseExcelToSanctions = (buffer: ArrayBuffer, fileName: string): any[] => {
  try {
    const workbook = XLSX.read(buffer, { type: 'array' });
    const firstSheetName = workbook.SheetNames[0];
    const worksheet = workbook.Sheets[firstSheetName];
    // Convert to JSON with headers
    return XLSX.utils.sheet_to_json(worksheet, { defval: '' });
  } catch (error) {
    console.error("Excel Parsing Error:", error);
    return [];
  }
};

/**
 * Maps arbitrary row data to internal SanctionEntry structure
 */
export const mapFieldsToSanction = (row: any, mapping: Record<string, string>, source: string): SanctionEntry => {
  const getVal = (field: string) => {
    const mappedKey = mapping[field];
    if (!mappedKey) return '';
    return String(row[mappedKey] || '').trim();
  };

  const firstName = getVal('firstName');
  const lastName = getVal('lastName');
  const comments = getVal('comments');
  const dataId = getVal('dataId') || `${source}-${Math.random().toString(36).substr(2, 8).toUpperCase()}`;

  return {
    dataId,
    source,
    firstName,
    lastName,
    secondName: getVal('secondName'),
    thirdName: getVal('thirdName'),
    unListType: getVal('unListType') || 'Manual Ingestion',
    referenceNumber: getVal('referenceNumber'),
    listedOn: getVal('listedOn') || new Date().toISOString().split('T')[0],
    comments,
    nationality: getVal('nationality'),
    dateOfBirth: getVal('dateOfBirth'),
    type: getVal('type').toLowerCase().includes('entity') || getVal('type').toLowerCase().includes('corp') 
          ? EntityType.CORPORATE 
          : EntityType.INDIVIDUAL,
    aliases: [], // Aliases can be added in mapping if needed as comma-separated strings
    fetchDate: new Date().toISOString()
  };
};

export const fetchAndNormalize = async (url: string, sourceName: string): Promise<SanctionEntry[]> => {
  try {
    const proxyResponse = await fetch(`${PROXY_URL}${encodeURIComponent(url)}`);
    const json = await proxyResponse.json();
    const content = json.contents;
    if (!content) throw new Error("Empty payload");
    if (content.trim().startsWith('<')) return parseUNSanctionsXML(content);
    return [];
  } catch (error: any) {
    throw error;
  }
};

