/**
 * AUTHORITATIVE SEARCH V3.6.8
 * Solves the "No Results" issue for multi-word entities.
 * Logic: Split name into tokens, find records matching the primary token, then refine.
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const queryStr = name.trim().toUpperCase();
  const tokens = queryStr.split(/\s+/).filter(t => t.length > 2);

  try {
    // 1. Primary Strategy: Exact Phrase Match across all logic units
    let query = supabaseClient
      .from('sanctions')
      .select('*')
      .or(`first_name.ilike.%${queryStr}%,last_name.ilike.%${queryStr}%,comments.ilike.%${queryStr}%,aliases::text.ilike.%${queryStr}%`);

    const { data: exactData, error: exactError } = await query.limit(50);

    if (exactError) {
      console.error("Search Error:", exactError);
      // Handle the "column not found" error specifically
      if (exactError.message?.includes("data_id") || exactError.message?.includes("column")) {
        throw new Error("SCHEMA_MISMATCH: The database schema is out of date. Please run the SQL script in Admin Panel.");
      }
      return [];
    }

    // 2. Secondary Strategy: If no exact matches, search by tokens (e.g. just "AEROCARIBBEAN")
    let results = exactData || [];
    if (results.length === 0 && tokens.length > 0) {
      const primaryToken = tokens[0];
      const { data: tokenData } = await supabaseClient
        .from('sanctions')
        .select('*')
        .or(`first_name.ilike.%${primaryToken}%,last_name.ilike.%${primaryToken}%,aliases::text.ilike.%${primaryToken}%`)
        .limit(100);

      if (tokenData) {
        // Refine token data: Ensure all tokens are present somewhere in the record
        results = tokenData.filter((row: any) => {
          const fullRowText = `${row.first_name} ${row.second_name} ${row.third_name} ${row.last_name} ${JSON.stringify(row.aliases)} ${row.comments}`.toUpperCase();
          return tokens.every(t => fullRowText.includes(t));
        });
      }
    }

    return results.map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: String(row.first_name ?? ''),
      secondName: String(row.second_name ?? ''),
      thirdName: String(row.third_name ?? ''),
      lastName: String(row.last_name ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? ''),
      listedOn: String(row.listed_on ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? ''),
      unListType: String(row.un_list_type ?? ''),
      comments: String(row.comments ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e: any) { 
    console.error("Authoritative search failed:", e);
    throw e;
  }
};

export const screenEntityAgainstDb = async (client: Client, userId: string = 'System'): Promise<Client> => {
  try {
    const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
    const match = screenClient(client, candidates);
    const riskLevel = match ? match.riskLevel : RiskLevel.NONE;

    return {
      ...client,
      riskLevel: riskLevel,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };
  } catch (e) {
    return { ...client, riskLevel: RiskLevel.NONE, lastScreenedAt: new Date().toISOString() };
  }
};

