    END IF;
END $$;

-- 4. Entity Registry
CREATE TABLE IF NOT EXISTS public.clients (id TEXT PRIMARY KEY);
ALTER TABLE public.clients DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS client_name TEXT;
ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS risk_level TEXT DEFAULT 'None';
ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS matches JSONB DEFAULT '[]'::jsonb;
ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS last_screened_at TIMESTAMPTZ;

-- 5. Ingestion Logs
CREATE TABLE IF NOT EXISTS public.ingestion_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid());
ALTER TABLE public.ingestion_logs DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.ingestion_logs ADD COLUMN IF NOT EXISTS source TEXT;
ALTER TABLE public.ingestion_logs ADD COLUMN IF NOT EXISTS status TEXT;
ALTER TABLE public.ingestion_logs ADD COLUMN IF NOT EXISTS records_processed INTEGER DEFAULT 0;

-- Force API Schema Reload
NOTIFY pgrst, 'reload schema';`;

