import React, { useState } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus, SystemEnvironment } from '../types';
import { Plus, Power, Trash2, Shield, Copy, Check, Users, ShieldAlert, History, Beaker, Zap, Terminal, X, Loader2 } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

// Fix: Completed the implementation of AdminPanel and added default export for App.tsx consumption
const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'users' | 'engine' | 'logs'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);
  const [copiedSql, setCopiedSql] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const SQL_SCHEMA = `-- v3.8.0 Enterprise Master Repair Script (FORCED DEDUPLICATION & NULL PURGE)
-- PURPOSE: Resolves PK violations, NULL values, and "no unique constraint" errors.

-- 1. Ensure Table Structure
CREATE TABLE IF NOT EXISTS public.sanctions (
  data_id TEXT
);
ALTER TABLE public.sanctions DISABLE ROW LEVEL SECURITY;

-- 2. Handle Column Migration (id -> data_id)
DO $$
BEGIN
    -- If 'id' exists and 'data_id' does not, rename 'id' to 'data_id'
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='id') 
       AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='data_id') THEN
        ALTER TABLE public.sanctions RENAME COLUMN id TO data_id;
    END IF;

    -- If 'data_id' still does not exist, add it
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='data_id') THEN
        ALTER TABLE public.sanctions ADD COLUMN data_id TEXT;
    END IF;
END $$;

-- 3. CRITICAL: Data Sanitization (Purge NULLs and Duplicates)
-- A Primary Key requires non-null, unique values.

-- Remove NULL or empty IDs
DELETE FROM public.sanctions WHERE data_id IS NULL OR data_id = '';

-- Remove Duplicates (Keep only the first row for each data_id)
DELETE FROM public.sanctions a USING public.sanctions b 
WHERE a.ctid < b.ctid AND a.data_id = b.data_id;

-- Ensure data_id is strictly NOT NULL
ALTER TABLE public.sanctions ALTER COLUMN data_id SET NOT NULL;

-- 4. Mandatory Columns Reconciliation
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS first_name TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS second_name TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS third_name TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS last_name TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS source TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS reference_number TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS listed_on TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS nationality TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS date_of_birth TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS un_list_type TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS comments TEXT;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS aliases JSONB DEFAULT '[]'::jsonb;
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS fetch_date TIMESTAMPTZ DEFAULT now();

-- 5. ENFORCE PRIMARY KEY
DO $$
BEGIN
    -- Check if table has ANY primary key
    IF EXISTS (
        SELECT 1 FROM information_schema.table_constraints 
        WHERE table_name='sanctions' AND constraint_type='PRIMARY KEY'
    ) THEN
        -- Check if that primary key is ALREADY data_id
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.key_column_usage 
            WHERE table_name='sanctions' AND column_name='data_id'
            AND constraint_name IN (
                SELECT constraint_name FROM information_schema.table_constraints 
                WHERE table_name='sanctions' AND constraint_type='PRIMARY KEY'
            )
        ) THEN
            -- If it's the wrong PK, drop it and reset
            EXECUTE 'ALTER TABLE public.sanctions DROP CONSTRAINT ' || (
                SELECT constraint_name FROM information_schema.table_constraints 
                WHERE table_name='sanctions' AND constraint_type='PRIMARY KEY'
                LIMIT 1
            );
            ALTER TABLE public.sanctions ADD PRIMARY KEY (data_id);
        END IF;
    ELSE
        -- No PK exists, add it
        ALTER TABLE public.sanctions ADD PRIMARY KEY (data_id);
    END IF;
END $$;

-- 6. UNIQUE INDEX FOR UPSERT (Ensures PostgREST optimization)
CREATE UNIQUE INDEX IF NOT EXISTS sanctions_data_id_idx ON public.sanctions (data_id);

-- 7. Sync Metadata Table
CREATE TABLE IF NOT EXISTS public.system_metadata (key TEXT PRIMARY KEY, value JSONB DEFAULT '{}'::jsonb);
ALTER TABLE public.system_metadata DISABLE ROW LEVEL SECURITY;

-- Reload Cache
NOTIFY pgrst, 'reload schema';`;

  const copySql = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopiedSql(true);
    setTimeout(() => setCopiedSql(false), 2000);
  };

  const saveUsersToStorage = (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isDelete) { await deleteCloudUser(user.email); } else { await upsertCloudUser(user); }
    } catch (e) {} finally { setIsSyncing(false); }
  };

  const toggleUserStatus = async (email: string) => {
    const updated = systemUsers.map(u => {
      if (u.email === email) {
        const newUser = { ...u, status: u.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE };
        handleCloudSync(newUser);
        return newUser;
      }
      return u;
    });
    saveUsersToStorage(updated);
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;
    const updated = systemUsers.filter(u => u.email !== pendingDeleteUser.email);
    saveUsersToStorage(updated);
    await handleCloudSync(pendingDeleteUser, true);
    setPendingDeleteUser(null);
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: newUserEmail.trim().toLowerCase(),
      password: DEFAULT_TEMP_PASSWORD,
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };
    await handleCloudSync(newUser);
    saveUsersToStorage([...systemUsers, newUser]);
    setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false); setIsNewUserAdmin(false);
  };

  const toggleEnvironment = () => {
    const newEnv = settings.environment === SystemEnvironment.PRODUCTION 
      ? SystemEnvironment.SANDBOX 
      : SystemEnvironment.PRODUCTION;
    onUpdateSettings({ ...settings, environment: newEnv });
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center bg-white p-6 sm:p-8 rounded-[2rem] shadow-sm border border-gray-100 gap-6">
        <div className="flex items-center gap-4">
          <div className={`${settings.environment === SystemEnvironment.PRODUCTION ? 'bg-emerald-800' : 'bg-amber-600'} p-4 rounded-2xl text-white shadow-xl transition-colors duration-500`}>
            {settings.environment === SystemEnvironment.PRODUCTION ? <Shield size={28}/> : <Beaker size={28}/>}
          </div>
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-900 tracking-tight uppercase">Governance</h2>
            <p className="text-[10px] text-emerald-600 font-black uppercase tracking-widest mt-1">Enterprise Registry Control</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full xl:w-auto">
            <button onClick={() => setActiveTab('users')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'users' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Identities</button>
            <button onClick={() => setActiveTab('engine')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'engine' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Engine</button>
            <button onClick={() => setActiveTab('logs')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'logs' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>System Logs</button>
        </div>
      </div>

      {activeTab === 'users' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex justify-between items-center border-b border-gray-50 pb-6">
              <div className="flex items-center gap-3">
                 <Users className="text-emerald-800" size={20} />
                 <h3 className="text-sm font-black uppercase text-slate-900">Identity Management</h3>
              </div>
              <button onClick={() => setIsUserModalOpen(true)} className="bg-emerald-800 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg hover:bg-emerald-900 transition-all">
                 <Plus size={16} /> Provision User
              </button>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[600px]">
                 <thead>
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                       <th className="px-4 py-4">Identity</th>
                       <th className="px-4 py-4">Role</th>
                       <th className="px-4 py-4">Status</th>
                       <th className="px-4 py-4 text-right">Actions</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {systemUsers.map((user: any) => (
                       <tr key={user.email} className="hover:bg-slate-50 transition-colors group">
                          <td className="px-4 py-4">
                             <p className="text-sm font-black text-slate-900 uppercase">{user.full_name}</p>
                             <p className="text-[10px] text-slate-400 font-bold">{user.email}</p>
                          </td>
                          <td className="px-4 py-4">
