        timestamp: new Date().toISOString(), source, method: 'Manual', status: 'Success',
        recordsProcessed: count, recordsAccepted: count, recordsRejected: 0, triggeredBy: currentUser?.id || 'System'
      });
      await refreshDbStats();
      setStatus('COMPLETED');
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate);
      const isSchemaError = err.message?.includes('data_id') || err.message?.includes('column') || err.message?.includes('SCHEMA_CONFLICT') || err.message?.includes('primary');
      setErrorMessage(isSchemaError ? "DATABASE SCHEMA MISMATCH: You must copy and run the SQL v4.2.0 script from the Governance tab to reconcile columns and constraints." : err.message);
