/**
 * FIXED UPSERT LOGIC V4.2.0
 * Explicitly targets 'data_id' as the unique constraint.
 */
export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void) => {
  if (!supabaseClient) throw new Error("Database offline.");
  const total = sanctions.length;
  for (let i = 0; i < total; i += 200) {
    const batch = sanctions.slice(i, i + 200).map(s => ({
      data_id: String(s.dataId),
      first_name: String(s.firstName || ''),
      second_name: String(s.secondName || ''),
      third_name: String(s.thirdName || ''),
      last_name: String(s.lastName || ''),
      source: String(s.source || 'Manual Ingestion'),
      reference_number: String(s.referenceNumber || ''),
      listed_on: String(s.listedOn || ''),
      nationality: String(s.nationality || ''),
      date_of_birth: String(s.dateOfBirth || ''),
      un_list_type: String(s.unListType || ''),
      comments: String(s.comments || ''),
      aliases: Array.isArray(s.aliases) ? s.aliases : [],
      fetch_date: s.fetchDate || new Date().toISOString()
    }));

    const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });

    if (error) {
      if (error.message?.includes('unique') || error.message?.includes('constraint') || error.message?.includes('primary')) {
        throw new Error("SCHEMA_CONFLICT: data_id column violates Primary Key or lacks UNIQUE constraint. Please run SQL Repair v4.2.0 in the Governance tab.");
      }
      throw new Error(`Cloud Persist Failed at index ${i}: ${error.message}`);
    }
    if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
  }
};

