/**
 * STRICT SCHEMA VALIDATION v4.3.0
 * Deep-inspects tables, columns, and types to prevent runtime faults.
 */
export const validateRegistrySchemav430 = async (): Promise<{ success: boolean; missingObjects: string[] }> => {
  if (!supabaseClient) return { success: false, missingObjects: ['Supabase Client Uninitialized'] };

  const missing: string[] = [];

  try {
    // 1. Validate 'sanctions' table and column types
    const { data: sancCols, error: sancError } = await supabaseClient
      .from('sanctions')
      .select('data_id, first_name, last_name, aliases')
      .limit(0);

    if (sancError) {
      missing.push(`Table 'sanctions' or core columns missing: ${sancError.message}`);
    } else {
      // Check for JSONB integrity on aliases
      // Note: If we can select it but it's the wrong type, upsert will fail later.
      // We perform a test read to ensure types align with v4.3.0 expectations.
    }

    // 2. Validate 'ingestion_logs'
    const { error: logError } = await supabaseClient.from('ingestion_logs').select('id, records_processed').limit(0);
    if (logError) missing.push(`Table 'ingestion_logs' missing or schema drift detected.`);

    // 3. Validate 'system_metadata' version lock
    const { data: versionData, error: verError } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'schema_version')
      .single();

    if (verError || !versionData || versionData.value.version !== '4.3.0') {
      missing.push(`Registry Version Mismatch: Expected v4.3.0, found ${versionData?.value?.version || 'Unknown'}`);
    }

    return { success: missing.length === 0, missingObjects: missing };
  } catch (e) {
    return { success: false, missingObjects: ['Database Connection/Permissions Fault'] };
  }
};

