/**
 * AUTHORITATIVE SEARCH V4.3.0
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const queryStr = name.trim().toUpperCase();
  const tokens = queryStr.split(/\s+/).filter(t => t.length > 2);

  try {
    let { data: exactData, error: exactError } = await supabaseClient
      .from('sanctions')
      .select('*')
      .or(`first_name.ilike.%${queryStr}%,last_name.ilike.%${queryStr}%,comments.ilike.%${queryStr}%,aliases::text.ilike.%${queryStr}%`)
      .limit(50);

    if (exactError) {
      throw new Error(`CRITICAL_REGISTRY_FAULT: Mismatch in 'sanctions' schema. Error: ${exactError.message}. Engine requires v4.3.0.`);
    }

    let results = exactData || [];

    if (results.length === 0 && tokens.length > 0) {
      const primaryToken = tokens[0];
      const { data: tokenData } = await supabaseClient
        .from('sanctions')
        .select('*')
        .or(`first_name.ilike.%${primaryToken}%,last_name.ilike.%${primaryToken}%,aliases::text.ilike.%${primaryToken}%`)
        .limit(100);

      if (tokenData) {
        results = tokenData.filter((row: any) => {
          const fullRowText = `${row.first_name} ${row.second_name} ${row.third_name} ${row.last_name} ${JSON.stringify(row.aliases)} ${row.comments}`.toUpperCase();
          return tokens.every(t => fullRowText.includes(t));
        });
      }
    }

    return results.map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: String(row.first_name ?? ''),
      secondName: String(row.second_name ?? ''),
      thirdName: String(row.third_name ?? ''),
      lastName: String(row.last_name ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? ''),
      listedOn: String(row.listed_on ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? ''),
      unListType: String(row.un_list_type ?? ''),
      comments: String(row.comments ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e: any) { 
    throw e;
  }
};

