export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) throw new Error("Registry server unreachable.");
  const screenedClient = await screenEntityAgainstDb(client, client.created_by || 'SYSTEM');
  const dbClient = {
    id: screenedClient.id,
    client_name: screenedClient["Client Name"],
    company_nationality: screenedClient["Company Nationality"],
    qfc_no: screenedClient["QFC No"],
    legal_structure: screenedClient["Legal Structure"],
    file_no: screenedClient["No"],
    email: screenedClient["E Mail"],
    address: screenedClient["Registered Address"],
    kyc_status: screenedClient.kyc_status || KYCStatus.DRAFT,
    risk_level: screenedClient.riskLevel || RiskLevel.NONE,
    entity_type: screenedClient.entity_type || EntityType.CORPORATE,
    created_at: screenedClient.created_at || new Date().toISOString(),
    created_by: screenedClient.created_by || "SYSTEM",
    last_screened_at: screenedClient.lastScreenedAt,
    matches: screenedClient.matches || [],
    status: screenedClient["Status"] || "Active",
    services_provided: screenedClient["Services Provided"] || [],
    engagement_year: screenedClient["Engagement Year"],
    engagement_date: cleanDate(screenedClient["Engagement Date"]),
    onboarding_date: cleanDate(screenedClient["Onboarding Date"]),
    qfc_incorp_date: cleanDate(screenedClient["Date of QFC Incorporation or Registration"]),
    cr_expiry_date: cleanDate(screenedClient["CR Expired date"]),
    entity_card_no: screenedClient["Entity Card No"],
    entity_card_expiry: cleanDate(screenedClient["Entity Card Expiry"]),
    license: screenedClient["License"],
    license_expiry: cleanDate(screenedClient["License Expiry"]),
    nature_of_business: screenedClient["Nature of Business"],
    telephone_number: screenedClient["Telephone Number"],
    website: screenedClient["Website"],
    directors_names: screenedClient["Directors Names"] || [],
    shareholders: screenedClient["Significant Shareholders"] || [],
    ubo_details: screenedClient["UBO Details"] || [],
    signatories: screenedClient["Authorized Signatory"] || [],
    secretary: screenedClient["Secretary"],
    sef: screenedClient["Senior Executive Function"],
    auditor: screenedClient["Approved Auditor"],
    company_type: screenedClient["Company Type"]
  };
  const { error } = await supabaseClient.from('clients').upsert([dbClient], { onConflict: 'id' });
  if (error) throw new Error(extractError(error));
};

