 * ENGINE-LOCK VALIDATION v4.3.1
 * Verifies that the database schema exactly matches the engine expectations.
 */
export const validateRegistrySchemaV431 = async (): Promise<{ success: boolean; error?: string }> => {
  if (!supabaseClient) return { success: false, error: 'Database client uninitialized' };

  try {
    const { data: versionData, error: verError } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'schema_version')
      .single();

    if (verError) {
      return { success: false, error: `Metadata table unreachable: ${verError.message}` };
    }

    if (!versionData || versionData.value.version !== REQUIRED_ENGINE_VERSION) {
      return { 
        success: false, 
        error: `Engine v4.3.1 requires Registry v4.3.1. Found: ${versionData?.value?.version || 'Unknown Legacy'}` 
      };
    }

    // Verify 'sanctions' columns to ensure 23502 won't occur
    const { error: sancCheck } = await supabaseClient
      .from('sanctions')
      .select('data_id, first_name, source, un_list_type, listed_on')
      .limit(1);

    if (sancCheck) {
      return { success: false, error: `Sanctions table schema drift: ${sancCheck.message}` };
    }

    return { success: true };
  } catch (e: any) {
    return { success: false, error: e.message };
  }
};

