const extractError = (err: any): string => {
  if (!err) return "Unknown Error";
  if (typeof err === 'string') return err;

  // High-fidelity mapping for Postgres Error 23502 (NOT NULL violation)
  if (err.code === '23502') {
    const col = err.column || 'unknown';
    const tbl = err.table || 'sanctions';
    return `STRUCTURAL_INTEGRITY_FAULT: Column '${col}' in table '${tbl}' rejected the operation due to a NULL value constraint. RESOLUTION: Run v4.3.1 Reconciliation script to apply missing defaults to existing columns.`;
  }

  return err.message || err.details || JSON.stringify(err);
};

