const extractError = (err: any): string => {
  if (!err) return "Unknown Error";
  if (typeof err === 'string') return err;

  // High-fidelity mapping for Postgres Error 23502 (NOT NULL violation)
  if (err.code === '23502') {
    let col = err.column;
    // Attempt to extract from details if column name is hidden in the driver object
    if (!col && err.details) {
      const match = err.details.match(/column "(.+)" violates/);
      if (match) col = match[1];
    }
    const colName = col || 'unknown';
    const tbl = err.table || 'sanctions';
    return `STRUCTURAL_INTEGRITY_FAULT: Column '${colName}' in table '${tbl}' rejected the operation due to a NULL value constraint. RESOLUTION: Run v4.3.1 Reconciliation script in Governance tab to synchronize defaults.`;
  }

  return err.message || err.details || JSON.stringify(err);
};

const cleanDate = (val: any) => {
  if (!val || val === "" || val === "undefined" || val === "null") return null;
  return String(val);
};

