  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const SQL_SCHEMA = `-- v4.3.1 Enterprise Master Reconciliation Script (FORCE ENGINE LOCK)
-- PURPOSE: Force defaults on all NOT NULL columns to eliminate Code 23502 (Upsert Abort).

-- 1. Table Lockdown & Legacy Cleanup
ALTER TABLE IF EXISTS public.sanctions DISABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    -- Rename legacy ID column to data_id if data_id is missing
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='id') 
       AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='data_id') THEN
        ALTER TABLE public.sanctions RENAME COLUMN id TO data_id;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='sanctions') THEN
        CREATE TABLE public.sanctions (data_id TEXT PRIMARY KEY);
    END IF;
END $$;

-- 2. Purge Duplicates that block Primary Key enforcement
DELETE FROM public.sanctions WHERE data_id IS NULL OR data_id = '';
DELETE FROM public.sanctions a USING public.sanctions b 
WHERE a.ctid > b.ctid AND a.data_id = b.data_id;

-- 3. Comprehensive Column Reconciliation (DEFAULT Enforcement)
DO $$
DECLARE
    col_name TEXT;
    target_cols TEXT[] := ARRAY[
        'first_name', 'second_name', 'third_name', 'last_name', 
        'source', 'un_list_type', 'reference_number', 'listed_on', 
        'comments', 'nationality', 'date_of_birth', 'type'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS %I TEXT DEFAULT %L', col_name, '');
        EXECUTE format('UPDATE public.sanctions SET %I = %L WHERE %I IS NULL', col_name, '', col_name);
        EXECUTE format('ALTER TABLE public.sanctions ALTER COLUMN %I SET NOT NULL', col_name);
        EXECUTE format('ALTER TABLE public.sanctions ALTER COLUMN %I SET DEFAULT %L', col_name, '');
    END LOOP;
END $$;

-- 4. Modality Alignment (JSONB Aliases)
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='aliases') THEN
        BEGIN
            ALTER TABLE public.sanctions ALTER COLUMN aliases TYPE JSONB USING aliases::JSONB;
        EXCEPTION WHEN OTHERS THEN
            ALTER TABLE public.sanctions DROP COLUMN aliases;
            ALTER TABLE public.sanctions ADD COLUMN aliases JSONB DEFAULT '[]'::jsonb;
        END;
    ELSE
        ALTER TABLE public.sanctions ADD COLUMN aliases JSONB DEFAULT '[]'::jsonb;
    END IF;
    UPDATE public.sanctions SET aliases = '[]'::jsonb WHERE aliases IS NULL;
    ALTER TABLE public.sanctions ALTER COLUMN aliases SET NOT NULL;
    ALTER TABLE public.sanctions ALTER COLUMN aliases SET DEFAULT '[]'::jsonb;
END $$;

-- 5. Constraint Hardening
ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS fetch_date TIMESTAMPTZ DEFAULT now();
UPDATE public.sanctions SET fetch_date = now() WHERE fetch_date IS NULL;
ALTER TABLE public.sanctions ALTER COLUMN fetch_date SET NOT NULL;

DO $$
DECLARE
    const_name TEXT;
BEGIN
    FOR const_name IN (
        SELECT constraint_name 
        FROM information_schema.table_constraints 
        WHERE table_name='sanctions' AND constraint_type IN ('PRIMARY KEY', 'UNIQUE')
    ) LOOP
        EXECUTE 'ALTER TABLE public.sanctions DROP CONSTRAINT IF EXISTS ' || quote_ident(const_name) || ' CASCADE';
    END LOOP;
END $$;

ALTER TABLE public.sanctions ADD PRIMARY KEY (data_id);
CREATE UNIQUE INDEX IF NOT EXISTS sanctions_data_id_idx ON public.sanctions (data_id);

-- 6. Engine Version Lock (CRITICAL)
CREATE TABLE IF NOT EXISTS public.system_metadata (key TEXT PRIMARY KEY, value JSONB DEFAULT '{}'::jsonb);
INSERT INTO public.system_metadata (key, value) 
VALUES ('schema_version', jsonb_build_object('version', '4.3.1', 'updated_at', now()))
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

NOTIFY pgrst, 'reload schema';`;

  const copySql = () => {
