export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const queryStr = name.trim().toUpperCase();

  try {
    let { data, error } = await supabaseClient
      .from('sanctions')
      .select('*')
      .or(`first_name.ilike.%${queryStr}%,last_name.ilike.%${queryStr}%,comments.ilike.%${queryStr}%,aliases::text.ilike.%${queryStr}%`)
      .limit(50);

    if (error) {
      throw new Error(`REGISTRY_QUERY_FAULT: ${extractError(error)}`);
    }

    return (data || []).map((row: any) => ({
      dataId: String(row.data_id ?? row.dataId ?? row.id ?? ''),
      firstName: String(row.first_name ?? row.firstName ?? ''),
      secondName: String(row.second_name ?? row.secondName ?? ''),
      thirdName: String(row.third_name ?? row.thirdName ?? ''),
      lastName: String(row.last_name ?? row.lastName ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? row.referenceNumber ?? ''),
      listedOn: String(row.listed_on ?? row.listedOn ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? row.dateOfBirth ?? ''),
      unListType: String(row.un_list_type ?? row.unListType ?? ''),
      comments: String(row.comments ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: String(row.type || 'Individual'),
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e: any) { 
    throw e;
  }
};

