              <div className="bg-slate-900 p-8 rounded-3xl text-white shadow-2xl space-y-4 font-mono text-[10px] overflow-hidden relative border border-white/5">
                 <div className="flex justify-between items-center text-emerald-400 border-b border-white/5 pb-4 mb-4">
                    <span className="flex items-center gap-2 uppercase tracking-widest"><Terminal size={14}/> SYSTEM_DIAG_V4.3.1</span>
                    <span className="bg-emerald-500/10 px-2 py-0.5 rounded uppercase font-black">Active</span>
                 </div>
                 <div className="space-y-2 opacity-80">
                    <p className="text-emerald-300"># Initializing Compliance Engine v4.3.1...</p>
                    <p className="text-slate-400">Loading Fuzzy Matrix [SIMILARITY_LEVENSHTEIN]</p>
                    <p className="text-slate-400">Handshake: SUCCESS [Supabase-PostgREST]</p>
                    <p className="text-slate-400">PK Enforcement: ACTIVE [data_id]</p>
                    <p className="text-emerald-400 font-black">Node Status: AUTHORITATIVE_READ_WRITE</p>
                    <p className="text-slate-500 mt-4">--- SYSTEM REPORT ---</p>
                    <p className="text-slate-400">Memory Pressure: NOMINAL</p>
                    <p className="text-slate-400">Ingestion Pipeline: READY</p>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'logs' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex items-center gap-3 border-b border-gray-50 pb-6">
