const extractError = (err: any): string => {
  if (!err) return "Unknown Error";
  if (typeof err === 'string') return err;

  // High-fidelity mapping for Postgres Error 23502 (NOT NULL violation)
  if (err.code === '23502') {
    let col = err.column;
    const searchString = `${err.message || ''} ${err.details || ''} ${err.hint || ''}`;
    const colMatch = searchString.match(/column "(.+?)"/i);
    if (!col && colMatch) col = colMatch[1];

    const colName = col || 'unknown';
    const tbl = err.table || 'sanctions';

    if (colName.toLowerCase().includes('dataid')) {
        return `STRUCTURAL_INTEGRITY_FAULT: Redundant case-sensitive column 'dataId' detected in table '${tbl}'. This column must be merged into 'data_id'. RESOLUTION: Run v4.3.1 Reconciliation script in Governance tab.`;
    }

    return `STRUCTURAL_INTEGRITY_FAULT: Column '${colName}' in table '${tbl}' rejected the operation due to a NULL value constraint. RESOLUTION: Run v4.3.1 Reconciliation script in Governance tab to synchronize schema mapping.`;
  }

  return err.message || err.details || JSON.stringify(err);
};

const cleanDate = (val: any) => {
  if (!val || val === "" || val === "undefined" || val === "null") return null;
  return String(val);
};

