 * Replaces uncontrolled process termination with deterministic structural diagnostics.
 */
export const validateRegistrySchemaV431 = async (): Promise<{ success: boolean; error?: string; discrepancies: string[] }> => {
  if (!supabaseClient) return { success: false, error: 'Supabase client uninitialized', discrepancies: ['No active database connection'] };

  const discrepancies: string[] = [];

  try {
    // 1. Version Compliance Check
    const { data: verData, error: verErr } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'schema_version')
      .single();

    if (verErr || !verData || verData.value.version !== REQUIRED_ENGINE_VERSION) {
      discrepancies.push(`Registry Version Conflict: Application requires v${REQUIRED_ENGINE_VERSION}, but database is at v${verData?.value?.version || 'Legacy/Unversioned'}.`);
    }

    // 2. Sanctions Column Audit (v4.3.1 Comprehensive Set)
    const requiredColumns = [
      'data_id', 'first_name', 'second_name', 'third_name', 'last_name', 'source', 
      'un_list_type', 'reference_number', 'listed_on', 
      'comments', 'nationality', 'date_of_birth', 'aliases', 'fetch_date', 'type'
    ];

    const { error: sancErr } = await supabaseClient
      .from('sanctions')
      .select(requiredColumns.join(','))
      .limit(0);

    if (sancErr) {
      discrepancies.push(`Registry Schema Drift: Sanctions table is missing one or more v4.3.1 required columns: ${sancErr.message}`);
    }

    // 3. Metadata Table Check
    const { error: metaErr } = await supabaseClient.from('system_metadata').select('key').limit(0);
    if (metaErr) discrepancies.push('Auxiliary Metadata table is missing or corrupted.');

    return { 
      success: discrepancies.length === 0, 
      discrepancies 
    };
  } catch (e: any) {
    return { success: false, error: `Critical Structural Audit Failure: ${e.message}`, discrepancies: [e.message] };
  }
};

