/**
 * AUTHORITATIVE SEARCH V4.3.2
 * Uses multi-token heuristic to find entities like 'AEROCARIBBEAN AIRLINES' even 
 * if parts of the name are split across columns or containing noisy fragments.
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const queryStr = name.trim().toUpperCase();
  const tokens = queryStr.split(/\s+/).filter(t => t.length >= 2);

  try {
    // Primary strategy: Exact phrase match across all major text columns
    let query = supabaseClient.from('sanctions').select('*');

    const filterParts = [
      `first_name.ilike.%${queryStr}%`,
      `last_name.ilike.%${queryStr}%`,
      `comments.ilike.%${queryStr}%`,
      `reference_number.ilike.%${queryStr}%`,
      `data_id.ilike.%${queryStr}%`,
      `aliases::text.ilike.%${queryStr}%`
    ];

    // If query is multi-word, also try matching the first token and second token separately
    if (tokens.length >= 2) {
      filterParts.push(`first_name.ilike.%${tokens[0]}%`);
      filterParts.push(`last_name.ilike.%${tokens[0]}%`);
    }

    const { data, error } = await query.or(filterParts.join(',')).limit(100);

    if (error) throw new Error(`REGISTRY_QUERY_FAULT: ${extractError(error)}`);

    return (data || []).map((row: any) => ({
      dataId: String(row.data_id ?? row.dataId ?? row.id ?? ''),
      firstName: String(row.first_name ?? row.firstName ?? ''),
      secondName: String(row.second_name ?? row.secondName ?? ''),
      thirdName: String(row.third_name ?? row.thirdName ?? ''),
      lastName: String(row.last_name ?? row.lastName ?? ''),
      source: String(row.source || 'Master Registry'),
      referenceNumber: String(row.reference_number ?? row.referenceNumber ?? ''),
      listedOn: String(row.listed_on ?? row.listedOn ?? ''),
      nationality: String(row.nationality ?? ''),
      dateOfBirth: String(row.date_of_birth ?? row.dateOfBirth ?? ''),
      unListType: String(row.un_list_type ?? row.unListType ?? ''),
      comments: String(row.comments ?? ''),
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: String(row.type || 'Individual'),
      fetchDate: row.fetch_date || ''
    } as SanctionEntry));
  } catch (e: any) { 
    throw e;
  }
};

