const extractError = (err: any): string => {
  if (!err) return "Unknown Error";
  if (typeof err === 'string') return err;

  // Specific catch for missing column error in Supabase/PostgREST
  if (err.message && err.message.includes('column') && err.message.includes('not found')) {
      return `STRUCTURAL_INTEGRITY_FAULT: Database column '${err.message.split("'")[1]}' missing. RESOLUTION: Execute v4.3.3 Reconciliation Script in Governance tab.`;
  }

  return err.message || err.details || JSON.stringify(err);
};

const computeHash = async (data: any): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(JSON.stringify(data));
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

