-- PURPOSE: Ensure schema accepts literal NULLs from source files per Immutability Policy v4.3.4.

-- 1. Table Lockdown & Legacy Cleanup
ALTER TABLE IF EXISTS public.sanctions DISABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    -- HANDLE CASE-SENSITIVE COLLISION
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='dataId') THEN
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='data_id') THEN
            ALTER TABLE public.sanctions RENAME COLUMN "dataId" TO data_id;
        ELSE
            UPDATE public.sanctions SET data_id = "dataId" WHERE data_id IS NULL OR data_id = '';
            ALTER TABLE public.sanctions DROP COLUMN "dataId";
        END IF;
    END IF;

    -- Create table if missing
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='sanctions') THEN
        CREATE TABLE public.sanctions (data_id TEXT PRIMARY KEY);
    END IF;
END $$;

-- 2. Purge Duplicates & Identity Hazards
DELETE FROM public.sanctions WHERE data_id IS NULL OR data_id = '';

-- 3. Comprehensive Column Reconciliation (Removing Constraints to allow RAW NULLS)
DO $$
DECLARE
    col_name TEXT;
    target_cols TEXT[] := ARRAY[
        'first_name', 'second_name', 'third_name', 'last_name', 
        'source', 'un_list_type', 'reference_number', 'listed_on', 
        'comments', 'nationality', 'date_of_birth', 'type', 'integrity_hash'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS %I TEXT', col_name);
        -- REMOVE NOT NULL: Schema must accept file as-is, including NULL values.
        EXECUTE format('ALTER TABLE public.sanctions ALTER COLUMN %I DROP NOT NULL', col_name);
        -- REMOVE DEFAULT: Default values are considered data mutation.
        EXECUTE format('ALTER TABLE public.sanctions ALTER COLUMN %I DROP DEFAULT', col_name);
