/**
 * IMMUTABLE UPSERT POLICY V4.3.5
 * Logic: Authoritative Replace Mode.
 * Ensures strict newer-than check before destructive overwrite.
 */
export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void, replace: boolean = false) => {
  if (!supabaseClient) throw new Error("Registry offline.");
  const total = sanctions.length;
  if (total === 0) return;

  // 1. REGRESSION GUARD: Only replace if new batch is strictly newer than existing data
  if (replace) {
    const { data: latestRecord, error: fetchErr } = await supabaseClient
      .from('sanctions')
      .select('fetch_date')
      .order('fetch_date', { ascending: false })
      .limit(1)
      .single();

    if (!fetchErr && latestRecord && sanctions[0].fetchDate) {
      if (new Date(sanctions[0].fetchDate) <= new Date(latestRecord.fetch_date)) {
         throw new Error("REGRESSION_GUARD: Injected dataset is not newer than current registry. Operation aborted.");
      }
    }

    // 2. AUTHORITATIVE PURGE: Delete all records to prevent duplication during refresh
    const { error: deleteErr } = await supabaseClient.from('sanctions').delete().neq('data_id', '_none_');
    if (deleteErr) throw new Error(`PURGE_FAILURE: ${extractError(deleteErr)}`);
  }

  for (let i = 0; i < total; i += 200) {
    const rawBatch = sanctions.slice(i, i + 200);
    const preHash = await computeHash(rawBatch);

    const batch = rawBatch.map(s => ({
      data_id: s.dataId,
      first_name: s.firstName,
      second_name: s.secondName,
      third_name: s.thirdName,
      last_name: s.lastName,
      source: s.source,
      reference_number: s.referenceNumber,
      listed_on: s.listedOn,
      nationality: s.nationality,
      date_of_birth: s.dateOfBirth,
      un_list_type: s.unListType,
      comments: s.comments,
      type: s.type,
      aliases: s.aliases,
      fetch_date: s.fetchDate,
      integrity_hash: preHash,
      raw_payload: JSON.stringify(s) // Byte-for-byte preservation
    }));

    const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });

    if (error) {
      throw new Error(`IMMUTABILITY_VIOLATION: ${extractError(error)}`);
    }

    if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
  }
};

