                       <tr key={log.id} className="text-[11px]">
                          <td className="px-4 py-4 text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                          <td className="px-4 py-4 font-bold text-slate-800">{log.details}</td>
                          <td className="px-4 py-4 font-black uppercase text-emerald-700">{log.triggeredBy}</td>
                       </tr>
                    ))}
                    {logs.length === 0 && (
                       <tr>
                          <td colSpan={3} className="py-20 text-center text-slate-300 font-black uppercase tracking-widest text-[10px]">No recent audit trails</td>
                       </tr>
                    )}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase">Provision Identity</h3>
                 <button onClick={() => setIsUserModalOpen(false)} className="p-2 bg-white/10 rounded-full"><X size={20}/></button>
              </div>
              <form onSubmit={handleCreateUser} className="p-8 space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                    <input required className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserName} onChange={e => setNewUserName(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Corporate Email</label>
                    <input required type="email" className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserEmail} onChange={e => setNewUserEmail(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Access Role</label>
                    <select className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold outline-none" value={newUserRole} onChange={e => setNewUserRole(e.target.value as UserRole)}>
                       <option value={UserRole.DATA_ENTRY}>Data Entry Officer</option>
                       <option value={UserRole.REVIEWER}>Compliance Reviewer</option>
                       <option value={UserRole.ADMIN}>Compliance Manager</option>
                       <option value={UserRole.REPORTING}>Reporting User</option>
                       <option value={UserRole.AUDITOR}>Audit Viewer</option>
                    </select>
                 </div>
                 <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl">
                    <input type="checkbox" className="h-4 w-4 rounded border-slate-300 text-emerald-800 focus:ring-emerald-800" checked={isNewUserAdmin} onChange={e => setIsNewUserAdmin(e.target.checked)} />
                    <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Elevated System Admin Privileges</label>
                 </div>
                 <button type="submit" disabled={isSyncing} className="w-full py-5 bg-emerald-800 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-xl hover:bg-emerald-900 transition-all flex items-center justify-center gap-3">
                    {isSyncing ? <Loader2 className="animate-spin" size={20}/> : <Shield size={20}/>}
                    Commit to Registry
                 </button>
              </form>
           </div>
        </div>
      )}

      {pendingDeleteUser && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] p-8 max-sm w-full shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center text-red-600 mx-auto mb-6">
                 <Trash2 size={32} />
              </div>
              <h3 className="text-lg font-black text-slate-900 uppercase tracking-tight mb-2">Delete User?</h3>
              <p className="text-xs text-slate-500 font-bold mb-8 uppercase leading-relaxed">
                 Are you sure you want to remove <span className="text-red-600">{pendingDeleteUser.full_name}</span>? Access will be immediately revoked.
              </p>
              <div className="flex gap-3">
                 <button onClick={() => setPendingDeleteUser(null)} className="flex-1 py-4 bg-slate-50 text-slate-400 font-black text-[10px] uppercase rounded-xl tracking-widest">Cancel</button>
                 <button onClick={confirmDeleteUser} disabled={isSyncing} className="flex-1 py-4 bg-red-600 text-white font-black text-[10px] uppercase rounded-xl tracking-widest flex items-center justify-center gap-2">
                    {isSyncing ? <Loader2 className="animate-spin" size={14}/> : 'Confirm Delete'}
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry, EntityType, SystemEnvironment, IngestionLog, UserRole } from '../types';
import { 
  RefreshCw, Search, ChevronLeft, ChevronRight, Database, Activity, 
  AlertCircle, Loader2, Play, Pause, Trash2, Clock, 
  ShieldCheck, CloudDownload, Cpu, CheckCircle, Zap, Upload, FileText, 
  Globe, ShieldAlert, FileJson, Info, ExternalLink, Terminal, BarChart3, ListChecks,
  History, Settings, FileWarning, ArrowUpRight, Check, Map, Layers, FileSpreadsheet,
  X, AlertTriangle, ArrowRightLeft, Shield
} from 'lucide-react';
import { 
  fetchSanctionsBatch, 
  fetchSanctionsTotalCount, 
  upsertCloudSanctions, 
  setGlobalSyncLock, 
  logIngestionEvent,
  fetchIngestionLogs,
  searchSanctionsAuthoritative
} from '../services/cloudDb';
import { 
  fetchAndNormalize,
  detectFormat,
  parseUNSanctionsXML, 
  parseCSVToSanctions, 
  parseExcelToSanctions,
  mapFieldsToSanction,
  OFFICIAL_UN_XML_URL, 
  QATAR_NCTC_URL, 
  OPENSANCTIONS_URL 
} from '../services/unSanctionsService';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[], stats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string }) => void;
  isCloudConnected: boolean;
  initialStats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string };
  isGlobalSyncing?: boolean;
  environment?: SystemEnvironment;
  currentUser?: { role: UserRole; id: string };
}

type ProcessStatus = 'IDLE' | 'FETCHING' | 'VALIDATING' | 'MAPPING' | 'UPLOADING' | 'COMPLETED' | 'ERROR';

const ITEMS_PER_PAGE = 15;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, initialStats, isGlobalSyncing, environment, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'hub' | 'audit'>('hub');
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successReport, setSuccessReport] = useState<{source: string, count: number, method: string, newRecords: number, updatedRecords: number} | null>(null);
  const [ingestionHistory, setIngestionHistory] = useState<IngestionLog[]>([]);

  // Mapping State
  const [rawUploadData, setRawUploadData] = useState<any[]>([]);
  const [currentMapping, setCurrentMapping] = useState<Record<string, string>>({
    dataId: '', firstName: '', lastName: '', unListType: '', referenceNumber: '', listedOn: '', comments: '', nationality: '', type: '', dateOfBirth: ''
  });
  const [mappingSource, setMappingSource] = useState<string>('');

  const [lastSourceUpdate, setLastSourceUpdate] = useState<string>(initialStats?.lastSourceUpdate || 'Never');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const refreshDbStats = useCallback(async () => {
    if (isCloudConnected) {
      try {
        const count = await fetchSanctionsTotalCount();
        setTotalInDb(count);
        const logs = await fetchIngestionLogs();
        setIngestionHistory(logs);

        // Initial load of the most recent records
        const initialBatch = await fetchSanctionsBatch(0, 500);
        setSanctions(initialBatch);
        return count;
      } catch (e) { return 0; }
    }
    return 0;
  }, [isCloudConnected]);

  useEffect(() => {
    const handler = setTimeout(async () => {
      const term = searchTerm.trim();
      if (term.length >= 2) {
        setIsSearching(true);
        try {
          const results = await searchSanctionsAuthoritative(term);
          setSanctions(results || []);
          setCurrentPage(1);
        } catch (err) {
          console.error("Authoritative search failed", err);
        } finally {
          setIsSearching(false);
        }
      } else if (term.length === 0) {
        refreshDbStats();
      }
    }, 400);

    return () => clearTimeout(handler);
  }, [searchTerm, refreshDbStats]);

  useEffect(() => {
    refreshDbStats();
  }, [refreshDbStats]);

  const handleFileSelection = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isCloudConnected) return;
    setStatus('VALIDATING');
    setErrorMessage(null);
    setSuccessReport(null);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result;
        const format = detectFormat(typeof content === 'string' ? content : '', file.name);
        let parsedRows: any[] = [];
        if (format === 'EXCEL') parsedRows = parseExcelToSanctions(content as ArrayBuffer, file.name);
        else if (format === 'CSV') parsedRows = parseCSVToSanctions(content as string, file.name);
        else if (format === 'JSON') {
           const data = JSON.parse(content as string);
           parsedRows = Array.isArray(data) ? data : (data.entities || []);
        } else if (format === 'XML') {
           const finalData = parseUNSanctionsXML(content as string);
           return finalizeIngestion(finalData, "UN XML", "Manual Upload");
        } else throw new Error("Unrecognized data protocol.");

        if (parsedRows.length === 0) throw new Error("Empty dataset detected.");
        setRawUploadData(parsedRows);
        setMappingSource(file.name.split('.')[0].toUpperCase());
        setStatus('MAPPING');
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMessage(err.message);
      }
    };
    if (file.name.match(/\.(xlsx|xls)$/i)) reader.readAsArrayBuffer(file);
    else reader.readAsText(file);
  };

  const finalizeIngestion = async (data: SanctionEntry[], source: string, method: string) => {
    setStatus('UPLOADING');
    setUploadProgress(0);
    try {
      await setGlobalSyncLock(true, `${method}: ${source}...`);
      const count = data.length;

      // Authoritative Replace Mode: true (v4.3.5 Implementation)
      await upsertCloudSanctions(data, (p) => setUploadProgress(p), true);

      const now = new Date().toLocaleString();
      await setGlobalSyncLock(false, now);
      setLastSourceUpdate(now);
      setSuccessReport({ source, count, method, newRecords: 0, updatedRecords: count });
      await logIngestionEvent({
        timestamp: new Date().toISOString(), source, method: 'Manual', status: 'Success',
        recordsProcessed: count, recordsAccepted: count, recordsRejected: 0, triggeredBy: currentUser?.id || 'System'
      });
      await refreshDbStats();
      setStatus('COMPLETED');
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate);
      setErrorMessage(err.message);
      setStatus('ERROR');
    }
  };

  const handleMappingCommit = () => {
    try {
      const normalizedData = rawUploadData.map(row => mapFieldsToSanction(row, currentMapping, mappingSource));
      finalizeIngestion(normalizedData, mappingSource, "Custom Injection");
    } catch (e: any) { setErrorMessage("Mapping configuration invalid: " + e.message); }
  };

  const runAutomatedFetch = async (url: string, name: string) => {
    if (!isCloudConnected || isGlobalSyncing) return;
    setStatus('FETCHING');
    setErrorMessage(null);
    setSuccessReport(null);
    try {
      const data = await fetchAndNormalize(url, name);
      finalizeIngestion(data, name, "Direct Fetch");
    } catch (err: any) {
      setStatus('ERROR');
      setErrorMessage(`Connectivity Fault: ${err.message}`);
    }
  };

  const paginatedData = sanctions.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const totalPages = Math.ceil(sanctions.length / ITEMS_PER_PAGE);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-6 sm:p-8 rounded-[3rem] border border-gray-100 shadow-sm gap-6">
         <div className="flex items-center gap-5">
            <div className="bg-emerald-950 p-4 rounded-3xl text-emerald-400 shadow-xl"><Cpu size={28}/></div>
            <div>
               <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Sanctions Ingestion Hub</h2>
               <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Version 2.9.8 • Consolidated Node</p>
            </div>
         </div>
         <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full md:w-auto">
            <button onClick={() => setActiveTab('hub')} className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${activeTab === 'hub' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>Ingest</button>
            <button onClick={() => setActiveTab('audit')} className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${activeTab === 'audit' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>History</button>
         </div>
      </div>

      {activeTab === 'hub' && (
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
          <div className="xl:col-span-2 space-y-8">
             <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-8">
                <div className="flex items-center justify-between border-b border-gray-50 pb-6">
                   <div className="flex items-center gap-3">
                      <CloudDownload className="text-blue-600" size={20} />
                      <h3 className="text-sm font-black uppercase text-slate-900">Method 1: Direct Integration</h3>
                   </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-5">
                   {[
                     { name: 'UN Security Council', url: OFFICIAL_UN_XML_URL, icon: <Globe />, color: 'bg-blue-600', format: 'XML' },
                     { name: 'Qatar MOI (NCTC)', url: QATAR_NCTC_URL, icon: <Shield />, color: 'bg-amber-600', format: 'HTML' },
                     { name: 'OpenSanctions', url: OPENSANCTIONS_URL, icon: <FileJson />, color: 'bg-emerald-600', format: 'JSON' }
                   ].map(source => (
                     <button key={source.name} onClick={() => runAutomatedFetch(source.url, source.name)} disabled={status !== 'IDLE'} className="group p-6 rounded-[2.5rem] border border-slate-100 hover:border-blue-300 hover:bg-blue-50/30 transition-all flex flex-col items-center text-center gap-4 disabled:opacity-30">
                        <div className={`p-4 rounded-2xl bg-slate-50 text-slate-400 group-hover:${source.color} group-hover:text-white transition-all`}>{source.icon}</div>
                        <h4 className="text-[10px] font-black uppercase text-slate-800 leading-tight">{source.name}</h4>
                     </button>
                   ))}
                </div>
                {errorMessage && (
                  <div className="p-8 bg-red-50 border border-red-100 rounded-[2.5rem] space-y-4">
                     <div className="flex items-start gap-4">
                        <div className="p-3 bg-red-600 text-white rounded-2xl"><AlertTriangle size={20}/></div>
                        <div>
                           <p className="text-[10px] font-black text-red-900 uppercase">Process Interruption Detected</p>
                           <p className="text-xs font-bold text-red-700 mt-1 uppercase leading-relaxed">{errorMessage}</p>
                        </div>
                     </div>
                  </div>
                )}
                {successReport && (
                  <div className="p-8 bg-emerald-50 border border-emerald-100 rounded-[2.5rem] flex items-center gap-4">
                     <CheckCircle className="text-emerald-600" size={32}/>
                     <p className="text-xs font-black text-emerald-900 uppercase">{successReport.count} Records Ingested from {successReport.source}</p>
                  </div>
                )}
             </div>
          </div>
          <div className="space-y-8">
             <div className="bg-slate-950 p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden flex flex-col h-full justify-between border-b-8 border-emerald-500">
                <div className="relative z-10 space-y-6">
                   <div className="flex items-center gap-3">
                      <div className="bg-emerald-500/20 p-2.5 rounded-xl"><Upload className="text-emerald-400" size={20} /></div>
                      <h3 className="text-sm font-black uppercase tracking-widest">Method 2: Local Injection</h3>
                   </div>
                   <input type="file" ref={fileInputRef} onChange={handleFileSelection} className="hidden" />
                   <button onClick={() => fileInputRef.current?.click()} disabled={status !== 'IDLE'} className="w-full py-5 bg-white text-slate-950 rounded-[1.5rem] font-black text-[11px] uppercase tracking-[0.2em] flex items-center justify-center gap-3">
                      <Layers size={18} /> Select File
                   </button>
                   {status === 'UPLOADING' && (
                     <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden mt-4">
                        <div className="h-full bg-emerald-400 transition-all duration-300" style={{ width: `${uploadProgress}%` }} />
                     </div>
                   )}
                </div>
             </div>
          </div>
        </div>
      )}

      {status === 'MAPPING' && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[200] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] w-full max-w-4xl shadow-2xl overflow-hidden flex flex-col h-[85vh]">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center shrink-0">
                 <h3 className="text-xl font-black uppercase">Schema Alignment</h3>
                 <button onClick={() => setStatus('IDLE')} className="p-3 bg-white/10 rounded-full"><X size={24}/></button>
              </div>
              <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8 bg-gray-50/50">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {Object.keys(currentMapping).map(field => (
                       <div key={field} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm space-y-2">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{field}</label>
                          <select value={currentMapping[field]} onChange={(e) => setCurrentMapping({...currentMapping, [field]: e.target.value})} className="w-full bg-slate-50 rounded-xl py-3 px-4 text-xs font-bold">
                             <option value="">-- No Mapping --</option>
                             {Object.keys(rawUploadData[0] || {}).map(col => <option key={col} value={col}>{col}</option>)}
                          </select>
                       </div>
                    ))}
                 </div>
              </div>
              <div className="p-8 border-t bg-white flex justify-end gap-3 shrink-0">
                 <button onClick={handleMappingCommit} className="px-12 py-4 bg-emerald-800 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em]">Commit Ingestion</button>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'audit' && (
        <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-8 animate-in slide-in-from-right-4 duration-500">
           <h3 className="text-lg font-black text-slate-900 uppercase">Access Logs</h3>
           <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[900px]">
                 <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                    <tr><th className="px-6 py-5">Timestamp</th><th className="px-6 py-5">Source</th><th className="px-6 py-5">Status</th><th className="px-6 py-5 text-right">Records</th></tr>
                 </thead>
                 <tbody className="divide-y divide-slate-50">
                    {ingestionHistory.map(log => (
                       <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                          <td className="px-6 py-5 text-xs font-bold text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                          <td className="px-6 py-5 font-black text-slate-900 text-sm">{log.source}</td>
                          <td className="px-6 py-5"><span className={`px-2 py-1 text-[8px] font-black uppercase rounded-md ${log.status === 'Success' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>{log.status}</span></td>
                          <td className="px-6 py-5 text-right text-xs font-black text-slate-900">{log.recordsProcessed} Hits</td>
                       </tr>
                    ))}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      <div className="space-y-6">
         <div className="bg-white p-4 rounded-[2.5rem] shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 w-full">
               <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20}/>
               <input 
                 type="text" 
                 placeholder="Search Authoritative Master Cache (e.g. AEROCARIBBEAN AIRLINES)..." 
                 className="w-full pl-16 pr-12 py-5 bg-gray-50/50 rounded-[2rem] border-none outline-none text-xs font-bold focus:ring-2 focus:ring-emerald-800 transition-all" 
                 value={searchTerm} 
                 onChange={(e) => setSearchTerm(e.target.value)} 
               />
               {isSearching && <Loader2 className="absolute right-6 top-1/2 -translate-y-1/2 animate-spin text-emerald-800" size={20}/>}
            </div>
            <div className="px-6 py-3 rounded-2xl bg-emerald-50 border border-emerald-100 flex items-center gap-3 whitespace-nowrap">
               <Database className="text-emerald-800" size={16}/>
               <div className="flex flex-col">
                  <span className="text-[10px] font-black text-emerald-800 uppercase tracking-widest leading-none">Total Registry</span>
                  <span className="text-xs font-black text-emerald-950 mt-0.5">{totalInDb.toLocaleString()} Synchronized Identities</span>
               </div>
            </div>
         </div>
         <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
            <div className="overflow-x-auto custom-scrollbar">
               <table className="w-full text-left min-w-[1000px]">
                  <thead className="bg-gray-50/50 border-b">
                     <tr><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">First Name</th><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Last Name</th><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Nationality</th><th className="px-10 py-7 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Authority</th></tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                     {paginatedData.map(entry => (
                        <tr key={entry.dataId} className="hover:bg-emerald-50/20 transition-colors group">
                           <td className="px-10 py-6 font-black text-slate-950 text-sm uppercase">{entry.firstName}</td>
                           <td className="px-10 py-6 font-black text-slate-950 text-sm uppercase">{entry.lastName}</td>
                           <td className="px-10 py-6 font-black text-[10px] text-slate-600 uppercase tracking-widest">{entry.nationality || 'N/A'}</td>
                           <td className="px-10 py-6 text-right"><span className="px-3 py-1 text-[8px] font-black uppercase border border-slate-100 text-slate-400 bg-white group-hover:text-emerald-800 transition-all">{entry.source}</span></td>
                        </tr>
                     ))}
                     {paginatedData.length === 0 && !isSearching && (
                       <tr>
                         <td colSpan={4} className="py-24 text-center">
                            <div className="flex flex-col items-center gap-4">
                               <div className="p-4 bg-gray-50 rounded-full"><Search size={40} className="text-gray-200"/></div>
                               <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">No records found in authoritative cache</p>
                               <p className="text-[9px] font-bold text-gray-300 uppercase tracking-widest">Spelling Mismatch? Try a broader search term.</p>
                            </div>
                         </td>
                       </tr>
                     )}
                  </tbody>
               </table>
            </div>
            {sanctions.length > ITEMS_PER_PAGE && (
              <div className="px-10 py-6 border-t border-gray-100 flex justify-between items-center bg-gray-50/30">
                 <div className="text-[10px] font-black text-gray-400 uppercase">Page {currentPage} of {totalPages}</div>
                 <div className="flex gap-2">
                    <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="p-2 border rounded-xl bg-white hover:bg-gray-50 disabled:opacity-30"><ChevronLeft size={18}/></button>
                    <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="p-2 border rounded-xl bg-white hover:bg-gray-50 disabled:opacity-30"><ChevronRight size={18}/></button>
                 </div>
              </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default SanctionsRegistry;

import React, { useState } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus, SystemEnvironment } from '../types';
import { Plus, Power, Trash2, Shield, Copy, Check, Users, ShieldAlert, History, Beaker, Zap, Terminal, X, Loader2 } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'users' | 'engine' | 'logs'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);
  const [copiedSql, setCopiedSql] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const SQL_SCHEMA = `-- v4.3.6 Enterprise Master Reconciliation Script (CLIENTS + SANCTIONS)
-- PURPOSE: Enforce structural alignment for the Corporate Registry and Sanctions Master.

-- 1. Table Lockdown & Legacy Cleanup
ALTER TABLE IF EXISTS public.sanctions DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.clients DISABLE ROW LEVEL SECURITY;

-- 2. Clients Table Provisioning (Authoritative Schema)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='clients') THEN
        CREATE TABLE public.clients (id TEXT PRIMARY KEY);
    END IF;
END $$;

DO $$
DECLARE
    col_name TEXT;
    -- Note: Quoted identifiers are required for names with spaces/caps in Postgres
    target_cols TEXT[] := ARRAY[
        'No', 'Status', 'QFC No', 'Legal Structure', 'Company Nationality',
        'Client Name', 'Engagement Year', 'Engagement Date', 'Onboarding Date',
        'Date of QFC Incorporation or Registration', 'CR Expired date',
        'Entity Card No', 'Entity Card Expiry', 'License', 'License Expiry',
        'Nature of Business', 'Registered Address', 'Telephone Number', 
        'E Mail', 'Website', 'Secretary', 'Senior Executive Function',
        'Approved Auditor', 'Company Type', 'created_by', 'kyc_status',
        'riskLevel', 'entity_type', 'lastScreenedAt'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS %I TEXT', col_name);
    END LOOP;
END $$;

-- 3. Clients JSONB Complexity Alignment
DO $$
DECLARE
    col_name TEXT;
    json_cols TEXT[] := ARRAY[
        'Services Provided', 'Directors Names', 'Significant Shareholders', 
        'UBO Details', 'Authorized Signatory', 'matches'
    ];
BEGIN
    FOREACH col_name IN ARRAY json_cols
    LOOP
        -- Add as JSONB if missing, or convert if existing
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='clients' AND column_name=col_name) THEN
            EXECUTE format('ALTER TABLE public.clients ADD COLUMN %I JSONB DEFAULT %L', col_name, '[]');
        ELSE
            BEGIN
                EXECUTE format('ALTER TABLE public.clients ALTER COLUMN %I TYPE JSONB USING %I::JSONB', col_name, col_name);
            EXCEPTION WHEN OTHERS THEN
                -- If conversion fails, replace
                EXECUTE format('ALTER TABLE public.clients DROP COLUMN %I', col_name);
                EXECUTE format('ALTER TABLE public.clients ADD COLUMN %I JSONB DEFAULT %L', col_name, '[]');
            END;
        END IF;
    END LOOP;
END $$;

-- 4. Sanctions Registry Reconciliation (v4.3.5+ Standards)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='sanctions') THEN
        CREATE TABLE public.sanctions (data_id TEXT PRIMARY KEY);
    END IF;
END $$;

DO $$
DECLARE
    col_name TEXT;
    target_cols TEXT[] := ARRAY[
        'first_name', 'second_name', 'third_name', 'last_name', 
        'source', 'un_list_type', 'reference_number', 'listed_on', 
        'comments', 'nationality', 'date_of_birth', 'type', 'integrity_hash', 'raw_payload'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS %I TEXT', col_name);
        EXECUTE format('ALTER TABLE public.sanctions ALTER COLUMN %I DROP NOT NULL', col_name);
        EXECUTE format('ALTER TABLE public.sanctions ALTER COLUMN %I DROP DEFAULT', col_name);
    END LOOP;
END $$;

-- 5. Sanctions JSONB Aliases
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='aliases') THEN
        ALTER TABLE public.sanctions ADD COLUMN aliases JSONB DEFAULT '[]'::jsonb;
    ELSE
        ALTER TABLE public.sanctions ALTER COLUMN aliases TYPE JSONB USING aliases::JSONB;
    END IF;
END $$;

-- 6. Engine Version & Audit Locks
CREATE TABLE IF NOT EXISTS public.system_metadata (key TEXT PRIMARY KEY, value JSONB DEFAULT '{}'::jsonb);
INSERT INTO public.system_metadata (key, value) 
VALUES ('schema_version', jsonb_build_object('version', '4.3.6', 'updated_at', now()))
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

-- Mandatory Schema Cache Refresh
NOTIFY pgrst, 'reload schema';`;

  const copySql = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopiedSql(true);
    setTimeout(() => setCopiedSql(false), 2000);
  };

  const saveUsersToStorage = (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isDelete) { await deleteCloudUser(user.email); } else { await upsertCloudUser(user); }
    } catch (e) {} finally { setIsSyncing(false); }
  };

  const toggleUserStatus = async (email: string) => {
    const updated = systemUsers.map(u => {
      if (u.email === email) {
        const newUser = { ...u, status: u.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE };
        handleCloudSync(newUser);
        return newUser;
      }
      return u;
    });
    saveUsersToStorage(updated);
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;
    const updated = systemUsers.filter(u => u.email !== pendingDeleteUser.email);
    saveUsersToStorage(updated);
    await handleCloudSync(pendingDeleteUser, true);
    setPendingDeleteUser(null);
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: newUserEmail.trim().toLowerCase(),
      password: DEFAULT_TEMP_PASSWORD,
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };
    await handleCloudSync(newUser);
    saveUsersToStorage([...systemUsers, newUser]);
    setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false); setIsNewUserAdmin(false);
  };

  const toggleEnvironment = () => {
    const newEnv = settings.environment === SystemEnvironment.PRODUCTION 
      ? SystemEnvironment.SANDBOX 
      : SystemEnvironment.PRODUCTION;
    onUpdateSettings({ ...settings, environment: newEnv });
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center bg-white p-6 sm:p-8 rounded-[2rem] shadow-sm border border-gray-100 gap-6">
        <div className="flex items-center gap-4">
          <div className={`${settings.environment === SystemEnvironment.PRODUCTION ? 'bg-emerald-800' : 'bg-amber-600'} p-4 rounded-2xl text-white shadow-xl transition-colors duration-500`}>
            {settings.environment === SystemEnvironment.PRODUCTION ? <Shield size={28}/> : <Beaker size={28}/>}
          </div>
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-900 tracking-tight uppercase">Governance</h2>
            <p className="text-[10px] text-emerald-600 font-black uppercase tracking-widest mt-1">Enterprise Registry Control</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full xl:w-auto">
            <button onClick={() => setActiveTab('users')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'users' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Identities</button>
            <button onClick={() => setActiveTab('engine')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'engine' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Engine</button>
            <button onClick={() => setActiveTab('logs')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'logs' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>System Logs</button>
        </div>
      </div>

      {activeTab === 'users' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex justify-between items-center border-b border-gray-50 pb-6">
              <div className="flex items-center gap-3">
                 <Users className="text-emerald-800" size={20} />
                 <h3 className="text-sm font-black uppercase text-slate-900">Identity Management</h3>
              </div>
              <button onClick={() => setIsUserModalOpen(true)} className="bg-emerald-800 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg hover:bg-emerald-900 transition-all">
                 <Plus size={16} /> Provision User
              </button>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[600px]">
                 <thead>
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                       <th className="px-4 py-4">Identity</th>
                       <th className="px-4 py-4">Role</th>
                       <th className="px-4 py-4">Status</th>
                       <th className="px-4 py-4 text-right">Actions</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {systemUsers.map((user: any) => (
                       <tr key={user.email} className="hover:bg-slate-50 transition-colors group">
                          <td className="px-4 py-4">
                             <p className="text-sm font-black text-slate-900 uppercase">{user.full_name}</p>
                             <p className="text-[10px] text-slate-400 font-bold">{user.email}</p>
                          </td>
                          <td className="px-4 py-4">
                             <span className="text-[10px] font-black uppercase text-emerald-700">{user.role}</span>
                          </td>
                          <td className="px-4 py-4">
                             <button onClick={() => toggleUserStatus(user.email)} className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase border transition-all ${user.status === AccountStatus.ACTIVE ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-red-50 text-red-600 border-red-100'}`}>
                                {user.status}
                             </button>
                          </td>
                          <td className="px-4 py-4 text-right">
                             <button onClick={() => setPendingDeleteUser(user)} className="p-2 text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all">
                                <Trash2 size={18} />
                             </button>
                          </td>
                       </tr>
                    ))}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {activeTab === 'engine' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex items-center gap-3 border-b border-gray-50 pb-6">
              <Zap className="text-amber-500" size={20} />
              <h3 className="text-sm font-black uppercase text-slate-900">Compliance Engine (v4.3.6)</h3>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                 <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 space-y-4">
                    <h4 className="text-[11px] font-black uppercase tracking-widest text-slate-900">Master Registry Health</h4>
                    <p className="text-[10px] text-slate-500 font-medium leading-relaxed">
                       The v4.3.6 SQL reconciliation script fixes "Client Name" schema cache errors by provisioning the correct authoritative structure for both Clients and Sanctions tables.
                    </p>
                    <button onClick={copySql} className="w-full py-4 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-black transition-all">
                       {copiedSql ? <Check size={16} /> : <Copy size={16} />}
                       {copiedSql ? 'Copied to Clipboard' : 'Copy Reconciliation v4.3.6'}
                    </button>
                 </div>

                 <div className="p-6 bg-amber-50 rounded-2xl border border-amber-100 space-y-4">
                    <div className="flex items-center gap-2">
                       <ShieldAlert className="text-amber-600" size={18} />
                       <h4 className="text-[11px] font-black uppercase tracking-widest text-amber-900">Environment Sandbox</h4>
                    </div>
                    <p className="text-[10px] text-amber-800 font-medium leading-relaxed">
                       Sandbox mode prevents destructive writes to the master registry.
                    </p>
                    <button onClick={toggleEnvironment} className={`w-full py-4 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${settings.environment === SystemEnvironment.PRODUCTION ? 'bg-amber-600 text-white hover:bg-amber-700' : 'bg-emerald-800 text-white hover:bg-emerald-900'}`}>
                       <Power size={16} /> {settings.environment === SystemEnvironment.PRODUCTION ? 'Enable Sandbox Mode' : 'Restore Production'}
                    </button>
                 </div>
              </div>

              <div className="bg-slate-900 p-8 rounded-3xl text-white shadow-2xl space-y-4 font-mono text-[10px] overflow-hidden relative border border-white/5">
                 <div className="flex justify-between items-center text-emerald-400 border-b border-white/5 pb-4 mb-4">
                    <span className="flex items-center gap-2 uppercase tracking-widest"><Terminal size={14}/> SYSTEM_DIAG_V4.3.6</span>
                    <span className="bg-emerald-500/10 px-2 py-0.5 rounded uppercase font-black">Active</span>
                 </div>
                 <div className="space-y-2 opacity-80">
                    <p className="text-emerald-300"># Initializing Compliance Engine v4.3.6...</p>
                    <p className="text-slate-400">Loading Fuzzy Matrix [SIMILARITY_LEVENSHTEIN]</p>
                    <p className="text-slate-400">Handshake: SUCCESS [Supabase-PostgREST]</p>
                    <p className="text-slate-400">PK Enforcement: ACTIVE [data_id, id]</p>
                    <p className="text-emerald-400 font-black">Node Status: AUTHORITATIVE_READ_WRITE</p>
                    <p className="text-slate-500 mt-4">--- SYSTEM REPORT ---</p>
                    <p className="text-slate-400">Immutability Protocol: SHA-256 ENABLED</p>
                    <p className="text-slate-400">Clients Registry: RECONCILED (Case-Sensitive Identifiers)</p>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'logs' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex items-center gap-3 border-b border-gray-50 pb-6">
              <History className="text-slate-400" size={20} />
              <h3 className="text-sm font-black uppercase text-slate-900">Audit & Log Trail</h3>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-left">
                 <thead>
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                       <th className="px-4 py-4">Timestamp</th>
                       <th className="px-4 py-4">Event</th>
                       <th className="px-4 py-4">User</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {logs.map((log) => (
                       <tr key={log.id} className="text-[11px]">
                          <td className="px-4 py-4 text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                          <td className="px-4 py-4 font-bold text-slate-800">{log.details}</td>
                          <td className="px-4 py-4 font-black uppercase text-emerald-700">{log.triggeredBy}</td>
                       </tr>
                    ))}
                    {logs.length === 0 && (
                       <tr>
                          <td colSpan={3} className="py-20 text-center text-slate-300 font-black uppercase tracking-widest text-[10px]">No recent audit trails</td>
                       </tr>
                    )}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase">Provision Identity</h3>
                 <button onClick={() => setIsUserModalOpen(false)} className="p-2 bg-white/10 rounded-full"><X size={20}/></button>
              </div>
              <form onSubmit={handleCreateUser} className="p-8 space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                    <input required className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserName} onChange={e => setNewUserName(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Corporate Email</label>
                    <input required type="email" className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserEmail} onChange={e => setNewUserEmail(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Access Role</label>
                    <select className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold outline-none" value={newUserRole} onChange={e => setNewUserRole(e.target.value as UserRole)}>
                       <option value={UserRole.DATA_ENTRY}>Data Entry Officer</option>
                       <option value={UserRole.REVIEWER}>Compliance Reviewer</option>
                       <option value={UserRole.ADMIN}>Compliance Manager</option>
                       <option value={UserRole.REPORTING}>Reporting User</option>
                       <option value={UserRole.AUDITOR}>Audit Viewer</option>
                    </select>
                 </div>
                 <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl">
                    <input type="checkbox" className="h-4 w-4 rounded border-slate-300 text-emerald-800 focus:ring-emerald-800" checked={isNewUserAdmin} onChange={e => setIsNewUserAdmin(e.target.checked)} />
                    <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Elevated System Admin Privileges</label>
                 </div>
                 <button type="submit" disabled={isSyncing} className="w-full py-5 bg-emerald-800 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-xl hover:bg-emerald-900 transition-all flex items-center justify-center gap-3">
                    {isSyncing ? <Loader2 className="animate-spin" size={20}/> : <Shield size={20}/>}
                    Commit to Registry
                 </button>
              </form>
           </div>
        </div>
      )}

      {pendingDeleteUser && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] p-8 max-sm w-full shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center text-red-600 mx-auto mb-6">
                 <Trash2 size={32} />
              </div>
              <h3 className="text-lg font-black text-slate-900 uppercase tracking-tight mb-2">Delete User?</h3>
              <p className="text-xs text-slate-500 font-bold mb-8 uppercase leading-relaxed">
                 Are you sure you want to remove <span className="text-red-600">{pendingDeleteUser.full_name}</span>? Access will be immediately revoked.
              </p>
              <div className="flex gap-3">
                 <button onClick={() => setPendingDeleteUser(null)} className="flex-1 py-4 bg-slate-50 text-slate-400 font-black text-[10px] uppercase rounded-xl tracking-widest">Cancel</button>
                 <button onClick={confirmDeleteUser} disabled={isSyncing} className="flex-1 py-4 bg-red-600 text-white font-black text-[10px] uppercase rounded-xl tracking-widest flex items-center justify-center gap-2">
                    {isSyncing ? <Loader2 className="animate-spin" size={14}/> : 'Confirm Delete'}
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

