const extractError = (err: any): string => {
  if (!err) return "Unknown Error";
  if (typeof err === 'string') return err;

  if (err.message && err.message.includes('column') && err.message.includes('not found')) {
      return `STRUCTURAL_INTEGRITY_FAULT: Database column '${err.message.split("'")[1]}' missing. RESOLUTION: Execute v4.3.6 Reconciliation Script in Governance tab.`;
  }

  if (err.message && err.message.includes('violates not-null constraint')) {
      return `SCHEMA_DRIFT_FAULT: DB constraint violation detected. RESOLUTION: Execute v4.3.6 Reconciliation Script to enable Null-Safety.`;
  }

  return err.message || err.details || JSON.stringify(err);
};

const computeHash = async (data: any): Promise<string> => {
  const msgUint8 = new TextEncoder().encode(JSON.stringify(data));
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
};

export const initSupabase = () => {
  try {
    supabaseClient = createClient(MASTER_REGISTRY_URL, MASTER_REGISTRY_KEY, {
      auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false }
    });
    return true;
  } catch (e) {
    console.error(`[v${REQUIRED_ENGINE_VERSION}] Handshake Fatal:`, e);
    return false;
  }
};

export const validateRegistrySchemaV431 = async (): Promise<{ success: boolean; error?: string; discrepancies: string[] }> => {
  if (!supabaseClient) return { success: false, error: 'Supabase client uninitialized', discrepancies: ['No active database connection'] };
  const discrepancies: string[] = [];
  try {
    const { data: verData, error: verErr } = await supabaseClient.from('system_metadata').select('value').eq('key', 'schema_version').single();
    if (verErr || !verData || (verData.value.version !== '4.3.1' && verData.value.version !== '4.3.3' && verData.value.version !== '4.3.4' && verData.value.version !== '4.3.5' && verData.value.version !== '4.3.6')) {
      discrepancies.push(`Registry Version Conflict: Application requires v4.3.6.`);
    }
    return { success: discrepancies.length === 0, discrepancies };
  } catch (e: any) {
    return { success: false, error: e.message, discrepancies: [e.message] };
  }
};

