/**
 * AUTHORITATIVE SEARCH:
 * Decomposes input name into tokens to pull fuzzy candidates from DB.
 */
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const queryStr = name.trim().toUpperCase();

  try {
    // 1. Extract Retrieval Tokens (Salient words only)
    const tokens = queryStr.split(/\s+/)
      .filter(t => t.length > 2 && !RETRIEVAL_NOISE.includes(t))
      .slice(0, 3); // Top 3 salient tokens to prevent query bloat

    if (tokens.length === 0) {
      // Fallback to literal search if no salient tokens found
      const term = `*${queryStr}*`;
      const { data, error } = await supabaseClient.from('sanctions').select('*').or(`first_name.ilike.${term},last_name.ilike.${term},data_id.ilike.${term}`).limit(50);
      if (error) throw error;
      return mapSanctions(data);
    }

    // 2. Multi-token Broad Search
    // This ensures 'SaNRISE GREENLAND' retrieves 'SUNRISE' entities.
    const filterParts: string[] = [];
    tokens.forEach(t => {
      const term = `*${t}*`;
      filterParts.push(`first_name.ilike.${term}`);
      filterParts.push(`last_name.ilike.${term}`);
      filterParts.push(`comments.ilike.${term}`);
    });

    const { data, error } = await supabaseClient.from('sanctions')
      .select('*')
      .or(filterParts.join(','))
      .limit(150);

    if (error) throw new Error(`REGISTRY_QUERY_FAULT: ${extractError(error)}`);

    return mapSanctions(data);
  } catch (e: any) { 
    throw e;
  }
};

const mapSanctions = (data: any[]): SanctionEntry[] => {
  return (data || []).map((row: any) => ({
    dataId: String(row.data_id ?? row.dataId ?? row.id ?? ''),
    firstName: row.first_name,
    secondName: row.second_name,
    thirdName: row.third_name,
    lastName: row.last_name,
    source: row.source,
    referenceNumber: row.reference_number,
    listedOn: row.listed_on,
    nationality: row.nationality,
    dateOfBirth: row.date_of_birth,
    unListType: row.un_list_type,
    comments: row.comments,
    aliases: Array.isArray(row.aliases) ? row.aliases : [],
    type: row.type,
    fetchDate: row.fetch_date
  } as SanctionEntry));
}

