interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'users' | 'engine' | 'logs'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);
  const [copiedSql, setCopiedSql] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const SQL_SCHEMA = `-- v4.3.6 Enterprise Master Reconciliation Script
-- PURPOSE: Enforce structural alignment for Clients, Sanctions, and Identity Profiles.

-- 1. Table Lockdown
ALTER TABLE IF EXISTS public.sanctions DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.clients DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.profiles DISABLE ROW LEVEL SECURITY;

-- 2. Profiles Table Provisioning (Identity Registry)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='profiles') THEN
        CREATE TABLE public.profiles (email TEXT PRIMARY KEY);
    END IF;
END $$;

DO $$
DECLARE
    col_name TEXT;
    target_cols TEXT[] := ARRAY[
        'id', 'full_name', 'password_hash_mock', 'role', 
        'is_system_admin', 'status', 'must_change_password', 
        'password_expiry', 'created_at'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS %I TEXT', col_name);
    END LOOP;

    -- Ensure boolean-like columns are handled as TEXT or cast properly if needed
    -- For simplicity in this mock-heavy environment, we use TEXT for statuses and roles.
END $$;

-- 3. Clients Table Provisioning
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='clients') THEN
        CREATE TABLE public.clients (id TEXT PRIMARY KEY);
    END IF;
END $$;

DO $$
DECLARE
    col_name TEXT;
    target_cols TEXT[] := ARRAY[
        'No', 'Status', 'QFC No', 'Legal Structure', 'Company Nationality',
        'Client Name', 'Engagement Year', 'Engagement Date', 'Onboarding Date',
        'Date of QFC Incorporation or Registration', 'CR Expired date',
        'Entity Card No', 'Entity Card Expiry', 'License', 'License Expiry',
        'Nature of Business', 'Registered Address', 'Telephone Number', 
        'E Mail', 'Website', 'Secretary', 'Senior Executive Function',
        'Approved Auditor', 'Company Type', 'created_by', 'kyc_status',
        'riskLevel', 'entity_type', 'lastScreenedAt'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS %I TEXT', col_name);
    END LOOP;
END $$;

-- 4. Clients JSONB Complexity
DO $$
DECLARE
    col_name TEXT;
    json_cols TEXT[] := ARRAY[
        'Services Provided', 'Directors Names', 'Significant Shareholders', 
        'UBO Details', 'Authorized Signatory', 'matches'
    ];
BEGIN
    FOREACH col_name IN ARRAY json_cols
    LOOP
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='clients' AND column_name=col_name) THEN
            EXECUTE format('ALTER TABLE public.clients ADD COLUMN %I JSONB DEFAULT %L', col_name, '[]');
        ELSE
            BEGIN
                EXECUTE format('ALTER TABLE public.clients ALTER COLUMN %I TYPE JSONB USING %I::JSONB', col_name, col_name);
            EXCEPTION WHEN OTHERS THEN
                EXECUTE format('ALTER TABLE public.clients DROP COLUMN %I', col_name);
                EXECUTE format('ALTER TABLE public.clients ADD COLUMN %I JSONB DEFAULT %L', col_name, '[]');
            END;
        END IF;
    END LOOP;
END $$;

-- 5. Sanctions Registry Reconciliation
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='sanctions') THEN
        CREATE TABLE public.sanctions (data_id TEXT PRIMARY KEY);
    END IF;
END $$;

DO $$
DECLARE
    col_name TEXT;
    target_cols TEXT[] := ARRAY[
        'first_name', 'second_name', 'third_name', 'last_name', 
        'source', 'un_list_type', 'reference_number', 'listed_on', 
        'comments', 'nationality', 'date_of_birth', 'type', 'integrity_hash', 'raw_payload'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS %I TEXT', col_name);
    END LOOP;
END $$;

-- 6. Sanctions JSONB Aliases
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='aliases') THEN
        ALTER TABLE public.sanctions ADD COLUMN aliases JSONB DEFAULT '[]'::jsonb;
    ELSE
        ALTER TABLE public.sanctions ALTER COLUMN aliases TYPE JSONB USING aliases::JSONB;
    END IF;
END $$;

-- 7. System Metadata
CREATE TABLE IF NOT EXISTS public.system_metadata (key TEXT PRIMARY KEY, value JSONB DEFAULT '{}'::jsonb);
INSERT INTO public.system_metadata (key, value) 
VALUES ('schema_version', jsonb_build_object('version', '4.3.6', 'updated_at', now()))
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

NOTIFY pgrst, 'reload schema';`;

  const copySql = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopiedSql(true);
    setTimeout(() => setCopiedSql(false), 2000);
  };

  const saveUsersToStorage = (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isDelete) { 
        await deleteCloudUser(user.email); 
      } else { 
        await upsertCloudUser(user); 
      }
    } catch (e: any) {
      alert(`Cloud Provisioning Error: ${e.message || 'Check database connection and schema alignment.'}`);
      throw e; // Rethrow to prevent local storage update if cloud fails
    } finally {
      setIsSyncing(false);
    }
  };

  const toggleUserStatus = async (email: string) => {
    const userToUpdate = systemUsers.find(u => u.email === email);
    if (!userToUpdate) return;

    const nextStatus = userToUpdate.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE;
    const updatedUser = { ...userToUpdate, status: nextStatus };

    try {
      await handleCloudSync(updatedUser);
      const nextUsers = systemUsers.map(u => u.email === email ? updatedUser : u);
      saveUsersToStorage(nextUsers);
    } catch (e) {}
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;
    try {
      await handleCloudSync(pendingDeleteUser, true);
      const updated = systemUsers.filter(u => u.email !== pendingDeleteUser.email);
      saveUsersToStorage(updated);
      setPendingDeleteUser(null);
    } catch (e) {}
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;

    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: newUserEmail.trim().toLowerCase(),
      password_hash_mock: DEFAULT_TEMP_PASSWORD, 
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };

    try {
      await handleCloudSync(newUser);
      saveUsersToStorage([...systemUsers, newUser]);
      setNewUserEmail(''); 
      setNewUserName(''); 
      setIsUserModalOpen(false); 
      setIsNewUserAdmin(false);
    } catch (err) {}
  };

  const toggleEnvironment = () => {
    const newEnv = settings.environment === SystemEnvironment.PRODUCTION 
      ? SystemEnvironment.SANDBOX 
      : SystemEnvironment.PRODUCTION;
    onUpdateSettings({ ...settings, environment: newEnv });
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center bg-white p-6 sm:p-8 rounded-[2rem] shadow-sm border border-gray-100 gap-6">
        <div className="flex items-center gap-4">
          <div className={`${settings.environment === SystemEnvironment.PRODUCTION ? 'bg-emerald-800' : 'bg-amber-600'} p-4 rounded-2xl text-white shadow-xl transition-colors duration-500`}>
            {settings.environment === SystemEnvironment.PRODUCTION ? <Shield size={28}/> : <Beaker size={28}/>}
          </div>
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-900 tracking-tight uppercase">Governance</h2>
            <p className="text-[10px] text-emerald-600 font-black uppercase tracking-widest mt-1">Enterprise Registry Control</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full xl:u-auto">
            <button onClick={() => setActiveTab('users')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'users' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Identities</button>
            <button onClick={() => setActiveTab('engine')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'engine' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Engine</button>
            <button onClick={() => setActiveTab('logs')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'logs' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>System Logs</button>
        </div>
      </div>

      {activeTab === 'users' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex justify-between items-center border-b border-gray-50 pb-6">
              <div className="flex items-center gap-3">
                 <Users className="text-emerald-800" size={20} />
                 <h3 className="text-sm font-black uppercase text-slate-900">Identity Management</h3>
              </div>
              <button onClick={() => setIsUserModalOpen(true)} className="bg-emerald-800 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg hover:bg-emerald-900 transition-all">
                 <Plus size={16} /> Provision User
              </button>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[600px]">
                 <thead>
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                       <th className="px-4 py-4">Identity</th>
                       <th className="px-4 py-4">Role</th>
                       <th className="px-4 py-4">Status</th>
                       <th className="px-4 py-4 text-right">Actions</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {systemUsers.map((user: any) => (
                       <tr key={user.email} className="hover:bg-slate-50 transition-colors group">
                          <td className="px-4 py-4">
                             <p className="text-sm font-black text-slate-900 uppercase">{user.full_name}</p>
                             <p className="text-[10px] text-slate-400 font-bold">{user.email}</p>
                          </td>
                          <td className="px-4 py-4">
                             <span className="text-[10px] font-black uppercase text-emerald-700">{user.role}</span>
                          </td>
                          <td className="px-4 py-4">
                             <button onClick={() => toggleUserStatus(user.email)} className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase border transition-all ${user.status === AccountStatus.ACTIVE ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-red-50 text-red-600 border-red-100'}`}>
                                {user.status}
                             </button>
                          </td>
                          <td className="px-4 py-4 text-right">
                             <button onClick={() => setPendingDeleteUser(user)} className="p-2 text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all">
                                <Trash2 size={18} />
                             </button>
                          </td>
                       </tr>
                    ))}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {activeTab === 'engine' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex items-center gap-3 border-b border-gray-50 pb-6">
              <Zap className="text-amber-500" size={20} />
              <h3 className="text-sm font-black uppercase text-slate-900">Compliance Engine (v4.3.6)</h3>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                 <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 space-y-4">
                    <h4 className="text-[11px] font-black uppercase tracking-widest text-slate-900">Master Registry Health</h4>
                    <p className="text-[10px] text-slate-500 font-medium leading-relaxed">
                       The v4.3.6 SQL reconciliation script fixes "Client Name" schema cache errors by provisioning the correct authoritative structure for Clients, Sanctions, and Profiles tables.
                    </p>
                    <button onClick={copySql} className="w-full py-4 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-black transition-all">
                       {copiedSql ? <Check size={16} /> : <Copy size={16} />}
                       {copiedSql ? 'Copied to Clipboard' : 'Copy Reconciliation v4.3.6'}
                    </button>
                 </div>

                 <div className="p-6 bg-amber-50 rounded-2xl border border-amber-100 space-y-4">
                    <div className="flex items-center gap-2">
                       <ShieldAlert className="text-amber-600" size={18} />
                       <h4 className="text-[11px] font-black uppercase tracking-widest text-amber-900">Environment Sandbox</h4>
                    </div>
                    <p className="text-[10px] text-amber-800 font-medium leading-relaxed">
                       Sandbox mode prevents destructive writes to the master registry.
                    </p>
                    <button onClick={toggleEnvironment} className={`w-full py-4 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${settings.environment === SystemEnvironment.PRODUCTION ? 'bg-amber-600 text-white hover:bg-amber-700' : 'bg-emerald-800 text-white hover:bg-emerald-900'}`}>
                       <Power size={16} /> {settings.environment === SystemEnvironment.PRODUCTION ? 'Enable Sandbox Mode' : 'Restore Production'}
                    </button>
                 </div>
              </div>

              <div className="bg-slate-900 p-8 rounded-3xl text-white shadow-2xl space-y-4 font-mono text-[10px] overflow-hidden relative border border-white/5">
                 <div className="flex justify-between items-center text-emerald-400 border-b border-white/5 pb-4 mb-4">
                    <span className="flex items-center gap-2 uppercase tracking-widest"><Terminal size={14}/> SYSTEM_DIAG_V4.3.6</span>
                    <span className="bg-emerald-500/10 px-2 py-0.5 rounded uppercase font-black">Active</span>
                 </div>
                 <div className="space-y-2 opacity-80">
                    <p className="text-emerald-300"># Initializing Compliance Engine v4.3.6...</p>
                    <p className="text-slate-400">Loading Fuzzy Matrix [SIMILARITY_LEVENSHTEIN]</p>
                    <p className="text-slate-400">Handshake: SUCCESS [Supabase-PostgREST]</p>
                    <p className="text-slate-400">PK Enforcement: ACTIVE [profiles.email, sanctions.data_id, clients.id]</p>
                    <p className="text-emerald-400 font-black">Node Status: AUTHORITATIVE_READ_WRITE</p>
                    <p className="text-slate-500 mt-4">--- SYSTEM REPORT ---</p>
                    <p className="text-slate-400">Immutability Protocol: SHA-256 ENABLED</p>
                    <p className="text-slate-400">Clients Registry: RECONCILED (Case-Sensitive Identifiers)</p>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'logs' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex items-center gap-3 border-b border-gray-50 pb-6">
              <History className="text-slate-400" size={20} />
              <h3 className="text-sm font-black uppercase text-slate-900">Audit & Log Trail</h3>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-left">
                 <thead>
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                       <th className="px-4 py-4">Timestamp</th>
                       <th className="px-4 py-4">Event</th>
                       <th className="px-4 py-4">User</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {logs.map((log) => (
                       <tr key={log.id} className="text-[11px]">
                          <td className="px-4 py-4 text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                          <td className="px-4 py-4 font-bold text-slate-800">{log.details}</td>
                          <td className="px-4 py-4 font-black uppercase text-emerald-700">{log.triggeredBy}</td>
                       </tr>
                    ))}
                    {logs.length === 0 && (
                       <tr>
                          <td colSpan={3} className="py-20 text-center text-slate-300 font-black uppercase tracking-widest text-[10px]">No recent audit trails</td>
                       </tr>
                    )}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase">Provision Identity</h3>
                 <button onClick={() => setIsUserModalOpen(false)} className="p-2 bg-white/10 rounded-full"><X size={20}/></button>
              </div>
              <form onSubmit={handleCreateUser} className="p-8 space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                    <input required className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserName} onChange={e => setNewUserName(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Corporate Email</label>
                    <input required type="email" className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserEmail} onChange={e => setNewUserEmail(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Access Role</label>
                    <select className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold outline-none" value={newUserRole} onChange={e => setNewUserRole(e.target.value as UserRole)}>
                       <option value={UserRole.DATA_ENTRY}>Data Entry Officer</option>
                       <option value={UserRole.REVIEWER}>Compliance Reviewer</option>
                       <option value={UserRole.ADMIN}>Compliance Manager</option>
                       <option value={UserRole.REPORTING}>Reporting User</option>
                       <option value={UserRole.AUDITOR}>Audit Viewer</option>
                    </select>
                 </div>
                 <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl">
                    <input type="checkbox" className="h-4 w-4 rounded border-slate-300 text-emerald-800 focus:ring-emerald-800" checked={isNewUserAdmin} onChange={e => setIsNewUserAdmin(e.target.checked)} />
                    <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Elevated System Admin Privileges</label>
                 </div>
                 <button type="submit" disabled={isSyncing} className="w-full py-5 bg-emerald-800 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-xl hover:bg-emerald-900 transition-all flex items-center justify-center gap-3">
                    {isSyncing ? <Loader2 className="animate-spin" size={20}/> : <Shield size={20}/>}
                    Commit to Registry
                 </button>
              </form>
           </div>
        </div>
      )}

      {pendingDeleteUser && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] p-8 max-sm w-full shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center text-red-600 mx-auto mb-6">
                 <Trash2 size={32} />
              </div>
              <h3 className="text-lg font-black text-slate-900 uppercase tracking-tight mb-2">Delete User?</h3>
              <p className="text-xs text-slate-500 font-bold mb-8 uppercase leading-relaxed">
                 Are you sure you want to remove <span className="text-red-600">{pendingDeleteUser.full_name}</span>? Access will be immediately revoked.
              </p>
              <div className="flex gap-3">
                 <button onClick={() => setPendingDeleteUser(null)} className="flex-1 py-4 bg-slate-50 text-slate-400 font-black text-[10px] uppercase rounded-xl tracking-widest">Cancel</button>
                 <button onClick={confirmDeleteUser} disabled={isSyncing} className="flex-1 py-4 bg-red-600 text-white font-black text-[10px] uppercase rounded-xl tracking-widest flex items-center justify-center gap-2">
                    {isSyncing ? <Loader2 className="animate-spin" size={14}/> : 'Confirm Delete'}
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState } from 'react';
import { Lock, Mail, AlertCircle, Eye, EyeOff, CheckCircle, WifiOff, Loader2, Globe, Shield } from 'lucide-react';
import { UserProfile, UserRole, AccountStatus } from '../types';
import { fetchCloudUsers } from '../services/cloudDb';

interface LoginProps {
  onLogin: (user: UserProfile) => void;
  isCloudConnected: boolean;
}

const Login: React.FC<LoginProps> = ({ onLogin, isCloudConnected }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const PRIMARY_LOGO = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";
  const FALLBACK_LOGO = "https://placehold.co/600x400/064e3b/ffffff?text=RPME+LIMITED";

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPassword = password.trim();

    // v2.7.0: Root Administrator Bypass
    if (normalizedEmail === 'aqandeel@gmail.com' && normalizedPassword === 'Rodl@2026') {
      setIsSuccess(true);
      setTimeout(() => {
        onLogin({
          id: 'SYS-ROOT', email: 'aqandeel@gmail.com', full_name: 'RPME System Root',
          role: UserRole.ADMIN, is_system_admin: true, status: AccountStatus.ACTIVE,
          must_change_password: false, password_expiry: '', created_at: new Date().toISOString()
        });
      }, 800);
      return;
    }

    if (!isCloudConnected) {
      setError('System Node Offline: Handshake with Enterprise Registry failed.');
      setIsLoading(false);
      return;
    }

    try {
      const cloudUsers = await fetchCloudUsers();
      if (!cloudUsers || cloudUsers.length === 0) {
        setError('Authorization Server Empty: No identities found in Cloud Registry.');
        setIsLoading(false);
        return;
      }

      // Authoritative comparison against fetched cloud profiles
      const userFound = cloudUsers.find((u: any) => {
        const dbEmail = (u.email || '').toLowerCase().trim();
        // Comparing password_hash_mock with provided plain text
        return dbEmail === normalizedEmail && u.password_hash_mock === normalizedPassword;
      });

      if (userFound) {
