                    <button onClick={toggleEnvironment} className={`w-full py-4 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${settings.environment === SystemEnvironment.PRODUCTION ? 'bg-amber-600 text-white hover:bg-amber-700' : 'bg-emerald-800 text-white hover:bg-emerald-900'}`}>
