                    <p className="text-slate-400">Handshake: SUCCESS [Supabase-PostgREST]</p>
                    <p className="text-slate-400">PK Enforcement: ACTIVE [profiles.email, sanctions.data_id, clients.id]</p>
                    <p className="text-emerald-400 font-black">Node Status: AUTHORITATIVE_READ_WRITE</p>
                    <p className="text-slate-500 mt-4">--- SYSTEM REPORT ---</p>
                    <p className="text-slate-400">Identity Integrity: PK_ENFORCED [Email]</p>
                    <p className="text-slate-400">Clients Registry: RECONCILED [v4.3.7]</p>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'logs' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex items-center gap-3 border-b border-gray-50 pb-6">
              <History className="text-slate-400" size={20} />
              <h3 className="text-sm font-black uppercase text-slate-900">Audit & Log Trail</h3>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-left">
                 <thead>
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                       <th className="px-4 py-4">Timestamp</th>
                       <th className="px-4 py-4">Event</th>
                       <th className="px-4 py-4">User</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {logs.map((log) => (
                       <tr key={log.id} className="text-[11px]">
                          <td className="px-4 py-4 text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                          <td className="px-4 py-4 font-bold text-slate-800">{log.details}</td>
                          <td className="px-4 py-4 font-black uppercase text-emerald-700">{log.triggeredBy}</td>
                       </tr>
                    ))}
                    {logs.length === 0 && (
                       <tr>
                          <td colSpan={3} className="py-20 text-center text-slate-300 font-black uppercase tracking-widest text-[10px]">No recent audit trails</td>
                       </tr>
                    )}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase">Provision Identity</h3>
                 <button onClick={() => setIsUserModalOpen(false)} className="p-2 bg-white/10 rounded-full"><X size={20}/></button>
              </div>
              <form onSubmit={handleCreateUser} className="p-8 space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                    <input required className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserName} onChange={e => setNewUserName(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Corporate Email</label>
                    <input required type="email" className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserEmail} onChange={e => setNewUserEmail(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Access Role</label>
                    <select className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold outline-none" value={newUserRole} onChange={e => setNewUserRole(e.target.value as UserRole)}>
                       <option value={UserRole.DATA_ENTRY}>Data Entry Officer</option>
                       <option value={UserRole.REVIEWER}>Compliance Reviewer</option>
                       <option value={UserRole.ADMIN}>Compliance Manager</option>
                       <option value={UserRole.REPORTING}>Reporting User</option>
                       <option value={UserRole.AUDITOR}>Audit Viewer</option>
                    </select>
                 </div>
                 <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl">
                    <input type="checkbox" className="h-4 w-4 rounded border-slate-300 text-emerald-800 focus:ring-emerald-800" checked={isNewUserAdmin} onChange={e => setIsNewUserAdmin(e.target.checked)} />
                    <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Elevated System Admin Privileges</label>
                 </div>
                 <button type="submit" disabled={isSyncing} className="w-full py-5 bg-emerald-800 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-xl hover:bg-emerald-900 transition-all flex items-center justify-center gap-3">
                    {isSyncing ? <Loader2 className="animate-spin" size={20}/> : <Shield size={20}/>}
                    Commit to Registry
                 </button>
              </form>
           </div>
        </div>
      )}

      {pendingDeleteUser && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] p-8 max-sm w-full shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center text-red-600 mx-auto mb-6">
                 <Trash2 size={32} />
              </div>
              <h3 className="text-lg font-black text-slate-900 uppercase tracking-tight mb-2">Delete User?</h3>
              <p className="text-xs text-slate-500 font-bold mb-8 uppercase leading-relaxed">
                 Are you sure you want to remove <span className="text-red-600">{pendingDeleteUser.full_name}</span>? Access will be immediately revoked.
              </p>
              <div className="flex gap-3">
                 <button onClick={() => setPendingDeleteUser(null)} className="flex-1 py-4 bg-slate-50 text-slate-400 font-black text-[10px] uppercase rounded-xl tracking-widest">Cancel</button>
                 <button onClick={confirmDeleteUser} disabled={isSyncing} className="flex-1 py-4 bg-red-600 text-white font-black text-[10px] uppercase rounded-xl tracking-widest flex items-center justify-center gap-2">
                    {isSyncing ? <Loader2 className="animate-spin" size={14}/> : 'Confirm Delete'}
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus, SystemEnvironment } from '../types';
import { Plus, Power, Trash2, Shield, Copy, Check, Users, ShieldAlert, History, Beaker, Zap, Terminal, X, Loader2 } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'users' | 'engine' | 'logs'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);
  const [copiedSql, setCopiedSql] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const SQL_SCHEMA = `-- v4.3.8 Enterprise Master Reconciliation Script
-- PURPOSE: Enforce structural alignment and fix 'role_id' constraint violations.

-- 1. Table Lockdown
ALTER TABLE IF EXISTS public.sanctions DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.clients DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.profiles DISABLE ROW LEVEL SECURITY;

-- 2. Profiles Table Provisioning (Standardized Boolean Types)
CREATE TABLE IF NOT EXISTS public.profiles (
    email TEXT PRIMARY KEY,
    id TEXT,
    full_name TEXT,
    password_hash_mock TEXT,
    role TEXT,
    is_system_admin BOOLEAN DEFAULT false,
    status TEXT DEFAULT 'Active',
    must_change_password BOOLEAN DEFAULT true,
    password_expiry TEXT,
    created_at TEXT
);

-- 3. Authoritative Constraint Fix (Resolves role_id Not-Null Violation)
DO $$
BEGIN
    -- If role_id exists and is NOT NULL, make it optional
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='profiles' AND column_name='role_id') THEN
        ALTER TABLE public.profiles ALTER COLUMN role_id DROP NOT NULL;
    END IF;

    -- Ensure columns exist if table was already created with older scripts
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS id TEXT;
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS full_name TEXT;
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS password_hash_mock TEXT;
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS role TEXT;
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS is_system_admin BOOLEAN DEFAULT false;
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS status TEXT DEFAULT 'Active';
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS must_change_password BOOLEAN DEFAULT true;
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS password_expiry TEXT;
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS created_at TEXT;
EXCEPTION WHEN OTHERS THEN
    NULL;
END $$;

-- 4. Clients Table Provisioning
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='clients') THEN
        CREATE TABLE public.clients (id TEXT PRIMARY KEY);
    END IF;
END $$;

DO $$
DECLARE
    col_name TEXT;
    target_cols TEXT[] := ARRAY[
        'No', 'Status', 'QFC No', 'Legal Structure', 'Company Nationality',
        'Client Name', 'Engagement Year', 'Engagement Date', 'Onboarding Date',
        'Date of QFC Incorporation or Registration', 'CR Expired date',
        'Entity Card No', 'Entity Card Expiry', 'License', 'License Expiry',
        'Nature of Business', 'Registered Address', 'Telephone Number', 
        'E Mail', 'Website', 'Secretary', 'Senior Executive Function',
        'Approved Auditor', 'Company Type', 'created_by', 'kyc_status',
        'riskLevel', 'entity_type', 'lastScreenedAt'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS %I TEXT', col_name);
    END LOOP;
END $$;

-- 5. Clients JSONB Alignment
DO $$
DECLARE
    col_name TEXT;
    json_cols TEXT[] := ARRAY[
        'Services Provided', 'Directors Names', 'Significant Shareholders', 
        'UBO Details', 'Authorized Signatory', 'matches'
    ];
BEGIN
    FOREACH col_name IN ARRAY json_cols
    LOOP
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='clients' AND column_name=col_name) THEN
            EXECUTE format('ALTER TABLE public.clients ADD COLUMN %I JSONB DEFAULT %L', col_name, '[]');
        ELSE
            BEGIN
                EXECUTE format('ALTER TABLE public.clients ALTER COLUMN %I TYPE JSONB USING %I::JSONB', col_name, col_name);
            EXCEPTION WHEN OTHERS THEN
                EXECUTE format('ALTER TABLE public.clients DROP COLUMN %I', col_name);
                EXECUTE format('ALTER TABLE public.clients ADD COLUMN %I JSONB DEFAULT %L', col_name, '[]');
            END;
        END IF;
    END LOOP;
END $$;

-- 6. Sanctions Registry Reconciliation
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='sanctions') THEN
        CREATE TABLE public.sanctions (data_id TEXT PRIMARY KEY);
    END IF;
END $$;

DO $$
DECLARE
    col_name TEXT;
    target_cols TEXT[] := ARRAY[
        'first_name', 'second_name', 'third_name', 'last_name', 
        'source', 'un_list_type', 'reference_number', 'listed_on', 
        'comments', 'nationality', 'date_of_birth', 'type', 'integrity_hash', 'raw_payload'
    ];
BEGIN
    FOREACH col_name IN ARRAY target_cols
    LOOP
        EXECUTE format('ALTER TABLE public.sanctions ADD COLUMN IF NOT EXISTS %I TEXT', col_name);
    END LOOP;
END $$;

-- 7. Sanctions JSONB Aliases
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sanctions' AND column_name='aliases') THEN
        ALTER TABLE public.sanctions ADD COLUMN aliases JSONB DEFAULT '[]'::jsonb;
    ELSE
        ALTER TABLE public.sanctions ALTER COLUMN aliases TYPE JSONB USING aliases::JSONB;
    END IF;
END $$;

-- 8. System Metadata
CREATE TABLE IF NOT EXISTS public.system_metadata (key TEXT PRIMARY KEY, value JSONB DEFAULT '{}'::jsonb);
INSERT INTO public.system_metadata (key, value) 
VALUES ('schema_version', jsonb_build_object('version', '4.3.8', 'updated_at', now()))
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

NOTIFY pgrst, 'reload schema';`;

  const copySql = () => {
    navigator.clipboard.writeText(SQL_SCHEMA);
    setCopiedSql(true);
    setTimeout(() => setCopiedSql(false), 2000);
  };

  const saveUsersToStorage = (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isDelete) { 
        await deleteCloudUser(user.email); 
      } else { 
        await upsertCloudUser(user); 
      }
    } catch (e: any) {
      console.error("[Governance] Sync Fault:", e);
      alert(`Cloud Provisioning Error: ${e.message || 'Check database connection and schema alignment.'}`);
      throw e; 
    } finally {
      setIsSyncing(false);
    }
  };

  const toggleUserStatus = async (email: string) => {
    const userToUpdate = systemUsers.find(u => u.email === email);
    if (!userToUpdate) return;
    const nextStatus = userToUpdate.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE;
    const updatedUser = { ...userToUpdate, status: nextStatus };
    try {
      await handleCloudSync(updatedUser);
      const nextUsers = systemUsers.map(u => u.email === email ? updatedUser : u);
      saveUsersToStorage(nextUsers);
    } catch (e) {}
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;
    try {
      await handleCloudSync(pendingDeleteUser, true);
      const updated = systemUsers.filter(u => u.email !== pendingDeleteUser.email);
      saveUsersToStorage(updated);
      setPendingDeleteUser(null);
    } catch (e) {}
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: newUserEmail.trim().toLowerCase(),
      password_hash_mock: DEFAULT_TEMP_PASSWORD, 
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };
    try {
      await handleCloudSync(newUser);
      saveUsersToStorage([...systemUsers, newUser]);
      setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false); setIsNewUserAdmin(false);
    } catch (err) {
      console.error("[Governance] User creation aborted due to registry failure.");
    }
  };

  const toggleEnvironment = () => {
    const newEnv = settings.environment === SystemEnvironment.PRODUCTION ? SystemEnvironment.SANDBOX : SystemEnvironment.PRODUCTION;
    onUpdateSettings({ ...settings, environment: newEnv });
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20">
