              <div className="bg-slate-900 p-8 rounded-3xl text-white shadow-2xl space-y-4 font-mono text-[10px] overflow-hidden relative border border-white/5">
                 <div className="flex justify-between items-center text-emerald-400 border-b border-white/5 pb-4 mb-4">
                    <span className="flex items-center gap-2 uppercase tracking-widest"><Terminal size={14}/> SYSTEM_DIAG_V4.3.8</span>
