        </div>
      )}

      {activeTab === 'logs' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
           <div className="flex items-center gap-3 border-b border-gray-50 pb-6">
              <History className="text-slate-400" size={20} />
              <h3 className="text-sm font-black uppercase text-slate-900">Audit & Log Trail</h3>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-left">
                 <thead>
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                       <th className="px-4 py-4">Timestamp</th>
                       <th className="px-4 py-4">Event</th>
                       <th className="px-4 py-4">User</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {logs.map((log) => (
                       <tr key={log.id} className="text-[11px]">
                          <td className="px-4 py-4 text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                          <td className="px-4 py-4 font-bold text-slate-800">{log.details}</td>
                          <td className="px-4 py-4 font-black uppercase text-emerald-700">{log.triggeredBy}</td>
                       </tr>
                    ))}
                    {logs.length === 0 && (
                       <tr>
                          <td colSpan={3} className="py-20 text-center text-slate-300 font-black uppercase tracking-widest text-[10px]">No recent audit trails</td>
                       </tr>
                    )}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase">Provision Identity</h3>
                 <button onClick={() => setIsUserModalOpen(false)} className="p-2 bg-white/10 rounded-full"><X size={20}/></button>
              </div>
              <form onSubmit={handleCreateUser} className="p-8 space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                    <input required className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserName} onChange={e => setNewUserName(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Corporate Email</label>
                    <input required type="email" className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold" value={newUserEmail} onChange={e => setNewUserEmail(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Access Role</label>
                    <select className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold outline-none" value={newUserRole} onChange={e => setNewUserRole(e.target.value as UserRole)}>
                       <option value={UserRole.DATA_ENTRY}>Data Entry Officer</option>
                       <option value={UserRole.REVIEWER}>Compliance Reviewer</option>
                       <option value={UserRole.ADMIN}>Compliance Manager</option>
                       <option value={UserRole.REPORTING}>Reporting User</option>
                       <option value={UserRole.AUDITOR}>Audit Viewer</option>
                    </select>
                 </div>
                 <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl">
                    <input type="checkbox" className="h-4 w-4 rounded border-slate-300 text-emerald-800 focus:ring-emerald-800" checked={isNewUserAdmin} onChange={e => setIsNewUserAdmin(e.target.checked)} />
                    <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Elevated System Admin Privileges</label>
                 </div>
                 <button type="submit" disabled={isSyncing} className="w-full py-5 bg-emerald-800 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-xl hover:bg-emerald-900 transition-all flex items-center justify-center gap-3">
                    {isSyncing ? <Loader2 className="animate-spin" size={20}/> : <Shield size={20}/>}
                    Commit to Registry
                 </button>
              </form>
           </div>
        </div>
      )}

      {pendingDeleteUser && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] p-8 max-sm w-full shadow-2xl text-center">
              <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center text-red-600 mx-auto mb-6">
                 <Trash2 size={32} />
              </div>
              <h3 className="text-lg font-black text-slate-900 uppercase tracking-tight mb-2">Delete User?</h3>
              <p className="text-xs text-slate-500 font-bold mb-8 uppercase leading-relaxed">
                 Are you sure you want to remove <span className="text-red-600">{pendingDeleteUser.full_name}</span>? Access will be immediately revoked.
              </p>
              <div className="flex gap-3">
                 <button onClick={() => setPendingDeleteUser(null)} className="flex-1 py-4 bg-slate-50 text-slate-400 font-black text-[10px] uppercase rounded-xl tracking-widest">Cancel</button>
                 <button onClick={confirmDeleteUser} disabled={isSyncing} className="flex-1 py-4 bg-red-600 text-white font-black text-[10px] uppercase rounded-xl tracking-widest flex items-center justify-center gap-2">
                    {isSyncing ? <Loader2 className="animate-spin" size={14}/> : 'Confirm Delete'}
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount,
  fetchSanctionsBatch,
  upsertCloudSanctions,
  fetchClientsTotalCount,
  screenEntityAgainstDb,
  validateRegistrySchemaV431
} from './services/cloudDb';
import { parseUNSanctionsXML, parseCSVToSanctions, OFFICIAL_UN_XML_URL } from './services/unSanctionsService';
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsRegistry from './components/SanctionsRegistry';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Client, SanctionEntry, RiskLevel, AppSettings, UserRole, UserProfile, SystemEnvironment, ScreeningProgress } from './types';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  environment: SystemEnvironment.PRODUCTION
};

const CLIENTS_PER_PAGE = 15;

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [clientsCount, setClientsCount] = useState(0);
  const [currentClientsPage, setCurrentClientsPage] = useState(1);
  const [isRefreshingClients, setIsRefreshingClients] = useState(false);

  const [screeningProgress, setScreeningProgress] = useState<ScreeningProgress>({
    totalRecords: 0,
    screenedRecords: 0,
    pendingRecords: 0,
    status: 'Not Started',
    currentBatch: 0
  });

  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [isUpdatingSanctions, setIsUpdatingSanctions] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [totalInDb, setTotalInDb] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR' | 'SAFE_MODE'>('CONNECTING');
  const [schemaDiscrepancies, setSchemaDiscrepancies] = useState<string[]>([]);

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    if (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
      loadSanctionsCache();
    }
  }, []);

  const loadSanctionsCache = useCallback(async () => {
    try {
      const count = await fetchSanctionsTotalCount();
      setTotalInDb(count);
      setSanctionsCount(count); 
      setSanctions([]); 
    } catch (e) { console.error("[App] Cache Refresh Failure:", e); }
  }, []);

  const refreshClients = useCallback(async (page: number = 1) => {
    setIsRefreshingClients(true);
    try {
      const from = (page - 1) * CLIENTS_PER_PAGE;
      const to = from + CLIENTS_PER_PAGE - 1;
      const [cloudClients, count] = await Promise.all([
        fetchCloudClients(from, to),
        fetchClientsTotalCount()
      ]);
      if (cloudClients) setClients(cloudClients);
      setClientsCount(count);
      setCurrentClientsPage(page);
    } catch (e) { console.error("[App] Registry Pull Failure:", e); } finally { setIsRefreshingClients(false); }
  }, []);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');
    setSchemaDiscrepancies([]);
    try {
      initSupabase();
      const healthy = await checkConnection();
      if (healthy) {
        const audit = await validateRegistrySchemaV431();
        if (!audit.success) {
           setConnectionStatus('SAFE_MODE');
           setSchemaDiscrepancies(audit.discrepancies || ['Structural Audit Conflict']);
           await Promise.all([refreshClients(1), loadSanctionsCache()]);
        } else {
           setConnectionStatus('CONNECTED');
           await Promise.all([
             refreshClients(1),
             loadSanctionsCache(),
             fetchGlobalSyncStatus().then(l => l && handleGlobalMetadataUpdate(l))
           ]);
           if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
           subscriptionRef.current = subscribeToClients(() => refreshClients(currentClientsPage));
           if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
           syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
        }
      } else {
        setConnectionStatus('ERROR');
      }
    } catch (e: any) { setConnectionStatus('ERROR'); }
    setTimeout(() => setIsBooting(false), 1500);
  }, [handleGlobalMetadataUpdate, loadSanctionsCache, refreshClients, currentClientsPage]);

  useEffect(() => { bootEnterpriseNode(); }, [bootEnterpriseNode]);

  const handleAddClientWithAuthoritativeScreening = async (newClient: Client) => {
    if (connectionStatus !== 'CONNECTED') {
        const err = "Registry mutation prohibited while node is out of sync.";
        alert(err);
        throw new Error(err);
    }

    setIsRefreshingClients(true);
    try {
      console.log("[Provisioning] Executing automatic fuzzy screening for:", newClient["Client Name"]);
      const screenedClient = await screenEntityAgainstDb(newClient, currentUser?.id);
      await upsertCloudClient(screenedClient);
      await refreshClients(currentClientsPage); 
    } catch (e: any) { 
      throw e; 
    } finally { 
      setIsRefreshingClients(false); 
    }
  };

  const handleDeleteClient = async (id: string) => {
    if (connectionStatus !== 'CONNECTED') {
      alert("SECURITY_BLOCK: Mutation denied.");
      return;
    }
    setIsRefreshingClients(true);
    try {
      await deleteCloudClient(id);
      await refreshClients(currentClientsPage);
    } catch (e: any) {
      alert(`Deletion Error: ${e.message}.`);
    } finally {
      setIsRefreshingClients(false);
    }
  };

  const handleReScreenAllAuthoritative = async () => {
    if (connectionStatus !== 'CONNECTED' || isRefreshingClients) return;
    setIsRefreshingClients(true);
    try {
      const total = await fetchClientsTotalCount();
      setScreeningProgress({ totalRecords: total, screenedRecords: 0, pendingRecords: total, status: 'In Progress', currentBatch: 0 });
      const batchSize = 10; 
      for (let i = 0; i < total; i += batchSize) {
        const batch = await fetchCloudClients(i, i + batchSize - 1) || [];
        for (const client of batch) {
          const screened = await screenEntityAgainstDb(client, currentUser?.id);
          await upsertCloudClient(screened);
          setScreeningProgress(prev => ({ ...prev, screenedRecords: prev.screenedRecords + 1 }));
        }
      }
      setScreeningProgress(prev => ({ ...prev, status: 'Completed', pendingRecords: 0 }));
      await refreshClients(currentClientsPage);
      setTimeout(() => setScreeningProgress(p => ({ ...p, status: 'Not Started' })), 4000);
    } catch (e) {
      setScreeningProgress(prev => ({ ...prev, status: 'Not Started' }));
    } finally {
      setIsRefreshingClients(false);
    }
  };

  const handlePasswordUpdate = async (newPassword: string) => {
    if (!currentUser) return;
    try {
      const updatedUser = { 
        ...currentUser, 
        password_hash_mock: newPassword, 
        must_change_password: false 
      };
      await upsertCloudUser(updatedUser);
      setCurrentUser(updatedUser);
      localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      alert("Security Handshake Complete: Password updated successfully.");
    } catch (e: any) {
      alert("Failed to update password: " + e.message);
    }
  };

  const handleUpdateClient = async (updatedClient: Client) => {
    try {
      await upsertCloudClient(updatedClient);
      setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    } catch (e: any) {
      alert("Status Update Failed: " + e.message);
    }
  };

  const effectiveEnvironment = (currentUser?.id === 'SYS-ROOT') ? settings.environment : SystemEnvironment.PRODUCTION;

  if (!currentUser) {
    return <Login onLogin={(u) => { setCurrentUser(u); localStorage.setItem('unsg_session', JSON.stringify(u)); }} isCloudConnected={connectionStatus === 'CONNECTED' || connectionStatus === 'SAFE_MODE'} />;
  }

  // Intercept for mandatory password change
  if (currentUser.must_change_password) {
    return <PasswordUpdate user={currentUser} onUpdate={handlePasswordUpdate} />;
  }

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'} 
        isSafeMode={connectionStatus === 'SAFE_MODE'} 
        schemaFaults={schemaDiscrepancies}
        onLogout={() => { setCurrentUser(null); localStorage.removeItem('unsg_session'); }} 
        currentUser={currentUser} 
        onRetryConnection={() => bootEnterpriseNode()} 
        environment={effectiveEnvironment}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} totalClientsCount={clientsCount} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} />} />
          <Route path="/clients" element={<ClientManager clients={clients} totalCount={clientsCount} currentPage={currentClientsPage} onPageChange={refreshClients} isRefreshing={isRefreshingClients} onAddClient={handleAddClientWithAuthoritativeScreening} onDeleteClient={handleDeleteClient} onRefresh={() => refreshClients(currentClientsPage)} onReScreen={handleReScreenAllAuthoritative} onUpdateClient={handleUpdateClient} screeningProgress={screeningProgress} currentUserRole={currentUser.role} currentUserId={currentUser.id} />} />
          <Route path="/sanctions" element={<SanctionsRegistry onSyncComplete={() => loadSanctionsCache()} isCloudConnected={connectionStatus === 'CONNECTED'} initialStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} currentUser={currentUser} />} />
          <Route path="/admin" element={currentUser.is_system_admin === true ? <AdminPanel settings={settings} logs={[]} onUpdateSettings={(s) => { setSettings(s); localStorage.setItem('unsg_settings', JSON.stringify(s)); }} currentUser={currentUser} /> : <Navigate to="/" replace />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

