export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void, replace: boolean = false) => {
  if (!supabaseClient) throw new Error("Registry offline.");
  const total = sanctions.length;
  if (total === 0) return;
  if (replace) {
    const { data: latestRecord, error: fetchErr } = await supabaseClient.from('sanctions').select('fetch_date').order('fetch_date', { ascending: false }).limit(1).single();
    if (!fetchErr && latestRecord && sanctions[0].fetchDate) {
      if (new Date(sanctions[0].fetchDate) <= new Date(latestRecord.fetch_date)) {
         throw new Error("REGRESSION_GUARD: Injected dataset is not newer than current registry.");
      }
    }
    const { error: deleteErr } = await supabaseClient.from('sanctions').delete().neq('data_id', '_none_');
    if (deleteErr) throw deleteErr;
  }
  for (let i = 0; i < total; i += 200) {
    const rawBatch = sanctions.slice(i, i + 200);
    const preHash = await computeHash(rawBatch);
    const batch = rawBatch.map(s => ({
      data_id: s.dataId, first_name: s.firstName, second_name: s.secondName, third_name: s.thirdName,
      last_name: s.lastName, source: s.source, reference_number: s.referenceNumber, listed_on: s.listedOn,
      nationality: s.nationality, date_of_birth: s.dateOfBirth, un_list_type: s.unListType,
      comments: s.comments, type: s.type, aliases: s.aliases, fetch_date: s.fetchDate,
      integrity_hash: preHash, raw_payload: JSON.stringify(s)
    }));
    const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
    if (error) throw error;
    if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
  }
};

