export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];
  const queryStr = name.trim().toUpperCase();
  try {
    const tokens = queryStr.split(/\s+/).filter(t => t.length > 2 && !RETRIEVAL_NOISE.includes(t)).slice(0, 3);
    const filterParts: string[] = [];
    if (tokens.length === 0) {
      filterParts.push(`first_name.ilike.*${queryStr}*`, `last_name.ilike.*${queryStr}*`);
    } else {
      tokens.forEach(t => filterParts.push(`first_name.ilike.*${t}*`, `last_name.ilike.*${t}*`, `comments.ilike.*${t}*`));
    }
    const { data, error } = await supabaseClient.from('sanctions').select('*').or(filterParts.join(',')).limit(150);
    if (error) throw error;
    return (data || []).map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: row.first_name,
      secondName: row.second_name,
      thirdName: row.third_name,
      lastName: row.last_name,
      source: row.source,
      referenceNumber: row.reference_number,
      listedOn: row.listed_on,
      nationality: row.nationality,
      dateOfBirth: row.date_of_birth,
      unListType: row.un_list_type,
      comments: row.comments,
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: row.type,
      fetchDate: row.fetch_date
    } as SanctionEntry));
  } catch (e: any) { throw e; }
};

export const fetchCloudClients = async (from: number, to: number): Promise<Client[]> => {
  if (!supabaseClient) return getLocalClients().slice(from, to + 1);
  try {
    const { data, error } = await supabaseClient.from('clients').select('*').order('created_at', { ascending: false }).range(from, to);
    if (error) throw error;
    const cloudClients = (data || []).map((row: any) => ({ ...row, id: row.id } as Client));
    if (from === 0) saveLocalClients(cloudClients); // Cache first page
    return cloudClients;
  } catch (e) {
    return getLocalClients().slice(from, to + 1);
  }
};

export const fetchClientsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return getLocalClients().length;
  try {
    const { count, error } = await supabaseClient.from('clients').select('*', { count: 'exact', head: true });
    return error ? getLocalClients().length : count || 0;
  } catch (e) {
    return getLocalClients().length;
  }
};

export const upsertCloudClient = async (client: Client) => {
  // Always update local shadow first
  const local = getLocalClients();
  const existingIndex = local.findIndex(c => c.id === client.id);
  if (existingIndex > -1) local[existingIndex] = client;
  else local.unshift(client);
  saveLocalClients(local);

  if (!supabaseClient) return;
  try {
    const { error } = await supabaseClient.from('clients').upsert([client], { onConflict: 'id' });
    if (error) throw error;
  } catch (e: any) {
    console.warn("[Registry] Cloud Sync failed, change preserved in local shadow.", e);
    // Rethrow only if we specifically need to notify the UI of a network failure
    if (e.message?.includes('fetch')) throw e;
  }
};

export const deleteCloudClient = async (id: string) => {
  // Update local shadow
  const local = getLocalClients().filter(c => c.id !== id);
  saveLocalClients(local);

  if (!supabaseClient) return;
  try {
    const { error } = await supabaseClient.from('clients').delete().eq('id', id);
    if (error) throw error;
  } catch (e: any) {
    console.warn("[Registry] Cloud Deletion failed, local shadow updated.");
    if (e.message?.includes('fetch')) throw e;
  }
};

export const fetchCloudUsers = async (): Promise<any[]> => {
  if (!supabaseClient) return JSON.parse(localStorage.getItem('unsg_users') || '[]');
  try {
    const { data, error } = await supabaseClient.from('profiles').select('*');
    return error ? [] : data || [];
  } catch (e) { return JSON.parse(localStorage.getItem('unsg_users') || '[]'); }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) return;
  try {
    const { error } = await supabaseClient.from('profiles').upsert([user], { onConflict: 'email' });
    if (error) throw error;
  } catch (e: any) {
    if (e.message?.includes('fetch')) throw e;
  }
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  try {
    const { error } = await supabaseClient.from('profiles').delete().eq('email', email);
    if (error) throw error;
  } catch (e: any) {
    if (e.message?.includes('fetch')) throw e;
  }
};

export const subscribeToClients = (callback: () => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('clients-all').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, callback).subscribe();
};

export const unsubscribeFromClients = (channel: any) => {
  if (channel) channel.unsubscribe();
};

export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient.from('system_metadata').select('*').eq('key', 'global_sync_status').single();
    return error ? null : data.value;
  } catch (e) { return null; }
};

export const subscribeToGlobalSync = (callback: (meta: any) => void) => {
  if (!supabaseClient) return null;
  return supabaseClient.channel('sync-status').on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'system_metadata', filter: 'key=eq.global_sync_status' }, (p: any) => callback(p.new.value)).subscribe();
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync: string) => {
  if (!supabaseClient) return;
  const value = { is_syncing: isSyncing, last_sync: lastSync };
  try {
    await supabaseClient.from('system_metadata').upsert([{ key: 'global_sync_status', value }], { onConflict: 'key' });
  } catch (e) {}
};

export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  try {
    const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
    return error ? 0 : count || 0;
  } catch (e) { return 0; }
};

export const fetchSanctionsBatch = async (from: number, to: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient.from('sanctions').select('*').range(from, to);
    if (error) throw error;
    return data || [];
  } catch (e) { return []; }
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void, replace: boolean = false) => {
  if (!supabaseClient) throw new Error("Registry offline.");
  const total = sanctions.length;
  if (total === 0) return;
  try {
    if (replace) {
      const { error: deleteErr } = await supabaseClient.from('sanctions').delete().neq('data_id', '_none_');
      if (deleteErr) throw deleteErr;
    }
    for (let i = 0; i < total; i += 200) {
      const rawBatch = sanctions.slice(i, i + 200);
      const batch = rawBatch.map(s => ({
        data_id: s.dataId, first_name: s.firstName, second_name: s.secondName, third_name: s.thirdName,
        last_name: s.lastName, source: s.source, reference_number: s.referenceNumber, listed_on: s.listedOn,
        nationality: s.nationality, date_of_birth: s.dateOfBirth, un_list_type: s.unListType,
        comments: s.comments, type: s.type, aliases: s.aliases, fetch_date: s.fetchDate
      }));
      const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
      if (error) throw error;
      if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
    }
  } catch (e: any) {
    if (e.message?.includes('fetch')) throw new Error("Registry cloud link severed. Check network connectivity.");
    throw e;
  }
};

export const screenEntityAgainstDb = async (client: Client, userId: string = 'System'): Promise<Client> => {
  try {
    const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
    const match = screenClient(client, candidates);
    return {
      ...client,
      riskLevel: match ? match.riskLevel : RiskLevel.NONE,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };
  } catch (e) {
    return { ...client, lastScreenedAt: new Date().toISOString() };
  }
};

import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount,
  upsertCloudSanctions,
  fetchClientsTotalCount,
  screenEntityAgainstDb,
  validateRegistrySchemaV431,
  logAuditEvent,
  fetchSystemLogs
} from './services/cloudDb';
import { OFFICIAL_UN_XML_URL } from './services/unSanctionsService';
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsRegistry from './components/SanctionsRegistry';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Client, AppSettings, UserProfile, SystemEnvironment, ScreeningProgress, SystemLog } from './types';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: false,
  syncIntervalMinutes: 0,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  environment: SystemEnvironment.PRODUCTION
};

const CLIENTS_PER_PAGE = 15;

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [clientsCount, setClientsCount] = useState(0);
  const [systemLogs, setSystemLogs] = useState<SystemLog[]>([]);
  const [currentClientsPage, setCurrentClientsPage] = useState(1);
  const [isRefreshingClients, setIsRefreshingClients] = useState(false);

  const [screeningProgress, setScreeningProgress] = useState<ScreeningProgress>({
    totalRecords: 0,
    screenedRecords: 0,
    pendingRecords: 0,
    status: 'Not Started',
    currentBatch: 0
  });

  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR' | 'SAFE_MODE'>('CONNECTING');
  const [schemaDiscrepancies, setSchemaDiscrepancies] = useState<string[]>([]);

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const loadLogs = useCallback(async () => {
    const logs = await fetchSystemLogs();
    setSystemLogs(logs);
  }, []);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    if (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
      loadSanctionsCache();
    }
  }, []);

  const loadSanctionsCache = useCallback(async () => {
    try {
      const count = await fetchSanctionsTotalCount();
      setSanctionsCount(count); 
    } catch (e) { console.error("[App] Cache Refresh Failure:", e); }
  }, []);

  const refreshClients = useCallback(async (page: number = 1) => {
    setIsRefreshingClients(true);
    try {
      const from = (page - 1) * CLIENTS_PER_PAGE;
      const to = from + CLIENTS_PER_PAGE - 1;
      const [cloudClients, count] = await Promise.all([
        fetchCloudClients(from, to),
        fetchClientsTotalCount()
      ]);
      if (cloudClients) setClients(cloudClients);
      setClientsCount(count);
      setCurrentClientsPage(page);
    } catch (e) { 
      console.error("[App] Registry Pull Failure:", e);
      setConnectionStatus('SAFE_MODE');
    } finally { setIsRefreshingClients(false); }
  }, []);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');
    setSchemaDiscrepancies([]);
    try {
      initSupabase();
      const healthy = await checkConnection();
      if (healthy) {
        const audit = await validateRegistrySchemaV431();
        if (!audit.success) {
           setConnectionStatus('SAFE_MODE');
           setSchemaDiscrepancies(audit.discrepancies || ['Structural Audit Conflict']);
        } else {
           setConnectionStatus('CONNECTED');
           await Promise.all([
             refreshClients(1),
             loadSanctionsCache(),
             loadLogs(),
             fetchGlobalSyncStatus().then(l => l && handleGlobalMetadataUpdate(l))
           ]);
           if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
           subscriptionRef.current = subscribeToClients(() => refreshClients(currentClientsPage));
           if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
           syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
        }
      } else {
        setConnectionStatus('SAFE_MODE');
      }
    } catch (e: any) { 
      setConnectionStatus('SAFE_MODE');
      refreshClients(1);
    }
    setTimeout(() => setIsBooting(false), 1500);
  }, [handleGlobalMetadataUpdate, loadSanctionsCache, refreshClients, currentClientsPage, loadLogs]);

  useEffect(() => { bootEnterpriseNode(); }, [bootEnterpriseNode]);

  const handleAddClientWithAuthoritativeScreening = async (newClient: Client) => {
    setIsRefreshingClients(true);
    try {
      const screenedClient = await screenEntityAgainstDb(newClient, currentUser?.email);
      await upsertCloudClient(screenedClient);
      await logAuditEvent('ENTITY_PROVISIONED', `Entity "${newClient["Client Name"]}" provisioned to registry.`, currentUser?.email || 'System');
      await refreshClients(currentClientsPage); 
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
        // If it was a fetch error, the client was already saved locally by upsertCloudClient shadow logic
        await refreshClients(currentClientsPage);
      } else {
        throw e;
      }
    } finally { setIsRefreshingClients(false); }
  };

  const handleDeleteClient = async (id: string) => {
    const client = clients.find(c => c.id === id);
    setIsRefreshingClients(true);
    try {
      await deleteCloudClient(id);
      await logAuditEvent('ENTITY_REVOKED', `Entity "${client?.["Client Name"] || id}" removed from registry.`, currentUser?.email || 'System');
      await refreshClients(currentClientsPage);
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
        await refreshClients(currentClientsPage);
      } else {
        alert(`Deletion Error: ${e.message}.`); 
      }
    } finally { setIsRefreshingClients(false); }
  };

  const handleUpdateClient = async (updatedClient: Client) => {
    try {
      const original = clients.find(c => c.id === updatedClient.id);
      await upsertCloudClient(updatedClient);
      if (original?.kyc_status !== updatedClient.kyc_status) {
        await logAuditEvent('KYC_STATUS_OVERRIDE', `Status for "${updatedClient["Client Name"]}" changed to ${updatedClient.kyc_status}.`, currentUser?.email || 'System');
      } else {
        await logAuditEvent('ENTITY_MODIFIED', `Data updated for entity "${updatedClient["Client Name"]}".`, currentUser?.email || 'System');
      }
      setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
      } else {
        alert("Status Update Failed: " + e.message); 
      }
    }
  };

  const handlePasswordUpdate = async (newPassword: string) => {
    if (!currentUser) return;
    try {
      const dbPayload: any = { ...currentUser };
      dbPayload.password_hash_mock = newPassword;
      dbPayload.must_change_password = false;
      delete dbPayload.password;
      delete dbPayload.confirmPassword;
      await upsertCloudUser(dbPayload);
      await logAuditEvent('PASSWORD_ROTATION', `Security policy enforced: Password updated.`, currentUser.email);
      const updatedUser = { ...currentUser, must_change_password: false, password_hash_mock: newPassword };
      setCurrentUser(updatedUser);
      localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      alert("Security Handshake Complete: Password updated successfully.");
    } catch (e: any) { alert("Failed to update password: " + e.message); }
  };

  const effectiveEnvironment = (currentUser?.id === 'SYS-ROOT') ? settings.environment : SystemEnvironment.PRODUCTION;

  if (!currentUser) {
    return <Login onLogin={(u) => { 
      setCurrentUser(u); 
      localStorage.setItem('unsg_session', JSON.stringify(u)); 
      logAuditEvent('SESSION_INITIALIZED', `User authenticated successfully.`, u.email);
    }} isCloudConnected={connectionStatus === 'CONNECTED' || connectionStatus === 'SAFE_MODE'} />;
  }

  if (currentUser.must_change_password) {
    return <PasswordUpdate user={currentUser} onUpdate={handlePasswordUpdate} />;
  }

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'} 
        isSafeMode={connectionStatus === 'SAFE_MODE'} 
        schemaFaults={schemaDiscrepancies}
        onLogout={() => { 
          logAuditEvent('SESSION_TERMINATED', `User logged out.`, currentUser.email);
          setCurrentUser(null); 
          localStorage.removeItem('unsg_session'); 
        }} 
        currentUser={currentUser} 
        onRetryConnection={() => bootEnterpriseNode()} 
        environment={effectiveEnvironment}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} totalClientsCount={clientsCount} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} />} />
          <Route path="/clients" element={<ClientManager clients={clients} totalCount={clientsCount} currentPage={currentClientsPage} onPageChange={refreshClients} isRefreshing={isRefreshingClients} onAddClient={handleAddClientWithAuthoritativeScreening} onDeleteClient={handleDeleteClient} onRefresh={() => refreshClients(currentClientsPage)} onReScreen={() => {}} onUpdateClient={handleUpdateClient} screeningProgress={screeningProgress} currentUserRole={currentUser.role} currentUserId={currentUser.id} />} />
          <Route path="/sanctions" element={<SanctionsRegistry onSyncComplete={() => loadSanctionsCache()} isCloudConnected={connectionStatus === 'CONNECTED'} initialStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} currentUser={currentUser} />} />
          <Route path="/admin" element={currentUser.is_system_admin === true ? <AdminPanel settings={settings} logs={systemLogs} onUpdateSettings={(s) => { 
            logAuditEvent('SYSTEM_SETTINGS_MODIFIED', `Environment set to ${s.environment}.`, currentUser.email);
            setSettings(s); 
            localStorage.setItem('unsg_settings', JSON.stringify(s)); 
          }} currentUser={currentUser} onLogsRefresh={loadLogs} /> : <Navigate to="/" replace />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

