// --- LOCAL STORAGE PERSISTENCE FALLBACKS ---
const getLocalClients = (): Client[] => JSON.parse(localStorage.getItem('unsg_shadow_clients') || '[]');
const saveLocalClients = (clients: Client[]) => localStorage.setItem('unsg_shadow_clients', JSON.stringify(clients));

const getLocalLogs = (): SystemLog[] => JSON.parse(localStorage.getItem('unsg_shadow_logs') || '[]');
const saveLocalLogs = (logs: SystemLog[]) => localStorage.setItem('unsg_shadow_logs', JSON.stringify(logs));

export const validateRegistrySchemaV431 = async (): Promise<{ success: boolean; error?: string; discrepancies: string[] }> => {
  if (!supabaseClient) return { success: false, error: 'Supabase client uninitialized', discrepancies: ['No active database connection'] };
  const discrepancies: string[] = [];
  try {
    const { data: verData, error: verErr } = await supabaseClient.from('system_metadata').select('value').eq('key', 'schema_version').single();
    if (verErr || !verData || !['4.3.1', '4.3.3', '4.3.4', '4.3.5', '4.3.6', '4.3.7', '4.3.8'].includes(verData.value.version)) {
      discrepancies.push(`Registry Version Conflict: Application requires v${REQUIRED_ENGINE_VERSION}.`);
    }
    return { success: discrepancies.length === 0, discrepancies };
  } catch (e: any) {
    return { success: false, error: e.message, discrepancies: [e.message] };
  }
};

export const checkConnection = async () => {
  if (!supabaseClient) return false;
  try {
    const { error } = await supabaseClient.from('clients').select('id').limit(1);
    return !error;
  } catch (err) { return false; }
};

// --- AUDIT LOGGING SERVICE ---
export const logAuditEvent = async (action: string, details: string, triggeredBy: string, status: string = 'Success') => {
  const logEntry: SystemLog = {
    id: `LOG-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
    timestamp: new Date().toISOString(),
    source: action,
    method: 'SYSTEM_AUDIT',
    status: status,
    details: details,
    triggeredBy: triggeredBy
  };

  // Always log locally for redundancy
  const logs = [logEntry, ...getLocalLogs()].slice(0, 200);
  saveLocalLogs(logs);

  if (!supabaseClient) return;
  try {
    await supabaseClient.from('system_logs').insert([logEntry]);
  } catch (e) {
    console.warn("[Audit] Cloud Persistence Unavailable, local shadow updated.");
  }
};

export const fetchSystemLogs = async (): Promise<SystemLog[]> => {
  if (!supabaseClient) return getLocalLogs();
  try {
    const { data, error } = await supabaseClient.from('system_logs').select('*').order('timestamp', { ascending: false }).limit(100);
    if (error) return getLocalLogs();
    const cloudLogs = data || [];
    // Merge and deduplicate
    return cloudLogs;
  } catch (e) {
    return getLocalLogs();
  }
};

export const logIngestionEvent = async (log: any) => {
  if (!supabaseClient) return;
  try {
    await supabaseClient.from('ingestion_logs').insert([log]);
  } catch (e) {
    console.error("[Ingestion] Log Persistence Failure:", e);
  }
};

export const fetchIngestionLogs = async (): Promise<IngestionLog[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient.from('ingestion_logs').select('*').order('timestamp', { ascending: false }).limit(50);
