  } catch (e) { return []; }
};

// --- REGISTRY SERVICES ---
export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient || !name) return [];

  // Sanitize and normalize search query
  const queryStr = name.trim().toUpperCase().replace(/[^\w\s]/gi, '');
  if (queryStr.length < 2) return [];

  try {
    const tokens = queryStr.split(/\s+/).filter(t => t.length >= 2 && !RETRIEVAL_NOISE.includes(t)).slice(0, 4);
    const filterParts: string[] = [];

    if (tokens.length === 0) {
      // Fallback for short or noisy queries
      filterParts.push(`first_name.ilike.*${queryStr}*`, `last_name.ilike.*${queryStr}*`);
    } else {
      tokens.forEach(t => {
        filterParts.push(`first_name.ilike.*${t}*`, `last_name.ilike.*${t}*`, `comments.ilike.*${t}*`);
      });
    }

    const { data, error } = await supabaseClient
      .from('sanctions')
      .select('*')
      .or(filterParts.join(','))
      .limit(150);

    if (error) throw error;

    return (data || []).map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: row.first_name,
      secondName: row.second_name,
      thirdName: row.third_name,
      lastName: row.last_name,
      source: row.source,
      referenceNumber: row.reference_number,
      listedOn: row.listed_on,
      nationality: row.nationality,
      dateOfBirth: row.date_of_birth,
      unListType: row.un_list_type,
      comments: row.comments,
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: row.type,
      fetchDate: row.fetch_date
    } as SanctionEntry));
  } catch (e: any) {
    console.error("[Search Service] Authoritative query failed:", e);
    return [];
  }
};

export const fetchCloudClients = async (from: number, to: number): Promise<Client[]> => {
  if (!supabaseClient) return getLocalClients().slice(from, to + 1);
  try {
    const { data, error } = await supabaseClient.from('clients').select('*').order('created_at', { ascending: false }).range(from, to);
    if (error) throw error;
    const cloudClients = (data || []).map((row: any) => ({ ...row, id: row.id } as Client));
    if (from === 0) saveLocalClients(cloudClients); // Cache first page
    return cloudClients;
  } catch (e) {
    return getLocalClients().slice(from, to + 1);
  }
};

export const fetchClientsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return getLocalClients().length;
  try {
    const { count, error } = await supabaseClient.from('clients').select('*', { count: 'exact', head: true });
    return error ? getLocalClients().length : count || 0;
  } catch (e) {
    return getLocalClients().length;
  }
};

export const upsertCloudClient = async (client: Client) => {
  // Always update local shadow first
  const local = getLocalClients();
  const existingIndex = local.findIndex(c => c.id === client.id);
  if (existingIndex > -1) local[existingIndex] = client;
  else local.unshift(client);
  saveLocalClients(local);

  if (!supabaseClient) return;
  try {
    const { error } = await supabaseClient.from('clients').upsert([client], { onConflict: 'id' });
    if (error) throw error;
  } catch (e: any) {
    console.warn("[Registry] Cloud Sync failed, change preserved in local shadow.", e);
    // Rethrow only if we specifically need to notify the UI of a network failure
    if (e.message?.includes('fetch')) throw e;
  }
};

export const deleteCloudClient = async (id: string) => {
  // Update local shadow
  const local = getLocalClients().filter(c => c.id !== id);
  saveLocalClients(local);

  if (!supabaseClient) return;
  try {
    const { error } = await supabaseClient.from('clients').delete().eq('id', id);
    if (error) throw error;
  } catch (e: any) {
    console.warn("[Registry] Cloud Deletion failed, local shadow updated.");
    if (e.message?.includes('fetch')) throw e;
  }
};

