export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return 0;
  try {
    const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
    return error ? 0 : count || 0;
  } catch (e) { return 0; }
};

export const fetchSanctionsBatch = async (from: number, to: number): Promise<SanctionEntry[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient.from('sanctions').select('*').range(from, to);
    if (error) throw error;
    return data || [];
  } catch (e) { return []; }
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void, replace: boolean = false) => {
  if (!supabaseClient) throw new Error("Registry offline.");
  const total = sanctions.length;
  if (total === 0) return;
  try {
    if (replace) {
      const { error: deleteErr } = await supabaseClient.from('sanctions').delete().neq('data_id', '_none_');
      if (deleteErr) throw deleteErr;
    }
    for (let i = 0; i < total; i += 200) {
      const rawBatch = sanctions.slice(i, i + 200);
      const batch = rawBatch.map(s => ({
        data_id: s.dataId, first_name: s.firstName, second_name: s.secondName, third_name: s.thirdName,
        last_name: s.lastName, source: s.source, reference_number: s.referenceNumber, listed_on: s.listedOn,
        nationality: s.nationality, date_of_birth: s.dateOfBirth, un_list_type: s.unListType,
        comments: s.comments, type: s.type, aliases: s.aliases, fetch_date: s.fetchDate
      }));
      const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
      if (error) throw error;
      if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
    }
  } catch (e: any) {
    if (e.message?.includes('fetch')) throw new Error("Registry cloud link severed. Check network connectivity.");
    throw e;
  }
};

export const screenEntityAgainstDb = async (client: Client, userId: string = 'System'): Promise<Client> => {
  try {
    const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
    const match = screenClient(client, candidates);
    return {
      ...client,
      riskLevel: match ? match.riskLevel : RiskLevel.NONE,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };
  } catch (e) {
    return { ...client, lastScreenedAt: new Date().toISOString() };
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
