/**
 * Initializes or returns the existing Supabase client.
 * Uses a singleton pattern to prevent multiple connection pools.
 */
export const initSupabase = () => {
  if (supabaseClient) return true;
  try {
    supabaseClient = createClient(MASTER_REGISTRY_URL, MASTER_REGISTRY_KEY, {
      auth: { 
        persistSession: false, 
        autoRefreshToken: false, 
        detectSessionInUrl: false 
      },
      global: {
        headers: { 'x-application-name': 'unsanctionguard-enterprise' }
      }
    });
    return true;
  } catch (e) {
    console.error(`[v${REQUIRED_ENGINE_VERSION}] Handshake Fatal:`, e);
    return false;
  }
};

