export const searchSanctionsAuthoritative = async (name: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient || !name) return [];

  const cleanName = name.trim().toUpperCase().replace(/[^\w\s]/gi, '');
  if (cleanName.length < 2) return [];

  try {
    const tokens = cleanName.split(/\s+/)
      .filter(t => t.length >= 2 && !RETRIEVAL_NOISE.includes(t))
      .map(t => t.replace(/[%_]/g, '\\$&')) 
      .slice(0, 5); 

    const filterParts: string[] = [];

    if (tokens.length === 0) {
      // Basic fallback
      filterParts.push(`first_name.ilike.*${cleanName}*`, `last_name.ilike.*${cleanName}*`);
    } else {
