      .from('sanctions')
      .select('data_id, first_name, second_name, third_name, last_name, source, reference_number, nationality, type, listed_on, un_list_type, date_of_birth')
      .range(from, to);
    if (error) throw error;

    return (data || []).map((row: any) => ({
      dataId: String(row.data_id ?? row.id ?? ''),
      firstName: row.first_name || '',
      secondName: row.second_name || '',
      thirdName: row.third_name || '',
      lastName: row.last_name || '',
      source: row.source || 'Unknown',
      referenceNumber: row.reference_number || '',
      nationality: row.nationality || '',
      type: row.type || EntityType.CORPORATE,
      listedOn: row.listed_on || '',
      unListType: row.un_list_type || '',
      dateOfBirth: row.date_of_birth || ''
    } as any));
  } catch (e) { return []; }
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void, replace: boolean = false) => {
  if (!supabaseClient) throw new Error("Registry offline.");
  const total = sanctions.length;
  if (total === 0) return;
  try {
    if (replace) {
      const { error: deleteErr } = await supabaseClient.from('sanctions').delete().neq('data_id', '_none_');
      if (deleteErr) throw deleteErr;
    }
    for (let i = 0; i < total; i += 200) {
      const rawBatch = sanctions.slice(i, i + 200);
      const batch = rawBatch.map(s => ({
        data_id: s.dataId, first_name: s.firstName, second_name: s.secondName, third_name: s.thirdName,
        last_name: s.lastName, source: s.source, reference_number: s.referenceNumber, listed_on: s.listedOn,
        nationality: s.nationality, date_of_birth: s.dateOfBirth, un_list_type: s.unListType,
        comments: s.comments, type: s.type, aliases: s.aliases, fetch_date: s.fetchDate
      }));
      const { error } = await supabaseClient.from('sanctions').upsert(batch, { onConflict: 'data_id' });
      if (error) throw error;
      if (onProgress) onProgress(Math.round(((i + batch.length) / total) * 100));
    }
  } catch (e: any) {
    if (e.message?.includes('fetch')) throw new Error("Registry cloud link severed. Check network connectivity.");
    throw e;
  }
};

export const screenEntityAgainstDb = async (client: Client, userId: string = 'System'): Promise<Client> => {
  try {
    const candidates = await searchSanctionsAuthoritative(client["Client Name"]);
    const match = screenClient(client, candidates);
    return {
      ...client,
      riskLevel: match ? match.riskLevel : RiskLevel.NONE,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };
  } catch (e) {
    return { ...client, lastScreenedAt: new Date().toISOString() };
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry, EntityType, SystemEnvironment, IngestionLog, UserRole } from '../types';
import { 
  RefreshCw, Search, ChevronLeft, ChevronRight, Database, Activity, 
  AlertCircle, Loader2, Play, Pause, Trash2, Clock, 
  ShieldCheck, CloudDownload, Cpu, CheckCircle, Zap, Upload, FileText, 
  Globe, ShieldAlert, FileJson, Info, ExternalLink, Terminal, BarChart3, ListChecks,
  History, Settings, FileWarning, ArrowUpRight, Check, Map, Layers, FileSpreadsheet,
  X, AlertTriangle, ArrowRightLeft, Shield, Landmark
} from 'lucide-react';
import { 
  fetchSanctionsBatch, 
  fetchSanctionsTotalCount, 
  upsertCloudSanctions, 
  setGlobalSyncLock, 
  logIngestionEvent,
  fetchIngestionLogs,
  searchSanctionsAuthoritative
} from '../services/cloudDb';
import { 
  fetchAndNormalize,
  detectFormat,
  parseUNSanctionsXML, 
  parseCSVToSanctions, 
  parseExcelToSanctions,
  mapFieldsToSanction,
  OFFICIAL_UN_XML_URL, 
  QATAR_NCTC_URL, 
  OPENSANCTIONS_URL 
} from '../services/unSanctionsService';

interface SanctionsRegistryProps {
  onSyncComplete: (data: SanctionEntry[], stats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string }) => void;
  isCloudConnected: boolean;
  initialStats?: { lastFetch: string; lastTest: string; lastSourceUpdate?: string };
  isGlobalSyncing?: boolean;
  environment?: SystemEnvironment;
  currentUser?: { role: UserRole; id: string };
}

type ProcessStatus = 'IDLE' | 'FETCHING' | 'VALIDATING' | 'MAPPING' | 'UPLOADING' | 'COMPLETED' | 'ERROR';

const ITEMS_PER_PAGE = 15;

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, initialStats, isGlobalSyncing, environment, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'hub' | 'audit'>('hub');
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalInDb, setTotalInDb] = useState(0);

  const [status, setStatus] = useState<ProcessStatus>('IDLE');
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successReport, setSuccessReport] = useState<{source: string, count: number, method: string, newRecords: number, updatedRecords: number} | null>(null);
  const [ingestionHistory, setIngestionHistory] = useState<IngestionLog[]>([]);

  // Mapping State
  const [rawUploadData, setRawUploadData] = useState<any[]>([]);
  const [currentMapping, setCurrentMapping] = useState<Record<string, string>>({
    dataId: '', firstName: '', lastName: '', unListType: '', referenceNumber: '', listedOn: '', comments: '', nationality: '', type: '', dateOfBirth: ''
  });
  const [mappingSource, setMappingSource] = useState<string>('');

  const [lastSourceUpdate, setLastSourceUpdate] = useState<string>(initialStats?.lastSourceUpdate || 'Never');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const refreshDbStats = useCallback(async (forceRefreshList: boolean = false) => {
    if (!isCloudConnected) return 0;
    try {
      const [count, logs] = await Promise.all([
        fetchSanctionsTotalCount(),
        fetchIngestionLogs()
      ]);
      setTotalInDb(count);
      setIngestionHistory(logs);

      // Pull initial list if search is empty or explicitly requested
      if (!searchTerm.trim() || forceRefreshList) {
        const initialBatch = await fetchSanctionsBatch(0, 199);
        setSanctions(initialBatch);
      }
      return count;
    } catch (e) { 
      console.error("[Registry] Stats Handshake Failure:", e);
      return 0; 
    }
  }, [isCloudConnected, searchTerm]);

  // Initial load
  useEffect(() => {
    refreshDbStats();
  }, [isCloudConnected]);

  // Search Logic
  useEffect(() => {
    const term = searchTerm.trim();
    if (!term) {
      if (sanctions.length < totalInDb && totalInDb > 0) refreshDbStats();
      setIsSearching(false);
      return;
    }

    const handler = setTimeout(async () => {
      if (term.length >= 2) {
        setIsSearching(true);
        try {
          const results = await searchSanctionsAuthoritative(term);
          setSanctions(results || []);
          setCurrentPage(1);
        } catch (err) {
          console.error("Registry Search Error:", err);
          setSanctions([]);
        } finally {
          setIsSearching(false);
        }
      }
    }, 500); 

    return () => clearTimeout(handler);
  }, [searchTerm]);

  const handleFileSelection = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isCloudConnected) return;
    setStatus('VALIDATING');
    setErrorMessage(null);
    setSuccessReport(null);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result;
        const format = detectFormat(typeof content === 'string' ? content : '', file.name);
        let parsedRows: any[] = [];
        if (format === 'EXCEL') parsedRows = parseExcelToSanctions(content as ArrayBuffer, file.name);
        else if (format === 'CSV') parsedRows = parseCSVToSanctions(content as string, file.name);
        else if (format === 'JSON') {
           const data = JSON.parse(content as string);
           parsedRows = Array.isArray(data) ? data : (data.entities || []);
        } else if (format === 'XML') {
           const finalData = parseUNSanctionsXML(content as string);
           return finalizeIngestion(finalData, "UN XML", "Manual Upload");
        } else throw new Error("Unrecognized data protocol.");

        if (parsedRows.length === 0) throw new Error("Empty dataset detected.");
        setRawUploadData(parsedRows);
        setMappingSource(file.name.split('.')[0].toUpperCase());
        setStatus('MAPPING');
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMessage(err.message);
      }
    };
    if (file.name.match(/\.(xlsx|xls)$/i)) reader.readAsArrayBuffer(file);
    else reader.readAsText(file);
  };

  const finalizeIngestion = async (data: SanctionEntry[], source: string, method: string) => {
    setStatus('UPLOADING');
    setUploadProgress(0);
    try {
      await setGlobalSyncLock(true, `${method}: ${source}...`);
      const count = data.length;
      await upsertCloudSanctions(data, (p) => setUploadProgress(p), true);

      const now = new Date().toLocaleString();
      await setGlobalSyncLock(false, now);
      setLastSourceUpdate(now);
      setSuccessReport({ source, count, method, newRecords: 0, updatedRecords: count });
      await logIngestionEvent({
        timestamp: new Date().toISOString(), source, method: 'Manual', status: 'Success',
        recordsProcessed: count, recordsAccepted: count, recordsRejected: 0, triggeredBy: currentUser?.id || 'System'
      });
      await refreshDbStats(true);
      setStatus('COMPLETED');
    } catch (err: any) {
      await setGlobalSyncLock(false, lastSourceUpdate);
      setErrorMessage(err.message);
      setStatus('ERROR');
    }
  };

  const handleMappingCommit = () => {
    try {
      const normalizedData = rawUploadData.map(row => mapFieldsToSanction(row, currentMapping, mappingSource));
      finalizeIngestion(normalizedData, mappingSource, "Custom Injection");
    } catch (e: any) { setErrorMessage("Mapping configuration invalid: " + e.message); }
  };

  const runAutomatedFetch = async (url: string, name: string) => {
    if (!isCloudConnected || isGlobalSyncing) return;
    setStatus('FETCHING');
    setErrorMessage(null);
    setSuccessReport(null);
    try {
      const data = await fetchAndNormalize(url, name);
      finalizeIngestion(data, name, "Direct Fetch");
    } catch (err: any) {
      setStatus('ERROR');
      setErrorMessage(`Connectivity Fault: ${err.message}`);
    }
  };

  const paginatedData = sanctions.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const totalPages = Math.ceil(sanctions.length / ITEMS_PER_PAGE);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-6 sm:p-8 rounded-[3rem] border border-gray-100 shadow-sm gap-6">
         <div className="flex items-center gap-5">
            <div className="bg-emerald-950 p-4 rounded-3xl text-emerald-400 shadow-xl"><Cpu size={28}/></div>
            <div>
               <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Sanctions Ingestion Hub</h2>
               <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Version 2.9.8 • Consolidated Node</p>
            </div>
         </div>
         <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full md:w-auto">
            <button onClick={() => setActiveTab('hub')} className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${activeTab === 'hub' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>Ingest</button>
            <button onClick={() => setActiveTab('audit')} className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${activeTab === 'audit' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>History</button>
         </div>
      </div>

      {activeTab === 'hub' && (
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
          <div className="xl:col-span-2 space-y-8">
             <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-8">
                <div className="flex items-center justify-between border-b border-gray-50 pb-6">
                   <div className="flex items-center gap-3">
                      <CloudDownload className="text-blue-600" size={20} />
                      <h3 className="text-sm font-black uppercase text-slate-900">Method 1: Direct Integration</h3>
                   </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-5">
                   {[
                     { name: 'UN Security Council', url: OFFICIAL_UN_XML_URL, icon: <Globe />, color: 'bg-blue-600', format: 'XML' },
                     { name: 'Qatar MOI (NCTC)', url: QATAR_NCTC_URL, icon: <Shield />, color: 'bg-amber-600', format: 'HTML' },
                     { name: 'OpenSanctions', url: OPENSANCTIONS_URL, icon: <FileJson />, color: 'bg-emerald-600', format: 'JSON' }
                   ].map(source => (
                     <button key={source.name} onClick={() => runAutomatedFetch(source.url, source.name)} disabled={status !== 'IDLE'} className="group p-6 rounded-[2.5rem] border border-slate-100 hover:border-blue-300 hover:bg-blue-50/30 transition-all flex flex-col items-center text-center gap-4 disabled:opacity-30">
                        <div className={`p-4 rounded-2xl bg-slate-50 text-slate-400 group-hover:${source.color} group-hover:text-white transition-all`}>{source.icon}</div>
                        <h4 className="text-[10px] font-black uppercase text-slate-800 leading-tight">{source.name}</h4>
                     </button>
                   ))}
                </div>
                {errorMessage && (
                  <div className="p-8 bg-red-50 border border-red-100 rounded-[2.5rem] space-y-4">
                     <div className="flex items-start gap-4">
                        <div className="p-3 bg-red-600 text-white rounded-2xl"><AlertTriangle size={20}/></div>
                        <div>
                           <p className="text-[10px] font-black text-red-900 uppercase">Process Interruption Detected</p>
                           <p className="text-xs font-bold text-red-700 mt-1 uppercase leading-relaxed">{errorMessage}</p>
                        </div>
                     </div>
                  </div>
                )}
                {successReport && (
                  <div className="p-8 bg-emerald-50 border border-emerald-100 rounded-[2.5rem] flex items-center gap-4">
                     <CheckCircle className="text-emerald-600" size={32}/>
                     <p className="text-xs font-black text-emerald-900 uppercase">{successReport.count} Records Ingested from {successReport.source}</p>
                  </div>
                )}
             </div>
          </div>
          <div className="space-y-8">
             <div className="bg-slate-950 p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden flex flex-col h-full justify-between border-b-8 border-emerald-500">
                <div className="relative z-10 space-y-6">
                   <div className="flex items-center gap-3">
                      <div className="bg-emerald-500/20 p-2.5 rounded-xl"><Upload className="text-emerald-400" size={20} /></div>
                      <h3 className="text-sm font-black uppercase tracking-widest">Method 2: Local Injection</h3>
                   </div>
                   <input type="file" ref={fileInputRef} onChange={handleFileSelection} className="hidden" />
                   <button onClick={() => fileInputRef.current?.click()} disabled={status !== 'IDLE'} className="w-full py-5 bg-white text-slate-950 rounded-[1.5rem] font-black text-[11px] uppercase tracking-[0.2em] flex items-center justify-center gap-3">
                      <Layers size={18} /> Select File
                   </button>
                   {status === 'UPLOADING' && (
                     <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden mt-4">
                        <div className="h-full bg-emerald-400 transition-all duration-300" style={{ width: `${uploadProgress}%` }} />
                     </div>
                   )}
                </div>
             </div>
          </div>
        </div>
      )}

      {status === 'MAPPING' && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[200] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] w-full max-w-4xl shadow-2xl overflow-hidden flex flex-col h-[85vh]">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center shrink-0">
                 <h3 className="text-xl font-black uppercase">Schema Alignment</h3>
                 <button onClick={() => setStatus('IDLE')} className="p-3 bg-white/10 rounded-full"><X size={24}/></button>
              </div>
              <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8 bg-gray-50/50">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {Object.keys(currentMapping).map(field => (
                       <div key={field} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm space-y-2">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{field}</label>
                          <select value={currentMapping[field]} onChange={(e) => setCurrentMapping({...currentMapping, [field]: e.target.value})} className="w-full bg-slate-50 rounded-xl py-3 px-4 text-xs font-bold">
                             <option value="">-- No Mapping --</option>
                             {Object.keys(rawUploadData[0] || {}).map(col => <option key={col} value={col}>{col}</option>)}
                          </select>
                       </div>
                    ))}
                 </div>
              </div>
              <div className="p-8 border-t bg-white flex justify-end gap-3 shrink-0">
                 <button onClick={handleMappingCommit} className="px-12 py-4 bg-emerald-800 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em]">Commit Ingestion</button>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'audit' && (
        <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-8 animate-in slide-in-from-right-4 duration-500">
           <h3 className="text-lg font-black text-slate-900 uppercase">Access Logs</h3>
           <div className="overflow-x-auto">
              <table className="w-full text-left min-w-[900px]">
                 <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                    <tr><th className="px-6 py-5">Timestamp</th><th className="px-6 py-5">Source</th><th className="px-6 py-5">Status</th><th className="px-6 py-5 text-right">Records</th></tr>
                 </thead>
                 <tbody className="divide-y divide-slate-50">
                    {ingestionHistory.map(log => (
                       <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                          <td className="px-6 py-5 text-xs font-bold text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                          <td className="px-6 py-5 font-black text-slate-900 text-sm">{log.source}</td>
                          <td className="px-6 py-5"><span className={`px-2 py-1 text-[8px] font-black uppercase rounded-md ${log.status === 'Success' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>{log.status}</span></td>
                          <td className="px-6 py-5 text-right text-xs font-black text-slate-900">{log.recordsProcessed} Hits</td>
                       </tr>
                    ))}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      <div className="space-y-6">
         <div className="bg-white p-4 rounded-[2.5rem] shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 w-full">
               <span className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300">
                 <Search size={20}/>
               </span>
               <input 
                 type="text" 
                 placeholder="Search Authoritative Master Cache (e.g. AEROCARIBBEAN AIRLINES)..." 
                 className="w-full pl-16 pr-12 py-5 bg-gray-50/50 rounded-[2rem] border-none outline-none text-xs font-bold focus:ring-2 focus:ring-emerald-800 transition-all" 
                 value={searchTerm} 
                 onChange={(e) => setSearchTerm(e.target.value)} 
               />
               {isSearching && <Loader2 className="absolute right-6 top-1/2 -translate-y-1/2 animate-spin text-emerald-800" size={20}/>}
            </div>
            <div className="px-6 py-3 rounded-2xl bg-emerald-50 border border-emerald-100 flex items-center gap-3 whitespace-nowrap">
               <Landmark className="text-emerald-800" size={16}/>
               <div className="flex flex-col">
                  <span className="text-[10px] font-black text-emerald-800 uppercase tracking-widest leading-none">Total Registry</span>
                  <span className="text-xs font-black text-emerald-950 mt-0.5">{totalInDb.toLocaleString()} Synchronized Identities</span>
               </div>
            </div>
         </div>
         <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
            <div className="overflow-x-auto custom-scrollbar">
               <table className="w-full text-left min-w-[1000px]">
                  <thead className="bg-gray-50/50 border-b">
                     <tr><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">First Name</th><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Last Name</th><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Nationality</th><th className="px-10 py-7 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Authority</th></tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50 relative min-h-[200px]">
                     {isSearching ? (
                        <tr>
                          <td colSpan={4} className="py-24 text-center">
                             <div className="flex flex-col items-center gap-4">
                                <Loader2 className="animate-spin text-emerald-800" size={40}/>
                                <p className="text-xs font-black uppercase tracking-[0.3em] text-emerald-800">Querying Master Database...</p>
                             </div>
                          </td>
                        </tr>
                     ) : paginatedData.length > 0 ? (
                        paginatedData.map(entry => (
                           <tr key={entry.dataId} className="hover:bg-emerald-50/20 transition-colors group">
                              <td className="px-10 py-6 font-black text-slate-950 text-sm uppercase">{entry.firstName}</td>
                              <td className="px-10 py-6 font-black text-slate-950 text-sm uppercase">{entry.lastName}</td>
                              <td className="px-10 py-6 font-black text-[10px] text-slate-600 uppercase tracking-widest">{entry.nationality || 'N/A'}</td>
                              <td className="px-10 py-6 text-right"><span className="px-3 py-1 text-[8px] font-black uppercase border border-slate-100 text-slate-400 bg-white group-hover:text-emerald-800 transition-all">{entry.source}</span></td>
                           </tr>
                        ))
                     ) : (
                       <tr>
                         <td colSpan={4} className="py-24 text-center">
                            <div className="flex flex-col items-center gap-4">
                               <div className="p-4 bg-gray-50 rounded-full"><Search size={40} className="text-gray-200"/></div>
                               <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">No records found in authoritative cache</p>
                               <p className="text-[9px] font-bold text-gray-300 uppercase tracking-widest">Spelling Mismatch? Try a broader search term.</p>
                            </div>
                         </td>
                       </tr>
                     )}
                  </tbody>
               </table>
            </div>
            {sanctions.length > ITEMS_PER_PAGE && (
              <div className="px-10 py-6 border-t border-gray-100 flex justify-between items-center bg-gray-50/30">
                 <div className="text-[10px] font-black text-gray-400 uppercase">Page {currentPage} of {totalPages}</div>
                 <div className="flex gap-2">
                    <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="p-2 border rounded-xl bg-white hover:bg-gray-50 disabled:opacity-30 transition-all"><ChevronLeft size={18}/></button>
                    <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="p-2 border rounded-xl bg-white hover:bg-gray-50 disabled:opacity-30 transition-all"><ChevronRight size={18}/></button>
                 </div>
              </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default SanctionsRegistry;

import { createClient } from '@supabase/supabase-js';
