// --- REGISTRY VALIDATION ---
export const validateRegistrySchemaV431 = async (): Promise<{ success: boolean; error?: string; discrepancies: string[] }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { success: false, error: 'Supabase client uninitialized', discrepancies: ['No active database connection'] };

  const discrepancies: string[] = [];
  try {
    const { data: verData, error: verErr } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'schema_version')
      .maybeSingle();

    if (verErr) throw verErr;

    if (!verData || !['4.3.1', '4.3.3', '4.3.4', '4.3.5', '4.3.6', '4.3.7', '4.3.8'].includes(verData.value?.version)) {
      discrepancies.push(`Incompatible Registry Version (v${REQUIRED_ENGINE_VERSION} series required). Detected: ${verData?.value?.version || 'None'}`);
    }
    return { success: discrepancies.length === 0, discrepancies };
  } catch (e: any) {
    return { success: false, error: e.message, discrepancies: [e.message] };
  }
};

