    const batch = sanctions.slice(i, i + BATCH_SIZE);
    const { error } = await supabaseClient.from('sanctions').upsert(batch);
    if (error) throw error;
    if (onProgress) onProgress(Math.round(((i + batch.length) / sanctions.length) * 100));
  }
