// --- SCREENING ENGINE SERVICE ---
export const screenEntityAgainstDb = async (client: Client, triggeredBy: string = 'System'): Promise<Client> => {
  if (!supabaseClient) return { ...client, riskLevel: RiskLevel.NONE };

  try {
    const term = client["Client Name"].trim();
    const searchTerms = term.split(/\s+/).filter(t => t.length > 2);

    // Fetch potential candidates based on name fragments using correct SQL columns
    const orFilter = searchTerms.map(t => `first_name.ilike.%${t}%,last_name.ilike.%${t}%`).join(',');
    const { data: candidates, error } = await supabaseClient
      .from('sanctions')
      .select('*')
      .or(orFilter);

    if (error) throw error;

    // Map candidates to camelCase for the screening engine
    const mappedCandidates: SanctionEntry[] = (candidates || []).map((row: any) => ({
      dataId: String(row.data_id || row.dataId || ''),
      firstName: row.first_name || row.firstName || '',
      secondName: row.second_name || row.secondName || '',
      thirdName: row.third_name || row.thirdName || '',
      lastName: row.last_name || row.lastName || '',
      source: row.source || 'Unknown',
      referenceNumber: row.reference_number || row.referenceNumber || '',
      listedOn: row.listed_on || row.listedOn || '',
      comments: row.comments || '',
      nationality: row.nationality || '',
      dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: row.type || EntityType.CORPORATE,
      fetchDate: row.fetch_date || row.fetchDate || ''
    }));

    const match = screenClient(client, mappedCandidates);
    const updatedClient = {
      ...client,
      riskLevel: match ? match.riskLevel : RiskLevel.NONE,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };

    if (match && match.riskLevel === RiskLevel.HIGH) {
      await logAuditEvent('HIGH_RISK_MATCH_DETECTED', `Match detected for "${client["Client Name"]}" against ${match.sanctionId}.`, triggeredBy, 'Alert');
    }

    return updatedClient;
  } catch (e) {
    console.error("Screening Failure:", e);
    return { ...client, riskLevel: RiskLevel.NONE };
  }
};

