/**
 * REBUILT AUTHORITATIVE SEARCH (v4.5.0 Enterprise Rebuild)
 * 
 * Capability: Full identity evaluation across all textual and castable columns.
 * Columns Covered: first_name, second_name, third_name, last_name, aliases, 
 * reference_number, data_id, nationality, date_of_birth, source, comments, un_list_type.
 * 
 * Architecture: Optimized PostgreSQL ILIKE construct via PostgREST OR filter.
 */
export const searchSanctionsAuthoritative = async (term: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient || !term) return [];

  const cleanTerm = term.trim().replace(/['"%;]/g, ''); // Basic sanitization
  if (cleanTerm.length < 2) return [];

  try {
    // 1. Construct the Universal Multi-Column Filter
    // Note: aliases is often stored as JSONB, casting to text allows pattern matching
    const searchColumns = [
      'first_name', 'second_name', 'third_name', 'last_name',
      'aliases::text', 'reference_number', 'data_id', 'comments',
      'nationality', 'date_of_birth', 'source', 'un_list_type'
    ];

    const orFilter = searchColumns.map(col => `${col}.ilike.%${cleanTerm}%`).join(',');

    // 2. Execute authoritative database query
    const { data, error } = await supabaseClient
      .from('sanctions')
      .select('*')
      .or(orFilter)
      .limit(300); // Increased limit for enterprise search depth

    if (error) throw error;

    const resultCount = data?.length || 0;

    // 3. Traceability: Log the audit event for compliance
    // We attempt this async to not block the user's result delivery
    logAuditEvent('SANCTIONS_QUERY_EXECUTED', `Term: "${cleanTerm}" | Results: ${resultCount}`, 'User-Initiated', 'Audit');

