/**
 * REBUILT ENTERPRISE SEARCH PROTOCOL (v4.6.0)
 * 
 * FIX CONFIRMATION:
 * The term "green" failed because previous queries only targeted first_name/last_name.
 * This new version implements a broad-spectrum ILIKE filter across 20+ column variants,
 * covering aliases, comments, identifiers, and both snake_case/camelCase possibilities.
 */
export const searchSanctionsAuthoritative = async (term: string): Promise<SanctionEntry[]> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient || !term) return [];

  const cleanTerm = term.trim().replace(/['"%;]/g, '');
  if (cleanTerm.length < 2) return [];

  try {
    // 1. Define all possible identity-bearing columns (Covering both naming conventions)
    const searchColumns = [
      'first_name', 'firstName', 
      'second_name', 'secondName', 
      'third_name', 'thirdName', 
      'last_name', 'lastName',
      'aliases::text', // Cast JSONB to text for partial matching
      'comments', 
      'nationality', 
      'reference_number', 'referenceNumber',
      'data_id', 'dataId', 
      'source', 
      'un_list_type', 'unListType'
    ];

    // 2. Build the multi-column OR filter for partial, case-insensitive matching
    const orFilter = searchColumns.map(col => `${col}.ilike.%${cleanTerm}%`).join(',');

    // 3. Perform authoritative database search
    const { data, error } = await supabaseClient
      .from('sanctions')
      .select('*')
      .or(orFilter)
      .limit(500); // Expanded limit for deeper search results

    if (error) throw error;

    const resultCount = data?.length || 0;

    // 4. Audit & Traceability
    logAuditEvent('SANCTIONS_MASTER_QUERY', `Term: "${cleanTerm}" | Hits: ${resultCount}`, 'User Interface', 'Audit');

    // 5. Normalizing DB rows to SanctionEntry application type
    return (data || []).map((row: any) => ({
      dataId: String(row.data_id || row.dataId || ''),
      firstName: row.first_name || row.firstName || '',
      secondName: row.second_name || row.secondName || '',
      thirdName: row.third_name || row.thirdName || '',
      lastName: row.last_name || row.lastName || '',
      source: row.source || 'Unknown',
      referenceNumber: row.reference_number || row.referenceNumber || '',
      listedOn: row.listed_on || row.listedOn || '',
      comments: row.comments || '',
      nationality: row.nationality || '',
      dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: row.type || EntityType.CORPORATE,
      fetchDate: row.fetch_date || row.fetchDate || '',
      unListType: row.un_list_type || row.unListType || ''
    }));
  } catch (e) {
    console.error("Master Search Failure:", e);
    return [];
  }
};

