  } catch (e) { return JSON.parse(localStorage.getItem('unsg_users') || '[]'); }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('profiles').upsert(user);
  if (error) throw error;
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('profiles').delete().eq('email', email);
  if (error) throw error;
};

// --- GLOBAL SYNC & LOCKS ---
export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'global_sync_state')
      .maybeSingle();
    if (error) return null;
    return data?.value || null;
  } catch (e) { return null; }
};

export const subscribeToGlobalSync = (callback: (meta: any) => void) => {
  if (!supabaseClient) return { unsubscribe: () => {} };
  return supabaseClient
    .channel('global-sync')
    .on('postgres_changes', { event: '*', schema: 'public', table: 'system_metadata', filter: 'key=eq.global_sync_state' }, (payload: any) => {
      callback(payload.new?.value);
    })
    .subscribe();
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync: string) => {
  if (!supabaseClient) return;
  const value = { is_syncing: isSyncing, last_sync: lastSync };
  await supabaseClient
    .from('system_metadata')
    .upsert({ key: 'global_sync_state', value });
};

// --- SCREENING ENGINE SERVICE ---
export const screenEntityAgainstDb = async (client: Client, triggeredBy: string = 'System'): Promise<Client> => {
  if (!supabaseClient) return { ...client, riskLevel: RiskLevel.NONE };

  try {
    const term = client["Client Name"].trim();
    // Use authoritative search for screening intersection
    const response = await searchSanctionsAuthoritative(term, 0, 99);
    const candidates = response.data;

    const match = screenClient(client, candidates);
    const updatedClient = {
      ...client,
      riskLevel: match ? match.riskLevel : RiskLevel.NONE,
      matches: match ? [match.sanctionId] : [],
      lastScreenedAt: new Date().toISOString()
    };

    if (match && match.riskLevel === RiskLevel.HIGH) {
      await logAuditEvent('HIGH_RISK_MATCH_DETECTED', `Match detected for "${client["Client Name"]}" against ${match.sanctionId}.`, triggeredBy, 'Alert');
    }

    return updatedClient;
  } catch (e) {
    console.error("Screening Failure:", e);
    return { ...client, riskLevel: RiskLevel.NONE };
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry, EntityType, SystemEnvironment, IngestionLog, UserRole } from '../types';
