export const upsertCloudClient = async (client: Client) => {
  const local = getLocalClients();
  const index = local.findIndex(c => c.id === client.id);
  if (index >= 0) local[index] = client;
  else local.push(client);
  saveLocalClients(local);

  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').upsert(client);
