/**
 * RESILIENT AUTHORITATIVE SEARCH (v5.8.0 FAIL-SAFE RESET)
 * 
 * Capability: Universal pattern matching across available schema.
 * Strategy: Falls back to a high-confidence column set if the exhaustive query fails 
 * due to missing columns in the remote DB environment.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/['"%;]/g, '').toLowerCase();
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  // CORE SEARCH HELPER
  const executeQuery = async (cols: string[]) => {
    const filter = cols.map(c => `${c}.ilike.%${cleanTerm}%`).join(',');
    return await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filter)
      .order('data_id', { ascending: true })
      .range(from, to);
  };

  try {
    // 1. ATTEMPT EXHAUSTIVE SEARCH (V5.7.0 Strategy)
    const exhaustiveCols = [
      'first_name', 'last_name', 'comments', 'reference_number', 
      'nationality', 'source', 'un_list_type', 'data_id'
    ];

    let { data, count, error } = await executeQuery(exhaustiveCols);

    // 2. FAIL-SAFE FALLBACK
    // If PostgREST returns 400 (Bad Request), it's usually because a column name is wrong.
    if (error) {
      console.warn("[SearchEngine] Exhaustive Query rejected. Falling back to Core Identity columns.");
      const coreCols = ['first_name', 'last_name', 'comments'];
      const fallback = await executeQuery(coreCols);
      data = fallback.data;
      count = fallback.count;
      if (fallback.error) throw fallback.error;
    }

    const resultCount = count || 0;
    logAuditEvent('SEARCH_AUTHORITATIVE_EXECUTED', `Term: "${cleanTerm}" | Hits: ${resultCount}`, 'Compliance-Node', 'Audit');

    // 3. DETERMINISTIC MAPPING
    const normalizedData = (data || []).map((row: any) => ({
      dataId: String(row.data_id || row.dataId || ''),
      firstName: row.first_name || row.firstName || '',
      secondName: row.second_name || row.secondName || '',
      thirdName: row.third_name || row.thirdName || '',
      lastName: row.last_name || row.lastName || '',
      source: row.source || 'Unknown',
      referenceNumber: row.reference_number || row.referenceNumber || '',
      listedOn: row.listed_on || row.listedOn || '',
      comments: row.comments || '',
      nationality: row.nationality || '',
      dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: row.type || EntityType.CORPORATE,
      fetchDate: row.fetch_date || row.fetchDate || '',
      unListType: row.un_list_type || row.unListType || ''
    }));

    return { data: normalizedData, count: resultCount };
  } catch (e) {
    console.error("Critical Resilient Search Failure (v5.8.0):", e);
    return { data: [], count: 0 };
  }
};

