                 </tbody>
              </table>
           </div>
        </div>
      )}

      <div className="space-y-6">
         <div className="bg-white p-4 rounded-[2.5rem] shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-4 items-center">
            <div className="relative flex-1 w-full">
               <span className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300">
                 <Search size={20}/>
               </span>
               <input 
                 type="text" 
                 placeholder="Search Authoritative Cache (e.g. GREEN PINE, AEROCARIBBEAN)..." 
                 className="w-full pl-16 pr-12 py-5 bg-gray-50/50 rounded-[2rem] border-none outline-none text-xs font-bold focus:ring-2 focus:ring-emerald-800 transition-all" 
                 value={searchTerm} 
                 onChange={(e) => setSearchTerm(e.target.value)} 
               />
               {isSearching && <Loader2 className="absolute right-6 top-1/2 -translate-y-1/2 animate-spin text-emerald-800" size={20}/>}
            </div>
            <div className="px-6 py-3 rounded-2xl bg-emerald-50 border border-emerald-100 flex items-center gap-3 whitespace-nowrap">
               <Landmark className="text-emerald-800" size={16}/>
               <div className="flex flex-col">
                  <span className="text-[10px] font-black text-emerald-800 uppercase tracking-widest leading-none">Total Registry</span>
                  <span className="text-xs font-black text-emerald-950 mt-0.5">{totalInDb.toLocaleString()} Synchronized Identities</span>
               </div>
            </div>
         </div>
         <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
            <div className="overflow-x-auto custom-scrollbar">
               <table className="w-full text-left min-w-[1000px]">
                  <thead className="bg-gray-50/50 border-b">
                     <tr><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">First Name / Entity Name</th><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Last Name</th><th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Nationality</th><th className="px-10 py-7 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Authority</th></tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50 relative min-h-[200px]">
                     {isSearching ? (
                        <tr>
                          <td colSpan={4} className="py-24 text-center">
                             <div className="flex flex-col items-center gap-4">
                                <Loader2 className="animate-spin text-emerald-800" size={40}/>
                                <p className="text-xs font-black uppercase tracking-[0.3em] text-emerald-800">Querying Master Database...</p>
                             </div>
                          </td>
                        </tr>
                     ) : paginatedData.length > 0 ? (
                        paginatedData.map(entry => (
                           <tr key={entry.dataId} className="hover:bg-emerald-50/20 transition-colors group">
                              <td className="px-10 py-6 font-black text-slate-950 text-sm uppercase">{entry.firstName}</td>
                              <td className="px-10 py-6 font-black text-slate-950 text-sm uppercase">{entry.lastName}</td>
                              <td className="px-10 py-6 font-black text-[10px] text-slate-600 uppercase tracking-widest">{entry.nationality || 'N/A'}</td>
                              <td className="px-10 py-6 text-right"><span className="px-3 py-1 text-[8px] font-black uppercase border border-slate-100 text-slate-400 bg-white group-hover:text-emerald-800 transition-all">{entry.source}</span></td>
                           </tr>
                        ))
                     ) : (
                       <tr>
                         <td colSpan={4} className="py-24 text-center">
                            <div className="flex flex-col items-center gap-4">
                               <div className="p-4 bg-gray-50 rounded-full"><Search size={40} className="text-gray-200"/></div>
                               <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">No matches found for "{searchTerm}"</p>
                               <p className="text-[9px] font-bold text-gray-300 uppercase tracking-widest">Database Population: {totalInDb.toLocaleString()} records indexed.</p>
                            </div>
                         </td>
                       </tr>
                     )}
                  </tbody>
               </table>
            </div>
            {totalMatches > ITEMS_PER_PAGE && (
              <div className="px-10 py-6 border-t border-gray-100 flex justify-between items-center bg-gray-50/30">
                 <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                   {totalMatches.toLocaleString()} results • Page {currentPage} of {totalPages}
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1 || isSearching} className="p-2 border rounded-xl bg-white hover:bg-gray-50 disabled:opacity-30 transition-all"><ChevronLeft size={18}/></button>
                    <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages || isSearching} className="p-2 border rounded-xl bg-white hover:bg-gray-50 disabled:opacity-30 transition-all"><ChevronRight size={18}/></button>
                 </div>
              </div>
            )}
         </div>
      </div>
    </div>
  );
};

