/**
 * v8.0.0 AUTHORITATIVE SEARCH ENGINE
 * 
 * Capability: Absolute space-tolerant matching for UN identities (e.g., "GREEN PINE").
 * Logic: Fixed PostgREST quoting ("%pattern%") and conversion of spaces to wildcards.
 * Resiliency: Silent fallback to core columns if broad query fails due to DB schema drifts.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/[%,;]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  // Transform spaces into wildcards to catch "GREEN PINE" vs "GREEN-PINE" etc.
  const searchPattern = `%${cleanTerm.split(/\s+/).join('%')}%`;

  const executeSearch = async (cols: string[]) => {
    // CRITICAL: Double quotes are required inside the .or() string for PostgREST to parse spaces correctly
    const filter = cols.map(c => `${c}.ilike."${searchPattern}"`).join(',');
    return await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filter)
      .order('data_id', { ascending: true })
      .range(from, to);
  };

  try {
    // 1. BROAD SEARCH (Preferred)
    const targetCols = ['first_name', 'last_name', 'comments', 'reference_number', 'nationality', 'source', 'data_id'];
    let { data, count, error } = await executeSearch(targetCols);

    // 2. FALLBACK SEARCH (If broad fails or returns nothing unexpectedly)
    if (error || (!data || data.length === 0)) {
      if (error) console.warn("[SearchEngine v8] Broad query fault, retrying core columns...");
      const coreCols = ['first_name', 'last_name', 'comments'];
      const fallback = await executeSearch(coreCols);
      data = fallback.data;
      count = fallback.count;
      if (fallback.error && error) throw error; // If both fail, throw original
    }

    const resultCount = count || 0;
    logAuditEvent('SEARCH_AUTHORITATIVE_V8', `Term: "${cleanTerm}" | Hits: ${resultCount}`, 'Compliance-Node', 'Audit');

    const normalizedData = (data || []).map((row: any) => ({
      dataId: String(row.data_id || row.dataId || ''),
      firstName: row.first_name || row.firstName || '',
      secondName: row.second_name || row.secondName || '',
      thirdName: row.third_name || row.thirdName || '',
      lastName: row.last_name || row.lastName || '',
      source: row.source || 'Unknown',
      referenceNumber: row.reference_number || row.referenceNumber || '',
      listedOn: row.listed_on || row.listedOn || '',
      comments: row.comments || '',
      nationality: row.nationality || '',
      dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: row.type || EntityType.CORPORATE,
      fetchDate: row.fetch_date || row.fetchDate || '',
      unListType: row.un_list_type || row.unListType || ''
    }));

    return { data: normalizedData, count: resultCount };
  } catch (e) {
    console.error("Critical Authoritative Search Failure (v8.0.0):", e);
    return { data: [], count: 0 };
  }
};

