/**
 * v9.0.0 AUTHORITATIVE SEARCH ENGINE
 * 
 * Capability: Absolute standard SQL matching for multi-word identities (e.g., "GREEN PINE").
 * Logic: Removed internal double-quoting in ilike strings to avoid literal quote matching.
 * Resiliency: Automatic fallback to verified columns with explicit error reporting.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  // Clean term for search: maintain spaces but remove SQL control chars
  const cleanTerm = term.trim().replace(/[%,;()]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  const executeSearch = async (cols: string[]) => {
    // PostgREST ilike pattern: NO QUOTES. Spaces are naturally delimited by commas in .or().
    // Pattern "%term%" matches anywhere.
    const filter = cols.map(c => `${c}.ilike.%${cleanTerm}%`).join(',');
    return await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filter)
      .order('data_id', { ascending: true })
      .range(from, to);
  };

  try {
    const targetCols = ['first_name', 'last_name', 'comments', 'reference_number', 'nationality'];
    let { data, count, error } = await executeSearch(targetCols);

    if (error) {
      console.error("[SearchEngine v9] Query Exception:", error);
      // Fallback: Minimum set of guaranteed columns
      const fallback = await executeSearch(['first_name', 'last_name']);
      data = fallback.data;
      count = fallback.count;
      if (fallback.error) throw fallback.error;
    }

    const resultCount = count || 0;
    logAuditEvent('SEARCH_AUTHORITATIVE_V9', `Term: "${cleanTerm}" | Hits: ${resultCount}`, 'Compliance-Node', 'Audit');

    const normalizedData = (data || []).map((row: any) => ({
      dataId: String(row.data_id || row.dataId || ''),
      firstName: row.first_name || row.firstName || '',
      secondName: row.second_name || row.secondName || '',
      thirdName: row.third_name || row.thirdName || '',
      lastName: row.last_name || row.lastName || '',
      source: row.source || 'Unknown',
      referenceNumber: row.reference_number || row.referenceNumber || '',
      listedOn: row.listed_on || row.listedOn || '',
      comments: row.comments || '',
      nationality: row.nationality || '',
      dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
      aliases: Array.isArray(row.aliases) ? row.aliases : [],
      type: row.type || EntityType.CORPORATE,
      fetchDate: row.fetch_date || row.fetchDate || '',
      unListType: row.un_list_type || row.unListType || ''
    }));

    return { data: normalizedData, count: resultCount };
  } catch (e) {
    console.error("Critical Authoritative Search Failure (v9.0.0):", e);
    return { data: [], count: 0 };
  }
};

