export const fetchCloudClients = async (from: number, to: number): Promise<Client[]> => {
  if (!supabaseClient) return getLocalClients().slice(from, to + 1);
  try {
    const { data, error } = await supabaseClient
      .from('clients')
      .select('*')
      .order('created_at', { ascending: false })
      .range(from, to);
    if (error) throw error;
    return data || [];
  } catch (e) {
    return getLocalClients().slice(from, to + 1);
  }
};

export const fetchClientsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) return getLocalClients().length;
  try {
    const { count, error } = await supabaseClient
      .from('clients')
      .select('*', { count: 'exact', head: true });
    if (error) throw error;
    return count || 0;
  } catch (e) {
    return getLocalClients().length;
  }
};

export const upsertCloudClient = async (client: Client) => {
  const local = getLocalClients();
  const index = local.findIndex(c => c.id === client.id);
  if (index >= 0) local[index] = client;
  else local.push(client);
  saveLocalClients(local);

  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').upsert(client);
  if (error) throw error;
};

export const deleteCloudClient = async (id: string) => {
  const local = getLocalClients().filter(c => c.id !== id);
  saveLocalClients(local);

  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('clients').delete().eq('id', id);
  if (error) throw error;
};

export const subscribeToClients = (callback: () => void) => {
  if (!supabaseClient) return null;
  return supabaseClient
    .channel('clients-all')
    .on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, callback)
    .subscribe();
};

export const unsubscribeFromClients = (subscription: any) => {
  if (subscription) subscription.unsubscribe();
};

