/**
 * v11.0.0 AUTHORITATIVE SEARCH ENGINE (DEEP SCAN)
 * 
 * Features:
 * 1. Space-to-Wildcard: Replaces spaces with % to find multi-word matches despite spacing variation.
 * 2. Internal Quoting: Mandatory double-quotes for ILIKE strings in .or() filters.
 * 3. Schema Resiliency: Searches across 7 different column names.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/[%,;()]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  // Normalize term: "GREEN PINE" -> "%GREEN%PINE%"
  const searchPattern = `%${cleanTerm.split(/\s+/).join('%')}%`;

  try {
    // List of columns to check
    const cols = ['first_name', 'last_name', 'second_name', 'third_name', 'reference_number', 'comments', 'data_id'];

    // Construct PostgREST .or filter with double-quoted patterns
    const filterStr = cols.map(c => `${c}.ilike."${searchPattern}"`).join(',');

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterStr)
      .order('first_name', { ascending: true })
      .range(from, to);

    if (error) {
      console.error("[SearchEngine v11] Query Error:", error);
      // Panic Fallback: Minimum search
      const minFilter = `first_name.ilike."${searchPattern}",last_name.ilike."${searchPattern}"`;
      const fallback = await supabaseClient.from('sanctions').select('*', { count: 'exact' }).or(minFilter).range(from, to);
      if (fallback.error) throw fallback.error;
      return { 
        data: (fallback.data || []).map(row => mapRowToEntry(row)), 
        count: fallback.count || 0 
      };
    }

    return { 
      data: (data || []).map(row => mapRowToEntry(row)), 
      count: count || 0 
    };
  } catch (e) {
    console.error("Critical Authoritative Search Failure (v11.0.0):", e);
    return { data: [], count: 0 };
  }
};

const mapRowToEntry = (row: any): SanctionEntry => ({
  dataId: String(row.data_id || row.dataId || ''),
  firstName: row.first_name || row.firstName || '',
  secondName: row.second_name || row.secondName || '',
  thirdName: row.third_name || row.thirdName || '',
  lastName: row.last_name || row.lastName || '',
  source: row.source || 'Unknown',
  referenceNumber: row.reference_number || row.referenceNumber || '',
  listedOn: row.listed_on || row.listedOn || '',
  comments: row.comments || '',
  nationality: row.nationality || '',
  dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
  aliases: Array.isArray(row.aliases) ? row.aliases : [],
  type: row.type || EntityType.CORPORATE,
  fetchDate: row.fetch_date || row.fetchDate || '',
  unListType: row.un_list_type || row.unListType || ''
});

