};

// --- AUDIT LOGGING SERVICE ---
export const logAuditEvent = async (action: string, details: string, triggeredBy: string, status: string = 'Success') => {
  const logEntry: SystemLog = {
    id: `LOG-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
    timestamp: new Date().toISOString(),
    source: action,
    method: 'SYSTEM_AUDIT',
    status: status,
    details: details,
    triggeredBy: triggeredBy
  };

  const logs = [logEntry, ...getLocalLogs()].slice(0, 200);
  saveLocalLogs(logs);

  if (!supabaseClient) return;
  try {
    await supabaseClient.from('system_logs').insert([logEntry]);
  } catch (e) {
    console.warn("[Audit] Cloud Persistence Unavailable, local shadow updated.");
  }
};

export const fetchSystemLogs = async (): Promise<SystemLog[]> => {
  if (!supabaseClient) return getLocalLogs();
  try {
    const { data, error } = await supabaseClient
      .from('system_logs')
      .select('*')
      .order('timestamp', { ascending: false })
      .limit(100);
    if (error) return getLocalLogs();
    return data || [];
  } catch (e) {
    return getLocalLogs();
  }
};

