/**
 * v13.0.0 AUTHORITATIVE SEARCH ENGINE (ADAPTIVE FULL-SCAN)
 * 
 * Major Fixes for "No Results" anomaly:
 * 1. PostgREST Quoting: Removed mandatory internal double-quotes in .or() filters.
 * 2. Token Matching: Falls back to matching first word if phrase match fails.
 * 3. Telemetry: Logs exactly what query is sent to Supabase.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/[%,;()]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  // Strategy 1: Phrase Match (e.g. %GREEN%PINE%)
  const tokens = cleanTerm.split(/\s+/);
  const searchPattern = `%${tokens.join('%')}%`;

  console.log(`[SearchEngine v13] Interrogating registry for phrase: "${searchPattern}"`);

  try {
    const cols = ['first_name', 'last_name', 'second_name', 'third_name', 'reference_number', 'comments', 'data_id'];

    // Construct filter string: "first_name.ilike.%green%,last_name.ilike.%green%..."
    // NOTE: We do NOT wrap pattern in double quotes unless it contains a comma.
    const filterStr = cols.map(c => `${c}.ilike.${searchPattern}`).join(',');

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterStr)
      .order('first_name', { ascending: true })
      .range(from, to);

    if (error) {
       console.error("[SearchEngine v13] API Error:", error.message);
       throw error;
    }

    // Strategy 2: If no results for phrase, and it was a multi-word search, try matching first word
    if ((!data || data.length === 0) && tokens.length > 1) {
       console.warn(`[SearchEngine v13] Phrase yielded zero hits. Dropping to token-level scan for: "${tokens[0]}"`);
       const fallbackPattern = `%${tokens[0]}%`;
       const fallbackFilter = cols.map(c => `${c}.ilike.${fallbackPattern}`).join(',');

       const fallback = await supabaseClient
         .from('sanctions')
         .select('*', { count: 'exact' })
         .or(fallbackFilter)
         .order('first_name', { ascending: true })
         .range(from, to);

       if (!fallback.error && fallback.data && fallback.data.length > 0) {
          return { data: fallback.data.map(row => mapRowToEntry(row)), count: fallback.count || 0 };
       }
    }

    return { 
      data: (data || []).map(row => mapRowToEntry(row)), 
      count: count || 0 
    };
  } catch (e) {
    console.error("[SearchEngine v13] Critical Failure:", e);
    return { data: [], count: 0 };
  }
};

const mapRowToEntry = (row: any): SanctionEntry => ({
  dataId: String(row.data_id || row.dataId || ''),
  firstName: row.first_name || row.firstName || '',
  secondName: row.second_name || row.secondName || '',
  thirdName: row.third_name || row.thirdName || '',
  lastName: row.last_name || row.lastName || '',
  source: row.source || 'Unknown',
  referenceNumber: row.reference_number || row.referenceNumber || '',
  listedOn: row.listed_on || row.listedOn || '',
  comments: row.comments || '',
  nationality: row.nationality || '',
  dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
  aliases: Array.isArray(row.aliases) ? row.aliases : [],
  type: row.type || EntityType.CORPORATE,
  fetchDate: row.fetch_date || row.fetchDate || '',
  unListType: row.un_list_type || row.unListType || ''
});

