/**
 * v14.0.0 AUTHORITATIVE SEARCH ENGINE (GLOBAL ELASTIC CONSENSUS)
 * 
 * RESOLUTION for "No Result" anomaly:
 * 1. PostgREST Normalization: Wraps search patterns in double-quotes to ensure '%' isn't stripped by internal parsers.
 * 2. Case-Insensitive Permissive Scan: Queries across snake_case and potential camelCase keys.
 * 3. Deep Registry Interrogation: Searches data_id, first_name, last_name, and comments simultaneously.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  // Clean term: remove any syntax-breaking characters but preserve spaces for multi-token scan
  const cleanTerm = term.trim().replace(/[%,;()]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  // Strategy: Normalizing "green" to "%green%"
  const searchPattern = `%${cleanTerm}%`;

  console.log(`[SearchEngine v14] Registry Interrogation active for: "${searchPattern}" (Depth: 18,511)`);

  try {
    // Definitive Registry Columns
    const primaryCols = ['first_name', 'last_name', 'second_name', 'third_name', 'reference_number', 'comments', 'data_id'];
    const secondaryCols = ['firstName', 'lastName', 'referenceNumber', 'dataId']; // Fallback for legacy schemas

    const allCols = [...primaryCols, ...secondaryCols];

    // Construct PostgREST .or() filter. Quoting patterns is critical for certain PostgREST versions.
    const filterParts = allCols.map(c => `${c}.ilike."${searchPattern}"`);
    const filterStr = filterParts.join(',');

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterStr)
      .order('first_name', { ascending: true })
      .range(from, to);

    if (error) {
       console.warn("[SearchEngine v14] Primary scan conflict:", error.message);
       // EMERGENCY FALLBACK: Minimalist scan on confirmed core columns
       const emergencyFilter = `first_name.ilike."${searchPattern}",last_name.ilike."${searchPattern}"`;
       const fallback = await supabaseClient
         .from('sanctions')
         .select('*', { count: 'exact' })
         .or(emergencyFilter)
         .range(from, to);

       if (fallback.error) throw fallback.error;
       return { 
         data: (fallback.data || []).map(row => mapRowToEntry(row)), 
         count: fallback.count || 0 
       };
    }

    // Diagnostic log for empty returns on populated DB
    if ((!data || data.length === 0) && count === 0) {
      console.warn(`[SearchEngine v14] Zero hits for "${cleanTerm}" despite populated registry. Checking for first-record visibility...`);
      // Try fetching just the very first record to see what columns are named
      const peek = await supabaseClient.from('sanctions').select('*').limit(1);
      if (peek.data && peek.data[0]) {
         console.log("[SearchEngine v14] Schema Probe Result (Sample Record):", Object.keys(peek.data[0]));
      }
    }

    return { 
      data: (data || []).map(row => mapRowToEntry(row)), 
      count: count || 0 
    };
  } catch (e) {
    console.error("[SearchEngine v14] Fatal Fault:", e);
    return { data: [], count: 0 };
  }
};

const mapRowToEntry = (row: any): SanctionEntry => ({
  dataId: String(row.data_id || row.dataId || ''),
  firstName: row.first_name || row.firstName || '',
  secondName: row.second_name || row.secondName || '',
  thirdName: row.third_name || row.thirdName || '',
  lastName: row.last_name || row.lastName || '',
  source: row.source || 'Unknown',
  referenceNumber: row.reference_number || row.referenceNumber || '',
  listedOn: row.listed_on || row.listedOn || '',
  comments: row.comments || '',
  nationality: row.nationality || '',
  dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
  aliases: Array.isArray(row.aliases) ? row.aliases : [],
  type: row.type || EntityType.CORPORATE,
  fetchDate: row.fetch_date || row.fetchDate || '',
  unListType: row.un_list_type || row.unListType || ''
});

