/**
 * v15.0.0 AUTHORITATIVE SEARCH ENGINE (GLOBAL AUTHORITY PROTOCOL)
 * 
 * FIX for "No Results" on populated DB:
 * 1. Syntax: Removed double-quotes inside ilike filters.
 * 2. Strategy: Performs a broad phrase scan, falling back to a tokenized scan.
 * 3. Diagnostics: Logs the exact PostgREST filter string to console for debugging.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/[%,;()]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  // Tokenize: "Green Pine" -> ["green", "pine"]
  const tokens = cleanTerm.split(/\s+/);
  const searchPattern = `%${tokens.join('%')}%`;

  console.log(`[SearchEngine v15] Executing Authority Scan: "${searchPattern}" (Capacity: 18k+)`);

  try {
    // Definitive Registry Columns - matching exact database keys
    const targetCols = [
      'first_name', 'last_name', 'second_name', 'third_name', 
      'reference_number', 'comments', 'data_id', 'source'
    ];

    // Construct filter string: "first_name.ilike.%green%,last_name.ilike.%green%..."
    // NO INTERNAL DOUBLE QUOTES - simpler syntax is more robust across Postgres versions.
    const filterStr = targetCols.map(c => `${c}.ilike.${searchPattern}`).join(',');

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterStr)
      .order('first_name', { ascending: true })
      .range(from, to);

    if (error) {
       console.warn("[SearchEngine v15] Primary Protocol Divergence:", error.message);
       // EMERGENCY FALLBACK: Single word scan if multi-word pattern fails
       if (tokens.length > 1) {
          console.warn(`[SearchEngine v15] Phrase failed. Falling back to Token 1: "${tokens[0]}"`);
          const fallbackPattern = `%${tokens[0]}%`;
          const fallbackFilter = targetCols.map(c => `${c}.ilike.${fallbackPattern}`).join(',');
          const fallback = await supabaseClient.from('sanctions').select('*', { count: 'exact' }).or(fallbackFilter).range(from, to);
          if (fallback.error) throw fallback.error;
          return { data: (fallback.data || []).map(row => mapRowToEntry(row)), count: fallback.count || 0 };
       }
       throw error;
    }

    // DIAGNOSTIC PEEK: If results are empty but count > 0 (should not happen with ilike, but check anyway)
    if ((!data || data.length === 0)) {
       console.warn(`[SearchEngine v15] Zero hits for "${searchPattern}". Interrogating schema visibility...`);
       const sample = await supabaseClient.from('sanctions').select('*').limit(3);
       if (sample.data && sample.data.length > 0) {
          console.log("[SearchEngine v15] Registry Sample (Internal Keys):", Object.keys(sample.data[0]));
          console.log("[SearchEngine v15] Registry Sample (Content):", sample.data[0]);
       } else {
          console.error("[SearchEngine v15] Registry appears unpopulated despite capacity claim.");
       }
    }

    return { 
      data: (data || []).map(row => mapRowToEntry(row)), 
      count: count || 0 
    };
  } catch (e) {
    console.error("[SearchEngine v15] Fatal Execution Fault:", e);
    return { data: [], count: 0 };
  }
};

const mapRowToEntry = (row: any): SanctionEntry => ({
  dataId: String(row.data_id || row.dataId || ''),
  firstName: row.first_name || row.firstName || '',
  secondName: row.second_name || row.secondName || '',
  thirdName: row.third_name || row.thirdName || '',
  lastName: row.last_name || row.lastName || '',
  source: row.source || 'Unknown',
  referenceNumber: row.reference_number || row.referenceNumber || '',
  listedOn: row.listed_on || row.listedOn || '',
  comments: row.comments || '',
  nationality: row.nationality || '',
  dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
  aliases: Array.isArray(row.aliases) ? row.aliases : [],
  type: row.type || EntityType.CORPORATE,
  fetchDate: row.fetch_date || row.fetchDate || '',
  unListType: row.un_list_type || row.unListType || ''
});

