/**
 * v16.0.0 AUTHORITATIVE SEARCH ENGINE (GLOBAL CONSENSUS)
 * 
 * RESOLUTION for "Zero Results on Populated DB":
 * 1. Dual-Path Interrogation: Attempts indexed multi-column scan first.
 * 2. CORE IDENTITY FALLBACK: If primary scan fails, automatically pivots to a Name-only scan.
 * 3. KEY-NORMALIZATION: Handles both snake_case (database) and camelCase (application) properties.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/[%,;()]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  // Tokenization for phrase matching: "Green Pine" -> "%green%pine%"
  const tokens = cleanTerm.split(/\s+/).filter(t => t.length > 0);
  const searchPattern = `%${tokens.join('%')}%`;

  console.log(`[SearchEngine v16] Global Consensus Interrogation: "${searchPattern}"`);

  try {
    // Definitive list of columns that must be searched
    const cols = ['first_name', 'last_name', 'second_name', 'third_name', 'reference_number', 'comments', 'data_id'];

    // PostgREST .or() filter construction
    const filterStr = cols.map(c => `${c}.ilike.${searchPattern}`).join(',');

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterStr)
      .order('first_name', { ascending: true, nullsFirst: false })
      .range(from, to);

    if (error) throw error;

    // PATH 2: Pivot to Name-Only Fallback if Phrase/Consensus failed but DB is populated
    if ((!data || data.length === 0) && tokens.length > 0) {
      console.warn(`[SearchEngine v16] Consensus scan yielded zero hits. Pivoting to Name-Only Fallback for "${tokens[0]}"...`);
      const fallbackPattern = `%${tokens[0]}%`;
      const fallbackFilter = `first_name.ilike.${fallbackPattern},last_name.ilike.${fallbackPattern},second_name.ilike.${fallbackPattern}`;

      const fallback = await supabaseClient
        .from('sanctions')
        .select('*', { count: 'exact' })
        .or(fallbackFilter)
        .order('first_name', { ascending: true })
        .range(from, to);

      if (!fallback.error && fallback.data && fallback.data.length > 0) {
        return { 
          data: fallback.data.map((row: any) => mapRowToEntry(row)), 
          count: fallback.count || 0 
        };
      }
    }

    return { 
      data: (data || []).map((row: any) => mapRowToEntry(row)), 
      count: count || 0 
    };
  } catch (e: any) {
    console.error("[SearchEngine v16] Critical Protocol Failure:", e.message);
    return { data: [], count: 0 };
  }
};

/**
 * Normalizes mixed-case database rows into internal SanctionEntry structure.
 */
const mapRowToEntry = (row: any): SanctionEntry => {
  return {
    dataId: String(row.data_id || row.dataId || ''),
    firstName: row.first_name || row.firstName || '',
    secondName: row.second_name || row.secondName || '',
    thirdName: row.third_name || row.thirdName || '',
    lastName: row.last_name || row.lastName || '',
    source: row.source || 'Unknown Authority',
    referenceNumber: row.reference_number || row.referenceNumber || '',
    listedOn: row.listed_on || row.listedOn || '',
    comments: row.comments || '',
    nationality: row.nationality || '',
    dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
    aliases: Array.isArray(row.aliases) ? row.aliases : [],
    type: row.type || EntityType.CORPORATE,
    fetchDate: row.fetch_date || row.fetchDate || '',
    unListType: row.un_list_type || row.unListType || ''
  };
};

