/**
 * v17.0.0 AUTHORITATIVE SEARCH ENGINE (OMNI-SCHEMA PROTOCOL)
 * 
 * FIX for "Zero Results on Populated DB":
 * 1. OMNI-COLUMN INTERROGATION: Queries both snake_case AND camelCase column variants.
 * 2. PATTERN EVOLUTION: Uses greedy ilike with internal token normalization.
 * 3. FALLBACK REDUNDANCY: Pivot to independent token search if intersection fails.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/[%,;()]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  // Greedy Tokenization: "Green" -> "%green%"
  const tokens = cleanTerm.split(/\s+/).filter(t => t.length > 0);
  const searchPattern = `%${tokens.join('%')}%`;

  console.log(`[SearchEngine v17] Omni-Protocol Interrogation: "${searchPattern}"`);

  try {
    // Definitive list of columns - INCLUDES BOTH SNAKE AND CAMEL CASE VARIANTS
    const omniCols = [
      'first_name', 'firstName', 
      'last_name', 'lastName', 
      'second_name', 'secondName', 
      'third_name', 'thirdName', 
      'reference_number', 'referenceNumber', 
      'comments', 
      'data_id', 'dataId'
    ];

    const filterStr = omniCols.map(c => `${c}.ilike.${searchPattern}`).join(',');

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterStr)
      .order('first_name', { ascending: true, nullsFirst: false })
      .range(from, to);

    // If query succeeds but returns zero, and search was multi-word, try token intersection fallback
    if (!error && (!data || data.length === 0) && tokens.length > 1) {
       console.warn(`[SearchEngine v17] Composite phrase missed. Pivoting to Token-Intersection...`);
       const firstTokenPattern = `%${tokens[0]}%`;
       const fallbackFilter = omniCols.map(c => `${c}.ilike.${firstTokenPattern}`).join(',');
       const fallback = await supabaseClient
         .from('sanctions')
         .select('*', { count: 'exact' })
         .or(fallbackFilter)
         .range(from, to);

       if (!fallback.error && fallback.data && fallback.data.length > 0) {
          return { data: fallback.data.map(mapRowToEntry), count: fallback.count || 0 };
       }
    }

    if (error) {
       console.error("[SearchEngine v17] Protocol Conflict:", error.message);
       // Simple fallback for syntax errors
       const emergencyFilter = `first_name.ilike.${searchPattern},lastName.ilike.${searchPattern}`;
       const emergency = await supabaseClient.from('sanctions').select('*', { count: 'exact' }).or(emergencyFilter).range(from, to);
       if (emergency.data) return { data: emergency.data.map(mapRowToEntry), count: emergency.count || 0 };
       throw error;
    }

    return { 
      data: (data || []).map((row: any) => mapRowToEntry(row)), 
      count: count || 0 
    };
  } catch (e: any) {
    console.error("[SearchEngine v17] Fatal Execution Fault:", e.message);
    return { data: [], count: 0 };
  }
};

/**
 * Omni-Protocol Mapper: Resolves mixed-case keys into a single SanctionEntry
 */
const mapRowToEntry = (row: any): SanctionEntry => {
  return {
    dataId: String(row.data_id || row.dataId || ''),
    firstName: row.first_name || row.firstName || '',
    secondName: row.second_name || row.secondName || '',
    thirdName: row.third_name || row.thirdName || '',
    lastName: row.last_name || row.lastName || '',
    source: row.source || 'Unknown Authority',
    referenceNumber: row.reference_number || row.referenceNumber || '',
    listedOn: row.listed_on || row.listedOn || '',
    comments: row.comments || '',
    nationality: row.nationality || '',
    dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
    aliases: Array.isArray(row.aliases) ? row.aliases : [],
    type: row.type || EntityType.CORPORATE,
    fetchDate: row.fetch_date || row.fetchDate || '',
    unListType: row.un_list_type || row.unListType || ''
  };
};

