/**
 * v18.0.0 AUTHORITATIVE SEARCH ENGINE (SCHEMA-AGNOSTIC RECOVERY)
 * 
 * RESOLUTION for "Zero Results after 36 Hours":
 * 1. DYNAMIC PROBE: Inspects the table to find EXACT column names.
 * 2. SAFE-BUILD: Only searches columns that actually exist in the DB.
 * 3. TOKENIZED FALLBACK: Automatically splits queries to find partial hits.
 */
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/[%,;()]/g, '');
  if (!cleanTerm) {
    const count = await fetchSanctionsTotalCount();
    const data = await fetchSanctionsBatch(from, to);
    return { data, count };
  }

  try {
    // PHASE 1: DYNAMIC SCHEMA PROBE
    // Get a sample row to see what columns actually exist in the DB right now
    const { data: probeData } = await supabaseClient.from('sanctions').select('*').limit(1);
    const existingCols = probeData && probeData.length > 0 ? Object.keys(probeData[0]) : [];

    // Identity-related columns we want to search if they exist
    const targetKeys = [
      'first_name', 'firstName', 'last_name', 'lastName', 
      'second_name', 'secondName', 'third_name', 'thirdName',
      'reference_number', 'referenceNumber', 'comments', 'data_id', 'dataId'
    ];

    const validSearchCols = targetKeys.filter(k => existingCols.includes(k));

    // If we found no valid identity columns (very unlikely), fall back to standard naming
    const finalCols = validSearchCols.length > 0 ? validSearchCols : ['first_name', 'last_name'];

    // PHASE 2: SEARCH EXECUTION
    const tokens = cleanTerm.split(/\s+/).filter(t => t.length > 0);
    const searchPattern = `%${tokens.join('%')}%`;
    const filterStr = finalCols.map(c => `${c}.ilike.${searchPattern}`).join(',');

    console.log(`[SearchEngine v18] Probed Schema Keys:`, existingCols);
    console.log(`[SearchEngine v18] Executing Safe-Query on columns:`, finalCols);

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterStr)
      .order(existingCols.includes('first_name') ? 'first_name' : existingCols[0], { ascending: true })
      .range(from, to);

    if (error) throw error;

    // PHASE 3: MULTI-TOKEN FALLBACK
    // If "Green Pine" phrase match failed, try matching JUST "Green"
    if ((!data || data.length === 0) && tokens.length > 1) {
       console.warn(`[SearchEngine v18] Intersection failed. Falling back to Token 1: "${tokens[0]}"`);
       const fbPattern = `%${tokens[0]}%`;
       const fbFilter = finalCols.map(c => `${c}.ilike.${fbPattern}`).join(',');
       const fb = await supabaseClient.from('sanctions').select('*', { count: 'exact' }).or(fbFilter).range(from, to);
       if (!fb.error && fb.data) {
          return { data: fb.data.map(mapRowToEntry), count: fb.count || 0 };
       }
    }

    return { 
      data: (data || []).map(mapRowToEntry), 
      count: count || 0 
    };
  } catch (e: any) {
    console.error("[SearchEngine v18] Fatal Protocol Break:", e.message);
    return { data: [], count: 0 };
  }
};

/**
 * Omni-Protocol Mapper: Resolves any combination of snake/camel keys into SanctionEntry
 */
const mapRowToEntry = (row: any): SanctionEntry => {
  return {
    dataId: String(row.data_id || row.dataId || ''),
    firstName: row.first_name || row.firstName || '',
    secondName: row.second_name || row.secondName || '',
    thirdName: row.third_name || row.thirdName || '',
    lastName: row.last_name || row.lastName || '',
    source: row.source || 'Master Registry',
    referenceNumber: row.reference_number || row.referenceNumber || '',
    listedOn: row.listed_on || row.listedOn || '',
    comments: row.comments || '',
    nationality: row.nationality || '',
    dateOfBirth: row.date_of_birth || row.dateOfBirth || '',
    aliases: Array.isArray(row.aliases) ? row.aliases : [],
    type: row.type || EntityType.CORPORATE,
    fetchDate: row.fetch_date || row.fetchDate || '',
    unListType: row.un_list_type || row.unListType || ''
  };
};

