// Global Sync Management
export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient
      .from('system_metadata')
      .select('value')
      .eq('key', 'global_sync')
      .maybeSingle();
    if (error) return null;
    return data?.value || null;
  } catch (e) { return null; }
};

export const subscribeToGlobalSync = (callback: (meta: any) => void) => {
  if (!supabaseClient) return { unsubscribe: () => {} };
  return supabaseClient
    .channel('global-sync')
    .on('postgres_changes', { event: '*', schema: 'public', table: 'system_metadata', filter: 'key=eq.global_sync' }, (payload: any) => {
      callback(payload.new?.value);
    })
    .subscribe();
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync: string) => {
  if (!supabaseClient) return;
  const value = { is_syncing: isSyncing, last_sync: lastSync };
  const { error } = await supabaseClient.from('system_metadata').upsert({ key: 'global_sync', value });
  if (error) throw error;
};

// Ingestion Management
export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void, isBatch: boolean = false) => {
  if (!supabaseClient) return;
  const chunkSize = 100;
  for (let i = 0; i < sanctions.length; i += chunkSize) {
    const chunk = sanctions.slice(i, i + chunkSize).map(s => ({
      data_id: s.dataId,
      first_name: s.firstName,
      second_name: s.secondName,
      third_name: s.thirdName,
      last_name: s.lastName,
      source: s.source,
      reference_number: s.referenceNumber,
      listed_on: s.listedOn,
      comments: s.comments,
      nationality: s.nationality,
      date_of_birth: s.dateOfBirth,
      aliases: s.aliases,
      type: s.type,
      fetch_date: s.fetchDate,
      un_list_type: s.unListType
    }));
    const { error } = await supabaseClient.from('sanctions').upsert(chunk);
    if (error) throw error;
    if (onProgress) onProgress(Math.round(((i + chunk.length) / sanctions.length) * 100));
  }
};

export const logIngestionEvent = async (log: any) => {
  if (!supabaseClient) return;
  const { error } = await supabaseClient.from('ingestion_logs').insert([log]);
  if (error) throw error;
};

export const fetchIngestionLogs = async (): Promise<IngestionLog[]> => {
  if (!supabaseClient) return [];
  try {
    const { data, error } = await supabaseClient
      .from('ingestion_logs')
      .select('*')
      .order('timestamp', { ascending: false });
    if (error) return [];
    return data || [];
  } catch (e) { return []; }
};

/**
 * AUTHORITATIVE SCREENING ENGINE
 */
export const screenEntityAgainstDb = async (client: Client, triggeredBy?: string): Promise<Client> => {
  const { screenClient } = await import('./screeningEngine');
  const response = await searchSanctionsAuthoritative(client["Client Name"], 0, 100);
  const match = screenClient(client, response.data);

  return {
    ...client,
    riskLevel: match ? match.riskLevel : RiskLevel.NONE,
    matches: match ? [match.sanctionId] : [],
    lastScreenedAt: new Date().toISOString()
  };
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry, EntityType, SystemEnvironment, IngestionLog, UserRole } from '../types';
