// --- SEARCH ENGINE v20.0.0 (SIMPLE & ROBUST) ---
export const searchSanctionsAuthoritative = async (
  term: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanTerm = term.trim().replace(/[%,;()'"&]/g, '');
  if (!cleanTerm) {
    const { data, count } = await supabaseClient.from('sanctions').select('*', { count: 'exact' }).range(from, to).order('first_name', { ascending: true });
    return { data: (data || []).map(mapRowToEntry), count: count || 0 };
  }

  // Decompose into salient tokens for broad OR search
  const tokens = cleanTerm.split(/\s+/).filter(t => t.length > 1);
  const searchTokens = tokens.length > 0 ? tokens : [cleanTerm];

  // Simple set of authoritative columns
  const cols = ['first_name', 'last_name', 'second_name', 'third_name', 'reference_number', 'comments'];

  // Build simple OR filter string
  const orParts: string[] = [];
  searchTokens.forEach(token => {
    cols.forEach(col => orParts.push(`${col}.ilike.%${token}%`));
  });

  try {
    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(orParts.join(','))
      .range(from, to)
      .order('first_name', { ascending: true });

    if (error) throw error;
    return { data: (data || []).map(mapRowToEntry), count: count || 0 };
  } catch (e) {
    console.error("[Search] Simple Query Failed:", e);
    return { data: [], count: 0 };
  }
};

