/**
 * AUTHORITATIVE SEARCH ENGINE v21.2.0 (Salient Token Consensus)
 * DECOMPOSES input into salient tokens to pull fuzzy candidates from DB.
 */
export const searchSanctionsAuthoritative = async (
  name: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const queryStr = name.trim().toUpperCase();
  if (!queryStr) {
    const { data, count } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .range(from, to)
      .order('first_name', { ascending: true });
    return { data: (data || []).map(mapRowToEntry), count: count || 0 };
  }

  try {
    // 1. Extract Salient Tokens (Filtering out noise/short words)
    const tokens = queryStr.split(/\s+/)
      .filter(t => t.length >= 2 && !RETRIEVAL_NOISE.includes(t))
      .slice(0, 3); // Top 3 salient tokens to prevent query bloat

    const cols = ['first_name', 'last_name', 'comments', 'data_id', 'reference_number'];
    const filterParts: string[] = [];

    if (tokens.length === 0) {
      // Fallback to literal partial search if no salient tokens found
      const term = `%${queryStr}%`;
      cols.forEach(col => filterParts.push(`${col}.ilike.${term}`));
    } else {
      // 2. Multi-token Broad Interrogation
      // Ensures 'SaNRISE GREENLAND' retrieves 'SUNRISE' entities.
      tokens.forEach(t => {
        const term = `%${t}%`;
        cols.forEach(col => filterParts.push(`${col}.ilike.${term}`));
      });
    }

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterParts.join(','))
      .range(from, to)
      .order('first_name', { ascending: true });

    if (error) throw new Error(`REGISTRY_QUERY_FAULT: ${extractError(error)}`);

    return { 
      data: (data || []).map(mapRowToEntry), 
      count: count || 0 
    };
  } catch (e: any) {
    console.error("[Search] Authoritative Execution Fault:", e.message);
    return { data: [], count: 0 };
  }
};

