import { 
  Plus, Power, Trash2, Shield, Copy, Check, Users, 
  ShieldAlert, History, Beaker, Zap, Terminal, X, 
  Loader2, RefreshCw, FileCheck, Bookmark, Calendar
} from 'lucide-react';
import { upsertCloudUser, deleteCloudUser, logAuditEvent } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  currentUser?: UserProfile | null;
  onLogsRefresh?: () => void;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, currentUser, onLogsRefresh }) => {
  const [activeTab, setActiveTab] = useState<'users' | 'engine' | 'logs'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<any | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const saveUsersToStorage = (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isDelete) { 
        await deleteCloudUser(user.email); 
        await logAuditEvent('USER_REVOKED', `Identity "${user.full_name}" removed from access list.`, currentUser?.email || 'System');
      } else { 
        await upsertCloudUser(user); 
      }
    } catch (e: any) {
      alert(`Cloud Provisioning Error: ${e.message}`);
      throw e; 
    } finally {
      setIsSyncing(false);
    }
  };

  const toggleUserStatus = async (email: string) => {
    const userToUpdate = systemUsers.find(u => u.email === email);
    if (!userToUpdate) return;
    const nextStatus = userToUpdate.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE;
    const updatedUser = { ...userToUpdate, status: nextStatus };
    try {
      await handleCloudSync(updatedUser);
      await logAuditEvent('USER_STATUS_MODIFIED', `Account ${email} set to ${nextStatus}.`, currentUser?.email || 'System');
      const nextUsers = systemUsers.map(u => u.email === email ? updatedUser : u);
      saveUsersToStorage(nextUsers);
    } catch (e) {}
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;
    try {
      await handleCloudSync(pendingDeleteUser, true);
      const updated = systemUsers.filter(u => u.email !== pendingDeleteUser.email);
      saveUsersToStorage(updated);
      setPendingDeleteUser(null);
    } catch (e) {}
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: newUserEmail.trim().toLowerCase(),
      password_hash_mock: DEFAULT_TEMP_PASSWORD, 
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };
    try {
      await handleCloudSync(newUser);
      await logAuditEvent('USER_PROVISIONED', `New identity "${newUserName}" created with role ${newUserRole}.`, currentUser?.email || 'System');
      saveUsersToStorage([...systemUsers, newUser]);
      setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false); setIsNewUserAdmin(false);
    } catch (err) {}
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center bg-white p-6 sm:p-8 rounded-[2rem] shadow-sm border border-gray-100 gap-6">
        <div className="flex items-center gap-4">
          <div className={`${settings.environment === SystemEnvironment.PRODUCTION ? 'bg-emerald-800' : 'bg-amber-600'} p-4 rounded-2xl text-white shadow-xl transition-colors duration-500`}>
            {settings.environment === SystemEnvironment.PRODUCTION ? <Shield size={28}/> : <Beaker size={28}/>}
          </div>
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-900 tracking-tight uppercase">Governance</h2>
            <p className="text-[10px] text-emerald-600 font-black uppercase tracking-widest mt-1">Enterprise Registry Control</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full xl:w-auto">
            <button onClick={() => setActiveTab('users')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'users' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Identities</button>
            <button onClick={() => setActiveTab('engine')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'engine' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Engine</button>
            <button onClick={() => { setActiveTab('logs'); onLogsRefresh?.(); }} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'logs' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>System Logs</button>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 space-y-8">
           {activeTab === 'users' && (
            <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8 animate-in fade-in duration-500">
               <div className="flex justify-between items-center border-b border-gray-50 pb-6">
                  <div className="flex items-center gap-3">
                     <Users className="text-emerald-800" size={20} />
                     <h3 className="text-sm font-black uppercase text-slate-900">Identity Management</h3>
                  </div>
                  <button onClick={() => setIsUserModalOpen(true)} className="bg-emerald-800 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg hover:bg-emerald-900 transition-all">
                     <Plus size={16} /> Provision User
                  </button>
               </div>

               <div className="overflow-x-auto">
                  <table className="w-full text-left min-w-[600px]">
                     <thead>
                        <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                           <th className="px-4 py-4">Identity</th>
                           <th className="px-4 py-4">Role</th>
                           <th className="px-4 py-4">Status</th>
                           <th className="px-4 py-4 text-right">Actions</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-50">
                        {systemUsers.map((user: any) => (
                           <tr key={user.email} className="hover:bg-slate-50 transition-colors group">
                              <td className="px-4 py-4">
                                 <p className="text-sm font-black text-slate-900 uppercase">{user.full_name}</p>
                                 <p className="text-[10px] text-slate-400 font-bold">{user.email}</p>
                              </td>
                              <td className="px-4 py-4">
                                 <span className="text-[10px] font-black uppercase text-emerald-700">{user.role}</span>
                              </td>
                              <td className="px-4 py-4">
                                 <button onClick={() => toggleUserStatus(user.email)} className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase border transition-all ${user.status === AccountStatus.ACTIVE ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-red-50 text-red-600 border-red-100'}`}>
                                    {user.status}
                                 </button>
                              </td>
                              <td className="px-4 py-4 text-right">
                                 <button onClick={() => setPendingDeleteUser(user)} className="p-2 text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all">
                                    <Trash2 size={18} />
                                 </button>
                              </td>
                           </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
          )}

          {activeTab === 'logs' && (
            <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8 animate-in fade-in">
               <div className="flex items-center justify-between border-b border-gray-50 pb-6">
                  <div className="flex items-center gap-3">
                     <History className="text-slate-400" size={20} />
                     <h3 className="text-sm font-black uppercase text-slate-900">Governance Audit Trail</h3>
                  </div>
                  <button onClick={onLogsRefresh} className="p-3 text-emerald-800 bg-emerald-50 rounded-xl hover:bg-emerald-100 transition-all">
                     <RefreshCw size={18} />
                  </button>
               </div>

               <div className="overflow-x-auto custom-scrollbar max-h-[600px]">
                  <table className="w-full text-left">
                     <thead>
                        <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b sticky top-0 bg-white">
                           <th className="px-4 py-4">Timestamp</th>
                           <th className="px-4 py-4">Action</th>
                           <th className="px-4 py-4">Entity/Details</th>
                           <th className="px-4 py-4">Triggered By</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-50">
                        {logs.map((log) => (
                           <tr key={log.id} className="text-[11px] hover:bg-slate-50 transition-colors">
                              <td className="px-4 py-4 text-slate-400 whitespace-nowrap">{new Date(log.timestamp).toLocaleString()}</td>
                              <td className="px-4 py-4">
                                 <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${
                                   log.source.includes('REVOKED') || log.source.includes('DELETED') ? 'bg-red-100 text-red-700' :
                                   log.source.includes('PROVISIONED') ? 'bg-emerald-100 text-emerald-700' :
                                   log.source.includes('OVERRIDE') ? 'bg-amber-100 text-amber-700' :
                                   'bg-slate-100 text-slate-700'
                                 }`}>
                                    {log.source.replace(/_/g, ' ')}
                                 </span>
                              </td>
                              <td className="px-4 py-4 font-bold text-slate-800">{log.details}</td>
                              <td className="px-4 py-4 font-black uppercase text-emerald-700">{log.triggeredBy}</td>
                           </tr>
                        ))}
                        {logs.length === 0 && (
                           <tr>
                              <td colSpan={4} className="py-20 text-center text-slate-300 font-black uppercase tracking-widest text-[10px]">No audit history found in cloud registry</td>
                           </tr>
                        )}
                     </tbody>
                  </table>
               </div>
            </div>
          )}
        </div>

        {/* BUILD MANIFEST / SUCCESS POINT CARD */}
        <div className="space-y-8">
           <div className="bg-emerald-950 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden border border-emerald-400/20 animate-in slide-in-from-right-4">
              <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none">
                 <Bookmark size={120} />
              </div>
              <div className="relative z-10 space-y-6">
                 <div className="flex items-center gap-3 border-b border-white/10 pb-4">
                    <div className="p-2 bg-emerald-400 text-emerald-950 rounded-lg"><FileCheck size={20}/></div>
                    <h3 className="text-xs font-black uppercase tracking-widest">Build Manifest</h3>
                 </div>
                 <div className="space-y-4">
                    <div className="flex justify-between items-center bg-white/5 p-4 rounded-2xl border border-white/5">
                       <span className="text-[9px] font-black uppercase text-emerald-400">Status</span>
                       <span className="px-2 py-1 bg-emerald-500 text-emerald-950 rounded text-[8px] font-black uppercase animate-pulse">Success Point</span>
                    </div>
                    <div className="flex justify-between items-center bg-white/5 p-4 rounded-2xl border border-white/5">
                       <span className="text-[9px] font-black uppercase text-emerald-400">Version</span>
                       <span className="text-xs font-black">v1.9.0-GOLD</span>
                    </div>
                    <div className="flex justify-between items-center bg-white/5 p-4 rounded-2xl border border-white/5">
                       <span className="text-[9px] font-black uppercase text-emerald-400">Archived On</span>
                       <div className="text-right">
                          <p className="text-xs font-black">2024-06-20</p>
                          <p className="text-[8px] font-bold text-white/40 uppercase">16:45 UTC</p>
                       </div>
                    </div>
                 </div>
                 <div className="p-4 bg-emerald-400/10 border border-emerald-400/20 rounded-2xl flex gap-3 text-emerald-300">
                    <Calendar size={18} className="shrink-0" />
                    <p className="text-[8px] font-bold leading-relaxed uppercase">
                       This state has been verified as a global stable milestone. You may request a restoration to this specific codebase at any time.
                    </p>
                 </div>
              </div>
           </div>

           <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-6">
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                 <Terminal size={14} /> Global Mutex Settings
              </h4>
              <div className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl">
                 <span className="text-[10px] font-black uppercase text-slate-500">Registry Sync Lock</span>
                 <div className="w-12 h-6 bg-emerald-800 rounded-full p-1 flex justify-end">
                    <div className="w-4 h-4 bg-white rounded-full shadow-sm" />
                 </div>
              </div>
              <p className="text-[8px] text-gray-400 font-bold leading-relaxed uppercase text-center px-4">
                 Global synchronization is currently locked to ensure write-integrity during the success point archiving process.
              </p>
           </div>
        </div>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase">Provision Identity</h3>
                 <button onClick={() => setIsUserModalOpen(false)} className="p-2 bg-white/10 rounded-full"><X size={20}/></button>
              </div>
              <form onSubmit={handleCreateUser} className="p-8 space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                    <input required className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold outline-none" value={newUserName} onChange={e => setNewUserName(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Corporate Email</label>
                    <input required type="email" className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold outline-none" value={newUserEmail} onChange={e => setNewUserEmail(e.target.value)} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Access Role</label>
                    <select className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-bold outline-none" value={newUserRole} onChange={e => setNewUserRole(e.target.value as UserRole)}>
                       <option value={UserRole.DATA_ENTRY}>Data Entry Officer</option>
                       <option value={UserRole.REVIEWER}>Compliance Reviewer</option>
                       <option value={UserRole.ADMIN}>Compliance Manager</option>
                       <option value={UserRole.REPORTING}>Reporting User</option>
                       <option value={UserRole.AUDITOR}>Audit Viewer</option>
                    </select>
                 </div>
                 <button type="submit" disabled={isSyncing} className="w-full py-5 bg-emerald-800 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-xl hover:bg-emerald-900 transition-all flex items-center justify-center gap-3">
                    {isSyncing ? <Loader2 className="animate-spin" size={20}/> : <Shield size={20}/>}
                    Commit to Registry
                 </button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
// Added Terminal to the import list from lucide-react to fix the compilation error on line 181
import { LayoutDashboard, Users, Globe, FileText, Settings, Menu, X, Wifi, WifiOff, LogOut, ShieldCheck, Clock, RefreshCw, AlertTriangle, ChevronRight, Share2, Database, Shield, Activity, Beaker, ShieldAlert, Terminal } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';
import { UserProfile, UserRole, SystemEnvironment } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  isCloudConnected: boolean;
  isConnecting?: boolean;
  isSafeMode?: boolean;
  schemaFaults?: string[];
  onLogout: () => void;
  currentUser: UserProfile;
  onRetryConnection?: () => void;
  onSettingsRequest?: () => void;
  environment?: SystemEnvironment;
}

const Layout: React.FC<LayoutProps> = ({ children, isCloudConnected, isConnecting, isSafeMode, schemaFaults = [], onLogout, currentUser, onRetryConnection, onSettingsRequest, environment }) => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isDiagOpen, setIsDiagOpen] = useState(false);
  const [registryStats, setRegistryStats] = useState({ lastSourceUpdate: 'Never' });
  const location = useLocation();

  const PRIMARY_LOGO = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";
  const LOCAL_LOGO = "/images/logo.png";
  const FALLBACK_LOGO = "https://placehold.co/600x400/064e3b/ffffff?text=RPME+LIMITED+LLC";

  useEffect(() => {
    const updateStats = () => {
      const saved = localStorage.getItem('unsg_registry_stats');
      if (saved) setRegistryStats(JSON.parse(saved));
    };
    updateStats();
    window.addEventListener('storage', updateStats);
    return () => window.removeEventListener('storage', updateStats);
  }, []);

  const navItems = [
    { label: 'System Dashboard', path: '/', icon: <LayoutDashboard size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.DATA_ENTRY, UserRole.REPORTING, UserRole.AUDITOR] },
    { label: 'Client Onboarding', path: '/clients', icon: <Users size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.DATA_ENTRY] },
    { label: 'Sanctions Registry', path: '/sanctions', icon: <Globe size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.DATA_ENTRY, UserRole.AUDITOR] },
    { label: 'Regulatory Reports', path: '/reports', icon: <FileText size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.REPORTING] },
    { label: 'Governance', path: '/admin', icon: <Settings size={20} />, roles: [], adminOnly: true },
  ];

  const filteredNavItems = navItems.filter(item => {
    if (item.adminOnly) return currentUser.is_system_admin === true;
    return item.roles.includes(currentUser.role);
  });

  const BrandLogo = ({ size = "h-10" }: { size?: string }) => (
    <div className={`relative flex items-center justify-center ${size}`}>
      <img 
        src={LOCAL_LOGO} 
        alt="RPME LIMITED LLC" 
        className={`${size} w-auto object-contain`} 
        onError={(e) => { 
          const target = e.currentTarget;
          if (target.src.includes('images/logo.png')) {
            target.src = PRIMARY_LOGO;
          } else if (target.src.includes('raw.githubusercontent')) {
            target.src = FALLBACK_LOGO;
          }
        }} 
      />
    </div>
  );

  const isProd = environment === SystemEnvironment.PRODUCTION;

  return (
    <div className="flex h-screen bg-[#f8fafc] text-gray-900 overflow-hidden font-sans">
      <div className={`fixed top-0 left-0 right-0 h-1 z-[100] transition-colors duration-500 ${isSafeMode ? 'bg-red-500 animate-pulse' : !isProd ? 'bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.5)]' : isCloudConnected ? 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]' : 'bg-red-500 shadow-[0_0_10px_rgba(239,68,68,0.5)]'}`} />

      {isSidebarOpen && <div className="fixed inset-0 bg-emerald-950/60 backdrop-blur-md z-[60] md:hidden" onClick={() => setSidebarOpen(false)} />}

      <aside className={`fixed inset-y-0 left-0 z-[70] w-72 bg-emerald-950 text-white flex flex-col transform transition-transform duration-500 ease-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 md:static md:h-full flex-shrink-0 shadow-2xl`}>
        <div className="p-8 border-b border-white/5 flex flex-col items-center gap-6">
          <Link to="/" className="flex flex-col items-center gap-4 group">
            <div className="bg-white p-3 rounded-2xl shadow-xl transform group-hover:scale-105 transition-all duration-500 min-h-[90px] flex items-center justify-center w-full relative border border-emerald-100">
              <BrandLogo size="h-16" />
              <div className="absolute -top-2 -right-2 bg-emerald-600 text-white text-[7px] font-black px-1.5 py-0.5 rounded-full shadow-lg border border-white/20">v1.8.5</div>
            </div>
            <div className="text-center">
              <h1 className="text-sm font-black tracking-[0.25em] uppercase text-emerald-100">SanctionGuard</h1>
              <p className="text-[8px] text-amber-500 uppercase tracking-widest font-black mt-1">RPME LIMITED LLC</p>
            </div>
          </Link>
        </div>

        <nav className="flex-1 px-4 py-8 space-y-2 overflow-y-auto custom-scrollbar">
          {filteredNavItems.map((item) => (
            <Link key={item.path} to={item.path} className={`flex items-center gap-4 px-6 py-4 rounded-2xl transition-all ${location.pathname === item.path ? 'bg-amber-600 text-white shadow-lg' : 'text-emerald-100/60 hover:bg-white/5 hover:text-white'}`}>
              <div className={location.pathname === item.path ? 'text-white' : 'text-amber-500'}>{item.icon}</div>
              <span className="font-bold text-xs uppercase tracking-widest">{item.label}</span>
            </Link>
          ))}
        </nav>

        <div className="p-6 border-t border-white/5">
          <div className="bg-white/5 rounded-[2rem] p-4 text-xs">
            <div className="flex items-center gap-3 mb-4">
              <div className="h-10 w-10 rounded-2xl bg-emerald-800 flex items-center justify-center text-xs font-black shrink-0">
                {currentUser.full_name.charAt(0)}
              </div>
              <div className="overflow-hidden">
                <p className="font-black text-white truncate text-[10px] uppercase tracking-wider">{currentUser.full_name}</p>
                <p className="text-[8px] font-black uppercase text-emerald-400 truncate">{currentUser.role}</p>
              </div>
            </div>
            <div className="flex gap-2 mb-4">
              <button onClick={onLogout} className="flex-1 flex items-center justify-center gap-2 py-3 bg-white/5 hover:bg-red-500/20 text-red-400 hover:text-red-300 rounded-xl transition-all font-black uppercase text-[9px] tracking-widest">
                <LogOut size={14} /> Terminate
              </button>
            </div>
            <div className="pt-2 border-t border-white/5 flex justify-center">
               <p className="text-[7px] text-white/30 font-black uppercase tracking-widest flex items-center gap-1.5">
                 <ShieldCheck size={10} /> Build: 1.8.5-ENTERPRISE
               </p>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto flex flex-col h-full w-full relative min-w-0">
        <header className="bg-white border-b border-gray-100 sticky top-0 z-50 flex-shrink-0">
           <div className="px-4 sm:px-6 md:px-10 py-4 sm:py-5 flex justify-between items-center">
              <div className="flex items-center gap-3">
                <button onClick={() => setSidebarOpen(true)} className="md:hidden text-emerald-950 p-2 hover:bg-emerald-50 rounded-xl"><Menu size={24} /></button>
                <div className="flex flex-col">
