const CLIENTS_PER_PAGE = 15;

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [clientsCount, setClientsCount] = useState(0);
  const [systemLogs, setSystemLogs] = useState<SystemLog[]>([]);
  const [currentClientsPage, setCurrentClientsPage] = useState(1);
  const [isRefreshingClients, setIsRefreshingClients] = useState(false);

  const [riskSummary, setRiskSummary] = useState<Record<RiskLevel, number>>({
    [RiskLevel.HIGH]: 0,
    [RiskLevel.MEDIUM]: 0,
    [RiskLevel.LOW]: 0,
    [RiskLevel.NONE]: 0
  });

  const currentPageRef = useRef(1);

  const [screeningProgress, setScreeningProgress] = useState<ScreeningProgress>({
    totalRecords: 0,
    screenedRecords: 0,
    pendingRecords: 0,
    status: 'Not Started',
    currentBatch: 0
  });

  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR' | 'SAFE_MODE'>('CONNECTING');
  const [schemaDiscrepancies, setSchemaDiscrepancies] = useState<string[]>([]);

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const loadLogs = useCallback(async () => {
    const logs = await fetchSystemLogs();
    setSystemLogs(logs);
  }, []);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    if (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
      loadSanctionsCache();
      loadLogs(); // Refresh logs when sync finishes
    }
  }, [loadLogs]);

  const loadSanctionsCache = useCallback(async () => {
    try {
      const count = await fetchSanctionsTotalCount();
      setSanctionsCount(count); 
    } catch (e) { console.error("[App] Cache Refresh Failure:", e); }
  }, []);

  const refreshClients = useCallback(async (page: number = 1) => {
    setIsRefreshingClients(true);
    currentPageRef.current = page;
    try {
      const from = (page - 1) * CLIENTS_PER_PAGE;
      const to = from + CLIENTS_PER_PAGE - 1;
      const [cloudClients, count, globalRisks] = await Promise.all([
        fetchCloudClients(from, to),
        fetchClientsTotalCount(),
        fetchGlobalRiskCounts()
      ]);
      if (cloudClients) setClients(cloudClients);
      setClientsCount(count);
      setRiskSummary(globalRisks);
      setCurrentClientsPage(page);
    } catch (e) { 
      console.error("[App] Registry Pull Failure:", e);
      setConnectionStatus('SAFE_MODE');
    } finally { setIsRefreshingClients(false); }
  }, []);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');
    setSchemaDiscrepancies([]);
    try {
      initSupabase();
      const healthy = await checkConnection();
      if (healthy) {
        const audit = await validateRegistrySchemaV431();
        if (!audit.success) {
           setConnectionStatus('SAFE_MODE');
           setSchemaDiscrepancies(audit.discrepancies || ['Structural Audit Conflict']);
        } else {
           setConnectionStatus('CONNECTED');
        }

        await Promise.all([
          refreshClients(1),
          loadSanctionsCache(),
          loadLogs(),
          fetchGlobalSyncStatus().then(l => l && handleGlobalMetadataUpdate(l))
        ]);

        if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
        subscriptionRef.current = subscribeToClients(() => refreshClients(currentPageRef.current));

        if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
        syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
      } else {
        setConnectionStatus('SAFE_MODE');
      }
    } catch (e: any) { 
      setConnectionStatus('SAFE_MODE');
      refreshClients(1);
    }
    setTimeout(() => setIsBooting(false), 1500);
  }, [handleGlobalMetadataUpdate, loadSanctionsCache, refreshClients, loadLogs]);

  useEffect(() => { bootEnterpriseNode(); }, [bootEnterpriseNode]);

  const handleGlobalBatchScreening = async () => {
    if (screeningProgress.status === 'In Progress') return;

    await logAuditEvent('GLOBAL_BATCH_SCREENING_INITIATED', `Registry-wide authoritative screening protocol started.`, currentUser?.email || 'System');
    await loadLogs();

    const totalCount = await fetchClientsTotalCount();
    const allClients: Client[] = [];

    for (let i = 0; i < totalCount; i += 50) {
      const batch = await fetchCloudClients(i, i + 49);
      allClients.push(...batch);
    }

    setScreeningProgress({
      totalRecords: totalCount,
      screenedRecords: 0,
      pendingRecords: totalCount,
      status: 'In Progress',
      currentBatch: 0
    });

    for (let i = 0; i < allClients.length; i++) {
      const client = allClients[i];
      try {
        const screened = await screenEntityAgainstDb(client, currentUser?.email);
        await upsertCloudClient(screened);
      } catch (err) {
        console.error(`[Screening] Critical Fault for entity "${client["Client Name"]}":`, err);
      }

      setScreeningProgress(prev => ({
        ...prev,
        screenedRecords: i + 1,
        pendingRecords: totalCount - (i + 1)
      }));
    }

    const finalRiskSummary = await fetchGlobalRiskCounts();
    setRiskSummary(finalRiskSummary);

    setScreeningProgress(prev => ({ ...prev, status: 'Completed' }));
    await logAuditEvent('GLOBAL_BATCH_SCREENING_COMPLETED', `Successfully processed screening pass for ${totalCount} records.`, currentUser?.email || 'System');
    await loadLogs();

    setTimeout(() => {
      setScreeningProgress(prev => ({ ...prev, status: 'Not Started' }));
    }, 10000);
  };

  const handleAddClientWithAuthoritativeScreening = async (newClient: Client) => {
    setIsRefreshingClients(true);
    try {
      const screenedClient = await screenEntityAgainstDb(newClient, currentUser?.email);
      await upsertCloudClient(screenedClient);
      await logAuditEvent('ENTITY_PROVISIONED', `Entity "${newClient["Client Name"]}" provisioned to registry.`, currentUser?.email || 'System');
      await loadLogs();
      await refreshClients(currentClientsPage); 
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
        await refreshClients(currentClientsPage);
      } else {
        throw e;
      }
    } finally { setIsRefreshingClients(false); }
  };

  const handleDeleteClient = async (id: string) => {
    const client = clients.find(c => c.id === id);
    setIsRefreshingClients(true);
    try {
      await deleteCloudClient(id);
      await logAuditEvent('ENTITY_REVOKED', `Entity "${client?.["Client Name"] || id}" removed from registry.`, currentUser?.email || 'System');
      await loadLogs();
      await refreshClients(currentClientsPage);
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
        await refreshClients(currentClientsPage);
      } else {
        alert(`Deletion Error: ${e.message}.`); 
      }
    } finally { setIsRefreshingClients(false); }
  };

  const handleUpdateClient = async (updatedClient: Client) => {
    try {
      const original = clients.find(c => c.id === updatedClient.id);
      await upsertCloudClient(updatedClient);

      if (original?.kyc_status !== updatedClient.kyc_status) {
        await logAuditEvent('KYC_STATUS_OVERRIDE', `Status for "${updatedClient["Client Name"]}" changed to ${updatedClient.kyc_status}.`, currentUser?.email || 'System');
      } else {
        await logAuditEvent('ENTITY_MODIFIED', `Data updated for entity "${updatedClient["Client Name"]}".`, currentUser?.email || 'System');
      }
      await loadLogs();

      setClients(prev => prev.map(c => c.id === updatedClient.id ? { ...updatedClient } : c));

      if (original?.riskLevel !== updatedClient.riskLevel) {
        const nextRisks = await fetchGlobalRiskCounts();
        setRiskSummary(nextRisks);
      }
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
      } else {
        throw e;
      }
    }
  };

  const handlePasswordUpdate = async (newPassword: string) => {
    if (!currentUser) return;
    try {
      const dbPayload: any = { ...currentUser };
      dbPayload.password_hash_mock = newPassword;
      dbPayload.must_change_password = false;
      delete dbPayload.password;
      delete dbPayload.confirmPassword;
      await upsertCloudUser(dbPayload);
      await logAuditEvent('PASSWORD_ROTATION', `Security policy enforced: Password updated.`, currentUser.email);
      await loadLogs();
      const updatedUser = { ...currentUser, must_change_password: false, password_hash_mock: newPassword };
      setCurrentUser(updatedUser);
      localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      alert("Security Handshake Complete: Password updated successfully.");
    } catch (e: any) { alert("Failed to update password: " + e.message); }
  };

  const effectiveEnvironment = (currentUser?.id === 'SYS-ROOT') ? settings.environment : SystemEnvironment.PRODUCTION;

  if (!currentUser) {
    return <Login onLogin={(u) => { 
      setCurrentUser(u); 
      localStorage.setItem('unsg_session', JSON.stringify(u)); 
      logAuditEvent('SESSION_INITIALIZED', `User authenticated successfully.`, u.email).then(() => loadLogs());
    }} isCloudConnected={connectionStatus === 'CONNECTED' || connectionStatus === 'SAFE_MODE'} />;
  }

  if (currentUser.must_change_password) {
    return <PasswordUpdate user={currentUser} onUpdate={handlePasswordUpdate} />;
  }

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'} 
        isSafeMode={connectionStatus === 'SAFE_MODE'} 
        schemaFaults={schemaDiscrepancies}
        onLogout={() => { 
          logAuditEvent('SESSION_TERMINATED', `User logged out.`, currentUser.email).then(() => loadLogs());
          setCurrentUser(null); 
          localStorage.removeItem('unsg_session'); 
        }} 
        currentUser={currentUser} 
        onRetryConnection={() => bootEnterpriseNode()} 
        environment={effectiveEnvironment}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} totalClientsCount={clientsCount} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} riskSummary={riskSummary} />} />
          <Route path="/clients" element={<ClientManager clients={clients} totalCount={clientsCount} currentPage={currentClientsPage} onPageChange={refreshClients} isRefreshing={isRefreshingClients} onAddClient={handleAddClientWithAuthoritativeScreening} onDeleteClient={handleDeleteClient} onRefresh={() => refreshClients(currentClientsPage)} onReScreen={handleGlobalBatchScreening} onUpdateClient={handleUpdateClient} screeningProgress={screeningProgress} currentUserRole={currentUser.role} currentUserId={currentUser.id} />} />
          <Route path="/sanctions" element={<SanctionsRegistry onSyncComplete={() => loadSanctionsCache()} isCloudConnected={connectionStatus === 'CONNECTED' || connectionStatus === 'SAFE_MODE'} initialStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} currentUser={currentUser} />} />
          <Route path="/admin" element={currentUser.is_system_admin === true ? <AdminPanel settings={settings} logs={systemLogs} onUpdateSettings={(s) => { 
            logAuditEvent('SYSTEM_SETTINGS_MODIFIED', `Environment set to ${s.environment}.`, currentUser.email).then(() => loadLogs());
            setSettings(s); 
            localStorage.setItem('unsg_settings', JSON.stringify(s)); 
          }} currentUser={currentUser} onLogsRefresh={loadLogs} /> : <Navigate to="/" replace />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus, SystemEnvironment } from '../types';
import { 
  Plus, Trash2, Shield, Users, History, Beaker, Terminal, X, 
  Loader2, RefreshCw, FileCheck, Bookmark, Calendar, AlertTriangle
} from 'lucide-react';
import { upsertCloudUser, deleteCloudUser, logAuditEvent, fetchCloudUsers } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  currentUser?: UserProfile | null;
  onLogsRefresh?: () => void;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, currentUser, onLogsRefresh }) => {
  const [activeTab, setActiveTab] = useState<'users' | 'engine' | 'logs'>('users');
  const [systemUsers, setSystemUsers] = useState<UserProfile[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isLoadingUsers, setIsLoadingUsers] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [pendingDeleteUser, setPendingDeleteUser] = useState<UserProfile | null>(null);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [isNewUserAdmin, setIsNewUserAdmin] = useState(false);

  const loadAuthoritativeData = useCallback(async () => {
    setIsLoadingUsers(true);
    try {
      const users = await fetchCloudUsers();
      setSystemUsers(users);
      if (onLogsRefresh) await onLogsRefresh();
    } catch (e) {
      console.error("[Admin] Identity Refresh Failed:", e);
    } finally {
      setIsLoadingUsers(false);
    }
  }, [onLogsRefresh]);

  useEffect(() => {
    loadAuthoritativeData();
  }, [loadAuthoritativeData]);

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isDelete) { 
        await deleteCloudUser(user.email); 
        await logAuditEvent('USER_REVOKED', `Identity "${user.full_name}" removed from access list.`, currentUser?.email || 'System');
      } else { 
        await upsertCloudUser(user); 
      }
      await loadAuthoritativeData();
      if (onLogsRefresh) await onLogsRefresh(); // Refresh logs after user changes
    } catch (e: any) {
      alert(`Cloud Provisioning Error: ${e.message}`);
      throw e; 
    } finally {
      setIsSyncing(false);
    }
  };

  const toggleUserStatus = async (email: string) => {
    const userToUpdate = systemUsers.find(u => u.email === email);
    if (!userToUpdate) return;
    const nextStatus = userToUpdate.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE;
    const updatedUser = { ...userToUpdate, status: nextStatus };
    try {
      await handleCloudSync(updatedUser);
      await logAuditEvent('USER_STATUS_MODIFIED', `Account ${email} set to ${nextStatus}.`, currentUser?.email || 'System');
      if (onLogsRefresh) await onLogsRefresh();
    } catch (e) {}
  };

  const confirmDeleteUser = async () => {
    if (!pendingDeleteUser) return;
    try {
      await handleCloudSync(pendingDeleteUser, true);
      setPendingDeleteUser(null);
    } catch (e) {}
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: newUserEmail.trim().toLowerCase(),
      password_hash_mock: DEFAULT_TEMP_PASSWORD, 
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: isNewUserAdmin, 
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };
    try {
      await handleCloudSync(newUser);
      await logAuditEvent('USER_PROVISIONED', `New identity "${newUserName}" created with role ${newUserRole}.`, currentUser?.email || 'System');
      if (onLogsRefresh) await onLogsRefresh();
      setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false); setIsNewUserAdmin(false);
    } catch (err) {}
  };

  return (
    <div className="space-y-6 sm:space-y-8 pb-20">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center bg-white p-6 sm:p-8 rounded-[2rem] shadow-sm border border-gray-100 gap-6">
        <div className="flex items-center gap-4">
          <div className={`${settings.environment === SystemEnvironment.PRODUCTION ? 'bg-emerald-800' : 'bg-amber-600'} p-4 rounded-2xl text-white shadow-xl transition-colors duration-500`}>
            {settings.environment === SystemEnvironment.PRODUCTION ? <Shield size={28}/> : <Beaker size={28}/>}
          </div>
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-900 tracking-tight uppercase">Governance</h2>
            <p className="text-[10px] text-emerald-600 font-black uppercase tracking-widest mt-1">Enterprise Registry Control</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 w-full xl:w-auto">
            <button onClick={() => setActiveTab('users')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'users' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Identities</button>
            <button onClick={() => setActiveTab('engine')} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'engine' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>Engine</button>
            <button onClick={() => { setActiveTab('logs'); onLogsRefresh?.(); }} className={`flex-1 xl:flex-none whitespace-nowrap px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${activeTab === 'logs' ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-400'}`}>System Logs</button>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 space-y-8">
           {activeTab === 'users' && (
            <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8 animate-in fade-in duration-500">
               <div className="flex justify-between items-center border-b border-gray-50 pb-6">
                  <div className="flex items-center gap-3">
                     <Users className="text-emerald-800" size={20} />
                     <h3 className="text-sm font-black uppercase text-slate-900">Identity Management</h3>
                  </div>
                  <div className="flex items-center gap-3">
                     <button onClick={loadAuthoritativeData} disabled={isLoadingUsers} className="p-3 text-emerald-800 bg-emerald-50 rounded-xl hover:bg-emerald-100 transition-all disabled:opacity-50">
                        <RefreshCw size={16} className={isLoadingUsers ? 'animate-spin' : ''} />
                     </button>
                     <button onClick={() => setIsUserModalOpen(true)} className="bg-emerald-800 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg hover:bg-emerald-900 transition-all">
                        <Plus size={16} /> Provision User
                     </button>
                  </div>
               </div>

               <div className="overflow-x-auto relative">
                  {isLoadingUsers && (
                    <div className="absolute inset-0 bg-white/60 backdrop-blur-[1px] z-10 flex items-center justify-center">
                       <Loader2 className="animate-spin text-emerald-800" size={32} />
                    </div>
                  )}
                  <table className="w-full text-left min-w-[600px]">
                     <thead>
                        <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                           <th className="px-4 py-4">Identity</th>
                           <th className="px-4 py-4">Role</th>
                           <th className="px-4 py-4">Status</th>
                           <th className="px-4 py-4 text-right">Actions</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-50">
                        {systemUsers.map((user) => (
                           <tr key={user.email} className="hover:bg-slate-50 transition-colors group">
                              <td className="px-4 py-4">
                                 <p className="text-sm font-black text-slate-900 uppercase">{user.full_name}</p>
                                 <p className="text-[10px] text-slate-400 font-bold">{user.email}</p>
                              </td>
                              <td className="px-4 py-4">
                                 <span className="text-[10px] font-black uppercase text-emerald-700">{user.role}</span>
                              </td>
                              <td className="px-4 py-4">
                                 <button onClick={() => toggleUserStatus(user.email)} className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase border transition-all ${user.status === AccountStatus.ACTIVE ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-red-50 text-red-600 border-red-100'}`}>
                                    {user.status}
                                 </button>
                              </td>
                              <td className="px-4 py-4 text-right">
                                 <button onClick={() => setPendingDeleteUser(user)} className="p-2 text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all">
                                    <Trash2 size={18} />
                                 </button>
                              </td>
                           </tr>
                        ))}
                        {systemUsers.length === 0 && !isLoadingUsers && (
                           <tr>
                              <td colSpan={4} className="py-20 text-center text-slate-300 font-black uppercase tracking-widest text-[10px]">No identities found in cloud registry</td>
                           </tr>
                        )}
                     </tbody>
                  </table>
               </div>
            </div>
          )}

          {activeTab === 'logs' && (
            <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8 animate-in fade-in">
               <div className="flex items-center justify-between border-b border-gray-50 pb-6">
                  <div className="flex items-center gap-3">
                     <History className="text-slate-400" size={20} />
                     <h3 className="text-sm font-black uppercase text-slate-900">Governance Audit Trail</h3>
                  </div>
                  <button onClick={onLogsRefresh} className="p-3 text-emerald-800 bg-emerald-50 rounded-xl hover:bg-emerald-100 transition-all">
                     <RefreshCw size={18} />
                  </button>
               </div>

               <div className="overflow-x-auto custom-scrollbar max-h-[600px]">
                  <table className="w-full text-left">
                     <thead>
                        <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b sticky top-0 bg-white">
                           <th className="px-4 py-4">Timestamp</th>
                           <th className="px-4 py-4">Action</th>
                           <th className="px-4 py-4">Entity/Details</th>
                           <th className="px-4 py-4">Triggered By</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-50">
                        {logs.map((log) => (
                           <tr key={log.id} className="text-[11px] hover:bg-slate-50 transition-colors">
                              <td className="px-4 py-4 text-slate-400 whitespace-nowrap">{new Date(log.timestamp).toLocaleString()}</td>
                              <td className="px-4 py-4">
                                 <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${
                                   log.source.includes('REVOKED') || log.source.includes('DELETED') ? 'bg-red-100 text-red-700' :
                                   log.source.includes('PROVISIONED') ? 'bg-emerald-100 text-emerald-700' :
                                   log.source.includes('OVERRIDE') ? 'bg-amber-100 text-amber-700' :
                                   log.source.includes('SYNC') || log.source.includes('IMPORT') ? 'bg-blue-100 text-blue-700' :
                                   'bg-slate-100 text-slate-700'
                                 }`}>
                                    {log.source.replace(/_/g, ' ')}
                                 </span>
                              </td>
                              <td className="px-4 py-4 font-bold text-slate-800">{log.details}</td>
                              <td className="px-4 py-4 font-black uppercase text-emerald-700">{log.triggeredBy}</td>
                           </tr>
                        ))}
                        {logs.length === 0 && (
                           <tr>
