/**
 * Authoritative Governance Audit Logging
 * Ensures exact alignment with 'system_logs' table in Master Registry
 */
export const logAuditEvent = async (action: string, details: string, triggeredBy: string) => {
  if (!supabaseClient) initSupabase();
  const log = { 
    id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`, 
    timestamp: new Date().toISOString(), 
    source: action, 
    method: 'AUDIT', 
    status: 'Success', 
    details, 
    triggered_by: triggeredBy 
  };

  if (supabaseClient) {
    // Attempting insert into 'system_logs' table
    const { error } = await supabaseClient.from('system_logs').insert([log]);
    if (error) {
      console.error("[Audit] Database Write Failed. Ensure 'system_logs' table exists with columns: id, timestamp, source, method, status, details, triggered_by.");
      console.error("[Audit] Fault Details:", extractError(error));
      return false;
    }
    return true;
  }
  return false;
};

export const fetchSystemLogs = async (): Promise<SystemLog[]> => {
  if (!supabaseClient) initSupabase();
  try {
    console.debug("[Audit] Initiating authoritative log retrieval...");
    const { data, error } = await supabaseClient
      .from('system_logs')
      .select('*')
      .order('timestamp', { ascending: false })
      .limit(200);

    if (error) {
       console.error("[Audit] Fetch Fault:", extractError(error));
       throw error;
    }

    if (!data || data.length === 0) {
      console.warn("[Audit] Retrieval complete. Table 'system_logs' returned ZERO records.");
      return [];
    }

    return (data || []).map(row => ({
      id: row.id,
      timestamp: row.timestamp || row.created_at || new Date().toISOString(),
      source: row.source || 'Unknown',
      method: row.method || 'AUDIT',
      status: row.status || 'Success',
      details: row.details || 'No detail provided',
      triggeredBy: row.triggered_by || row.triggeredBy || 'System'
    }));
  } catch (e) {
    console.error("[Audit] Retrieval Protocol Fatal:", e);
    return [];
  }
};

