/**
 * Authoritative Governance Audit Logging
 * Handles missing tables with silent failure or alternate routing
 */
export const logAuditEvent = async (action: string, details: string, triggeredBy: string) => {
  if (!supabaseClient) initSupabase();
  const log = { 
    id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`, 
    timestamp: new Date().toISOString(), 
    source: action, 
    method: 'AUDIT', 
    status: 'Success', 
    details, 
    triggered_by: triggeredBy 
  };

  if (supabaseClient) {
    // Try primary audit table
    let { error } = await supabaseClient.from('system_logs').insert([log]);

    // Fallback: If system_logs doesn't exist, don't crash the app
    if (error && (error.code === '42P01' || error.message.includes('schema cache'))) {
      console.warn("[Audit] Primary 'system_logs' table missing. In-memory audit only.");
      return true; // Return true to prevent UI from thinking it failed
    }

    if (error) {
      console.error("[Audit] Database Write Failed:", extractError(error));
      return false;
    }
    return true;
  }
  return false;
};

export const fetchSystemLogs = async (): Promise<SystemLog[]> => {
  if (!supabaseClient) initSupabase();
  try {
    console.debug("[Audit] Protocol: Attempting authoritative retrieval from 'system_logs'...");
    const { data, error } = await supabaseClient
      .from('system_logs')
      .select('*')
      .order('timestamp', { ascending: false })
      .limit(200);

    // PGRST116/42P01: Table not found in schema cache
    if (error) {
       if (error.code === '42P01' || error.message.includes('schema cache')) {
          console.error("[Audit] Table 'system_logs' is missing from the Master Registry schema.");
          return []; // Return empty instead of throwing to prevent boot failure
       }
       throw error;
    }

    return (data || []).map(row => ({
      id: row.id,
      timestamp: row.timestamp || row.created_at || new Date().toISOString(),
      source: row.source || 'Unknown',
      method: row.method || 'AUDIT',
      status: row.status || 'Success',
      details: row.details || 'No detail provided',
      triggeredBy: row.triggered_by || row.triggeredBy || 'System'
    }));
  } catch (e) {
    console.error("[Audit] Critical Fetch Failure:", e);
    return [];
  }
};

