export const validateRegistrySchemaV431 = async () => {
  if (!supabaseClient) initSupabase();
  const discrepancies: string[] = [];

  // 1. Check core clients table
  const { error: clientErr } = await supabaseClient.from('clients').select('id').limit(1);
  if (clientErr) discrepancies.push(`Core Table 'clients' Access Denied: ${extractError(clientErr)}`);

  // 2. Check system_logs table
  const { error: logsErr } = await supabaseClient.from('system_logs').select('id').limit(1);
  if (logsErr && (logsErr.code === '42P01' || logsErr.message.includes('schema cache'))) {
    discrepancies.push("Registry Fault: Table 'system_logs' missing from cloud schema.");
  } else if (logsErr) {
    discrepancies.push(`Audit Access Fault: ${extractError(logsErr)}`);
  }

  return { success: discrepancies.length === 0, discrepancies };
};

