export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void) => {
  if (!supabaseClient) initSupabase();
  const chunkSize = 100;
  for (let i = 0; i < sanctions.length; i += chunkSize) {
    const chunk = sanctions.slice(i, i + chunkSize).map(s => ({
      data_id: s.dataId, first_name: s.firstName, second_name: s.secondName, third_name: s.thirdName, 
      last_name: s.lastName, source: s.source, reference_number: s.referenceNumber, listed_on: s.listedOn,
      comments: s.comments, nationality: s.nationality, date_of_birth: s.dateOfBirth, aliases: s.aliases,
      type: s.type, fetch_date: s.fetchDate, un_list_type: s.unListType
    }));
    const { error } = await supabaseClient.from('sanctions').upsert(chunk, { onConflict: 'data_id' });
    if (error) throw error;
    if (onProgress) onProgress(Math.round(((i + chunk.length) / sanctions.length) * 100));
  }
};

