 * Merges localStorage with Cloud Registry to handle missing tables.
 */
export const logAuditEvent = async (action: string, details: string, triggeredBy: string) => {
  const log: SystemLog = { 
    id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`, 
    timestamp: new Date().toISOString(), 
    source: action, 
    method: 'AUDIT', 
    status: 'Success', 
    details, 
    triggeredBy: triggeredBy 
  };

  // 1. Immediate Local Fallback (Always works)
  try {
    const localLogs = JSON.parse(localStorage.getItem('unsg_audit_local') || '[]');
    localStorage.setItem('unsg_audit_local', JSON.stringify([log, ...localLogs].slice(0, 200)));
  } catch (e) { console.error("[Audit] Local Storage Fault:", e); }

  // 2. Cloud Persistence Attempt
  if (!supabaseClient) initSupabase();
  if (supabaseClient) {
    const { error } = await supabaseClient.from('system_logs').insert([{
      id: log.id,
      timestamp: log.timestamp,
      source: log.source,
      method: log.method,
      status: log.status,
      details: log.details,
      triggered_by: triggeredBy // Aligned to DB snake_case
    }]);

    // Fail silently if table is missing to avoid PGRST errors in console
    if (error && (error.code === '42P01' || error.message.includes('schema cache'))) {
      return true; // Consider successful since local persistence is active
    }
  }
  return true;
};

export const fetchSystemLogs = async (): Promise<SystemLog[]> => {
  let localLogs: SystemLog[] = [];
  try {
    localLogs = JSON.parse(localStorage.getItem('unsg_audit_local') || '[]');
  } catch (e) { localLogs = []; }

  if (!supabaseClient) initSupabase();
  try {
    const { data, error } = await supabaseClient
      .from('system_logs')
      .select('*')
      .order('timestamp', { ascending: false })
      .limit(100);

    if (error) {
       // Silent degradation for schema faults
       return localLogs;
    }

    const cloudLogs = (data || []).map(row => ({
      id: row.id,
      timestamp: row.timestamp,
      source: row.source,
      method: row.method || 'AUDIT',
      status: row.status || 'Success',
      details: row.details,
      triggeredBy: row.triggered_by || row.triggeredBy || 'System'
    }));

    // Merge and Deduplicate by ID
    const merged = [...localLogs];
    const seenIds = new Set(merged.map(l => l.id));

    for (const cl of cloudLogs) {
      if (!seenIds.has(cl.id)) {
        merged.push(cl);
      }
    }

    return merged.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  } catch (e) {
    return localLogs;
  }
};

// --- SYSTEM ---
export const checkConnection = async () => {
  if (!supabaseClient) initSupabase();
  const { error } = await supabaseClient.from('clients').select('id').limit(1);
  return !error;
};

export const validateRegistrySchemaV431 = async () => {
  if (!supabaseClient) initSupabase();
  const discrepancies: string[] = [];

  const { error: logsErr } = await supabaseClient.from('system_logs').select('id').limit(1);
  if (logsErr && (logsErr.code === '42P01' || logsErr.message.includes('schema cache'))) {
    discrepancies.push("Registry Fault: Table 'system_logs' missing from cloud schema. Local Fallback active.");
  }

  return { success: discrepancies.length === 0, discrepancies };
};

export const fetchGlobalSyncStatus = async () => {
  if (!supabaseClient) initSupabase();
  const { data, error } = await supabaseClient.from('system_metadata').select('value').eq('key', 'global_sync').maybeSingle();
  return error ? null : data?.value || null;
};

export const subscribeToGlobalSync = (callback: (meta: any) => void) => {
  if (!supabaseClient) initSupabase();
  return supabaseClient.channel('global-sync').on('postgres_changes', { event: '*', schema: 'public', table: 'system_metadata', filter: 'key=eq.global_sync' }, (p: any) => callback(p.new?.value)).subscribe();
};

export const setGlobalSyncLock = async (isSyncing: boolean, lastSync: string) => {
  if (!supabaseClient) initSupabase();
  await supabaseClient.from('system_metadata').upsert({ key: 'global_sync', value: { is_syncing: isSyncing, last_sync: lastSync } });
};

export const screenEntityAgainstDb = async (client: Client, triggeredBy?: string): Promise<Client> => {
  const { screenClient } = await import('./screeningEngine');
  const response = await searchSanctionsAuthoritative(client["Client Name"], 0, 150);
  const match = screenClient(client, response.data);
  return { 
    ...client, 
    riskLevel: match ? match.riskLevel : RiskLevel.NONE, 
    matches: match ? [match.sanctionId] : [], 
    lastScreenedAt: new Date().toISOString() 
  };
};

// User Profile Management
export const fetchCloudUsers = async (): Promise<UserProfile[]> => {
  if (!supabaseClient) initSupabase();
  const { data, error } = await supabaseClient.from('profiles').select('*').order('full_name', { ascending: true });
  return error ? [] : data || [];
};

export const upsertCloudUser = async (user: any) => {
  if (!supabaseClient) initSupabase();
  await supabaseClient.from('profiles').upsert([user], { onConflict: 'email' });
};

export const deleteCloudUser = async (email: string) => {
  if (!supabaseClient) initSupabase();
  await supabaseClient.from('profiles').delete().eq('email', email);
};

