            <div className="hidden sm:flex items-center gap-3">
              <ShieldCheck className="text-emerald-500" size={20} />
              <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Node Status</span>
                <span className="text-[11px] font-black uppercase text-emerald-950">
                  {isCloudConnected ? 'Authoritative Master Connection' : isConnecting ? 'Synchronizing Cluster...' : 'Restricted Local Cache Mode'}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-6">
            {!isProd && (
              <div className="hidden md:flex items-center gap-2 px-4 py-2 bg-amber-50 border border-amber-100 rounded-xl text-amber-700">
                <Beaker size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Sandbox Protocol</span>
              </div>
            )}

            <div className="flex items-center gap-4 border-l border-slate-100 pl-6">
              <div className="text-right">
                <p className="text-[11px] font-black uppercase text-slate-950">{currentUser.full_name}</p>
                <p className="text-[9px] font-black uppercase text-slate-400 tracking-tighter">{currentUser.role}</p>
              </div>
              <div className="h-10 w-10 bg-emerald-100 text-emerald-800 rounded-xl flex items-center justify-center font-black text-xs">
                {currentUser.full_name.charAt(0)}
              </div>
            </div>
          </div>
        </header>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
          {isSafeMode && (
            <div className="mb-8 p-6 bg-red-50 border border-red-100 rounded-[2rem] flex items-center justify-between gap-6 animate-in slide-in-from-top-4">
               <div className="flex items-center gap-4">
                  <div className="p-3 bg-red-100 text-red-600 rounded-2xl">
                     <ShieldAlert size={24} />
                  </div>
                  <div>
                     <h4 className="text-sm font-black text-red-900 uppercase tracking-tight">Security Fallback Protocol Active</h4>
                     <p className="text-[10px] text-red-600 font-bold uppercase mt-1">Cloud registry handshake failed or structural audit mismatch detected.</p>
                  </div>
               </div>
               <div className="flex gap-3">
                  <button 
                    onClick={() => setIsDiagOpen(true)}
                    className="px-6 py-3 bg-red-100 text-red-600 rounded-xl text-[10px] font-black uppercase hover:bg-red-200 transition-all"
                  >
                    View Discrepancies
                  </button>
                  {onRetryConnection && (
                    <button 
                      onClick={onRetryConnection}
                      className="px-6 py-3 bg-red-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-red-600/20 hover:bg-red-700 transition-all flex items-center gap-2"
                    >
                      <RefreshCw size={14} /> Re-verify Node
                    </button>
                  )}
               </div>
            </div>
          )}

          <div className="max-w-7xl mx-auto pb-20">
            {children}
          </div>
        </div>

        {/* Global Status Footer */}
        <footer className="h-10 bg-white border-t border-slate-100 flex items-center justify-between px-8 shrink-0 text-[8px] font-black text-slate-400 uppercase tracking-[0.2em]">
           <div className="flex items-center gap-4">
              <span className="flex items-center gap-1.5"><Terminal size={10}/> Node Cluster: DC-04</span>
              <span className="flex items-center gap-1.5"><Activity size={10}/> Registry Pulse: {isCloudConnected ? 'Optimal' : 'Interrupted'}</span>
           </div>
           <div>© 2025 RPME LIMITED • Governance Success Point</div>
        </footer>
      </main>

      {/* Diagnostics Modal for Safe Mode Discrepancies */}
      {isDiagOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95">
             <div className="bg-red-600 p-8 text-white flex justify-between items-center">
                <h3 className="text-xl font-black uppercase">Schema Audit Discrepancies</h3>
                <button onClick={() => setIsDiagOpen(false)} className="p-2 bg-white/10 rounded-full hover:bg-white/20"><X size={20}/></button>
             </div>
             <div className="p-8 space-y-6">
                <div className="bg-red-50 border border-red-100 p-6 rounded-2xl flex gap-4 text-red-700">
                   <AlertTriangle className="shrink-0" size={24} />
                   <p className="text-xs font-bold leading-relaxed">
                     The following structural mismatches were detected during the node verification sequence. Read-write access to the master registry has been throttled to prevent corruption.
                   </p>
                </div>
                <div className="space-y-3">
                   {schemaFaults.map((fault, i) => (
                     <div key={i} className="flex items-center gap-3 p-4 bg-slate-50 rounded-xl text-[10px] font-black text-slate-600 uppercase border border-slate-100">
                        <div className="h-1.5 w-1.5 bg-red-500 rounded-full" />
                        {fault}
                     </div>
                   ))}
                </div>
                <button onClick={() => setIsDiagOpen(false)} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest hover:bg-black transition-all">Acknowledged</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Layout;

import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount,
  upsertCloudSanctions,
  fetchClientsTotalCount,
  screenEntityAgainstDb,
  validateRegistrySchemaV431,
  logAuditEvent,
  fetchSystemLogs,
  fetchGlobalRiskCounts,
  setGlobalSyncLock,
  logIngestionEvent
} from './services/cloudDb';
import { OFFICIAL_UN_XML_URL, fetchAndNormalize } from './services/unSanctionsService';
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsRegistry from './components/SanctionsRegistry';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Client, AppSettings, UserProfile, SystemEnvironment, ScreeningProgress, SystemLog, KYCStatus, RiskLevel } from './types';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: true,
  syncIntervalMinutes: 60, // Default to hourly continuous update
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  environment: SystemEnvironment.PRODUCTION
};

const CLIENTS_PER_PAGE = 15;

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [clientsCount, setClientsCount] = useState(0);
  const [systemLogs, setSystemLogs] = useState<SystemLog[]>([]);
  const [currentClientsPage, setCurrentClientsPage] = useState(1);
  const [isRefreshingClients, setIsRefreshingClients] = useState(false);

  const [riskSummary, setRiskSummary] = useState<Record<RiskLevel, number>>({
    [RiskLevel.HIGH]: 0,
    [RiskLevel.MEDIUM]: 0,
    [RiskLevel.LOW]: 0,
    [RiskLevel.NONE]: 0
  });

  const currentPageRef = useRef(1);

  const [screeningProgress, setScreeningProgress] = useState<ScreeningProgress>({
    totalRecords: 0,
    screenedRecords: 0,
    pendingRecords: 0,
    status: 'Not Started',
    currentBatch: 0
  });

  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR' | 'SAFE_MODE'>('CONNECTING');
  const [schemaDiscrepancies, setSchemaDiscrepancies] = useState<string[]>([]);

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const updateLocalRefreshTimestamp = useCallback(() => {
    const now = new Date().toLocaleString();
    setRegistryStats(prev => {
      const next = { ...prev, lastFetch: now };
      localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
      return next;
    });
  }, []);

  const loadLogs = useCallback(async () => {
    const logs = await fetchSystemLogs();
    setSystemLogs(logs);
  }, []);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    if (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') {
      setRegistryStats(prev => {
        if (prev.lastSourceUpdate === meta.last_sync) return prev;
        const next = { ...prev, lastSourceUpdate: meta.last_sync };
        localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
        return next;
      });
      loadSanctionsCache();
      loadLogs();
    }
  }, [loadLogs]);

  const loadSanctionsCache = useCallback(async () => {
    try {
      const count = await fetchSanctionsTotalCount();
      setSanctionsCount(count); 
      updateLocalRefreshTimestamp();
    } catch (e) { console.error("[App] Cache Refresh Failure:", e); }
  }, [updateLocalRefreshTimestamp]);

  const refreshClients = useCallback(async (page: number = 1) => {
    setIsRefreshingClients(true);
    currentPageRef.current = page;
    try {
      const from = (page - 1) * CLIENTS_PER_PAGE;
      const to = from + CLIENTS_PER_PAGE - 1;
      const [cloudClients, count, globalRisks] = await Promise.all([
        fetchCloudClients(from, to),
        fetchClientsTotalCount(),
        fetchGlobalRiskCounts()
      ]);
      if (cloudClients) setClients(cloudClients);
      setClientsCount(count);
      setRiskSummary(globalRisks);
      setCurrentClientsPage(page);
      updateLocalRefreshTimestamp();
    } catch (e) { 
      console.error("[App] Registry Pull Failure:", e);
      setConnectionStatus('SAFE_MODE');
    } finally { setIsRefreshingClients(false); }
  }, [updateLocalRefreshTimestamp]);

  // --- CONTINUOUS BACKGROUND UPDATE ENGINE ---
  useEffect(() => {
    if (!settings.autoSync || settings.syncIntervalMinutes <= 0 || connectionStatus !== 'CONNECTED') return;

    const runAutomatedSync = async () => {
      if (isGlobalSyncing) return;

      try {
        const currentMeta = await fetchGlobalSyncStatus();
        if (currentMeta?.is_syncing) return;

        const sourceName = "UN Security Council (Continuous)";
        await logAuditEvent('REGISTRY_AUTO_SYNC_INITIATED', `Background synchronization sequence started for: ${sourceName}`, 'System Engine');
        await setGlobalSyncLock(true, 'In Progress...');

        const entries = await fetchAndNormalize(OFFICIAL_UN_XML_URL, sourceName);
        await upsertCloudSanctions(entries);

        const syncTime = new Date().toLocaleString();
        await setGlobalSyncLock(false, syncTime);
        await logIngestionEvent({ 
          timestamp: new Date().toISOString(), 
          source: sourceName, 
          method: 'Automated', 
          status: 'Success', 
          recordsProcessed: entries.length, 
          triggeredBy: 'System Engine'
        });

        await logAuditEvent('REGISTRY_AUTO_SYNC_SUCCESS', `Successfully updated ${entries.length} entities in the authoritative registry.`, 'System Engine');
        loadLogs();
      } catch (err: any) {
        await setGlobalSyncLock(false, "Failed: " + new Date().toLocaleString());
        await logAuditEvent('REGISTRY_AUTO_SYNC_FAULT', `Automated update sequence aborted: ${err.message}`, 'System Engine');
        loadLogs();
      }
    };

    const intervalId = setInterval(runAutomatedSync, settings.syncIntervalMinutes * 60 * 1000);
    return () => clearInterval(intervalId);
  }, [settings.autoSync, settings.syncIntervalMinutes, connectionStatus, isGlobalSyncing, loadLogs]);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');
    setSchemaDiscrepancies([]);
    try {
      initSupabase();
      const healthy = await checkConnection();
      if (healthy) {
        const audit = await validateRegistrySchemaV431();
        if (!audit.success) {
           setConnectionStatus('SAFE_MODE');
           setSchemaDiscrepancies(audit.discrepancies || ['Structural Audit Conflict']);
        } else {
           setConnectionStatus('CONNECTED');
        }

        await Promise.all([
          refreshClients(1),
          loadSanctionsCache(),
          loadLogs(),
          fetchGlobalSyncStatus().then(l => l && handleGlobalMetadataUpdate(l))
        ]);

        if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
        subscriptionRef.current = subscribeToClients(() => refreshClients(currentPageRef.current));

        if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
        syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
      } else {
        setConnectionStatus('SAFE_MODE');
      }
    } catch (e: any) { 
      setConnectionStatus('SAFE_MODE');
      refreshClients(1);
    }
    setTimeout(() => setIsBooting(false), 1500);
  }, [handleGlobalMetadataUpdate, loadSanctionsCache, refreshClients, loadLogs]);

  useEffect(() => { bootEnterpriseNode(); }, [bootEnterpriseNode]);

  const handleGlobalBatchScreening = async () => {
    if (screeningProgress.status === 'In Progress') return;

    await logAuditEvent('GLOBAL_BATCH_SCREENING_INITIATED', `Registry-wide authoritative screening protocol started.`, currentUser?.email || 'System');
    await loadLogs();

    const totalCount = await fetchClientsTotalCount();
    const allClients: Client[] = [];

    for (let i = 0; i < totalCount; i += 50) {
      const batch = await fetchCloudClients(i, i + 49);
      allClients.push(...batch);
    }

    setScreeningProgress({
      totalRecords: totalCount,
      screenedRecords: 0,
      pendingRecords: totalCount,
      status: 'In Progress',
      currentBatch: 0
    });

    for (let i = 0; i < allClients.length; i++) {
      const client = allClients[i];
      try {
        const screened = await screenEntityAgainstDb(client, currentUser?.email);
        await upsertCloudClient(screened);
      } catch (err) {
        console.error(`[Screening] Critical Fault for entity "${client["Client Name"]}":`, err);
      }

      setScreeningProgress(prev => ({
        ...prev,
        screenedRecords: i + 1,
        pendingRecords: totalCount - (i + 1)
      }));
    }

    const finalRiskSummary = await fetchGlobalRiskCounts();
    setRiskSummary(finalRiskSummary);

    setScreeningProgress(prev => ({ ...prev, status: 'Completed' }));
    await logAuditEvent('GLOBAL_BATCH_SCREENING_COMPLETED', `Successfully processed screening pass for ${totalCount} records.`, currentUser?.email || 'System');
    await loadLogs();

    setTimeout(() => {
      setScreeningProgress(prev => ({ ...prev, status: 'Not Started' }));
    }, 10000);
  };

  const handleAddClientWithAuthoritativeScreening = async (newClient: Client) => {
    setIsRefreshingClients(true);
    try {
      const screenedClient = await screenEntityAgainstDb(newClient, currentUser?.email);
      await upsertCloudClient(screenedClient);
      await logAuditEvent('ENTITY_PROVISIONED', `Entity "${newClient["Client Name"]}" provisioned to registry.`, currentUser?.email || 'System');
      await loadLogs();
      await refreshClients(currentClientsPage); 
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
        await refreshClients(currentClientsPage);
      } else {
        throw e;
      }
    } finally { setIsRefreshingClients(false); }
  };

  const handleDeleteClient = async (id: string) => {
    const client = clients.find(c => c.id === id);
    setIsRefreshingClients(true);
    try {
      await deleteCloudClient(id);
      await logAuditEvent('ENTITY_REVOKED', `Entity "${client?.["Client Name"] || id}" removed from registry.`, currentUser?.email || 'System');
      await loadLogs();
      await refreshClients(currentClientsPage);
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
        await refreshClients(currentClientsPage);
      } else {
        alert(`Deletion Error: ${e.message}.`); 
      }
    } finally { setIsRefreshingClients(false); }
  };

  const handleUpdateClient = async (updatedClient: Client) => {
    try {
      const original = clients.find(c => c.id === updatedClient.id);
      await upsertCloudClient(updatedClient);

      if (original?.kyc_status !== updatedClient.kyc_status) {
        await logAuditEvent('KYC_STATUS_OVERRIDE', `Status for "${updatedClient["Client Name"]}" changed to ${updatedClient.kyc_status}.`, currentUser?.email || 'System');
      } else {
        await logAuditEvent('ENTITY_MODIFIED', `Data updated for entity "${updatedClient["Client Name"]}".`, currentUser?.email || 'System');
      }
      await loadLogs();

      setClients(prev => prev.map(c => c.id === updatedClient.id ? { ...updatedClient } : c));

      if (original?.riskLevel !== updatedClient.riskLevel) {
        const nextRisks = await fetchGlobalRiskCounts();
        setRiskSummary(nextRisks);
      }
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
      } else {
        throw e;
      }
    }
  };

  const handlePasswordUpdate = async (newPassword: string) => {
    if (!currentUser) return;
    try {
      const dbPayload: any = { ...currentUser };
      dbPayload.password_hash_mock = newPassword;
      dbPayload.must_change_password = false;
      delete dbPayload.password;
      delete dbPayload.confirmPassword;
      await upsertCloudUser(dbPayload);
      await logAuditEvent('PASSWORD_ROTATION', `Security policy enforced: Password updated.`, currentUser.email);
      await loadLogs();
      const updatedUser = { ...currentUser, must_change_password: false, password_hash_mock: newPassword };
      setCurrentUser(updatedUser);
      localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      alert("Security Handshake Complete: Password updated successfully.");
    } catch (e: any) { alert("Failed to update password: " + e.message); }
  };

  const effectiveEnvironment = (currentUser?.id === 'SYS-ROOT') ? settings.environment : SystemEnvironment.PRODUCTION;

  if (!currentUser) {
    return <Login onLogin={(u) => { 
      setCurrentUser(u); 
      localStorage.setItem('unsg_session', JSON.stringify(u)); 
      logAuditEvent('SESSION_INITIALIZED', `User authenticated successfully.`, u.email).then(() => loadLogs());
    }} isCloudConnected={connectionStatus === 'CONNECTED' || connectionStatus === 'SAFE_MODE'} />;
  }

  if (currentUser.must_change_password) {
    return <PasswordUpdate user={currentUser} onUpdate={handlePasswordUpdate} />;
  }

  return (
    <Router>
      <Layout 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'} 
        isSafeMode={connectionStatus === 'SAFE_MODE'} 
        schemaFaults={schemaDiscrepancies}
        onLogout={() => { 
          logAuditEvent('SESSION_TERMINATED', `User logged out.`, currentUser.email).then(() => loadLogs());
          setCurrentUser(null); 
          localStorage.removeItem('unsg_session'); 
        }} 
        currentUser={currentUser} 
        onRetryConnection={() => bootEnterpriseNode()} 
        environment={effectiveEnvironment}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} totalClientsCount={clientsCount} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} riskSummary={riskSummary} />} />
          <Route path="/clients" element={<ClientManager clients={clients} totalCount={clientsCount} currentPage={currentClientsPage} onPageChange={refreshClients} isRefreshing={isRefreshingClients} onAddClient={handleAddClientWithAuthoritativeScreening} onDeleteClient={handleDeleteClient} onRefresh={() => refreshClients(currentClientsPage)} onReScreen={handleGlobalBatchScreening} onUpdateClient={handleUpdateClient} screeningProgress={screeningProgress} currentUserRole={currentUser.role} currentUserId={currentUser.id} />} />
          <Route path="/sanctions" element={<SanctionsRegistry onSyncComplete={() => loadSanctionsCache()} isCloudConnected={connectionStatus === 'CONNECTED' || connectionStatus === 'SAFE_MODE'} initialStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} currentUser={currentUser} />} />
          <Route path="/admin" element={currentUser.is_system_admin === true ? <AdminPanel settings={settings} logs={systemLogs} onUpdateSettings={(s) => { 
            logAuditEvent('SYSTEM_SETTINGS_MODIFIED', `Environment set to ${s.environment}.`, currentUser.email).then(() => loadLogs());
            setSettings(s); 
            localStorage.setItem('unsg_settings', JSON.stringify(s)); 
          }} currentUser={currentUser} onLogsRefresh={loadLogs} /> : <Navigate to="/" replace />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Users, Globe, FileText, Settings, Menu, X, Wifi, WifiOff, LogOut, ShieldCheck, Clock, RefreshCw, AlertTriangle, ChevronRight, Share2, Database, Shield, Activity, Beaker, ShieldAlert, Terminal } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';
import { UserProfile, UserRole, SystemEnvironment, APP_VERSION } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  isCloudConnected: boolean;
  isConnecting?: boolean;
  isSafeMode?: boolean;
  schemaFaults?: string[];
  onLogout: () => void;
  currentUser: UserProfile;
  onRetryConnection?: () => void;
  onSettingsRequest?: () => void;
  environment?: SystemEnvironment;
}

const Layout: React.FC<LayoutProps> = ({ 
  children, 
  isCloudConnected, 
  isConnecting, 
  isSafeMode, 
  schemaFaults = [], 
  onLogout, 
  currentUser, 
  onRetryConnection, 
  onSettingsRequest, 
  environment 
}) => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isDiagOpen, setIsDiagOpen] = useState(false);
  const [registryStats, setRegistryStats] = useState({ lastSourceUpdate: 'Never' });
  const location = useLocation();

  const PRIMARY_LOGO = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";
  const LOCAL_LOGO = "/images/logo.png";
  const FALLBACK_LOGO = "https://placehold.co/600x400/064e3b/ffffff?text=RPME+LIMITED+LLC";

  useEffect(() => {
    const updateStats = () => {
      const saved = localStorage.getItem('unsg_registry_stats');
      if (saved) setRegistryStats(JSON.parse(saved));
    };
    updateStats();
    window.addEventListener('storage', updateStats);
    return () => window.removeEventListener('storage', updateStats);
  }, []);

  const navItems = [
    { label: 'System Dashboard', path: '/', icon: <LayoutDashboard size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.DATA_ENTRY, UserRole.REPORTING, UserRole.AUDITOR] },
    { label: 'Client Onboarding', path: '/clients', icon: <Users size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.DATA_ENTRY] },
    { label: 'Sanctions Registry', path: '/sanctions', icon: <Globe size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.DATA_ENTRY, UserRole.AUDITOR] },
    { label: 'Regulatory Reports', path: '/reports', icon: <FileText size={20} />, roles: [UserRole.ADMIN, UserRole.REVIEWER, UserRole.REPORTING] },
    { label: 'Governance', path: '/admin', icon: <Settings size={20} />, roles: [], adminOnly: true },
  ];

  const filteredNavItems = navItems.filter(item => {
