                             >
                                <option value="">-- Ignore Field --</option>
                                {detectedHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                             </select>
                          </div>
                       </div>
                    ))}
                 </div>
              </div>

              <div className="p-8 border-t bg-white flex justify-end items-center gap-4 shrink-0">
                 <button onClick={() => setStatus('IDLE')} className="px-8 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">Abort Import</button>
                 <button 
                   onClick={executeMappedImport}
                   className="px-12 py-4 bg-emerald-800 text-white rounded-2xl font-black text-[11px] uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-900 transition-all flex items-center gap-3"
                 >
                    <ShieldCheck size={18} /> Commit {pendingData.length} Entities
                 </button>
              </div>
           </div>
        </div>
      )}

      {errorMessage && (
        <div className="p-6 bg-red-50 border border-red-100 rounded-3xl text-red-600 flex items-start gap-4 animate-in slide-in-from-top-2">
           <AlertTriangle size={20} className="shrink-0 mt-0.5" />
           <div className="space-y-1">
              <p className="text-[10px] font-black uppercase tracking-widest">Ingestion Fault</p>
              <p className="text-xs font-bold leading-relaxed">{errorMessage}</p>
           </div>
        </div>
      )}

      <div className="space-y-6">
         <div className="flex flex-col sm:flex-row gap-4 items-stretch sm:items-center bg-white p-4 sm:p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
            <div className="relative flex-1">
               <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20}/>
               <input 
                  type="text" 
                  placeholder="Interrogate Master Registry (e.g. GREENLAND, QA-102)..." 
                  className="w-full pl-16 pr-6 py-5 bg-gray-50/50 rounded-2xl border-2 border-transparent focus:border-emerald-800 focus:bg-white outline-none text-sm font-black uppercase transition-all" 
                  value={searchTerm} 
                  onChange={e => { setSearchTerm(e.target.value); setCurrentPage(1); }} 
               />
               {isSearching && <Loader2 className="absolute right-6 top-1/2 -translate-y-1/2 animate-spin text-emerald-800" size={18}/>}
            </div>
            <div className="px-8 py-5 bg-emerald-50 border border-emerald-100 rounded-2xl flex flex-col items-center justify-center min-w-[200px]">
               <div className="flex items-center gap-2 mb-1">
                  <Database size={12} className="text-emerald-700" />
                  <span className="text-[8px] font-black text-emerald-800 uppercase tracking-widest">Master Count</span>
               </div>
               <span className="text-base font-black text-emerald-950">{totalInDb.toLocaleString()}</span>
            </div>
         </div>

         <div className="bg-white rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden">
            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left min-w-[900px]">
                 <thead className="bg-gray-50 border-b">
                    <tr className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                       <th className="px-10 py-6">Legal Name / Identity</th>
                       <th className="px-10 py-6">Reference Profile</th>
                       <th className="px-10 py-6">Jurisdiction</th>
                       <th className="px-10 py-6 text-right">Source Protocol</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {sanctions.length > 0 ? (
                       sanctions.map(s => (
                          <tr key={s.dataId} className="hover:bg-emerald-50/30 transition-colors group">
                             <td className="px-10 py-5">
                                <div className="text-sm font-black text-slate-900 uppercase group-hover:text-emerald-900 transition-colors">
                                   {[s.firstName, s.lastName].filter(Boolean).join(' ')}
                                </div>
                                <div className="text-[9px] text-gray-400 font-bold uppercase mt-1 tracking-tighter">DATA_ID: {s.dataId}</div>
                             </td>
                             <td className="px-10 py-5">
                                <div className="flex items-center gap-2">
                                   <FileCode size={14} className="text-gray-300" />
                                   <span className="text-[10px] font-black text-slate-500 uppercase">{s.referenceNumber || 'INTERNAL-REF'}</span>
                                </div>
                             </td>
                             <td className="px-10 py-5">
                                <div className="flex items-center gap-2">
                                   <MapPin size={14} className="text-gray-300" />
                                   <span className="text-[10px] font-black text-slate-500 uppercase">{s.nationality || 'UNKNOWN'}</span>
                                </div>
                             </td>
                             <td className="px-10 py-5 text-right">
                                <span className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase border ${
                                  s.source === 'UN Consolidated' ? 'bg-blue-50 text-blue-700 border-blue-100' :
                                  s.source === 'Qatar NCTC' ? 'bg-amber-50 text-amber-700 border-amber-100' :
                                  'bg-slate-50 text-slate-500 border-slate-200'
                                }`}>
                                   {s.source}
                                </span>
                             </td>
                          </tr>
                       ))
                    ) : (
                       <tr>
                          <td colSpan={4} className="py-24 text-center">
                             {isSearching ? (
                               <div className="flex flex-col items-center gap-4">
                                  <Loader2 className="animate-spin text-emerald-800" size={40} />
                                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Interrogating Master Registry...</p>
                               </div>
                             ) : (
                               <div className="flex flex-col items-center gap-4 opacity-30">
                                  <Search size={48} className="text-gray-300" />
                                  <p className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em]">No Authoritative Matches Found</p>
                               </div>
                             )}
                          </td>
                       </tr>
                    )}
                 </tbody>
              </table>
            </div>

            {totalMatches > ITEMS_PER_PAGE && (
              <div className="p-8 border-t border-gray-100 bg-gray-50/30 flex justify-between items-center">
                 <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                    Showing <span className="text-emerald-900">{sanctions.length}</span> of {totalMatches.toLocaleString()} Matches
                 </div>
                 <div className="flex items-center gap-2">
                    <button 
                      onClick={() => setCurrentPage(p => Math.max(1, p - 1))} 
                      disabled={currentPage === 1}
                      className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 transition-all disabled:opacity-30 shadow-sm"
                    >
                       <ChevronLeft size={18} />
                    </button>
                    <div className="px-6 py-3 bg-white border border-gray-200 rounded-xl text-[10px] font-black text-emerald-950 uppercase tracking-widest shadow-sm">
                       Page {currentPage} of {Math.ceil(totalMatches / ITEMS_PER_PAGE)}
                    </div>
                    <button 
                      onClick={() => setCurrentPage(p => Math.min(Math.ceil(totalMatches / ITEMS_PER_PAGE), p + 1))} 
                      disabled={currentPage >= Math.ceil(totalMatches / ITEMS_PER_PAGE)}
                      className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 transition-all disabled:opacity-30 shadow-sm"
                    >
                       <ChevronRight size={18} />
                    </button>
                 </div>
              </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default SanctionsRegistry;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SanctionEntry, SystemEnvironment, IngestionLog, UserRole, EntityType } from '../types';
import { 
  RefreshCw, Search, Cpu, Globe, Upload, Layers, X, 
  CheckCircle, AlertTriangle, Loader2, FileJson, 
  Table as TableIcon, FileCode, CheckCircle2, ChevronRight,
  Database, Info, ArrowRight, ShieldCheck, MapPin, 
  Settings2, FileSpreadsheet, CloudDownload, ChevronLeft
} from 'lucide-react';
import { 
  fetchSanctionsTotalCount, 
  upsertCloudSanctions, 
  setGlobalSyncLock, 
  logIngestionEvent, 
  fetchIngestionLogs, 
  searchSanctionsAuthoritative,
  logAuditEvent
} from '../services/cloudDb';
import { 
  fetchAndNormalize, 
  detectFormat, 
  parseUNSanctionsXML, 
  parseCSVToSanctions, 
  parseExcelToSanctions, 
  mapFieldsToSanction, 
  OFFICIAL_UN_XML_URL, 
  QATAR_NCTC_URL, 
  OPENSANCTIONS_URL 
} from '../services/unSanctionsService';

interface SanctionsRegistryProps {
  onSyncComplete: () => void;
  isCloudConnected: boolean;
  initialStats?: { lastSourceUpdate: string };
  isGlobalSyncing?: boolean;
  environment?: SystemEnvironment;
  currentUser?: { role: UserRole; id: string; email: string };
}

const ITEMS_PER_PAGE = 15;

const REQUIRED_SYSTEM_FIELDS = [
  { key: 'firstName', label: 'First Name / Primary Identity' },
  { key: 'lastName', label: 'Last Name / Surname' },
  { key: 'dataId', label: 'Reference ID / Data ID' },
  { key: 'nationality', label: 'Nationality / Jurisdiction' },
  { key: 'referenceNumber', label: 'Official Ref Number' },
  { key: 'comments', label: 'Comments / Details' },
  { key: 'type', label: 'Entity Type (Individual/Corporate)' }
];

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, isGlobalSyncing, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'hub' | 'audit'>('hub');
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalMatches, setTotalMatches] = useState(0);
  const [totalInDb, setTotalInDb] = useState(0);
  const [status, setStatus] = useState<'IDLE' | 'WORKING' | 'SUCCESS' | 'ERROR' | 'MAPPING'>('IDLE');
  const [uploadProgress, setUploadProgress] = useState(0);
  const [ingestionCount, setIngestionCount] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [ingestionHistory, setIngestionHistory] = useState<IngestionLog[]>([]);

  const [pendingData, setPendingData] = useState<any[]>([]);
  const [pendingSource, setPendingSource] = useState('');
  const [detectedHeaders, setDetectedHeaders] = useState<string[]>([]);
  const [fieldMapping, setFieldMapping] = useState<Record<string, string>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);

  const performSearch = useCallback(async (page: number, term: string) => {
    setIsSearching(true);
    try {
      const from = (page - 1) * ITEMS_PER_PAGE;
      const to = from + ITEMS_PER_PAGE - 1;
      const response = await searchSanctionsAuthoritative(term, from, to);
      setSanctions(response.data);
      setTotalMatches(response.count);
      if (!term) setTotalInDb(response.count);
    } catch (e) {
      console.error(e);
    } finally {
      setIsSearching(false);
    }
  }, []);

  useEffect(() => {
    const t = setTimeout(() => performSearch(1, searchTerm), 300);
    return () => clearTimeout(t);
  }, [searchTerm, performSearch]);

  useEffect(() => {
    performSearch(currentPage, searchTerm);
  }, [currentPage, performSearch]);

  const refreshLogs = useCallback(async () => {
    const logs = await fetchIngestionLogs();
    setIngestionHistory(logs);
    const count = await fetchSanctionsTotalCount();
    setTotalInDb(count);
  }, []);

  useEffect(() => { refreshLogs(); }, [refreshLogs]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setStatus('WORKING');
    setErrorMessage(null);
    setUploadProgress(1); // Start with 1% to show the bar

    const fileName = file.name;
    const reader = new FileReader();

    reader.onload = async (event) => {
      try {
        const content = event.target?.result;
        const format = detectFormat(typeof content === 'string' ? content : '', fileName);

        if (format === 'UNKNOWN') throw new Error("Unsupported file format. Please use XML, CSV, Excel, or JSON.");

        let rawData: any[] = [];

        if (format === 'XML') {
          const entries = parseUNSanctionsXML(content as string);
          await commitSanctions(entries, fileName, 'Manual');
          return;
        } else if (format === 'JSON') {
          // Fix: Use a separate variable to parse JSON and determine its structure before assigning to the array-typed 'rawData'
          const parsed = JSON.parse(content as string);
          if (Array.isArray(parsed)) {
            rawData = parsed;
          } else {
            // Check if it's an OpenSanctions style object
            rawData = (parsed as any).entities || (parsed as any).data || [parsed];
          }
        } else if (format === 'CSV') {
          rawData = parseCSVToSanctions(content as string, fileName);
        } else if (format === 'EXCEL') {
          rawData = parseExcelToSanctions(content as ArrayBuffer, fileName);
        }

        if (rawData.length === 0) throw new Error("The selected file contains no identifiable entity records.");

        setPendingData(rawData);
        setPendingSource(fileName);
        const headers = Object.keys(rawData[0]);
        setDetectedHeaders(headers);

        const initialMapping: Record<string, string> = {};
        REQUIRED_SYSTEM_FIELDS.forEach(sf => {
          const match = headers.find(h => 
            h.toLowerCase().includes(sf.key.toLowerCase()) || 
            sf.label.toLowerCase().includes(h.toLowerCase())
          );
          if (match) initialMapping[sf.key] = match;
        });

        setFieldMapping(initialMapping);
        setStatus('MAPPING');
      } catch (err: any) {
        setErrorMessage(err.message);
        setStatus('ERROR');
      }
    };

    if (fileName.match(/\.(xlsx|xls)$/i)) {
      reader.readAsArrayBuffer(file);
    } else {
      reader.readAsText(file);
    }
  };

  const executeMappedImport = async () => {
    if (pendingData.length === 0) return;
    setStatus('WORKING');

    try {
      const mappedEntries = pendingData.map(row => mapFieldsToSanction(row, fieldMapping, pendingSource));
      await commitSanctions(mappedEntries, pendingSource, 'Manual');
    } catch (err: any) {
      setErrorMessage(err.message);
      setStatus('ERROR');
    }
  };

  const commitSanctions = async (entries: SanctionEntry[], source: string, method: 'Automated' | 'Manual') => {
    const userHandle = currentUser?.email || currentUser?.id || 'System';
    setIngestionCount(entries.length);
    try {
      await setGlobalSyncLock(true, `${method} Upload: ${source}`);
      await upsertCloudSanctions(entries, p => setUploadProgress(p));
      await setGlobalSyncLock(false, new Date().toLocaleString());

      await logIngestionEvent({ 
        timestamp: new Date().toISOString(), 
        source: source, 
        method: method, 
        status: 'Success', 
        recordsProcessed: entries.length, 
        triggeredBy: userHandle
      });

      await logAuditEvent(
        method === 'Automated' ? 'REGISTRY_SYNC_FEED' : 'REGISTRY_MANUAL_IMPORT',
        `Registry update: Processed ${entries.length} entities from ${source}.`,
        userHandle
      );

      setStatus('SUCCESS');
      onSyncComplete();
      refreshLogs();

      setTimeout(() => {
        if (fileInputRef.current) fileInputRef.current.value = '';
        setStatus('IDLE');
        setUploadProgress(0);
      }, 5000);
    } catch (err: any) {
      await setGlobalSyncLock(false, "Sync Failed");
      setErrorMessage(err.message);
      setStatus('ERROR');
      await logAuditEvent('INGESTION_FAILURE', `Registry update failed for ${source}: ${err.message}`, userHandle);
    }
  };

  const handleFetch = async (url: string, name: string) => {
    setStatus('WORKING');
    setUploadProgress(5); // Show immediate transport progress
    setErrorMessage(null);
    try {
      const data = await fetchAndNormalize(url, name);
      if (!data || data.length === 0) {
        throw new Error(`Authoritative feed ${name} returned an empty dataset. This may be due to a proxy timeout or structural change in the source feed.`);
      }
      await commitSanctions(data, name, 'Automated');
    } catch (err: any) {
      setErrorMessage(err.message || "An unexpected error occurred during the authoritative handshake.");
      setStatus('ERROR');
    }
  };

  return (
    <div className="space-y-8 pb-20">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm gap-6">
         <div className="flex items-center gap-4">
            <div className="bg-emerald-950 p-4 rounded-2xl text-emerald-400 shadow-lg"><Cpu size={28}/></div>
            <div>
               <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Sanctions Master Hub</h2>
               <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Multi-Source Universal Registry</p>
            </div>
         </div>
         <div className="flex bg-slate-50 p-1 rounded-2xl border w-full sm:w-auto">
            <button onClick={() => setActiveTab('hub')} className={`flex-1 sm:flex-none px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'hub' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>Import Hub</button>
            <button onClick={() => setActiveTab('audit')} className={`flex-1 sm:flex-none px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'audit' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>Ingestion Audit</button>
         </div>
      </div>

      {activeTab === 'hub' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-10 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
             <div className="flex items-center gap-4 border-b border-gray-50 pb-6">
                <div className="p-3 bg-blue-50 text-blue-600 rounded-xl"><Globe size={20}/></div>
                <h3 className="text-sm font-black uppercase text-slate-900 tracking-wider">Enterprise Automated Feeds</h3>
             </div>
             <div className="grid grid-cols-1 gap-4">
               {[
                 { name: 'UN Security Council (Consolidated)', url: OFFICIAL_UN_XML_URL, info: 'Global Authoritative Baseline' },
                 { name: 'Qatar NCTC (Unified List)', url: QATAR_NCTC_URL, info: 'National Counter-Terrorism Authority' },
                 { name: 'OpenSanctions (Composite)', url: OPENSANCTIONS_URL, info: 'International Multi-Source Dataset' }
               ].map(s => (
                 <button 
                   key={s.name} 
                   onClick={() => handleFetch(s.url, s.name)} 
                   disabled={status === 'WORKING'} 
                   className="group flex items-center justify-between p-6 bg-slate-50 border border-transparent hover:border-blue-200 hover:bg-white rounded-2xl transition-all disabled:opacity-30"
                 >
                   <div className="text-left">
                      <p className="text-[11px] font-black text-slate-900 uppercase">{s.name}</p>
                      <p className="text-[8px] text-gray-400 font-bold uppercase mt-1 tracking-widest">{s.info}</p>
                   </div>
                   <CloudDownload size={20} className="text-blue-500 group-hover:scale-110 transition-transform" />
                 </button>
               ))}
             </div>
          </div>

          <div className="bg-emerald-950 p-10 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
                <Upload size={140} />
             </div>

             <div className="relative z-10 space-y-8">
                <div className="flex items-center gap-4 border-b border-white/10 pb-6">
                   <div className="p-3 bg-white/10 text-emerald-400 rounded-xl"><Layers size={20}/></div>
                   <div>
                      <h3 className="text-sm font-black uppercase tracking-wider">Universal Manual Import</h3>
                      <p className="text-[9px] text-emerald-400/60 font-black uppercase tracking-widest mt-1">XML • CSV • XLSX • JSON</p>
                   </div>
                </div>

                <div className="space-y-4">
                   <input 
                      type="file" 
                      ref={fileInputRef} 
                      onChange={handleFileUpload} 
                      className="hidden" 
                      accept=".xml,.csv,.xlsx,.xls,.json"
                   />
                   <button 
                     onClick={() => fileInputRef.current?.click()} 
                     disabled={status === 'WORKING'}
                     className="w-full py-6 bg-white text-emerald-950 rounded-2xl font-black text-[11px] uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-50 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                   >
                      <Upload size={20} /> Deploy Data Bundle
                   </button>
                </div>

                <div className="grid grid-cols-2 gap-4">
                   <div className="p-4 bg-white/5 border border-white/10 rounded-2xl text-center">
                      <FileSpreadsheet size={16} className="mx-auto mb-2 text-emerald-400" />
                      <p className="text-[8px] font-black uppercase tracking-widest text-emerald-100">XLSX Mapping</p>
                   </div>
                   <div className="p-4 bg-white/5 border border-white/10 rounded-2xl text-center">
                      <FileCode size={16} className="mx-auto mb-2 text-blue-400" />
                      <p className="text-[8px] font-black uppercase tracking-widest text-emerald-100">XML Support</p>
                   </div>
                </div>

                {status === 'WORKING' && (
                  <div className="space-y-3 animate-in fade-in slide-in-from-bottom-2">
                     <div className="flex justify-between items-center text-[9px] font-black uppercase tracking-widest">
                        <span className="text-emerald-400 flex items-center gap-2">
                           <Loader2 size={12} className="animate-spin" /> 
                           {uploadProgress <= 5 ? 'Initiating Authoritative Transport...' : 'Synchronizing Cloud Registry...'}
                        </span>
                        <span>{uploadProgress}%</span>
                     </div>
                     <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden">
                        <div className="h-full bg-emerald-400 transition-all duration-300" style={{width: `${uploadProgress}%`}}/>
                     </div>
                  </div>
                )}

                {status === 'SUCCESS' && (
                  <div className="p-4 bg-emerald-500/20 border border-emerald-500/30 rounded-2xl flex items-center gap-3 text-emerald-400 animate-in zoom-in-95">
                     <CheckCircle2 size={24} />
                     <div className="min-w-0">
                        <p className="text-[10px] font-black uppercase tracking-widest">Registry Synchronized Successfully</p>
                        <p className="text-[8px] font-bold uppercase opacity-60 mt-0.5">{ingestionCount.toLocaleString()} entities provisioned to master tier.</p>
                     </div>
                  </div>
                )}
             </div>
          </div>
        </div>
      )}

      {status === 'MAPPING' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[200] flex items-center justify-center p-6">
           <div className="bg-white rounded-[3rem] w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in-95">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center shrink-0">
                 <div className="flex items-center gap-4">
                    <div className="p-3 bg-white/10 rounded-xl text-emerald-400"><Settings2 size={24}/></div>
                    <div>
                       <h3 className="text-xl font-black uppercase">Field Alignment Protocol</h3>
                       <p className="text-[9px] text-emerald-400/60 font-black uppercase tracking-widest mt-1">File: {pendingSource}</p>
                    </div>
                 </div>
                 <button onClick={() => setStatus('IDLE')} className="p-3 bg-white/10 rounded-full hover:bg-white/20 transition-all"><X size={20}/></button>
              </div>

              <div className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar bg-gray-50/30">
                 <div className="bg-blue-50 border border-blue-100 p-6 rounded-[2rem] flex gap-4 text-blue-800">
                    <Info size={24} className="shrink-0" />
                    <div className="space-y-1">
                       <p className="text-[10px] font-black uppercase tracking-widest">Action Required</p>
                       <p className="text-xs font-bold leading-relaxed">Please map the headers from your file to our system fields. We detected <span className="text-blue-900 font-black">{pendingData.length} entities</span> ready for ingestion.</p>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 gap-6">
                    {REQUIRED_SYSTEM_FIELDS.map(sf => (
                       <div key={sf.key} className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-6 bg-white border border-gray-100 rounded-2xl shadow-sm hover:border-emerald-200 transition-all">
                          <div className="space-y-1">
                             <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{sf.label}</p>
                             <p className="text-[8px] font-black text-emerald-600 uppercase">System Key: {sf.key}</p>
