        throw new Error(`Authoritative feed ${name} returned an empty dataset. This may be due to a proxy timeout, JS-heavy rendering on the portal, or a structural change in the source.`);
      }
      await commitSanctions(data, name, 'Automated');
    } catch (err: any) {
      setErrorMessage(err.message || "An unexpected error occurred during the authoritative handshake.");
      setStatus('ERROR');
    }
  };

