/**
 * Advanced parser for Qatar NCTC Portal HTML table structure.
 * Now uses dynamic header detection and more flexible row matching.
 */
export const parseQatarNCTCHTML = (htmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const doc = parser.parseFromString(htmlString, "text/html");
  const entries: SanctionEntry[] = [];

  // Search across all table rows in the document
  const rows = Array.from(doc.querySelectorAll('tr'));
  if (rows.length === 0) return [];

  let nameCol = -1;
  let refCol = -1;
  let natCol = -1;
  let headerFound = false;

  // Attempt to find the table header row to map columns dynamically
  // We scan the first few rows looking for keywords in English or Arabic
  for (let i = 0; i < Math.min(rows.length, 30); i++) {
    const text = rows[i].textContent?.toUpperCase() || '';
    if (text.includes('NAME') || text.includes('الاسم') || text.includes('IDENTITY') || text.includes('NO.')) {
      const cells = Array.from(rows[i].querySelectorAll('td, th'));
      cells.forEach((cell, idx) => {
        const cText = cell.textContent?.trim().toUpperCase() || '';
        if (cText.includes('NAME') || cText.includes('الاسم') || cText.includes('FULL NAME')) nameCol = idx;
        if (cText.includes('REF') || cText.includes('NO') || cText.includes('الرقم')) refCol = idx;
        if (cText.includes('NAT') || cText.includes('الجنسية') || cText.includes('CITIZENSHIP')) natCol = idx;
      });
      if (nameCol !== -1) {
        headerFound = true;
        break;
      }
    }
  }

  // Conservative fallbacks if no headers were clearly identified
  if (!headerFound) {
    // These defaults reflect common portal layouts if automated mapping fails
    nameCol = 1; 
    refCol = 0;  
    natCol = 2;  
  }

  rows.forEach((row) => {
    const cells = Array.from(row.querySelectorAll('td'));
    // Portal rows usually have between 3 to 10 columns
    if (cells.length < 2) return;

    const nameText = cells[nameCol]?.textContent?.trim() || '';
    const refNo = cells[refCol]?.textContent?.trim() || '';
    const nationality = cells[natCol]?.textContent?.trim() || 'Qatar';

    // Filter out rows that are clearly headers, navigational, or too short to be valid identities
    const normalizedName = nameText.toUpperCase();
    if (!nameText || nameText.length < 3) return;

    // Skip if name contains header keywords
    if (normalizedName.includes('NAME') || normalizedName.includes('الاسم') || normalizedName.includes('FULLNAME')) return;

    // Split name into parts for the SanctionEntry format
    const nameParts = nameText.split(/\s+/);

    entries.push({
      dataId: `QA-NCTC-${refNo.replace(/[^a-zA-Z0-9]/g, '') || 'R' + Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      source: 'Qatar NCTC',
      firstName: nameParts[0] || 'UNKNOWN',
      lastName: nameParts.slice(1).join(' ') || '',
      unListType: 'National Unified List',
      referenceNumber: refNo || 'QA-REF-NCTC',
      listedOn: new Date().toISOString().split('T')[0],
      comments: `Portal Scrape Node: Automated high-confidence ingestion.`,
      nationality: nationality,
      aliases: [],
      type: EntityType.INDIVIDUAL,
      fetchDate: new Date().toISOString()
    });
  });

  return entries;
};

/**
 * Parses the UN Consolidated List XML string with defensive node checking
 */
export const parseUNSanctionsXML = (xmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlString, "text/xml");
  const entries: SanctionEntry[] = [];

  const getNodeVal = (parent: Element, tagName: string): string => {
    const node = parent.getElementsByTagName(tagName)[0];
    return node ? node.textContent?.trim() || '' : '';
  };

  const parseNode = (node: Element, isInd: boolean): SanctionEntry => {
    const natNode = node.getElementsByTagName("NATIONALITY")[0];
    const nationality = natNode ? getNodeVal(natNode, "VALUE") : '';

    const dobNode = node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0];
    const dob = dobNode ? getNodeVal(dobNode, "DATE") : '';

    return {
      dataId: `UN-${getNodeVal(node, "DATAID")}`,
      source: 'UN Consolidated',
      firstName: getNodeVal(node, "FIRST_NAME"),
      secondName: getNodeVal(node, "SECOND_NAME"),
      thirdName: getNodeVal(node, "THIRD_NAME"),
      lastName: getNodeVal(node, "LAST_NAME"),
      unListType: getNodeVal(node, "UN_LIST_TYPE"),
      referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
      listedOn: getNodeVal(node, "LISTED_ON"),
      comments: getNodeVal(node, "COMMENTS1"),
      nationality: nationality,
      dateOfBirth: isInd ? dob : '',
      aliases: Array.from(node.getElementsByTagName(isInd ? "INDIVIDUAL_ALIAS" : "ENTITY_ALIAS"))
        .map(a => getNodeVal(a, "ALIAS_NAME"))
        .filter(Boolean),
      type: isInd ? EntityType.INDIVIDUAL : EntityType.CORPORATE,
      fetchDate: new Date().toISOString()
    };
  };

  const individuals = xmlDoc.getElementsByTagName("INDIVIDUAL");
  for (let i = 0; i < individuals.length; i++) {
    const entry = parseNode(individuals[i], true);
    if (entry.firstName || entry.lastName) entries.push(entry);
  }

  const entities = xmlDoc.getElementsByTagName("ENTITY");
  for (let i = 0; i < entities.length; i++) {
    const entry = parseNode(entities[i], false);
    if (entry.firstName || entry.lastName) entries.push(entry);
  }

  return entries;
};

