// Fix: Implement missing exported function to detect file format based on content and filename
export const detectFormat = (content: string, fileName: string): 'XML' | 'CSV' | 'EXCEL' | 'JSON' | 'UNKNOWN' => {
  const ext = fileName.split('.').pop()?.toUpperCase();
  if (ext === 'XLSX' || ext === 'XLS') return 'EXCEL';
  if (ext === 'CSV') return 'CSV';
  if (ext === 'JSON') return 'JSON';
  if (ext === 'XML') return 'XML';

  const trimmed = content.trim();
  if (trimmed.startsWith('<?xml') || trimmed.startsWith('<')) return 'XML';
  if (trimmed.startsWith('[') || trimmed.startsWith('{')) return 'JSON';
  if (trimmed.includes(',') && trimmed.includes('\n')) return 'CSV';

  return 'UNKNOWN';
};

