/**
 * Advanced parser for Qatar NCTC Portal HTML table structure.
 * Scans the DOM for potential data tables and maps columns based on keyword density.
 */
export const parseQatarNCTCHTML = (htmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const doc = parser.parseFromString(htmlString, "text/html");
  const entries: SanctionEntry[] = [];

  // Portals often nest tables deeply. We look for rows that contain multiple cells.
  const rows = Array.from(doc.querySelectorAll('tr, .table-row, [role="row"]'));
  if (rows.length === 0) return [];

  let nameCol = -1;
  let refCol = -1;
  let natCol = -1;

  // Dynamic header discovery across the first 50 rows (handling potential pagination info)
  for (let i = 0; i < Math.min(rows.length, 50); i++) {
    const cells = Array.from(rows[i].querySelectorAll('td, th, .table-cell, [role="gridcell"]'));
    const rowText = rows[i].textContent?.toUpperCase() || '';

    // Look for Arabic or English identifying keywords
    const isHeaderCandidate = (
      rowText.includes('NAME') || rowText.includes('الاسم') || 
      rowText.includes('IDENTITY') || rowText.includes('FULL') ||
      rowText.includes('NO.') || rowText.includes('الرقم')
    );

    if (isHeaderCandidate) {
      cells.forEach((cell, idx) => {
        const cText = cell.textContent?.trim().toUpperCase() || '';
        if (cText.includes('NAME') || cText.includes('الاسم') || cText.includes('البيان')) nameCol = idx;
        if (cText.includes('REF') || cText.includes('NO') || cText.includes('الرقم') || cText.includes('التسلسل')) refCol = idx;
        if (cText.includes('NAT') || cText.includes('الجنسية') || cText.includes('CITIZENSHIP')) natCol = idx;
      });
      if (nameCol !== -1) break; // Found headers
    }
  }

  // Fallbacks if no explicit headers found
  if (nameCol === -1) nameCol = 1;
  if (refCol === -1) refCol = 0;
  if (natCol === -1) natCol = 2;

  rows.forEach((row) => {
    const cells = Array.from(row.querySelectorAll('td, .table-cell, [role="gridcell"]'));
    if (cells.length < 2) return;

    const nameText = cells[nameCol]?.textContent?.trim() || '';
    const refNo = cells[refCol]?.textContent?.trim() || '';
    const nationality = cells[natCol]?.textContent?.trim() || 'Qatar';

    // Validation
    const normalizedName = nameText.toUpperCase();
    if (!nameText || nameText.length < 3) return;

    // Ignore header duplicates
    if (normalizedName.includes('NAME') || normalizedName.includes('الاسم') || normalizedName.includes('IDENTITY')) return;

    const nameParts = nameText.split(/\s+/);

    entries.push({
      dataId: `QA-NCTC-${refNo.replace(/[^a-zA-Z0-9]/g, '') || Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      source: 'Qatar NCTC',
      firstName: nameParts[0] || 'UNKNOWN',
      lastName: nameParts.slice(1).join(' ') || '',
      unListType: 'National Unified List',
      referenceNumber: refNo || 'QA-REF-NCTC',
      listedOn: new Date().toISOString().split('T')[0],
      comments: `Portal Scrape Node: High-fidelity automated extraction from Unified List.`,
      nationality: nationality,
      aliases: [],
      type: EntityType.INDIVIDUAL,
      fetchDate: new Date().toISOString()
    });
  });

  return entries;
};

