/**
 * Advanced parser for Qatar NCTC Portal HTML table structure.
 * Scans for common IBM WebSphere portal table patterns and dynamic grid layouts.
 */
export const parseQatarNCTCHTML = (htmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const doc = parser.parseFromString(htmlString, "text/html");
  const entries: SanctionEntry[] = [];

  // Portals like MOI/NCTC often use nested tables or complex grid structures
  const rows = Array.from(doc.querySelectorAll('tr, .v-grid-row, .wpthemeTable tr, [role="row"]'));

  if (rows.length === 0) {
    // Fallback: If no rows found, the portal might be using a div-based grid
    const gridItems = Array.from(doc.querySelectorAll('.v-grid-cell-content, .grid-item'));
    if (gridItems.length > 0) {
       console.log("[NCTC Scraper] Detected div-based grid layout.");
    }
  }

  let nameCol = -1;
  let refCol = -1;
  let natCol = -1;

  // Scrutinize the first few rows to identify column meanings (Bilingual support)
  for (let i = 0; i < Math.min(rows.length, 40); i++) {
    const cells = Array.from(rows[i].querySelectorAll('td, th, div, span')).slice(0, 10);
    const rowText = rows[i].textContent?.toUpperCase() || '';

    const isHeader = (
      rowText.includes('NAME') || rowText.includes('الاسم') || 
      rowText.includes('ID') || rowText.includes('NO.') || 
      rowText.includes('الرقم') || rowText.includes('IDENTITY')
    );

    if (isHeader) {
      cells.forEach((cell, idx) => {
        const cText = cell.textContent?.trim().toUpperCase() || '';
        if (cText.includes('NAME') || cText.includes('الاسم') || cText.includes('IDENTITY')) nameCol = idx;
        if (cText.includes('REF') || cText.includes('NO') || cText.includes('الرقم') || cText.includes('REFERENCE')) refCol = idx;
        if (cText.includes('NAT') || cText.includes('الجنسية') || cText.includes('CITIZENSHIP')) natCol = idx;
      });
      if (nameCol !== -1) break;
    }
  }

  // Hardcoded mapping fallbacks for the Unified List if dynamic detection fails
  if (nameCol === -1) nameCol = 1;
  if (refCol === -1) refCol = 0;
  if (natCol === -1) natCol = 2;

  rows.forEach((row) => {
    const cells = Array.from(row.querySelectorAll('td, .v-grid-cell, [role="gridcell"]'));
    if (cells.length < 2) return;

    const nameText = cells[nameCol]?.textContent?.trim() || '';
    const refNo = cells[refCol]?.textContent?.trim() || '';
    const nationality = cells[natCol]?.textContent?.trim() || 'Qatar';

    // Skip garbage/header rows
    const norm = nameText.toUpperCase();
    if (!nameText || nameText.length < 3) return;
    if (norm.includes('NAME') || norm.includes('الاسم') || norm.includes('IDENTITY')) return;

    const nameParts = nameText.split(/\s+/);

    entries.push({
      dataId: `QA-NCTC-${refNo.replace(/[^a-zA-Z0-9]/g, '') || Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      source: 'Qatar NCTC',
      firstName: nameParts[0] || 'UNKNOWN',
      lastName: nameParts.slice(1).join(' ') || '',
      unListType: 'National Unified List',
      referenceNumber: refNo || 'NCTC-REF',
      listedOn: new Date().toISOString().split('T')[0],
      comments: `Automated ingest from NCTC Unified Sanctions Portal.`,
      nationality: nationality,
      aliases: [],
      type: EntityType.INDIVIDUAL,
      fetchDate: new Date().toISOString()
    });
  });

  return entries;
};

/**
 * Handles the transport layer with multi-proxy fallback logic
 */
const fetchRawContent = async (url: string): Promise<string> => {
  try {
    // Attempt Primary Proxy (AllOrigins)
    const resp = await fetch(`${PROXY_PRIMARY}${encodeURIComponent(url)}`);
    if (!resp.ok) throw new Error("Primary proxy unreachable");
    const json = await resp.json();
    if (json.contents) return json.contents;
    throw new Error("Primary proxy returned empty contents");
  } catch (err) {
    console.warn("[Ingestion] Primary proxy failed, attempting secondary transport...", err);

    // Attempt Secondary Proxy (CodeTabs)
    try {
      const resp = await fetch(`${PROXY_SECONDARY}${encodeURIComponent(url)}`);
      if (!resp.ok) throw new Error("Secondary proxy unreachable");
      return await resp.text();
    } catch (err2) {
      throw new Error(`Critical Transport Fault: All authoritative proxies are currently being blocked by the portal at moi.gov.qa. Please verify the session URL is still valid.`);
    }
  }
};

export const fetchAndNormalize = async (url: string, name: string): Promise<SanctionEntry[]> => {
  const content = await fetchRawContent(url);
  const format = detectFormat(content, url);

  if (name.includes('UN Security Council') || format === 'XML') {
    return parseUNSanctionsXML(content);
  }

  // Specific catch for Qatar Portal regardless of detected format (often returned as HTML)
  if (name.includes('Qatar') || url.includes('moi.gov.qa') || content.includes('NCTC')) {
    const qatarEntries = parseQatarNCTCHTML(content);
    if (qatarEntries.length > 0) return qatarEntries;
    throw new Error(`Handshake Successful, but no entity records were found in the NCTC portal response. The session ID may have expired.`);
  }

  if (name.includes('OpenSanctions') || format === 'JSON') {
    const parsed = typeof content === 'string' ? JSON.parse(content) : content;
    return parseOpenSanctionsJSON(parsed);
  }

  return [];
};

export const parseUNSanctionsXML = (xmlString: string): SanctionEntry[] => {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlString, "text/xml");
  const entries: SanctionEntry[] = [];

  const getNodeVal = (parent: Element, tagName: string): string => {
    const node = parent.getElementsByTagName(tagName)[0];
    return node ? node.textContent?.trim() || '' : '';
  };

  const parseNode = (node: Element, isInd: boolean): SanctionEntry => {
    const natNode = node.getElementsByTagName("NATIONALITY")[0];
    const nationality = natNode ? getNodeVal(natNode, "VALUE") : '';
    const dobNode = node.getElementsByTagName("INDIVIDUAL_DATE_OF_BIRTH")[0];
    const dob = dobNode ? getNodeVal(dobNode, "DATE") : '';

    return {
      dataId: `UN-${getNodeVal(node, "DATAID")}`,
      source: 'UN Consolidated',
      firstName: getNodeVal(node, "FIRST_NAME"),
      secondName: getNodeVal(node, "SECOND_NAME"),
      thirdName: getNodeVal(node, "THIRD_NAME"),
      lastName: getNodeVal(node, "LAST_NAME"),
      unListType: getNodeVal(node, "UN_LIST_TYPE"),
      referenceNumber: getNodeVal(node, "REFERENCE_NUMBER"),
      listedOn: getNodeVal(node, "LISTED_ON"),
      comments: getNodeVal(node, "COMMENTS1"),
      nationality: nationality,
      dateOfBirth: isInd ? dob : '',
      aliases: Array.from(node.getElementsByTagName(isInd ? "INDIVIDUAL_ALIAS" : "ENTITY_ALIAS"))
        .map(a => getNodeVal(a, "ALIAS_NAME"))
        .filter(Boolean),
      type: isInd ? EntityType.INDIVIDUAL : EntityType.CORPORATE,
      fetchDate: new Date().toISOString()
    };
  };

  const individuals = xmlDoc.getElementsByTagName("INDIVIDUAL");
  for (let i = 0; i < individuals.length; i++) {
    const entry = parseNode(individuals[i], true);
    if (entry.firstName || entry.lastName) entries.push(entry);
  }

  const entities = xmlDoc.getElementsByTagName("ENTITY");
  for (let i = 0; i < entities.length; i++) {
    const entry = parseNode(entities[i], false);
    if (entry.firstName || entry.lastName) entries.push(entry);
  }

  return entries;
};

export const parseOpenSanctionsJSON = (json: any): SanctionEntry[] => {
  const results: any[] = Array.isArray(json) ? json : (json.entities || json.data || []);

  return results.map((item: any) => {
    const nameParts = (item.caption || item.name || '').split(' ');
    const firstName = nameParts[0] || 'UNKNOWN';
    const lastName = nameParts.slice(1).join(' ') || '';

    return {
      dataId: item.id || `OS-${Math.random().toString(36).substr(2, 9)}`,
      source: 'OpenSanctions',
      firstName,
      lastName,
      unListType: item.schema || 'Sanctioned Entity',
      referenceNumber: item.id,
      listedOn: item.first_seen || new Date().toISOString().split('T')[0],
      comments: item.notes || item.summary || '',
      nationality: Array.isArray(item.properties?.nationality) ? item.properties.nationality[0] : (item.properties?.jurisdiction?.[0] || ''),
      aliases: item.properties?.alias || [],
      type: item.schema === 'Person' ? EntityType.INDIVIDUAL : EntityType.CORPORATE,
      fetchDate: new Date().toISOString()
    };
  });
};

export const detectFormat = (content: string, fileName: string): 'XML' | 'CSV' | 'EXCEL' | 'JSON' | 'HTML' | 'UNKNOWN' => {
  const ext = fileName.split('.').pop()?.toUpperCase();
  const trimmed = content.trim();

  if (ext === 'XLSX' || ext === 'XLS') return 'EXCEL';
  if (ext === 'CSV') return 'CSV';
  if (ext === 'JSON' || trimmed.startsWith('[') || trimmed.startsWith('{')) return 'JSON';
  if (ext === 'XML' || trimmed.startsWith('<?xml') || trimmed.startsWith('<')) {
    if (trimmed.toLowerCase().includes('<html')) return 'HTML';
    return 'XML';
  }
  if (trimmed.toLowerCase().includes('<!doctype html') || trimmed.toLowerCase().includes('<html')) return 'HTML';

  return 'UNKNOWN';
};

export const parseExcelToSanctions = (buffer: ArrayBuffer, sourceName: string): any[] => {
  const workbook = XLSX.read(buffer, { type: 'array' });
  const sheetName = workbook.SheetNames[0];
  const worksheet = workbook.Sheets[sheetName];
  return XLSX.utils.sheet_to_json(worksheet);
};

export const mapFieldsToSanction = (row: any, mapping: Record<string, string>, source: string): SanctionEntry => {
  const getVal = (key: string) => {
    const mappedKey = mapping[key];
    return mappedKey ? String(row[mappedKey] || '') : '';
  };

  const typeStr = getVal('type').toUpperCase();
  const entityType = (typeStr.includes('CORP') || typeStr.includes('ENTITY') || typeStr.includes('CORPORATE')) 
    ? EntityType.CORPORATE 
    : EntityType.INDIVIDUAL;

  return {
    dataId: getVal('dataId') || `MANUAL-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
    source: source,
    firstName: getVal('firstName') || 'UNKNOWN',
    lastName: getVal('lastName'),
    unListType: 'Manual Import',
    referenceNumber: getVal('referenceNumber'),
    listedOn: new Date().toISOString().split('T')[0],
    comments: getVal('comments'),
    nationality: getVal('nationality'),
    aliases: [],
    type: entityType,
    fetchDate: new Date().toISOString()
  };
};

export const parseCSVToSanctions = (csv: string, sourceName: string): any[] => {
  const rows: any[] = [];
  const lines = csv.split(/\r?\n/);
  if (lines.length < 1) return [];

  const splitLine = (line: string) => {
    const result = [];
    let startValueIndex = 0;
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      if (line[i] === '"') inQuotes = !inQuotes;
      if (line[i] === ',' && !inQuotes) {
        result.push(line.substring(startValueIndex, i).replace(/^"|"$/g, '').trim());
        startValueIndex = i + 1;
      }
    }
    result.push(line.substring(startValueIndex).replace(/^"|"$/g, '').trim());
    return result;
  };

  const headers = splitLine(lines[0]).filter(Boolean);
  if (headers.length === 0) return [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const values = splitLine(line);
    const row: any = {};
    headers.forEach((header, index) => {
      row[header] = values[index] || '';
    });
    rows.push(row);
  }
  return rows;
};

