  { key: 'firstName', label: 'First Name / Primary Identity' },
  { key: 'lastName', label: 'Last Name / Surname' },
  { key: 'dataId', label: 'Reference ID / Data ID' },
  { key: 'nationality', label: 'Nationality / Jurisdiction' },
  { key: 'referenceNumber', label: 'Official Ref Number' },
  { key: 'comments', label: 'Comments / Details' },
  { key: 'type', label: 'Entity Type (Individual/Corporate)' }
];

const SanctionsRegistry: React.FC<SanctionsRegistryProps> = ({ onSyncComplete, isCloudConnected, isGlobalSyncing, currentUser }) => {
  const [activeTab, setActiveTab] = useState<'hub' | 'audit'>('hub');
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalMatches, setTotalMatches] = useState(0);
  const [totalInDb, setTotalInDb] = useState(0);
  const [status, setStatus] = useState<'IDLE' | 'WORKING' | 'SUCCESS' | 'ERROR' | 'MAPPING' | 'PURGING'>('IDLE');
  const [uploadProgress, setUploadProgress] = useState(0);
  const [ingestionCount, setIngestionCount] = useState(0);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [ingestionHistory, setIngestionHistory] = useState<IngestionLog[]>([]);

  const [pendingData, setPendingData] = useState<any[]>([]);
  const [pendingSource, setPendingSource] = useState('');
  const [detectedHeaders, setDetectedHeaders] = useState<string[]>([]);
  const [fieldMapping, setFieldMapping] = useState<Record<string, string>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);

  const performSearch = useCallback(async (page: number, term: string) => {
    setIsSearching(true);
    try {
      const from = (page - 1) * ITEMS_PER_PAGE;
      const to = from + ITEMS_PER_PAGE - 1;
      const response = await searchSanctionsAuthoritative(term, from, to);
      setSanctions(response.data);
      setTotalMatches(response.count);
      if (!term) setTotalInDb(response.count);
    } catch (e) {
      console.error(e);
    } finally {
      setIsSearching(false);
    }
  }, []);

  useEffect(() => {
    const t = setTimeout(() => performSearch(1, searchTerm), 300);
    return () => clearTimeout(t);
  }, [searchTerm, performSearch]);

  useEffect(() => {
    performSearch(currentPage, searchTerm);
  }, [currentPage, performSearch]);

  const refreshLogs = useCallback(async () => {
    const logs = await fetchIngestionLogs();
    setIngestionHistory(logs);
    const count = await fetchSanctionsTotalCount();
    setTotalInDb(count);
  }, []);

  useEffect(() => { refreshLogs(); }, [refreshLogs]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setStatus('WORKING');
    setErrorMessage(null);
    setUploadProgress(1);

    const fileName = file.name;
    const reader = new FileReader();

    reader.onload = async (event) => {
      try {
        const content = event.target?.result;
        const format = detectFormat(typeof content === 'string' ? content : '', fileName);

        if (format === 'UNKNOWN') throw new Error("Unsupported format. Use XML, CSV, Excel, or JSON.");

        let rawData: any[] = [];
        const batchTimestamp = new Date().toISOString();

        if (format === 'XML') {
          const entries = parseUNSanctionsXML(content as string, batchTimestamp);
          await commitSanctions(entries, fileName, 'Manual', batchTimestamp);
          return;
        } else if (format === 'JSON') {
          const parsed = JSON.parse(content as string);
          rawData = Array.isArray(parsed) ? parsed : (parsed.entities || parsed.data || [parsed]);
        } else if (format === 'CSV') {
          rawData = parseCSVToSanctions(content as string, fileName);
        } else if (format === 'EXCEL') {
          rawData = parseExcelToSanctions(content as ArrayBuffer, fileName);
        }

        if (rawData.length === 0) throw new Error("File contains no identifiable records.");

        setPendingData(rawData);
        setPendingSource(fileName);
        const headers = Object.keys(rawData[0]);
        setDetectedHeaders(headers);

        const initialMapping: Record<string, string> = {};
        REQUIRED_SYSTEM_FIELDS.forEach(sf => {
          const match = headers.find(h => 
            h.toLowerCase().includes(sf.key.toLowerCase()) || 
            sf.label.toLowerCase().includes(h.toLowerCase())
          );
          if (match) initialMapping[sf.key] = match;
        });

        setFieldMapping(initialMapping);
        setStatus('MAPPING');
      } catch (err: any) {
        setErrorMessage(err.message);
        setStatus('ERROR');
      }
    };

    if (fileName.match(/\.(xlsx|xls)$/i)) {
      reader.readAsArrayBuffer(file);
    } else {
      reader.readAsText(file);
    }
  };

  const executeMappedImport = async () => {
    if (pendingData.length === 0) return;
    setStatus('WORKING');

    try {
      const batchTimestamp = new Date().toISOString();
      const mappedEntries = pendingData.map(row => {
        const entry = mapFieldsToSanction(row, fieldMapping, pendingSource);
        return { ...entry, fetchDate: batchTimestamp };
      });
      await commitSanctions(mappedEntries, pendingSource, 'Manual', batchTimestamp);
    } catch (err: any) {
      setErrorMessage(err.message);
      setStatus('ERROR');
    }
  };

  const commitSanctions = async (entries: SanctionEntry[], source: string, method: 'Automated' | 'Manual', batchTimestamp: string) => {
    const userHandle = currentUser?.email || currentUser?.id || 'System';
    setIngestionCount(entries.length);
    try {
      await setGlobalSyncLock(true, `${method} Upload: ${source}`, 0, source);

      // Phase 1: Ingest new records
      await upsertCloudSanctions(entries, p => {
        setUploadProgress(p);
        if (p % 10 === 0) setGlobalSyncLock(true, `${method} Upload: ${source}`, p, source);
      });

      // Phase 2: State Purge (Delete the old)
      setStatus('PURGING');
      await deleteStaleSanctions(source, batchTimestamp);

      await setGlobalSyncLock(false, new Date().toLocaleString());

      await logIngestionEvent({ 
        timestamp: new Date().toISOString(), 
        source: source, 
        method: method, 
        status: 'Success', 
        recordsProcessed: entries.length, 
        triggeredBy: userHandle
      });

      await logAuditEvent(
        method === 'Automated' ? 'REGISTRY_SYNC_FEED' : 'REGISTRY_MANUAL_IMPORT',
        `Registry Refreshed: New state for "${source}" synchronized. Stale identities purged.`,
        userHandle
      );

      setStatus('SUCCESS');
      onSyncComplete();
      refreshLogs();

      setTimeout(() => {
        if (fileInputRef.current) fileInputRef.current.value = '';
        setStatus('IDLE');
        setUploadProgress(0);
      }, 5000);
    } catch (err: any) {
      await setGlobalSyncLock(false, "Sync Failed");
      setErrorMessage(err.message);
      setStatus('ERROR');
      await logAuditEvent('INGESTION_FAILURE', `Registry update failed for ${source}: ${err.message}`, userHandle);
    }
  };

  const handleFetch = async (url: string, name: string) => {
    setStatus('WORKING');
    setUploadProgress(5); 
    setErrorMessage(null);
    try {
      const batchTimestamp = new Date().toISOString();
      const data = await fetchAndNormalize(url, name, batchTimestamp);
      if (!data || data.length === 0) {
        throw new Error(`Feed ${name} returned 0 records. Process aborted.`);
      }
      await commitSanctions(data, name, 'Automated', batchTimestamp);
    } catch (err: any) {
      setErrorMessage(err.message || "Handshake failure.");
      setStatus('ERROR');
    }
  };

  return (
    <div className="space-y-8 pb-20">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm gap-6">
         <div className="flex items-center gap-4">
            <div className="bg-emerald-950 p-4 rounded-2xl text-emerald-400 shadow-lg"><Cpu size={28}/></div>
            <div>
               <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Sanctions Master Hub</h2>
               <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Atomic State Synchronization Engine</p>
            </div>
         </div>
         <div className="flex bg-slate-50 p-1 rounded-2xl border w-full sm:w-auto">
            <button onClick={() => setActiveTab('hub')} className={`flex-1 sm:flex-none px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'hub' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>Import Hub</button>
            <button onClick={() => setActiveTab('audit')} className={`flex-1 sm:flex-none px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'audit' ? 'bg-white text-emerald-800 shadow-sm' : 'text-slate-400'}`}>Ingestion Audit</button>
         </div>
      </div>

      {activeTab === 'hub' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-10 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
             <div className="flex items-center gap-4 border-b border-gray-50 pb-6">
                <div className="p-3 bg-blue-50 text-blue-600 rounded-xl"><Globe size={20}/></div>
                <h3 className="text-sm font-black uppercase text-slate-900 tracking-wider">Automated State Feeds</h3>
             </div>
             <div className="grid grid-cols-1 gap-4">
               {[
                 { name: 'UN Security Council (Consolidated)', url: OFFICIAL_UN_XML_URL, info: 'Global Authoritative Baseline' },
                 { name: 'Qatar NCTC (Unified List Portal)', url: QATAR_NCTC_PORTAL_URL, info: 'National Counter-Terrorism Authority' },
                 { name: 'OpenSanctions (Composite)', url: OPENSANCTIONS_URL, info: 'International Multi-Source Dataset' }
               ].map(s => (
                 <button 
                   key={s.name} 
                   onClick={() => handleFetch(s.url, s.name)} 
                   disabled={status === 'WORKING' || status === 'PURGING'} 
                   className="group flex items-center justify-between p-6 bg-slate-50 border border-transparent hover:border-blue-200 hover:bg-white rounded-2xl transition-all disabled:opacity-30"
                 >
                   <div className="text-left">
                      <p className="text-[11px] font-black text-slate-900 uppercase">{s.name}</p>
                      <p className="text-[8px] text-gray-400 font-bold uppercase mt-1 tracking-widest">{s.info}</p>
                   </div>
                   <CloudDownload size={20} className="text-blue-500 group-hover:scale-110 transition-transform" />
                 </button>
               ))}
             </div>
          </div>

          <div className="bg-emerald-950 p-10 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
                <Upload size={140} />
             </div>

             <div className="relative z-10 space-y-8">
                <div className="flex items-center gap-4 border-b border-white/10 pb-6">
                   <div className="p-3 bg-white/10 text-emerald-400 rounded-xl"><Layers size={20}/></div>
                   <div>
                      <h3 className="text-sm font-black uppercase tracking-wider">Bundle Deployment</h3>
                      <p className="text-[9px] text-emerald-400/60 font-black uppercase tracking-widest mt-1">Atomic Ingest & Purge</p>
                   </div>
                </div>

                <div className="space-y-4">
                   <input 
                      type="file" 
                      ref={fileInputRef} 
                      onChange={handleFileUpload} 
                      className="hidden" 
                      accept=".xml,.csv,.xlsx,.xls,.json"
                   />
                   <button 
                     onClick={() => fileInputRef.current?.click()} 
                     disabled={status === 'WORKING' || status === 'PURGING'}
                     className="w-full py-6 bg-white text-emerald-950 rounded-2xl font-black text-[11px] uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-50 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                   >
                      <Upload size={20} /> Deploy Data Bundle
                   </button>
                </div>

                {(status === 'WORKING' || status === 'PURGING') && (
                  <div className="space-y-3 animate-in fade-in slide-in-from-bottom-2">
                     <div className="flex justify-between items-center text-[9px] font-black uppercase tracking-widest">
                        <span className="text-emerald-400 flex items-center gap-2">
                           <Loader2 size={12} className="animate-spin" /> 
                           {status === 'PURGING' ? 'Purging Stale Records...' : (uploadProgress <= 5 ? 'Initiating Transport...' : 'Ingesting Entities...')}
                        </span>
                        <span>{uploadProgress}%</span>
                     </div>
                     <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden">
                        <div className={`h-full bg-emerald-400 transition-all duration-300 ${status === 'PURGING' ? 'animate-pulse' : ''}`} style={{width: `${uploadProgress}%`}}/>
                     </div>
                  </div>
                )}

                {status === 'SUCCESS' && (
                  <div className="p-4 bg-emerald-500/20 border border-emerald-500/30 rounded-2xl flex items-center gap-3 text-emerald-400 animate-in zoom-in-95">
                     <CheckCircle2 size={24} />
                     <div className="min-w-0">
                        <p className="text-[10px] font-black uppercase tracking-widest">State Sync Finalized</p>
                        <p className="text-[8px] font-bold uppercase opacity-60 mt-0.5">{ingestionCount.toLocaleString()} entities maintained. Source is clean.</p>
                     </div>
                  </div>
                )}
             </div>
          </div>
        </div>
      )}

      {status === 'MAPPING' && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[200] flex items-center justify-center p-6">
           <div className="bg-white rounded-[3rem] w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in-95">
              <div className="bg-emerald-950 p-8 text-white flex justify-between items-center shrink-0">
                 <div className="flex items-center gap-4">
                    <div className="p-3 bg-white/10 rounded-xl text-emerald-400"><Settings2 size={24}/></div>
                    <div>
                       <h3 className="text-xl font-black uppercase">Alignment Protocol</h3>
                       <p className="text-[9px] text-emerald-400/60 font-black uppercase tracking-widest mt-1">File: {pendingSource}</p>
                    </div>
                 </div>
                 <button onClick={() => setStatus('IDLE')} className="p-3 bg-white/10 rounded-full hover:bg-white/20 transition-all"><X size={20}/></button>
              </div>

              <div className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar bg-gray-50/30">
                 <div className="bg-blue-50 border border-blue-100 p-6 rounded-[2rem] flex gap-4 text-blue-800">
                    <Info size={24} className="shrink-0" />
                    <div className="space-y-1">
                       <p className="text-[10px] font-black uppercase tracking-widest">State Sync Overwrite</p>
                       <p className="text-xs font-bold leading-relaxed">Proceeding will replace all current data for <span className="font-black">"{pendingSource}"</span> with this new state.</p>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 gap-6">
                    {REQUIRED_SYSTEM_FIELDS.map(sf => (
                       <div key={sf.key} className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-6 bg-white border border-gray-100 rounded-2xl shadow-sm hover:border-emerald-200 transition-all">
                          <div className="space-y-1">
                             <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{sf.label}</p>
                             <p className="text-[8px] font-black text-emerald-600 uppercase">Field Key: {sf.key}</p>
                          </div>
                          <div className="flex items-center gap-4">
                             <ArrowRight className="text-gray-200 hidden sm:block" size={18} />
                             <select 
                               className="bg-gray-50 border-2 border-transparent focus:border-emerald-800 focus:bg-white rounded-xl px-4 py-3 text-xs font-black uppercase outline-none min-w-[220px]"
                               value={fieldMapping[sf.key] || ''}
                               onChange={(e) => setFieldMapping({...fieldMapping, [sf.key]: e.target.value})}
                             >
                                <option value="">-- Ignore Field --</option>
                                {detectedHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                             </select>
                          </div>
                       </div>
                    ))}
                 </div>
              </div>

              <div className="p-8 border-t bg-white flex justify-end items-center gap-4 shrink-0">
                 <button onClick={() => setStatus('IDLE')} className="px-8 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">Cancel</button>
                 <button 
                   onClick={executeMappedImport}
                   className="px-12 py-4 bg-emerald-800 text-white rounded-2xl font-black text-[11px] uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-900 transition-all flex items-center gap-3"
                 >
                    <ShieldCheck size={18} /> Deploy Bundle ({pendingData.length})
                 </button>
              </div>
           </div>
        </div>
      )}

      {errorMessage && (
        <div className="p-6 bg-red-50 border border-red-100 rounded-3xl text-red-600 flex items-start gap-4 animate-in slide-in-from-top-2">
           <AlertTriangle size={20} className="shrink-0 mt-0.5" />
           <div className="space-y-1">
              <p className="text-[10px] font-black uppercase tracking-widest">Sync Fault</p>
              <p className="text-xs font-bold leading-relaxed">{errorMessage}</p>
           </div>
        </div>
      )}

      <div className="space-y-6">
         <div className="flex flex-col sm:flex-row gap-4 items-stretch sm:items-center bg-white p-4 sm:p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
            <div className="relative flex-1">
               <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-300" size={20}/>
               <input 
                  type="text" 
                  placeholder="Interrogate Master Registry..." 
                  className="w-full pl-16 pr-6 py-5 bg-gray-50/50 rounded-2xl border-2 border-transparent focus:border-emerald-800 focus:bg-white outline-none text-sm font-black uppercase transition-all" 
                  value={searchTerm} 
                  onChange={e => { setSearchTerm(e.target.value); setCurrentPage(1); }} 
               />
               {isSearching && <Loader2 className="absolute right-6 top-1/2 -translate-y-1/2 animate-spin text-emerald-800" size={18}/>}
            </div>
            <div className="px-8 py-5 bg-emerald-50 border border-emerald-100 rounded-2xl flex flex-col items-center justify-center min-w-[200px]">
               <div className="flex items-center gap-2 mb-1">
                  <Database size={12} className="text-emerald-700" />
                  <span className="text-[8px] font-black text-emerald-800 uppercase tracking-widest">Master Identity Tally</span>
               </div>
               <span className="text-base font-black text-emerald-950">{totalInDb.toLocaleString()}</span>
            </div>
         </div>

         <div className="bg-white rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden">
            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left min-w-[900px]">
                 <thead className="bg-gray-50 border-b">
                    <tr className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                       <th className="px-10 py-6">Identity</th>
                       <th className="px-10 py-6">Reference</th>
                       <th className="px-10 py-6">Jurisdiction</th>
                       <th className="px-10 py-6 text-right">Source Protocol</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-50">
                    {sanctions.length > 0 ? (
                       sanctions.map(s => (
                          <tr key={s.dataId} className="hover:bg-emerald-50/30 transition-colors group">
                             <td className="px-10 py-5">
                                <div className="text-sm font-black text-slate-900 uppercase group-hover:text-emerald-900 transition-colors">
                                   {[s.firstName, s.lastName].filter(Boolean).join(' ')}
                                </div>
                                <div className="text-[9px] text-gray-400 font-bold uppercase mt-1 tracking-tighter">ID: {s.dataId}</div>
                             </td>
                             <td className="px-10 py-5">
                                <div className="flex items-center gap-2">
                                   <FileCode size={14} className="text-gray-300" />
                                   <span className="text-[10px] font-black text-slate-500 uppercase">{s.referenceNumber || 'INTERNAL-REF'}</span>
                                </div>
                             </td>
                             <td className="px-10 py-5">
                                <div className="flex items-center gap-2">
                                   <MapPin size={14} className="text-gray-300" />
                                   <span className="text-[10px] font-black text-slate-500 uppercase">{s.nationality || 'UNKNOWN'}</span>
                                </div>
                             </td>
                             <td className="px-10 py-5 text-right">
                                <span className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase border ${
                                  s.source.includes('UN') ? 'bg-blue-50 text-blue-700 border-blue-100' :
                                  s.source.includes('Qatar') ? 'bg-amber-50 text-amber-700 border-amber-100' :
                                  'bg-slate-50 text-slate-500 border-slate-200'
                                }`}>
                                   {s.source}
                                </span>
                             </td>
                          </tr>
                       ))
                    ) : (
                       <tr>
                          <td colSpan={4} className="py-24 text-center">
                             {isSearching ? (
                               <div className="flex flex-col items-center gap-4">
                                  <Loader2 className="animate-spin text-emerald-800" size={40} />
                                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Handshake Active...</p>
                               </div>
                             ) : (
                               <div className="flex flex-col items-center gap-4 opacity-30">
                                  <Search size={48} className="text-gray-300" />
                                  <p className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em]">Registry Empty</p>
                               </div>
                             )}
                          </td>
                       </tr>
                    )}
                 </tbody>
              </table>
            </div>

            {totalMatches > ITEMS_PER_PAGE && (
              <div className="p-8 border-t border-gray-100 bg-gray-50/30 flex justify-between items-center">
                 <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                    Showing <span className="text-emerald-900">{sanctions.length}</span> of {totalMatches.toLocaleString()}
                 </div>
                 <div className="flex items-center gap-2">
                    <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 shadow-sm transition-all disabled:opacity-30"><ChevronLeft size={18} /></button>
                    <div className="px-6 py-3 bg-white border border-gray-200 rounded-xl text-[10px] font-black text-emerald-950 uppercase tracking-widest shadow-sm">Page {currentPage} of {Math.ceil(totalMatches / ITEMS_PER_PAGE)}</div>
                    <button onClick={() => setCurrentPage(p => Math.min(Math.ceil(totalMatches / ITEMS_PER_PAGE), p + 1))} disabled={currentPage >= Math.ceil(totalMatches / ITEMS_PER_PAGE)} className="p-3 bg-white border border-gray-200 rounded-xl hover:bg-emerald-50 shadow-sm transition-all disabled:opacity-30"><ChevronRight size={18} /></button>
                 </div>
              </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default SanctionsRegistry;

import { 
  initSupabase, 
  fetchCloudClients, 
  upsertCloudClient, 
  deleteCloudClient, 
  subscribeToClients, 
  unsubscribeFromClients, 
  checkConnection, 
  upsertCloudUser,
  fetchGlobalSyncStatus,
  subscribeToGlobalSync,
  fetchSanctionsTotalCount,
  upsertCloudSanctions,
  deleteStaleSanctions,
  fetchClientsTotalCount,
  screenEntityAgainstDb,
  validateRegistrySchemaV431,
  logAuditEvent,
  fetchSystemLogs,
  fetchGlobalRiskCounts,
  setGlobalSyncLock,
  logIngestionEvent
} from './services/cloudDb';
import { OFFICIAL_UN_XML_URL, QATAR_NCTC_PORTAL_URL, fetchAndNormalize } from './services/unSanctionsService';
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsRegistry from './components/SanctionsRegistry';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Client, AppSettings, UserProfile, SystemEnvironment, ScreeningProgress, SystemLog, KYCStatus, RiskLevel } from './types';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: true,
  syncIntervalMinutes: 60,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: '',
  environment: SystemEnvironment.PRODUCTION
};

const CLIENTS_PER_PAGE = 15;
const SYNC_HOUR = 8;
const SYNC_MINUTE = 0;

const App: React.FC = () => {
  const [isBooting, setIsBooting] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('unsg_session');
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [clientsCount, setClientsCount] = useState(0);
  const [systemLogs, setSystemLogs] = useState<SystemLog[]>([]);
  const [currentClientsPage, setCurrentClientsPage] = useState(1);
  const [isRefreshingClients, setIsRefreshingClients] = useState(false);

  const [riskSummary, setRiskSummary] = useState<Record<RiskLevel, number>>({
    [RiskLevel.HIGH]: 0,
    [RiskLevel.MEDIUM]: 0,
    [RiskLevel.LOW]: 0,
    [RiskLevel.NONE]: 0
  });

  const currentPageRef = useRef(1);

  const [screeningProgress, setScreeningProgress] = useState<ScreeningProgress>({
    totalRecords: 0,
    screenedRecords: 0,
    pendingRecords: 0,
    status: 'Not Started',
    currentBatch: 0
  });

  const [isGlobalSyncing, setIsGlobalSyncing] = useState(false);
  const [sanctionsCount, setSanctionsCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'ERROR' | 'SAFE_MODE'>('CONNECTING');
  const [schemaDiscrepancies, setSchemaDiscrepancies] = useState<string[]>([]);

  const [registryStats, setRegistryStats] = useState(() => {
    try {
      const saved = localStorage.getItem('unsg_registry_stats');
      return saved ? JSON.parse(saved) : { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never', syncProgress: 0, currentSyncSource: '' };
    } catch (e) { return { lastFetch: 'Never', lastTest: 'Never', lastSourceUpdate: 'Never', syncProgress: 0, currentSyncSource: '' }; }
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : { ...DEFAULT_SETTINGS };
  });

  const subscriptionRef = useRef<any>(null);
  const syncChannelRef = useRef<any>(null);

  const updateLocalRefreshTimestamp = useCallback(() => {
    const now = new Date().toLocaleString();
    setRegistryStats(prev => {
      const next = { ...prev, lastFetch: now };
      localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
      return next;
    });
  }, []);

  const loadLogs = useCallback(async () => {
    const logs = await fetchSystemLogs();
    setSystemLogs(logs);
  }, []);

  const handleGlobalMetadataUpdate = useCallback((meta: any) => {
    if (!meta) return;
    setIsGlobalSyncing(!!meta.is_syncing);
    setRegistryStats(prev => {
      const next = { 
        ...prev, 
        lastSourceUpdate: (meta.last_sync && meta.last_sync !== 'In Progress...' && meta.last_sync !== 'Uninitialized') ? meta.last_sync : prev.lastSourceUpdate,
        syncProgress: meta.progress || 0,
        currentSyncSource: meta.current_source || ''
      };
      localStorage.setItem('unsg_registry_stats', JSON.stringify(next));
      return next;
    });

    if (meta.last_sync && meta.last_sync !== 'In Progress...' && !meta.is_syncing) {
      loadSanctionsCache();
      loadLogs();
    }
  }, [loadLogs]);

  const loadSanctionsCache = useCallback(async () => {
    try {
      const count = await fetchSanctionsTotalCount();
      setSanctionsCount(count); 
      updateLocalRefreshTimestamp();
    } catch (e) { console.error("[App] Cache Refresh Failure:", e); }
  }, [updateLocalRefreshTimestamp]);

  const refreshClients = useCallback(async (page: number = 1) => {
    setIsRefreshingClients(true);
    currentPageRef.current = page;
    try {
      const from = (page - 1) * CLIENTS_PER_PAGE;
      const to = from + CLIENTS_PER_PAGE - 1;
      const [cloudClients, count, globalRisks] = await Promise.all([
        fetchCloudClients(from, to),
        fetchClientsTotalCount(),
        fetchGlobalRiskCounts()
      ]);
      if (cloudClients) setClients(cloudClients);
      setClientsCount(count);
      setRiskSummary(globalRisks);
      setCurrentClientsPage(page);
      updateLocalRefreshTimestamp();
    } catch (e) { 
      setConnectionStatus('SAFE_MODE');
    } finally { setIsRefreshingClients(false); }
  }, [updateLocalRefreshTimestamp]);

  // --- SCHEDULED 08:00 AM BACKGROUND UPDATE ENGINE ---
  useEffect(() => {
    if (!settings.autoSync || connectionStatus !== 'CONNECTED') return;

    const runAutomatedSync = async () => {
      if (isGlobalSyncing) return;

      const now = new Date();
      const currentDay = now.toISOString().split('T')[0];
      const lastSyncDay = localStorage.getItem('unsg_last_auto_sync_day');

      // Condition: Current time >= 08:00 and we haven't synced yet today
      const isSyncWindow = now.getHours() >= SYNC_HOUR && (now.getHours() > SYNC_HOUR || now.getMinutes() >= SYNC_MINUTE);

      if (!isSyncWindow || lastSyncDay === currentDay) return;

      try {
        const currentMeta = await fetchGlobalSyncStatus();
        if (currentMeta?.is_syncing) return;

        const sources = [
          { name: "UN Security Council", url: OFFICIAL_UN_XML_URL },
          { name: "Qatar NCTC", url: QATAR_NCTC_PORTAL_URL }
        ];

        for (const src of sources) {
          const syncStartTime = new Date().toISOString();
          await logAuditEvent('REGISTRY_SCHEDULED_SYNC_START', `Executing 08:00 AM authoritative state sync for ${src.name}...`, 'System Engine');
          await setGlobalSyncLock(true, 'In Progress...', 0, src.name);

          const entries = await fetchAndNormalize(src.url, src.name, syncStartTime);
          if (entries.length > 0) {
            await upsertCloudSanctions(entries, async (progress) => {
              if (progress % 10 === 0) {
                 await setGlobalSyncLock(true, 'In Progress...', progress, src.name);
              }
            });

            await deleteStaleSanctions(src.name, syncStartTime);

            await logIngestionEvent({ 
              timestamp: new Date().toISOString(), 
              source: src.name, 
              method: 'Automated', 
              status: 'Success', 
              recordsProcessed: entries.length, 
              triggeredBy: 'System Engine (Scheduled)'
            });
            await logAuditEvent('REGISTRY_SCHEDULED_SYNC_SUCCESS', `Daily Sync Complete: ${entries.length} identities from ${src.name} synchronized.`, 'System Engine');
          } else {
             await logAuditEvent('REGISTRY_SYNC_SKIPPED', `Source ${src.name} returned 0 records during scheduled sync.`, 'System Engine');
          }
        }

        // Mark today as synced
        localStorage.setItem('unsg_last_auto_sync_day', currentDay);
        const syncTime = new Date().toLocaleString();
        await setGlobalSyncLock(false, syncTime, 100, '');
        loadLogs();
      } catch (err: any) {
        await setGlobalSyncLock(false, "Failed: " + new Date().toLocaleString(), 0, '');
        await logAuditEvent('REGISTRY_SYNC_FAULT', `Scheduled sync aborted: ${err.message}`, 'System Engine');
        loadLogs();
      }
    };

    // Check every 60 seconds for the sync window
    const intervalId = setInterval(runAutomatedSync, 60000);
    runAutomatedSync();
    return () => clearInterval(intervalId);
  }, [settings.autoSync, connectionStatus, isGlobalSyncing, loadLogs]);

  const bootEnterpriseNode = useCallback(async () => {
    setConnectionStatus('CONNECTING');
    setSchemaDiscrepancies([]);
    try {
      initSupabase();
      const healthy = await checkConnection();
      if (healthy) {
        const audit = await validateRegistrySchemaV431();
        if (!audit.success) {
           setConnectionStatus('SAFE_MODE');
           setSchemaDiscrepancies(audit.discrepancies || ['Structural Audit Conflict']);
        } else {
           setConnectionStatus('CONNECTED');
        }

        await Promise.all([
          refreshClients(1),
          loadSanctionsCache(),
          loadLogs(),
          fetchGlobalSyncStatus().then(l => l && handleGlobalMetadataUpdate(l))
        ]);

        if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
        subscriptionRef.current = subscribeToClients(() => refreshClients(currentPageRef.current));

        if (syncChannelRef.current) syncChannelRef.current.unsubscribe();
        syncChannelRef.current = subscribeToGlobalSync(handleGlobalMetadataUpdate);
      } else {
        setConnectionStatus('SAFE_MODE');
      }
    } catch (e: any) { 
      setConnectionStatus('SAFE_MODE');
      refreshClients(1);
    }
    setTimeout(() => setIsBooting(false), 1500);
  }, [handleGlobalMetadataUpdate, loadSanctionsCache, refreshClients, loadLogs]);

  useEffect(() => { bootEnterpriseNode(); }, [bootEnterpriseNode]);

  const handleGlobalBatchScreening = async () => {
    if (screeningProgress.status === 'In Progress') return;
    await logAuditEvent('GLOBAL_BATCH_SCREENING_INITIATED', `Registry-wide screening protocol started.`, currentUser?.email || 'System');
    await loadLogs();

    const totalCount = await fetchClientsTotalCount();
    const allClients: Client[] = [];
    for (let i = 0; i < totalCount; i += 50) {
      const batch = await fetchCloudClients(i, i + 49);
      allClients.push(...batch);
    }

    setScreeningProgress({ totalRecords: totalCount, screenedRecords: 0, pendingRecords: totalCount, status: 'In Progress', currentBatch: 0 });

    for (let i = 0; i < allClients.length; i++) {
      const client = allClients[i];
      try {
        const screened = await screenEntityAgainstDb(client, currentUser?.email);
        await upsertCloudClient(screened);
      } catch (err) {}
      setScreeningProgress(prev => ({ ...prev, screenedRecords: i + 1, pendingRecords: totalCount - (i + 1) }));
    }

    const finalRiskSummary = await fetchGlobalRiskCounts();
    setRiskSummary(finalRiskSummary);
    setScreeningProgress(prev => ({ ...prev, status: 'Completed' }));
    await logAuditEvent('GLOBAL_BATCH_SCREENING_COMPLETED', `Processed screening for ${totalCount} records.`, currentUser?.email || 'System');
    await loadLogs();
    setTimeout(() => setScreeningProgress(prev => ({ ...prev, status: 'Not Started' })), 10000);
  };

  const handleAddClientWithAuthoritativeScreening = async (newClient: Client) => {
    setIsRefreshingClients(true);
    try {
      const screenedClient = await screenEntityAgainstDb(newClient, currentUser?.email);
      await upsertCloudClient(screenedClient);
      await logAuditEvent('ENTITY_PROVISIONED', `Entity "${newClient["Client Name"]}" provisioned.`, currentUser?.email || 'System');
      await loadLogs();
      await refreshClients(currentClientsPage); 
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
        await refreshClients(currentClientsPage);
      } else throw e;
    } finally { setIsRefreshingClients(false); }
  };

  const handleDeleteClient = async (id: string) => {
    const client = clients.find(c => c.id === id);
    setIsRefreshingClients(true);
    try {
      await deleteCloudClient(id);
      await logAuditEvent('ENTITY_REVOKED', `Entity "${client?.["Client Name"] || id}" removed.`, currentUser?.email || 'System');
      await loadLogs();
      await refreshClients(currentClientsPage);
    } catch (e: any) { 
      if (e.message?.includes('fetch')) {
        setConnectionStatus('SAFE_MODE');
        await refreshClients(currentClientsPage);
      } else alert(`Deletion Error: ${e.message}.`); 
    } finally { setIsRefreshingClients(false); }
  };

  const handleUpdateClient = async (updatedClient: Client) => {
    try {
      const original = clients.find(c => c.id === updatedClient.id);
      await upsertCloudClient(updatedClient);
      if (original?.kyc_status !== updatedClient.kyc_status) {
        await logAuditEvent('KYC_STATUS_OVERRIDE', `Status for "${updatedClient["Client Name"]}" changed to ${updatedClient.kyc_status}.`, currentUser?.email || 'System');
      } else {
        await logAuditEvent('ENTITY_MODIFIED', `Data updated for "${updatedClient["Client Name"]}".`, currentUser?.email || 'System');
      }
      await loadLogs();
      setClients(prev => prev.map(c => c.id === updatedClient.id ? { ...updatedClient } : c));
      if (original?.riskLevel !== updatedClient.riskLevel) {
        const nextRisks = await fetchGlobalRiskCounts();
        setRiskSummary(nextRisks);
      }
    } catch (e: any) { 
      if (e.message?.includes('fetch')) setConnectionStatus('SAFE_MODE'); else throw e;
    }
  };

  const handlePasswordUpdate = async (newPassword: string) => {
    if (!currentUser) return;
    try {
      const dbPayload: any = { ...currentUser };
      dbPayload.password_hash_mock = newPassword;
      dbPayload.must_change_password = false;
      delete dbPayload.password; delete dbPayload.confirmPassword;
      await upsertCloudUser(dbPayload);
      await logAuditEvent('PASSWORD_ROTATION', `Security policy enforced.`, currentUser.email);
      await loadLogs();
      const updatedUser = { ...currentUser, must_change_password: false, password_hash_mock: newPassword };
      setCurrentUser(updatedUser);
      localStorage.setItem('unsg_session', JSON.stringify(updatedUser));
      alert("Password updated successfully.");
    } catch (e: any) { alert("Failed to update password: " + e.message); }
  };

  const effectiveEnvironment = (currentUser?.id === 'SYS-ROOT') ? settings.environment : SystemEnvironment.PRODUCTION;

  if (!currentUser) {
    return <Login onLogin={(u) => { 
      setCurrentUser(u); 
      localStorage.setItem('unsg_session', JSON.stringify(u)); 
      logAuditEvent('SESSION_INITIALIZED', `User authenticated.`, u.email).then(() => loadLogs());
    }} isCloudConnected={connectionStatus === 'CONNECTED' || connectionStatus === 'SAFE_MODE'} />;
  }

  if (currentUser.must_change_password) {
    return <PasswordUpdate user={currentUser} onUpdate={handlePasswordUpdate} />;
  }

  return (
    <Router>
      <Layout isCloudConnected={connectionStatus === 'CONNECTED'} isConnecting={connectionStatus === 'CONNECTING'} isSafeMode={connectionStatus === 'SAFE_MODE'} schemaFaults={schemaDiscrepancies} onLogout={() => { logAuditEvent('SESSION_TERMINATED', `User logged out.`, currentUser.email).then(() => loadLogs()); setCurrentUser(null); localStorage.removeItem('unsg_session'); }} currentUser={currentUser} onRetryConnection={() => bootEnterpriseNode()} environment={effectiveEnvironment}>
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} totalClientsCount={clientsCount} sanctionsCount={sanctionsCount} registryStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} riskSummary={riskSummary} />} />
          <Route path="/clients" element={<ClientManager clients={clients} totalCount={clientsCount} currentPage={currentClientsPage} onPageChange={refreshClients} isRefreshing={isRefreshingClients} onAddClient={handleAddClientWithAuthoritativeScreening} onDeleteClient={handleDeleteClient} onRefresh={() => refreshClients(currentClientsPage)} onReScreen={handleGlobalBatchScreening} onUpdateClient={handleUpdateClient} screeningProgress={screeningProgress} currentUserRole={currentUser.role} currentUserId={currentUser.id} />} />
          <Route path="/sanctions" element={<SanctionsRegistry onSyncComplete={() => loadSanctionsCache()} isCloudConnected={connectionStatus === 'CONNECTED' || connectionStatus === 'SAFE_MODE'} initialStats={registryStats} isGlobalSyncing={isGlobalSyncing} environment={effectiveEnvironment} currentUser={currentUser} />} />
          <Route path="/admin" element={currentUser.is_system_admin === true ? <AdminPanel settings={settings} logs={systemLogs} onUpdateSettings={(s) => { logAuditEvent('SYSTEM_SETTINGS_MODIFIED', `Environment set to ${s.environment}.`, currentUser.email).then(() => loadLogs()); setSettings(s); localStorage.setItem('unsg_settings', JSON.stringify(s)); }} currentUser={currentUser} onLogsRefresh={loadLogs} /> : <Navigate to="/" replace />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import { createClient } from '@supabase/supabase-js';
import { Client, RiskLevel, UserProfile, SanctionEntry, EntityType, IngestionLog, SystemLog, KYCStatus, SystemEnvironment } from '../types';

const MASTER_REGISTRY_URL = 'https://wbjiokaryxrjicavcvwx.supabase.co';
const MASTER_REGISTRY_KEY = 'sb_publishable_Folrp4epgSCgQArvm2GAfQ_Nbo-xJ-m';

const RETRIEVAL_NOISE = [
  'CO', 'LTD', 'CORP', 'INC', 'INTERNATIONAL', 'LIMITED', 'GROUP', 'COMPANY', 'LLC', 
  'PVT', 'FZE', 'PLC', 'SERVICES', 'TRADING', 'HOLDINGS', 'TRUST', 'SDN', 'BHD', 'BERHAD', 'PRIVATE'
];

let supabaseClient: any = null;

const extractError = (err: any): string => {
  if (!err) return "Unknown Error";
  if (typeof err === 'string') return err;
  return err.message || err.details || JSON.stringify(err);
};

export const initSupabase = () => {
  if (supabaseClient) return true;
  try {
    supabaseClient = createClient(MASTER_REGISTRY_URL, MASTER_REGISTRY_KEY, {
      auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false }
    });
    return true;
  } catch (e) {
    console.error("[Registry] Handshake Fatal:", e);
    return false;
  }
};

const mapRowToEntry = (row: any): SanctionEntry => ({
  dataId: String(row.data_id ?? row.dataId ?? row.id ?? ''),
  firstName: row.first_name ?? row.firstName ?? '',
  secondName: row.second_name ?? row.secondName ?? '',
  thirdName: row.third_name ?? row.thirdName ?? '',
  lastName: row.last_name ?? row.lastName ?? '',
  source: row.source ?? 'Master Registry',
  referenceNumber: row.reference_number ?? row.referenceNumber ?? '',
  listedOn: row.listed_on ?? row.listedOn ?? '',
  comments: row.comments ?? '',
  nationality: row.nationality ?? '',
  dateOfBirth: row.date_of_birth ?? row.dateOfBirth ?? '',
  aliases: Array.isArray(row.aliases) ? row.aliases : [],
  type: row.type ?? EntityType.CORPORATE,
  fetchDate: row.fetch_date ?? row.fetchDate ?? '',
  unListType: row.un_list_type ?? row.unListType ?? ''
});

export const searchSanctionsAuthoritative = async (
  name: string, 
  from: number = 0, 
  to: number = 14
): Promise<{ data: SanctionEntry[], count: number }> => {
  if (!supabaseClient) initSupabase();
  if (!supabaseClient) return { data: [], count: 0 };

  const cleanName = name.trim().replace(/[(),'"]/g, '').toUpperCase();

  if (!cleanName) {
    const { data, count } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .range(from, to)
      .order('first_name', { ascending: true });
    return { data: (data || []).map(mapRowToEntry), count: count || 0 };
  }

  try {
    const tokens = cleanName.split(/\s+/)
      .filter(t => t.length >= 2 && !RETRIEVAL_NOISE.includes(t))
      .slice(0, 3); 

    const cols = ['first_name', 'last_name', 'comments', 'data_id', 'reference_number'];
    const filterParts: string[] = [];

    if (tokens.length === 0) {
      const term = `%${cleanName}%`;
      cols.forEach(col => filterParts.push(`${col}.ilike.${term}`));
    } else {
      tokens.forEach(t => {
        const term = `%${t}%`;
        cols.forEach(col => filterParts.push(`${col}.ilike.${term}`));
      });
    }

    const { data, count, error } = await supabaseClient
      .from('sanctions')
      .select('*', { count: 'exact' })
      .or(filterParts.join(','))
      .range(from, to)
      .order('first_name', { ascending: true });

    if (error) throw new Error(`REGISTRY_QUERY_FAULT: ${extractError(error)}`);

    return { 
      data: (data || []).map(mapRowToEntry), 
      count: count || 0 
    };
  } catch (e: any) {
    console.error("[Search] Authoritative Execution Fault:", e.message);
    return { data: [], count: 0 };
  }
};

export const fetchCloudClients = async (from: number, to: number): Promise<Client[]> => {
  if (!supabaseClient) initSupabase();
  const { data, error } = await supabaseClient.from('clients').select('*').order('created_at', { ascending: false }).range(from, to);
  if (error) throw error;
  return (data || []).map((row: any) => ({ ...row, id: row.id } as Client));
};

export const fetchClientsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) initSupabase();
  const { count, error } = await supabaseClient.from('clients').select('*', { count: 'exact', head: true });
  return error ? 0 : count || 0;
};

export const fetchGlobalRiskCounts = async (): Promise<Record<RiskLevel, number>> => {
  if (!supabaseClient) initSupabase();
  const summary: Record<RiskLevel, number> = {
    [RiskLevel.HIGH]: 0,
    [RiskLevel.MEDIUM]: 0,
    [RiskLevel.LOW]: 0,
    [RiskLevel.NONE]: 0
  };

  try {
    const riskLevels = [RiskLevel.HIGH, RiskLevel.MEDIUM, RiskLevel.LOW, RiskLevel.NONE];
    const results = await Promise.all(
      riskLevels.map(rl => 
        supabaseClient.from('clients').select('*', { count: 'exact', head: true }).eq('riskLevel', rl)
      )
    );

    riskLevels.forEach((rl, index) => {
      summary[rl] = results[index].count || 0;
    });

    return summary;
  } catch (e) {
    console.error("[Stats] Failed to aggregate risk metrics:", e);
    return summary;
  }
};

export const upsertCloudClient = async (client: Client) => {
  if (!supabaseClient) initSupabase();
  const { error } = await supabaseClient.from('clients').upsert([client], { onConflict: 'id' });
  if (error) throw new Error(extractError(error));
};

export const deleteCloudClient = async (id: string) => {
  if (!supabaseClient) initSupabase();
  const { error } = await supabaseClient.from('clients').delete().eq('id', id);
  if (error) throw error;
};

export const subscribeToClients = (callback: () => void) => {
  if (!supabaseClient) initSupabase();
  return supabaseClient.channel('clients-all').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, callback).subscribe();
};

export const unsubscribeFromClients = (subscription: any) => subscription?.unsubscribe();

export const fetchSanctionsTotalCount = async (): Promise<number> => {
  if (!supabaseClient) initSupabase();
  const { count, error } = await supabaseClient.from('sanctions').select('*', { count: 'exact', head: true });
  return error ? 0 : count || 0;
};

export const upsertCloudSanctions = async (sanctions: SanctionEntry[], onProgress?: (p: number) => void) => {
  if (!supabaseClient) initSupabase();
  const chunkSize = 150; 
  for (let i = 0; i < sanctions.length; i += chunkSize) {
    const chunk = sanctions.slice(i, i + chunkSize).map(s => ({
      data_id: s.dataId, 
      first_name: s.firstName, 
      second_name: s.secondName, 
      third_name: s.thirdName, 
      last_name: s.lastName, 
      source: s.source, 
      reference_number: s.referenceNumber, 
      listed_on: s.listedOn,
      comments: s.comments, 
      nationality: s.nationality, 
      date_of_birth: s.dateOfBirth, 
      aliases: s.aliases,
      type: s.type, 
      fetch_date: s.fetch_date || s.fetchDate || new Date().toISOString(), 
      un_list_type: s.unListType
    }));
    const { error } = await supabaseClient.from('sanctions').upsert(chunk, { onConflict: 'data_id' });
    if (error) throw error;
    if (onProgress) onProgress(Math.round(((i + chunk.length) / sanctions.length) * 100));
  }
};

/**
 * Removes sanctions from a specific source that were NOT part of the latest update.
 * Ensures the database perfectly mirrors the source list (Deletes old/removed entities).
 */
export const deleteStaleSanctions = async (source: string, latestTimestamp: string) => {
  if (!supabaseClient) initSupabase();
  // We delete where the source matches and the fetch_date is strictly older than the latest batch timestamp
  const { error } = await supabaseClient
    .from('sanctions')
    .delete()
    .eq('source', source)
    .lt('fetch_date', latestTimestamp);

  if (error) console.error(`[Purge] Failed to remove stale identities from ${source}:`, error);
};

export const logIngestionEvent = async (log: any) => {
  if (!supabaseClient) initSupabase();
  await supabaseClient.from('ingestion_logs').insert([log]);
};

export const fetchIngestionLogs = async (): Promise<IngestionLog[]> => {
  if (!supabaseClient) initSupabase();
  const { data, error } = await supabaseClient.from('ingestion_logs').select('*').order('timestamp', { ascending: false }).limit(50);
  return error ? [] : data || [];
};

export const logAuditEvent = async (action: string, details: string, triggeredBy: string) => {
  const log: SystemLog = { 
    id: `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`, 
    timestamp: new Date().toISOString(), 
    source: action, 
    method: 'AUDIT', 
    status: 'Success', 
    details, 
    triggeredBy: triggeredBy 
  };

  try {
    const localLogs = JSON.parse(localStorage.getItem('unsg_audit_local') || '[]');
    localStorage.setItem('unsg_audit_local', JSON.stringify([log, ...localLogs].slice(0, 100)));
  } catch (e) {}

  if (!supabaseClient) initSupabase();
  if (supabaseClient) {
    const { error: primaryError } = await supabaseClient.from('system_logs').insert([{
      id: log.id,
      timestamp: log.timestamp,
      source: log.source,
      method: log.method,
      status: log.status,
      details: log.details,
      triggered_by: triggeredBy
    }]);

    if (primaryError && (primaryError.code === '42P01' || primaryError.message.includes('schema cache'))) {
      const { error: fallbackError } = await supabaseClient.from('ingestion_logs').insert([{
        id: log.id,
        timestamp: log.timestamp,
        source: log.source,
        method: 'AUDIT_REDUNDANT',
        status: log.status,
        details: log.details,
        triggeredBy: triggeredBy,
        recordsProcessed: 0,
        recordsAccepted: 0,
        recordsRejected: 0
      }]);
      return !fallbackError;
    }
    return !primaryError;
  }
  return true;
};

export const fetchSystemLogs = async (): Promise<SystemLog[]> => {
  let combined: SystemLog[] = [];
  try { combined = JSON.parse(localStorage.getItem('unsg_audit_local') || '[]'); } catch (e) {}

  if (!supabaseClient) initSupabase();
  if (supabaseClient) {
    try {
      const { data: primary, error: pErr } = await supabaseClient.from('system_logs').select('*').limit(50).order('timestamp', { ascending: false });
      if (!pErr && primary) {
        primary.forEach((row: any) => combined.push({
          id: row.id, timestamp: row.timestamp, source: row.source, method: row.method || 'AUDIT',
          status: row.status || 'Success', details: row.details, triggeredBy: row.triggered_by || row.triggeredBy
        }));
      }
      const { data: fallback, error: fErr } = await supabaseClient.from('ingestion_logs').select('*').eq('method', 'AUDIT_REDUNDANT').limit(50).order('timestamp', { ascending: false });
      if (!fErr && fallback) {
        fallback.forEach((row: any) => combined.push({
          id: row.id, timestamp: row.timestamp, source: row.source, method: 'AUDIT (Redundant)',
          status: row.status || 'Success', details: row.details, triggeredBy: row.triggeredBy
        }));
      }
    } catch (e) {}
  }
  const seen = new Set();
  return combined
    .filter(l => {
      const isNew = !seen.has(l.id);
      seen.add(l.id);
      return isNew;
    })
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
};

export const checkConnection = async () => {
  if (!supabaseClient) initSupabase();
  const { error } = await supabaseClient.from('clients').select('id').limit(1);
  return !error;
};

export const validateRegistrySchemaV431 = async () => {
  if (!supabaseClient) initSupabase();
  const discrepancies: string[] = [];
  const { error: logsErr } = await supabaseClient.from('system_logs').select('id').limit(1);
  if (logsErr && (logsErr.code === '42P01' || logsErr.message.includes('schema cache'))) {
    const { error: fallbackErr } = await supabaseClient.from('ingestion_logs').select('id').limit(1);
    if (!fallbackErr) return { success: true, discrepancies: ["Governance Warning: Using 'ingestion_logs' for audit redundancy."] };
    discrepancies.push("Registry Critical: Audit tables missing from cloud schema.");
  }
  return { success: discrepancies.length === 0, discrepancies };
};

